VALUES ('doc-09-mitre-attack-p0-437', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["BRONZE BUTLER", "REDBALDKNIGHT", "Tick"], "created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRONZE BUTLER](https://attack.mitre.org/groups/G0060) is a cyber espionage group with likely Chinese origins that has been active since at least 2008. The group primarily targets Japanese organizations, particularly those in government, biotechnology, electronics manufacturing, and industrial chemistry.(Citation: Trend Micro Daserf Nov 2017)(Citation: Secureworks BRONZE BUTLER Oct 2017)(Citation: Trend Micro Tick November 2019)", "external_references": [{"external_id": "G0060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0060"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)(Citation: Trend Micro Tick November 2019)", "source_name": "BRONZE BUTLER"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)(Citation: Trend Micro Tick November 2019)", "source_name": "REDBALDKNIGHT"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)(Citation: Symantec Tick Apr 2016)(Citation: Trend Micro Tick November 2019)", "source_name": "Tick"}, {"description": "Chen, J. and Hsieh, M. (2017, November 7). REDBALDKNIGHT/BRONZE BUTLER’s Daserf Backdoor Now Using Steganography. Retrieved December 27, 2017.", "source_name": "Trend Micro Daserf Nov 2017", "url": "http://blog.trendmicro.com/trendlabs-security-intelligence/redbaldknight-bronze-butler-daserf-backdoor-now-using-steganography/"}, {"description": "Counter Threat Unit Research Team. (2017, October 12). BRONZE BUTLER Targets Japanese Enterprises. Retrieved January 4, 2018.", "source_name": "Secureworks BRONZE BUTLER Oct 2017", "url": "https://www.secureworks.com/research/bronze-butler-targets-japanese-businesses"}, {"description": "Chen, J. et al. (2019, November). Operation ENDTRADE: TICK’s Multi-Stage Backdoors for Attacking Industries and Stealing Classified Data. Retrieved June 9, 2020.", "source_name": "Trend Micro Tick November 2019", "url": "https://documents.trendmicro.com/assets/pdf/Operation-ENDTRADE-TICK-s-Multi-Stage-Backdoors-for-Attacking-Industries-and-Stealing-Classified-Data.pdf"}, {"description": "DiMaggio, J. (2016, April 28). Tick cyberespionage group zeros in on Japan. Retrieved July 16, 2018.", "source_name": "Symantec Tick Apr 2016", "url": "https://www.symantec.com/connect/blogs/tick-cyberespionage-group-zeros-japan"}], "id": "intrusion-set--93f52415-0fe4-4d3d-896c-fc9b8e88ab90", "modified": "2026-07-31T18:48:09.344Z", "name": "BRONZE BUTLER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Trend Micro Incorporated"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-437', 0, 252, '09-mitre-attack', 'retrieved', '8DC15EEB327B41073468D08FA28B32DE28574F4F8288FBDFE9359CDE5CF84219', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
