VALUES ('doc-09-mitre-attack-p0-442', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["BackdoorDiplomacy"], "created": "2021-09-21T14:52:49.596Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BackdoorDiplomacy](https://attack.mitre.org/groups/G0135) is a cyber espionage threat group that has been active since at least 2017. [BackdoorDiplomacy](https://attack.mitre.org/groups/G0135) has targeted Ministries of Foreign Affairs and telecommunication companies in Africa, Europe, the Middle East, and Asia.(Citation: ESET BackdoorDiplomacy Jun 2021)", "external_references": [{"external_id": "G0135", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0135"}, {"description": "Adam Burgher. (2021, June 10). BackdoorDiplomacy: Upgrading from Quarian to Turian. Retrieved September 1, 2021", "source_name": "ESET BackdoorDiplomacy Jun 2021", "url": "https://www.welivesecurity.com/2021/06/10/backdoordiplomacy-upgrading-quarian-turian/"}], "id": "intrusion-set--9735c036-8ebe-47e9-9c77-b0ae656dab93", "modified": "2026-07-31T18:48:10.579Z", "name": "BackdoorDiplomacy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Zaw Min Htun, @Z3TAE"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-442', 0, 103, '09-mitre-attack', 'retrieved', 'F81BA250128F940D8754BCA73117C7077D595327DF7F737325E90DEAEFABF5B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
