VALUES ('doc-09-mitre-attack-p0-443', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Gelsemium"], "created": "2021-11-30T16:25:49.366Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gelsemium](https://attack.mitre.org/groups/G0141) is a cyberespionage group that has been active since at least 2014, targeting governmental institutions, electronics manufacturers, universities, and religious organizations in East Asia and the Middle East.(Citation: ESET Gelsemium June 2021)", "external_references": [{"external_id": "G0141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0141"}, {"description": "Dupuy, T. and Faou, M. (2021, June). Gelsemium. Retrieved November 30, 2021.", "source_name": "ESET Gelsemium June 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/06/eset_gelsemium.pdf"}], "id": "intrusion-set--99910207-1741-4da1-9b5d-537410186b51", "modified": "2026-07-31T18:48:41.293Z", "name": "Gelsemium", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-443', 0, 91, '09-mitre-attack', 'retrieved', '5198F641F5D596B99D414162C0F0BB1AE93DB4E51F7F443ACAAD0A3668737B38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
