VALUES ('doc-09-mitre-attack-p0-446', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Axiom", "Group 72"], "created": "2017-05-31T21:31:45.629Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Axiom](https://attack.mitre.org/groups/G0001) is a suspected Chinese cyber espionage group that has targeted the aerospace, defense, government, manufacturing, and media sectors since at least 2008. Some reporting suggests a degree of overlap between [Axiom](https://attack.mitre.org/groups/G0001) and [Winnti Group](https://attack.mitre.org/groups/G0044) but the two groups appear to be distinct based on differences in reporting on TTPs and targeting.(Citation: Kaspersky Winnti April 2013)(Citation: Kaspersky Winnti June 2015)(Citation: Novetta Winnti April 2015)", "external_references": [{"external_id": "G0001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0001"}, {"description": "(Citation: Cisco Group 72)", "source_name": "Group 72"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Axiom"}, {"description": "Esler, J., Lee, M., and Williams, C. (2014, October 14). Threat Spotlight: Group 72. Retrieved January 14, 2016.", "source_name": "Cisco Group 72", "url": "http://blogs.cisco.com/security/talos/threat-spotlight-group-72"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2013, April 11). Winnti. More than just a game. Retrieved February 8, 2017.", "source_name": "Kaspersky Winnti April 2013", "url": "https://securelist.com/winnti-more-than-just-a-game/37029/"}, {"description": "Novetta Threat Research Group. (2015, April 7). Winnti Analysis. Retrieved February 8, 2017.", "source_name": "Novetta Winnti April 2015", "url": "https://web.archive.org/web/20150412223949/http://www.novetta.com/wp-content/uploads/2015/04/novetta_winntianalysis.pdf"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}, {"description": "Tarakanov, D. (2015, June 22). Games are over: Winnti is now targeting pharmaceutical companies. Retrieved January 14, 2016.", "source_name": "Kaspersky Winnti June 2015", "url": "https://securelist.com/games-are-over/70991/"}], "id": "intrusion-set--a0cb9370-e39b-44d5-9f50-ef78e412b973", "modified": "2026-07-31T18:48:11.488Z", "name": "Axiom", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-446', 0, 235, '09-mitre-attack', 'retrieved', '11742EA19DA3AF54606F5D3491A770A5DB4E100BC2982C3D9C53730998CB7E7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
