VALUES ('doc-09-mitre-attack-p0-450', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["LazyScripter"], "created": "2021-11-24T19:26:27.305Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LazyScripter](https://attack.mitre.org/groups/G0140) is threat group that has mainly targeted the airlines industry since at least 2018, primarily using open-source toolsets.(Citation: MalwareBytes LazyScripter Feb 2021)", "external_references": [{"external_id": "G0140", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0140"}, {"description": "(Citation: MalwareBytes LazyScripter Feb 2021)", "source_name": "LazyScripter"}, {"description": "Jazi, H. (2021, February). LazyScripter: From Empire to double RAT. Retrieved November 17, 2024.", "source_name": "MalwareBytes LazyScripter Feb 2021", "url": "https://web.archive.org/web/20211003035156/https://www.malwarebytes.com/resources/files/2021/02/lazyscripter.pdf"}], "id": "intrusion-set--abc5a1d4-f0dc-49d1-88a1-4a80e478bb03", "modified": "2026-07-31T18:48:12.417Z", "name": "LazyScripter", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-450', 0, 106, '09-mitre-attack', 'retrieved', '0F32DAC65865CE1161E38FE93BA8ECB6FCB8D241A6D4309302429342C7651B89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
