VALUES ('doc-09-mitre-attack-p0-451', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Dust Storm"], "created": "2017-05-31T21:32:03.306Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dust Storm](https://attack.mitre.org/groups/G0031) is a threat group that has targeted multiple industries in Japan, South Korea, the United States, Europe, and several Southeast Asian countries. (Citation: Cylance Dust Storm)", "external_references": [{"external_id": "G0031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0031"}, {"description": "(Citation: Cylance Dust Storm)", "source_name": "Dust Storm"}, {"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "intrusion-set--ae41895a-243f-4a65-b99b-d85022326c31", "modified": "2026-07-31T18:48:41.294Z", "name": "Dust Storm", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-451', 0, 95, '09-mitre-attack', 'retrieved', 'EED43030E8C5A9FDCA9F48BB2214E55121E92ADC3FCA953611502BA66FB47E00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
