VALUES ('doc-09-mitre-attack-p0-452', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Windshift", "Bahamut"], "created": "2020-06-25T17:16:39.168Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Windshift](https://attack.mitre.org/groups/G0112) is a threat group that has been active since at least 2017, targeting specific individuals for surveillance in government departments and critical infrastructure across the Middle East.(Citation: SANS Windshift August 2018)(Citation: objective-see windtail1 dec 2018)(Citation: objective-see windtail2 jan 2019)", "external_references": [{"external_id": "G0112", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0112"}, {"description": "(Citation: SANS Windshift August 2018)", "source_name": "Bahamut"}, {"description": "Karim, T. (2018, August). TRAILS OF WINDSHIFT. Retrieved November 17, 2024.", "source_name": "SANS Windshift August 2018", "url": "https://www.scribd.com/document/661837258/WINDSHIFT-summit-archive-1554718868"}, {"description": "Wardle, Patrick. (2018, December 20). Middle East Cyber-Espionage analyzing WindShift''s implant: OSX.WindTail (part 1). Retrieved October 3, 2019.", "source_name": "objective-see windtail1 dec 2018", "url": "https://objective-see.com/blog/blog_0x3B.html"}, {"description": "Wardle, Patrick. (2019, January 15). Middle East Cyber-Espionage analyzing WindShift''s implant: OSX.WindTail (part 2). Retrieved October 3, 2019.", "source_name": "objective-see windtail2 jan 2019", "url": "https://objective-see.com/blog/blog_0x3D.html"}], "id": "intrusion-set--afec6dc3-a18e-4b62-b1a4-5510e1a498d1", "modified": "2026-07-31T20:48:43.267Z", "name": "Windshift", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-452', 0, 159, '09-mitre-attack', 'retrieved', '7DB0A6F49BABE893DF21FE0D0512E729759EFA420732A0C514352ADAE2344CB2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
