VALUES ('doc-09-mitre-attack-p0-453', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Volatile Cedar", "Lebanese Cedar"], "created": "2021-02-08T20:30:30.578Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volatile Cedar](https://attack.mitre.org/groups/G0123) is a Lebanese threat group that has targeted individuals, companies, and institutions worldwide. [Volatile Cedar](https://attack.mitre.org/groups/G0123) has been operating since 2012 and is motivated by political and ideological interests.(Citation: CheckPoint Volatile Cedar March 2015)(Citation: ClearSky Lebanese Cedar Jan 2021)", "external_references": [{"external_id": "G0123", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0123"}, {"description": "(Citation: CheckPoint Volatile Cedar March 2015)", "source_name": "Volatile Cedar"}, {"description": "(Citation: ClearSky Lebanese Cedar Jan 2021)", "source_name": "Lebanese Cedar"}, {"description": "ClearSky Cyber Security. (2021, January). “Lebanese Cedar” APT Global Lebanese Espionage Campaign Leveraging Web Servers. Retrieved February 10, 2021.", "source_name": "ClearSky Lebanese Cedar Jan 2021", "url": "https://www.clearskysec.com/wp-content/uploads/2021/01/Lebanese-Cedar-APT.pdf"}, {"description": "Threat Intelligence and Research. (2015, March 30). VOLATILE CEDAR. Retrieved February 8, 2021.", "source_name": "CheckPoint Volatile Cedar March 2015", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/03/20082004/volatile-cedar-technical-report.pdf"}], "id": "intrusion-set--b2e34388-6938-4c59-a702-80dc219e15e3", "modified": "2026-07-31T18:48:12.835Z", "name": "Volatile Cedar", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-453', 0, 152, '09-mitre-attack', 'retrieved', '3E93A5F2263F3ECCE896491D6ED07EF02B6C6E6315BA8E62EE80448BC1C207A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
