VALUES ('doc-09-mitre-attack-p0-454', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["ToddyCat"], "created": "2024-01-03T21:34:10.988Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ToddyCat](https://attack.mitre.org/groups/G1022) is a sophisticated threat group that has been active since at least 2020 using custom loaders and malware in multi-stage infection chains against government and military targets across Europe and Asia.(Citation: Kaspersky ToddyCat June 2022)(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"external_id": "G1022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1022"}, {"description": "Dedola, G. (2022, June 21). APT ToddyCat. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat June 2022", "url": "https://securelist.com/toddycat/106799/"}, {"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "intrusion-set--b516b235-fc7d-4635-aca5-3d33312339c3", "modified": "2026-07-31T18:48:13.519Z", "name": "ToddyCat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-454', 0, 126, '09-mitre-attack', 'retrieved', '8E9867C14DCDF2533E6C03921863D5E6FC5ED945C9B431B500FD38D5D1094D18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
