VALUES ('doc-09-mitre-attack-p0-455', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Whitefly"], "created": "2020-05-26T16:55:09.674Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Whitefly](https://attack.mitre.org/groups/G0107) is a cyber espionage group that has been operating since at least 2017. The group has targeted organizations based mostly in Singapore across a wide variety of sectors, and is primarily interested in stealing large amounts of sensitive information. The group has been linked to an attack against Singapore’s largest public health organization, SingHealth.(Citation: Symantec Whitefly March 2019)", "external_references": [{"external_id": "G0107", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0107"}, {"description": "Symantec. (2019, March 6). Whitefly: Espionage Group has Singapore in Its Sights. Retrieved May 26, 2020.", "source_name": "Symantec Whitefly March 2019", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/whitefly-espionage-singapore"}], "id": "intrusion-set--b74f909f-8e52-4b69-b770-162bf59a1b4e", "modified": "2026-07-31T18:48:13.766Z", "name": "Whitefly", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-455', 0, 121, '09-mitre-attack', 'retrieved', '3CF423DAC1C216922EF31C29C3A3282B0FDB0EC49A1E197C33619D34EA0A6A5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
