VALUES ('doc-09-mitre-attack-p0-457', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Agrius", "Pink Sandstorm", "AMERICIUM", "Agonizing Serpens", "BlackShadow"], "created": "2024-05-21T19:13:23.526Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) is an Iranian threat actor active since 2020 notable for a series of ransomware and wiper operations in the Middle East, with an emphasis on Israeli targets.(Citation: SentinelOne Agrius 2021)(Citation: CheckPoint Agrius 2023) Public reporting has linked [Agrius](https://attack.mitre.org/groups/G1030) to Iran''s Ministry of Intelligence and Security (MOIS).(Citation: Microsoft Iran Cyber 2023)", "external_references": [{"external_id": "G1030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1030"}, {"description": "(Citation: CheckPoint Agrius 2023)", "source_name": "BlackShadow"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "Pink Sandstorm"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "AMERICIUM"}, {"description": "(Citation: Unit42 Agrius 2023)", "source_name": "Agonizing Serpens"}, {"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}, {"description": "Marc Salinas Fernandez & Jiri Vinopal. (2023, May 23). AGRIUS DEPLOYS MONEYBIRD IN TARGETED ATTACKS AGAINST ISRAELI ORGANIZATIONS. Retrieved May 21, 2024.", "source_name": "CheckPoint Agrius 2023", "url": "https://research.checkpoint.com/2023/agrius-deploys-moneybird-in-targeted-attacks-against-israeli-organizations/"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}, {"description": "Microsoft Threat Intelligence. (2023, May 2). Iran turning to cyber-enabled influence operations for greater effect. Retrieved May 21, 2024.", "source_name": "Microsoft Iran Cyber 2023", "url": "https://www.microsoft.com/en-us/security/business/security-insider/wp-content/uploads/2023/05/Iran-turning-to-cyber-enabled-influence-operations-for-greater-effect-05022023.pdf"}, {"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "modified": "2026-07-31T18:48:13.867Z", "name": "Agrius", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Asritha Narina"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-457', 0, 275, '09-mitre-attack', 'retrieved', '494EC0098B931078F6B46DB28BEF41B2F5D3596220C65AD7DEF60BE7D0327A9C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
