VALUES ('doc-09-mitre-attack-p0-467', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT12", "IXESHE", "DynCalc", "Numbered Panda", "DNSCALC"], "created": "2017-05-31T21:31:47.537Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT12](https://attack.mitre.org/groups/G0005) is a threat group that has been attributed to China. The group has targeted a variety of victims including but not limited to media outlets, high-tech companies, and multiple governments.(Citation: Meyers Numbered Panda)", "external_references": [{"external_id": "G0005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0005"}, {"description": "(Citation: Meyers Numbered Panda) (Citation: Moran 2014)", "source_name": "APT12"}, {"description": "(Citation: Meyers Numbered Panda) (Citation: Moran 2014)", "source_name": "IXESHE"}, {"description": "(Citation: Meyers Numbered Panda) (Citation: Moran 2014)", "source_name": "DynCalc"}, {"description": "(Citation: Meyers Numbered Panda)", "source_name": "Numbered Panda"}, {"description": "(Citation: Moran 2014)", "source_name": "DNSCALC"}, {"description": "Meyers, A. (2013, March 29). Whois Numbered Panda. Retrieved January 14, 2016.", "source_name": "Meyers Numbered Panda", "url": "http://www.crowdstrike.com/blog/whois-numbered-panda/"}, {"description": "Moran, N., Oppenheim, M., Engle, S., & Wartell, R.. (2014, September 3). Darwin’s Favorite APT Group [Blog]. Retrieved November 12, 2014.", "source_name": "Moran 2014", "url": "https://www.fireeye.com/blog/threat-research/2014/09/darwins-favorite-apt-group-2.html"}], "id": "intrusion-set--c47f937f-1022-4f42-8525-e7a4779a14cb", "modified": "2026-07-31T18:48:17.463Z", "name": "APT12", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-467', 0, 167, '09-mitre-attack', 'retrieved', 'D7A54D9CC5BA9EE63198A86D9A04904F28445A7C6EB7B11B68F06AB81104A707', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
