INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-468', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT-C-36", "Blind Eagle", "TAG-144", "AguilaCiega", "APT-Q-98"], "created": "2020-05-05T18:53:08.166Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT-C-36](https://attack.mitre.org/groups/G0099) is a suspected South American threat group that has engaged in espionage and financially motivated operations since at least 2018. [APT-C-36](https://attack.mitre.org/groups/G0099) has targeted government institutions and entities in the financial, energy, and professional manufacturing sectors across Colombia and other Latin American countries.(Citation: QiAnXin APT-C-36 Feb2019)(Citation: Kaspersky BlindEagle AUG 2024)(Citation: Check Point Blind Eagle MAR 2025)(Citation: Recorded Future TAG-144 AUG 2025)", "external_references": [{"external_id": "G0099", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0099"}, {"description": "(Citation: QiAnXin APT-C-36 Feb2019)(Citation: Recorded Future TAG-144 AUG 2025)", "source_name": "Blind Eagle"}, {"description": "(Citation: Recorded Future TAG-144 AUG 2025)", "source_name": "TAG-144"}, {"description": "(Citation: Recorded Future TAG-144 AUG 2025)", "source_name": "AguilaCiega"}, {"description": "(Citation: Recorded Future TAG-144 AUG 2025)", "source_name": "APT-Q-98"}, {"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "Global Research & Analysis Team, Kaspersky. (2024, August 19). BlindEagle flying high in Latin America. Retrieved April 16, 2026.", "source_name": "Kaspersky BlindEagle AUG 2024", "url": "https://securelist.com/blindeagle-apt/113414/"}, {"description": "Insikt Group. (2025, August 26). TAG-144’s Persistent Grip on South American Organizations. Retrieved April 16, 2026.", "source_name": "Recorded Future TAG-144 AUG 2025", "url": "https://assets.recordedfuture.com/insikt-report-pdfs/2025/cta-2025-0826.pdf"}, {"description": "QiAnXin Threat Intelligence Center. (2019, February 18). APT-C-36: Continuous Attacks Targeting Colombian Government Institutions and Corporations. Retrieved May 5, 2020.", "source_name": "QiAnXin APT-C-36 Feb2019", "url": "https://web.archive.org/web/20190625182633if_/https://ti.360.net/blog/articles/apt-c-36-continuous-attacks-targeting-colombian-government-institutions-and-corporations-en/"}], "id": "intrusion-set--c4d50cdf-87ce-407d-86d8-862883485842", "modified": "2026-07-31T18:48:17.693Z", "name": "APT-C-36", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Jose Luis Sánchez Martinez"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-468', 0, 254, '09-mitre-attack', 'retrieved', '82EC7397016E42D8947994FFB477C5ACBE2EB7A868D165F25DECCB723A2D2B1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
