VALUES ('doc-09-mitre-attack-p0-474', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["INC Ransom", "GOLD IONIC"], "created": "2024-06-06T17:16:38.704Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[INC Ransom](https://attack.mitre.org/groups/G1032) is a ransomware and data extortion threat group associated with the deployment of [INC Ransomware](https://attack.mitre.org/software/S1139) that has been active since at least July 2023. [INC Ransom](https://attack.mitre.org/groups/G1032) has targeted organizations worldwide most commonly in the industrial, healthcare, and education sectors in the US and Europe.(Citation: Bleeping Computer INC Ransomware March 2024)(Citation: Cybereason INC Ransomware November 2023)(Citation: Secureworks GOLD IONIC April 2024)(Citation: SentinelOne INC Ransomware)", "external_references": [{"external_id": "G1032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1032"}, {"description": "(Citation: Secureworks GOLD IONIC April 2024)", "source_name": "GOLD IONIC"}, {"description": "Counter Threat Unit Research Team. (2024, April 15). GOLD IONIC DEPLOYS INC RANSOMWARE. Retrieved June 5, 2024.", "source_name": "Secureworks GOLD IONIC April 2024", "url": "https://www.secureworks.com/blog/gold-ionic-deploys-inc-ransomware"}, {"description": "Cybereason Security Research Team. (2023, November 20). Threat Alert: INC Ransomware. Retrieved June 5, 2024.", "source_name": "Cybereason INC Ransomware November 2023", "url": "https://www.cybereason.com/hubfs/dam/collateral/reports/threat-alert-inc-ransomware.pdf"}, {"description": "SentinelOne. (n.d.). What Is Inc. Ransomware?. Retrieved June 5, 2024.", "source_name": "SentinelOne INC Ransomware", "url": "https://www.sentinelone.com/anthology/inc-ransom/"}, {"description": "Toulas, B. (2024, March 27). INC Ransom threatens to leak 3TB of NHS Scotland stolen data. Retrieved June 5, 2024.", "source_name": "Bleeping Computer INC Ransomware March 2024", "url": "https://www.bleepingcomputer.com/news/security/inc-ransom-threatens-to-leak-3tb-of-nhs-scotland-stolen-data/"}], "id": "intrusion-set--cb41e991-65f4-4668-a65f-f4200545b5a1", "modified": "2026-07-31T20:48:47.333Z", "name": "INC Ransom", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Matt Anderson, @‌nosecurething, Huntress"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-474', 0, 219, '09-mitre-attack', 'retrieved', '51366DB6F710540261478EC9E701B091ED7835850ACA3CCFF5E6F219D428B1FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
