VALUES ('doc-09-mitre-attack-p0-477', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Silence", "Whisper Spider"], "created": "2019-05-24T17:57:36.491Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Silence](https://attack.mitre.org/groups/G0091) is a financially motivated threat actor targeting financial institutions in different countries. The group was first seen in June 2016. Their main targets reside in Russia, Ukraine, Belarus, Azerbaijan, Poland and Kazakhstan. They compromised various banking systems, including the Russian Central Bank''s Automated Workstation Client, ATMs, and card processing.(Citation: Cyber Forensicator Silence Jan 2019)(Citation: SecureList Silence Nov 2017) ", "external_references": [{"external_id": "G0091", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0091"}, {"description": "(Citation: Crowdstrike GTR2020 Mar 2020)", "source_name": "Whisper Spider"}, {"description": "(Citation: Cyber Forensicator Silence Jan 2019)(Citation: SecureList Silence Nov 2017) ", "source_name": "Silence"}, {"description": "Crowdstrike. (2020, March 2). 2020 Global Threat Report. Retrieved December 11, 2020.", "source_name": "Crowdstrike GTR2020 Mar 2020", "url": "https://go.crowdstrike.com/rs/281-OBQ-266/images/Report2020CrowdStrikeGlobalThreatReport.pdf"}, {"description": "GReAT. (2017, November 1). Silence – a new Trojan attacking financial organizations. Retrieved May 24, 2019.", "source_name": "SecureList Silence Nov 2017", "url": "https://securelist.com/the-silence/83009/"}, {"description": "Skulkin, O.. (2019, January 20). Silence: Dissecting Malicious CHM Files and Performing Forensic Analysis. Retrieved November 17, 2024.", "source_name": "Cyber Forensicator Silence Jan 2019", "url": "https://web.archive.org/web/20220119133748/https://cyberforensicator.com/2019/01/20/silence-dissecting-malicious-chm-files-and-performing-forensic-analysis/"}], "id": "intrusion-set--d13c8a7f-740b-4efa-a232-de7d6bb05321", "modified": "2026-07-31T18:48:20.506Z", "name": "Silence", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Oleg Skulkin, Group-IB"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-477', 0, 198, '09-mitre-attack', 'retrieved', '767878F8B64C1F5F84067B019F9C0180ABA387755240EC94A71B612808D5A051', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
