VALUES ('doc-09-mitre-attack-p0-478', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Sowbug"], "created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sowbug](https://attack.mitre.org/groups/G0054) is a threat group that has conducted targeted attacks against organizations in South America and Southeast Asia, particularly government entities, since at least 2015. (Citation: Symantec Sowbug Nov 2017)", "external_references": [{"external_id": "G0054", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0054"}, {"description": "(Citation: Symantec Sowbug Nov 2017)", "source_name": "Sowbug"}, {"description": "Symantec Security Response. (2017, November 7). Sowbug: Cyber espionage group targets South American and Southeast Asian governments. Retrieved November 16, 2017.", "source_name": "Symantec Sowbug Nov 2017", "url": "https://www.symantec.com/connect/blogs/sowbug-cyber-espionage-group-targets-south-american-and-southeast-asian-governments"}], "id": "intrusion-set--d1acfbb3-647b-4723-9154-800ec119006e", "modified": "2026-07-31T18:48:20.561Z", "name": "Sowbug", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Alan Neville, @abnev"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-478', 0, 109, '09-mitre-attack', 'retrieved', 'EB0C6FC7BB993A02EF1E3A40686A0CBA37403423911C843130E9D51ABAE7CB45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
