VALUES ('doc-09-mitre-attack-p0-479', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Threat Group-1314", "TG-1314"], "created": "2017-05-31T21:31:59.120Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-1314](https://attack.mitre.org/groups/G0028) is an unattributed threat group that has used compromised credentials to log into a victim''s remote access infrastructure. (Citation: Dell TG-1314)", "external_references": [{"external_id": "G0028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0028"}, {"description": "(Citation: Dell TG-1314)", "source_name": "Threat Group-1314"}, {"description": "(Citation: Dell TG-1314)", "source_name": "TG-1314"}, {"description": "Dell SecureWorks Counter Threat Unit Special Operations Team. (2015, May 28). Living off the Land. Retrieved January 26, 2016.", "source_name": "Dell TG-1314", "url": "https://web.archive.org/web/20150626073312/http://www.secureworks.com/resources/blog/living-off-the-land/"}], "id": "intrusion-set--d519164e-f5fa-4b8c-a1fb-cf0172ad0983", "modified": "2026-07-31T18:48:20.978Z", "name": "Threat Group-1314", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-479', 0, 102, '09-mitre-attack', 'retrieved', '2239A4FC84581F5432ECFFB3A06740950823AA6A61F88DEB60BC2C436FAAC627', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
