VALUES ('doc-09-mitre-attack-p0-481', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT16"], "created": "2017-05-31T21:31:56.270Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT16](https://attack.mitre.org/groups/G0023) is a China-based threat group that has launched spearphishing campaigns targeting Japanese and Taiwanese organizations. (Citation: FireEye EPS Awakens Part 2)", "external_references": [{"external_id": "G0023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0023"}, {"description": "(Citation: FireEye EPS Awakens Part 2)", "source_name": "APT16"}, {"description": "Winters, R. (2015, December 20). The EPS Awakens - Part 2. Retrieved January 22, 2016.", "source_name": "FireEye EPS Awakens Part 2", "url": "https://web.archive.org/web/20151226205946/https://www.fireeye.com/blog/threat-research/2015/12/the-eps-awakens-part-two.html"}], "id": "intrusion-set--d6e88e18-81e8-4709-82d8-973095da1e70", "modified": "2026-07-31T18:48:21.512Z", "name": "APT16", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-481', 0, 93, '09-mitre-attack', 'retrieved', '33CCB4D41EC1889D1DA4677CF3AD6A4C693801AFE1748FD151A2C695CEAC4058', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
