VALUES ('doc-09-mitre-attack-p0-482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["LAPSUS$", "DEV-0537", "Strawberry Tempest"], "created": "2022-06-09T19:14:31.327Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LAPSUS$](https://attack.mitre.org/groups/G1004) is cyber criminal threat group that has been active since at least mid-2021. [LAPSUS$](https://attack.mitre.org/groups/G1004) specializes in large-scale social engineering and extortion operations, including destructive attacks without the use of ransomware. The group has targeted organizations globally, including in the government, manufacturing, higher education, energy, healthcare, technology, telecommunications, and media sectors.(Citation: BBC LAPSUS Apr 2022)(Citation: MSTIC DEV-0537 Mar 2022)(Citation: UNIT 42 LAPSUS Mar 2022)", "external_references": [{"external_id": "G1004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1004"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "Strawberry Tempest"}, {"description": "(Citation: MSTIC DEV-0537 Mar 2022)", "source_name": "DEV-0537"}, {"description": "BBC. (2022, April 1). LAPSUS: Two UK Teenagers Charged with Hacking for Gang. Retrieved June 9, 2022.", "source_name": "BBC LAPSUS Apr 2022", "url": "https://www.bbc.com/news/technology-60953527"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}, {"description": "MSTIC, DART, M365 Defender. (2022, March 24). DEV-0537 Criminal Actor Targeting Organizations for Data Exfiltration and Destruction. Retrieved May 17, 2022.", "source_name": "MSTIC DEV-0537 Mar 2022", "url": "https://www.microsoft.com/security/blog/2022/03/22/dev-0537-criminal-actor-targeting-organizations-for-data-exfiltration-and-destruction/"}, {"description": "UNIT 42. (2022, March 24). Threat Brief: Lapsus$ Group. Retrieved May 17, 2022.", "source_name": "UNIT 42 LAPSUS Mar 2022", "url": "https://unit42.paloaltonetworks.com/lapsus-group/"}], "id": "intrusion-set--d8bc9788-4f7d-41a9-9e9d-ee1ea18a8cf7", "modified": "2026-07-31T20:48:49.009Z", "name": "LAPSUS$", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["David Hughes, BT Security", "Matt Brenton, Zurich Insurance Group", "Flávio Costa, @Segurança Descomplicada", "Caio Silva"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-482', 0, 241, '09-mitre-attack', 'retrieved', '2D70DCBF58CC5F8395BEAC2FA35A8E9A8B3BF1EC525B5BEA75DECAD3781E185F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
