VALUES ('doc-09-mitre-attack-p0-489', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Velvet Ant"], "created": "2025-03-14T19:21:17.470Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Velvet Ant](https://attack.mitre.org/groups/G1047) is a threat actor operating since at least 2021. [Velvet Ant](https://attack.mitre.org/groups/G1047) is associated with complex persistence mechanisms, the targeting of network devices and appliances during operations, and the use of zero day exploits.(Citation: Sygnia VelvetAnt 2024A)(Citation: Sygnia VelvetAnt 2024B)", "external_references": [{"external_id": "G1047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1047"}, {"description": "Sygnia Team. (2024, July 1). China-Nexus Threat Group ‘Velvet Ant’ Exploits Cisco Zero-Day (CVE-2024-20399) to Compromise Nexus Switch Devices – Advisory for Mitigation and Response. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024B", "url": "https://www.sygnia.co/threat-reports-and-advisories/china-nexus-threat-group-velvet-ant-exploits-cisco-0-day/"}, {"description": "Sygnia Team. (2024, June 3). China-Nexus Threat Group ‘Velvet Ant’ Abuses F5 Load Balancers for Persistence. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024A", "url": "https://www.sygnia.co/blog/china-nexus-threat-group-velvet-ant/"}], "id": "intrusion-set--e1fc262c-dad2-4b82-abda-5f08dd134971", "modified": "2026-07-31T18:48:23.128Z", "name": "Velvet Ant", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Oren Biderman, Sygnia", "Amnon Kushnir, Sygnia"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-489', 0, 151, '09-mitre-attack', 'retrieved', '220CB6657C96496694B322E916301A35FCE562BDD572088D21719C332F2A68D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
