VALUES ('doc-09-mitre-attack-p0-491', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["IndigoZebra"], "created": "2021-09-24T21:41:34.797Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IndigoZebra](https://attack.mitre.org/groups/G0136) is a suspected Chinese cyber espionage group that has been targeting Central Asian governments since at least 2014.(Citation: HackerNews IndigoZebra July 2021)(Citation: Checkpoint IndigoZebra July 2021)(Citation: Securelist APT Trends Q2 2017)", "external_references": [{"external_id": "G0136", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0136"}, {"description": "(Citation: HackerNews IndigoZebra July 2021)(Citation: Checkpoint IndigoZebra July 2021)(Citation: Securelist APT Trends Q2 2017)", "source_name": "IndigoZebra"}, {"description": "Lakshmanan, R.. (2021, July 1). IndigoZebra APT Hacking Campaign Targets the Afghan Government. Retrieved September 24, 2021.", "source_name": "HackerNews IndigoZebra July 2021", "url": "https://thehackernews.com/2021/07/indigozebra-apt-hacking-campaign.html"}, {"description": "CheckPoint Research. (2021, July 1). IndigoZebra APT continues to attack Central Asia with evolving tools. Retrieved September 24, 2021.", "source_name": "Checkpoint IndigoZebra July 2021", "url": "https://research.checkpoint.com/2021/indigozebra-apt-continues-to-attack-central-asia-with-evolving-tools/"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2017, August 8). APT Trends report Q2 2017. Retrieved February 15, 2018.", "source_name": "Securelist APT Trends Q2 2017", "url": "https://securelist.com/apt-trends-report-q2-2017/79332/"}], "id": "intrusion-set--e5603ea8-4c36-40e7-b7af-a077d24fedc1", "modified": "2026-07-31T18:48:23.936Z", "name": "IndigoZebra", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-491', 0, 182, '09-mitre-attack', 'retrieved', '3A5A625ACA2E130FC29BCE48BD29FCD888A5AA6712DBF99C6E96DC2A359C13BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
