VALUES ('doc-09-mitre-attack-p0-492', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Moonstone Sleet", "Storm-1789"], "created": "2024-08-26T17:39:06.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Moonstone Sleet](https://attack.mitre.org/groups/G1036) is a North Korean-linked threat actor executing both financially motivated attacks and espionage operations. The group previously overlapped significantly with another North Korean-linked entity, [Lazarus Group](https://attack.mitre.org/groups/G0032), but has differentiated its tradecraft since 2023. [Moonstone Sleet](https://attack.mitre.org/groups/G1036) is notable for creating fake companies and personas to interact with victim entities, as well as developing unique malware such as a variant delivered via a fully functioning game.(Citation: Microsoft Moonstone Sleet 2024)", "external_references": [{"external_id": "G1036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1036"}, {"description": "(Citation: Microsoft Moonstone Sleet 2024)", "source_name": "Storm-1789"}, {"description": "Microsoft Threat Intelligence. (2024, May 28). Moonstone Sleet emerges as new North Korean threat actor with new bag of tricks. Retrieved August 26, 2024.", "source_name": "Microsoft Moonstone Sleet 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/28/moonstone-sleet-emerges-as-new-north-korean-threat-actor-with-new-bag-of-tricks/"}], "id": "intrusion-set--e6db1e55-b199-4b6b-8633-989345ee45e0", "modified": "2026-07-31T18:48:24.240Z", "name": "Moonstone Sleet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Aung Kyaw Min Naing, @Nolan"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-492', 0, 157, '09-mitre-attack', 'retrieved', '2839D8D46E5F51C1C2A6E0C05504FB97C501EAB54CD52590CA3399409FF1E9A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
