VALUES ('doc-09-mitre-attack-p0-493', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Inception", "Inception Framework", "Cloud Atlas"], "created": "2020-05-08T17:01:04.058Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Inception](https://attack.mitre.org/groups/G0100) is a cyber espionage group active since at least 2014. The group has targeted multiple industries and governmental entities primarily in Russia, but has also been active in the United States and throughout Europe, Asia, Africa, and the Middle East.(Citation: Unit 42 Inception November 2018)(Citation: Symantec Inception Framework March 2018)(Citation: Kaspersky Cloud Atlas December 2014)", "external_references": [{"external_id": "G0100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0100"}, {"description": "(Citation: Kaspersky Cloud Atlas December 2014)", "source_name": "Cloud Atlas"}, {"description": "(Citation: Symantec Inception Framework March 2018)", "source_name": "Inception"}, {"description": "(Citation: Symantec Inception Framework March 2018)", "source_name": "Inception Framework"}, {"description": "GReAT. (2014, December 10). Cloud Atlas: RedOctober APT is back in style. Retrieved May 8, 2020.", "source_name": "Kaspersky Cloud Atlas December 2014", "url": "https://securelist.com/cloud-atlas-redoctober-apt-is-back-in-style/68083/"}, {"description": "Lancaster, T. (2018, November 5). Inception Attackers Target Europe with Year-old Office Vulnerability. Retrieved May 8, 2020.", "source_name": "Unit 42 Inception November 2018", "url": "https://unit42.paloaltonetworks.com/unit42-inception-attackers-target-europe-year-old-office-vulnerability/"}, {"description": "Symantec. (2018, March 14). Inception Framework: Alive and Well, and Hiding Behind Proxies. Retrieved May 8, 2020.", "source_name": "Symantec Inception Framework March 2018", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/inception-framework-hiding-behind-proxies"}], "id": "intrusion-set--ead23196-d7b6-4ce6-a124-4ab4b67d81bd", "modified": "2026-07-31T18:48:24.355Z", "name": "Inception", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Oleg Skulkin, Group-IB"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-493', 0, 208, '09-mitre-attack', 'retrieved', '66D51FD5E68E83C67C769BB638BC63612C45D824BC571BB77E371FD9638B4BF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
