VALUES ('doc-09-mitre-attack-p0-496', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Play"], "created": "2024-09-24T19:48:18.278Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Play](https://attack.mitre.org/groups/G1040) is a ransomware group that has been active since at least 2022 deploying [Playcrypt](https://attack.mitre.org/software/S1162) ransomware against the business, government, critical infrastructure, healthcare, and media sectors in North America, South America, and Europe. [Play](https://attack.mitre.org/groups/G1040) actors employ a double-extortion model, encrypting systems after exfiltrating data, and are presumed by security researchers to operate as a closed group.(Citation: CISA Play Ransomware Advisory December 2023)(Citation: Trend Micro Ransomware Spotlight Play July 2023)", "external_references": [{"external_id": "G1040", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1040"}, {"description": "CISA. (2023, December 18). #StopRansomware: Play Ransomware AA23-352A. Retrieved September 24, 2024.", "source_name": "CISA Play Ransomware Advisory December 2023", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-352a"}, {"description": "Trend Micro Research. (2023, July 21). Ransomware Spotlight: Play. Retrieved September 24, 2024.", "source_name": "Trend Micro Ransomware Spotlight Play July 2023", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-play"}], "id": "intrusion-set--ecbf507f-6786-4121-a4cc-0fd6a8d3a29d", "modified": "2026-07-31T18:48:24.924Z", "name": "Play", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Marco Pedrinazzi, @pedrinazziM"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-496', 0, 157, '09-mitre-attack', 'retrieved', 'B6496B0ABDBAD5DFEA56C54503A3FDB67F8525CEC3D3CA1CF49002F4F8382245', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
