VALUES ('doc-09-mitre-attack-p0-498', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT30"], "created": "2017-05-31T21:31:51.026Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT30](https://attack.mitre.org/groups/G0013) is a threat group suspected to be associated with the Chinese government. While [Naikon](https://attack.mitre.org/groups/G0019) shares some characteristics with [APT30](https://attack.mitre.org/groups/G0013), the two groups do not appear to be exact matches.(Citation: FireEye APT30)(Citation: Baumgartner Golovkin Naikon 2015)", "external_references": [{"external_id": "G0013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0013"}, {"description": "(Citation: FireEye APT30) (Citation: Baumgartner Golovkin Naikon 2015)", "source_name": "APT30"}, {"description": "Baumgartner, K., Golovkin, M.. (2015, May 14). The Naikon APT. Retrieved January 14, 2015.", "source_name": "Baumgartner Golovkin Naikon 2015", "url": "https://securelist.com/the-naikon-apt/69953/"}, {"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "intrusion-set--f047ee18-7985-4946-8bfb-4ed754d3a0dd", "modified": "2026-07-31T18:48:25.451Z", "name": "APT30", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-498', 0, 131, '09-mitre-attack', 'retrieved', '56A753C3571297AF5DAEDD0456C17B9CECC42260E2CBDB8A545805B94FBD6AE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
