VALUES ('doc-09-mitre-attack-p0-504', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["PLATINUM"], "created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PLATINUM](https://attack.mitre.org/groups/G0068) is an activity group that has targeted victims since at least 2009. The group has focused on targets associated with governments and related organizations in South and Southeast Asia. (Citation: Microsoft PLATINUM April 2016)", "external_references": [{"external_id": "G0068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0068"}, {"description": "(Citation: Microsoft PLATINUM April 2016)", "source_name": "PLATINUM"}, {"description": "Windows Defender Advanced Threat Hunting Team. (2016, April 29). PLATINUM: Targeted attacks in South and Southeast Asia. Retrieved February 15, 2018.", "source_name": "Microsoft PLATINUM April 2016", "url": "https://download.microsoft.com/download/2/2/5/225BFE3E-E1DE-4F5B-A77B-71200928D209/Platinum%20feature%20article%20-%20Targeted%20attacks%20in%20South%20and%20Southeast%20Asia%20April%202016.pdf"}], "id": "intrusion-set--f9c06633-dcff-48a1-8588-759e7cec5694", "modified": "2026-07-31T18:48:27.175Z", "name": "PLATINUM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Ryan Becwar"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-504', 0, 113, '09-mitre-attack', 'retrieved', 'EBB94E2951CF12E83D1BE825E75121EC9EC5336FCFF4745FCC924ECCA84041D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
