VALUES ('doc-09-mitre-attack-p0-510', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["FIN8", "Syssphinx"], "created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN8](https://attack.mitre.org/groups/G0061) is a financially motivated threat group that has been active since at least January 2016, and known for targeting organizations in the hospitality, retail, entertainment, insurance, technology, chemical, and financial sectors. In June 2021, security researchers detected [FIN8](https://attack.mitre.org/groups/G0061) switching from targeting point-of-sale (POS) devices to distributing a number of ransomware variants.(Citation: FireEye Obfuscation June 2017)(Citation: FireEye Fin8 May 2016)(Citation: Bitdefender Sardonic Aug 2021)(Citation: Symantec FIN8 Jul 2023)", "external_references": [{"external_id": "G0061", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0061"}, {"description": "(Citation: FireEye Obfuscation June 2017)", "source_name": "FIN8"}, {"description": "(Citation: Symantec FIN8 Jul 2023)", "source_name": "Syssphinx"}, {"description": "Bohannon, D. & Carr N. (2017, June 30). Obfuscation in the Wild: Targeted Attackers Lead the Way in Evasion Techniques. Retrieved February 12, 2018.", "source_name": "FireEye Obfuscation June 2017", "url": "https://web.archive.org/web/20170923102302/https://www.fireeye.com/blog/threat-research/2017/06/obfuscation-in-the-wild.html"}, {"description": "Budaca, E., et al. (2021, August 25). FIN8 Threat Actor Goes Agile with New Sardonic Backdoor. Retrieved August 9, 2023.", "source_name": "Bitdefender Sardonic Aug 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/401/Bitdefender-PR-Whitepaper-FIN8-creat5619-en-EN.pdf"}, {"description": "Kizhakkinan, D., et al. (2016, May 11). Threat Actor Leverages Windows Zero-day Exploit in Payment Card Data Attacks. Retrieved February 12, 2018.", "source_name": "FireEye Fin8 May 2016", "url": "https://www.fireeye.com/blog/threat-research/2016/05/windows-zero-day-payment-cards.html"}, {"description": "Symantec Threat Hunter Team. (2023, July 18). FIN8 Uses Revamped Sardonic Backdoor to Deliver Noberus Ransomware. Retrieved August 9, 2023.", "source_name": "Symantec FIN8 Jul 2023", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/syssphinx-fin8-backdoor"}], "id": "intrusion-set--fd19bd82-1b14-49a1-a176-6cdc46b8a826", "modified": "2026-07-31T18:48:28.923Z", "name": "FIN8", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security", "Serhii Melnyk, Trustwave SpiderLabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-510', 0, 250, '09-mitre-attack', 'retrieved', 'CCF6448C33E1728A4856A2B70DA769162EDA082CA4DED0E7A1814189BA3FD4E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
