VALUES ('doc-09-mitre-attack-p0-512', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT19", "Codoso", "C0d0so0", "Codoso Team", "Sunshop Group"], "created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT19](https://attack.mitre.org/groups/G0073) is a Chinese-based threat group that has targeted a variety of industries, including defense, finance, energy, pharmaceutical, telecommunications, high tech, education, manufacturing, and legal services. In 2017, a phishing campaign was used to target seven law and investment firms. (Citation: FireEye APT19) Some analysts track [APT19](https://attack.mitre.org/groups/G0073) and [Deep Panda](https://attack.mitre.org/groups/G0009) as the same group, but it is unclear from open source information if the groups are the same. (Citation: ICIT China''s Espionage Jul 2016) (Citation: FireEye APT Groups) (Citation: Unit 42 C0d0so0 Jan 2016)", "external_references": [{"external_id": "G0073", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0073"}, {"description": "(Citation: Dark Reading Codoso Feb 2015)", "source_name": "Sunshop Group"}, {"description": "(Citation: FireEye APT Groups)", "source_name": "Codoso Team"}, {"description": "(Citation: FireEye APT19)", "source_name": "APT19"}, {"description": "(Citation: Unit 42 C0d0so0 Jan 2016)", "source_name": "Codoso"}, {"description": "(Citation: Unit 42 C0d0so0 Jan 2016)", "source_name": "C0d0so0"}, {"description": "Ahl, I. (2017, June 06). Privileges and Credentials: Phished at the Request of Counsel. Retrieved May 17, 2018.", "source_name": "FireEye APT19", "url": "https://www.fireeye.com/blog/threat-research/2017/06/phished-at-the-request-of-counsel.html"}, {"description": "Chickowski, E. (2015, February 10). Chinese Hacking Group Codoso Team Uses Forbes.com As Watering Hole. Retrieved September 13, 2018.", "source_name": "Dark Reading Codoso Feb 2015", "url": "https://www.darkreading.com/attacks-breaches/chinese-hacking-group-codoso-team-uses-forbescom-as-watering-hole-/d/d-id/1319059"}, {"description": "FireEye. (n.d.). Advanced Persistent Threat Groups. Retrieved August 3, 2018.", "source_name": "FireEye APT Groups", "url": "https://www.fireeye.com/current-threats/apt-groups.html#apt19"}, {"description": "Grunzweig, J., Lee, B. (2016, January 22). New Attacks Linked to C0d0so0 Group. Retrieved August 2, 2018.", "source_name": "Unit 42 C0d0so0 Jan 2016", "url": "https://researchcenter.paloaltonetworks.com/2016/01/new-attacks-linked-to-c0d0s0-group/"}, {"description": "Scott, J. and Spaniel, D. (2016, July 28). ICIT Brief - China’s Espionage Dynasty: Economic Death by a Thousand Cuts. Retrieved June 7, 2018.", "source_name": "ICIT China''s Espionage Jul 2016", "url": "https://web.archive.org/web/20171017072306/https://icitech.org/icit-brief-chinas-espionage-dynasty-economic-death-by-a-thousand-cuts/"}], "id": "intrusion-set--fe8796a4-2a02-41a0-9d27-7aa1e995feb6", "modified": "2026-07-31T18:48:29.759Z", "name": "APT19", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["FS-ISAC", "Darren Spruell"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-512', 0, 302, '09-mitre-attack', 'retrieved', '046B994D411FC10F44D9B7F7F7D404BFE3BC1302ECF3D9E67AB0CB1222CEA7E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
