VALUES ('doc-09-mitre-attack-p0-515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:40.801Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HDoor](https://attack.mitre.org/software/S0061) is malware that has been customized and used by the [Naikon](https://attack.mitre.org/groups/G0019) group. (Citation: Baumgartner Naikon 2015)", "external_references": [{"external_id": "S0061", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0061"}, {"description": "Baumgartner, K., Golovkin, M.. (2015, May). The MsnMM Campaigns: The Earliest Naikon APT Campaigns. Retrieved April 10, 2019.", "source_name": "Baumgartner Naikon 2015", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07205555/TheNaikonAPT-MsnMM1.pdf"}], "id": "malware--007b44b6-e4c5-480b-b5b9-56f2081b1b7b", "is_family": true, "modified": "2025-04-16T20:37:51.573Z", "name": "HDoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HDoor", "Custom HDoor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-515', 0, 86, '09-mitre-attack', 'retrieved', 'BAF48C300C580FEAF909C639C92CA0AF6FC8C7478372C581F098F133657436EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
