VALUES ('doc-09-mitre-attack-p0-518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:19.746Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerDuke](https://attack.mitre.org/software/S0139) is a backdoor that was used by [APT29](https://attack.mitre.org/groups/G0016) in 2016. It has primarily been delivered through Microsoft Word or Excel attachments containing malicious macros. (Citation: Volexity PowerDuke November 2016)", "external_references": [{"external_id": "S0139", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0139"}, {"description": "(Citation: Volexity PowerDuke November 2016)", "source_name": "PowerDuke"}, {"description": "Adair, S.. (2016, November 9). PowerDuke: Widespread Post-Election Spear Phishing Campaigns Targeting Think Tanks and NGOs. Retrieved January 11, 2017.", "source_name": "Volexity PowerDuke November 2016", "url": "https://www.volexity.com/blog/2016/11/09/powerduke-post-election-spear-phishing-campaigns-targeting-think-tanks-and-ngos/"}], "id": "malware--00c3bfcb-99bd-4767-8c03-b08f585f5c8a", "is_family": true, "modified": "2025-04-25T14:42:30.325Z", "name": "PowerDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PowerDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-518', 0, 106, '09-mitre-attack', 'retrieved', 'EA89C03000CBCF728308231A8931DE84D410858427D90C30B638A655872B26D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
