VALUES ('doc-09-mitre-attack-p0-520', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-27T18:45:58.576Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BLINDINGCAN](https://attack.mitre.org/software/S0520) is a remote access Trojan that has been used by the North Korean government since at least early 2020 in cyber operations against defense, engineering, and government organizations in Western Europe and the US.(Citation: US-CERT BLINDINGCAN Aug 2020)(Citation: NHS UK BLINDINGCAN Aug 2020)", "external_references": [{"external_id": "S0520", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0520"}, {"description": "NHS Digital . (2020, August 20). BLINDINGCAN Remote Access Trojan. Retrieved August 20, 2020.", "source_name": "NHS UK BLINDINGCAN Aug 2020", "url": "https://digital.nhs.uk/cyber-alerts/2020/cc-3603"}, {"description": "US-CERT. (2020, August 19). MAR-10295134-1.v1 – North Korean Remote Access Trojan: BLINDINGCAN. Retrieved August 19, 2020.", "source_name": "US-CERT BLINDINGCAN Aug 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-232a"}], "id": "malware--01dbc71d-0ee8-420d-abb4-3dfb6a4bf725", "is_family": true, "modified": "2025-10-21T03:13:35.145Z", "name": "BLINDINGCAN", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BLINDINGCAN"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-520', 0, 138, '09-mitre-attack', 'retrieved', '1194BA628D531E6B3AABECCF472F7190BBAABEEEC69EDD81CB64F3B2F7F8A812', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
