INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-521', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-11T18:40:51.497Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ninja](https://attack.mitre.org/software/S1100) is a malware developed in C++ that has been used by [ToddyCat](https://attack.mitre.org/groups/G1022) to penetrate networks and control remote systems since at least 2020. [Ninja](https://attack.mitre.org/software/S1100) is possibly part of a post exploitation toolkit exclusively used by [ToddyCat](https://attack.mitre.org/groups/G1022) and allows multiple operators to work simultaneously on the same machine. [Ninja](https://attack.mitre.org/software/S1100) has been used against government and military entities in Europe and Asia and observed in specific infection chains being deployed by [Samurai](https://attack.mitre.org/software/S1099).(Citation: Kaspersky ToddyCat June 2022)", "external_references": [{"external_id": "S1100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1100"}, {"description": "Dedola, G. (2022, June 21). APT ToddyCat. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat June 2022", "url": "https://securelist.com/toddycat/106799/"}], "id": "malware--023254de-caaf-4a05-b2c7-e4e2f283f7a5", "is_family": true, "modified": "2025-10-22T02:17:48.978Z", "name": "Ninja", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ninja"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-521', 0, 136, '09-mitre-attack', 'retrieved', '7FC7B5D2E86B8A484BB5755CEF665700846B99378D0B1BEEF3B0B63EC5DD286F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
