VALUES ('doc-09-mitre-attack-p0-525', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-15T01:30:05.198Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\n[Spark](https://attack.mitre.org/software/S0543) is a Windows backdoor and has been in use since as early as 2017.(Citation: Unit42 Molerat Mar 2020) ", "external_references": [{"external_id": "S0543", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0543"}, {"description": "\n(Citation: Unit42 Molerat Mar 2020) ", "source_name": "Spark"}, {"description": "Falcone, R., et al. (2020, March 3). Molerats Delivers Spark Backdoor to Government and Telecommunications Organizations. Retrieved December 14, 2020.", "source_name": "Unit42 Molerat Mar 2020", "url": "https://unit42.paloaltonetworks.com/molerats-delivers-spark-backdoor/"}], "id": "malware--03ea629c-517a-41e3-94f8-c7e5368cf8f4", "is_family": true, "modified": "2025-04-25T14:42:31.753Z", "name": "Spark", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Spark"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-525', 0, 97, '09-mitre-attack', 'retrieved', '9F7A9DA83DECD7BDF0CA2CE62CCC499034437078CB4782BA50CA1F7C2CA3F5FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
