VALUES ('doc-09-mitre-attack-p0-526', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-18T16:46:39.268Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QuietSieve](https://attack.mitre.org/software/S0686) is an information stealer that has been used by [Gamaredon Group](https://attack.mitre.org/groups/G0047) since at least 2021.(Citation: Microsoft Actinium February 2022)", "external_references": [{"external_id": "S0686", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0686"}, {"description": "Microsoft Threat Intelligence Center. (2022, February 4). ACTINIUM targets Ukrainian organizations. Retrieved February 18, 2022.", "source_name": "Microsoft Actinium February 2022", "url": "https://www.microsoft.com/security/blog/2022/02/04/actinium-targets-ukrainian-organizations/"}], "id": "malware--03eb4a05-6a02-43f6-afb7-3c7835501828", "is_family": true, "modified": "2025-04-16T20:37:52.215Z", "name": "QuietSieve", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["QuietSieve"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-526', 0, 85, '09-mitre-attack', 'retrieved', '139E028D1E1318EF6B0D430321D340D1AB05F448575C78935F63DC0C3D85ED79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
