VALUES ('doc-09-mitre-attack-p0-527', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SynAck](https://attack.mitre.org/software/S0242) is variant of Trojan ransomware targeting mainly English-speaking users since at least fall 2017. (Citation: SecureList SynAck Doppelgänging May 2018) (Citation: Kaspersky Lab SynAck May 2018)", "external_references": [{"external_id": "S0242", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0242"}, {"description": "(Citation: SecureList SynAck Doppelgänging May 2018) (Citation: Kaspersky Lab SynAck May 2018)", "source_name": "SynAck"}, {"description": "Ivanov, A. et al. (2018, May 7). SynAck targeted ransomware uses the Doppelgänging technique. Retrieved May 22, 2018.", "source_name": "SecureList SynAck Doppelgänging May 2018", "url": "https://securelist.com/synack-targeted-ransomware-uses-the-doppelganging-technique/85431/"}, {"description": "Bettencourt, J. (2018, May 7). Kaspersky Lab finds new variant of SynAck ransomware using sophisticated Doppelgänging technique. Retrieved May 24, 2018.", "source_name": "Kaspersky Lab SynAck May 2018", "url": "https://usa.kaspersky.com/about/press-releases/2018_synack-doppelganging"}], "id": "malware--04227b24-7817-4de1-9050-b7b1b57f5866", "is_family": true, "modified": "2025-04-25T14:42:32.305Z", "name": "SynAck", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SynAck"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-527', 0, 139, '09-mitre-attack', 'retrieved', 'FB0BF08B71C4C3F8DB462490E82A2D039B9727E0CA3C41F2D22CF0C391EB66BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
