VALUES ('doc-09-mitre-attack-p0-531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-25T15:27:08.214Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AcidRain](https://attack.mitre.org/software/S1125) is an ELF binary targeting modems and routers using MIPS architecture.(Citation: AcidRain JAGS 2022) [AcidRain](https://attack.mitre.org/software/S1125) is associated with the ViaSat KA-SAT communication outage that took place during the initial phases of the 2022 full-scale invasion of Ukraine. Analysis indicates overlap with another network device-targeting malware, VPNFilter, associated with [Sandworm Team](https://attack.mitre.org/groups/G0034).(Citation: AcidRain JAGS 2022) US and European government sources linked [AcidRain](https://attack.mitre.org/software/S1125) to Russian government entities, while Ukrainian government sources linked [AcidRain](https://attack.mitre.org/software/S1125) specifically to [Sandworm Team](https://attack.mitre.org/groups/G0034).(Citation: AcidRain State Department 2022)(Citation: Vincens AcidPour 2024)", "external_references": [{"external_id": "S1125", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1125"}, {"description": "A.J. Vincens, CyberScoop. (2024, March 18). Researchers spot updated version of malware that hit Viasat. Retrieved March 25, 2024.", "source_name": "Vincens AcidPour 2024", "url": "https://cyberscoop.com/viasat-malware-wiper-acidrain/"}, {"description": "Antony J. Blinken, US Department of State. (2022, May 10). Attribution of Russia’s Malicious Cyber Activity Against Ukraine. Retrieved March 25, 2024.", "source_name": "AcidRain State Department 2022", "url": "https://www.state.gov/attribution-of-russias-malicious-cyber-activity-against-ukraine/"}, {"description": "Juan Andres Guerrero-Saade and Max van Amerongen, SentinelOne. (2022, March 31). AcidRain | A Modem Wiper Rains Down on Europe. Retrieved March 25, 2024.", "source_name": "AcidRain JAGS 2022", "url": "https://www.sentinelone.com/labs/acidrain-a-modem-wiper-rains-down-on-europe/"}], "id": "malware--04cecafd-cb5f-4daf-aa1f-73899116c4a2", "is_family": true, "modified": "2025-04-15T19:46:33.099Z", "name": "AcidRain", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AcidRain"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-531', 0, 213, '09-mitre-attack', 'retrieved', 'FAE51B4AB6CC0CC481358E065F86CAB312E354118ACA2A14557B05AB0927C527', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
