VALUES ('doc-09-mitre-attack-p0-532', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-11T17:29:20.165Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GRIFFON](https://attack.mitre.org/software/S0417) is a JavaScript backdoor used by [FIN7](https://attack.mitre.org/groups/G0046). (Citation: SecureList Griffon May 2019)", "external_references": [{"external_id": "S0417", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0417"}, {"description": "Namestnikov, Y. and Aime, F. (2019, May 8). FIN7.5: the infamous cybercrime rig “FIN7” continues its activities. Retrieved October 11, 2019.", "source_name": "SecureList Griffon May 2019", "url": "https://securelist.com/fin7-5-the-infamous-cybercrime-rig-fin7-continues-its-activities/90703/"}], "id": "malware--04fc1842-f9e4-47cf-8cb8-5c61becad142", "is_family": true, "modified": "2025-04-25T14:42:33.402Z", "name": "GRIFFON", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GRIFFON"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-532', 0, 82, '09-mitre-attack', 'retrieved', 'A0037F69A40A59BA65AB8A29B91E48E49342E0FD11AC0C872117E2CFFDE039D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
