VALUES ('doc-09-mitre-attack-p0-533', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T15:10:03.894Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Exaramel for Windows](https://attack.mitre.org/software/S0343) is a backdoor used for targeting Windows systems. The Linux version is tracked separately under [Exaramel for Linux](https://attack.mitre.org/software/S0401).(Citation: ESET TeleBots Oct 2018)", "external_references": [{"external_id": "S0343", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0343"}, {"description": "(Citation: ESET TeleBots Oct 2018)", "source_name": "Exaramel for Windows"}, {"description": "Cherepanov, A., Lipovsky, R. (2018, October 11). New TeleBots backdoor: First evidence linking Industroyer to NotPetya. Retrieved November 27, 2018.", "source_name": "ESET TeleBots Oct 2018", "url": "https://www.welivesecurity.com/2018/10/11/new-telebots-backdoor-linking-industroyer-notpetya/"}], "id": "malware--051eaca1-958f-4091-9e5f-a9acd8f820b5", "is_family": true, "modified": "2025-04-16T20:37:52.840Z", "name": "Exaramel for Windows", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Exaramel for Windows"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-533', 0, 109, '09-mitre-attack', 'retrieved', '78CAFE9B0F74A28EB64E06DDB65ADC0B1837070CFF1BC55D27633A7D03E53F88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
