VALUES ('doc-09-mitre-attack-p0-534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-14T17:30:54.927Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Amadey](https://attack.mitre.org/software/S1025) is a Trojan bot that has been used since at least October 2018.(Citation: Korean FSI TA505 2020)(Citation: BlackBerry Amadey 2020)", "external_references": [{"external_id": "S1025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1025"}, {"description": "Financial Security Institute. (2020, February 28). Profiling of TA505 Threat Group That Continues to Attack the Financial Sector. Retrieved July 14, 2022.", "source_name": "Korean FSI TA505 2020", "url": "https://www.fsec.or.kr/user/bbs/fsec/163/344/bbsDataView/1382.do?page=1&column=&search=&searchSDate=&searchEDate=&bbsDataCategory="}, {"description": "Kasuya, M. (2020, January 8). Threat Spotlight: Amadey Bot Targets Non-Russian Users. Retrieved July 14, 2022.", "source_name": "BlackBerry Amadey 2020", "url": "https://blogs.blackberry.com/en/2020/01/threat-spotlight-amadey-bot"}], "id": "malware--05318127-5962-444b-b900-a9dcfe0ff6e9", "is_family": true, "modified": "2026-05-12T15:12:00.732Z", "name": "Amadey", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Amadey"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-534', 0, 116, '09-mitre-attack', 'retrieved', 'B737948BC448FF44BA53421B55003006718C58546FC8F57455575C85EB2D5ACD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
