VALUES ('doc-09-mitre-attack-p0-535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T20:50:43.343Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[JumbledPath](https://attack.mitre.org/software/S1206) is a custom-built utility written in GO that has been used by [Salt Typhoon](https://attack.mitre.org/groups/G1045) since at least 2024 for packet capture on remote Cisco devices. [JumbledPath](https://attack.mitre.org/software/S1206) is compiled as an ELF binary using x86-64 architecture which makes it potentially useable across Linux operating systems and network devices from multiple vendors.(Citation: Cisco Salt Typhoon FEB 2025)", "external_references": [{"external_id": "S1206", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1206"}, {"description": "Cisco Talos. (2025, February 20). Weathering the storm: In the midst of a Typhoon. Retrieved February 24, 2025.", "source_name": "Cisco Salt Typhoon FEB 2025", "url": "https://blog.talosintelligence.com/salt-typhoon-analysis/"}], "id": "malware--05489800-6c6f-4922-a0de-d573b333e612", "is_family": true, "modified": "2025-04-15T19:46:33.196Z", "name": "JumbledPath", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["JumbledPath"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-535', 0, 126, '09-mitre-attack', 'retrieved', '4D7C088A1773984D484BB56383B9839C1263DC2BADEC80251067BA86AA210037', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
