VALUES ('doc-09-mitre-attack-p0-537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-08T22:16:27.705Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NICECURL](https://attack.mitre.org/software/S1192) is a VBScript-based backdoor used by [APT42](https://attack.mitre.org/groups/G1044) to download additional modules.(Citation: Mandiant APT42-untangling)", "external_references": [{"external_id": "S1192", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1192"}, {"description": "Rozmann, O., et al. (2024, May 1). Uncharmed: Untangling Iran''s APT42 Operations. Retrieved October 9, 2024.", "source_name": "Mandiant APT42-untangling", "url": "https://cloud.google.com/blog/topics/threat-intelligence/untangling-iran-apt42-operations"}], "id": "malware--0659f55c-3b68-4e5d-8071-12ded6684731", "is_family": true, "modified": "2025-01-08T23:14:18.123Z", "name": "NICECURL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NICECURL"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-537', 0, 78, '09-mitre-attack', 'retrieved', '38B49A784E8185F5605802CADFE8AA09DA193F0FAA8F53BEDE94C080F3C71E36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
