VALUES ('doc-09-mitre-attack-p0-542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[yty](https://attack.mitre.org/software/S0248) is a modular, plugin-based malware framework. The components of the framework are written in a variety of programming languages. (Citation: ASERT Donot March 2018)", "external_references": [{"external_id": "S0248", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0248"}, {"description": "(Citation: ASERT Donot March 2018)", "source_name": "yty"}, {"description": "Schwarz, D., Sopko J. (2018, March 08). Donot Team Leverages New Modular Malware Framework in South Asia. Retrieved June 11, 2018.", "source_name": "ASERT Donot March 2018", "url": "https://www.arbornetworks.com/blog/asert/donot-team-leverages-new-modular-malware-framework-south-asia/"}], "id": "malware--0817aaf2-afea-4c32-9285-4dcd1df5bf14", "is_family": true, "modified": "2025-10-22T03:06:38.183Z", "name": "yty", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["yty"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-542', 0, 104, '09-mitre-attack', 'retrieved', 'CEADE464DE7191541C4361C6E62F4ABF3807BD34EF488F9855F07B1FF16D67E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
