VALUES ('doc-09-mitre-attack-p0-545', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-14T17:34:58.457Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Stuxnet](https://attack.mitre.org/software/S0603) was the first publicly reported malware to specifically target industrial control systems devices. [Stuxnet](https://attack.mitre.org/software/S0603) is a large and complex malware that utilized multiple behaviors, including numerous zero-day vulnerabilities, a sophisticated Windows rootkit, and network infection routines.(Citation: Nicolas Falliere, Liam O Murchu, Eric Chien February 2011)(Citation: CISA ICS Advisory ICSA-10-272-01)(Citation: ESET Stuxnet Under the Microscope)(Citation: Langer Stuxnet) [Stuxnet](https://attack.mitre.org/software/S0603) was discovered in 2010, with some components being used as early as November 2008.(Citation: Nicolas Falliere, Liam O Murchu, Eric Chien February 2011) ", "external_references": [{"external_id": "S0603", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0603"}, {"description": "(Citation: Nicolas Falliere, Liam O Murchu, Eric Chien February 2011) ", "source_name": "W32.Stuxnet"}, {"description": "CISA. (2010, September 10). ICS Advisory (ICSA-10-272-01). Retrieved December 7, 2020.", "source_name": "CISA ICS Advisory ICSA-10-272-01", "url": "https://us-cert.cisa.gov/ics/advisories/ICSA-10-272-01"}, {"description": "Matrosov, A., Rodionov, E., Harley, D., Malcho, J.. (n.d.). Stuxnet Under the Microscope. Retrieved December 7, 2020.", "source_name": "ESET Stuxnet Under the Microscope", "url": "https://web-assets.esetstatic.com/wls/2012/11/Stuxnet_Under_the_Microscope.pdf"}, {"description": "Nicolas Falliere, Liam O Murchu, Eric Chien 2011, February W32.Stuxnet Dossier (Version 1.4) Retrieved November 17, 2024.", "source_name": "Nicolas Falliere, Liam O Murchu, Eric Chien February 2011", "url": "https://docs.broadcom.com/doc/security-response-w32-stuxnet-dossier-11-en"}, {"description": "Ralph Langner. (2013, November). To Kill a Centrifuge: A Technical Analysis of What Stuxnet''s Creators Tried to Achieve. Retrieved December 7, 2020.", "source_name": "Langer Stuxnet", "url": "https://www.langner.com/wp-content/uploads/2017/03/to-kill-a-centrifuge.pdf"}], "id": "malware--088f1d6e-0783-47c6-9923-9c79b2af43d4", "is_family": true, "modified": "2026-04-24T02:36:25.135Z", "name": "Stuxnet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Stuxnet", "W32.Stuxnet"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-545', 0, 243, '09-mitre-attack', 'retrieved', 'A6AEF41B843C92307D81AA2FBA5336EF2350C5DDB86396B56A74566BF6004EF1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
