VALUES ('doc-09-mitre-attack-p0-546', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T12:42:31.383Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IronWind](https://attack.mitre.org/software/S9029) is a custom loader malware that has been in use since at least 2023 by actors including [WIRTE](https://attack.mitre.org/groups/G0090) to target entities in the Middle East.(Citation: Check Point Wirte NOV 2024)", "external_references": [{"external_id": "S9029", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9029"}, {"description": "Check Point. (2024, November 12). Hamas-affiliated Threat Actor WIRTE Continues its Middle East Operations and Moves to Disruptive Activity. Retrieved April 20, 2026.", "source_name": "Check Point Wirte NOV 2024", "url": "https://research.checkpoint.com/2024/hamas-affiliated-threat-actor-expands-to-disruptive-activity/"}], "id": "malware--089aa00a-99ac-46b4-9cf8-4224d463566d", "is_family": true, "modified": "2026-05-12T15:12:00.732Z", "name": "IronWind", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["IronWind"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-546', 0, 105, '09-mitre-attack', 'retrieved', '426CF94B4184A26AA345A8C10BA9993153E477CA94AF903183BC81A907F87D91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
