VALUES ('doc-09-mitre-attack-p0-547', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:16.790Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Downdelph](https://attack.mitre.org/software/S0134) is a first-stage downloader written in Delphi that has been used by [APT28](https://attack.mitre.org/groups/G0007) in rare instances between 2013 and 2015. (Citation: ESET Sednit Part 3)", "external_references": [{"external_id": "S0134", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0134"}, {"description": "ESET. (2016, October). En Route with Sednit - Part 3: A Mysterious Downloader. Retrieved November 21, 2016.", "source_name": "ESET Sednit Part 3", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part3.pdf"}], "id": "malware--08d20cd2-f084-45ee-8558-fa6ef5a18519", "is_family": true, "modified": "2025-04-25T14:42:36.848Z", "name": "Downdelph", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Downdelph", "Delphacy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-547', 0, 92, '09-mitre-attack', 'retrieved', '231DD45F5221D0020035028D65FDF23DE5CD3EF137E8F70EBC4B1C0E87A182BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
