VALUES ('doc-09-mitre-attack-p0-548', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-14T17:04:01.673Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) is a 64-bit Linux backdoor used by [APT32](https://attack.mitre.org/groups/G0050). First seen in 2018, it uses a plugin architecture to extend capabilities. [RotaJakiro](https://attack.mitre.org/software/S1078) can determine it''s permission level and execute according to access type (`root` or `user`).(Citation: RotaJakiro 2021 netlab360 analysis)(Citation: netlab360 rotajakiro vs oceanlotus)", "external_references": [{"external_id": "S1078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1078"}, {"description": " Alex Turing, Hui Wang. (2021, April 28). RotaJakiro: A long live secret backdoor with 0 VT detection. Retrieved June 14, 2023.", "source_name": "RotaJakiro 2021 netlab360 analysis", "url": "https://blog.netlab.360.com/stealth_rotajakiro_backdoor_en/"}, {"description": "Alex Turing. (2021, May 6). RotaJakiro, the Linux version of the OceanLotus. Retrieved June 14, 2023.", "source_name": "netlab360 rotajakiro vs oceanlotus", "url": "https://blog.netlab.360.com/rotajakiro_linux_version_of_oceanlotus/"}], "id": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "is_family": true, "modified": "2023-10-12T21:19:45.801Z", "name": "RotaJakiro", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RotaJakiro"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-548', 0, 140, '09-mitre-attack', 'retrieved', 'D126F2CF639D0B1B612A083673378E7BE8A7B1C937635AEB9387ECD09D6AE352', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
