VALUES ('doc-09-mitre-attack-p0-549', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-11T21:17:36.149Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AvosLocker](https://attack.mitre.org/software/S1053) is ransomware written in C++ that has been offered via the Ransomware-as-a-Service (RaaS) model. It was first observed in June 2021 and has been used against financial services, critical manufacturing, government facilities, and other critical infrastructure sectors in the United States. As of March 2022, [AvosLocker](https://attack.mitre.org/software/S1053) had also been used against organizations in Belgium, Canada, China, Germany, Saudi Arabia, Spain, Syria, Taiwan, Turkey, the United Arab Emirates, and the United Kingdom.(Citation: Malwarebytes AvosLocker Jul 2021)(Citation: Trend Micro AvosLocker Apr 2022)(Citation: Joint CSA AvosLocker Mar 2022)", "external_references": [{"external_id": "S1053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1053"}, {"description": "FBI, FinCEN, Treasury. (2022, March 17). Indicators of Compromise Associated with AvosLocker Ransomware. Retrieved January 11, 2023.", "source_name": "Joint CSA AvosLocker Mar 2022", "url": "https://www.ic3.gov/Media/News/2022/220318.pdf"}, {"description": "Hasherezade. (2021, July 23). AvosLocker enters the ransomware scene, asks for partners. Retrieved January 11, 2023.", "source_name": "Malwarebytes AvosLocker Jul 2021", "url": "https://www.malwarebytes.com/blog/threat-intelligence/2021/07/avoslocker-enters-the-ransomware-scene-asks-for-partners"}, {"description": "Trend Micro Research. (2022, April 4). Ransomware Spotlight AvosLocker. Retrieved January 11, 2023.", "source_name": "Trend Micro AvosLocker Apr 2022", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-avoslocker"}], "id": "malware--0945a1a5-a79a-47c8-9079-10c16cdfcb5d", "is_family": true, "modified": "2025-04-21T19:40:47.538Z", "name": "AvosLocker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AvosLocker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Flávio Costa, @Segurança Descomplicada"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-549', 0, 206, '09-mitre-attack', 'retrieved', '0B04300A6113BE74A9B7CF9D6D0D5AB9689019BD2D5224531E804CC205945DA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
