VALUES ('doc-09-mitre-attack-p0-550', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SEASHARPEE](https://attack.mitre.org/software/S0185) is a Web shell that has been used by [OilRig](https://attack.mitre.org/groups/G0049). (Citation: FireEye APT34 Webinar Dec 2017)", "external_references": [{"external_id": "S0185", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0185"}, {"description": "(Citation: FireEye APT34 Webinar Dec 2017)", "source_name": "SEASHARPEE"}, {"description": "Davis, S. and Caban, D. (2017, December 19). APT34 - New Targeted Attack in the Middle East. Retrieved December 20, 2017.", "source_name": "FireEye APT34 Webinar Dec 2017", "url": "https://www.brighttalk.com/webcast/10703/296317/apt34-new-targeted-attack-in-the-middle-east"}], "id": "malware--0998045d-f96e-4284-95ce-3c8219707486", "is_family": true, "modified": "2025-04-25T14:42:37.580Z", "name": "SEASHARPEE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SEASHARPEE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-550', 0, 96, '09-mitre-attack', 'retrieved', 'B8066888DFC3080311BFAEC30DDA9014158664402958F00BB9E06CA2F6FA1047', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
