VALUES ('doc-09-mitre-attack-p0-552', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[POWRUNER](https://attack.mitre.org/software/S0184) is a PowerShell script that sends and receives commands to and from the C2 server. (Citation: FireEye APT34 Dec 2017)", "external_references": [{"external_id": "S0184", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0184"}, {"description": "(Citation: FireEye APT34 Dec 2017)", "source_name": "POWRUNER"}, {"description": "Sardiwal, M, et al. (2017, December 7). New Targeted Attack in the Middle East by APT34, a Suspected Iranian Threat Group, Using CVE-2017-11882 Exploit. Retrieved December 20, 2017.", "source_name": "FireEye APT34 Dec 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/12/targeted-attack-in-middle-east-by-apt34.html"}], "id": "malware--09b2cd76-c674-47cc-9f57-d2f2ad150a46", "is_family": true, "modified": "2025-04-25T14:42:38.309Z", "name": "POWRUNER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["POWRUNER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-552', 0, 105, '09-mitre-attack', 'retrieved', '2550A7F40237819657441A8016D2C6CB14E65397CB7C1931F5F888B4C73CB781', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
