VALUES ('doc-09-mitre-attack-p0-553', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-17T18:49:25.528Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KOPILUWAK](https://attack.mitre.org/software/S1075) is a JavaScript-based reconnaissance tool that has been used for victim profiling and C2 since at least 2017.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"external_id": "S1075", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1075"}, {"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "malware--09fcc02f-f9d4-43fa-8609-5e5e186b7103", "is_family": true, "modified": "2025-04-16T20:37:54.797Z", "name": "KOPILUWAK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KOPILUWAK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-553', 0, 108, '09-mitre-attack', 'retrieved', '24F708A2711D4BD0EEE7A289C9566012C93EAF1D4A5FCE1AA736619D10C4B0CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
