VALUES ('doc-09-mitre-attack-p0-554', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-29T14:27:18.204Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RobbinHood](https://attack.mitre.org/software/S0400) is ransomware that was first observed being used in an attack against the Baltimore city government''s computer network.(Citation: CarbonBlack RobbinHood May 2019)(Citation: BaltimoreSun RobbinHood May 2019)", "external_references": [{"external_id": "S0400", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0400"}, {"description": "Lee, S. (2019, May 17). CB TAU Threat Intelligence Notification: RobbinHood Ransomware Stops 181 Windows Services Before Encryption. Retrieved July 29, 2019.", "source_name": "CarbonBlack RobbinHood May 2019", "url": "https://www.carbonblack.com/2019/05/17/cb-tau-threat-intelligence-notification-robbinhood-ransomware-stops-181-windows-services-before-encryption/"}, {"description": "Duncan, I., Campbell, C. (2019, May 7). Baltimore city government computer network hit by ransomware attack. Retrieved July 29, 2019.", "source_name": "BaltimoreSun RobbinHood May 2019", "url": "https://www.baltimoresun.com/politics/bs-md-ci-it-outage-20190507-story.html"}], "id": "malware--0a607c53-df52-45da-a75d-0e53df4dad5f", "is_family": true, "modified": "2025-04-25T14:42:38.861Z", "name": "RobbinHood", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RobbinHood"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-554', 0, 125, '09-mitre-attack', 'retrieved', '041847348CF17019C6384A5946CA0B458913DD4F9B861EA3D9DED1317B1FFB25', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
