VALUES ('doc-09-mitre-attack-p0-558', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TDTESS](https://attack.mitre.org/software/S0164) is a 64-bit .NET binary backdoor used by [CopyKittens](https://attack.mitre.org/groups/G0052). (Citation: ClearSky Wilted Tulip July 2017)", "external_references": [{"external_id": "S0164", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0164"}, {"description": "(Citation: ClearSky Wilted Tulip July 2017)", "source_name": "TDTESS"}, {"description": "ClearSky Cyber Security and Trend Micro. (2017, July). Operation Wilted Tulip: Exposing a cyber espionage apparatus. Retrieved August 21, 2017.", "source_name": "ClearSky Wilted Tulip July 2017", "url": "http://www.clearskysec.com/wp-content/uploads/2017/07/Operation_Wilted_Tulip.pdf"}], "id": "malware--0b32ec39-ba61-4864-9ebe-b4b0b73caf9a", "is_family": true, "modified": "2025-04-25T14:42:39.777Z", "name": "TDTESS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TDTESS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-558', 0, 94, '09-mitre-attack', 'retrieved', 'F8658E84F00551A3FF13F895DE7BE95FD9ECB211E9B3887E535B6408E8367554', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
