VALUES ('doc-09-mitre-attack-p0-563', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-05T15:56:46.250Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sardonic](https://attack.mitre.org/software/S1085) is a backdoor written in C and C++ that is known to be used by [FIN8](https://attack.mitre.org/groups/G0061), as early as August 2021 to target a financial institution in the United States. [Sardonic](https://attack.mitre.org/software/S1085) has a plugin system that can load specially made DLLs and execute their functions.(Citation: Bitdefender Sardonic Aug 2021)(Citation: Symantec FIN8 Jul 2023)", "external_references": [{"external_id": "S1085", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1085"}, {"description": "Budaca, E., et al. (2021, August 25). FIN8 Threat Actor Goes Agile with New Sardonic Backdoor. Retrieved August 9, 2023.", "source_name": "Bitdefender Sardonic Aug 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/401/Bitdefender-PR-Whitepaper-FIN8-creat5619-en-EN.pdf"}, {"description": "Symantec Threat Hunter Team. (2023, July 18). FIN8 Uses Revamped Sardonic Backdoor to Deliver Noberus Ransomware. Retrieved August 9, 2023.", "source_name": "Symantec FIN8 Jul 2023", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/syssphinx-fin8-backdoor"}], "id": "malware--0c52f5bc-557d-4083-bd27-66d7cdb794bb", "is_family": true, "modified": "2025-10-22T02:07:46.452Z", "name": "Sardonic", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Sardonic"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Serhii Melnyk, Trustwave SpiderLabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-563', 0, 157, '09-mitre-attack', 'retrieved', '5097DE9412EC814614FA20857A0A57EFD693067F160AA349C212C26E66CBA14D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
