VALUES ('doc-09-mitre-attack-p0-566', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-04T19:01:53.566Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WindTail](https://attack.mitre.org/software/S0466) is a macOS surveillance implant used by [Windshift](https://attack.mitre.org/groups/G0112). [WindTail](https://attack.mitre.org/software/S0466) shares code similarities with Hack Back aka KitM OSX.(Citation: SANS Windshift August 2018)(Citation: objective-see windtail1 dec 2018)(Citation: objective-see windtail2 jan 2019)", "external_references": [{"external_id": "S0466", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0466"}, {"description": "Karim, T. (2018, August). TRAILS OF WINDSHIFT. Retrieved November 17, 2024.", "source_name": "SANS Windshift August 2018", "url": "https://www.scribd.com/document/661837258/WINDSHIFT-summit-archive-1554718868"}, {"description": "Wardle, Patrick. (2018, December 20). Middle East Cyber-Espionage analyzing WindShift''s implant: OSX.WindTail (part 1). Retrieved October 3, 2019.", "source_name": "objective-see windtail1 dec 2018", "url": "https://objective-see.com/blog/blog_0x3B.html"}, {"description": "Wardle, Patrick. (2019, January 15). Middle East Cyber-Espionage analyzing WindShift''s implant: OSX.WindTail (part 2). Retrieved October 3, 2019.", "source_name": "objective-see windtail2 jan 2019", "url": "https://objective-see.com/blog/blog_0x3D.html"}], "id": "malware--0d1f9f5b-11ea-42c3-b5f4-63cce0122541", "is_family": true, "modified": "2024-11-17T14:15:51.851Z", "name": "WindTail", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WindTail"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-566', 0, 144, '09-mitre-attack', 'retrieved', '485FB614EAE2320D27C4359E82B6F61FB84D369D8E9A56AAD16AD737ACFD395F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
