VALUES ('doc-09-mitre-attack-p0-567', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:55.126Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Misdat](https://attack.mitre.org/software/S0083) is a backdoor that was used in [Operation Dust Storm](https://attack.mitre.org/campaigns/C0016) from 2010 to 2011.(Citation: Cylance Dust Storm)", "external_references": [{"external_id": "S0083", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0083"}, {"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "malware--0db09158-6e48-4e7c-8ce7-2b10b9c0c039", "is_family": true, "modified": "2025-04-16T20:37:55.806Z", "name": "Misdat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Misdat"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-567', 0, 79, '09-mitre-attack', 'retrieved', '43FA4D2BD8810B7CE18F2AB48E6B45252A057EE63E8965125D723E8932FCAF33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
