VALUES ('doc-09-mitre-attack-p0-568', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T18:21:30.985Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[reGeorg](https://attack.mitre.org/software/S1187) is an open-source web shell written in Python that can be used as a proxy to bypass firewall rules and tunnel data in and out of targeted networks.(Citation: Fortinet reGeorg MAR 2019)(Citation: GitHub reGeorg 2016)", "external_references": [{"external_id": "S1187", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1187"}, {"description": "FortiGard Labs. (2019, March 12). ReGeorg.HTTP.Tunnel. Retrieved December 3, 2024.", "source_name": "Fortinet reGeorg MAR 2019", "url": "https://www.fortiguard.com/encyclopedia/ips/47584/regeorg-http-tunnel"}, {"description": "xl7dev. (2016). reGeorg-master. Retrieved December 3, 2024.", "source_name": "GitHub reGeorg 2016", "url": "https://github.com/xl7dev/WebShell/tree/master/reGeorg-master"}], "id": "malware--0e17b066-50dd-4c2f-83bf-205c5eb2bb34", "is_family": true, "modified": "2025-04-15T19:46:33.459Z", "name": "reGeorg", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["reGeorg"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Windows", "macOS", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-568', 0, 114, '09-mitre-attack', 'retrieved', '662662DC2599EA1969863C114FB9BAA494396EE51518131B965EB2F525DBDABC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
