VALUES ('doc-09-mitre-attack-p0-569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FLIPSIDE](https://attack.mitre.org/software/S0173) is a simple tool similar to Plink that is used by [FIN5](https://attack.mitre.org/groups/G0053) to maintain access to victims. (Citation: Mandiant FIN5 GrrCON Oct 2016)", "external_references": [{"external_id": "S0173", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0173"}, {"description": "(Citation: Mandiant FIN5 GrrCON Oct 2016)", "source_name": "FLIPSIDE"}, {"description": "Bromiley, M. and Lewis, P. (2016, October 7). Attacking the Hospitality and Gaming Industries: Tracking an Attacker Around the World in 7 Years. Retrieved October 6, 2017.", "source_name": "Mandiant FIN5 GrrCON Oct 2016", "url": "https://www.youtube.com/watch?v=fevGZs0EQu8"}], "id": "malware--0e18b800-906c-4e44-a143-b11c72b3448b", "is_family": true, "modified": "2025-04-25T14:42:42.171Z", "name": "FLIPSIDE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FLIPSIDE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-569', 0, 109, '09-mitre-attack', 'retrieved', 'F6E42EE90B9DF7B7AAB9EC172D2430E1B90564079ACF4D27C3A8D5986D075118', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
