VALUES ('doc-09-mitre-attack-p0-570', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-04T17:12:37.586Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Linux Rabbit](https://attack.mitre.org/software/S0362) is malware that targeted Linux servers and IoT devices in a campaign lasting from August to October 2018. It shares code with another strain of malware known as Rabbot. The goal of the campaign was to install cryptocurrency miners onto the targeted servers and devices.(Citation: Anomali Linux Rabbit 2018)\n", "external_references": [{"external_id": "S0362", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0362"}, {"description": "Anomali Threat Research. (2018, December 6). Pulling Linux Rabbit/Rabbot Malware Out of a Hat. Retrieved December 17, 2020.", "source_name": "anomali-linux-rabbit", "url": "https://www.anomali.com/blog/pulling-linux-rabbit-rabbot-malware-out-of-a-hat"}, {"description": "Anomali Labs. (2018, December 6). Pulling Linux Rabbit/Rabbot Malware Out of a Hat. Retrieved March 4, 2019.", "source_name": "Anomali Linux Rabbit 2018", "url": "https://www.anomali.com/blog/pulling-linux-rabbit-rabbot-malware-out-of-a-hat"}], "id": "malware--0efefea5-78da-4022-92bc-d726139e8883", "is_family": true, "modified": "2025-04-25T14:42:42.534Z", "name": "Linux Rabbit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Linux Rabbit"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-570', 0, 141, '09-mitre-attack', 'retrieved', '4FD831B2D8DF77C805FB6427F9AFB627C681B70DCD4F8D83918A11197C475F65', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
