VALUES ('doc-09-mitre-attack-p0-571', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[adbupd](https://attack.mitre.org/software/S0202) is a backdoor used by [PLATINUM](https://attack.mitre.org/groups/G0068) that is similar to [Dipsind](https://attack.mitre.org/software/S0200). (Citation: Microsoft PLATINUM April 2016)", "external_references": [{"external_id": "S0202", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0202"}, {"description": "(Citation: Microsoft PLATINUM April 2016)", "source_name": "adbupd"}, {"description": "Windows Defender Advanced Threat Hunting Team. (2016, April 29). PLATINUM: Targeted attacks in South and Southeast Asia. Retrieved February 15, 2018.", "source_name": "Microsoft PLATINUM April 2016", "url": "https://download.microsoft.com/download/2/2/5/225BFE3E-E1DE-4F5B-A77B-71200928D209/Platinum%20feature%20article%20-%20Targeted%20attacks%20in%20South%20and%20Southeast%20Asia%20April%202016.pdf"}], "id": "malware--0f1ad2ef-41d4-4b7a-9304-ddae68ea3005", "is_family": true, "modified": "2025-04-25T14:42:42.902Z", "name": "adbupd", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["adbupd"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Ryan Becwar"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-571', 0, 97, '09-mitre-attack', 'retrieved', '4BA1B5BE8FA5F9C7870463B44A94A27178B127D466839A9F9A01FF3FFDAC0CC1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
