VALUES ('doc-09-mitre-attack-p0-572', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:54.772Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emissary](https://attack.mitre.org/software/S0082) is a Trojan that has been used by [Lotus Blossom](https://attack.mitre.org/groups/G0030). It shares code with [Elise](https://attack.mitre.org/software/S0081), with both Trojans being part of a malware group referred to as LStudio.(Citation: Lotus Blossom Dec 2015)", "external_references": [{"external_id": "S0082", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0082"}, {"description": "(Citation: Lotus Blossom Dec 2015)", "source_name": "Emissary"}, {"description": "Falcone, R. and Miller-Osborn, J.. (2015, December 18). Attack on French Diplomat Linked to Operation Lotus Blossom. Retrieved February 15, 2016.", "source_name": "Lotus Blossom Dec 2015", "url": "http://researchcenter.paloaltonetworks.com/2015/12/attack-on-french-diplomat-linked-to-operation-lotus-blossom/"}], "id": "malware--0f862b01-99da-47cc-9bdb-db4a86a95bb1", "is_family": true, "modified": "2025-04-02T20:35:25.274Z", "name": "Emissary", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Emissary"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-572', 0, 112, '09-mitre-attack', 'retrieved', '90169B92E5091C9788A4FC063B48FEB688D723667E916B77DB6FF090641BCFAF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
