VALUES ('doc-09-mitre-attack-p0-573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-26T13:02:46.378Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Exaramel for Linux](https://attack.mitre.org/software/S0401) is a backdoor written in the Go Programming Language and compiled as a 64-bit ELF binary. The Windows version is tracked separately under [Exaramel for Windows](https://attack.mitre.org/software/S0343).(Citation: ESET TeleBots Oct 2018)", "external_references": [{"external_id": "S0401", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0401"}, {"description": "(Citation: ESET TeleBots Oct 2018)", "source_name": "Exaramel for Linux"}, {"description": "Cherepanov, A., Lipovsky, R. (2018, October 11). New TeleBots backdoor: First evidence linking Industroyer to NotPetya. Retrieved November 27, 2018.", "source_name": "ESET TeleBots Oct 2018", "url": "https://www.welivesecurity.com/2018/10/11/new-telebots-backdoor-linking-industroyer-notpetya/"}], "id": "malware--11194d8b-fdce-45d2-8047-df15bb8f16bd", "is_family": true, "modified": "2024-04-11T02:34:14.304Z", "name": "Exaramel for Linux", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Exaramel for Linux"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-573', 0, 117, '09-mitre-attack', 'retrieved', 'A0BF5B9A2309693C67D76F684DEF57F56F757CF4B908B91EDDA1E92052007A1D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
