VALUES ('doc-09-mitre-attack-p0-574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KEYMARBLE](https://attack.mitre.org/software/S0271) is a Trojan that has reportedly been used by the North Korean government. (Citation: US-CERT KEYMARBLE Aug 2018)", "external_references": [{"external_id": "S0271", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0271"}, {"description": "(Citation: US-CERT KEYMARBLE Aug 2018)", "source_name": "KEYMARBLE"}, {"description": "US-CERT. (2018, August 09). MAR-10135536-17 – North Korean Trojan: KEYMARBLE. Retrieved August 16, 2018.", "source_name": "US-CERT KEYMARBLE Aug 2018", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR18-221A"}], "id": "malware--11e36d5b-6a92-4bf9-8eb7-85eb24f59e22", "is_family": true, "modified": "2025-10-22T02:28:32.075Z", "name": "KEYMARBLE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KEYMARBLE"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-574', 0, 91, '09-mitre-attack', 'retrieved', 'F74B17A78CD6ABB92435FDFC3295AFC0B46E3166C4D6CB1C5F9EEEAECA4E41FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
