VALUES ('doc-09-mitre-attack-p0-575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:33.738Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BUBBLEWRAP](https://attack.mitre.org/software/S0043) is a full-featured, second-stage backdoor used by the [admin@338](https://attack.mitre.org/groups/G0018) group. It is set to run when the system boots and includes functionality to check, upload, and register plug-ins that can further enhance its capabilities. (Citation: FireEye admin@338)", "external_references": [{"external_id": "S0043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0043"}, {"description": "FireEye Threat Intelligence. (2015, December 1). China-based Cyber Threat Group Uses Dropbox for Malware Communications and Targets Hong Kong Media Outlets. Retrieved December 4, 2015.", "source_name": "FireEye admin@338", "url": "https://www.fireeye.com/blog/threat-research/2015/11/china-based-threat.html"}], "id": "malware--123bd7b3-675c-4b1a-8482-c55782b20e2b", "is_family": true, "modified": "2025-04-25T14:42:44.013Z", "name": "BUBBLEWRAP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BUBBLEWRAP", "Backdoor.APT.FakeWinHTTPHelper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-575', 0, 110, '09-mitre-attack', 'retrieved', '2E351D0104CD77C9C724163330535A610BF3A1391932C249ACD22CA8AE3ED807', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
