VALUES ('doc-09-mitre-attack-p0-576', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-20T14:52:45.057Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HAWKBALL](https://attack.mitre.org/software/S0391) is a backdoor that was observed in targeting of the government sector in Central Asia.(Citation: FireEye HAWKBALL Jun 2019)", "external_references": [{"external_id": "S0391", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0391"}, {"description": "(Citation: FireEye HAWKBALL Jun 2019)", "source_name": "HAWKBALL"}, {"description": "Patil, S. and Williams, M.. (2019, June 5). Government Sector in Central Asia Targeted With New HAWKBALL Backdoor Delivered via Microsoft Office Vulnerabilities. Retrieved June 20, 2019.", "source_name": "FireEye HAWKBALL Jun 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/06/government-in-central-asia-targeted-with-hawkball-backdoor.html"}], "id": "malware--12a7450d-b03e-4990-a5b8-b405ab9c803b", "is_family": true, "modified": "2024-04-11T02:23:13.352Z", "name": "HAWKBALL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HAWKBALL"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-576', 0, 105, '09-mitre-attack', 'retrieved', '185429CA38C91F91882F83B38F2248A6EF4D62F1E1C7EC08B52F09103DC498F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
