VALUES ('doc-09-mitre-attack-p0-577', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-08T22:21:32.556Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TAMECAT](https://attack.mitre.org/software/S1193) is a malware that is used by [APT42](https://attack.mitre.org/groups/G1044) to execute PowerShell or C# content.(Citation: Mandiant APT42-untangling) ", "external_references": [{"external_id": "S1193", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1193"}, {"description": "Rozmann, O., et al. (2024, May 1). Uncharmed: Untangling Iran''s APT42 Operations. Retrieved October 9, 2024.", "source_name": "Mandiant APT42-untangling", "url": "https://cloud.google.com/blog/topics/threat-intelligence/untangling-iran-apt42-operations"}], "id": "malware--12fdf05a-4bd1-4f45-9cde-d3af35f82db1", "is_family": true, "modified": "2025-01-08T22:21:48.530Z", "name": "TAMECAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TAMECAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-577', 0, 82, '09-mitre-attack', 'retrieved', 'FD159C2DAC97D3E79B290482DFF32C2C429A4FA86F26363B4DA7A5A7897D4B36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
