VALUES ('doc-09-mitre-attack-p0-581', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-16T20:20:54.148Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CASTLETAP](https://attack.mitre.org/software/S1224) is an ICMP port knocking backdoor that has been installed on compromised FortiGate firewalls by [UNC3886](https://attack.mitre.org/groups/G1048).(Citation: Mandiant Fortinet Zero Day)", "external_references": [{"external_id": "S1224", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1224"}, {"description": "Marvi, A. et al.. (2023, March 16). Fortinet Zero-Day and Custom Malware Used by Suspected Chinese Actor in Espionage Operation. Retrieved March 22, 2023.", "source_name": "Mandiant Fortinet Zero Day", "url": "https://www.mandiant.com/resources/blog/fortinet-malware-ecosystem"}], "id": "malware--15c7bcdb-23e1-4ce3-81a7-b109b4d2a4f1", "is_family": true, "modified": "2025-06-16T20:21:39.051Z", "name": "CASTLETAP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CASTLETAP"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-581', 0, 96, '09-mitre-attack', 'retrieved', '597C8B15CD017DB0B980746D38C27C41C8BAC9D7F59BD43F6F89D6FA9CB82535', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
