VALUES ('doc-09-mitre-attack-p0-582', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-30T15:46:36.159Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThreatNeedle](https://attack.mitre.org/software/S0665) is a backdoor that has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032) since at least 2019 to target cryptocurrency, defense, and mobile gaming organizations. It is considered to be an advanced cluster of [Lazarus Group](https://attack.mitre.org/groups/G0032)''s Manuscrypt (a.k.a. NukeSped) malware family.(Citation: Kaspersky ThreatNeedle Feb 2021)", "external_references": [{"external_id": "S0665", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0665"}, {"description": "Vyacheslav Kopeytsev and Seongsu Park. (2021, February 25). Lazarus targets defense industry with ThreatNeedle. Retrieved October 27, 2021.", "source_name": "Kaspersky ThreatNeedle Feb 2021", "url": "https://securelist.com/lazarus-threatneedle/100803/"}], "id": "malware--16040b1c-ed28-4850-9d8f-bb8b81c42092", "is_family": true, "modified": "2024-04-10T22:32:30.915Z", "name": "ThreatNeedle", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ThreatNeedle"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-582', 0, 111, '09-mitre-attack', 'retrieved', '2981F5BB20F4052615D2645972BFF014CDE9CFAA7F357BF1DC44F53CF2862014', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
