VALUES ('doc-09-mitre-attack-p0-583', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-17T19:03:28.707Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RansomHub](https://attack.mitre.org/software/S1212) is a ransomware-as-a-service (RaaS) offering with Windows, ESXi, Linux, and FreeBSD versions that has been in use since at least 2024 to target organizations in multiple sectors globally. [RansomHub](https://attack.mitre.org/software/S1212) operators may have purchased and rebranded resources from Knight (formerly Cyclops) Ransomware which shares infrastructure, feature, and code overlaps with [RansomHub](https://attack.mitre.org/software/S1212).(Citation: CISA RansomHub AUG 2024)(Citation: Group-IB RansomHub FEB 2025)", "external_references": [{"external_id": "S1212", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1212"}, {"description": "Alfano, V. et al. (2025, February 12). RansomHub Never Sleeps Episode 1: The evolution of modern ransomware. Retrieved March 17, 2025.", "source_name": "Group-IB RansomHub FEB 2025", "url": "https://www.group-ib.com/blog/ransomhub-never-sleeps-episode-1/"}, {"description": "CISA et al. (2024, August 29). #StopRansomware: RansomHub Ransomware. Retrieved March 17, 2025.", "source_name": "CISA RansomHub AUG 2024", "url": "https://www.cisa.gov/sites/default/files/2024-09/aa24-242a-stopransomware-ransomhub-ransomware_1.pdf"}], "id": "malware--16662bee-9d15-4564-a128-1fce214866e9", "is_family": true, "modified": "2025-03-27T14:29:41.961Z", "name": "RansomHub", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RansomHub"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-583', 0, 152, '09-mitre-attack', 'retrieved', '56F1E10A255AB45FB381D2569A8DC54E874C21C0FA6167C2F3BE6A4A71F97B75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
