VALUES ('doc-09-mitre-attack-p0-585', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLeaves](https://attack.mitre.org/software/S0153) is a malware family used by [menuPass](https://attack.mitre.org/groups/G0045). The code overlaps with [PlugX](https://attack.mitre.org/software/S0013) and may be based upon the open source tool Trochilus. (Citation: PWC Cloud Hopper Technical Annex April 2017) (Citation: FireEye APT10 April 2017)", "external_references": [{"external_id": "S0153", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0153"}, {"description": "(Citation: PWC Cloud Hopper Technical Annex April 2017)", "source_name": "RedLeaves"}, {"description": "Based on similarities in reported malware behavior and open source reporting, it is assessed that the malware named BUGJUICE by FireEye is likely the same as the malware RedLeaves. (Citation: FireEye APT10 April 2017) (Citation: Twitter Nick Carr APT10)", "source_name": "BUGJUICE"}, {"description": "Carr, N.. (2017, April 6). Retrieved September 12, 2024.", "source_name": "Twitter Nick Carr APT10", "url": "https://x.com/ItsReallyNick/status/850105140589633536"}, {"description": "FireEye iSIGHT Intelligence. (2017, April 6). APT10 (MenuPass Group): New Tools, Global Campaign Latest Manifestation of Longstanding Threat. Retrieved June 29, 2017.", "source_name": "FireEye APT10 April 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/04/apt10_menupass_grou.html"}, {"description": "PwC and BAE Systems. (2017, April). Operation Cloud Hopper: Technical Annex. Retrieved April 13, 2017.", "source_name": "PWC Cloud Hopper Technical Annex April 2017", "url": "https://www.pwc.co.uk/cyber-security/pdf/pwc-uk-operation-cloud-hopper-technical-annex-april-2017.pdf"}], "id": "malware--17b40f60-729f-4fe8-8aea-cc9ee44a95d5", "is_family": true, "modified": "2024-09-12T19:32:28.614Z", "name": "RedLeaves", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RedLeaves", "BUGJUICE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Edward Millington"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-585', 0, 208, '09-mitre-attack', 'retrieved', 'CC3118D08474487CB0101DE76BB702E325813F2579633F43F2313A75B572B97D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
