VALUES ('doc-09-mitre-attack-p0-586', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:16.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Miner-C](https://attack.mitre.org/software/S0133) is malware that mines victims for the Monero cryptocurrency. It has targeted FTP servers and Network Attached Storage (NAS) devices to spread. (Citation: Softpedia MinerC)", "external_references": [{"external_id": "S0133", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0133"}, {"description": "Cimpanu, C.. (2016, September 9). Cryptocurrency Mining Malware Discovered Targeting Seagate NAS Hard Drives. Retrieved September 12, 2024.", "source_name": "Softpedia MinerC", "url": "https://news.softpedia.com/news/cryptocurrency-mining-malware-discovered-targeting-seagate-nas-hard-drives-508119.shtml"}], "id": "malware--17dec760-9c8f-4f1b-9b4b-0ac47a453234", "is_family": true, "modified": "2024-09-12T15:19:00.433Z", "name": "Miner-C", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Miner-C"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-586', 0, 90, '09-mitre-attack', 'retrieved', 'CC51EF55E5EF0B9620434327ADE8BC98FD4551117C52CC8E05D7F1AC1BD6CD77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
