INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-588', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T22:24:44.870Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tsundere Botnet](https://attack.mitre.org/software/S9034) is a botnet first reported in mid-2025 that is delivered via MSI installer or a PowerShell script. It leverages Node.js and JavaScript for payload delivery and execution, and uses smart contracts on the blockchain to host command and control (C2) addresses. [Tsundere Botnet](https://attack.mitre.org/software/S9034) is attributed to a likely Russian-speaking threat actor.\n\nA variant named DinDoor has been linked to [MuddyWater](https://attack.mitre.org/groups/G0069) operations and uses the Deno runtime for execution rather than Node.js.(Citation: Checkpoint_MOISCyberCrime_Mar2026)(Citation: SOCRadar_MuddyWaterDindoor_Mar2026)(Citation: CAL_MuddyWater_Mar2026)(Citation: SecureListUbiedo_Tsundere_Nov2025) ", "external_references": [{"external_id": "S9034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9034"}, {"description": "(Citation: Checkpoint_MOISCyberCrime_Mar2026)", "source_name": "DinDoor"}, {"description": "CheckPoint Research. (2026, March 10). Iranian MOIS Actors & the Cyber Crime Connection. Retrieved March 12, 2026.", "source_name": "Checkpoint_MOISCyberCrime_Mar2026", "url": "https://research.checkpoint.com/2026/iranian-mois-actors-the-cyber-crime-connection/"}, {"description": "Ctrl-Alt-Intel. (2026, March 4). MuddyWater Exposed: Inside an Iranian APT operation . Retrieved April 6, 2026.", "source_name": "CAL_MuddyWater_Mar2026", "url": "https://ctrlaltintel.com/research/MuddyWater/"}, {"description": "SOCRadar. (2026, March 9). MuddyWater Uses Dindoor Malware Targeting U.S. Networks. Retrieved March 12, 2026.", "source_name": "SOCRadar_MuddyWaterDindoor_Mar2026", "url": "https://socradar.io/blog/iran-muddywater-dindoor-malware-us-networks/"}, {"description": "Ubiedo, L. (2025, November 20). Blockchain and Node.js abused by Tsundere: an emerging botnet. Retrieved April 6, 2026.", "source_name": "SecureListUbiedo_Tsundere_Nov2025", "url": "https://securelist.com/tsundere-node-js-botnet-uses-ethereum-blockchain/117979/"}], "id": "malware--18f5f8c6-bba5-4aba-93e7-3539fe565883", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "Tsundere Botnet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Tsundere Botnet", "DinDoor"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-588', 0, 215, '09-mitre-attack', 'retrieved', 'F9AF8C0338003415269D68F6A288BD4D6D06EA4BA2B1DBF5F65C36CA8AB39A77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
