VALUES ('doc-09-mitre-attack-p0-591', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T17:59:43.600Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zeus Panda](https://attack.mitre.org/software/S0330) is a Trojan designed to steal banking information and other sensitive credentials for exfiltration. [Zeus Panda](https://attack.mitre.org/software/S0330)’s original source code was leaked in 2011, allowing threat actors to use its source code as a basis for new malware variants. It is mainly used to target Windows operating systems ranging from Windows XP through Windows 10.(Citation: Talos Zeus Panda Nov 2017)(Citation: GDATA Zeus Panda June 2017)", "external_references": [{"external_id": "S0330", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0330"}, {"description": "(Citation: Talos Zeus Panda Nov 2017)(Citation: GDATA Zeus Panda June 2017)", "source_name": "Zeus Panda"}, {"description": "Brumaghin, E., et al. (2017, November 02). Poisoning the Well: Banking Trojan Targets Google Search Results. Retrieved November 5, 2018.", "source_name": "Talos Zeus Panda Nov 2017", "url": "https://blog.talosintelligence.com/2017/11/zeus-panda-campaign.html#More"}, {"description": "Ebach, L. (2017, June 22). Analysis Results of Zeus.Variant.Panda. Retrieved November 5, 2018.", "source_name": "GDATA Zeus Panda June 2017", "url": "https://cyberwtf.files.wordpress.com/2017/07/panda-whitepaper.pdf"}], "id": "malware--198db886-47af-4f4c-bff5-11b891f85946", "is_family": true, "modified": "2024-04-10T20:31:00.234Z", "name": "Zeus Panda", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Zeus Panda"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-591', 0, 176, '09-mitre-attack', 'retrieved', '621A1E362771F4902F623EAE010661F8C82CF5657281D1B32ACEA789B1EB809B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
