VALUES ('doc-09-mitre-attack-p0-592', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:36.177Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GeminiDuke](https://attack.mitre.org/software/S0049) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2009 to 2012. (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0049", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0049"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--199463de-d9be-46d6-bb41-07234c1dd5a6", "is_family": true, "modified": "2025-04-25T14:42:46.881Z", "name": "GeminiDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GeminiDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-592', 0, 79, '09-mitre-attack', 'retrieved', '3C529835B26D106BCBC0CFEC67A99D64E6D55C1FC452E5B0210E725F22E26BE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
