VALUES ('doc-09-mitre-attack-p0-593', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-05T18:12:15.228Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Havoc](https://attack.mitre.org/software/S1229) is an open-source post-exploitation command and control (C2) framework first released on GitHub in October 2022 by C5pider (Paul Ungur), who continues to maintain and develop it with community contributors. [Havoc](https://attack.mitre.org/software/S1229) provides a wide range of offensive security capabilities and has been adopted by multiple threat actors to establish and maintain control over compromised systems.", "external_references": [{"external_id": "S1229", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1229"}], "id": "malware--1996aed9-6234-4c1d-a145-e8a4913679dd", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "Havoc", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Havoc"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Enis Aksu"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-593', 0, 103, '09-mitre-attack', 'retrieved', '1F53970D3B0B6378AAD5487BE31BBE0E03F3127F08F10B8BA89335DB2E4ECD69', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
