VALUES ('doc-09-mitre-attack-p0-595', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Matryoshka](https://attack.mitre.org/software/S0167) is a malware framework used by [CopyKittens](https://attack.mitre.org/groups/G0052) that consists of a dropper, loader, and RAT. It has multiple versions; v1 was seen in the wild from July 2016 until January 2017. v2 has fewer commands and other minor differences. (Citation: ClearSky Wilted Tulip July 2017) (Citation: CopyKittens Nov 2015)", "external_references": [{"external_id": "S0167", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0167"}, {"description": "(Citation: ClearSky Wilted Tulip July 2017)", "source_name": "Matryoshka"}, {"description": "ClearSky Cyber Security and Trend Micro. (2017, July). Operation Wilted Tulip: Exposing a cyber espionage apparatus. Retrieved August 21, 2017.", "source_name": "ClearSky Wilted Tulip July 2017", "url": "http://www.clearskysec.com/wp-content/uploads/2017/07/Operation_Wilted_Tulip.pdf"}, {"description": "Minerva Labs LTD and ClearSky Cyber Security. (2015, November 23). CopyKittens Attack Group. Retrieved November 17, 2024.", "source_name": "CopyKittens Nov 2015", "url": "https://cdn2.hubspot.net/hubfs/1903456/Whitepapers/CopyKittens.pdf"}], "id": "malware--1cc934e4-b01d-4543-a011-b988dfc1a458", "is_family": true, "modified": "2024-11-17T12:44:07.639Z", "name": "Matryoshka", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Matryoshka"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-595', 0, 154, '09-mitre-attack', 'retrieved', '2E4A7FE71AB2636BB685A6AE1EC12A54B2544B1ADAB8FD9C283894419D85EECD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
