VALUES ('doc-09-mitre-attack-p0-596', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-08T14:55:46.094Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FrameworkPOS](https://attack.mitre.org/software/S0503) is a point of sale (POS) malware used by [FIN6](https://attack.mitre.org/groups/G0037) to steal payment card data from sytems that run physical POS devices.(Citation: SentinelOne FrameworkPOS September 2019)", "external_references": [{"external_id": "S0503", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0503"}, {"description": "(Citation: SentinelOne FrameworkPOS September 2019)", "source_name": "Trinity"}, {"description": "Kremez, V. (2019, September 19). FIN6 “FrameworkPOS”: Point-of-Sale Malware Analysis & Internals. Retrieved September 8, 2020.", "source_name": "SentinelOne FrameworkPOS September 2019", "url": "https://labs.sentinelone.com/fin6-frameworkpos-point-of-sale-malware-analysis-internals-2/"}], "id": "malware--1cdbbcab-903a-414d-8eb0-439a97343737", "is_family": true, "modified": "2025-04-25T14:42:47.607Z", "name": "FrameworkPOS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FrameworkPOS", "Trinity"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Center for Threat-Informed Defense (CTID)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-596', 0, 104, '09-mitre-attack', 'retrieved', 'EA9E2CA099FFAC4BAA54D54885A8B010820B8E9D1D5BEB657CCA2D5F9E41BA70', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
