VALUES ('doc-09-mitre-attack-p0-598', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:06.433Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WEBC2](https://attack.mitre.org/software/S0109) is a family of backdoor malware used by [APT1](https://attack.mitre.org/groups/G0006) as early as July 2006. [WEBC2](https://attack.mitre.org/software/S0109) backdoors are designed to retrieve a webpage, with commands hidden in HTML comments or special tags, from a predetermined C2 server. (Citation: Mandiant APT1 Appendix)(Citation: Mandiant APT1)", "external_references": [{"external_id": "S0109", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0109"}, {"description": "(Citation: Mandiant APT1)", "source_name": "WEBC2"}, {"description": "Mandiant. (n.d.). Appendix C (Digital) - The Malware Arsenal. Retrieved July 18, 2016.", "source_name": "Mandiant APT1 Appendix", "url": "https://www.mandiant.com/sites/default/files/2021-09/mandiant-apt1-report.pdf"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "malware--1d808f62-cf63-4063-9727-ff6132514c22", "is_family": true, "modified": "2023-12-26T19:55:54.848Z", "name": "WEBC2", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WEBC2"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Wes Hurd"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-598', 0, 134, '09-mitre-attack', 'retrieved', '6741F27BF90654139CCD1918C8F5247B58076992B3D558EB4C92D33B57E7BF28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
