VALUES ('doc-09-mitre-attack-p0-599', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-20T18:43:05.682Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Prestige](https://attack.mitre.org/software/S1058) ransomware has been used by [Sandworm Team](https://attack.mitre.org/groups/G0034) since at least March 2022, including against transportation and related logistics industries in Ukraine and Poland in October 2022.(Citation: Microsoft Prestige ransomware October 2022)", "external_references": [{"external_id": "S1058", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1058"}, {"description": "MSTIC. (2022, October 14). New “Prestige” ransomware impacts organizations in Ukraine and Poland. Retrieved January 19, 2023.", "source_name": "Microsoft Prestige ransomware October 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/10/14/new-prestige-ransomware-impacts-organizations-in-ukraine-and-poland/"}], "id": "malware--1da748a5-875d-4212-9222-b4c23ab861be", "is_family": true, "modified": "2025-04-16T20:37:57.513Z", "name": "Prestige", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Prestige"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Mindaugas Gudzis, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-599', 0, 105, '09-mitre-attack', 'retrieved', '4C2BA6E2997DE6D8EFE753B1733E869847F5D01F90E734337AE1FFA867222D98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
