VALUES ('doc-09-mitre-attack-p0-601', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bankshot](https://attack.mitre.org/software/S0239) is a remote access tool (RAT) that was first reported by the Department of Homeland Security in December of 2017. In 2018, [Lazarus Group](https://attack.mitre.org/groups/G0032) used the [Bankshot](https://attack.mitre.org/software/S0239) implant in attacks against the Turkish financial sector. (Citation: McAfee Bankshot)", "external_references": [{"external_id": "S0239", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0239"}, {"description": "(Citation: McAfee Bankshot)", "source_name": "Bankshot"}, {"description": "(Citation: McAfee Bankshot)", "source_name": "Trojan Manuscript"}, {"description": "Sherstobitoff, R. (2018, March 08). Hidden Cobra Targets Turkish Financial Sector With New Bankshot Implant. Retrieved May 18, 2018.", "source_name": "McAfee Bankshot", "url": "https://securingtomorrow.mcafee.com/mcafee-labs/hidden-cobra-targets-turkish-financial-sector-new-bankshot-implant/"}], "id": "malware--1f6e3702-7ca1-4582-b2e7-4591297d05a8", "is_family": true, "modified": "2025-10-22T02:26:07.951Z", "name": "Bankshot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bankshot", "Trojan Manuscript"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-601', 0, 121, '09-mitre-attack', 'retrieved', '4A615A6BA690FA9C9E3EB663B85E5C586DD2777A3C049CD110DAA44AB1346C48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
