VALUES ('doc-09-mitre-attack-p0-602', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-26T20:19:15.106Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SharpDisco](https://attack.mitre.org/software/S1089) is a dropper developed in C# that has been used by [MoustachedBouncer](https://attack.mitre.org/groups/G1019) since at least 2020 to load malicious plugins.(Citation: MoustachedBouncer ESET August 2023)", "external_references": [{"external_id": "S1089", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1089"}, {"description": "Faou, M. (2023, August 10). MoustachedBouncer: Espionage against foreign diplomats in Belarus. Retrieved September 25, 2023.", "source_name": "MoustachedBouncer ESET August 2023", "url": "https://www.welivesecurity.com/en/eset-research/moustachedbouncer-espionage-against-foreign-diplomats-in-belarus/"}], "id": "malware--1fefb062-feda-484a-8f10-0cebf65e20e3", "is_family": true, "modified": "2025-04-16T20:37:57.878Z", "name": "SharpDisco", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SharpDisco"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-602', 0, 91, '09-mitre-attack', 'retrieved', 'E0006DBF751634A4A8EA64BDC23249D642426DFDB0CD6BAAFBA2DD0AB280C17C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
