VALUES ('doc-09-mitre-attack-p0-605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-29T00:04:26.906Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[xCaon](https://attack.mitre.org/software/S0653) is an HTTP variant of the [BoxCaon](https://attack.mitre.org/software/S0651) malware family that has used by [IndigoZebra](https://attack.mitre.org/groups/G0136) since at least 2014. [xCaon](https://attack.mitre.org/software/S0653) has been used to target political entities in Central Asia, including Kyrgyzstan and Uzbekistan.(Citation: Checkpoint IndigoZebra July 2021)(Citation: Securelist APT Trends Q2 2017)", "external_references": [{"external_id": "S0653", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0653"}, {"description": "(Citation: Checkpoint IndigoZebra July 2021)", "source_name": "xCaon"}, {"description": "CheckPoint Research. (2021, July 1). IndigoZebra APT continues to attack Central Asia with evolving tools. Retrieved September 24, 2021.", "source_name": "Checkpoint IndigoZebra July 2021", "url": "https://research.checkpoint.com/2021/indigozebra-apt-continues-to-attack-central-asia-with-evolving-tools/"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2017, August 8). APT Trends report Q2 2017. Retrieved February 15, 2018.", "source_name": "Securelist APT Trends Q2 2017", "url": "https://securelist.com/apt-trends-report-q2-2017/79332/"}], "id": "malware--21583311-6321-4891-8a37-3eb4e57b0fb1", "is_family": true, "modified": "2025-04-25T14:42:49.417Z", "name": "xCaon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["xCaon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-605', 0, 161, '09-mitre-attack', 'retrieved', 'F7FCB01E32E70F33AE85F5C3633B07F078BCB9799302FF24B22E60DB63E47CB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
