VALUES ('doc-09-mitre-attack-p0-606', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PLAINTEE](https://attack.mitre.org/software/S0254) is a malware sample that has been used by [Rancor](https://attack.mitre.org/groups/G0075) in targeted attacks in Singapore and Cambodia. (Citation: Rancor Unit42 June 2018)", "external_references": [{"external_id": "S0254", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0254"}, {"description": "(Citation: Rancor Unit42 June 2018)", "source_name": "PLAINTEE"}, {"description": "Ash, B., et al. (2018, June 26). RANCOR: Targeted Attacks in South East Asia Using PLAINTEE and DDKONG Malware Families. Retrieved July 2, 2018.", "source_name": "Rancor Unit42 June 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/06/unit42-rancor-targeted-attacks-south-east-asia-using-plaintee-ddkong-malware-families/"}], "id": "malware--21c0b55b-5ff3-4654-a05e-e3fc1ee1ce1b", "is_family": true, "modified": "2025-04-25T14:42:49.775Z", "name": "PLAINTEE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PLAINTEE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-606', 0, 103, '09-mitre-attack', 'retrieved', '0EF5AF97D86D4DEEA87B5AEB49445B2AFD36DB67855197F681E1292D84E53961', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
