VALUES ('doc-09-mitre-attack-p0-607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-21T21:03:35.244Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pony](https://attack.mitre.org/software/S0453) is a credential stealing malware, though has also been used among adversaries for its downloader capabilities. The source code for Pony Loader 1.0 and 2.0 were leaked online, leading to their use by various threat actors.(Citation: Malwarebytes Pony April 2016)", "external_references": [{"external_id": "S0453", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0453"}, {"description": "hasherezade. (2016, April 11). No money, but Pony! From a mail to a trojan horse. Retrieved May 21, 2020.", "source_name": "Malwarebytes Pony April 2016", "url": "https://blog.malwarebytes.com/threat-analysis/2015/11/no-money-but-pony-from-a-mail-to-a-trojan-horse/"}], "id": "malware--222ba512-32d9-49ac-aefd-50ce981ce2ce", "is_family": true, "modified": "2025-04-25T14:42:50.153Z", "name": "Pony", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pony"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Arie Olshtein, Check Point", "Kobi Eisenkraft, Check Point"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-607', 0, 117, '09-mitre-attack', 'retrieved', 'DAE3F0D58C7CEA2738CD2A0D9DF66383A776A998B7CA98F72E750E6F17532FCE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
