VALUES ('doc-09-mitre-attack-p0-609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-30T14:44:35.055Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nebulae](https://attack.mitre.org/software/S0630) Is a backdoor that has been used by [Naikon](https://attack.mitre.org/groups/G0019) since at least 2020.(Citation: Bitdefender Naikon April 2021)", "external_references": [{"external_id": "S0630", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0630"}, {"description": "Vrabie, V. (2021, April 23). NAIKON – Traces from a Military Cyber-Espionage Operation. Retrieved June 29, 2021.", "source_name": "Bitdefender Naikon April 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/396/Bitdefender-PR-Whitepaper-NAIKON-creat5397-en-EN.pdf"}], "id": "malware--22b17791-45bf-45c0-9322-ff1a0af5cf2b", "is_family": true, "modified": "2025-04-25T14:42:50.875Z", "name": "Nebulae", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Nebulae"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-609', 0, 85, '09-mitre-attack', 'retrieved', 'C02FB2289B885312F0852D0A09D2AB5E605316FB4A6C2FAD0FFEACCA972D36DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
