VALUES ('doc-09-mitre-attack-p0-610', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Janicab](https://attack.mitre.org/software/S0163) is an OS X trojan that relied on a valid developer ID and oblivious users to install it. (Citation: Janicab)", "external_references": [{"external_id": "S0163", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0163"}, {"description": "Thomas. (2013, July 15). New signed malware called Janicab. Retrieved July 17, 2017.", "source_name": "Janicab", "url": "https://web.archive.org/web/20230331162455/https://www.thesafemac.com/new-signed-malware-called-janicab/"}], "id": "malware--234e7770-99b0-4f65-b983-d3230f76a60b", "is_family": true, "modified": "2024-09-12T19:07:36.511Z", "name": "Janicab", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Janicab"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-610', 0, 81, '09-mitre-attack', 'retrieved', 'EA247913EE9AE7FD3FB71A22CE1B2CA6C093DC5A883FF8228CC5E59694C868FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
