VALUES ('doc-09-mitre-attack-p0-611', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T15:47:41.018Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AuditCred](https://attack.mitre.org/software/S0347) is a malicious DLL that has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032) during their 2018 attacks.(Citation: TrendMicro Lazarus Nov 2018)", "external_references": [{"external_id": "S0347", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0347"}, {"description": "(Citation: TrendMicro Lazarus Nov 2018)", "source_name": "AuditCred"}, {"description": "(Citation: TrendMicro Lazarus Nov 2018)", "source_name": "Roptimizer"}, {"description": "Trend Micro. (2018, November 20). Lazarus Continues Heists, Mounts Attacks on Financial Organizations in Latin America. Retrieved December 3, 2018.", "source_name": "TrendMicro Lazarus Nov 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/lazarus-continues-heists-mounts-attacks-on-financial-organizations-in-latin-america/"}], "id": "malware--24b4ce59-eaac-4c8b-8634-9b093b7ccd92", "is_family": true, "modified": "2024-04-11T02:57:01.302Z", "name": "AuditCred", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AuditCred", "Roptimizer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-611', 0, 107, '09-mitre-attack', 'retrieved', 'A9A11F46807117F7A3DE7CB3A0E6324F7827FF6649EB5A643C43B771CDD14BAA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
