VALUES ('doc-09-mitre-attack-p0-612', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T19:03:01.696Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROAMINGHOUSE](https://attack.mitre.org/software/S9026) is a dropper malware used by [MirrorFace](https://attack.mitre.org/groups/G1054) to extract and execute embedded payloads including [UPPERCUT](https://attack.mitre.org/software/S0275) components.(Citation: Trend Micro Earth Kasha Updates APR 2025)", "external_references": [{"external_id": "S9026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9026"}, {"description": "Hiroaki, H. (2025, April 30). Earth Kasha Updates TTPs in Latest Campaign Targeting Taiwan and Japan. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Updates APR 2025", "url": "https://www.trendmicro.com/en_us/research/25/d/earth-kasha-updates-ttps.html"}], "id": "malware--251f1715-fc97-4487-b939-5c8823ef7a39", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "ROAMINGHOUSE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ROAMINGHOUSE"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-612', 0, 101, '09-mitre-attack', 'retrieved', 'C988F01515D59023399838E8F31ADDFCD5D6AC03C78F02B690BBD38881E3C807', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
