VALUES ('doc-09-mitre-attack-p0-613', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:14.527Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lurid](https://attack.mitre.org/software/S0010) is a malware family that has been used by several groups, including [PittyTiger](https://attack.mitre.org/groups/G0011), in targeted attacks as far back as 2006. (Citation: Villeneuve 2014) (Citation: Villeneuve 2011)", "external_references": [{"external_id": "S0010", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0010"}, {"description": "Villeneuve, N., Homan, J. (2014, July 31). Spy of the Tiger. Retrieved September 29, 2015.", "source_name": "Villeneuve 2014", "url": "https://www.fireeye.com/blog/threat-research/2014/07/spy-of-the-tiger.html"}, {"description": "Villeneuve, N., Sancho, D. (2011). THE “LURID” DOWNLOADER. Retrieved November 12, 2014.", "source_name": "Villeneuve 2011", "url": "http://www.trendmicro.com/cloud-content/us/pdfs/security-intelligence/white-papers/wp_dissecting-lurid-apt.pdf"}], "id": "malware--251fbae2-78f6-4de7-84f6-194c727a64ad", "is_family": true, "modified": "2025-04-25T14:42:51.586Z", "name": "Lurid", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Lurid", "Enfal"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-613', 0, 108, '09-mitre-attack', 'retrieved', '621DF3DC4987B515169FE3BA73B5F86B20B9268D163A0F931C9DB9590B011CCE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
