VALUES ('doc-09-mitre-attack-p0-614', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-15T13:52:23.890Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TONESHELL](https://attack.mitre.org/software/S1239) is a custom backdoor that has been used since at least Q1 2021.(Citation: Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023) [TONESHELL](https://attack.mitre.org/software/S1239) malware has previously been leveraged by Chinese affiliated actors identified as [Mustang Panda](https://attack.mitre.org/groups/G0129).(Citation: ATTACKIQ MUSTANG PANDA TONESHELL March 2023)(Citation: Zscaler)", "external_references": [{"external_id": "S1239", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1239"}, {"description": "Ken Towne, Francis Guibernau. (2023, March 23). Emulating the Politically Motivated Chinese APT Mustang Panda. Retrieved September 10, 2025.", "source_name": "ATTACKIQ MUSTANG PANDA TONESHELL March 2023", "url": "https://www.attackiq.com/2023/03/23/emulating-the-politically-motivated-chinese-apt-mustang-panda/"}, {"description": "Lior Rochberger, Tom Fakterman, Robert Falcone. (2023, September 22). Cyberespionage Attacks Against Southeast Asian Government Linked to Stately Taurus, Aka Mustang Panda. Retrieved September 9, 2025.", "source_name": "Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023", "url": "https://unit42.paloaltonetworks.com/stately-taurus-attacks-se-asian-government/"}, {"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: ToneShell and StarProxy | P1. Retrieved July 21, 2025.", "source_name": "Zscaler", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-toneshell-and-starproxy-p1"}], "id": "malware--2683fde8-1dc4-415c-94bd-9bb95cc5b7ff", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "TONESHELL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TONESHELL"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["YH Chang, ZScaler", "ZScaler"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-614', 0, 180, '09-mitre-attack', 'retrieved', '2BBD64F2AA2DFA603E1395DC7B36E7953C82070B07617DB20FAF3AA0F0CF117B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
