VALUES ('doc-09-mitre-attack-p0-615', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T21:55:54.792Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UPSTYLE](https://attack.mitre.org/software/S1164) is a Python-based backdoor associated with exploitation of Palo Alto firewalls using CVE-2024-3400 in early 2024. [UPSTYLE](https://attack.mitre.org/software/S1164) has only been observed in relation to this exploitation activity, which involved attempted install on compromised devices by the threat actor UTA0218.(Citation: Volexity UPSTYLE 2024)(Citation: Palo Alto MidnightEclipse APR 2024)", "external_references": [{"external_id": "S1164", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1164"}, {"description": "Unit 42. (2024, April 12). Threat Brief: Operation MidnightEclipse, Post-Exploitation Activity Related to CVE-2024-3400 . Retrieved January 15, 2025.", "source_name": "Palo Alto MidnightEclipse APR 2024", "url": "https://unit42.paloaltonetworks.com/cve-2024-3400/"}, {"description": "Volexity Threat Research. (2024, April 12). Zero-Day Exploitation of Unauthenticated Remote Code Execution Vulnerability in GlobalProtect (CVE-2024-3400). Retrieved November 20, 2024.", "source_name": "Volexity UPSTYLE 2024", "url": "https://www.volexity.com/blog/2024/04/12/zero-day-exploitation-of-unauthenticated-remote-code-execution-vulnerability-in-globalprotect-cve-2024-3400/"}], "id": "malware--2692bdd0-da52-44ff-88a3-9db28b948ea2", "is_family": true, "modified": "2025-04-15T19:46:33.707Z", "name": "UPSTYLE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["UPSTYLE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-615', 0, 148, '09-mitre-attack', 'retrieved', '533F713E12D7270C5F81C6915363656F160850E946B17242FACEA5B93247BB00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
