VALUES ('doc-09-mitre-attack-p0-616', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:57.344Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kasidet](https://attack.mitre.org/software/S0088) is a backdoor that has been dropped by using malicious VBA macros. (Citation: Zscaler Kasidet)", "external_references": [{"external_id": "S0088", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0088"}, {"description": "Yadav, A., et al. (2016, January 29). Malicious Office files dropping Kasidet and Dridex. Retrieved March 24, 2016.", "source_name": "Zscaler Kasidet", "url": "http://research.zscaler.com/2016/01/malicious-office-files-dropping-kasidet.html"}], "id": "malware--26fed817-e7bf-41f9-829a-9075ffac45c2", "is_family": true, "modified": "2025-04-25T14:42:52.151Z", "name": "Kasidet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kasidet"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-616', 0, 80, '09-mitre-attack', 'retrieved', '5038A3C0DA16A0D69318853256C792207974FA03F78743CA0E6E558B3D6BCD82', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
