VALUES ('doc-09-mitre-attack-p0-617', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-16T09:55:45.092Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hannotog](https://attack.mitre.org/software/S1211) is a type of backdoor malware uniquely assoicated with [Lotus Blossom](https://attack.mitre.org/groups/G0030) operations since at least 2022.(Citation: Symantec Bilbug 2022)", "external_references": [{"external_id": "S1211", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1211"}, {"description": "Symntec Threat Hunter Team. (2022, November 12). Billbug: State-sponsored Actor Targets Cert Authority, Government Agencies in Multiple Asian Countries. Retrieved March 15, 2025.", "source_name": "Symantec Bilbug 2022", "url": "https://www.security.com/threat-intelligence/espionage-asia-governments-cert-authority"}], "id": "malware--273e2b53-64ec-48be-9ad9-8f3dc0e53718", "is_family": true, "modified": "2025-04-04T17:35:36.538Z", "name": "Hannotog", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hannotog"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-617', 0, 92, '09-mitre-attack', 'retrieved', 'D18CA1F8442208E944DD4035EB90CED114556640F2785C658C691BF6A3DD01BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
