VALUES ('doc-09-mitre-attack-p0-618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T15:43:19.105Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OceanSalt](https://attack.mitre.org/software/S0346) is a Trojan that was used in a campaign targeting victims in South Korea, United States, and Canada. [OceanSalt](https://attack.mitre.org/software/S0346) shares code similarity with [SpyNote RAT](https://attack.mitre.org/software/S0305), which has been linked to [APT1](https://attack.mitre.org/groups/G0006).(Citation: McAfee Oceansalt Oct 2018)", "external_references": [{"external_id": "S0346", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0346"}, {"description": "(Citation: McAfee Oceansalt Oct 2018)", "source_name": "OceanSalt"}, {"description": "Sherstobitoff, R., Malhotra, A. (2018, October 18). ‘Operation Oceansalt’ Attacks South Korea, U.S., and Canada With Source Code From Chinese Hacker Group. Retrieved November 30, 2018.", "source_name": "McAfee Oceansalt Oct 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-oceansalt.pdf"}], "id": "malware--288fa242-e894-4c7e-ac86-856deedf5cea", "is_family": true, "modified": "2025-04-25T14:42:52.708Z", "name": "OceanSalt", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OceanSalt"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-618', 0, 118, '09-mitre-attack', 'retrieved', '708EF4300D5B577E31B6664834B3A329E5BEA65210D2AD3C74A671A3034A681C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
