VALUES ('doc-09-mitre-attack-p0-619', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-25T17:16:06.149Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Playcrypt](https://attack.mitre.org/software/S1162) is a ransomware that has been used by [Play](https://attack.mitre.org/groups/G1040) since at least 2022 in attacks against against the business, government, critical infrastructure, healthcare, and media sectors in North America, South America, and Europe. [Playcrypt](https://attack.mitre.org/software/S1162) derives its name from adding the .play extension to encrypted files and has overlap with tactics and tools associated with Hive and Nokoyawa ransomware and infrastructure associated with Quantum ransomware.(Citation: Microsoft PlayCrypt August 2022)(Citation: CISA Play Ransomware Advisory December 2023)(Citation: Trend Micro Ransomware Spotlight Play July 2023)", "external_references": [{"external_id": "S1162", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1162"}, {"description": "(Citation: CISA Play Ransomware Advisory December 2023)(Citation: Trend Micro Ransomware Spotlight Play July 2023)", "source_name": "Play"}, {"description": "CISA. (2023, December 18). #StopRansomware: Play Ransomware AA23-352A. Retrieved September 24, 2024.", "source_name": "CISA Play Ransomware Advisory December 2023", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-352a"}, {"description": "Microsoft Security Intelligence. (2022, August 27). Ransom:Win32/PlayCrypt.PA. Retrieved September 24, 2024.", "source_name": "Microsoft PlayCrypt August 2022", "url": "https://www.microsoft.com/en-us/wdsi/threats/malware-encyclopedia-description?Name=Ransom:Win32/PlayCrypt.PA&ThreatID=2147830341"}, {"description": "Trend Micro Research. (2023, July 21). Ransomware Spotlight: Play. Retrieved September 24, 2024.", "source_name": "Trend Micro Ransomware Spotlight Play July 2023", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-play"}], "id": "malware--28ad4983-151e-4e30-9792-768470e92b3e", "is_family": true, "modified": "2024-10-02T05:37:59.575Z", "name": "Playcrypt", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Playcrypt", "Play"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Marco Pedrinazzi, @pedrinazziM"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-619', 0, 211, '09-mitre-attack', 'retrieved', '73DA0C47F2474235136B54EFBA5A22A12A7B0E2BE881B6BA53152D8BC7D376FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
