VALUES ('doc-09-mitre-attack-p0-621', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-17T11:31:38.677Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Ransomware](https://attack.mitre.org/software/S1244) has been utilized in attacks since at least 2021. [Medusa Ransomware](https://attack.mitre.org/software/S1244) has been known to be utilized in conjunction with living off the land techniques and remote management software. [Medusa Ransomware](https://attack.mitre.org/software/S1244) has been used in campaigns associated with “double extortion” ransomware activity, where data is exfiltrated from victim environments prior to encryption, with threats to publish files if a ransom is not paid. [Medusa Ransomware](https://attack.mitre.org/software/S1244) software was initially a closed ransomware variant which later evolved to a Ransomware as a Service (RaaS). [Medusa Ransomware](https://attack.mitre.org/software/S1244) has impacted victims from a diverse range of sectors within a multitude of countries, and it is assessed [Medusa Ransomware](https://attack.mitre.org/software/S1244) is used in an opportunistic manner.(Citation: CISA Medusa Group Medusa Ransomware March 2025)(Citation: Security Scorecard Medusa Ransomware January 2024)(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)(Citation: Broadcom Medusa Ransomware Medusa Group March 2025)", "external_references": [{"external_id": "S1244", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1244"}, {"description": "Anthony Galiette, Doel Santos. (2024, January 11). Medusa Ransomware Turning Your Files into Stone. Retrieved October 15, 2025.", "source_name": "Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024", "url": "https://unit42.paloaltonetworks.com/medusa-ransomware-escalation-new-leak-site/"}, {"description": "Cybersecurity and Infrastructure Security Agency. (2025, March 12). AA25-071A #StopRansomware: Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "CISA Medusa Group Medusa Ransomware March 2025", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-071a"}, {"description": "Threat Hunter Team Symantec and Carbon Black. (2025, March 6). Medusa Ransomware Activity Continues to Increase. Retrieved October 15, 2025.", "source_name": "Broadcom Medusa Ransomware Medusa Group March 2025", "url": "https://www.security.com/threat-intelligence/medusa-ransomware-attacks"}, {"description": "Vlad Pasca. (2024, January 1). A Deep Dive into Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "Security Scorecard Medusa Ransomware January 2024", "url": "https://securityscorecard.com/wp-content/uploads/2024/01/deep-dive-into-medusa-ransomware.pdf"}], "id": "malware--28d93902-30e7-4436-8885-6d312c51c9a3", "is_family": true, "modified": "2025-10-21T14:58:41.162Z", "name": "Medusa Ransomware", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Medusa Ransomware"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-621', 0, 299, '09-mitre-attack', 'retrieved', '784E58CD31EFE154115022B5F4860206196EA05F5DC31974F810D863FD813EBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
