VALUES ('doc-09-mitre-attack-p0-622', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-29T14:46:45.468Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RainyDay](https://attack.mitre.org/software/S0629) is a backdoor tool that has been used by [Naikon](https://attack.mitre.org/groups/G0019) since at least 2020.(Citation: Bitdefender Naikon April 2021)", "external_references": [{"external_id": "S0629", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0629"}, {"description": "Vrabie, V. (2021, April 23). NAIKON – Traces from a Military Cyber-Espionage Operation. Retrieved June 29, 2021.", "source_name": "Bitdefender Naikon April 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/396/Bitdefender-PR-Whitepaper-NAIKON-creat5397-en-EN.pdf"}], "id": "malware--29231689-5837-4a7a-aafc-1b65b3f50cc7", "is_family": true, "modified": "2024-04-11T00:22:35.591Z", "name": "RainyDay", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RainyDay"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-622', 0, 86, '09-mitre-attack', 'retrieved', '77CD49E35681DAD3B22A56C24005F687A643BF43218F1B72D2A37C58993F0A5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
