VALUES ('doc-09-mitre-attack-p0-623', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T18:56:41.244Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ecipekac](https://attack.mitre.org/software/S0624) is a multi-layer loader that has been used by [menuPass](https://attack.mitre.org/groups/G0045) since at least 2019 including use as a loader for [P8RAT](https://attack.mitre.org/software/S0626), [SodaMaster](https://attack.mitre.org/software/S0627), and [FYAnti](https://attack.mitre.org/software/S0628).(Citation: Securelist APT10 March 2021)", "external_references": [{"external_id": "S0624", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0624"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "HEAVYHAND"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "SigLoader"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "DESLoader"}, {"description": "GREAT. (2021, March 30). APT10: sophisticated multi-layered loader Ecipekac discovered in A41APT campaign. Retrieved June 17, 2021.", "source_name": "Securelist APT10 March 2021", "url": "https://securelist.com/apt10-sophisticated-multi-layered-loader-ecipekac-discovered-in-a41apt-campaign/101519/"}], "id": "malware--292eb0c5-b8e8-4af6-9e8f-0fda6b4528d3", "is_family": true, "modified": "2025-04-25T14:42:53.604Z", "name": "Ecipekac", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ecipekac", "HEAVYHAND", "SigLoader", "DESLoader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-623', 0, 121, '09-mitre-attack', 'retrieved', 'DCCBF879A252523DD17E26B4D146896CFF1074DFA82A739D6F085F6C47F5C96D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
