VALUES ('doc-09-mitre-attack-p0-624', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-10T14:53:49.448Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AppleSeed](https://attack.mitre.org/software/S0622) is a backdoor that has been used by [Kimsuky](https://attack.mitre.org/groups/G0094) to target South Korean government, academic, and commercial targets since at least 2021.(Citation: Malwarebytes Kimsuky June 2021)", "external_references": [{"external_id": "S0622", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0622"}, {"description": "Jazi, H. (2021, June 1). Kimsuky APT continues to target South Korean government using AppleSeed backdoor. Retrieved June 10, 2021.", "source_name": "Malwarebytes Kimsuky June 2021", "url": "https://blog.malwarebytes.com/threat-analysis/2021/06/kimsuky-apt-continues-to-target-south-korean-government-using-appleseed-backdoor/"}], "id": "malware--295721d2-ee20-4fa3-ade3-37f4146b4570", "is_family": true, "modified": "2025-04-25T14:42:53.967Z", "name": "AppleSeed", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AppleSeed"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Android"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-624', 0, 96, '09-mitre-attack', 'retrieved', '072BD8696889901189A76A9D2E4962C2263A5A3A57CC8EB2AB44DA8C26D9D336', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
