VALUES ('doc-09-mitre-attack-p0-625', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-07T20:16:36.898Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BUSHWALK](https://attack.mitre.org/software/S1118) is a web shell written in Perl that was inserted into the legitimate querymanifest.cgi file on compromised Ivanti Connect Secure VPNs during [Cutting Edge](https://attack.mitre.org/campaigns/C0029).(Citation: Mandiant Cutting Edge Part 2 January 2024)(Citation: Mandiant Cutting Edge Part 3 February 2024)", "external_references": [{"external_id": "S1118", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1118"}, {"description": "Lin, M. et al. (2024, February 27). Cutting Edge, Part 3: Investigating Ivanti Connect Secure VPN Exploitation and Persistence Attempts. Retrieved March 1, 2024.", "source_name": "Mandiant Cutting Edge Part 3 February 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-exploitation-persistence"}, {"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}], "id": "malware--29a0bb87-1162-4c83-9834-2a98a876051b", "is_family": true, "modified": "2025-04-15T19:46:33.793Z", "name": "BUSHWALK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BUSHWALK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-625', 0, 150, '09-mitre-attack', 'retrieved', 'E475717364E4A7DF822121AB74F2B637851CF5FF3ABEEB16BA1AB5CCB30745EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
