VALUES ('doc-09-mitre-attack-p0-627', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:33.348Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LOWBALL](https://attack.mitre.org/software/S0042) is malware used by [admin@338](https://attack.mitre.org/groups/G0018). It was used in August 2015 in email messages targeting Hong Kong-based media organizations. (Citation: FireEye admin@338)", "external_references": [{"external_id": "S0042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0042"}, {"description": "FireEye Threat Intelligence. (2015, December 1). China-based Cyber Threat Group Uses Dropbox for Malware Communications and Targets Hong Kong Media Outlets. Retrieved December 4, 2015.", "source_name": "FireEye admin@338", "url": "https://www.fireeye.com/blog/threat-research/2015/11/china-based-threat.html"}], "id": "malware--2a6f4c7b-e690-4cc7-ab6b-1f821fb6b80b", "is_family": true, "modified": "2025-04-25T14:42:54.704Z", "name": "LOWBALL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LOWBALL"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-627', 0, 94, '09-mitre-attack', 'retrieved', '0CD76D899CC86FD8AD1CFC05FAA270B7D21D8337E086B205BA13DDE4710E24E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
