VALUES ('doc-09-mitre-attack-p0-628', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NETWIRE](https://attack.mitre.org/software/S0198) is a publicly available, multiplatform remote administration tool (RAT) that has been used by criminal and APT groups since at least 2012.(Citation: FireEye APT33 Sept 2017)(Citation: McAfee Netwire Mar 2015)(Citation: FireEye APT33 Webinar Sept 2017)", "external_references": [{"external_id": "S0198", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0198"}, {"description": "(Citation: FireEye APT33 Sept 2017) (Citation: FireEye APT33 Webinar Sept 2017) (Citation: McAfee Netwire Mar 2015)", "source_name": "NETWIRE"}, {"description": "Davis, S. and Carr, N. (2017, September 21). APT33: New Insights into Iranian Cyber Espionage Group. Retrieved February 15, 2018.", "source_name": "FireEye APT33 Webinar Sept 2017", "url": "https://www.brighttalk.com/webcast/10703/275683"}, {"description": "McAfee. (2015, March 2). Netwire RAT Behind Recent Targeted Attacks. Retrieved February 15, 2018.", "source_name": "McAfee Netwire Mar 2015", "url": "https://securingtomorrow.mcafee.com/mcafee-labs/netwire-rat-behind-recent-targeted-attacks/"}, {"description": "O''Leary, J., et al. (2017, September 20). Insights into Iranian Cyber Espionage: APT33 Targets Aerospace and Energy Sectors and has Ties to Destructive Malware. Retrieved February 15, 2018.", "source_name": "FireEye APT33 Sept 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/09/apt33-insights-into-iranian-cyber-espionage.html"}], "id": "malware--2a70812b-f1ef-44db-8578-a496a227aef2", "is_family": true, "modified": "2025-04-16T20:38:00.152Z", "name": "NETWIRE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NETWIRE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Tony Lambert, Red Canary"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux", "macOS"], "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-628', 0, 191, '09-mitre-attack', 'retrieved', 'C8C46BEBF0F75886040E6280C430C70B6A1D1D8DF348A5D0C510C32300C9434B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
