VALUES ('doc-09-mitre-attack-p0-629', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-02T15:09:20.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TinyTurla](https://attack.mitre.org/software/S0668) is a backdoor that has been used by [Turla](https://attack.mitre.org/groups/G0010) against targets in the US, Germany, and Afghanistan since at least 2020.(Citation: Talos TinyTurla September 2021)", "external_references": [{"external_id": "S0668", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0668"}, {"description": "Cisco Talos. (2021, September 21). TinyTurla - Turla deploys new malware to keep a secret backdoor on victim machines. Retrieved December 2, 2021.", "source_name": "Talos TinyTurla September 2021", "url": "https://blog.talosintelligence.com/2021/09/tinyturla.html"}], "id": "malware--2a7c1bb7-cd12-456e-810d-ab3bf8457bab", "is_family": true, "modified": "2025-04-16T20:38:00.312Z", "name": "TinyTurla", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TinyTurla"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Kyaw Pyiyt Htet, @KyawPyiytHtet", "Massimiliano Romano, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-629', 0, 108, '09-mitre-attack', 'retrieved', '539393F79BFCC869D02F33C95BDBA555DCF39B9874865C1D647B9B8598CA665A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
