VALUES ('doc-09-mitre-attack-p0-630', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-11T22:00:20.194Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PyDCrypt](https://attack.mitre.org/software/S1032) is malware written in Python designed to deliver [DCSrv](https://attack.mitre.org/software/S1033). It has been used by [Moses Staff](https://attack.mitre.org/groups/G1009) since at least September 2021, with each sample tailored for its intended victim organization.(Citation: Checkpoint MosesStaff Nov 2021)", "external_references": [{"external_id": "S1032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1032"}, {"description": "Checkpoint Research. (2021, November 15). Uncovering MosesStaff techniques: Ideology over Money. Retrieved August 11, 2022.", "source_name": "Checkpoint MosesStaff Nov 2021", "url": "https://research.checkpoint.com/2021/mosesstaff-targeting-israeli-companies/"}], "id": "malware--2ac41e8b-4865-4ced-839d-78e7852c47f3", "is_family": true, "modified": "2024-04-11T00:23:58.415Z", "name": "PyDCrypt", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PyDCrypt"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-630', 0, 115, '09-mitre-attack', 'retrieved', 'D16165D07F61B3D26FA259169615A3605EE53F58F20E8B25ED3190C136153DF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
