VALUES ('doc-09-mitre-attack-p0-632', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-27T19:36:32.094Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerExchange](https://attack.mitre.org/software/S1173) is a PowerShell backdoor that has been used by [OilRig](https://attack.mitre.org/groups/G0049) since at least 2023 including against government targets in the Middle East.(Citation: Symantec Crambus OCT 2023)", "external_references": [{"external_id": "S1173", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1173"}, {"description": "Symantec Threat Hunter Team. (2023, October 19). Crambus: New Campaign Targets Middle Eastern Government. Retrieved November 27, 2024.", "source_name": "Symantec Crambus OCT 2023", "url": "https://www.security.com/threat-intelligence/crambus-middle-east-government"}], "id": "malware--2c9d23e7-bfd6-4e23-a512-aee3bc1474f4", "is_family": true, "modified": "2024-11-27T19:38:21.789Z", "name": "PowerExchange", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PowerExchange"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-632', 0, 95, '09-mitre-attack', 'retrieved', 'B9C8A9976B9B59FCEC0B332F91584BD05F4C5C2BF0CDB30A322B72EF2014E7A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
