VALUES ('doc-09-mitre-attack-p0-634', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-02T20:48:23.462Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HyperStack](https://attack.mitre.org/software/S0537) is a RPC-based backdoor used by [Turla](https://attack.mitre.org/groups/G0010) since at least 2018. [HyperStack](https://attack.mitre.org/software/S0537) has similarities to other backdoors used by [Turla](https://attack.mitre.org/groups/G0010) including [Carbon](https://attack.mitre.org/software/S0335).(Citation: Accenture HyperStack October 2020)", "external_references": [{"external_id": "S0537", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0537"}, {"description": "Accenture. (2020, October). Turla uses HyperStack, Carbon, and Kazuar to compromise government entity. Retrieved December 2, 2020.", "source_name": "Accenture HyperStack October 2020", "url": "https://web.archive.org/web/20201101015247/https://www.accenture.com/us-en/blogs/cyber-defense/turla-belugasturgeon-compromises-government-entity"}], "id": "malware--2cf7dec3-66fc-423f-b2c7-58f1de243b4e", "is_family": true, "modified": "2026-01-20T15:11:37.735Z", "name": "HyperStack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HyperStack"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-634', 0, 94, '09-mitre-attack', 'retrieved', '11CBEDE43F16EFF7EC6DB585DC64951CD66137C354DD724AA36A7ADA560126E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
