VALUES ('doc-09-mitre-attack-p0-636', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:29.203Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HAMMERTOSS](https://attack.mitre.org/software/S0037) is a backdoor that was used by [APT29](https://attack.mitre.org/groups/G0016) in 2015. (Citation: FireEye APT29) (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0037"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}, {"description": "FireEye Labs. (2015, July). HAMMERTOSS: Stealthy Tactics Define a Russian Cyber Threat Group. Retrieved November 17, 2024.", "source_name": "FireEye APT29", "url": "https://services.google.com/fh/files/misc/rpt-apt29-hammertoss-stealthy-tactics-define-en.pdf"}], "id": "malware--2daa14d6-cbf3-4308-bb8e-213c324a08e4", "is_family": true, "modified": "2024-11-17T14:55:19.537Z", "name": "HAMMERTOSS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HAMMERTOSS", "HammerDuke", "NetDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-636', 0, 108, '09-mitre-attack', 'retrieved', '3B4ADAB5D7F121B836A3DBDD433D999AEE5DC32DD6944889C50D523246F0E410', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
