VALUES ('doc-09-mitre-attack-p0-637', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:18.946Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OLDBAIT](https://attack.mitre.org/software/S0138) is a credential harvester used by [APT28](https://attack.mitre.org/groups/G0007). (Citation: FireEye APT28) (Citation: FireEye APT28 January 2017)", "external_references": [{"external_id": "S0138", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0138"}, {"description": "FireEye iSIGHT Intelligence. (2017, January 11). APT28: At the Center of the Storm. Retrieved November 17, 2024.", "source_name": "FireEye APT28 January 2017", "url": "https://www.mandiant.com/sites/default/files/2021-09/APT28-Center-of-Storm-2017.pdf"}, {"description": "FireEye. (2015). APT28: A WINDOW INTO RUSSIA’S CYBER ESPIONAGE OPERATIONS?. Retrieved August 19, 2015.", "source_name": "FireEye APT28", "url": "https://web.archive.org/web/20151022204649/https://www.fireeye.com/content/dam/fireeye-www/global/en/current-threats/pdfs/rpt-apt28.pdf"}], "id": "malware--2dd34b01-6110-4aac-835d-b5e7b936b0be", "is_family": true, "modified": "2024-11-17T14:43:38.590Z", "name": "OLDBAIT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OLDBAIT", "Sasfis"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-637', 0, 104, '09-mitre-attack', 'retrieved', '0862EF3682605A9DA71444238F59591124D141C3974BA8CA15DB7EB3E66FC0E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
