VALUES ('doc-09-mitre-attack-p0-638', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-09T14:35:39.455Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bad Rabbit](https://attack.mitre.org/software/S0606) is a self-propagating ransomware that affected the Ukrainian transportation sector in 2017. [Bad Rabbit](https://attack.mitre.org/software/S0606) has also targeted organizations and consumers in Russia. (Citation: Secure List Bad Rabbit)(Citation: ESET Bad Rabbit)(Citation: Dragos Apr 2019)", "external_references": [{"external_id": "S0606", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0606"}, {"description": "Joe Slowik. (2019, April 10). Implications of IT Ransomware for ICS Environments. Retrieved October 27, 2019.", "source_name": "Dragos Apr 2019", "url": "https://dragos.com/blog/industry-news/implications-of-it-ransomware-for-ics-environments/"}, {"description": "M.Léveille, M-E.. (2017, October 24). Bad Rabbit: Not‑Petya is back with improved ransomware. Retrieved January 28, 2021.", "source_name": "ESET Bad Rabbit", "url": "https://www.welivesecurity.com/2017/10/24/bad-rabbit-not-petya-back/"}, {"description": "Mamedov, O. Sinitsyn, F. Ivanov, A.. (2017, October 24). Bad Rabbit ransomware. Retrieved January 28, 2021.", "source_name": "Secure List Bad Rabbit", "url": "https://securelist.com/bad-rabbit-ransomware/82851/"}], "id": "malware--2eaa5319-5e1e-4dd7-bbc4-566fced3964a", "is_family": true, "modified": "2025-01-02T19:45:31.402Z", "name": "Bad Rabbit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bad Rabbit", "Win32/Diskcoder.D"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-638', 0, 152, '09-mitre-attack', 'retrieved', '5D93C1F2EEB618A494837E7C5A018C312D40103968E70033FE6086BAF9345B42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
