VALUES ('doc-09-mitre-attack-p0-639', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:36.550Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CosmicDuke](https://attack.mitre.org/software/S0050) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2010 to 2015. (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0050", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0050"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--2eb9b131-d333-4a48-9eb4-d8dec46c19ee", "is_family": true, "modified": "2025-04-25T14:42:57.253Z", "name": "CosmicDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CosmicDuke", "TinyBaron", "BotgenStudios", "NemesisGemina"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-639', 0, 82, '09-mitre-attack', 'retrieved', '4EFC456122C26F4B3DF18AA5D272D73A01016FF37911E3400C0BE49953CD4F11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
