VALUES ('doc-09-mitre-attack-p0-642', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T16:54:17.773Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MirrorStealer](https://attack.mitre.org/software/S9022) is a credential stealer that has been used by [MirrorFace](https://attack.mitre.org/groups/G1054) since at least 2022 to steal credentials from various applications, including browsers and email clients. [MirrorStealer](https://attack.mitre.org/software/S9022) has been delivered directly into system memory via commands issued by [LODEINFO](https://attack.mitre.org/software/S9020).(Citation: ESET MirrorFace DEC 2022)", "external_references": [{"external_id": "S9022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9022"}, {"description": "Breitenbacher, D. (2022, December 14). Unmasking MirrorFace: Operation LiberalFace targeting Japanese political entities. Retrieved April 17, 2026.", "source_name": "ESET MirrorFace DEC 2022", "url": "https://www.welivesecurity.com/2022/12/14/unmasking-mirrorface-operation-liberalface-targeting-japanese-political-entities/"}], "id": "malware--2f851d4a-18cc-4d7f-9408-b10ef02ee936", "is_family": true, "modified": "2026-04-24T02:32:16.653Z", "name": "MirrorStealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MirrorStealer"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-642', 0, 114, '09-mitre-attack', 'retrieved', 'D206DC6900FA8073CAF0BDC8D5FB1D2ED7AEDA535D2A3089FE5B0C780560CE39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
