VALUES ('doc-09-mitre-attack-p0-643', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:39.606Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SslMM](https://attack.mitre.org/software/S0058) is a full-featured backdoor used by [Naikon](https://attack.mitre.org/groups/G0019) that has multiple variants. (Citation: Baumgartner Naikon 2015)", "external_references": [{"external_id": "S0058", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0058"}, {"description": "Baumgartner, K., Golovkin, M.. (2015, May). The MsnMM Campaigns: The Earliest Naikon APT Campaigns. Retrieved April 10, 2019.", "source_name": "Baumgartner Naikon 2015", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07205555/TheNaikonAPT-MsnMM1.pdf"}], "id": "malware--2fb26586-2b53-4b9a-ad4f-2b3bcb9a2421", "is_family": true, "modified": "2025-04-25T14:42:57.989Z", "name": "SslMM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SslMM"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-643', 0, 81, '09-mitre-attack', 'retrieved', 'D1DBAB44DF24A5012A2434C114AEB9C962848C797C6C4949F948F4A735969E98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
