VALUES ('doc-09-mitre-attack-p0-645', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-14T22:12:17.650Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IMAPLoader](https://attack.mitre.org/software/S1152) is a .NET-based loader malware exclusively associated with [CURIUM](https://attack.mitre.org/groups/G1012) operations since at least 2022. [IMAPLoader](https://attack.mitre.org/software/S1152) leverages email protocols for command and control and payload delivery.(Citation: PWC Yellow Liderc 2023)", "external_references": [{"external_id": "S1152", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1152"}, {"description": "PwC Threat Intelligence. (2023, October 25). Yellow Liderc ships its scripts and delivers IMAPLoader malware. Retrieved August 14, 2024.", "source_name": "PWC Yellow Liderc 2023", "url": "https://www.pwc.com/gx/en/issues/cybersecurity/cyber-threat-intelligence/yellow-liderc-ships-its-scripts-delivers-imaploader-malware.html"}], "id": "malware--3058b264-fe6b-46be-8948-2d1fadaf8adf", "is_family": true, "modified": "2024-10-02T12:20:43.866Z", "name": "IMAPLoader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["IMAPLoader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Wirapong Petshagun"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-645', 0, 102, '09-mitre-attack', 'retrieved', 'DC3EAF1840EC1D48383F3593B74FB4AE81DB565CD0F0D2DD14C456E0B1BDD1A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
