VALUES ('doc-09-mitre-attack-p0-646', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T13:53:14.264Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GreyEnergy](https://attack.mitre.org/software/S0342) is a backdoor written in C and compiled in Visual Studio. [GreyEnergy](https://attack.mitre.org/software/S0342) shares similarities with the [BlackEnergy](https://attack.mitre.org/software/S0089) malware and is thought to be the successor of it.(Citation: ESET GreyEnergy Oct 2018)", "external_references": [{"external_id": "S0342", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0342"}, {"description": "(Citation: ESET GreyEnergy Oct 2018)", "source_name": "GreyEnergy"}, {"description": "Cherepanov, A. (2018, October). GREYENERGY A successor to BlackEnergy. Retrieved November 15, 2018.", "source_name": "ESET GreyEnergy Oct 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/10/ESET_GreyEnergy.pdf"}], "id": "malware--308b3d68-a084-4dfb-885a-3125e1a9c1e8", "is_family": true, "modified": "2024-04-11T02:24:46.255Z", "name": "GreyEnergy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GreyEnergy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-646', 0, 103, '09-mitre-attack', 'retrieved', '61D7F915AD94B26C1C56BFEB0C99ECFCFF304B2F81F18D086B50DD1BA2E21A69', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
