VALUES ('doc-09-mitre-attack-p0-649', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-26T19:36:04.663Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Aria-body](https://attack.mitre.org/software/S0456) is a custom backdoor that has been used by [Naikon](https://attack.mitre.org/groups/G0019) since approximately 2017.(Citation: CheckPoint Naikon May 2020)", "external_references": [{"external_id": "S0456", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0456"}, {"description": "CheckPoint. (2020, May 7). Naikon APT: Cyber Espionage Reloaded. Retrieved May 26, 2020.", "source_name": "CheckPoint Naikon May 2020", "url": "https://research.checkpoint.com/2020/naikon-apt-cyber-espionage-reloaded/"}], "id": "malware--3161d76a-e2b2-4b97-9906-24909b735386", "is_family": true, "modified": "2025-10-22T02:32:48.657Z", "name": "Aria-body", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Aria-body"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-649', 0, 81, '09-mitre-attack', 'retrieved', 'B27773A2FF983B6CB29C848EC23D332B2DB377A8D76334C73C05269716810B73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
