VALUES ('doc-09-mitre-attack-p0-653', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T22:33:05.594Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOLDMOVE](https://attack.mitre.org/software/S1184) is a type of backdoor malware written in C linked to People’s Republic of China operations from 2022 through 2023. [BOLDMOVE](https://attack.mitre.org/software/S1184) includes both Windows and Linux variants, with some Linux variants specifically designed for FortiGate Firewall devices. [BOLDMOVE](https://attack.mitre.org/software/S1184) is linked to zero-day exploitation of CVE-2022-42475 in FortiOSS SSL-VPNs.(Citation: Google Cloud BOLDMOVE 2023) The record for [BOLDMOVE](https://attack.mitre.org/software/S1184) only covers known Linux variants.", "external_references": [{"external_id": "S1184", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1184"}, {"description": "Scott Henderson, Cristiana Kittner, Sarah Hawley & Mark Lechtik, Google Cloud. (2023, January 19). Suspected Chinese Threat Actors Exploiting FortiOS Vulnerability (CVE-2022-42475). Retrieved December 31, 2024.", "source_name": "Google Cloud BOLDMOVE 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/chinese-actors-exploit-fortios-flaw/"}], "id": "malware--325fa466-4a2a-45a0-acc6-f6bed9b45ebe", "is_family": true, "modified": "2025-04-15T19:46:33.956Z", "name": "BOLDMOVE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BOLDMOVE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-653', 0, 140, '09-mitre-attack', 'retrieved', '09C19196E89EF94348D6319173661CABAF7F661C30479428A002D1419FEB6A71', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
