VALUES ('doc-09-mitre-attack-p0-654', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:08.679Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Crimson](https://attack.mitre.org/software/S0115) is a remote access Trojan that has been used by [Transparent Tribe](https://attack.mitre.org/groups/G0134) since at least 2016.(Citation: Proofpoint Operation Transparent Tribe March 2016)(Citation: Kaspersky Transparent Tribe August 2020)", "external_references": [{"external_id": "S0115", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0115"}, {"description": "(Citation: Proofpoint Operation Transparent Tribe March 2016)", "source_name": "MSIL/Crimson"}, {"description": "Dedola, G. (2020, August 20). Transparent Tribe: Evolution analysis, part 1. Retrieved September 2, 2021.", "source_name": "Kaspersky Transparent Tribe August 2020", "url": "https://securelist.com/transparent-tribe-part-1/98127/"}, {"description": "Huss, D. (2016, March 1). Operation Transparent Tribe. Retrieved June 8, 2016.", "source_name": "Proofpoint Operation Transparent Tribe March 2016", "url": "https://www.proofpoint.com/sites/default/files/proofpoint-operation-transparent-tribe-threat-insight-en.pdf"}], "id": "malware--326af1cd-78e7-45b7-a326-125d2f7ef8f2", "is_family": true, "modified": "2025-04-16T20:38:01.622Z", "name": "Crimson", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Crimson", "MSIL/Crimson"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-654', 0, 127, '09-mitre-attack', 'retrieved', '8436B077DEBADF4A339779D7594286857503D92E499C496987CFBAB319BC5191', 'v1'