VALUES ('doc-09-mitre-attack-p0-655', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-29T14:47:19.862Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tomiris](https://attack.mitre.org/software/S0671) is a backdoor written in Go that continuously queries its C2 server for executables to download and execute on a victim system. It was first reported in September 2021 during an investigation of a successful DNS hijacking campaign against a Commonwealth of Independent States (CIS) member. Security researchers assess there are similarities between [Tomiris](https://attack.mitre.org/software/S0671) and [GoldMax](https://attack.mitre.org/software/S0588).(Citation: Kaspersky Tomiris Sep 2021)", "external_references": [{"external_id": "S0671", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0671"}, {"description": "Kwiatkoswki, I. and Delcher, P. (2021, September 29). DarkHalo After SolarWinds: the Tomiris connection. Retrieved December 27, 2021.", "source_name": "Kaspersky Tomiris Sep 2021", "url": "https://securelist.com/darkhalo-after-solarwinds-the-tomiris-connection/104311/"}], "id": "malware--327b3a25-9e60-4431-b3b6-93b9c64eacbc", "is_family": true, "modified": "2025-04-16T20:38:01.801Z", "name": "Tomiris", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Tomiris"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Craig Smith, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-655', 0, 132, '09-mitre-attack', 'retrieved', '5ED1167588230C5FE9F1EEB89B3F2DAC98694BBF7041FF9A51BAF73E25C060CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
