VALUES ('doc-09-mitre-attack-p0-657', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-16T08:38:41.404Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DUSTTRAP](https://attack.mitre.org/software/S1159) is a multi-stage plugin framework associated with [APT41](https://attack.mitre.org/groups/G0096) operations with multiple components.(Citation: Google Cloud APT41 2024)", "external_references": [{"external_id": "S1159", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1159"}, {"description": "Mike Stokkel et al. (2024, July 18). APT41 Has Arisen From the DUST. Retrieved September 16, 2024.", "source_name": "Google Cloud APT41 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/apt41-arisen-from-dust"}], "id": "malware--33139388-de0c-49ff-862a-041c315b142d", "is_family": true, "modified": "2024-09-21T07:20:52.417Z", "name": "DUSTTRAP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DUSTTRAP"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-657', 0, 84, '09-mitre-attack', 'retrieved', '38BDFF846C634393B24C06999A797F947206D89188E45920603A72D815ADAF61', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
