VALUES ('doc-09-mitre-attack-p0-659', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-21T15:21:31.795Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Turian](https://attack.mitre.org/software/S0647) is a backdoor that has been used by [BackdoorDiplomacy](https://attack.mitre.org/groups/G0135) to target Ministries of Foreign Affairs, telecommunication companies, and charities in Africa, Europe, the Middle East, and Asia. First reported in 2021, [Turian](https://attack.mitre.org/software/S0647) is likely related to Quarian, an older backdoor that was last observed being used in 2013 against diplomatic targets in Syria and the United States.(Citation: ESET BackdoorDiplomacy Jun 2021)", "external_references": [{"external_id": "S0647", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0647"}, {"description": "Adam Burgher. (2021, June 10). BackdoorDiplomacy: Upgrading from Quarian to Turian. Retrieved September 1, 2021", "source_name": "ESET BackdoorDiplomacy Jun 2021", "url": "https://www.welivesecurity.com/2021/06/10/backdoordiplomacy-upgrading-quarian-turian/"}], "id": "malware--350f12cf-fd3b-4dad-b323-14b943090df4", "is_family": true, "modified": "2025-04-25T14:43:01.037Z", "name": "Turian", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Turian"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Zaw Min Htun, @Z3TAE"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-659', 0, 131, '09-mitre-attack', 'retrieved', 'C007C29145A5B7B0E0BB1AA477526FAC122FE0BCC704A68D21F38675F8D5E0CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
