VALUES ('doc-09-mitre-attack-p0-660', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-16T19:30:05.694Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[THINCRUST](https://attack.mitre.org/software/S1223) is a Python-based backdoor tool that has been used by [UNC3886](https://attack.mitre.org/groups/G1048) since at least 2023.(Citation: Mandiant Fortinet Zero Day)", "external_references": [{"external_id": "S1223", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1223"}, {"description": "Marvi, A. et al.. (2023, March 16). Fortinet Zero-Day and Custom Malware Used by Suspected Chinese Actor in Espionage Operation. Retrieved March 22, 2023.", "source_name": "Mandiant Fortinet Zero Day", "url": "https://www.mandiant.com/resources/blog/fortinet-malware-ecosystem"}], "id": "malware--351b63d3-7b2c-4ede-b3fe-ff291527b397", "is_family": true, "modified": "2025-06-16T19:32:23.545Z", "name": "THINCRUST", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["THINCRUST"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-660', 0, 95, '09-mitre-attack', 'retrieved', '8282DD7A9AD1055B9C95664009890A00BD6B204BC8812B1AA0A5603923E55B76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
