VALUES ('doc-09-mitre-attack-p0-661', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-01T18:07:26.353Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BADHATCH](https://attack.mitre.org/software/S1081) is a backdoor that has been utilized by [FIN8](https://attack.mitre.org/groups/G0061) since at least 2019. [BADHATCH](https://attack.mitre.org/software/S1081) has been used to target the insurance, retail, technology, and chemical industries in the United States, Canada, South Africa, Panama, and Italy.(Citation: Gigamon BADHATCH Jul 2019)(Citation: BitDefender BADHATCH Mar 2021)", "external_references": [{"external_id": "S1081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1081"}, {"description": "Savelesky, K., et al. (2019, July 23). ABADBABE 8BADFOOD: Discovering BADHATCH and a Detailed Look at FIN8''s Tooling. Retrieved September 8, 2021.", "source_name": "Gigamon BADHATCH Jul 2019", "url": "https://blog.gigamon.com/2019/07/23/abadbabe-8badf00d-discovering-badhatch-and-a-detailed-look-at-fin8s-tooling/"}, {"description": "Vrabie, V., et al. (2021, March 10). FIN8 Returns with Improved BADHATCH Toolkit. Retrieved September 8, 2021.", "source_name": "BitDefender BADHATCH Mar 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/394/Bitdefender-PR-Whitepaper-BADHATCH-creat5237-en-EN.pdf"}], "id": "malware--3553b49d-d4ae-4fb6-ab17-0adbc520c888", "is_family": true, "modified": "2024-04-11T02:55:51.310Z", "name": "BADHATCH", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BADHATCH"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Serhii Melnyk, Trustwave SpiderLabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-661', 0, 147, '09-mitre-attack', 'retrieved', 'D267967B79F4AC9DE6BAD0F09240156D05B42BD7BAEE22F08BB7A6E7FB9F5A7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
