VALUES ('doc-09-mitre-attack-p0-662', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-13T13:17:25.718Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Machete](https://attack.mitre.org/software/S0409) is a cyber espionage toolset used by [Machete](https://attack.mitre.org/groups/G0095). It is a Python-based backdoor targeting Windows machines that was first observed in 2010.(Citation: ESET Machete July 2019)(Citation: Securelist Machete Aug 2014)(Citation: 360 Machete Sep 2020)", "external_references": [{"external_id": "S0409", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0409"}, {"description": "(Citation: 360 Machete Sep 2020)", "source_name": "Pyark"}, {"description": "(Citation: Securelist Machete Aug 2014)", "source_name": "Machete"}, {"description": "ESET. (2019, July). MACHETE JUST GOT SHARPER Venezuelan government institutions under attack. Retrieved September 13, 2019.", "source_name": "ESET Machete July 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/08/ESET_Machete.pdf"}, {"description": "Kaspersky Global Research and Analysis Team. (2014, August 20). El Machete. Retrieved September 13, 2019.", "source_name": "Securelist Machete Aug 2014", "url": "https://securelist.com/el-machete/66108/"}, {"description": "kate. (2020, September 25). APT-C-43 steals Venezuelan military secrets to provide intelligence support for the reactionaries — HpReact campaign. Retrieved November 20, 2020.", "source_name": "360 Machete Sep 2020", "url": "https://blog.360totalsecurity.com/en/apt-c-43-steals-venezuelan-military-secrets-to-provide-intelligence-support-for-the-reactionaries-hpreact-campaign/"}], "id": "malware--35cd1d01-1ede-44d2-b073-a264d727bc04", "is_family": true, "modified": "2025-06-06T14:13:34.557Z", "name": "Machete", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Machete", "Pyark"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Matias Nicolas Porolli, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-662', 0, 177, '09-mitre-attack', 'retrieved', '54436A708B0987C8AD10BBA1CC33063CB21F38F658FCBBAB74C21A6B59DC0871', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
