VALUES ('doc-09-mitre-attack-p0-663', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-01T20:20:02.166Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerLess](https://attack.mitre.org/software/S1012) is a PowerShell-based modular backdoor that has been used by [Magic Hound](https://attack.mitre.org/groups/G0059) since at least 2022.(Citation: Cybereason PowerLess February 2022)", "external_references": [{"external_id": "S1012", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1012"}, {"description": "Cybereason Nocturnus. (2022, February 1). PowerLess Trojan: Iranian APT Phosphorus Adds New PowerShell Backdoor for Espionage. Retrieved June 1, 2022.", "source_name": "Cybereason PowerLess February 2022", "url": "https://www.cybereason.com/blog/research/powerless-trojan-iranian-apt-phosphorus-adds-new-powershell-backdoor-for-espionage"}], "id": "malware--35ee9bf3-264b-4411-8a8f-b58cec8f35e4", "is_family": true, "modified": "2025-04-16T20:38:02.412Z", "name": "PowerLess", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PowerLess"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-663', 0, 91, '09-mitre-attack', 'retrieved', '79DE94166D59E3BDC386DC1FE0DBE401ADACD132F3648589339AF7873AF9577D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
