VALUES ('doc-09-mitre-attack-p0-665', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-11T15:24:48.709Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Avenger](https://attack.mitre.org/software/S0473) is a downloader that has been used by [BRONZE BUTLER](https://attack.mitre.org/groups/G0060) since at least 2019.(Citation: Trend Micro Tick November 2019)", "external_references": [{"external_id": "S0473", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0473"}, {"description": "Chen, J. et al. (2019, November). Operation ENDTRADE: TICK’s Multi-Stage Backdoors for Attacking Industries and Stealing Classified Data. Retrieved June 9, 2020.", "source_name": "Trend Micro Tick November 2019", "url": "https://documents.trendmicro.com/assets/pdf/Operation-ENDTRADE-TICK-s-Multi-Stage-Backdoors-for-Attacking-Industries-and-Stealing-Classified-Data.pdf"}], "id": "malware--36ede314-7db4-4d09-b53d-81bbfbe5f6f8", "is_family": true, "modified": "2025-10-22T03:24:56.552Z", "name": "Avenger", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Avenger"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-665', 0, 93, '09-mitre-attack', 'retrieved', '1CFA7467C1D6F600E136F565B5661F013DA92D5F8D6F9AE5E7CF4CF075B6A6C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
