VALUES ('doc-09-mitre-attack-p0-666', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-16T08:29:07.124Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DUSTPAN](https://attack.mitre.org/software/S1158) is an in-memory dropper written in C/C++ used by [APT41](https://attack.mitre.org/groups/G0096) since 2021 that decrypts and executes an embedded payload.(Citation: Google Cloud APT41 2024)(Citation: Google Cloud APT41 2022)", "external_references": [{"external_id": "S1158", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1158"}, {"description": "Mike Stokkel et al. (2024, July 18). APT41 Has Arisen From the DUST. Retrieved September 16, 2024.", "source_name": "Google Cloud APT41 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/apt41-arisen-from-dust"}, {"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman & John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved September 16, 2024.", "source_name": "Google Cloud APT41 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/apt41-us-state-governments"}], "id": "malware--37487ff6-de2a-4c14-9e8b-ba3b97f78aaf", "is_family": true, "modified": "2024-09-21T07:18:26.370Z", "name": "DUSTPAN", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DUSTPAN"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-666', 0, 133, '09-mitre-attack', 'retrieved', '3267B16D940EE3C1A0AF3285B630C2FD7211DCBBD825F15CE37699AD0EB9C32C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
