VALUES ('doc-09-mitre-attack-p0-667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:07.943Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Prikormka](https://attack.mitre.org/software/S0113) is a malware family used in a campaign known as Operation Groundbait. It has predominantly been observed in Ukraine and was used as early as 2008. (Citation: ESET Operation Groundbait)", "external_references": [{"external_id": "S0113", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0113"}, {"description": "Cherepanov, A.. (2016, May 17). Operation Groundbait: Analysis of a surveillance toolkit. Retrieved May 18, 2016.", "source_name": "ESET Operation Groundbait", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/05/Operation-Groundbait.pdf"}], "id": "malware--37cc7eb6-12e3-467b-82e8-f20f2cc73c69", "is_family": true, "modified": "2024-04-11T00:25:44.638Z", "name": "Prikormka", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Prikormka"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-667', 0, 96, '09-mitre-attack', 'retrieved', 'E9881F1576EDC91B34CB37751807C00F8F33DBB68B331879F9EDAC320215B164', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
