VALUES ('doc-09-mitre-attack-p0-669', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-15T22:33:21.950Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) is a malware family offered as a malware-as-a-service (MaaS) that is used to establish command and control and facilitate follow-on activity, including ransomware deployment.[SystemBC](https://attack.mitre.org/software/S9001) executes a variety of tasks including setting up SOCKS5 proxies, maintaining persistence, ingesting malicious files, and handing C2 communication. [SystemBC](https://attack.mitre.org/software/S9001) was first detected in 2018, and has been used by [Wizard Spider](https://attack.mitre.org/groups/G0102) since at least 2020, and by [FIN7](https://attack.mitre.org/groups/G0046) since at least 2022.(Citation: TrumanKroll_SYSTEMBCServer_Jan2024)(Citation: SophosGnGal_SystemBC_Dec2020)(Citation: BlackBasta)(Citation: AhnLab_SystemBC_Apr2022)(Citation: Lumen_SystemBC_Sept2025)", "external_references": [{"external_id": "S9001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9001"}, {"description": "(Citation: BlackBasta)(Citation: Broadcom_SystemBCCoroxy_Nov2023)(Citation: Microsoft_Coroxy_Oct2020) ", "source_name": "Coroxy"}, {"description": "AhnLab. (2022, April 4). SystemBC Being Used by Various Attackers . Retrieved June 18, 2025.", "source_name": "AhnLab_SystemBC_Apr2022", "url": "https://asec.ahnlab.com/en/33600/"}, {"description": "Antonio Cocomazzi and Antonio Pirozzi. (2022, November 3). Black Basta Ransomware | Attacks Deploy Custom EDR Evasion Tools Tied to FIN7 Threat Actor. Retrieved March 14, 2023.", "source_name": "BlackBasta", "url": "https://www.sentinelone.com/labs/black-basta-ransomware-attacks-deploy-custom-edr-evasion-tools-tied-to-fin7-threat-actor/"}, {"description": "Black Lotus Labs . (2025, September 18). SystemBC: Bringing the noise. Retrieved December 15, 2025.", "source_name": "Lumen_SystemBC_Sept2025", "url": "https://blog.lumen.com/systembc-bringing-the-noise/"}, {"description": "Broadcom. (2023, November 17). SystemBC (Coroxy) continuous activities. Retrieved December 15, 2025.", "source_name": "Broadcom_SystemBCCoroxy_Nov2023", "url": "https://www.broadcom.com/support/security-center/protection-bulletin/systembc-coroxy-continuous-activities"}, {"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}, {"description": "Microsoft Security Intelligence. (2020, October 30). Backdoor:Win32/Coroxy.A. Retrieved December 15, 2025.", "source_name": "Microsoft_Coroxy_Oct2020", "url": "https://www.microsoft.com/en-us/wdsi/threats/malware-encyclopedia-description?Name=Backdoor:Win32/Coroxy.A&ThreatID=2147766831"}, {"description": "Truman, D. (2024, January 19). Inside the SYSTEMBC Command-and-Control Server. Retrieved June 18, 2025.", "source_name": "TrumanKroll_SYSTEMBCServer_Jan2024", "url": "https://www.kroll.com/en/publications/cyber/inside-the-systembc-malware-server"}], "id": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "is_family": true, "modified": "2026-04-23T03:17:29.350Z", "name": "SystemBC", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SystemBC", "Coroxy"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Serhii Melnyk", "Stijn Geerts"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-669', 0, 279, '09-mitre-attack', 'retrieved', '74AF1476493E634EEB4F58DEFC3947B1E2D9355F15445D555A95DDBFF7257A45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
