VALUES ('doc-09-mitre-attack-p0-671', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-09T18:21:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PingPull](https://attack.mitre.org/software/S1031) is a remote access Trojan (RAT) written in Visual C++ that has been used by [GALLIUM](https://attack.mitre.org/groups/G0093) since at least June 2022. [PingPull](https://attack.mitre.org/software/S1031) has been used to target telecommunications companies, financial institutions, and government entities in Afghanistan, Australia, Belgium, Cambodia, Malaysia, Mozambique, the Philippines, Russia, and Vietnam.(Citation: Unit 42 PingPull Jun 2022)", "external_references": [{"external_id": "S1031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1031"}, {"description": "Unit 42. (2022, June 13). GALLIUM Expands Targeting Across Telecommunications, Government and Finance Sectors With New PingPull Tool. Retrieved August 7, 2022.", "source_name": "Unit 42 PingPull Jun 2022", "url": "https://unit42.paloaltonetworks.com/pingpull-gallium/"}], "id": "malware--3a0f6128-0a01-421d-8eca-e57d8671b1f1", "is_family": true, "modified": "2025-04-16T20:38:02.753Z", "name": "PingPull", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PingPull"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-671', 0, 140, '09-mitre-attack', 'retrieved', '947DEC727D0C0D4DE43F3FB65147E601944BF75E6D6E66B876E8AEE2EFBE34BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
