VALUES ('doc-09-mitre-attack-p0-672', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-24T19:39:44.392Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WellMess](https://attack.mitre.org/software/S0514) is lightweight malware family with variants written in .NET and Golang that has been in use since at least 2018 by [APT29](https://attack.mitre.org/groups/G0016).(Citation: CISA WellMess July 2020)(Citation: PWC WellMess July 2020)(Citation: NCSC APT29 July 2020)", "external_references": [{"external_id": "S0514", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0514"}, {"description": "CISA. (2020, July 16). MAR-10296782-2.v1 – WELLMESS. Retrieved September 24, 2020.", "source_name": "CISA WellMess July 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-198b"}, {"description": "PWC. (2020, July 16). How WellMess malware has been used to target COVID-19 vaccines. Retrieved September 24, 2020.", "source_name": "PWC WellMess July 2020", "url": "https://www.pwc.co.uk/issues/cyber-security-services/insights/cleaning-up-after-wellmess.html"}, {"description": "National Cyber Security Centre. (2020, July 16). Advisory: APT29 targets COVID-19 vaccine development. Retrieved September 29, 2020.", "source_name": "NCSC APT29 July 2020", "url": "https://www.ncsc.gov.uk/files/Advisory-APT29-targets-COVID-19-vaccine-development-V1-1.pdf"}], "id": "malware--3a4197ae-ec63-4162-907b-9a073d1157e4", "is_family": true, "modified": "2025-04-25T14:43:03.067Z", "name": "WellMess", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WellMess"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-672', 0, 150, '09-mitre-attack', 'retrieved', 'E5D08D4A0F372C1B2E8DB45501B1313B2B24E9CE149A515D734CDA4C5D396B11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
