VALUES ('doc-09-mitre-attack-p0-673', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-07T14:53:56.534Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dacls](https://attack.mitre.org/software/S0497) is a multi-platform remote access tool used by [Lazarus Group](https://attack.mitre.org/groups/G0032) since at least December 2019.(Citation: TrendMicro macOS Dacls May 2020)(Citation: SentinelOne Lazarus macOS July 2020)", "external_references": [{"external_id": "S0497", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0497"}, {"description": "Mabutas, G. (2020, May 11). New MacOS Dacls RAT Backdoor Shows Lazarus’ Multi-Platform Attack Capability. Retrieved August 10, 2020.", "source_name": "TrendMicro macOS Dacls May 2020", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/new-macos-dacls-rat-backdoor-show-lazarus-multi-platform-attack-capability/"}, {"description": "Stokes, P. (2020, July 27). Four Distinct Families of Lazarus Malware Target Apple’s macOS Platform. Retrieved August 7, 2020.", "source_name": "SentinelOne Lazarus macOS July 2020", "url": "https://www.sentinelone.com/blog/four-distinct-families-of-lazarus-malware-target-apples-macos-platform/"}], "id": "malware--3aa169f8-bbf6-44bb-b57d-7f6ada5c2128", "is_family": true, "modified": "2024-04-11T02:43:00.252Z", "name": "Dacls", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Dacls"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS", "Linux", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-673', 0, 126, '09-mitre-attack', 'retrieved', 'F62FBBEEA339A347C1758AFFD670451BB2645D6DAFB613D9E89CA4E045A00641', 'v1', '{