VALUES ('doc-09-mitre-attack-p0-675', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-14T16:52:39.925Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [Woody RAT](https://attack.mitre.org/software/S1065) is a remote access trojan (RAT) that has been used since at least August 2021 against Russian organizations.(Citation: MalwareBytes WoodyRAT Aug 2022)", "external_references": [{"external_id": "S1065", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1065"}, {"description": "MalwareBytes Threat Intelligence Team. (2022, August 3). Woody RAT: A new feature-rich malware spotted in the wild. Retrieved December 6, 2022.", "source_name": "MalwareBytes WoodyRAT Aug 2022", "url": "https://www.malwarebytes.com/blog/threat-intelligence/2022/08/woody-rat-a-new-feature-rich-malware-spotted-in-the-wild"}], "id": "malware--3bc7e862-5610-4c02-9c48-15b2e2dc1ddb", "is_family": true, "modified": "2025-10-21T03:29:54.769Z", "name": "Woody RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Woody RAT"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India", "Adam Lichters"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-675', 0, 115, '09-mitre-attack', 'retrieved', 'D1EA064282D19995A932BA47BF6E6C839CBFD90825AA3D1B50E4E17CD7E1A1A7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
