VALUES ('doc-09-mitre-attack-p0-676', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-26T01:21:43.409Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mafalda](https://attack.mitre.org/software/S1060) is a flexible interactive implant that has been used by [Metador](https://attack.mitre.org/groups/G1013). Security researchers assess the [Mafalda](https://attack.mitre.org/software/S1060) name may be inspired by an Argentinian cartoon character that has been popular as a means of political commentary since the 1960s. (Citation: SentinelLabs Metador Sept 2022)", "external_references": [{"external_id": "S1060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1060"}, {"description": "Ehrlich, A., et al. (2022, September). THE MYSTERY OF METADOR | AN UNATTRIBUTED THREAT HIDING IN TELCOS, ISPS, AND UNIVERSITIES. Retrieved January 23, 2023.", "source_name": "SentinelLabs Metador Sept 2022", "url": "https://assets.sentinelone.com/sentinellabs22/metador#page=1"}], "id": "malware--3be1fb7a-0f7e-415e-8e3a-74a80d596e68", "is_family": true, "modified": "2025-10-21T22:47:45.475Z", "name": "Mafalda", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mafalda"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Massimiliano Romano, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-676', 0, 123, '09-mitre-attack', 'retrieved', '5B53111EDB2131580BB07ADCAB37EEA868DBF7C76C7978CDF103C14596943E69', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
