VALUES ('doc-09-mitre-attack-p0-677', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KARAE](https://attack.mitre.org/software/S0215) is a backdoor typically used by [APT37](https://attack.mitre.org/groups/G0067) as first-stage malware. (Citation: FireEye APT37 Feb 2018)", "external_references": [{"external_id": "S0215", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0215"}, {"description": "(Citation: FireEye APT37 Feb 2018)", "source_name": "KARAE"}, {"description": "FireEye. (2018, February 20). APT37 (Reaper): The Overlooked North Korean Actor. Retrieved November 17, 2024.", "source_name": "FireEye APT37 Feb 2018", "url": "https://services.google.com/fh/files/misc/apt37-reaper-the-overlooked-north-korean-actor.pdf"}], "id": "malware--3c02fb1f-cbdb-48f5-abaf-8c81d6e0c322", "is_family": true, "modified": "2024-11-17T15:01:33.386Z", "name": "KARAE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KARAE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-677', 0, 89, '09-mitre-attack', 'retrieved', 'C112F138EF38B65E0F7D67D3F259DE91DF9DA887590E8AB66115F1E1DF69ABEA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
