VALUES ('doc-09-mitre-attack-p0-678', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-09T16:45:36.234Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Squirrelwaffle](https://attack.mitre.org/software/S1030) is a loader that was first seen in September 2021. It has been used in spam email campaigns to deliver additional malware such as [Cobalt Strike](https://attack.mitre.org/software/S0154) and the [QakBot](https://attack.mitre.org/software/S0650) banking trojan.(Citation: ZScaler Squirrelwaffle Sep 2021)(Citation: Netskope Squirrelwaffle Oct 2021)", "external_references": [{"external_id": "S1030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1030"}, {"description": "Kumar, A., Stone-Gross, Brett. (2021, September 28). Squirrelwaffle: New Loader Delivering Cobalt Strike. Retrieved August 9, 2022.", "source_name": "ZScaler Squirrelwaffle Sep 2021", "url": "https://www.zscaler.com/blogs/security-research/squirrelwaffle-new-loader-delivering-cobalt-strike"}, {"description": "Palazolo, G. (2021, October 7). SquirrelWaffle: New Malware Loader Delivering Cobalt Strike and QakBot. Retrieved August 9, 2022.", "source_name": "Netskope Squirrelwaffle Oct 2021", "url": "https://www.netskope.com/blog/squirrelwaffle-new-malware-loader-delivering-cobalt-strike-and-qakbot"}], "id": "malware--3c18ad16-9eaf-4649-984e-68551bff0d47", "is_family": true, "modified": "2024-04-11T00:02:15.805Z", "name": "Squirrelwaffle", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Squirrelwaffle"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Sebastian Showell-Westrip, BT Security", "Harry Hill, BT Security", "Catherine Williams, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-678', 0, 146, '09-mitre-attack', 'retrieved', 'F1DA3EC4E9DDFB1A3297540188D8C04989DB4DACA3F279347FAF07C36D275B5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
