VALUES ('doc-09-mitre-attack-p0-679', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:43.237Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ELMER](https://attack.mitre.org/software/S0064) is a non-persistent, proxy-aware HTTP backdoor written in Delphi that has been used by [APT16](https://attack.mitre.org/groups/G0023). (Citation: FireEye EPS Awakens Part 2)", "external_references": [{"external_id": "S0064", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0064"}, {"description": "Winters, R. (2015, December 20). The EPS Awakens - Part 2. Retrieved January 22, 2016.", "source_name": "FireEye EPS Awakens Part 2", "url": "https://web.archive.org/web/20151226205946/https://www.fireeye.com/blog/threat-research/2015/12/the-eps-awakens-part-two.html"}], "id": "malware--3cab1b76-2f40-4cd0-8d2c-7ed16eeb909c", "is_family": true, "modified": "2025-04-16T20:38:03.197Z", "name": "ELMER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ELMER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-679', 0, 88, '09-mitre-attack', 'retrieved', '2E851792ACD22F1AA59B724E39781DBAE7B447ADE111AE0D2AC10FD113D214A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
