VALUES ('doc-09-mitre-attack-p0-683', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A Linux rootkit that provides backdoor access and hides from defenders.", "external_references": [{"external_id": "S0221", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0221"}, {"description": "(Citation: Umbreon Trend Micro)", "source_name": "Umbreon"}, {"description": "Fernando Mercês. (2016, September 5). Pokémon-themed Umbreon Linux Rootkit Hits x86, ARM Systems. Retrieved March 5, 2018.", "source_name": "Umbreon Trend Micro", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/pokemon-themed-umbreon-linux-rootkit-hits-x86-arm-systems/?_ga=2.180041126.367598458.1505420282-1759340220.1502477046"}], "id": "malware--3d8e547d-9456-4f32-a895-dc86134e282f", "is_family": true, "modified": "2025-04-25T14:43:05.057Z", "name": "Umbreon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Umbreon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-683', 0, 82, '09-mitre-attack', 'retrieved', '43646BA8BA3953F301CF5A4C78EEFE05684613C35DA9F8F82EB4B4F127E5ADAE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
