VALUES ('doc-09-mitre-attack-p0-684', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-07T15:31:14.540Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AuTo Stealer](https://attack.mitre.org/software/S1029) is malware written in C++ has been used by [SideCopy](https://attack.mitre.org/groups/G1008) since at least December 2021 to target government agencies and personnel in India and Afghanistan.(Citation: MalwareBytes SideCopy Dec 2021)", "external_references": [{"external_id": "S1029", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1029"}, {"description": "Threat Intelligence Team. (2021, December 2). SideCopy APT: Connecting lures victims, payloads to infrastructure. Retrieved June 13, 2022.", "source_name": "MalwareBytes SideCopy Dec 2021", "url": "https://www.malwarebytes.com/blog/news/2021/12/sidecopy-apt-connecting-lures-to-victims-payloads-to-infrastructure"}], "id": "malware--3e4e2c79-2b27-4245-a5c1-5586a3cbd8f5", "is_family": true, "modified": "2025-04-16T20:38:03.701Z", "name": "AuTo Stealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AuTo Stealer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-684', 0, 101, '09-mitre-attack', 'retrieved', '2E7EEC16496DF487FAD67A4AA12889C00ECC2A80E10C159A495987674ADFFCF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
