VALUES ('doc-09-mitre-attack-p0-685', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-07T16:10:56.078Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShrinkLocker](https://attack.mitre.org/software/S1178) is a VBS-based malicious script that leverages the legitimate Bitlocker application to encrypt files on victim systems for ransom. [ShrinkLocker](https://attack.mitre.org/software/S1178) functions by using Bitlocker to encrypt files, then renames impacted drives to the adversary’s contact email address to facilitate communication for the ransom payment.(Citation: Kaspersky ShrinkLocker 2024)(Citation: Splunk ShrinkLocker 2024)", "external_references": [{"external_id": "S1178", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1178"}, {"description": "Cristian Souza, Eduardo Ovalle, Ashley Muñoz, & Christopher Zachor. (2024, May 23). ShrinkLocker: Turning BitLocker into ransomware. Retrieved December 7, 2024.", "source_name": "Kaspersky ShrinkLocker 2024", "url": "https://securelist.com/ransomware-abuses-bitlocker/112643/"}, {"description": "Splunk Threat Research Team , Teoderick Contreras. (2024, September 5). ShrinkLocker Malware: Abusing BitLocker to Lock Your Data. Retrieved December 7, 2024.", "source_name": "Splunk ShrinkLocker 2024", "url": "https://www.splunk.com/en_us/blog/security/shrinklocker-malware-abusing-bitlocker-to-lock-your-data.html"}], "id": "malware--3fc44c12-b16e-4de1-8869-cf0eb4446070", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "ShrinkLocker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ShrinkLocker"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Cristian Souza - Kaspersky GERT"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-685', 0, 156, '09-mitre-attack', 'retrieved', 'F749277B6D1653710817B95F8294F87CC7861C299107EDA67C06EC39071E6D96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
