VALUES ('doc-09-mitre-attack-p0-686', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-07T18:07:47.604Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hildegard](https://attack.mitre.org/software/S0601) is malware that targets misconfigured kubelets for initial access and runs cryptocurrency miner operations. The malware was first observed in January 2021. The TeamTNT activity group is believed to be behind [Hildegard](https://attack.mitre.org/software/S0601). (Citation: Unit 42 Hildegard Malware)", "external_references": [{"external_id": "S0601", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0601"}, {"description": "Chen, J. et al. (2021, February 3). Hildegard: New TeamTNT Cryptojacking Malware Targeting Kubernetes. Retrieved April 5, 2021.", "source_name": "Unit 42 Hildegard Malware", "url": "https://unit42.paloaltonetworks.com/hildegard-malware-teamtnt/"}], "id": "malware--40a1b8ec-7295-416c-a6b1-68181d86f120", "is_family": true, "modified": "2024-04-11T02:18:41.342Z", "name": "Hildegard", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hildegard"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Center for Threat-Informed Defense (CTID)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Containers", "IaaS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-686', 0, 114, '09-mitre-attack', 'retrieved', '049DFBE9CEFCF9F48B42F090F1A9D1F1CDB7D935E17368011DB6FDBA71E5C882', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
