VALUES ('doc-09-mitre-attack-p0-687', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:59.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agent.btz](https://attack.mitre.org/software/S0092) is a worm that primarily spreads itself via removable devices such as USB drives. It reportedly infected U.S. military networks in 2008. (Citation: Securelist Agent.btz)", "external_references": [{"external_id": "S0092", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0092"}, {"description": "Gostev, A.. (2014, March 12). Agent.btz: a Source of Inspiration?. Retrieved April 8, 2016.", "source_name": "Securelist Agent.btz", "url": "https://securelist.com/agent-btz-a-source-of-inspiration/58551/"}], "id": "malware--40d3e230-ed32-469f-ba89-be70cc08ab39", "is_family": true, "modified": "2025-04-25T14:43:05.955Z", "name": "Agent.btz", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Agent.btz"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-687', 0, 86, '09-mitre-attack', 'retrieved', '7E64B08E79F80A398D19B13631E4C534D042C3B54C23C14ED3540D828C6D02A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
