VALUES ('doc-09-mitre-attack-p0-688', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SLOWDRIFT](https://attack.mitre.org/software/S0218) is a backdoor used by [APT37](https://attack.mitre.org/groups/G0067) against academic and strategic victims in South Korea. (Citation: FireEye APT37 Feb 2018)", "external_references": [{"external_id": "S0218", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0218"}, {"description": "(Citation: FireEye APT37 Feb 2018)", "source_name": "SLOWDRIFT"}, {"description": "FireEye. (2018, February 20). APT37 (Reaper): The Overlooked North Korean Actor. Retrieved November 17, 2024.", "source_name": "FireEye APT37 Feb 2018", "url": "https://services.google.com/fh/files/misc/apt37-reaper-the-overlooked-north-korean-actor.pdf"}], "id": "malware--414dc555-c79e-4b24-a2da-9b607f7eaf16", "is_family": true, "modified": "2024-11-17T15:01:33.387Z", "name": "SLOWDRIFT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SLOWDRIFT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-688', 0, 93, '09-mitre-attack', 'retrieved', '1462E80EA72F698E571E0AD5ACFF98DEF1335BC48531F84FB1B29A4F6ED40BFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
