VALUES ('doc-09-mitre-attack-p0-691', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-26T18:49:37.827Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ODAgent](https://attack.mitre.org/software/S1170) is a C#/.NET downloader that has been used by [OilRig](https://attack.mitre.org/groups/G0049) since at least 2022 including against target organizations in Israel to download and execute payloads and to exfiltrate staged files.(Citation: ESET OilRig Downloaders DEC 2023)", "external_references": [{"external_id": "S1170", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1170"}, {"description": "Hromcova, Z. and Burgher, A. (2023, December 14). OilRig’s persistent attacks using cloud service-powered downloaders. Retrieved November 26, 2024.", "source_name": "ESET OilRig Downloaders DEC 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrig-persistent-attacks-cloud-service-powered-downloaders/"}], "id": "malware--42bf4ce8-415f-40e3-98b3-e3811875b406", "is_family": true, "modified": "2024-11-27T19:42:48.943Z", "name": "ODAgent", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ODAgent"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-691', 0, 106, '09-mitre-attack', 'retrieved', '5A7637D74F1A42597BA626089A144865DE656FF3BF2BC78EFDEAC63287F4C1BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
