VALUES ('doc-09-mitre-attack-p0-692', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T01:09:17.837Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackByte 2.0 Ransomware](https://attack.mitre.org/software/S1181) is a replacement for [BlackByte Ransomware](https://attack.mitre.org/software/S1180). Unlike [BlackByte Ransomware](https://attack.mitre.org/software/S1180), [BlackByte 2.0 Ransomware](https://attack.mitre.org/software/S1181) does not have a common key for victim decryption. [BlackByte 2.0 Ransomware](https://attack.mitre.org/software/S1181) remains uniquely associated with [BlackByte](https://attack.mitre.org/groups/G1043) operations.(Citation: Microsoft BlackByte 2023)", "external_references": [{"external_id": "S1181", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1181"}, {"description": "Microsoft Incident Response. (2023, July 6). The five-day job: A BlackByte ransomware intrusion case study. Retrieved December 16, 2024.", "source_name": "Microsoft BlackByte 2023", "url": "https://www.microsoft.com/en-us/security/blog/2023/07/06/the-five-day-job-a-blackbyte-ransomware-intrusion-case-study/"}], "id": "malware--42fdf9db-6005-4bb3-96f6-496b94ce519d", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "BlackByte 2.0 Ransomware", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BlackByte 2.0 Ransomware"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-692', 0, 108, '09-mitre-attack', 'retrieved', '343F64E86FE7AD3D58EB89D4F50E26536FF5BA50DAA17C9CADD1E69AFA2D4FB9', 'v1', '{"source_id": "09-mitre-attack", "version": 