VALUES ('doc-09-mitre-attack-p0-693', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-29T14:33:04.253Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FlawedGrace](https://attack.mitre.org/software/S0383) is a fully featured remote access tool (RAT) written in C++ that was first observed in late 2017.(Citation: Proofpoint TA505 Jan 2019)", "external_references": [{"external_id": "S0383", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0383"}, {"description": "Schwarz, D. and Proofpoint Staff. (2019, January 9). ServHelper and FlawedGrace - New malware introduced by TA505. Retrieved May 28, 2019.", "source_name": "Proofpoint TA505 Jan 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/servhelper-and-flawedgrace-new-malware-introduced-ta505"}], "id": "malware--43155329-3edf-47a6-9a14-7dac899b01e4", "is_family": true, "modified": "2024-04-11T02:32:31.883Z", "name": "FlawedGrace", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FlawedGrace"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-693', 0, 94, '09-mitre-attack', 'retrieved', '1599B7C6A7E5153965F321D0FCA8C34B5C3B37F9AFBECC69B684D75E513732E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
