VALUES ('doc-09-mitre-attack-p0-695', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-28T19:07:29.816Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FlawedAmmyy](https://attack.mitre.org/software/S0381) is a remote access tool (RAT) that was first seen in early 2016. The code for [FlawedAmmyy](https://attack.mitre.org/software/S0381) was based on leaked source code for a version of Ammyy Admin, a remote access software.(Citation: Proofpoint TA505 Mar 2018)", "external_references": [{"external_id": "S0381", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0381"}, {"description": "Proofpoint Staff. (2018, March 7). Leaked Ammyy Admin Source Code Turned into Malware. Retrieved May 28, 2019.", "source_name": "Proofpoint TA505 Mar 2018", "url": "https://www.proofpoint.com/us/threat-insight/post/leaked-ammyy-admin-source-code-turned-malware"}], "id": "malware--432555de-63bf-4f2a-a3fa-f720a4561078", "is_family": true, "modified": "2025-04-16T20:38:04.147Z", "name": "FlawedAmmyy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FlawedAmmyy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-695', 0, 105, '09-mitre-attack', 'retrieved', '8D0546B649D48EE633542E11DEFDDE8CE42B23CCEB82E2D5615B5DA2BD57D410', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
