VALUES ('doc-09-mitre-attack-p0-696', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-13T18:52:15.552Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Snip3](https://attack.mitre.org/software/S1086) is a sophisticated crypter-as-a-service that has been used since at least 2021 to obfuscate and load numerous strains of malware including [AsyncRAT](https://attack.mitre.org/software/S1087), [Revenge RAT](https://attack.mitre.org/software/S0379), [Agent Tesla](https://attack.mitre.org/software/S0331), and [NETWIRE](https://attack.mitre.org/software/S0198).(Citation: Morphisec Snip3 May 2021)(Citation: Telefonica Snip3 December 2021)", "external_references": [{"external_id": "S1086", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1086"}, {"description": "Jornet, A. (2021, December 23). Snip3, an investigation into malware. Retrieved September 19, 2023.", "source_name": "Telefonica Snip3 December 2021", "url": "https://telefonicatech.com/blog/snip3-investigacion-malware"}, {"description": "Lorber, N. (2021, May 7). Revealing the Snip3 Crypter, a Highly Evasive RAT Loader. Retrieved September 13, 2023.", "source_name": "Morphisec Snip3 May 2021", "url": "https://blog.morphisec.com/revealing-the-snip3-crypter-a-highly-evasive-rat-loader"}], "id": "malware--4327aff5-f194-440c-b499-4d9730cc1eab", "is_family": true, "modified": "2023-10-10T17:18:52.857Z", "name": "Snip3", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Snip3"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Aaron Jornet"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-696', 0, 130, '09-mitre-attack', 'retrieved', '672BFF753E711E6A5DFECF87CFAC000CB72C364649DF89AD0587C98F5E30BDFB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
