VALUES ('doc-09-mitre-attack-p0-697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-22T14:20:30.164Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FYAnti](https://attack.mitre.org/software/S0628) is a loader that has been used by [menuPass](https://attack.mitre.org/groups/G0045) since at least 2020, including to deploy [QuasarRAT](https://attack.mitre.org/software/S0262).(Citation: Securelist APT10 March 2021)", "external_references": [{"external_id": "S0628", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0628"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "DILLJUICE stage2"}, {"description": "GREAT. (2021, March 30). APT10: sophisticated multi-layered loader Ecipekac discovered in A41APT campaign. Retrieved June 17, 2021.", "source_name": "Securelist APT10 March 2021", "url": "https://securelist.com/apt10-sophisticated-multi-layered-loader-ecipekac-discovered-in-a41apt-campaign/101519/"}], "id": "malware--434ba392-ebdc-488b-b1ef-518deea65774", "is_family": true, "modified": "2025-04-25T14:43:07.972Z", "name": "FYAnti", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FYAnti", "DILLJUICE stage2"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-697', 0, 98, '09-mitre-attack', 'retrieved', '050458F98AAAD7FDE663D058B36CBE9BEDAC5FDF9F2DA66E53438B6292D3B0D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
