VALUES ('doc-09-mitre-attack-p0-698', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-05T14:03:11.359Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rifdoor](https://attack.mitre.org/software/S0433) is a remote access trojan (RAT) that shares numerous code similarities with [HotCroissant](https://attack.mitre.org/software/S0431).(Citation: Carbon Black HotCroissant April 2020)", "external_references": [{"external_id": "S0433", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0433"}, {"description": "Knight, S.. (2020, April 16). VMware Carbon Black TAU Threat Analysis: The Evolution of Lazarus. Retrieved May 1, 2020.", "source_name": "Carbon Black HotCroissant April 2020", "url": "https://www.carbonblack.com/2020/04/16/vmware-carbon-black-tau-threat-analysis-the-evolution-of-lazarus/"}], "id": "malware--44c75271-0e4d-496f-ae0a-a6d883a42a65", "is_family": true, "modified": "2024-04-11T00:14:59.199Z", "name": "Rifdoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Rifdoor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-698', 0, 89, '09-mitre-attack', 'retrieved', '6CBB99B7594DE1924373A8D7145CC4C230FCDBF30AA7B5E8A9527B2FD21E5C84', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
