VALUES ('doc-09-mitre-attack-p0-700', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-19T21:08:29.427Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoFiSe](https://attack.mitre.org/software/S1101) has been used by [ToddyCat](https://attack.mitre.org/groups/G1022) since at least 2023 to identify and collect files of interest on targeted systems.(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"external_id": "S1101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1101"}, {"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "malware--452da2d9-706c-4185-ad6f-f5edaf4b9f48", "is_family": true, "modified": "2024-01-19T21:09:35.017Z", "name": "LoFiSe", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LoFiSe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-700', 0, 95, '09-mitre-attack', 'retrieved', 'C20312D8C68109A42752FB0AADEE5D7D26E24F64A9EB2C003B0C0F8C64ED32A6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
