VALUES ('doc-09-mitre-attack-p0-701', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-19T15:30:36.593Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HOPLIGHT](https://attack.mitre.org/software/S0376) is a backdoor Trojan that has reportedly been used by the North Korean government.(Citation: US-CERT HOPLIGHT Apr 2019)", "external_references": [{"external_id": "S0376", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0376"}, {"description": "(Citation: US-CERT HOPLIGHT Apr 2019)", "source_name": "HOPLIGHT"}, {"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "is_family": true, "modified": "2025-10-22T02:57:05.402Z", "name": "HOPLIGHT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HOPLIGHT"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-701', 0, 91, '09-mitre-attack', 'retrieved', '86EDB01591302B7B994B1BEAF978297C62ADE973FA46F0D47A1DE81DB610B085', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
