VALUES ('doc-09-mitre-attack-p0-702', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-20T19:39:35.337Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cuckoo Stealer](https://attack.mitre.org/software/S1153) is a macOS malware with characteristics of spyware and an infostealer that has been in use since at least 2024. [Cuckoo Stealer](https://attack.mitre.org/software/S1153) is a universal Mach-O binary that can run on Intel or ARM-based Macs and has been spread through trojanized versions of various potentially unwanted programs or PUP''s such as converters, cleaners, and uninstallers.(Citation: Kandji Cuckoo April 2024)(Citation: SentinelOne Cuckoo Stealer May 2024)\n", "external_references": [{"external_id": "S1153", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1153"}, {"description": "Kohler, A. and Lopez, C. (2024, April 30). Malware: Cuckoo Behaves Like Cross Between Infostealer and Spyware. Retrieved August 20, 2024.", "source_name": "Kandji Cuckoo April 2024", "url": "https://www.kandji.io/blog/malware-cuckoo-infostealer-spyware"}, {"description": "Stokes, P. (2024, May 9). macOS Cuckoo Stealer | Ensuring Detection and Defense as New Samples Rapidly Emerge. Retrieved August 20, 2024.", "source_name": "SentinelOne Cuckoo Stealer May 2024", "url": "https://www.sentinelone.com/blog/macos-cuckoo-stealer-ensuring-detection-and-defense-as-new-samples-rapidly-emerge/"}], "id": "malware--457a5e8d-d964-4130-bde3-c07bb41a093e", "is_family": true, "modified": "2024-10-28T16:22:59.359Z", "name": "Cuckoo Stealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cuckoo Stealer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Takemasa Kamatani, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-702', 0, 185, '09-mitre-attack', 'retrieved', '683D3001D8AE36383002D74D659B5C76FB41D28E4C884FC88DAB94BA2A3C0B8C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
