VALUES ('doc-09-mitre-attack-p0-703', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-11T20:49:20.832Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GuLoader](https://attack.mitre.org/software/S0561) is a file downloader that has been used since at least December 2019 to distribute a variety of remote administration tool (RAT) malware, including [NETWIRE](https://attack.mitre.org/software/S0198), [Agent Tesla](https://attack.mitre.org/software/S0331), [NanoCore](https://attack.mitre.org/software/S0336), FormBook, and Parallax RAT.(Citation: Unit 42 NETWIRE April 2020)(Citation: Medium Eli Salem GuLoader April 2021)", "external_references": [{"external_id": "S0561", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0561"}, {"description": "Duncan, B. (2020, April 3). GuLoader: Malspam Campaign Installing NetWire RAT. Retrieved January 7, 2021.", "source_name": "Unit 42 NETWIRE April 2020", "url": "https://unit42.paloaltonetworks.com/guloader-installing-netwire-rat/"}, {"description": "Salem, E. (2021, April 19). Dancing With Shellcodes: Cracking the latest version of Guloader. Retrieved July 7, 2021.", "source_name": "Medium Eli Salem GuLoader April 2021", "url": "https://elis531989.medium.com/dancing-with-shellcodes-cracking-the-latest-version-of-guloader-75083fb15cb4"}], "id": "malware--45c759ac-b490-48bb-80d4-c8eee3431027", "is_family": true, "modified": "2025-04-25T14:43:09.227Z", "name": "GuLoader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GuLoader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Eli Salem, @elisalem9"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-703', 0, 140, '09-mitre-attack', 'retrieved', '3C40ACBBDE2D847FEA696019A96A96DED7AFCE851AAE5B7FD60CB708EECF09B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
