VALUES ('doc-09-mitre-attack-p0-704', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:53.681Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MobileOrder](https://attack.mitre.org/software/S0079) is a Trojan intended to compromise Android mobile devices. It has been used by [Scarlet Mimic](https://attack.mitre.org/groups/G0029). (Citation: Scarlet Mimic Jan 2016)", "external_references": [{"external_id": "S0079", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0079"}, {"description": "Falcone, R. and Miller-Osborn, J.. (2016, January 24). Scarlet Mimic: Years-Long Espionage Campaign Targets Minority Activists. Retrieved February 10, 2016.", "source_name": "Scarlet Mimic Jan 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/01/scarlet-mimic-years-long-espionage-targets-minority-activists/"}], "id": "malware--463f68f1-5cde-4dc2-a831-68b73488f8f4", "is_family": true, "modified": "2025-04-25T14:43:09.588Z", "name": "MobileOrder", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-704', 0, 86, '09-mitre-attack', 'retrieved', '2019F782511202497BA589CEB4DEAD400415910966BC6EF46D4987F09FAFBD94', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
