VALUES ('doc-09-mitre-attack-p0-707', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-30T19:47:47.136Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ProLock](https://attack.mitre.org/software/S0654) is a ransomware strain that has been used in Big Game Hunting (BGH) operations since at least 2020, often obtaining initial access with [QakBot](https://attack.mitre.org/software/S0650). [ProLock](https://attack.mitre.org/software/S0654) is the successor to PwndLocker ransomware which was found to contain a bug allowing decryption without ransom payment in 2019.(Citation: Group IB Ransomware September 2020)", "external_references": [{"external_id": "S0654", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0654"}, {"description": "Group IB. (2020, September). LOCK LIKE A PRO. Retrieved November 17, 2024.", "source_name": "Group IB Ransomware September 2020", "url": "https://web.archive.org/web/20220119114433/https://groupib.pathfactory.com/ransomware-reports/prolock_wp"}], "id": "malware--471d0e9f-2c8a-4e4b-8f3b-f85d2407806e", "is_family": true, "modified": "2024-11-17T23:58:37.273Z", "name": "ProLock", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ProLock"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-707', 0, 114, '09-mitre-attack', 'retrieved', '3105399DDE00F76D0E12237820C5A2F2F0E702C905E9CF42C498680CD6965721', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
