VALUES ('doc-09-mitre-attack-p0-708', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T23:05:34.895Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Moneybird](https://attack.mitre.org/software/S1137) is a ransomware variant written in C++ associated with [Agrius](https://attack.mitre.org/groups/G1030) operations. The name \"Moneybird\" is contained in the malware''s ransom note and as strings in the executable.(Citation: CheckPoint Agrius 2023)", "external_references": [{"external_id": "S1137", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1137"}, {"description": "Marc Salinas Fernandez & Jiri Vinopal. (2023, May 23). AGRIUS DEPLOYS MONEYBIRD IN TARGETED ATTACKS AGAINST ISRAELI ORGANIZATIONS. Retrieved May 21, 2024.", "source_name": "CheckPoint Agrius 2023", "url": "https://research.checkpoint.com/2023/agrius-deploys-moneybird-in-targeted-attacks-against-israeli-organizations/"}], "id": "malware--47ab6350-054f-4754-ba4d-e52a4e8751e2", "is_family": true, "modified": "2024-08-29T15:19:39.017Z", "name": "Moneybird", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Moneybird"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-708', 0, 102, '09-mitre-attack', 'retrieved', '25EDBD6C8CBF1DBCCABB2E657D77460645EDF520614BF2DA9FBB56631306FD52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
