VALUES ('doc-09-mitre-attack-p0-711', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-13T12:46:58.579Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[P.A.S. Webshell](https://attack.mitre.org/software/S0598) is a publicly available multifunctional PHP webshell in use since at least 2016 that provides remote access and execution on target web servers.(Citation: ANSSI Sandworm January 2021)", "external_references": [{"external_id": "S0598", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0598"}, {"description": "(Citation: NCCIC AR-17-20045 February 2017)", "source_name": "Fobushell"}, {"description": "ANSSI. (2021, January 27). SANDWORM INTRUSION SET CAMPAIGN TARGETING CENTREON SYSTEMS. Retrieved March 30, 2021.", "source_name": "ANSSI Sandworm January 2021", "url": "https://www.cert.ssi.gouv.fr/uploads/CERTFR-2021-CTI-005.pdf"}, {"description": "NCCIC. (2017, February 10). Enhanced Analysis of GRIZZLY STEPPE Activity. Retrieved April 12, 2021.", "source_name": "NCCIC AR-17-20045 February 2017", "url": "https://us-cert.cisa.gov/sites/default/files/publications/AR-17-20045_Enhanced_Analysis_of_GRIZZLY_STEPPE_Activity.pdf"}], "id": "malware--4800d0f9-00aa-47cd-a4d2-92198585b8fd", "is_family": true, "modified": "2025-04-25T14:43:11.044Z", "name": "P.A.S. Webshell", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["P.A.S. Webshell", "Fobushell"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-711', 0, 126, '09-mitre-attack', 'retrieved', '31CF075ABD8A9989BA67BD9741C37709F9E404812C4CF4716681E681452DC9F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
