VALUES ('doc-09-mitre-attack-p0-712', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-17T17:06:19.976Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QUIETEXIT](https://attack.mitre.org/software/S1084) is a novel backdoor, based on the open-source Dropbear SSH client-server software, that has been used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2021. [APT29](https://attack.mitre.org/groups/G0016) has deployed [QUIETEXIT](https://attack.mitre.org/software/S1084) on opaque network appliances that typically don''t support antivirus or endpoint detection and response tools within a victim environment.(Citation: Mandiant APT29 Eye Spy Email Nov 22)", "external_references": [{"external_id": "S1084", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1084"}, {"description": "Mandiant. (2022, May 2). UNC3524: Eye Spy on Your Email. Retrieved August 17, 2023.", "source_name": "Mandiant APT29 Eye Spy Email Nov 22", "url": "https://www.mandiant.com/resources/blog/unc3524-eye-spy-email"}], "id": "malware--4816d361-f82b-4a18-aa05-b215e7cf9200", "is_family": true, "modified": "2025-04-15T19:46:34.040Z", "name": "QUIETEXIT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["QUIETEXIT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Joe Gumke, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-712', 0, 126, '09-mitre-attack', 'retrieved', 'D4C5FF4D976BA2334278E4CA143149AF8AE0AA93C2F59EA6731906E35F18BB95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
