VALUES ('doc-09-mitre-attack-p0-715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volgmer](https://attack.mitre.org/software/S0180) is a backdoor Trojan designed to provide covert access to a compromised system. It has been used since at least 2013 to target the government, financial, automotive, and media industries. Its primary delivery mechanism is suspected to be spearphishing. (Citation: US-CERT Volgmer Nov 2017)", "external_references": [{"external_id": "S0180", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0180"}, {"description": "(Citation: US-CERT Volgmer Nov 2017) (Citation: US-CERT Volgmer 2 Nov 2017) (Citation: Symantec Volgmer Aug 2014)", "source_name": "Volgmer"}, {"description": "US-CERT. (2017, November 01). Malware Analysis Report (MAR) - 10135536-D. Retrieved July 16, 2018.", "source_name": "US-CERT Volgmer 2 Nov 2017", "url": "https://www.us-cert.gov/sites/default/files/publications/MAR-10135536-D_WHITE_S508C.PDF"}, {"description": "US-CERT. (2017, November 22). Alert (TA17-318B): HIDDEN COBRA – North Korean Trojan: Volgmer. Retrieved December 7, 2017.", "source_name": "US-CERT Volgmer Nov 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-318B"}, {"description": "Yagi, J. (2014, August 24). Trojan.Volgmer. Retrieved July 16, 2018.", "source_name": "Symantec Volgmer Aug 2014", "url": "https://web.archive.org/web/20181126143456/https://www.symantec.com/security-center/writeup/2014-081811-3237-99?tabid=2"}], "id": "malware--495b6cdb-7b5a-4fbc-8d33-e7ef68806d08", "is_family": true, "modified": "2024-04-10T22:16:05.440Z", "name": "Volgmer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Volgmer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-715', 0, 172, '09-mitre-attack', 'retrieved', 'A89A1FB310E62DF8B18F14A36FE36AF74ECE0EF1E0477589002B9C2F97CDF406', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
