VALUES ('doc-09-mitre-attack-p0-716', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WINERACK](https://attack.mitre.org/software/S0219) is a backdoor used by [APT37](https://attack.mitre.org/groups/G0067). (Citation: FireEye APT37 Feb 2018)", "external_references": [{"external_id": "S0219", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0219"}, {"description": "FireEye. (2018, February 20). APT37 (Reaper): The Overlooked North Korean Actor. Retrieved November 17, 2024.", "source_name": "FireEye APT37 Feb 2018", "url": "https://services.google.com/fh/files/misc/apt37-reaper-the-overlooked-north-korean-actor.pdf"}], "id": "malware--49abab73-3c5c-476e-afd5-69b5c732d845", "is_family": true, "modified": "2024-11-17T15:01:33.388Z", "name": "WINERACK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WINERACK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-716', 0, 75, '09-mitre-attack', 'retrieved', '2CAC37D239EBB2F9A2DCDF4EFD270F291A893C91B6C0F5494767DC14BB588D19', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
