VALUES ('doc-09-mitre-attack-p0-717', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-10T16:42:36.137Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WhisperGate](https://attack.mitre.org/software/S0689) is a multi-stage wiper designed to look like ransomware that has been used against multiple government, non-profit, and information technology organizations in Ukraine since at least January 2022.(Citation: Cybereason WhisperGate February 2022)(Citation: Unit 42 WhisperGate January 2022)(Citation: Microsoft WhisperGate January 2022)", "external_references": [{"external_id": "S0689", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0689"}, {"description": "Cybereason Nocturnus. (2022, February 15). Cybereason vs. WhisperGate and HermeticWiper. Retrieved March 10, 2022.", "source_name": "Cybereason WhisperGate February 2022", "url": "https://www.cybereason.com/blog/cybereason-vs.-whispergate-wiper"}, {"description": "Falcone, R. et al.. (2022, January 20). Threat Brief: Ongoing Russia and Ukraine Cyber Conflict. Retrieved March 10, 2022.", "source_name": "Unit 42 WhisperGate January 2022", "url": "https://unit42.paloaltonetworks.com/ukraine-cyber-conflict-cve-2021-32648-whispergate/#whispergate-malware-family"}, {"description": "MSTIC. (2022, January 15). Destructive malware targeting Ukrainian organizations. Retrieved March 10, 2022.", "source_name": "Microsoft WhisperGate January 2022", "url": "https://www.microsoft.com/security/blog/2022/01/15/destructive-malware-targeting-ukrainian-organizations/"}], "id": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "is_family": true, "modified": "2024-04-10T22:13:49.349Z", "name": "WhisperGate", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WhisperGate"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Phill Taylor, BT Security", "Matt Brenton, Zurich Global Information Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-717', 0, 166, '09-mitre-attack', 'retrieved', '717A6579380A6B1629D18F46A35EAFD5465FC962290095F7BAA0F660FBD23083', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
