VALUES ('doc-09-mitre-attack-p0-719', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZeroT](https://attack.mitre.org/software/S0230) is a Trojan used by [TA459](https://attack.mitre.org/groups/G0062), often in conjunction with [PlugX](https://attack.mitre.org/software/S0013). (Citation: Proofpoint TA459 April 2017) (Citation: Proofpoint ZeroT Feb 2017)", "external_references": [{"external_id": "S0230", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0230"}, {"description": "(Citation: Proofpoint TA459 April 2017) (Citation: Proofpoint ZeroT Feb 2017)", "source_name": "ZeroT"}, {"description": "Axel F. (2017, April 27). APT Targets Financial Analysts with CVE-2017-0199. Retrieved February 15, 2018.", "source_name": "Proofpoint TA459 April 2017", "url": "https://www.proofpoint.com/us/threat-insight/post/apt-targets-financial-analysts"}, {"description": "Huss, D., et al. (2017, February 2). Oops, they did it again: APT Targets Russia and Belarus with ZeroT and PlugX. Retrieved April 5, 2018.", "source_name": "Proofpoint ZeroT Feb 2017", "url": "https://www.proofpoint.com/us/threat-insight/post/APT-targets-russia-belarus-zerot-plugx"}], "id": "malware--4ab44516-ad75-4e43-a280-705dc0420e2f", "is_family": true, "modified": "2024-04-10T20:32:14.510Z", "name": "ZeroT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ZeroT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-719', 0, 133, '09-mitre-attack', 'retrieved', 'CA4B275B9AA87F22C48605148CB6BCC9C4C36243E41CBCD11E74D3A663ECBE9B', 'v1