VALUES ('doc-09-mitre-attack-p0-720', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "This piece of malware steals the content of the user''s keychain while maintaining a permanent backdoor (Citation: OSX Keydnap malware).", "external_references": [{"external_id": "S0276", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0276"}, {"description": "(Citation: OSX Keydnap malware)", "source_name": "OSX/Keydnap"}, {"description": "(Citation: synack 2016 review)", "source_name": "Keydnap"}, {"description": "Marc-Etienne M.Leveille. (2016, July 6). New OSX/Keydnap malware is hungry for credentials. Retrieved July 3, 2017.", "source_name": "OSX Keydnap malware", "url": "https://www.welivesecurity.com/2016/07/06/new-osxkeydnap-malware-hungry-credentials/"}, {"description": "Patrick Wardle. (2017, January 1). Mac Malware of 2016. Retrieved September 21, 2018.", "source_name": "synack 2016 review", "url": "https://objective-see.org/blog/blog_0x16.html"}], "id": "malware--4b072c90-bc7a-432b-940e-016fc1c01761", "is_family": true, "modified": "2024-01-10T15:18:40.400Z", "name": "Keydnap", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Keydnap", "OSX/Keydnap"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-720', 0, 120, '09-mitre-attack', 'retrieved', 'AB30071DB10E810C9E2936BB9A7D062B1FA9DD626D8E58296270F149107DC449', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
