VALUES ('doc-09-mitre-attack-p0-722', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-28T17:26:36.168Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RDAT](https://attack.mitre.org/software/S0495) is a backdoor used by the suspected Iranian threat group [OilRig](https://attack.mitre.org/groups/G0049). [RDAT](https://attack.mitre.org/software/S0495) was originally identified in 2017 and targeted companies in the telecommunications sector.(Citation: Unit42 RDAT July 2020)", "external_references": [{"external_id": "S0495", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0495"}, {"description": "Falcone, R. (2020, July 22). OilRig Targets Middle Eastern Telecommunications Organization and Adds Novel C2 Channel with Steganography to Its Inventory. Retrieved July 28, 2020.", "source_name": "Unit42 RDAT July 2020", "url": "https://unit42.paloaltonetworks.com/oilrig-novel-c2-channel-steganography/"}], "id": "malware--4b346d12-7f91-48d2-8f06-b26ffa0d825b", "is_family": true, "modified": "2025-04-25T14:43:13.198Z", "name": "RDAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RDAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-722', 0, 102, '09-mitre-attack', 'retrieved', 'DA69BF169789FD076E6C10FB6AA1E422C95B0948341DB90A004D3037FD36757E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
