VALUES ('doc-09-mitre-attack-p0-723', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:35.389Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hacking Team UEFI Rootkit](https://attack.mitre.org/software/S0047) is a rootkit developed by the company Hacking Team as a method of persistence for remote access software. (Citation: TrendMicro Hacking Team UEFI)", "external_references": [{"external_id": "S0047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0047"}, {"description": "Lin, P. (2015, July 13). Hacking Team Uses UEFI BIOS Rootkit to Keep RCS 9 Agent in Target Systems. Retrieved December 11, 2015.", "source_name": "TrendMicro Hacking Team UEFI", "url": "http://blog.trendmicro.com/trendlabs-security-intelligence/hacking-team-uses-uefi-bios-rootkit-to-keep-rcs-9-agent-in-target-systems/"}], "id": "malware--4b62ab58-c23b-4704-9c15-edd568cd59f8", "is_family": true, "modified": "2025-04-25T14:43:13.563Z", "name": "Hacking Team UEFI Rootkit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hacking Team UEFI Rootkit"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-723', 0, 102, '09-mitre-attack', 'retrieved', 'CEE5BD7FB7C8F4C272E3F8A2C1ECC078E8C6203FA06EDB01D9BBD6B9277E98C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
