VALUES ('doc-09-mitre-attack-p0-724', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-09T21:23:38.995Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Skidmap](https://attack.mitre.org/software/S0468) is a kernel-mode rootkit used for cryptocurrency mining.(Citation: Trend Micro Skidmap)", "external_references": [{"external_id": "S0468", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0468"}, {"description": "Remillano, A., Urbanec, J. (2019, September 19). Skidmap Linux Malware Uses Rootkit Capabilities to Hide Cryptocurrency-Mining Payload. Retrieved June 4, 2020.", "source_name": "Trend Micro Skidmap", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/skidmap-linux-malware-uses-rootkit-capabilities-to-hide-cryptocurrency-mining-payload/"}], "id": "malware--4b68b5ea-2e1b-4225-845b-8632f702b9a0", "is_family": true, "modified": "2024-04-11T00:06:31.222Z", "name": "Skidmap", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Skidmap"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-724', 0, 82, '09-mitre-attack', 'retrieved', 'AEA7B473E3002E03EFAC7DAC3EE2E40822899AFAD10A05757CAC122CD7223DEA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
