VALUES ('doc-09-mitre-attack-p0-725', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T21:12:31.535Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Okrum](https://attack.mitre.org/software/S0439) is a Windows backdoor that has been seen in use since December 2016 with strong links to [Ke3chang](https://attack.mitre.org/groups/G0004).(Citation: ESET Okrum July 2019)", "external_references": [{"external_id": "S0439", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0439"}, {"description": "Hromcova, Z. (2019, July). OKRUM AND KETRICAN: AN OVERVIEW OF RECENT KE3CHANG GROUP ACTIVITY. Retrieved May 6, 2020.", "source_name": "ESET Okrum July 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/07/ESET_Okrum_and_Ketrican.pdf"}], "id": "malware--4b6ec280-7bbb-48ff-ae59-b189520ebe83", "is_family": true, "modified": "2025-04-25T14:43:14.113Z", "name": "Okrum", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Okrum"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-725', 0, 91, '09-mitre-attack', 'retrieved', '4E5668D6DCAC1AA1F8D336F03BFBFF20EC81496F6406CC1EEF5370D1A413CA39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
