VALUES ('doc-09-mitre-attack-p0-727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:17.959Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Regin](https://attack.mitre.org/software/S0019) is a malware platform that has targeted victims in a range of industries, including telecom, government, and financial institutions. Some [Regin](https://attack.mitre.org/software/S0019) timestamps date back to 2003. (Citation: Kaspersky Regin)", "external_references": [{"external_id": "S0019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0019"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2014, November 24). THE REGIN PLATFORM NATION-STATE OWNAGE OF GSM NETWORKS. Retrieved December 1, 2014.", "source_name": "Kaspersky Regin", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/08070305/Kaspersky_Lab_whitepaper_Regin_platform_eng.pdf"}], "id": "malware--4c59cce8-cb48-4141-b9f1-f646edfaadb0", "is_family": true, "modified": "2023-10-01T02:47:21.211Z", "name": "Regin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Regin"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-727', 0, 100, '09-mitre-attack', 'retrieved', '3A6609DE7192156BA468CA700BD7B63BA4034576311433AD7435E1448457FF11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
