VALUES ('doc-09-mitre-attack-p0-728', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-16T14:59:40.051Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bonadan](https://attack.mitre.org/software/S0486) is a malicious version of OpenSSH which acts as a custom backdoor. [Bonadan](https://attack.mitre.org/software/S0486) has been active since at least 2018 and combines a new cryptocurrency-mining module with the same credential-stealing module used by the Onderon family of backdoors.(Citation: ESET ForSSHe December 2018)", "external_references": [{"external_id": "S0486", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0486"}, {"description": "Dumont, R., M.Léveillé, M., Porcher, H. (2018, December 1). THE DARK SIDE OF THE FORSSHE A landscape of OpenSSH backdoors. Retrieved July 16, 2020.", "source_name": "ESET ForSSHe December 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/12/ESET-The_Dark_Side_of_the_ForSSHe.pdf"}], "id": "malware--4c6d62c2-89f5-4159-8fab-0190b1f9d328", "is_family": true, "modified": "2025-04-25T14:43:14.836Z", "name": "Bonadan", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bonadan"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-728', 0, 115, '09-mitre-attack', 'retrieved', 'A39943A97C43A455B893C49129F1912867FC1917E0EA4B250EB8903DD1985199', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
