VALUES ('doc-09-mitre-attack-p0-730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-15T19:40:07.664Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SamSam](https://attack.mitre.org/software/S0370) is ransomware that appeared in early 2016. Unlike some ransomware, its variants have required operators to manually interact with the malware to execute some of its core components.(Citation: US-CERT SamSam 2018)(Citation: Talos SamSam Jan 2018)(Citation: Sophos SamSam Apr 2018)(Citation: Symantec SamSam Oct 2018)", "external_references": [{"external_id": "S0370", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0370"}, {"description": " Palotay, D. and Mackenzie, P. (2018, April). SamSam Ransomware Chooses Its Targets Carefully. Retrieved April 15, 2019.", "source_name": "Sophos SamSam Apr 2018", "url": "https://www.sophos.com/en-us/medialibrary/PDFs/technical-papers/SamSam-ransomware-chooses-Its-targets-carefully-wpna.pdf"}, {"description": "(Citation: US-CERT SamSam 2018)", "source_name": "Samas"}, {"description": "Symantec Security Response Attack Investigation Team. (2018, October 30). SamSam: Targeted Ransomware Attacks Continue. Retrieved April 16, 2019.", "source_name": "Symantec SamSam Oct 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/samsam-targeted-ransomware-attacks"}, {"description": "US-CERT. (2018, December 3). Alert (AA18-337A): SamSam Ransomware. Retrieved March 15, 2019.", "source_name": "US-CERT SamSam 2018", "url": "https://www.us-cert.gov/ncas/alerts/AA18-337A"}, {"description": "Ventura, V. (2018, January 22). SamSam - The Evolution Continues Netting Over $325,000 in 4 Weeks. Retrieved April 16, 2019.", "source_name": "Talos SamSam Jan 2018", "url": "https://blog.talosintelligence.com/2018/01/samsam-evolution-continues-netting-over.html"}], "id": "malware--4d56e6e9-1a6d-46e3-896c-dfdf3cc96e62", "is_family": true, "modified": "2024-04-11T00:09:42.414Z", "name": "SamSam", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SamSam", "Samas"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-730', 0, 193, '09-mitre-attack', 'retrieved', 'FA7E54EDBB2F949246720E7C6709C181A6864463DEFDB6020D79A1A21052B052', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
