INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-17T18:51:57.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Conti](https://attack.mitre.org/software/S0575) is a Ransomware-as-a-Service (RaaS) that was first observed in December 2019. [Conti](https://attack.mitre.org/software/S0575) has been deployed via [TrickBot](https://attack.mitre.org/software/S0266) and used against major corporations and government agencies, particularly those in North America. As with other ransomware families, actors using [Conti](https://attack.mitre.org/software/S0575) steal sensitive files and information from compromised networks, and threaten to publish this data unless the ransom is paid.(Citation: Cybereason Conti Jan 2021)(Citation: CarbonBlack Conti July 2020)(Citation: Cybleinc Conti January 2020)", "external_references": [{"external_id": "S0575", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0575"}, {"description": "(Citation: CarbonBlack Conti July 2020)(Citation: Cybereason Conti Jan 2021)", "source_name": "Conti"}, {"description": "Baskin, B. (2020, July 8). TAU Threat Discovery: Conti Ransomware. Retrieved February 17, 2021.", "source_name": "CarbonBlack Conti July 2020", "url": "https://www.carbonblack.com/blog/tau-threat-discovery-conti-ransomware/"}, {"description": "Cybleinc. (2021, January 21). Conti Ransomware Resurfaces, Targeting Government & Large Organizations. Retrieved April 13, 2021.", "source_name": "Cybleinc Conti January 2020", "url": "https://cybleinc.com/2021/01/21/conti-ransomware-resurfaces-targeting-government-large-organizations/"}, {"description": "Rochberger, L. (2021, January 12). Cybereason vs. Conti Ransomware. Retrieved February 17, 2021.", "source_name": "Cybereason Conti Jan 2021", "url": "https://www.cybereason.com/blog/cybereason-vs.-conti-ransomware"}], "id": "malware--4dea7d8e-af94-4bfb-afe4-7ff54f59308b", "is_family": true, "modified": "2025-04-16T20:38:06.412Z", "name": "Conti", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Conti"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-732', 0, 196, '09-mitre-attack', 'retrieved', 'EF852FE9A168DBD9E4B0106C7CB9FCC8A56FD139D70286C51AD82E179668EE01', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
