VALUES ('doc-09-mitre-attack-p0-733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T13:01:30.316Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SameCoin](https://attack.mitre.org/software/S9030) is a multi-platform wiper with Windows and Android versions that has been used by [WIRTE](https://attack.mitre.org/groups/G0090) to target entities in the Middle East including in Israel.(Citation: Check Point Wirte NOV 2024)", "external_references": [{"external_id": "S9030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9030"}, {"description": "Check Point. (2024, November 12). Hamas-affiliated Threat Actor WIRTE Continues its Middle East Operations and Moves to Disruptive Activity. Retrieved April 20, 2026.", "source_name": "Check Point Wirte NOV 2024", "url": "https://research.checkpoint.com/2024/hamas-affiliated-threat-actor-expands-to-disruptive-activity/"}], "id": "malware--4e164a21-3fbe-4aaa-be69-2513fdba90f7", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "SameCoin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SameCoin"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Android"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-733', 0, 107, '09-mitre-attack', 'retrieved', '0E7C6D289D81035AAEB6735CE56C2BC32CBCDD634A9324F325C04A0F7E602355', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
