INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-735', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-13T20:59:22.655Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) is a banking trojan written in Delphi that was first observed in 2019 and uses a Malware-as-a-Service (MaaS) business model.(Citation: ESET Security Mispadu Facebook Ads 2019)(Citation: SCILabs Malteiro 2021) This malware is operated, managed, and sold by the [Malteiro](https://attack.mitre.org/groups/G1026) cybercriminal group.(Citation: SCILabs Malteiro 2021) [Mispadu](https://attack.mitre.org/software/S1122) has mainly been used to target victims in Brazil and Mexico, and has also had confirmed operations throughout Latin America and Europe.(Citation: SCILabs Malteiro 2021)(Citation: SCILabs URSA/Mispadu Evolution 2023)(Citation: Segurança Informática URSA Sophisticated Loader 2020) ", "external_references": [{"external_id": "S1122", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1122"}, {"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "Pedro Tavares (Segurança Informática). (2020, September 15). Threat analysis: The emergent URSA trojan impacts many countries using a sophisticated loader. Retrieved March 13, 2024.", "source_name": "Segurança Informática URSA Sophisticated Loader 2020", "url": "https://seguranca-informatica.pt/threat-analysis-the-emergent-ursa-trojan-impacts-many-countries-using-a-sophisticated-loader/"}, {"description": "SCILabs. (2021, December 23). Cyber Threat Profile Malteiro. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro 2021", "url": "https://blog.scilabs.mx/en/cyber-threat-profile-malteiro/"}, {"description": "SCILabs. (2023, May 23). Evolution of banking trojan URSA/Mispadu. Retrieved March 13, 2024.", "source_name": "SCILabs URSA/Mispadu Evolution 2023", "url": "https://blog.scilabs.mx/en/evolution-of-banking-trojan-ursa-mispadu/"}], "id": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "is_family": true, "modified": "2024-04-18T14:15:33.229Z", "name": "Mispadu", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mispadu"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["SCILabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-735', 0, 226, '09-mitre-attack', 'retrieved', '0235EDF53EDA07BB91E1557C18D15B96E8257777D9679255E56E2C40E816CF4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
