VALUES ('doc-09-mitre-attack-p0-737', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-08T21:31:29.913Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Megazord](https://attack.mitre.org/software/S1191) is a Rust-based variant of [Akira](https://attack.mitre.org/software/S1129) ransomware that has been in use since at least August 2023 to target Windows environments. [Megazord](https://attack.mitre.org/software/S1191) has been attributed to the [Akira](https://attack.mitre.org/groups/G1024) group based on overlapping infrastructure though is possibly not exclusive to the group.(Citation: CISA Akira Ransomware APR 2024)(Citation: Cisco Akira Ransomware OCT 2024)(Citation: Palo Alto Howling Scorpius DEC 2024)\n\n", "external_references": [{"external_id": "S1191", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1191"}, {"description": "CISA et al. (2024, April 18). #StopRansomware: Akira Ransomware. Retrieved December 10, 2024.", "source_name": "CISA Akira Ransomware APR 2024", "url": "https://www.cisa.gov/sites/default/files/2024-04/aa24-109a-stopransomware-akira-ransomware_2.pdf"}, {"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}, {"description": "Zemah, Y. (2024, December 2). Threat Assessment: Howling Scorpius (Akira Ransomware). Retrieved January 8, 2025.", "source_name": "Palo Alto Howling Scorpius DEC 2024", "url": "https://unit42.paloaltonetworks.com/threat-assessment-howling-scorpius-akira-ransomware/"}], "id": "malware--4e762e29-3c56-4a2b-b205-c5890c0856ed", "is_family": true, "modified": "2025-03-11T15:37:31.186Z", "name": "Megazord", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Megazord"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jiraput Thamsongkrah"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-737', 0, 176, '09-mitre-attack', 'retrieved', '83A4865121C00683328AF86857E90A3322050FB4C8E281D9A3A7F40A7B2AD785', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
