INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-738', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-12T19:02:16.381Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Diavol](https://attack.mitre.org/software/S0659) is a ransomware variant first observed in June 2021 that is capable of prioritizing file types to encrypt based on a pre-configured list of extensions defined by the attacker. The [Diavol](https://attack.mitre.org/software/S0659) Ransomware-as-a Service (RaaS) program is managed by [Wizard Spider](https://attack.mitre.org/groups/G0102) and it has been observed being deployed by [Bazar](https://attack.mitre.org/software/S0534).(Citation: Fortinet Diavol July 2021)(Citation: FBI Flash Diavol January 2022)(Citation: DFIR Diavol Ransomware December 2021)(Citation: Microsoft Ransomware as a Service)", "external_references": [{"external_id": "S0659", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0659"}, {"description": "(Citation: Fortinet Diavol July 2021)", "source_name": "Diavol"}, {"description": "DFIR Report. (2021, December 13). Diavol Ransomware. Retrieved March 9, 2022.", "source_name": "DFIR Diavol Ransomware December 2021", "url": "https://thedfirreport.com/2021/12/13/diavol-ransomware/"}, {"description": "FBI. (2022, January 19). Indicators of Compromise Associated with Diavol. Retrieved November 17, 2024.", "source_name": "FBI Flash Diavol January 2022", "url": "https://www.ic3.gov/CSA/2022/220120.pdf"}, {"description": "Microsoft. (2022, May 9). Ransomware as a service: Understanding the cybercrime gig economy and how to protect yourself. Retrieved March 10, 2023.", "source_name": "Microsoft Ransomware as a Service", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/09/ransomware-as-a-service-understanding-the-cybercrime-gig-economy-and-how-to-protect-yourself/"}, {"description": "Neeamni, D., Rubinfeld, A.. (2021, July 1). Diavol - A New Ransomware Used By Wizard Spider?. Retrieved November 12, 2021.", "source_name": "Fortinet Diavol July 2021", "url": "https://www.fortinet.com/blog/threat-research/diavol-new-ransomware-used-by-wizard-spider"}], "id": "malware--4e9bdf9a-4957-47f6-87b3-c76898d3f623", "is_family": true, "modified": "2024-11-17T20:10:33.591Z", "name": "Diavol", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Diavol"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Massimiliano Romano, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-738', 0, 226, '09-mitre-attack', 'retrieved', 'C6673F46EC67B9C8DE6B4243A90DE6C88E65B39F11B0CF9B7DAF100ABDC2AB05', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
