VALUES ('doc-09-mitre-attack-p0-741', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-06T15:53:34.722Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Doki](https://attack.mitre.org/software/S0600) is a backdoor that uses a unique Dogecoin-based Domain Generation Algorithm and was first observed in July 2020. [Doki](https://attack.mitre.org/software/S0600) was used in conjunction with the [ngrok](https://attack.mitre.org/software/S0508) Mining Botnet in a campaign that targeted Docker servers in cloud platforms. (Citation: Intezer Doki July 20)", "external_references": [{"external_id": "S0600", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0600"}, {"description": "Fishbein, N., Kajiloti, M.. (2020, July 28). Watch Your Containers: Doki Infecting Docker Servers in the Cloud. Retrieved March 30, 2021.", "source_name": "Intezer Doki July 20", "url": "https://www.intezer.com/blog/cloud-security/watch-your-containers-doki-infecting-docker-servers-in-the-cloud/"}], "id": "malware--4f1c389e-a80e-4a3e-9b0e-9be8c91df64f", "is_family": true, "modified": "2025-04-25T14:43:17.148Z", "name": "Doki", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Doki"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Center for Threat-Informed Defense (CTID)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-741', 0, 120, '09-mitre-attack', 'retrieved', '62C38B520767761DE5F44B8B9C02CC54F598CDCC31499109D885563FD8447FE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
