VALUES ('doc-09-mitre-attack-p0-743', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T15:26:55.509Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Siloscape](https://attack.mitre.org/software/S0623) is malware that targets Kubernetes clusters through Windows containers. [Siloscape](https://attack.mitre.org/software/S0623) was first observed in March 2021.(Citation: Unit 42 Siloscape Jun 2021)", "external_references": [{"external_id": "S0623", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0623"}, {"description": "Prizmant, D. (2021, June 7). Siloscape: First Known Malware Targeting Windows Containers to Compromise Cloud Environments. Retrieved June 9, 2021.", "source_name": "Unit 42 Siloscape Jun 2021", "url": "https://unit42.paloaltonetworks.com/siloscape/"}], "id": "malware--4fbd565b-bf55-4ac7-80b4-b183a7b64b9c", "is_family": true, "modified": "2025-04-25T14:43:17.695Z", "name": "Siloscape", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Siloscape"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniel Prizmant, Palo Alto Networks", "Yuval Avrahami, Palo Alto Networks"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-743', 0, 103, '09-mitre-attack', 'retrieved', 'C560224F578474B2C93C85802DD24FE1D564D1BBF74D1AA70AC628DE452F3B15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
