VALUES ('doc-09-mitre-attack-p0-744', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T15:00:10.376Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RustyWater](https://attack.mitre.org/software/S9037) is a Rust-based implant used by [MuddyWater](https://attack.mitre.org/groups/G0069). Historically, [MuddyWater](https://attack.mitre.org/groups/G0069) has used PowerShell-based tools and [RustyWater](https://attack.mitre.org/software/S9037) reflects a shift in tooling, demonstrating better techniques for defense evasion and reverse engineering.(Citation: CloudSEK_RustyWater_Jan2026)", "external_references": [{"external_id": "S9037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9037"}, {"description": "(Citation: CloudSEK_RustyWater_Jan2026)", "source_name": "Archer RAT / RUSTRIC"}, {"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "RustyWater", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RustyWater", "Archer RAT / RUSTRIC"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-744', 0, 109, '09-mitre-attack', 'retrieved', '0E9603232DF2B9B2C6CB87586880A3E6CC88DF6CA914AD6E4AEDFB4F1A2A34FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
