VALUES ('doc-09-mitre-attack-p0-745', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-28T20:50:36.164Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackCat](https://attack.mitre.org/software/S1068) is ransomware written in Rust that has been offered via the Ransomware-as-a-Service (RaaS) model. First observed November 2021, [BlackCat](https://attack.mitre.org/software/S1068) has been used to target multiple sectors and organizations in various countries and regions in Africa, the Americas, Asia, Australia, and Europe.(Citation: Microsoft BlackCat Jun 2022)(Citation: Sophos BlackCat Jul 2022)(Citation: ACSC BlackCat Apr 2022)", "external_references": [{"external_id": "S1068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1068"}, {"description": "(Citation: ACSC BlackCat Apr 2022)", "source_name": "Noberus"}, {"description": "(Citation: Microsoft BlackCat Jun 2022)(Citation: ACSC BlackCat Apr 2022)", "source_name": "ALPHV"}, {"description": "Australian Cyber Security Centre. (2022, April 14). 2022-004: ACSC Ransomware Profile - ALPHV (aka BlackCat). Retrieved December 20, 2022.", "source_name": "ACSC BlackCat Apr 2022", "url": "https://www.cyber.gov.au/about-us/advisories/2022-004-acsc-ransomware-profile-alphv-aka-blackcat"}, {"description": "Brandt, Andrew. (2022, July 14). BlackCat ransomware attacks not merely a byproduct of bad luck. Retrieved December 20, 2022.", "source_name": "Sophos BlackCat Jul 2022", "url": "https://news.sophos.com/en-us/2022/07/14/blackcat-ransomware-attacks-not-merely-a-byproduct-of-bad-luck/"}, {"description": "Microsoft Defender Threat Intelligence. (2022, June 13). The many lives of BlackCat ransomware. Retrieved December 20, 2022.", "source_name": "Microsoft BlackCat Jun 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/06/13/the-many-lives-of-blackcat-ransomware/"}], "id": "malware--50c44c34-3abb-48ae-9433-a2337de5b0bc", "is_family": true, "modified": "2025-10-21T15:28:37.027Z", "name": "BlackCat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BlackCat", "ALPHV", "Noberus"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Josh Arenas, Trustwave Spiderlabs", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-745', 0, 217, '09-mitre-attack', 'retrieved', '23707A3B5B2763F691C48B641C4C3CACD25D9E08DB3763B8AC234AA20DF7BAE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
