VALUES ('doc-09-mitre-attack-p0-746', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-12T17:40:38.303Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Fysbis](https://attack.mitre.org/software/S0410) is a Linux-based backdoor used by [APT28](https://attack.mitre.org/groups/G0007) that dates back to at least 2014.(Citation: Fysbis Palo Alto Analysis)", "external_references": [{"external_id": "S0410", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0410"}, {"description": "Bryan Lee and Rob Downs. (2016, February 12). A Look Into Fysbis: Sofacy’s Linux Backdoor. Retrieved September 10, 2017.", "source_name": "Fysbis Palo Alto Analysis", "url": "https://researchcenter.paloaltonetworks.com/2016/02/a-look-into-fysbis-sofacys-linux-backdoor/"}], "id": "malware--50d6688b-0985-4f3d-8cbe-0c796b30703b", "is_family": true, "modified": "2024-04-11T02:29:45.766Z", "name": "Fysbis", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Fysbis"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-746', 0, 88, '09-mitre-attack', 'retrieved', '0E84CBFFE7C1DEFF07F0DDACF920AAAF8B8467AC7CAB9E3C81A6AAE6572208F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
