VALUES ('doc-09-mitre-attack-p0-747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-15T17:55:11.252Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IcedID](https://attack.mitre.org/software/S0483) is a modular banking malware designed to steal financial information that has been observed in the wild since at least 2017. [IcedID](https://attack.mitre.org/software/S0483) has been downloaded by [Emotet](https://attack.mitre.org/software/S0367) in multiple campaigns.(Citation: IBM IcedID November 2017)(Citation: Juniper IcedID June 2020)", "external_references": [{"external_id": "S0483", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0483"}, {"description": "Kessem, L., et al. (2017, November 13). New Banking Trojan IcedID Discovered by IBM X-Force Research. Retrieved July 14, 2020.", "source_name": "IBM IcedID November 2017", "url": "https://securityintelligence.com/new-banking-trojan-icedid-discovered-by-ibm-x-force-research/"}, {"description": "Kimayong, P. (2020, June 18). COVID-19 and FMLA Campaigns used to install new IcedID banking malware. Retrieved July 14, 2020.", "source_name": "Juniper IcedID June 2020", "url": "https://blogs.juniper.net/en-us/threat-research/covid-19-and-fmla-campaigns-used-to-install-new-icedid-banking-malware"}], "id": "malware--5147ef15-1cae-4707-8ea1-bee8d98b7f1d", "is_family": true, "modified": "2025-04-22T22:16:09.049Z", "name": "IcedID", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["IcedID"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jorge Orchilles", "Zaw Min Htun, @Z3TAE", "Matt Brenton, Zurich Global Information Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-747', 0, 150, '09-mitre-attack', 'retrieved', '92F21B7F0B0FF7DDEC0D8F4C88D00F9F89D8D5EDB92E5F1247647708ED68B1AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
