VALUES ('doc-09-mitre-attack-p0-748', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VERMIN](https://attack.mitre.org/software/S0257) is a remote access tool written in the Microsoft .NET framework. It is mostly composed of original code, but also has some open source code. (Citation: Unit 42 VERMIN Jan 2018)", "external_references": [{"external_id": "S0257", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0257"}, {"description": "(Citation: Unit 42 VERMIN Jan 2018)", "source_name": "VERMIN"}, {"description": "Lancaster, T., Cortes, J. (2018, January 29). VERMIN: Quasar RAT and Custom Malware Used In Ukraine. Retrieved July 5, 2018.", "source_name": "Unit 42 VERMIN Jan 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/01/unit42-vermin-quasar-rat-custom-malware-used-ukraine/"}], "id": "malware--5189f018-fea2-45d7-b0ed-23f9ee0a46f3", "is_family": true, "modified": "2024-04-10T22:17:02.480Z", "name": "VERMIN", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["VERMIN"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-748', 0, 112, '09-mitre-attack', 'retrieved', 'BFE3A11279B5DACCCC4EEE484C0A96454B611C1E1683070C46E8B8EFA92F7D02', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
