VALUES ('doc-09-mitre-attack-p0-749', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T19:09:26.355Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UBoatRAT](https://attack.mitre.org/software/S0333) is a remote access tool that was identified in May 2017.(Citation: PaloAlto UBoatRAT Nov 2017)", "external_references": [{"external_id": "S0333", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0333"}, {"description": "(Citation: PaloAlto UBoatRAT Nov 2017)", "source_name": "UBoatRAT"}, {"description": "Hayashi, K. (2017, November 28). UBoatRAT Navigates East Asia. Retrieved January 12, 2018.", "source_name": "PaloAlto UBoatRAT Nov 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/11/unit42-uboatrat-navigates-east-asia/"}], "id": "malware--518bb5f1-91f4-4ff2-b09d-5a94e1ebe95f", "is_family": true, "modified": "2024-04-10T22:22:03.759Z", "name": "UBoatRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["UBoatRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-749', 0, 87, '09-mitre-attack', 'retrieved', '2D7D710CA0D5C30A50EAE3A574990730F1DF135977063D318C6D3DD893D1682C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
