VALUES ('doc-09-mitre-attack-p0-751', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-08T15:49:02.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HTTPTroy](https://attack.mitre.org/software/S9007) is a highly obfuscated backdoor that facilitates collection, command and control, defense evasion and exfiltration. [HTTPTroy](https://attack.mitre.org/software/S9007) was first reported in October 2025. [HTTPTroy](https://attack.mitre.org/software/S9007) has been observed in operations attributed to DPRK-affiliated threat actors, including [Kimsuky](https://attack.mitre.org/groups/G0094). [HTTPTroy](https://attack.mitre.org/software/S9007) has been delivered to victims through a separate loader leveraged by [Kimsuky](https://attack.mitre.org/groups/G0094).(Citation: Gen Digital Kimsuky HTTPTroy October 2025)", "external_references": [{"external_id": "S9007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9007"}, {"description": "Alexndru-Cristian Bardas. (2025, October 30). DPRK’s Playbook: Kimsuky’s HttpTroy and Lazarus’s New BLINDINGCAN Variant. Retrieved April 8, 2026.", "source_name": "Gen Digital Kimsuky HTTPTroy October 2025", "url": "https://www.gendigital.com/blog/insights/research/dprk-kimsuky-lazarus-analysis"}], "id": "malware--52b52f72-88e6-4847-88d6-da3b9e4a4f71", "is_family": true, "modified": "2026-04-23T02:33:46.681Z", "name": "HTTPTroy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HTTPTroy"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-751', 0, 125, '09-mitre-attack', 'retrieved', '5420A74C9DDBD6AD7E877EBB3805802702AB69094692E8EB6804E1977AFB9150', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
