VALUES ('doc-09-mitre-attack-p0-752', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-28T17:48:36.547Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MarkiRAT](https://attack.mitre.org/software/S0652) is a remote access Trojan (RAT) compiled with Visual Studio that has been used by [Ferocious Kitten](https://attack.mitre.org/groups/G0137) since at least 2015.(Citation: Kaspersky Ferocious Kitten Jun 2021)", "external_references": [{"external_id": "S0652", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0652"}, {"description": "GReAT. (2021, June 16). Ferocious Kitten: 6 Years of Covert Surveillance in Iran. Retrieved September 22, 2021.", "source_name": "Kaspersky Ferocious Kitten Jun 2021", "url": "https://securelist.com/ferocious-kitten-6-years-of-covert-surveillance-in-iran/102806/"}], "id": "malware--532c6004-b1e8-415b-9516-f7c14ba783b1", "is_family": true, "modified": "2025-04-25T14:43:19.128Z", "name": "MarkiRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MarkiRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-752', 0, 108, '09-mitre-attack', 'retrieved', 'D7E295D0566681476C1DC31E9988AC1BD973C917B9E762765C3DD23A7BAC98C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
