VALUES ('doc-09-mitre-attack-p0-755', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NavRAT](https://attack.mitre.org/software/S0247) is a remote access tool designed to upload, download, and execute files. It has been observed in attacks targeting South Korea. (Citation: Talos NavRAT May 2018)", "external_references": [{"external_id": "S0247", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0247"}, {"description": "(Citation: Talos NavRAT May 2018)", "source_name": "NavRAT"}, {"description": "Mercer, W., Rascagneres, P. (2018, May 31). NavRAT Uses US-North Korea Summit As Decoy For Attacks In South Korea. Retrieved June 11, 2018.", "source_name": "Talos NavRAT May 2018", "url": "https://blog.talosintelligence.com/2018/05/navrat.html"}], "id": "malware--53a42597-1974-4b8e-84fd-3675e8992053", "is_family": true, "modified": "2025-04-25T14:43:20.237Z", "name": "NavRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NavRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-755', 0, 106, '09-mitre-attack', 'retrieved', '6709F71D9C5A921BBEA012FFB458ABA8AEB57E82FC69DA35B41E7C8F23A794FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
