VALUES ('doc-09-mitre-attack-p0-756', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T19:18:28.468Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkComet](https://attack.mitre.org/software/S0334) is a Windows remote administration tool and backdoor.(Citation: TrendMicro DarkComet Sept 2014)(Citation: Malwarebytes DarkComet March 2018)", "external_references": [{"external_id": "S0334", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0334"}, {"description": "(Citation: TrendMicro DarkComet Sept 2014)", "source_name": "DarkComet"}, {"description": "(Citation: TrendMicro DarkComet Sept 2014)", "source_name": "DarkKomet"}, {"description": "(Citation: TrendMicro DarkComet Sept 2014)", "source_name": "Fynloski"}, {"description": "(Citation: TrendMicro DarkComet Sept 2014)", "source_name": "Krademok"}, {"description": "(Citation: TrendMicro DarkComet Sept 2014)", "source_name": "FYNLOS"}, {"description": "Kujawa, A. (2018, March 27). You dirty RAT! Part 1: DarkComet. Retrieved November 6, 2018.", "source_name": "Malwarebytes DarkComet March 2018", "url": "https://blog.malwarebytes.com/threat-analysis/2012/06/you-dirty-rat-part-1-darkcomet/"}, {"description": "TrendMicro. (2014, September 03). DARKCOMET. Retrieved November 6, 2018.", "source_name": "TrendMicro DarkComet Sept 2014", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/DARKCOMET"}], "id": "malware--53ab35c2-d00e-491a-8753-41d35ae7e547", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "DarkComet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DarkComet", "DarkKomet", "Fynloski", "Krademok", "FYNLOS"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8