VALUES ('doc-09-mitre-attack-p0-759', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-12-22T20:03:48.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HUI Loader](https://attack.mitre.org/software/S1097) is a custom DLL loader that has been used since at least 2015 by China-based threat groups including [Cinnamon Tempest](https://attack.mitre.org/groups/G1021) and [menuPass](https://attack.mitre.org/groups/G0045) to deploy malware on compromised hosts. [HUI Loader](https://attack.mitre.org/software/S1097) has been observed in campaigns loading [SodaMaster](https://attack.mitre.org/software/S0627), [PlugX](https://attack.mitre.org/software/S0013), [Cobalt Strike](https://attack.mitre.org/software/S0154), [Komplex](https://attack.mitre.org/software/S0162), and several strains of ransomware.(Citation: SecureWorks BRONZE STARLIGHT Ransomware Operations June 2022)", "external_references": [{"external_id": "S1097", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1097"}, {"description": "Counter Threat Unit Research Team . (2022, June 23). BRONZE STARLIGHT RANSOMWARE OPERATIONS USE HUI LOADER. Retrieved December 7, 2023.", "source_name": "SecureWorks BRONZE STARLIGHT Ransomware Operations June 2022", "url": "https://www.secureworks.com/research/bronze-starlight-ransomware-operations-use-hui-loader"}], "id": "malware--54089fba-8662-4f37-9a44-6ad25a5f630a", "is_family": true, "modified": "2024-01-02T20:44:36.518Z", "name": "HUI Loader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HUI Loader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-759', 0, 130, '09-mitre-attack', 'retrieved', '2E82142281462E0D32807B6C80FF4E90AD04AD8A1B1B5E34A9D21E68CDA7B822', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
