VALUES ('doc-09-mitre-attack-p0-761', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-29T23:30:53.824Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ragnar Locker](https://attack.mitre.org/software/S0481) is a ransomware that has been in use since at least December 2019.(Citation: Sophos Ragnar May 2020)(Citation: Cynet Ragnar Apr 2020)", "external_references": [{"external_id": "S0481", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0481"}, {"description": "Gold, B. (2020, April 27). Cynet Detection Report: Ragnar Locker Ransomware. Retrieved June 29, 2020.", "source_name": "Cynet Ragnar Apr 2020", "url": "https://www.cynet.com/blog/cynet-detection-report-ragnar-locker-ransomware/"}, {"description": "SophosLabs. (2020, May 21). Ragnar Locker ransomware deploys virtual machine to dodge security. Retrieved June 29, 2020.", "source_name": "Sophos Ragnar May 2020", "url": "https://news.sophos.com/en-us/2020/05/21/ragnar-locker-ransomware-deploys-virtual-machine-to-dodge-security/"}], "id": "malware--54895630-efd2-4608-9c24-319de972a9eb", "is_family": true, "modified": "2025-04-16T20:38:08.233Z", "name": "Ragnar Locker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ragnar Locker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-761', 0, 115, '09-mitre-attack', 'retrieved', '244ACB3A10D14C2B3BA246FA7DBFC62F48187F2F36C60129C48642F0D0C2C66A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
