VALUES ('doc-09-mitre-attack-p0-762', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-24T13:23:45.162Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FatDuke](https://attack.mitre.org/software/S0512) is a backdoor used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2016.(Citation: ESET Dukes October 2019)", "external_references": [{"external_id": "S0512", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0512"}, {"description": "Faou, M., Tartare, M., Dupuy, T. (2019, October). OPERATION GHOST. Retrieved September 23, 2020.", "source_name": "ESET Dukes October 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Operation_Ghost_Dukes.pdf"}], "id": "malware--54a01db0-9fab-4d5f-8209-53cef8425f4a", "is_family": true, "modified": "2025-04-25T14:43:21.871Z", "name": "FatDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FatDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-762', 0, 79, '09-mitre-attack', 'retrieved', '8D0B8178C4096E3DD3CF16C21800B2F0A66FF947E575DBA06E8E50ED725D7796', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
