VALUES ('doc-09-mitre-attack-p0-765', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T17:48:35.006Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[zwShell](https://attack.mitre.org/software/S0350) is a remote access tool (RAT) written in Delphi that has been seen in the wild since the spring of 2010 and used by threat actors during [Night Dragon](https://attack.mitre.org/campaigns/C0002).(Citation: McAfee Night Dragon)", "external_references": [{"external_id": "S0350", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0350"}, {"description": "(Citation: McAfee Night Dragon)", "source_name": "zwShell"}, {"description": "McAfee® Foundstone® Professional Services and McAfee Labs™. (2011, February 10). Global Energy Cyberattacks: “Night Dragon”. Retrieved February 19, 2018.", "source_name": "McAfee Night Dragon", "url": "https://scadahacker.com/library/Documents/Cyber_Events/McAfee%20-%20Night%20Dragon%20-%20Global%20Energy%20Cyberattacks.pdf"}], "id": "malware--54e8672d-5338-4ad1-954a-a7c986bee530", "is_family": true, "modified": "2025-04-16T20:38:08.735Z", "name": "zwShell", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["zwShell"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-765', 0, 108, '09-mitre-attack', 'retrieved', '4E2A5DDDA1F24E3798D6E55140E443F8EF22AF164160F150724B6E9D29DE9CA7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
