VALUES ('doc-09-mitre-attack-p0-766', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:20.949Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zeroaccess](https://attack.mitre.org/software/S0027) is a kernel-mode [Rootkit](https://attack.mitre.org/techniques/T1014) that attempts to add victims to the ZeroAccess botnet, often for monetary gain. (Citation: Sophos ZeroAccess)", "external_references": [{"external_id": "S0027", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0027"}, {"description": "Wyke, J. (2012, April). ZeroAccess. Retrieved July 18, 2016.", "source_name": "Sophos ZeroAccess", "url": "https://sophosnews.files.wordpress.com/2012/04/zeroaccess2.pdf"}], "id": "malware--552462b9-ae79-49dd-855c-5973014e157f", "is_family": true, "modified": "2025-04-25T14:43:22.946Z", "name": "Zeroaccess", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-766', 0, 72, '09-mitre-attack', 'retrieved', 'F51285D1B72FE850D6E20E6C8D9DB1C72A0FBBDA587F3A18C1E1C2F7C26787F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
