VALUES ('doc-09-mitre-attack-p0-767', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-06T19:14:43.437Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GLASSTOKEN](https://attack.mitre.org/software/S1117) is a custom web shell used by threat actors during [Cutting Edge](https://attack.mitre.org/campaigns/C0029) to execute commands on compromised Ivanti Secure Connect VPNs.(Citation: Volexity Ivanti Zero-Day Exploitation January 2024)", "external_references": [{"external_id": "S1117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1117"}, {"description": "Meltzer, M. et al. (2024, January 10). Active Exploitation of Two Zero-Day Vulnerabilities in Ivanti Connect Secure VPN. Retrieved February 27, 2024.", "source_name": "Volexity Ivanti Zero-Day Exploitation January 2024", "url": "https://www.volexity.com/blog/2024/01/10/active-exploitation-of-two-zero-day-vulnerabilities-in-ivanti-connect-secure-vpn/"}], "id": "malware--554e010d-726b-439d-9a1a-f60fff0cc109", "is_family": true, "modified": "2025-04-15T19:46:34.213Z", "name": "GLASSTOKEN", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GLASSTOKEN"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-767', 0, 103, '09-mitre-attack', 'retrieved', 'B35D9B7D2B7B4C213FCF87A58BF10FC144BFA1A22B8879753A5D3ACE493D4881', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
