VALUES ('doc-09-mitre-attack-p0-768', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-11T22:31:31.468Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DCSrv](https://attack.mitre.org/software/S1033) is destructive malware that has been used by [Moses Staff](https://attack.mitre.org/groups/G1009) since at least September 2021. Though [DCSrv](https://attack.mitre.org/software/S1033) has ransomware-like capabilities, [Moses Staff](https://attack.mitre.org/groups/G1009) does not demand ransom or offer a decryption key.(Citation: Checkpoint MosesStaff Nov 2021)", "external_references": [{"external_id": "S1033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1033"}, {"description": "Checkpoint Research. (2021, November 15). Uncovering MosesStaff techniques: Ideology over Money. Retrieved August 11, 2022.", "source_name": "Checkpoint MosesStaff Nov 2021", "url": "https://research.checkpoint.com/2021/mosesstaff-targeting-israeli-companies/"}], "id": "malware--5633ffd3-81ef-4f98-8f93-4896b03998f0", "is_family": true, "modified": "2024-04-11T02:39:27.698Z", "name": "DCSrv", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DCSrv"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-768', 0, 116, '09-mitre-attack', 'retrieved', 'DC2D3853D0399D6F61FB6C5D60B3244AC7387F9052E1388CB7FFF2979E3A401F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
