VALUES ('doc-09-mitre-attack-p0-770', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-11T16:04:31.994Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOSTWRITE](https://attack.mitre.org/software/S0415) is a loader crafted to be launched via abuse of the DLL search order of applications used by [FIN7](https://attack.mitre.org/groups/G0046).(Citation: FireEye FIN7 Oct 2019)", "external_references": [{"external_id": "S0415", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0415"}, {"description": "Carr, N, et all. (2019, October 10). Mahalo FIN7: Responding to the Criminal Operators’ New Tools and Techniques. Retrieved October 11, 2019.", "source_name": "FireEye FIN7 Oct 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/10/mahalo-fin7-responding-to-new-tools-and-techniques.html"}], "id": "malware--56d10a7f-bb42-4267-9b4c-63abb9c06010", "is_family": true, "modified": "2024-04-11T02:48:51.475Z", "name": "BOOSTWRITE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BOOSTWRITE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-770', 0, 96, '09-mitre-attack', 'retrieved', 'DB5034923EBDC94D624BE76A19905DEDFE707F9F434F22FE251F75AC7B2D0CFE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
