VALUES ('doc-09-mitre-attack-p0-771', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T22:29:25.653Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rising Sun](https://attack.mitre.org/software/S0448) is a modular backdoor that was used extensively in [Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013) between 2017 and 2019. [Rising Sun](https://attack.mitre.org/software/S0448) infected at least 87 organizations around the world, including nuclear, defense, energy, and financial service companies. Security researchers assessed [Rising Sun](https://attack.mitre.org/software/S0448) included some source code from [Lazarus Group](https://attack.mitre.org/groups/G0032)''s Trojan Duuzer.(Citation: McAfee Sharpshooter December 2018)", "external_references": [{"external_id": "S0448", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0448"}, {"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "malware--56e6b6c2-e573-4969-8bab-783205cebbbf", "is_family": true, "modified": "2024-04-11T00:14:23.264Z", "name": "Rising Sun", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Rising Sun"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-771', 0, 126, '09-mitre-attack', 'retrieved', 'E797599A2C826073F1329D785C5EFD6BF4FF088E85149A398536A18451471053', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
