VALUES ('doc-09-mitre-attack-p0-772', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:47.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ASPXSpy](https://attack.mitre.org/software/S0073) is a Web shell. It has been modified by [Threat Group-3390](https://attack.mitre.org/groups/G0027) actors to create the ASPXTool version. (Citation: Dell TG-3390)", "external_references": [{"external_id": "S0073", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0073"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}], "id": "malware--56f46b17-8cfa-46c0-b501-dd52fef394e2", "is_family": true, "modified": "2024-05-22T19:06:12.701Z", "name": "ASPXSpy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ASPXSpy", "ASPXTool"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-772', 0, 90, '09-mitre-attack', 'retrieved', '98DF96CB19C444CC67A8E645DFCDF8B3E82251E1CA6CA5035A2174C7E6BB48E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
