INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-773', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T15:02:14.907Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NotPetya](https://attack.mitre.org/software/S0368) is malware that was used by [Sandworm Team](https://attack.mitre.org/groups/G0034) in a worldwide attack starting on June 27, 2017. While [NotPetya](https://attack.mitre.org/software/S0368) appears as a form of ransomware, its main purpose was to destroy data and disk structures on compromised systems; the attackers never intended to make the encrypted data recoverable. As such, [NotPetya](https://attack.mitre.org/software/S0368) may be more appropriately thought of as a form of wiper malware. [NotPetya](https://attack.mitre.org/software/S0368) contains worm-like features to spread itself across a computer network using the SMBv1 exploits EternalBlue and EternalRomance.(Citation: Talos Nyetya June 2017)(Citation: US-CERT NotPetya 2017)(Citation: ESET Telebots June 2017)(Citation: US District Court Indictment GRU Unit 74455 October 2020)", "external_references": [{"external_id": "S0368", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0368"}, {"description": "(Citation: ESET Telebots June 2017)", "source_name": "ExPetr"}, {"description": "(Citation: ESET Telebots June 2017)", "source_name": "Diskcoder.C"}, {"description": "(Citation: Talos Nyetya June 2017)", "source_name": "GoldenEye"}, {"description": "(Citation: Talos Nyetya June 2017)", "source_name": "Nyetya"}, {"description": "(Citation: Talos Nyetya June 2017)(Citation: ESET Telebots June 2017)", "source_name": "Petrwrap"}, {"description": "Cherepanov, A.. (2017, June 30). TeleBots are back: Supply chain attacks against Ukraine. Retrieved June 11, 2020.", "source_name": "ESET Telebots June 2017", "url": "https://www.welivesecurity.com/2017/06/30/telebots-back-supply-chain-attacks-against-ukraine/"}, {"description": "Chiu, A. (2016, June 27). New Ransomware Variant \"Nyetya\" Compromises Systems Worldwide. Retrieved March 26, 2019.", "source_name": "Talos Nyetya June 2017", "url": "https://blog.talosintelligence.com/2017/06/worldwide-ransomware-variant.html"}, {"description": "Scott W. Brady. (2020, October 15). United States vs. Yuriy Sergeyevich Andrienko et al.. Retrieved November 25, 2020.", "source_name": "US District Court Indictment GRU Unit 74455 October 2020", "url": "https://www.justice.gov/opa/press-release/file/1328521/download"}, {"description": "US-CERT. (2017, July 1). Alert (TA17-181A): Petya Ransomware. Retrieved March 15, 2019.", "source_name": "US-CERT NotPetya 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-181A"}], "id": "malware--5719af9d-6b16-46f9-9b28-fb019541ddbb", "is_family": true, "modified": "2025-04-16T20:38:09.202Z", "name": "NotPetya", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NotPetya", "ExPetr", "Diskcoder.C", "GoldenEye", "Petrwrap", "Nyetya"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-773', 0, 293, '09-mitre-attack', 'retrieved', 'F7D5135B98546D80350561225F1F021D83FC28481388C6DD1C3C2907DAD00EF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
