VALUES ('doc-09-mitre-attack-p0-775', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-01T18:36:54.260Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chrommme](https://attack.mitre.org/software/S0667) is a backdoor tool written using the Microsoft Foundation Class (MFC) framework that was first reported in June 2021; security researchers noted infrastructure overlaps with [Gelsemium](https://attack.mitre.org/software/S0666) malware.(Citation: ESET Gelsemium June 2021)", "external_references": [{"external_id": "S0667", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0667"}, {"description": "Dupuy, T. and Faou, M. (2021, June). Gelsemium. Retrieved November 30, 2021.", "source_name": "ESET Gelsemium June 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/06/eset_gelsemium.pdf"}], "id": "malware--579607c2-d046-40df-99ab-beb479c37a2a", "is_family": true, "modified": "2024-04-11T02:45:43.666Z", "name": "Chrommme", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Chrommme"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-775', 0, 94, '09-mitre-attack', 'retrieved', '24E5405BB1130B71D3424CBE4F56CEC89B30EBEFD99B77F579AA3AC5FA16CBA5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
