VALUES ('doc-09-mitre-attack-p0-776', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-26T18:49:41.155Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BADFLICK](https://attack.mitre.org/software/S0642) is a backdoor used by [Leviathan](https://attack.mitre.org/groups/G0065) in spearphishing campaigns first reported in 2018 that targeted the U.S. engineering and maritime industries.(Citation: FireEye Periscope March 2018)(Citation: Accenture MUDCARP March 2019)", "external_references": [{"external_id": "S0642", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0642"}, {"description": "FireEye. (2018, March 16). Suspected Chinese Cyber Espionage Group (TEMP.Periscope) Targeting U.S. Engineering and Maritime Industries. Retrieved April 11, 2018.", "source_name": "FireEye Periscope March 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/03/suspected-chinese-espionage-group-targeting-maritime-and-engineering-industries.html"}, {"description": "Accenture iDefense Unit. (2019, March 5). Mudcarp''s Focus on Submarine Technologies. Retrieved August 24, 2021.", "source_name": "Accenture MUDCARP March 2019", "url": "https://www.accenture.com/us-en/blogs/cyber-defense/mudcarps-focus-on-submarine-technologies"}], "id": "malware--57d83eac-a2ea-42b0-a7b2-c80c55157790", "is_family": true, "modified": "2025-04-25T14:43:25.093Z", "name": "BADFLICK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BADFLICK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-776', 0, 121, '09-mitre-attack', 'retrieved', '84A47451E1E0B7D94C7F69145AFCC7F828613F70E9AC48E3338B86F5ABA1ED7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
