VALUES ('doc-09-mitre-attack-p0-777', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-08T19:53:27.937Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ObliqueRAT](https://attack.mitre.org/software/S0644) is a remote access trojan, similar to [Crimson](https://attack.mitre.org/software/S0115), that has been in use by [Transparent Tribe](https://attack.mitre.org/groups/G0134) since at least 2020.(Citation: Talos Oblique RAT March 2021)(Citation: Talos Transparent Tribe May 2021)", "external_references": [{"external_id": "S0644", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0644"}, {"description": "Malhotra, A. (2021, March 2). ObliqueRAT returns with new campaign using hijacked websites. Retrieved September 2, 2021.", "source_name": "Talos Oblique RAT March 2021", "url": "https://blog.talosintelligence.com/2021/02/obliquerat-new-campaign.html"}, {"description": "Malhotra, A. et al. (2021, May 13). Transparent Tribe APT expands its Windows malware arsenal. Retrieved September 2, 2021.", "source_name": "Talos Transparent Tribe May 2021", "url": "https://blog.talosintelligence.com/2021/05/transparent-tribe-infra-and-targeting.html"}], "id": "malware--5864e59f-eb4c-43ad-83b2-b5e4fae056c9", "is_family": true, "modified": "2025-04-25T14:43:25.456Z", "name": "ObliqueRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ObliqueRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-777', 0, 125, '09-mitre-attack', 'retrieved', 'F803CE356F418CE3F99DB1BD3B7E8F184A241A4417E8C8288ADD2C7812C2166A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
