VALUES ('doc-09-mitre-attack-p0-778', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:42.754Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SHOTPUT](https://attack.mitre.org/software/S0063) is a custom backdoor used by [APT3](https://attack.mitre.org/groups/G0022). (Citation: FireEye Clandestine Wolf)", "external_references": [{"external_id": "S0063", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0063"}, {"description": "(Citation: FireEye Clandestine Fox Part 2)", "source_name": "Backdoor.APT.CookieCutter"}, {"description": "(Citation: FireEye Clandestine Fox Part 2)", "source_name": "Pirpi"}, {"description": "Eng, E., Caselden, D.. (2015, June 23). Operation Clandestine Wolf – Adobe Flash Zero-Day in APT3 Phishing Campaign. Retrieved January 14, 2016.", "source_name": "FireEye Clandestine Wolf", "url": "https://www.fireeye.com/blog/threat-research/2015/06/operation-clandestine-wolf-adobe-flash-zero-day.html"}, {"description": "Scott, M.. (2014, June 10). Clandestine Fox, Part Deux. Retrieved January 14, 2016.", "source_name": "FireEye Clandestine Fox Part 2", "url": "https://www.fireeye.com/blog/threat-research/2014/06/clandestine-fox-part-deux.html"}], "id": "malware--58adaaa8-f1e8-4606-9a08-422e568461eb", "is_family": true, "modified": "2025-04-25T14:43:25.821Z", "name": "SHOTPUT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SHOTPUT", "Backdoor.APT.CookieCutter", "Pirpi"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-778', 0, 123, '09-mitre-attack', 'retrieved', 'A80838BB913781658980FC201F5C52E43AE9AD86E4F4FF81C52ACB4B3A4836FD', 'v1', '{"