VALUES ('doc-09-mitre-attack-p0-779', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-23T19:38:33.073Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Avaddon](https://attack.mitre.org/software/S0640) is ransomware written in C++ that has been offered as Ransomware-as-a-Service (RaaS) since at least June 2020.(Citation: Awake Security Avaddon)(Citation: Arxiv Avaddon Feb 2021)", "external_references": [{"external_id": "S0640", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0640"}, {"description": "Gahlot, A. (n.d.). Threat Hunting for Avaddon Ransomware. Retrieved August 19, 2021.", "source_name": "Awake Security Avaddon", "url": "https://awakesecurity.com/blog/threat-hunting-for-avaddon-ransomware/"}, {"description": "Yuste, J. Pastrana, S. (2021, February 9). Avaddon ransomware: an in-depth analysis and decryption of infected systems. Retrieved August 19, 2021.", "source_name": "Arxiv Avaddon Feb 2021", "url": "https://arxiv.org/pdf/2102.04796.pdf"}], "id": "malware--58c5a3a1-928f-4094-9e98-a5a4e56dd5f3", "is_family": true, "modified": "2025-04-25T14:43:26.180Z", "name": "Avaddon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Avaddon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Matt Brenton, Zurich Global Information Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-779', 0, 120, '09-mitre-attack', 'retrieved', 'F66886C00B8CDA2BE824704260DFF125B4EFC33514FF900181C78738E9F3415E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
