VALUES ('doc-09-mitre-attack-p0-780', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-23T20:50:32.845Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Conficker](https://attack.mitre.org/software/S0608) is a computer worm first detected in October 2008 that targeted Microsoft Windows using the MS08-067 Windows vulnerability to spread.(Citation: SANS Conficker) In 2016, a variant of [Conficker](https://attack.mitre.org/software/S0608) made its way on computers and removable disk drives belonging to a nuclear power plant.(Citation: Conficker Nuclear Power Plant)", "external_references": [{"external_id": "S0608", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0608"}, {"description": "(Citation: SANS Conficker) ", "source_name": "Kido"}, {"description": "(Citation: SANS Conficker) ", "source_name": "Downadup"}, {"description": "Burton, K. (n.d.). The Conficker Worm. Retrieved February 18, 2021.", "source_name": "SANS Conficker", "url": "https://web.archive.org/web/20200125132645/https://www.sans.org/security-resources/malwarefaq/conficker-worm"}, {"description": "Cimpanu, C. (2016, April 26). Malware Shuts Down German Nuclear Power Plant on Chernobyl''s 30th Anniversary. Retrieved February 18, 2021.", "source_name": "Conficker Nuclear Power Plant", "url": "https://news.softpedia.com/news/on-chernobyl-s-30th-anniversary-malware-shuts-down-german-nuclear-power-plant-503429.shtml"}], "id": "malware--58eddbaf-7416-419a-ad7b-e65b9d4c3b55", "is_family": true, "modified": "2025-04-16T20:38:10.239Z", "name": "Conficker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Conficker", "Kido", "Downadup"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-780', 0, 151, '09-mitre-attack', 'retrieved', '6C234DA89F694A371D7E88A764FFE992653A9CE78BEE70BB702D050863374BF5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
