VALUES ('doc-09-mitre-attack-p0-781', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-22T19:21:30.424Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SocGholish](https://attack.mitre.org/software/S1124) is a JavaScript-based loader malware that has been used since at least 2017. It has been observed in use against multiple sectors globally for initial access, primarily through drive-by-downloads masquerading as software updates. SocGholish is operated by [Mustard Tempest](https://attack.mitre.org/groups/G1020) and its access has been sold to groups including [Indrik Spider](https://attack.mitre.org/groups/G0119) for downloading secondary RAT and ransomware payloads.(Citation: SentinelOne SocGholish Infrastructure November 2022)(Citation: SocGholish-update)(Citation: Red Canary SocGholish March 2024)(Citation: Secureworks Gold Prelude Profile) ", "external_references": [{"external_id": "S1124", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1124"}, {"description": "(Citation: Red Canary SocGholish March 2024)", "source_name": "FakeUpdates"}, {"description": "Andrew Northern. (2022, November 22). SocGholish, a very real threat from a very fake update. Retrieved February 13, 2024.", "source_name": "SocGholish-update", "url": "https://www.proofpoint.com/us/blog/threat-insight/part-1-socgholish-very-real-threat-very-fake-update"}, {"description": "Milenkoski, A. (2022, November 7). SocGholish Diversifies and Expands Its Malware Staging Infrastructure to Counter Defenders. Retrieved March 22, 2024.", "source_name": "SentinelOne SocGholish Infrastructure November 2022", "url": "https://www.sentinelone.com/labs/socgholish-diversifies-and-expands-its-malware-staging-infrastructure-to-counter-defenders/"}, {"description": "Red Canary. (2024, March). Red Canary 2024 Threat Detection Report: SocGholish. Retrieved March 22, 2024.", "source_name": "Red Canary SocGholish March 2024", "url": "https://redcanary.com/threat-detection-report/threats/socgholish/"}, {"description": "Secureworks. (n.d.). GOLD PRELUDE . Retrieved March 22, 2024.", "source_name": "Secureworks Gold Prelude Profile", "url": "https://www.secureworks.com/research/threat-profiles/gold-prelude"}], "id": "malware--5911d2ca-64f6-49b3-b94f-29b5d185085c", "is_family": true, "modified": "2024-04-06T00:08:07.956Z", "name": "SocGholish", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SocGholish", "FakeUpdates"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-781', 0, 220, '09-mitre-attack', 'retrieved', 'A18D9802A9081211AD2D099C4538592AA83BDAFEB0A27287FA9DDB3AB59083E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
