VALUES ('doc-09-mitre-attack-p0-782', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T14:58:24.832Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Flagpro](https://attack.mitre.org/software/S0696) is a Windows-based, first-stage downloader that has been used by [BlackTech](https://attack.mitre.org/groups/G0098) since at least October 2020. It has primarily been used against defense, media, and communications companies in Japan.(Citation: NTT Security Flagpro new December 2021) ", "external_references": [{"external_id": "S0696", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0696"}, {"description": "Hada, H. (2021, December 28). Flagpro The new malware used by BlackTech. Retrieved March 25, 2022.", "source_name": "NTT Security Flagpro new December 2021", "url": "https://insight-jp.nttsecurity.com/post/102hf3q/flagpro-the-new-malware-used-by-blacktech"}], "id": "malware--592260fb-dd5c-4a30-8d99-106a0485be0d", "is_family": true, "modified": "2025-04-25T19:04:04.232Z", "name": "Flagpro", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Flagpro"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Hannah S"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-782', 0, 108, '09-mitre-attack', 'retrieved', '7B4AB18EC1C65063A883F27A712D08BC3FB8C6335AD2965497110A9B707C655C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
