VALUES ('doc-09-mitre-attack-p0-783', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:56.860Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hi-Zor](https://attack.mitre.org/software/S0087) is a remote access tool (RAT) that has characteristics similar to [Sakula](https://attack.mitre.org/software/S0074). It was used in a campaign named INOCNATION. (Citation: Fidelis Hi-Zor)", "external_references": [{"external_id": "S0087", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0087"}, {"description": "Fidelis Threat Research Team. (2016, January 27). Introducing Hi-Zor RAT. Retrieved March 24, 2016.", "source_name": "Fidelis Hi-Zor", "url": "https://www.fidelissecurity.com/threatgeek/archive/introducing-hi-zor-rat/"}], "id": "malware--5967cc93-57c9-404a-8ffd-097edfa7bdfc", "is_family": true, "modified": "2024-04-11T02:20:26.551Z", "name": "Hi-Zor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hi-Zor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-783', 0, 86, '09-mitre-attack', 'retrieved', '75B58EAF260FB11173B3BEE969840CEF24269C176B8A99B2EE5253F09557CA4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
