VALUES ('doc-09-mitre-attack-p0-784', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-21T14:55:00.996Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SpicyOmelette](https://attack.mitre.org/software/S0646) is a JavaScript based remote access tool that has been used by [Cobalt Group](https://attack.mitre.org/groups/G0080) since at least 2018.(Citation: Secureworks GOLD KINGSWOOD September 2018)", "external_references": [{"external_id": "S0646", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0646"}, {"description": "CTU. (2018, September 27). Cybercriminals Increasingly Trying to Ensnare the Big Financial Fish. Retrieved September 20, 2021.", "source_name": "Secureworks GOLD KINGSWOOD September 2018", "url": "https://www.secureworks.com/blog/cybercriminals-increasingly-trying-to-ensnare-the-big-financial-fish"}], "id": "malware--599cd7b5-37b5-4cdd-8174-2811531ce9d0", "is_family": true, "modified": "2025-04-25T14:43:27.242Z", "name": "SpicyOmelette", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SpicyOmelette"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-784', 0, 90, '09-mitre-attack', 'retrieved', '01C6D3BEB4B3B717DCD4730365CE41AD43028B5C9C0BBAD2CD21AB2279B0D5FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
