VALUES ('doc-09-mitre-attack-p0-785', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XAgentOSX](https://attack.mitre.org/software/S0161) is a trojan that has been used by [APT28](https://attack.mitre.org/groups/G0007) on OS X and appears to be a port of their standard [CHOPSTICK](https://attack.mitre.org/software/S0023) or XAgent trojan. (Citation: XAgentOSX 2017)", "external_references": [{"external_id": "S0161", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0161"}, {"description": "(Citation: XAgentOSX 2017)", "source_name": "XAgentOSX"}, {"description": "(Citation: Symantec APT28 Oct 2018)", "source_name": "OSX.Sofacy"}, {"description": "Robert Falcone. (2017, February 14). XAgentOSX: Sofacy''s Xagent macOS Tool. Retrieved July 12, 2017.", "source_name": "XAgentOSX 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit42-xagentosx-sofacys-xagent-macos-tool/"}, {"description": "Symantec Security Response. (2018, October 04). APT28: New Espionage Operations Target Military and Government Organizations. Retrieved November 14, 2018.", "source_name": "Symantec APT28 Oct 2018", "url": "https://www.symantec.com/blogs/election-security/apt28-espionage-military-government"}], "id": "malware--59a97b15-8189-4d51-9404-e1ce8ea4a069", "is_family": true, "modified": "2025-04-25T14:43:27.602Z", "name": "XAgentOSX", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["XAgentOSX", "OSX.Sofacy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-785', 0, 131, '09-mitre-attack', 'retrieved', '6F4768F02800230E5D2BC480CEE14B65EB1691A4A586C56444B86DAE7D5F82B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
