VALUES ('doc-09-mitre-attack-p0-786', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-21T20:55:40.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Green Lambert](https://attack.mitre.org/software/S0690) is a modular backdoor that security researchers assess has been used by an advanced threat group referred to as Longhorn and The Lamberts. First reported in 2017, the Windows variant of [Green Lambert](https://attack.mitre.org/software/S0690) may have been used as early as 2008; a macOS version was uploaded to a multiscanner service in September 2014.(Citation: Kaspersky Lamberts Toolkit April 2017)(Citation: Objective See Green Lambert for OSX Oct 2021) ", "external_references": [{"external_id": "S0690", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0690"}, {"description": "(Citation: Kaspersky Lamberts Toolkit April 2017)", "source_name": "Green Lambert"}, {"description": "GREAT. (2017, April 11). Unraveling the Lamberts Toolkit. Retrieved March 21, 2022.", "source_name": "Kaspersky Lamberts Toolkit April 2017", "url": "https://securelist.com/unraveling-the-lamberts-toolkit/77990/"}, {"description": "Sandvik, Runa. (2021, October 1). Made In America: Green Lambert for OS X. Retrieved March 21, 2022.", "source_name": "Objective See Green Lambert for OSX Oct 2021", "url": "https://objective-see.com/blog/blog_0x68.html"}], "id": "malware--59c8a28c-200c-4565-9af1-cbdb24870ba0", "is_family": true, "modified": "2025-04-16T20:38:10.718Z", "name": "Green Lambert", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Green Lambert"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Runa Sandvik"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "iOS", "macOS", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-786', 0, 179, '09-mitre-attack', 'retrieved', '3FBDC5329560680DE16E528712FA85F70ED4A4B0473A2BB5343349342538853F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
