VALUES ('doc-09-mitre-attack-p0-788', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T20:59:11.460Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SnappyTCP](https://attack.mitre.org/software/S1163) is a web shell used by [Sea Turtle](https://attack.mitre.org/groups/G1041) between 2021 and 2023 against multiple victims. [SnappyTCP](https://attack.mitre.org/software/S1163) appears to be based on a public GitHub project that has since been removed from the code-sharing site. [SnappyTCP](https://attack.mitre.org/software/S1163) includes a simple reverse TCP shell for Linux and Unix environments with basic command and control capabilities.(Citation: PWC Sea Turtle 2023)", "external_references": [{"external_id": "S1163", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1163"}, {"description": "PwC Threat Intelligence. (2023, December 5). The Tortoise and The Malware. Retrieved November 20, 2024.", "source_name": "PWC Sea Turtle 2023", "url": "https://www.pwc.com/gx/en/issues/cybersecurity/cyber-threat-intelligence/tortoise-and-malwahare.html"}], "id": "malware--5a6fa62e-4ddf-4ae3-974a-f17f24058350", "is_family": true, "modified": "2025-01-07T16:01:34.817Z", "name": "SnappyTCP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SnappyTCP"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-788', 0, 122, '09-mitre-attack', 'retrieved', '7429DE246442638B15D6880B1AB99ECC82CB2B7C0C3F875F6E43A71AAD6B9FFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
