VALUES ('doc-09-mitre-attack-p0-789', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:20.137Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CALENDAR](https://attack.mitre.org/software/S0025) is malware used by [APT1](https://attack.mitre.org/groups/G0006) that mimics legitimate Gmail Calendar traffic. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0025"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "malware--5a84dc36-df0d-4053-9b7c-f0c388a57283", "is_family": true, "modified": "2025-04-25T14:43:28.496Z", "name": "CALENDAR", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CALENDAR"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-789', 0, 75, '09-mitre-attack', 'retrieved', 'F6753626D55738D2026658AE0FEA72F807C1A0573F8FC410EBDF8EC8BF7C6740', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
