VALUES ('doc-09-mitre-attack-p0-790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-16T19:00:49.435Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockerGoga](https://attack.mitre.org/software/S0372) is ransomware that was first reported in January 2019, and has been tied to various attacks on European companies, including industrial and manufacturing firms.(Citation: Unit42 LockerGoga 2019)(Citation: CarbonBlack LockerGoga 2019)", "external_references": [{"external_id": "S0372", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0372"}, {"description": "CarbonBlack Threat Analysis Unit. (2019, March 22). TAU Threat Intelligence Notification – LockerGoga Ransomware. Retrieved April 16, 2019.", "source_name": "CarbonBlack LockerGoga 2019", "url": "https://www.carbonblack.com/2019/03/22/tau-threat-intelligence-notification-lockergoga-ransomware/"}, {"description": "Harbison, M. (2019, March 26). Born This Way? Origins of LockerGoga. Retrieved April 16, 2019.", "source_name": "Unit42 LockerGoga 2019", "url": "https://unit42.paloaltonetworks.com/born-this-way-origins-of-lockergoga/"}], "id": "malware--5af7a825-2d9f-400d-931a-e00eb9e27f48", "is_family": true, "modified": "2026-05-12T15:12:00.733Z", "name": "LockerGoga", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LockerGoga"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Joe Slowik - Dragos"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-790', 0, 126, '09-mitre-attack', 'retrieved', 'C0E366E5B6AC0C0312599DBC2E3F03A9899AEFE92D13F63196C61C08C95361B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
