VALUES ('doc-09-mitre-attack-p0-791', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-03T20:41:46.276Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "First observed in 2018, LightSpy is a modular malware family that initially targeted iOS devices in Southern Asia before expanding to Android and macOS platforms. It consists of a downloader, a main executable that manages network communications, and functionality-specific modules, typically implemented as `.dylib` files (iOS, macOS) or `.apk` files (Android). LightSpy can collect VoIP call recordings, SMS messages, and credential stores, which are then exfiltrated to a command and control (C2) server.(Citation: MelikovBlackBerry LightSpy 2024) ", "external_references": [{"external_id": "S1185", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1185"}, {"description": "Melikov, D. (2024, April 11). LightSpy Returns: Renewed Espionage Campaign Targets Southern Asia, Possibly India. Retrieved January 14, 2025.", "source_name": "MelikovBlackBerry LightSpy 2024", "url": "https://blogs.blackberry.com/en/2024/04/lightspy-returns-renewed-espionage-campaign-targets-southern-asia-possibly-india"}], "id": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "is_family": true, "modified": "2025-04-15T18:40:23.781Z", "name": "LightSpy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LightSpy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Alden Schmidt", "Dmitry Bestuzhev"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Android", "Windows", "iOS", "macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-791', 0, 154, '09-mitre-attack', 'retrieved', '524C71273DBDAEFE652DC99F08CE8F6AE7981A772AAB51268C15C3A84442A07F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
