INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-792', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chaos](https://attack.mitre.org/software/S0220) is Linux malware that compromises systems by brute force attacks against SSH services. Once installed, it provides a reverse shell to its controllers, triggered by unsolicited packets. (Citation: Chaos Stolen Backdoor)", "external_references": [{"external_id": "S0220", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0220"}, {"description": "(Citation: Chaos Stolen Backdoor)", "source_name": "Chaos"}, {"description": "Sebastian Feldmann. (2018, February 14). Chaos: a Stolen Backdoor Rising Again. Retrieved March 5, 2018.", "source_name": "Chaos Stolen Backdoor", "url": "http://gosecure.net/2018/02/14/chaos-stolen-backdoor-rising/"}], "id": "malware--5bcd5511-6756-4824-a692-e8bb109364af", "is_family": true, "modified": "2025-04-25T14:43:29.227Z", "name": "Chaos", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Chaos"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-792', 0, 101, '09-mitre-attack', 'retrieved', '31067DF835DDBCE75286E4AA25142BFB891B1D49441D636C1FD016C94C7BABF5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
