VALUES ('doc-09-mitre-attack-p0-793', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ISMInjector](https://attack.mitre.org/software/S0189) is a Trojan used to install another [OilRig](https://attack.mitre.org/groups/G0049) backdoor, ISMAgent. (Citation: OilRig New Delivery Oct 2017)", "external_references": [{"external_id": "S0189", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0189"}, {"description": "(Citation: OilRig New Delivery Oct 2017)", "source_name": "ISMInjector"}, {"description": "Falcone, R. and Lee, B. (2017, October 9). OilRig Group Steps Up Attacks with New Delivery Documents and New Injector Trojan. Retrieved January 8, 2018.", "source_name": "OilRig New Delivery Oct 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/10/unit42-oilrig-group-steps-attacks-new-delivery-documents-new-injector-trojan/"}], "id": "malware--5be33fef-39c0-4532-84ee-bea31e1b5324", "is_family": true, "modified": "2025-04-25T14:43:29.589Z", "name": "ISMInjector", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ISMInjector"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Robert Falcone"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-793', 0, 103, '09-mitre-attack', 'retrieved', '2DC53FA7C749AEA219AC2C5D260F537C1F54FBF785506063A90B705527F785AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
