VALUES ('doc-09-mitre-attack-p0-794', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PUNCHBUGGY](https://attack.mitre.org/software/S0196) is a backdoor malware used by [FIN8](https://attack.mitre.org/groups/G0061) that has been observed targeting POS networks in the hospitality industry. (Citation: Morphisec ShellTea June 2019)(Citation: FireEye Fin8 May 2016) (Citation: FireEye Know Your Enemy FIN8 Aug 2016)", "external_references": [{"external_id": "S0196", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0196"}, {"description": "(Citation: FireEye Fin8 May 2016) (Citation: FireEye Know Your Enemy FIN8 Aug 2016)", "source_name": "PUNCHBUGGY"}, {"description": "(Citation: Morphisec ShellTea June 2019)", "source_name": "ShellTea"}, {"description": "Elovitz, S. & Ahl, I. (2016, August 18). Know Your Enemy: New Financially-Motivated & Spear-Phishing Group. Retrieved February 26, 2018.", "source_name": "FireEye Know Your Enemy FIN8 Aug 2016", "url": "https://www2.fireeye.com/WBNR-Know-Your-Enemy-UNC622-Spear-Phishing.html"}, {"description": "Gorelik, M.. (2019, June 10). SECURITY ALERT: FIN8 IS BACK IN BUSINESS, TARGETING THE HOSPITALITY INDUSTRY. Retrieved June 13, 2019.", "source_name": "Morphisec ShellTea June 2019", "url": "http://blog.morphisec.com/security-alert-fin8-is-back"}, {"description": "Kizhakkinan, D., et al. (2016, May 11). Threat Actor Leverages Windows Zero-day Exploit in Payment Card Data Attacks. Retrieved February 12, 2018.", "source_name": "FireEye Fin8 May 2016", "url": "https://www.fireeye.com/blog/threat-research/2016/05/windows-zero-day-payment-cards.html"}], "id": "malware--5c6ed2dc-37f4-40ea-b2e1-4c76140a388c", "is_family": true, "modified": "2025-04-16T20:38:11.382Z", "name": "PUNCHBUGGY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PUNCHBUGGY", "ShellTea"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-794', 0, 192, '09-mitre-attack', 'retrieved', '59DEA027E651E98D7A45C4484852EBA5F606B399CD96B91ACE1C2CA0D5436602', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
