VALUES ('doc-09-mitre-attack-p0-797', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-24T15:56:18.522Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CostaBricks](https://attack.mitre.org/software/S0614) is a loader that was used to deploy 32-bit backdoors in the [CostaRicto](https://attack.mitre.org/groups/G0132) campaign.(Citation: BlackBerry CostaRicto November 2020)", "external_references": [{"external_id": "S0614", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0614"}, {"description": "The BlackBerry Research and Intelligence Team. (2020, November 12). The CostaRicto Campaign: Cyber-Espionage Outsourced. Retrieved May 24, 2021.", "source_name": "BlackBerry CostaRicto November 2020", "url": "https://blogs.blackberry.com/en/2020/11/the-costaricto-campaign-cyber-espionage-outsourced"}], "id": "malware--5d342981-5194-41e7-b33f-8e91998d7d88", "is_family": true, "modified": "2025-04-16T20:38:11.736Z", "name": "CostaBricks", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CostaBricks"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-797', 0, 87, '09-mitre-attack', 'retrieved', 'C3D01C873F7094AB28D670EA8A3B1E46F2ED737821B0C60D21C46FAB564E53DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
