VALUES ('doc-09-mitre-attack-p0-798', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-12-18T20:24:33.641Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cheerscrypt](https://attack.mitre.org/software/S1096) is a ransomware that was developed by [Cinnamon Tempest](https://attack.mitre.org/groups/G1021) and has been used in attacks against ESXi and Windows environments since at least 2022. [Cheerscrypt](https://attack.mitre.org/software/S1096) was derived from the leaked [Babuk](https://attack.mitre.org/software/S0638) source code and has infrastructure overlaps with deployments of Night Sky ransomware, which was also derived from [Babuk](https://attack.mitre.org/software/S0638).(Citation: Sygnia Emperor Dragonfly October 2022)(Citation: Trend Micro Cheerscrypt May 2022)", "external_references": [{"external_id": "S1096", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1096"}, {"description": "Biderman, O. et al. (2022, October 3). REVEALING EMPEROR DRAGONFLY: NIGHT SKY AND CHEERSCRYPT - A SINGLE RANSOMWARE GROUP. Retrieved December 6, 2023.", "source_name": "Sygnia Emperor Dragonfly October 2022", "url": "https://blog.sygnia.co/revealing-emperor-dragonfly-a-chinese-ransomware-group"}, {"description": "Dela Cruz, A. et al. (2022, May 25). New Linux-Based Ransomware Cheerscrypt Targeting ESXi Devices Linked to Leaked Babuk Source Code. Retrieved December 19, 2023.", "source_name": "Trend Micro Cheerscrypt May 2022", "url": "https://www.trendmicro.com/en_se/research/22/e/new-linux-based-ransomware-cheerscrypt-targets-exsi-devices.html"}], "id": "malware--5d3fa1db-5041-4560-b87b-8f61cc225c52", "is_family": true, "modified": "2025-04-15T19:12:30.368Z", "name": "Cheerscrypt", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cheerscrypt"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "ESXi"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-798', 0, 169, '09-mitre-attack', 'retrieved', '65F0D70C6915C4E471F1C8F14F67E187D2FF68E40294A404BC7D9E593E542178', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
