VALUES ('doc-09-mitre-attack-p0-800', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-14T16:45:33.729Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KeyBoy](https://attack.mitre.org/software/S0387) is malware that has been used in targeted campaigns against members of the Tibetan Parliament in 2016.(Citation: CitizenLab KeyBoy Nov 2016)(Citation: PWC KeyBoys Feb 2017)", "external_references": [{"external_id": "S0387", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0387"}, {"description": "(Citation: PWC KeyBoys Feb 2017)(Citation: CitizenLab KeyBoy Nov 2016)(Citation: Rapid7 KeyBoy Jun 2013)", "source_name": "KeyBoy"}, {"description": "Guarnieri, C., Schloesser M. (2013, June 7). KeyBoy, Targeted Attacks against Vietnam and India. Retrieved June 14, 2019.", "source_name": "Rapid7 KeyBoy Jun 2013", "url": "https://blog.rapid7.com/2013/06/07/keyboy-targeted-attacks-against-vietnam-and-india/"}, {"description": "Hulcoop, A., et al. (2016, November 17). It’s Parliamentary KeyBoy and the targeting of the Tibetan Community. Retrieved June 13, 2019.", "source_name": "CitizenLab KeyBoy Nov 2016", "url": "https://citizenlab.ca/2016/11/parliament-keyboy/"}, {"description": "Parys, B. (2017, February 11). The KeyBoys are back in town. Retrieved June 13, 2019.", "source_name": "PWC KeyBoys Feb 2017", "url": "https://web.archive.org/web/20211129064701/https://www.pwc.co.uk/issues/cyber-security-services/research/the-keyboys-are-back-in-town.html"}], "id": "malware--5dd649c0-bca4-488b-bd85-b180474ec62e", "is_family": true, "modified": "2024-04-18T18:25:18.520Z", "name": "KeyBoy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KeyBoy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-800', 0, 162, '09-mitre-attack', 'retrieved', 'D05F9A248A0B90FA05789AAA86BFAD200BD626F8F7BD713103245163B6009986', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
