VALUES ('doc-09-mitre-attack-p0-803', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-09T17:42:44.777Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HyperBro](https://attack.mitre.org/software/S0398) is a custom in-memory backdoor used by [Threat Group-3390](https://attack.mitre.org/groups/G0027).(Citation: Unit42 Emissary Panda May 2019)(Citation: Securelist LuckyMouse June 2018)(Citation: Hacker News LuckyMouse June 2018)", "external_references": [{"external_id": "S0398", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0398"}, {"description": "(Citation: Unit42 Emissary Panda May 2019)", "source_name": "HyperBro"}, {"description": "Falcone, R. and Lancaster, T. (2019, May 28). Emissary Panda Attacks Middle East Government Sharepoint Servers. Retrieved July 9, 2019.", "source_name": "Unit42 Emissary Panda May 2019", "url": "https://unit42.paloaltonetworks.com/emissary-panda-attacks-middle-east-government-sharepoint-servers/"}, {"description": "Khandelwal, S. (2018, June 14). Chinese Hackers Carried Out Country-Level Watering Hole Attack. Retrieved August 18, 2018.", "source_name": "Hacker News LuckyMouse June 2018", "url": "https://thehackernews.com/2018/06/chinese-watering-hole-attack.html"}, {"description": "Legezo, D. (2018, June 13). LuckyMouse hits national data center to organize country-level waterholing campaign. Retrieved August 18, 2018.", "source_name": "Securelist LuckyMouse June 2018", "url": "https://securelist.com/luckymouse-hits-national-data-center/86083/"}], "id": "malware--5e814485-012d-423d-b769-026bfed0f451", "is_family": true, "modified": "2024-04-11T02:16:42.727Z", "name": "HyperBro", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HyperBro"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-803', 0, 157, '09-mitre-attack', 'retrieved', '8613614CB9BB175A00F0F5FC43B23CDD7BE95A41A12628790763FF358BC7B40A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
