VALUES ('doc-09-mitre-attack-p0-804', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-10T15:54:21.805Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Anchor](https://attack.mitre.org/software/S0504) is one of a family of backdoor malware that has been used in conjunction with [TrickBot](https://attack.mitre.org/software/S0266) on selected high profile targets since at least 2018.(Citation: Cyberreason Anchor December 2019)(Citation: Medium Anchor DNS July 2020)", "external_references": [{"external_id": "S0504", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0504"}, {"description": "(Citation: Cyberreason Anchor December 2019)(Citation: Medium Anchor DNS July 2020)", "source_name": "Anchor_DNS"}, {"description": "Dahan, A. et al. (2019, December 11). DROPPING ANCHOR: FROM A TRICKBOT INFECTION TO THE DISCOVERY OF THE ANCHOR MALWARE. Retrieved September 10, 2020.", "source_name": "Cyberreason Anchor December 2019", "url": "https://www.cybereason.com/blog/dropping-anchor-from-a-trickbot-infection-to-the-discovery-of-the-anchor-malware"}, {"description": "Grange, W. (2020, July 13). Anchor_dns malware goes cross platform. Retrieved September 10, 2020.", "source_name": "Medium Anchor DNS July 2020", "url": "https://medium.com/stage-2-security/anchor-dns-malware-family-goes-cross-platform-d807ba13ca30"}], "id": "malware--5f1d4579-4e8f-48e7-860e-2da773ae432e", "is_family": true, "modified": "2023-12-04T20:02:47.052Z", "name": "Anchor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Anchor", "Anchor_DNS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Cybereason Nocturnus, @nocturnus"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-804', 0, 151, '09-mitre-attack', 'retrieved', '9E097B1D9EF341232FA2B9A62DB1B8B179266FA09CC2CEE42617151EAEFD15AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
