VALUES ('doc-09-mitre-attack-p0-806', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:26.084Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pteranodon](https://attack.mitre.org/software/S0147) is a custom backdoor used by [Gamaredon Group](https://attack.mitre.org/groups/G0047). (Citation: Palo Alto Gamaredon Feb 2017)", "external_references": [{"external_id": "S0147", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0147"}, {"description": "(Citation: Symantec Shuckworm January 2022)(Citation: Secureworks IRON TILDEN Profile)", "source_name": "Pterodo"}, {"description": "Kasza, A. and Reichel, D. (2017, February 27). The Gamaredon Group Toolset Evolution. Retrieved March 1, 2017.", "source_name": "Palo Alto Gamaredon Feb 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit-42-title-gamaredon-group-toolset-evolution/"}, {"description": "Secureworks CTU. (n.d.). IRON TILDEN. Retrieved February 24, 2022.", "source_name": "Secureworks IRON TILDEN Profile", "url": "https://www.secureworks.com/research/threat-profiles/iron-tilden"}, {"description": "Symantec. (2022, January 31). Shuckworm Continues Cyber-Espionage Attacks Against Ukraine. Retrieved February 17, 2022.", "source_name": "Symantec Shuckworm January 2022", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/shuckworm-gamaredon-espionage-ukraine"}], "id": "malware--5f9f7648-04ba-4a9f-bb4c-2a13e74572bd", "is_family": true, "modified": "2025-04-16T20:38:12.213Z", "name": "Pteranodon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pteranodon", "Pterodo"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-806', 0, 135, '09-mitre-attack', 'retrieved', '6FB1C8D14FF288E15624DBD8E83D4D767B3AB2DF0E78DA9BA5834AC8F46EB670', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
