VALUES ('doc-09-mitre-attack-p0-807', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-16T13:57:53.205Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkTortilla](https://attack.mitre.org/software/S1066) is a highly configurable .NET-based crypter that has been possibly active since at least August 2015. [DarkTortilla](https://attack.mitre.org/software/S1066) has been used to deliver popular information stealers, RATs, and payloads such as [Agent Tesla](https://attack.mitre.org/software/S0331), AsyncRat, [NanoCore](https://attack.mitre.org/software/S0336), RedLine, [Cobalt Strike](https://attack.mitre.org/software/S0154), and Metasploit.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"external_id": "S1066", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1066"}, {"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "is_family": true, "modified": "2025-04-16T20:38:12.375Z", "name": "DarkTortilla", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DarkTortilla"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Mindaugas Gudzis, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-807', 0, 115, '09-mitre-attack', 'retrieved', '25A6C580B98DB0C862FC6243ABABCBB52F846E19A39DFE5D24F728EA142A355C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
