VALUES ('doc-09-mitre-attack-p0-809', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROKRAT](https://attack.mitre.org/software/S0240) is a cloud-based remote access tool (RAT) used by [APT37](https://attack.mitre.org/groups/G0067) to target victims in South Korea. [APT37](https://attack.mitre.org/groups/G0067) has used ROKRAT during several campaigns from 2016 through 2021.(Citation: Talos ROKRAT)(Citation: Talos Group123)(Citation: Volexity InkySquid RokRAT August 2021)", "external_references": [{"external_id": "S0240", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0240"}, {"description": "(Citation: Talos ROKRAT 2) (Citation: Talos Group123)", "source_name": "ROKRAT"}, {"description": "Mercer, W., Rascagneres, P. (2017, April 03). Introducing ROKRAT. Retrieved May 21, 2018.", "source_name": "Talos ROKRAT", "url": "https://blog.talosintelligence.com/2017/04/introducing-rokrat.html"}, {"description": "Mercer, W., Rascagneres, P. (2018, January 16). Korea In The Crosshairs. Retrieved May 21, 2018.", "source_name": "Talos Group123", "url": "https://blog.talosintelligence.com/2018/01/korea-in-crosshairs.html"}, {"description": "Cash, D., Grunzweig, J., Adair, S., Lancaster, T. (2021, August 25). North Korean BLUELIGHT Special: InkySquid Deploys RokRAT. Retrieved October 1, 2021.", "source_name": "Volexity InkySquid RokRAT August 2021", "url": "https://www.volexity.com/blog/2021/08/24/north-korean-bluelight-special-inkysquid-deploys-rokrat/"}, {"description": "Mercer, W., Rascagneres, P. (2017, November 28). ROKRAT Reloaded. Retrieved May 21, 2018.", "source_name": "Talos ROKRAT 2", "url": "https://blog.talosintelligence.com/2017/11/ROKRAT-Reloaded.html"}], "id": "malware--60a9c2f0-b7a5-4e8e-959c-e1a3ff314a5f", "is_family": true, "modified": "2025-04-25T14:43:33.037Z", "name": "ROKRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ROKRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.3"}', 'kb-doc-09-mitre-attack-p0-809', 0, 178, '09-mitre-attack', 'retrieved', '8D0DB2B75E58D4E0FCD10CE341999E91F8ABF4B4C3A6ABFB55F4557A7E6CE705', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
