VALUES ('doc-09-mitre-attack-p0-812', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T15:02:14.907Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VPNFilter](https://attack.mitre.org/software/S1010) is a multi-stage, modular platform with versatile capabilities to support both intelligence-collection and destructive cyber attack operations. [VPNFilter](https://attack.mitre.org/software/S1010) modules such as its packet sniffer (''ps'') can collect traffic that passes through an infected device, allowing the theft of website credentials and monitoring of Modbus SCADA protocols. (Citation: William Largent June 2018) (Citation: Carl Hurd March 2019) [VPNFilter](https://attack.mitre.org/software/S1010) was assessed to be replaced by [Sandworm Team](https://attack.mitre.org/groups/G0034) with [Cyclops Blink](https://attack.mitre.org/software/S0687) starting in 2019.(Citation: NCSC CISA Cyclops Blink Advisory February 2022)", "external_references": [{"external_id": "S1010", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1010"}, {"description": "Carl Hurd 2019, March 26 VPNFilter Deep Dive Retrieved. 2019/03/28 ", "source_name": "Carl Hurd March 2019", "url": "https://www.youtube.com/watch?v=yuZazP22rpI"}, {"description": "NCSC, CISA, FBI, NSA. (2022, February 23). New Sandworm malware Cyclops Blink replaces VPNFilter. Retrieved March 3, 2022.", "source_name": "NCSC CISA Cyclops Blink Advisory February 2022", "url": "https://www.ncsc.gov.uk/news/joint-advisory-shows-new-sandworm-malware-cyclops-blink-replaces-vpnfilter"}, {"description": "William Largent 2018, June 06 VPNFilter Update - VPNFilter exploits endpoints, targets new devices Retrieved. 2019/03/28 ", "source_name": "William Largent June 2018", "url": "https://blog.talosintelligence.com/2018/06/vpnfilter-update.html"}], "id": "malware--6108f800-10b8-4090-944e-be579f01263d", "is_family": true, "modified": "2025-04-15T19:46:34.471Z", "name": "VPNFilter", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["VPNFilter"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-812', 0, 197, '09-mitre-attack', 'retrieved', '442825534C498F6916FD66423530C521929E7A1DF796D748ED0AD8E5E5B1228B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
