VALUES ('doc-09-mitre-attack-p0-813', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-12T14:46:05.125Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SplatDropper](https://attack.mitre.org/software/S1232) is a loader that utilizes native windows API to deliver its payload to the victim environment. [SplatDropper](https://attack.mitre.org/software/S1232) has been delivered through RAR archives and used legitimate executable for DLL side-loading. [SplatDropper](https://attack.mitre.org/software/S1232) is known to be leveraged by [Mustang Panda](https://attack.mitre.org/groups/G0129) and was first observed utilized in 2025.", "external_references": [{"external_id": "S1232", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1232"}], "id": "malware--6114c345-4c09-42ce-8d37-aef16360a7f3", "is_family": true, "modified": "2025-10-21T16:56:26.801Z", "name": "SplatDropper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SplatDropper"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-813', 0, 89, '09-mitre-attack', 'retrieved', '73D36E54BADCB774DC1D66A804FC184F2211E4175AE03D6C2A05812C68E1768A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
