INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-814', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-11T17:36:46.197Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Babuk](https://attack.mitre.org/software/S0638) is a Ransomware-as-a-service (RaaS) malware that has been used since at least 2021. The operators of [Babuk](https://attack.mitre.org/software/S0638) employ a \"Big Game Hunting\" approach to targeting major enterprises and operate a leak site to post stolen data as part of their extortion scheme.(Citation: Sogeti CERT ESEC Babuk March 2021)(Citation: McAfee Babuk February 2021)(Citation: CyberScoop Babuk February 2021)", "external_references": [{"external_id": "S0638", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0638"}, {"description": "(Citation: Sogeti CERT ESEC Babuk March 2021)(Citation: McAfee Babuk February 2021)", "source_name": "Vasa Locker"}, {"description": "(Citation: Sogeti CERT ESEC Babuk March 2021)(Citation: McAfee Babuk February 2021)(Citation: Trend Micro Ransomware February 2021)", "source_name": "Babyk"}, {"description": "Centero, R. et al. (2021, February 5). New in Ransomware: Seth-Locker, Babuk Locker, Maoloa, TeslaCrypt, and CobraLocker. Retrieved August 11, 2021.", "source_name": "Trend Micro Ransomware February 2021", "url": "https://www.trendmicro.com/en_us/research/21/b/new-in-ransomware.html"}, {"description": "Lyngaas, S. (2021, February 4). Meet Babuk, a ransomware attacker blamed for the Serco breach. Retrieved August 11, 2021.", "source_name": "CyberScoop Babuk February 2021", "url": "https://www.cyberscoop.com/babuk-ransomware-serco-attack/"}, {"description": "Mundo, A. et al. (2021, February). Technical Analysis of Babuk Ransomware. Retrieved August 11, 2021.", "source_name": "McAfee Babuk February 2021", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-babuk-ransomware.pdf"}, {"description": "Sogeti. (2021, March). Babuk Ransomware. Retrieved August 11, 2021.", "source_name": "Sogeti CERT ESEC Babuk March 2021", "url": "https://www.sogeti.com/globalassets/reports/cybersecchronicles_-_babuk.pdf"}], "id": "malware--61c7a91a-0b83-461d-ad32-75d96eed4a09", "is_family": true, "modified": "2025-04-25T14:43:34.138Z", "name": "Babuk", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Babuk", "Babyk", "Vasa Locker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India", "Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-814', 0, 255, '09-mitre-attack', 'retrieved', 'EEE5F92F2C9BD37DA92FE258E2DD0620F077CA99F2B2E7814996952174F59A41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
