VALUES ('doc-09-mitre-attack-p0-815', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T00:18:02.466Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Exbyte](https://attack.mitre.org/software/S1179) is an exfiltration tool written in Go that is uniquely associated with [BlackByte](https://attack.mitre.org/groups/G1043) operations. Observed since 2022, [Exbyte](https://attack.mitre.org/software/S1179) transfers collected files to online file sharing and hosting services.(Citation: Symantec BlackByte 2022)", "external_references": [{"external_id": "S1179", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1179"}, {"description": "Symantec Threat Hunter Team. (2022, October 21). Exbyte: BlackByte Ransomware Attackers Deploy New Exfiltration Tool. Retrieved December 16, 2024.", "source_name": "Symantec BlackByte 2022", "url": "https://www.security.com/threat-intelligence/blackbyte-exbyte-ransomware"}], "id": "malware--6207dd22-bf18-4c96-aada-c573a9bbf5ec", "is_family": true, "modified": "2025-03-09T16:02:02.193Z", "name": "Exbyte", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Exbyte"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-815', 0, 100, '09-mitre-attack', 'retrieved', '8E2F28450F32ADA95C1A12F6EE359FC88C939872901F124857C13C1A2DA80E52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
