VALUES ('doc-09-mitre-attack-p0-816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-01-10T19:43:47.281Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkWatchman](https://attack.mitre.org/software/S0673) is a lightweight JavaScript-based remote access tool (RAT) that avoids file operations; it was first observed in November 2021.(Citation: Prevailion DarkWatchman 2021)", "external_references": [{"external_id": "S0673", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0673"}, {"description": "Smith, S., Stafford, M. (2021, December 14). DarkWatchman: A new evolution in fileless techniques. Retrieved January 10, 2022.", "source_name": "Prevailion DarkWatchman 2021", "url": "https://web.archive.org/web/20220629230035/https://www.prevailion.com/darkwatchman-new-fileless-techniques/"}], "id": "malware--63686509-069b-4143-99ea-4e59cad6cb2a", "is_family": true, "modified": "2024-08-26T16:28:39.922Z", "name": "DarkWatchman", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DarkWatchman"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-816', 0, 90, '09-mitre-attack', 'retrieved', 'B45D2AE0E4E62AC4A1165CF149D13A74959AE7CF9C238B226507DA817197FD9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
