VALUES ('doc-09-mitre-attack-p0-817', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:19.746Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dyre](https://attack.mitre.org/software/S0024) is a banking Trojan that has been used for financial gain. \n (Citation: Symantec Dyre June 2015)(Citation: Malwarebytes Dyreza November 2015)", "external_references": [{"external_id": "S0024", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0024"}, {"description": "(Citation: Symantec Dyre June 2015)", "source_name": "Dyre"}, {"description": "(Citation: Sophos Dyreza April 2015)", "source_name": "Dyzap"}, {"description": "(Citation: Sophos Dyreza April 2015)", "source_name": "Dyreza"}, {"description": "Symantec Security Response. (2015, June 23). Dyre: Emerging threat on financial fraud landscape. Retrieved August 23, 2018.", "source_name": "Symantec Dyre June 2015", "url": "http://www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/dyre-emerging-threat.pdf"}, {"description": "hasherezade. (2015, November 4). A Technical Look At Dyreza. Retrieved June 15, 2020.", "source_name": "Malwarebytes Dyreza November 2015", "url": "https://blog.malwarebytes.com/threat-analysis/2015/11/a-technical-look-at-dyreza/"}, {"description": "Ducklin, P. (2015, April 20). Notes from SophosLabs: Dyreza, the malware that discriminates against old computers. Retrieved June 16, 2020.", "source_name": "Sophos Dyreza April 2015", "url": "https://nakedsecurity.sophos.com/2015/04/20/notes-from-sophoslabs-dyreza-the-malware-that-discriminates-against-old-computers/"}], "id": "malware--63c2a130-8a5b-452f-ad96-07cf0af12ffe", "is_family": true, "modified": "2025-04-25T14:43:34.862Z", "name": "Dyre", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Dyre", "Dyzap", "Dyreza"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Josh Campbell, Cyborg Security, @cyb0rgsecur1ty"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-817', 0, 168, '09-mitre-attack', 'retrieved', 'BFBB4915C881CCC1DE797B31C8AF2C7874FDE8709F7E3E7D2D42D3669FF4A673', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
