VALUES ('doc-09-mitre-attack-p0-818', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-14T19:58:17.917Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackMould](https://attack.mitre.org/software/S0564) is a web shell based on [China Chopper](https://attack.mitre.org/software/S0020) for servers running Microsoft IIS. First reported in December 2019, it has been used in malicious campaigns by [GALLIUM](https://attack.mitre.org/groups/G0093) against telecommunication providers.(Citation: Microsoft GALLIUM December 2019)", "external_references": [{"external_id": "S0564", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0564"}, {"description": "MSTIC. (2019, December 12). GALLIUM: Targeting global telecom. Retrieved January 13, 2021.", "source_name": "Microsoft GALLIUM December 2019", "url": "https://www.microsoft.com/security/blog/2019/12/12/gallium-targeting-global-telecom/"}], "id": "malware--63c4511b-2d6e-4bb2-b582-e2e99a8a467d", "is_family": true, "modified": "2025-04-25T14:43:35.224Z", "name": "BlackMould", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BlackMould"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-818', 0, 97, '09-mitre-attack', 'retrieved', '0190E9522EC13F4EC19C10FE81C61BF18E7CB0614D0D3C2B4AA90D29D4C57546', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
