VALUES ('doc-09-mitre-attack-p0-819', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-09T18:32:18.369Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Javali](https://attack.mitre.org/software/S0528) is a banking trojan that has targeted Portuguese and Spanish-speaking countries since 2017, primarily focusing on customers of financial institutions in Brazil and Mexico.(Citation: Securelist Brazilian Banking Malware July 2020)", "external_references": [{"external_id": "S0528", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0528"}, {"description": "GReAT. (2020, July 14). The Tetrade: Brazilian banking malware goes global. Retrieved November 9, 2020.", "source_name": "Securelist Brazilian Banking Malware July 2020", "url": "https://securelist.com/the-tetrade-brazilian-banking-malware/97779/"}], "id": "malware--64122557-5940-4271-9123-25bfc0c693db", "is_family": true, "modified": "2025-04-25T14:43:35.588Z", "name": "Javali", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Javali"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-819', 0, 96, '09-mitre-attack', 'retrieved', '3A1644AE353FAF7F4C03A4E705722FAF63E3CE49887ECBAB696934BB50696130', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
