VALUES ('doc-09-mitre-attack-p0-820', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-08T19:38:27.401Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PACEMAKER](https://attack.mitre.org/software/S1109) is a credential stealer that was used by [APT5](https://attack.mitre.org/groups/G1023) as early as 2020 including activity against US Defense Industrial Base (DIB) companies.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"external_id": "S1109", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1109"}, {"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "malware--647215dd-29a6-4528-b354-ca8b5e08fca1", "is_family": true, "modified": "2025-04-15T19:46:34.604Z", "name": "PACEMAKER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PACEMAKER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-820', 0, 108, '09-mitre-attack', 'retrieved', 'F3D086812ACFC53C68188FA1AE2B2E97232A2C3C9B7904D53F3937F3F5652271', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
