VALUES ('doc-09-mitre-attack-p0-823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:15.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PlugX](https://attack.mitre.org/software/S0013) is a remote access tool (RAT) with modular plugins that has been used by multiple threat groups.(Citation: Lastline PlugX Analysis)(Citation: FireEye Clandestine Fox Part 2)(Citation: New DragonOK)(Citation: Dell TG-3390)", "external_references": [{"external_id": "S0013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0013"}, {"description": "(Citation: CIRCL PlugX March 2013)", "source_name": "DestroyRAT"}, {"description": "(Citation: FireEye Clandestine Fox Part 2)", "source_name": "Kaba"}, {"description": "(Citation: Lastline PlugX Analysis) (Citation: FireEye Clandestine Fox Part 2)(Citation: CIRCL PlugX March 2013)", "source_name": "PlugX"}, {"description": "(Citation: Lastline PlugX Analysis)(Citation: CIRCL PlugX March 2013)", "source_name": "Korplug"}, {"description": "(Citation: Lastline PlugX Analysis)(Citation: FireEye Clandestine Fox Part 2)(Citation: CIRCL PlugX March 2013)", "source_name": "Sogu"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Thoper"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "TVT"}, {"description": "Computer Incident Response Center Luxembourg. (2013, March 29). Analysis of a PlugX variant. Retrieved November 5, 2018.", "source_name": "CIRCL PlugX March 2013", "url": "http://circl.lu/assets/files/tr-12/tr-12-circl-plugx-analysis-v1.pdf"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}, {"description": "Miller-Osborn, J., Grunzweig, J.. (2015, April). Unit 42 Identifies New DragonOK Backdoor Malware Deployed Against Japanese Targets. Retrieved November 4, 2015.", "source_name": "New DragonOK", "url": "http://researchcenter.paloaltonetworks.com/2015/04/unit-42-identifies-new-dragonok-backdoor-malware-deployed-against-japanese-targets/"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}, {"description": "Scott, M.. (2014, June 10). Clandestine Fox, Part Deux. Retrieved January 14, 2016.", "source_name": "FireEye Clandestine Fox Part 2", "url": "https://www.fireeye.com/blog/threat-research/2014/06/clandestine-fox-part-deux.html"}, {"description": "Vasilenko, R. (2013, December 17). An Analysis of PlugX Malware. Retrieved November 24, 2015.", "source_name": "Lastline PlugX Analysis", "url": "https://lastline3.rssing.com/chan-29044929/all_p1.html#c29044929a2"}], "id": "malware--64fa0de0-6240-41f4-8638-f4ca7ed528fd", "is_family": true, "modified": "2026-05-12T15:12:00.734Z", "name": "PlugX", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PlugX", "Thoper", "TVT", "DestroyRAT", "Sogu", "Kaba", "Korplug"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Kyaw Pyiyt Htet (@KyawPyiytHtet)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "3.3"}', 'kb-doc-09-mitre-attack-p0-823', 0, 293, '09-mitre-attack', 'retrieved', 'C5771DE8CDBE874EB63812F6FDC3F115EABD8F04E3C394774C6462898C6D64D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
