VALUES ('doc-09-mitre-attack-p0-825', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bisonal](https://attack.mitre.org/software/S0268) is a remote access tool (RAT) that has been used by [Tonto Team](https://attack.mitre.org/groups/G0131) against public and private sector organizations in Russia, South Korea, and Japan since at least December 2010.(Citation: Unit 42 Bisonal July 2018)(Citation: Talos Bisonal Mar 2020)", "external_references": [{"external_id": "S0268", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0268"}, {"description": "(Citation: Unit 42 Bisonal July 2018)(Citation: Talos Bisonal Mar 2020)", "source_name": "Bisonal"}, {"description": "Hayashi, K., Ray, V. (2018, July 31). Bisonal Malware Used in Attacks Against Russia and South Korea. Retrieved August 7, 2018.", "source_name": "Unit 42 Bisonal July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-bisonal-malware-used-attacks-russia-south-korea/"}, {"description": "Mercer, W., et al. (2020, March 5). Bisonal: 10 years of play. Retrieved January 26, 2022.", "source_name": "Talos Bisonal Mar 2020", "url": "https://blog.talosintelligence.com/2020/03/bisonal-10-years-of-play.html"}], "id": "malware--65ffc206-d7c1-45b3-b543-f6b726e7840d", "is_family": true, "modified": "2024-04-11T02:53:35.918Z", "name": "Bisonal", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bisonal"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-825', 0, 149, '09-mitre-attack', 'retrieved', '21C17D31736EC330CF64E93D80915E3672F3DC2CA140FE552A30538AF365EAD3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
