VALUES ('doc-09-mitre-attack-p0-826', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:30:59.178Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MultiLayer Wiper](https://attack.mitre.org/software/S1135) is wiper malware written in .NET associated with [Agrius](https://attack.mitre.org/groups/G1030) operations. Observed samples of [MultiLayer Wiper](https://attack.mitre.org/software/S1135) have an anomalous, future compilation date suggesting possible metadata manipulation.(Citation: Unit42 Agrius 2023)", "external_references": [{"external_id": "S1135", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1135"}, {"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "malware--663d7dee-5a47-459e-a5ef-e850a94a8ee5", "is_family": true, "modified": "2024-08-29T15:20:13.078Z", "name": "MultiLayer Wiper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MultiLayer Wiper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-826', 0, 109, '09-mitre-attack', 'retrieved', 'CC16ABCD3B20547A8C7607B0C225C758BDFD13EE13F5FB29494972A972AEBD0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
