VALUES ('doc-09-mitre-attack-p0-827', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T18:35:44.528Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NOOPLDR](https://attack.mitre.org/software/S9025) is a shellcode loader with XML/C# and DLL versions that has been used by [MirrorFace](https://attack.mitre.org/groups/G1054) to load [HiddenFace](https://attack.mitre.org/software/S9023).(Citation: Trend Micro Earth Kasha NOV 2024)\n", "external_references": [{"external_id": "S9025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9025"}, {"description": "Trend Micro. (2024, November 19). Spot the Difference: Earth Kasha''s New LODEINFO Campaign And The Correlation Analysis With The APT10 Umbrella. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/lodeinfo-campaign-of-earth-kasha.html"}], "id": "malware--66637cd6-ae68-4bcd-af82-32f70a854175", "is_family": true, "modified": "2026-05-12T15:12:00.734Z", "name": "NOOPLDR", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NOOPLDR"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-827', 0, 106, '09-mitre-attack', 'retrieved', 'C8E07458528955FF9456B41707B5BC4184EB316C61390B13CE78A75CD8970625', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
