VALUES ('doc-09-mitre-attack-p0-829', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:05:50.305Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) is an information stealer malware family in use since at least 2022. [Lumma Stealer](https://attack.mitre.org/software/S1213) is a Malware as a Service (MaaS) where captured data has been sold in criminal markets to Initial Access Brokers.(Citation: Cybereason LumaStealer Undated)(Citation: Netskope LummaStealer 2025)(Citation: Qualys LummaStealer 2024)(Citation: Fortinet LummaStealer 2024)(Citation: TrendMicro LummaStealer 2025)", "external_references": [{"external_id": "S1213", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1213"}, {"description": "(Citation: Cybereason LumaStealer Undated)", "source_name": "LummaStealer"}, {"description": "Buddy Tancio, Fe Cureg, and Jovit Samaniego, Trend Micro. (2025, January 30). Lumma Stealer’s GitHub-Based Delivery Explored via Managed Detection and Response. Retrieved March 22, 2025.", "source_name": "TrendMicro LummaStealer 2025", "url": "https://www.trendmicro.com/en_us/research/25/a/lumma-stealers-github-based-delivery-via-mdr.html"}, {"description": "Cara Lin, Fortinet. (2024, January 8). Deceptive Cracked Software Spreads Lumma Variant on YouTube. Retrieved March 22, 2025.", "source_name": "Fortinet LummaStealer 2024", "url": "https://www.fortinet.com/blog/threat-research/lumma-variant-on-youtube"}, {"description": "Cybereaon Security Services Team. (n.d.). Your Data Is Under New Lummanagement: The Rise of LummaStealer. Retrieved March 22, 2025.", "source_name": "Cybereason LumaStealer Undated", "url": "https://www.cybereason.com/blog/threat-analysis-rise-of-lummastealer"}, {"description": "Leandro Fróes, Netskope. (2025, January 23). Lumma Stealer: Fake CAPTCHAs & New Techniques to Evade Detection. Retrieved March 22, 2025.", "source_name": "Netskope LummaStealer 2025", "url": "https://www.netskope.com/blog/lumma-stealer-fake-captchas-new-techniques-to-evade-detection"}, {"description": "Vishwajeet Kumar, Qualys. (2024, October 20). Unmasking Lumma Stealer: Analyzing Deceptive Tactics with Fake CAPTCHA. Retrieved March 22, 2025.", "source_name": "Qualys LummaStealer 2024", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2024/10/20/unmasking-lumma-stealer-analyzing-deceptive-tactics-with-fake-captcha"}], "id": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "is_family": true, "modified": "2025-03-22T16:02:03.819Z", "name": "Lumma Stealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Lumma Stealer", "LummaStealer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-829', 0, 240, '09-mitre-attack', 'retrieved', '2E761DA8FA1D2ABF8D72D64E581F7B4A07B84AD43BAB83D69B30616C626D0C51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
