VALUES ('doc-09-mitre-attack-p0-830', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:37.767Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SeaDuke](https://attack.mitre.org/software/S0053) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2014 to 2015. It was used primarily as a secondary backdoor for victims that were already compromised with [CozyCar](https://attack.mitre.org/software/S0046). (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0053"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--67e6d66b-1b82-4699-b47a-e2efb6268d14", "is_family": true, "modified": "2025-04-25T14:43:37.740Z", "name": "SeaDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SeaDuke", "SeaDaddy", "SeaDesk"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-830', 0, 97, '09-mitre-attack', 'retrieved', 'FB5D6226422F149A650DF04F4B0938F2F8A0EA0DD2E5BC91C4CEEE247FE625B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
