VALUES ('doc-09-mitre-attack-p0-831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:15.994Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BS2005](https://attack.mitre.org/software/S0014) is malware that was used by [Ke3chang](https://attack.mitre.org/groups/G0004) in spearphishing campaigns since at least 2011. (Citation: Mandiant Operation Ke3chang November 2014)", "external_references": [{"external_id": "S0014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0014"}, {"description": "Villeneuve, N., Bennett, J. T., Moran, N., Haq, T., Scott, M., & Geers, K. (2014). OPERATION “KE3CHANG”: Targeted Attacks Against Ministries of Foreign Affairs. Retrieved November 12, 2014.", "source_name": "Mandiant Operation Ke3chang November 2014", "url": "https://www.mandiant.com/resources/operation-ke3chang-targeted-attacks-against-ministries-of-foreign-affairs"}], "id": "malware--67fc172a-36fa-4a35-88eb-4ba730ed52a6", "is_family": true, "modified": "2025-04-25T14:43:38.100Z", "name": "BS2005", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BS2005"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-831', 0, 98, '09-mitre-attack', 'retrieved', '57793C489A7C768887EC65D2F19C2F06EB2A1F8B4145301C5079CA15DEAA1A80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
