VALUES ('doc-09-mitre-attack-p0-832', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:41.750Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DustySky](https://attack.mitre.org/software/S0062) is multi-stage malware written in .NET that has been used by [Molerats](https://attack.mitre.org/groups/G0021) since May 2015. (Citation: DustySky) (Citation: DustySky2)(Citation: Kaspersky MoleRATs April 2019)", "external_references": [{"external_id": "S0062", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0062"}, {"description": "ClearSky. (2016, January 7). Operation DustySky. Retrieved January 8, 2016.", "source_name": "DustySky", "url": "https://www.clearskysec.com/wp-content/uploads/2016/01/Operation%20DustySky_TLP_WHITE.pdf"}, {"description": "ClearSky Cybersecurity. (2016, June 9). Operation DustySky - Part 2. Retrieved August 3, 2016.", "source_name": "DustySky2", "url": "http://www.clearskysec.com/wp-content/uploads/2016/06/Operation-DustySky2_-6.2016_TLP_White.pdf"}, {"description": "GReAT. (2019, April 10). Gaza Cybergang Group1, operation SneakyPastes. Retrieved May 13, 2020.", "source_name": "Kaspersky MoleRATs April 2019", "url": "https://securelist.com/gaza-cybergang-group1-operation-sneakypastes/90068/"}], "id": "malware--687c23e4-4e25-4ee7-a870-c5e002511f54", "is_family": true, "modified": "2025-04-25T14:43:38.466Z", "name": "DustySky", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DustySky", "NeD Worm"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-832', 0, 121, '09-mitre-attack', 'retrieved', 'DB7EC8B3723943D417068964F5A5E3CDF249E02126A6442AAAA11093E5B9833A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
