VALUES ('doc-09-mitre-attack-p0-833', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:31.188Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Duqu](https://attack.mitre.org/software/S0038) is a malware platform that uses a modular approach to extend functionality after deployment within a target network. (Citation: Symantec W32.Duqu)", "external_references": [{"external_id": "S0038", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0038"}, {"description": "Symantec Security Response. (2011, November). W32.Duqu: The precursor to the next Stuxnet. Retrieved September 17, 2015.", "source_name": "Symantec W32.Duqu", "url": "https://www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/w32_duqu_the_precursor_to_the_next_stuxnet.pdf"}], "id": "malware--68dca94f-c11d-421e-9287-7c501108e18c", "is_family": true, "modified": "2025-04-16T20:38:14.352Z", "name": "Duqu", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Duqu"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-833', 0, 87, '09-mitre-attack', 'retrieved', 'DC83F10B018C818EB6CD0538FA179416EAF2CEB61851C802603222C560B8CFAD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
