VALUES ('doc-09-mitre-attack-p0-835', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:12.858Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Remsec](https://attack.mitre.org/software/S0125) is a modular backdoor that has been used by [Strider](https://attack.mitre.org/groups/G0041) and appears to have been designed primarily for espionage purposes. Many of its modules are written in Lua. (Citation: Symantec Strider Blog)", "external_references": [{"external_id": "S0125", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0125"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2016, August 8). ProjectSauron: top level cyber-espionage platform covertly extracts encrypted government comms. Retrieved August 17, 2016.", "source_name": "Kaspersky ProjectSauron Blog", "url": "https://securelist.com/faq-the-projectsauron-apt/75533/"}, {"description": "ProjectSauron is used to refer both to the threat group also known as G0041 as well as the malware platform also known as S0125. (Citation: Kaspersky ProjectSauron Blog)", "source_name": "ProjectSauron"}, {"description": "Symantec Security Response. (2016, August 7). Strider: Cyberespionage group turns eye of Sauron on targets. Retrieved August 17, 2016.", "source_name": "Symantec Strider Blog", "url": "http://www.symantec.com/connect/blogs/strider-cyberespionage-group-turns-eye-sauron-targets"}], "id": "malware--69d6f4a9-fcf0-4f51-bca7-597c51ad0bb8", "is_family": true, "modified": "2026-05-12T15:12:00.735Z", "name": "Remsec", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Remsec", "Backdoor.Remsec", "ProjectSauron"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-835', 0, 165, '09-mitre-attack', 'retrieved', 'F8F04D39D85E62D53988E1560DB74FDF2D893734257CA15657C0415D3264F204', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
