VALUES ('doc-09-mitre-attack-p0-836', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-30T19:20:45.556Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Industroyer2](https://attack.mitre.org/software/S1072) is a compiled and static piece of malware that has the ability to communicate over the IEC-104 protocol. It is similar to the IEC-104 module found in [Industroyer](https://attack.mitre.org/software/S0604). Security researchers assess that [Industroyer2](https://attack.mitre.org/software/S1072) was designed to cause impact to high-voltage electrical substations. The initial [Industroyer2](https://attack.mitre.org/software/S1072) sample was compiled on 03/23/2022 and scheduled to execute on 04/08/2022, however it was discovered before deploying, resulting in no impact.(Citation: Industroyer2 Blackhat ESET)", "external_references": [{"external_id": "S1072", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1072"}, {"description": "Anton Cherepanov, Robert Lipovsky. (2022, August). Industroyer2: Sandworm''s Cyberwarfare Targets Ukraine''s Power Grid. Retrieved April 6, 2023.", "source_name": "Industroyer2 Blackhat ESET", "url": "https://www.youtube.com/watch?v=xC9iM5wVedQ"}], "id": "malware--6a0d0ea9-b2c4-43fe-a552-ac41a3009dc5", "is_family": true, "modified": "2025-04-16T20:38:14.728Z", "name": "Industroyer2", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Industroyer2"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Field Controller/RTU/PLC/IED", "Engineering Workstation"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-836', 0, 140, '09-mitre-attack', 'retrieved', 'F99DEBB4241861CE29B6E259618A6D904856C227D19AC0E0D10812BA4E36312F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
