VALUES ('doc-09-mitre-attack-p0-837', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:17.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sykipot](https://attack.mitre.org/software/S0018) is malware that has been used in spearphishing campaigns since approximately 2007 against victims primarily in the US. One variant of [Sykipot](https://attack.mitre.org/software/S0018) hijacks smart cards on victims. (Citation: Alienvault Sykipot DOD Smart Cards) The group using this malware has also been referred to as Sykipot. (Citation: Blasco 2013)", "external_references": [{"external_id": "S0018", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0018"}, {"description": "Blasco, J. (2012, January 12). Sykipot variant hijacks DOD and Windows smart cards. Retrieved January 10, 2016.", "source_name": "Alienvault Sykipot DOD Smart Cards", "url": "https://www.alienvault.com/open-threat-exchange/blog/sykipot-variant-hijacks-dod-and-windows-smart-cards"}, {"description": "Blasco, J. (2013, March 21). New Sykipot developments [Blog]. Retrieved November 12, 2014.", "source_name": "Blasco 2013", "url": "http://www.alienvault.com/open-threat-exchange/blog/new-sykipot-developments"}], "id": "malware--6a0ef5d4-fc7c-4dda-85d7-592e4dbdc5d9", "is_family": true, "modified": "2025-04-25T14:43:39.731Z", "name": "Sykipot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Sykipot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-837', 0, 134, '09-mitre-attack', 'retrieved', 'C0563DB179ECA9EFD4F7AABE65B1CA2364D283FFCF133F35FEC27FE7BDA38485', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
