VALUES ('doc-09-mitre-attack-p0-839', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T13:28:47.452Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Xbash](https://attack.mitre.org/software/S0341) is a malware family that has targeted Linux and Microsoft Windows servers. The malware has been tied to the Iron Group, a threat actor group known for previous ransomware attacks. [Xbash](https://attack.mitre.org/software/S0341) was developed in Python and then converted into a self-contained Linux ELF executable by using PyInstaller.(Citation: Unit42 Xbash Sept 2018)", "external_references": [{"external_id": "S0341", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0341"}, {"description": "(Citation: Unit42 Xbash Sept 2018)", "source_name": "Xbash"}, {"description": "Xiao, C. (2018, September 17). Xbash Combines Botnet, Ransomware, Coinmining in Worm that Targets Linux and Windows. Retrieved November 14, 2018.", "source_name": "Unit42 Xbash Sept 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/09/unit42-xbash-combines-botnet-ransomware-coinmining-worm-targets-linux-windows/"}], "id": "malware--6a92d80f-cc65-45f6-aa66-3cdea6786b3c", "is_family": true, "modified": "2025-04-25T14:43:40.462Z", "name": "Xbash", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Xbash"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-839', 0, 130, '09-mitre-attack', 'retrieved', '4E2AC0CD3F01EC26267116AB1A0838ECBE9ED75722E0E73AC01780A1B99EAE15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
