VALUES ('doc-09-mitre-attack-p0-841', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:58.738Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Epic](https://attack.mitre.org/software/S0091) is a backdoor that has been used by [Turla](https://attack.mitre.org/groups/G0010). (Citation: Kaspersky Turla)", "external_references": [{"external_id": "S0091", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0091"}, {"description": "(Citation: Kaspersky Turla)", "source_name": "Epic"}, {"description": "(Citation: Kaspersky Turla)", "source_name": "Tavdig"}, {"description": "(Citation: Kaspersky Turla)", "source_name": "Wipbot"}, {"description": "(Citation: Kaspersky Turla)", "source_name": "WorldCupSec"}, {"description": "(Citation: Kaspersky Turla)", "source_name": "TadjMakhal"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2014, August 7). The Epic Turla Operation: Solving some of the mysteries of Snake/Uroburos. Retrieved December 11, 2014.", "source_name": "Kaspersky Turla", "url": "https://securelist.com/the-epic-turla-operation/65545/"}], "id": "malware--6b62e336-176f-417b-856a-8552dd8c44e1", "is_family": true, "modified": "2025-10-22T02:34:29.842Z", "name": "Epic", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Epic", "Tavdig", "Wipbot", "WorldCupSec", "TadjMakhal"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Martin Smolár, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-841', 0, 124, '09-mitre-attack', 'retrieved', 'CD277C637CA8DE5866BE11C084D54ABF900E83B8AD2645953F99816C64FB9A62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
