VALUES ('doc-09-mitre-attack-p0-842', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-28T13:09:26.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LightNeuron](https://attack.mitre.org/software/S0395) is a sophisticated backdoor that has targeted Microsoft Exchange servers since at least 2014. [LightNeuron](https://attack.mitre.org/software/S0395) has been used by [Turla](https://attack.mitre.org/groups/G0010) to target diplomatic and foreign affairs-related organizations. The presence of certain strings in the malware suggests a Linux variant of [LightNeuron](https://attack.mitre.org/software/S0395) exists.(Citation: ESET LightNeuron May 2019)", "external_references": [{"external_id": "S0395", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0395"}, {"description": "Faou, M. (2019, May). Turla LightNeuron: One email away from remote code execution. Retrieved June 24, 2019.", "source_name": "ESET LightNeuron May 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/05/ESET-LightNeuron.pdf"}], "id": "malware--6ba1d7ae-d60b-43e6-9f08-a8b787e9d9cb", "is_family": true, "modified": "2024-04-11T01:37:19.602Z", "name": "LightNeuron", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LightNeuron"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-842', 0, 115, '09-mitre-attack', 'retrieved', 'A5DE9E2F2693B94EEDF78EF660F2074AE12A8B203B537C7DEF3E86DA95A714CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
