VALUES ('doc-09-mitre-attack-p0-843', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-07T15:11:17.444Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Peppy](https://attack.mitre.org/software/S0643) is a Python-based remote access Trojan, active since at least 2012, with similarities to [Crimson](https://attack.mitre.org/software/S0115).(Citation: Proofpoint Operation Transparent Tribe March 2016)", "external_references": [{"external_id": "S0643", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0643"}, {"description": "Huss, D. (2016, March 1). Operation Transparent Tribe. Retrieved June 8, 2016.", "source_name": "Proofpoint Operation Transparent Tribe March 2016", "url": "https://www.proofpoint.com/sites/default/files/proofpoint-operation-transparent-tribe-threat-insight-en.pdf"}], "id": "malware--6c2550d5-a01a-4bbb-a004-6ead348ba623", "is_family": true, "modified": "2025-04-25T14:43:41.735Z", "name": "Peppy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Peppy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-843', 0, 84, '09-mitre-attack', 'retrieved', '60B9C8FFC2333E6CE54858C069F94F86D084328DA3E3E02427C185B33139F705', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
