VALUES ('doc-09-mitre-attack-p0-844', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-12T15:47:08.197Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KEYPLUG](https://attack.mitre.org/software/S1051) is a modular backdoor written in C++, with Windows and Linux variants, that has been used by [APT41](https://attack.mitre.org/groups/G0096) since at least June 2021.(Citation: Mandiant APT41)", "external_references": [{"external_id": "S1051", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1051"}, {"description": "(Citation: Mandiant APT41)", "source_name": "KEYPLUG.LINUX"}, {"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "malware--6c575670-d14c-4c7f-9b9d-fd1b363e255d", "is_family": true, "modified": "2024-04-11T01:46:20.169Z", "name": "KEYPLUG", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KEYPLUG", "KEYPLUG.LINUX"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-844', 0, 111, '09-mitre-attack', 'retrieved', '89FE49E432907826284DE78BF82104BB0032EF80581D91D139604AE03F833409', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
