VALUES ('doc-09-mitre-attack-p0-845', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T22:05:58.411Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\n[Cuba](https://attack.mitre.org/software/S0625) is a Windows-based ransomware family that has been used against financial institutions, technology, and logistics organizations in North and South America as well as Europe since at least December 2019.(Citation: McAfee Cuba April 2021)", "external_references": [{"external_id": "S0625", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0625"}, {"description": "(Citation: McAfee Cuba April 2021)", "source_name": "Cuba"}, {"description": "Roccio, T., et al. (2021, April). Technical Analysis of Cuba Ransomware. Retrieved June 18, 2021.", "source_name": "McAfee Cuba April 2021", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-cuba-ransomware.pdf"}], "id": "malware--6cd07296-14aa-403d-9229-6343d03d4752", "is_family": true, "modified": "2025-04-25T14:43:42.282Z", "name": "Cuba", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cuba"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-845', 0, 113, '09-mitre-attack', 'retrieved', '613D4F61542AF6FC83FE2EF5C3717AC34A97447FA8576E6F4105BBEEBE79AB82', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
