VALUES ('doc-09-mitre-attack-p0-847', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-12T20:54:55.974Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Clambling](https://attack.mitre.org/software/S0660) is a modular backdoor written in C++ that has been used by [Threat Group-3390](https://attack.mitre.org/groups/G0027) since at least 2017.(Citation: Trend Micro DRBControl February 2020)", "external_references": [{"external_id": "S0660", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0660"}, {"description": "Lunghi, D. et al. (2020, February). Uncovering DRBControl. Retrieved November 12, 2021.", "source_name": "Trend Micro DRBControl February 2020", "url": "https://documents.trendmicro.com/assets/white_papers/wp-uncovering-DRBcontrol.pdf"}], "id": "malware--6e95feb1-78ee-48d3-b421-4d76663b5c49", "is_family": true, "modified": "2025-04-25T14:43:43.008Z", "name": "Clambling", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Clambling"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-847', 0, 85, '09-mitre-attack', 'retrieved', '39DDCED9CEA2B7C33DC6FA03EAE502E91851E0C23FDE9885CA00E2D0BB97A5EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
