VALUES ('doc-09-mitre-attack-p0-848', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T22:06:18.120Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "PureCrypter is a fully-featured malware loader, developed by a threat actor called “PureCoder,\" that has been in use since at least 2021 to distribute a variety of remote access trojans and information stealers.(Citation: Zscaler PureCrypter JUN 2022)", "external_references": [{"external_id": "S9019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9019"}, {"description": "Dumont, R. (2022, June 13). Technical Analysis of PureCrypter: A Fully-Functional Loader Distributing Remote Access Trojans and Information Stealers. Retrieved April 16, 2026.", "source_name": "Zscaler PureCrypter JUN 2022", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-purecrypter"}], "id": "malware--6f22487c-dbbf-4a5b-85ca-a8c85e8f2f80", "is_family": true, "modified": "2026-04-23T03:35:11.899Z", "name": "PureCrypter", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PureCrypter"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-848', 0, 110, '09-mitre-attack', 'retrieved', '1F4A98015392A56A76361DE25212E2DE902939B52641C18AFB5B0E310A0CDEA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
