VALUES ('doc-09-mitre-attack-p0-849', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-04T17:59:46.698Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Akira](https://attack.mitre.org/software/S1129) ransomware, written in C++, is most prominently (but not exclusively) associated with the ransomware-as-a-service entity [Akira](https://attack.mitre.org/groups/G1024). [Akira](https://attack.mitre.org/software/S1129) ransomware has been used in attacks across North America, Europe, and Australia, with a focus on critical infrastructure sectors including manufacturing, education, and IT services. [Akira](https://attack.mitre.org/software/S1129) ransomware employs hybrid encryption and threading to increase the speed and efficiency of encryption and runtime arguments for tailored attacks. Notable variants include Rust-based [Megazord](https://attack.mitre.org/software/S1191) for targeting Windows and [Akira _v2](https://attack.mitre.org/software/S1194) for targeting VMware ESXi servers.(Citation: Kersten Akira 2023)(Citation: CISA Akira Ransomware APR 2024)(Citation: Cisco Akira Ransomware OCT 2024)", "external_references": [{"external_id": "S1129", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1129"}, {"description": "CISA et al. (2024, April 18). #StopRansomware: Akira Ransomware. Retrieved December 10, 2024.", "source_name": "CISA Akira Ransomware APR 2024", "url": "https://www.cisa.gov/sites/default/files/2024-04/aa24-109a-stopransomware-akira-ransomware_2.pdf"}, {"description": "Max Kersten & Alexandre Mundo. (2023, November 29). Akira Ransomware. Retrieved April 4, 2024.", "source_name": "Kersten Akira 2023", "url": "https://www.trellix.com/blogs/research/akira-ransomware/"}, {"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}], "id": "malware--6f6b2353-4b39-40ce-9d6d-d00b7a61e656", "is_family": true, "modified": "2025-03-11T15:37:13.258Z", "name": "Akira", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Akira"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jiraput Thamsongkrah"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-849', 0, 207, '09-mitre-attack', 'retrieved', '9BE900BD8C59D5E92AD67764BE16EDB84B8E2E7BFC8330611FDBE55974476428', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
