VALUES ('doc-09-mitre-attack-p0-851', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-25T17:00:15.045Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mongall](https://attack.mitre.org/software/S1026) is a backdoor that has been used since at least 2013, including by [Aoqin Dragon](https://attack.mitre.org/groups/G1007).(Citation: SentinelOne Aoqin Dragon June 2022)", "external_references": [{"external_id": "S1026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1026"}, {"description": "Chen, Joey. (2022, June 9). Aoqin Dragon | Newly-Discovered Chinese-linked APT Has Been Quietly Spying On Organizations For 10 Years. Retrieved July 14, 2022.", "source_name": "SentinelOne Aoqin Dragon June 2022", "url": "https://www.sentinelone.com/labs/aoqin-dragon-newly-discovered-chinese-linked-apt-has-been-quietly-spying-on-organizations-for-10-years/"}], "id": "malware--6fb36c6f-bb3d-4ed6-9471-cb9933e5c154", "is_family": true, "modified": "2025-10-21T23:07:12.767Z", "name": "Mongall", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mongall"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-851', 0, 111, '09-mitre-attack', 'retrieved', '2DFDD7A1B55D5FEBCDB73ABBDF497E26BC89E1D58ECBFA5358D91D1C99BEBBD1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
