VALUES ('doc-09-mitre-attack-p0-853', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-05T21:28:23.240Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 3.0](https://attack.mitre.org/software/S1202) is an evolution of the LockBit Ransomware-as-a-Service (RaaS) offering with similarities to BlackMatter and [BlackCat](https://attack.mitre.org/software/S1068) ransomware. [LockBit 3.0](https://attack.mitre.org/software/S1202) has been in use since at least June 2022 and features enhanced defense evasion and exfiltration tactics, robust encryption methods for Windows and VMware ESXi systems, and a more refined RaaS structure over its predecessors such as [LockBit 2.0](https://attack.mitre.org/software/S1199).(Citation: Sentinel Labs LockBit 3.0 JUL 2022)(Citation: Joint Cybersecurity Advisory LockBit JUN 2023)(Citation: Joint Cybersecurity Advisory LockBit 3.0 MAR 2023)(Citation: INCIBE-CERT LockBit MAR 2024)", "external_references": [{"external_id": "S1202", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1202"}, {"description": "(Citation: Joint Cybersecurity Advisory LockBit JUN 2023)(Citation: Joint Cybersecurity Advisory LockBit 3.0 MAR 2023)(Citation: Sentinel Labs LockBit 3.0 JUL 2022)", "source_name": "LockBit Black"}, {"description": "CISA et al. (2023, June 14). UNDERSTANDING RANSOMWARE THREAT ACTORS: LOCKBIT. Retrieved February 5, 2025.", "source_name": "Joint Cybersecurity Advisory LockBit JUN 2023", "url": "https://www.cisa.gov/sites/default/files/2023-06/aa23-165a_understanding_TA_LockBit_0.pdf"}, {"description": "FBI et al. (2023, March 16). #StopRansomware: LockBit 3.0. Retrieved February 5, 2025.", "source_name": "Joint Cybersecurity Advisory LockBit 3.0 MAR 2023", "url": "https://www.cisa.gov/sites/default/files/2023-03/aa23-075a-stop-ransomware-lockbit.pdf"}, {"description": "INCIBE-CERT. (2024, March 14). LockBit: response and recovery actions. Retrieved February 5, 2025.", "source_name": "INCIBE-CERT LockBit MAR 2024", "url": "https://www.incibe.es/en/incibe-cert/blog/lockbit-response-and-recovery-actions"}, {"description": "Walter, J. (2022, July 21). LockBit 3.0 Update | Unpicking the Ransomware’s Latest Anti-Analysis and Evasion Techniques. Retrieved February 5, 2025.", "source_name": "Sentinel Labs LockBit 3.0 JUL 2022", "url": "https://www.sentinelone.com/labs/lockbit-3-0-update-unpicking-the-ransomwares-latest-anti-analysis-and-evasion-techniques"}], "id": "malware--71fe9df1-1c6f-430c-ab9b-ff3c11074e52", "is_family": true, "modified": "2025-10-21T23:34:46.898Z", "name": "LockBit 3.0", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LockBit 3.0", "LockBit Black"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Matt Brenton, Zurich Global Information Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-853', 0, 260, '09-mitre-attack', 'retrieved', '4040BD4D9DF1DB733D32150644E6121CAE4EF6A7CDAE0CDB48ECB1D5DA4D1AF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
