VALUES ('doc-09-mitre-attack-p0-854', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-10T18:05:56.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SVCReady](https://attack.mitre.org/software/S1064) is a loader that has been used since at least April 2022 in malicious spam campaigns. Security researchers have noted overlaps between [TA551](https://attack.mitre.org/groups/G0127) activity and [SVCReady](https://attack.mitre.org/software/S1064) distribution, including similarities in file names, lure images, and identical grammatical errors.(Citation: HP SVCReady Jun 2022)", "external_references": [{"external_id": "S1064", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1064"}, {"description": "Schlapfer, Patrick. (2022, June 6). A New Loader Gets Ready. Retrieved December 13, 2022.", "source_name": "HP SVCReady Jun 2022", "url": "https://threatresearch.ext.hp.com/svcready-a-new-loader-reveals-itself/"}], "id": "malware--7230ded7-3b1a-4d6e-9735-d0ffd47af9f6", "is_family": true, "modified": "2025-04-16T20:38:16.488Z", "name": "SVCReady", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SVCReady"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Manikantan Srinivasan, NEC Corporation India", "Akiko To, NEC Corporation", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-854', 0, 122, '09-mitre-attack', 'retrieved', '807EAF5E918688F768B731DEEA60D011EB3994E04432FACA78A005FE5294C092', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
