INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-855', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-19T16:26:04.260Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) is a virus, data stealer, and wiper that presents itself as ransomware targeting macOS systems. [ThiefQuest](https://attack.mitre.org/software/S0595) was first seen in 2020 distributed via trojanized pirated versions of popular macOS software on Russian forums sharing torrent links.(Citation: Reed thiefquest fake ransom) Even though [ThiefQuest](https://attack.mitre.org/software/S0595) presents itself as ransomware, since the dynamically generated encryption key is never sent to the attacker it may be more appropriately thought of as a form of wiper malware.(Citation: wardle evilquest partii)(Citation: reed thiefquest ransomware analysis)", "external_references": [{"external_id": "S0595", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0595"}, {"description": "(Citation: Reed thiefquest fake ransom)", "source_name": "ThiefQuest"}, {"description": "(Citation: Reed thiefquest fake ransom)", "source_name": "EvilQuest"}, {"description": "(Citation: SentinelOne EvilQuest Ransomware Spyware 2020)", "source_name": "MacRansom.K"}, {"description": "Patrick Wardle. (2020, July 3). OSX.EvilQuest Uncovered part ii: insidious capabilities. Retrieved March 21, 2021.", "source_name": "wardle evilquest partii", "url": "https://objective-see.com/blog/blog_0x60.html"}, {"description": "Phil Stokes. (2020, July 8). “EvilQuest” Rolls Ransomware, Spyware & Data Theft Into One. Retrieved April 1, 2021.", "source_name": "SentinelOne EvilQuest Ransomware Spyware 2020", "url": "https://www.sentinelone.com/blog/evilquest-a-new-macos-malware-rolls-ransomware-spyware-and-data-theft-into-one/"}, {"description": "Thomas Reed. (2020, July 7). Mac ThiefQuest malware may not be ransomware after all. Retrieved March 18, 2021.", "source_name": "Reed thiefquest fake ransom", "url": "https://blog.malwarebytes.com/detections/osx-thiefquest/"}, {"description": "Thomas Reed. (2020, July 7). Mac ThiefQuest malware may not be ransomware after all. Retrieved March 22, 2021.", "source_name": "reed thiefquest ransomware analysis", "url": "https://blog.malwarebytes.com/mac/2020/07/mac-thiefquest-malware-may-not-be-ransomware-after-all/"}], "id": "malware--727afb95-3d0f-4451-b297-362a43909923", "is_family": true, "modified": "2025-04-16T20:38:16.679Z", "name": "ThiefQuest", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ThiefQuest", "MacRansom.K", "EvilQuest"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-855', 0, 250, '09-mitre-attack', 'retrieved', '21CB213B543091750501B4D5364216A2CD5754F15032C1C71C7A0742F7B35973', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
