VALUES ('doc-09-mitre-attack-p0-856', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-16T14:33:46.321Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FoggyWeb](https://attack.mitre.org/software/S0661) is a passive and highly-targeted backdoor capable of remotely exfiltrating sensitive information from a compromised Active Directory Federated Services (AD FS) server. It has been used by [APT29](https://attack.mitre.org/groups/G0016) since at least early April 2021.(Citation: MSTIC FoggyWeb September 2021)", "external_references": [{"external_id": "S0661", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0661"}, {"description": "Ramin Nafisi. (2021, September 27). FoggyWeb: Targeted NOBELIUM malware leads to persistent backdoor. Retrieved October 4, 2021.", "source_name": "MSTIC FoggyWeb September 2021", "url": "https://www.microsoft.com/security/blog/2021/09/27/foggyweb-targeted-nobelium-malware-leads-to-persistent-backdoor/"}], "id": "malware--72911fe3-f085-40f7-b4f2-f25a4221fe44", "is_family": true, "modified": "2024-04-11T02:32:04.884Z", "name": "FoggyWeb", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FoggyWeb"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Craig Smith, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-856', 0, 111, '09-mitre-attack', 'retrieved', '27E851B318E3AC4B854B38EAF565375ABB5DDA95A85400278EB23F9B11080C73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
