VALUES ('doc-09-mitre-attack-p0-857', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-08T15:23:05.910Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NGLite](https://attack.mitre.org/software/S1106) is a backdoor Trojan that is only capable of running commands received through its C2 channel. While the capabilities are standard for a backdoor, NGLite uses a novel C2 channel that leverages a decentralized network based on the legitimate NKN to communicate between the backdoor and the actors.(Citation: NGLite Trojan)", "external_references": [{"external_id": "S1106", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1106"}, {"description": "Robert Falcone, Jeff White, and Peter Renals. (2021, November 7). Targeted Attack Campaign Against ManageEngine ADSelfService Plus Delivers Godzilla Webshells, NGLite Trojan and KdcSponge Stealer. Retrieved February 8, 2024.", "source_name": "NGLite Trojan", "url": "https://unit42.paloaltonetworks.com/manageengine-godzilla-nglite-kdcsponge/"}], "id": "malware--72b5f07f-5448-4e00-9ff2-08bc193a7b77", "is_family": true, "modified": "2024-04-19T13:24:36.873Z", "name": "NGLite", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NGLite"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-857', 0, 128, '09-mitre-attack', 'retrieved', 'B41B1415F6EA03F7A1F131287C89E009FD273AA662CA01890469C14D44341388', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
