VALUES ('doc-09-mitre-attack-p0-858', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:22.213Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Carbanak](https://attack.mitre.org/software/S0030) is a full-featured, remote backdoor used by a group of the same name ([Carbanak](https://attack.mitre.org/groups/G0008)). It is intended for espionage, data exfiltration, and providing remote access to infected machines. (Citation: Kaspersky Carbanak) (Citation: FireEye CARBANAK June 2017)", "external_references": [{"external_id": "S0030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0030"}, {"description": "(Citation: FireEye CARBANAK June 2017)", "source_name": "Carbanak"}, {"description": "(Citation: Fox-It Anunak Feb 2015) (Citation: FireEye CARBANAK June 2017)", "source_name": "Anunak"}, {"description": "Bennett, J., Vengerik, B. (2017, June 12). Behind the CARBANAK Backdoor. Retrieved June 11, 2018.", "source_name": "FireEye CARBANAK June 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/06/behind-the-carbanak-backdoor.html"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2015, February). CARBANAK APT THE GREAT BANK ROBBERY. Retrieved August 23, 2018.", "source_name": "Kaspersky Carbanak", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/08064518/Carbanak_APT_eng.pdf"}, {"description": "Prins, R. (2015, February 16). Anunak (aka Carbanak) Update. Retrieved January 20, 2017.", "source_name": "Fox-It Anunak Feb 2015", "url": "https://www.fox-it.com/en/news/blog/anunak-aka-carbanak-update/"}], "id": "malware--72f54d66-675d-4587-9bd3-4ed09f9522e4", "is_family": true, "modified": "2025-04-16T20:38:16.838Z", "name": "Carbanak", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Carbanak", "Anunak"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-858', 0, 170, '09-mitre-attack', 'retrieved', '5309AD737625A7E4EB61BD72018E9AD15D338EB76CB447820EE4A5E632596BA7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
