VALUES ('doc-09-mitre-attack-p0-859', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:09.453Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XTunnel](https://attack.mitre.org/software/S0117) a VPN-like network proxy tool that can relay traffic between a C2 server and a victim. It was first seen in May 2013 and reportedly used by [APT28](https://attack.mitre.org/groups/G0007) during the compromise of the Democratic National Committee. (Citation: Crowdstrike DNC June 2016) (Citation: Invincea XTunnel) (Citation: ESET Sednit Part 2)", "external_references": [{"external_id": "S0117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0117"}, {"description": "(Citation: ESET Sednit Part 2)", "source_name": "XTunnel"}, {"description": "(Citation: Symantec APT28 Oct 2018)", "source_name": "Trojan.Shunnael"}, {"description": "(Citation: Crowdstrike DNC June 2016)(Citation: Symantec APT28 Oct 2018)", "source_name": "X-Tunnel"}, {"description": "(Citation: ESET Sednit Part 2)", "source_name": "XAPS"}, {"description": "Alperovitch, D.. (2016, June 15). Bears in the Midst: Intrusion into the Democratic National Committee. Retrieved August 3, 2016.", "source_name": "Crowdstrike DNC June 2016", "url": "https://www.crowdstrike.com/blog/bears-midst-intrusion-democratic-national-committee/"}, {"description": "Belcher, P.. (2016, July 28). Tunnel of Gov: DNC Hack and the Russian XTunnel. Retrieved August 3, 2016.", "source_name": "Invincea XTunnel", "url": "https://www.invincea.com/2016/07/tunnel-of-gov-dnc-hack-and-the-russian-xtunnel/"}, {"description": "ESET. (2016, October). En Route with Sednit - Part 2: Observing the Comings and Goings. Retrieved November 21, 2016.", "source_name": "ESET Sednit Part 2", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part-2.pdf"}, {"description": "Symantec Security Response. (2018, October 04). APT28: New Espionage Operations Target Military and Government Organizations. Retrieved November 14, 2018.", "source_name": "Symantec APT28 Oct 2018", "url": "https://www.symantec.com/blogs/election-security/apt28-espionage-military-government"}], "id": "malware--7343e208-7cab-45f2-a47b-41ba5e2f0fab", "is_family": true, "modified": "2025-04-25T14:43:45.148Z", "name": "XTunnel", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["XTunnel", "Trojan.Shunnael", "X-Tunnel", "XAPS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-859', 0, 234, '09-mitre-attack', 'retrieved', '869199BE305FD63DA91DECC89FC98694AB005721150F003C96E998002F6ED30C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
