VALUES ('doc-09-mitre-attack-p0-860', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hydraq](https://attack.mitre.org/software/S0203) is a data-theft trojan first used by [Elderwood](https://attack.mitre.org/groups/G0066) in the 2009 Google intrusion known as Operation Aurora, though variations of this trojan have been used in more recent campaigns by other Chinese actors, possibly including [APT17](https://attack.mitre.org/groups/G0025).(Citation: MicroFocus 9002 Aug 2016)(Citation: Symantec Elderwood Sept 2012)(Citation: Symantec Trojan.Hydraq Jan 2010)(Citation: ASERT Seven Pointed Dagger Aug 2015)(Citation: FireEye DeputyDog 9002 November 2013)(Citation: ProofPoint GoT 9002 Aug 2017)(Citation: FireEye Sunshop Campaign May 2013)(Citation: PaloAlto 3102 Sept 2015)", "external_references": [{"external_id": "S0203", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0203"}, {"description": "(Citation: MicroFocus 9002 Aug 2016)", "source_name": "9002 RAT"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Roarur"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "MdmBot"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "HomeUnix"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Homux"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "HidraQ"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "HydraQ"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "McRat"}, {"description": "(Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Trojan.Hydraq Jan 2010)", "source_name": "Hydraq"}, {"description": "(Citation: Symantec Elderwood Sept 2012)(Citation: Symantec Trojan.Hydraq Jan 2010)", "source_name": "Aurora"}, {"description": "ASERT. (2015, August). ASERT Threat Intelligence Report – Uncovering the Seven Pointed Dagger. Retrieved March 19, 2018.", "source_name": "ASERT Seven Pointed Dagger Aug 2015", "url": "https://www.arbornetworks.com/blog/asert/wp-content/uploads/2016/01/ASERT-Threat-Intelligence-Brief-2015-08-Uncovering-the-Seven-Point-Dagger.pdf"}, {"description": "Falcone, R. & Miller-Osborn, J. (2015, September 23). Chinese Actors Use ‘3102’ Malware in Attacks on US Government and EU Media. Retrieved March 19, 2018.", "source_name": "PaloAlto 3102 Sept 2015", "url": "https://researchcenter.paloaltonetworks.com/2015/09/chinese-actors-use-3102-malware-in-attacks-on-us-government-and-eu-media/"}, {"description": "Huss, D. & Mesa, M. (2017, August 25). Operation RAT Cook: Chinese APT actors use fake Game of Thrones leaks as lures. Retrieved March 19, 2018.", "source_name": "ProofPoint GoT 9002 Aug 2017", "url": "https://www.proofpoint.com/us/threat-insight/post/operation-rat-cook-chinese-apt-actors-use-fake-game-thrones-leaks-lures"}, {"description": "Moran, N. (2013, May 20). Ready for Summer: The Sunshop Campaign. Retrieved November 17, 2024.", "source_name": "FireEye Sunshop Campaign May 2013", "url": "https://web.archive.org/web/20200302085651/https://www.fireeye.com/blog/threat-research/2013/05/ready-for-summer-the-sunshop-campaign.html"}, {"description": "Moran, N. et al.. (2013, November 10). Operation Ephemeral Hydra: IE Zero-Day Linked to DeputyDog Uses Diskless Method. Retrieved November 17, 2024.", "source_name": "FireEye DeputyDog 9002 November 2013", "url": "https://web.archive.org/web/20190221032148/http://www.fireeye.com/blog/threat-research/2013/11/operation-ephemeral-hydra-ie-zero-day-linked-to-deputydog-uses-diskless-method.html"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}, {"description": "Petrovsky, O. (2016, August 30). “9002 RAT” -- a second building on the left. Retrieved February 20, 2018.", "source_name": "MicroFocus 9002 Aug 2016", "url": "https://community.softwaregrp.com/t5/Security-Research/9002-RAT-a-second-building-on-the-left/ba-p/228686#.WosBVKjwZPZ"}, {"description": "Symantec Security Response. (2010, January 18). The Trojan.Hydraq Incident. Retrieved February 20, 2018.", "source_name": "Symantec Trojan.Hydraq Jan 2010", "url": "https://www.symantec.com/connect/blogs/trojanhydraq-incident"}], "id": "malware--73a4793a-ce55-4159-b2a6-208ef29b326f", "is_family": true, "modified": "2024-11-17T19:55:07.589Z", "name": "Hydraq", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hydraq", "Roarur", "MdmBot", "HomeUnix", "Homux", "HidraQ", "HydraQ", "McRat", "Aurora", "9002 RAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-860', 0, 433, '09-mitre-attack', 'retrieved', '1DDAD035C46867D99D25510F419DC154B95D58E5BD8A925B63F9CD439760CD6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
