VALUES ('doc-09-mitre-attack-p0-861', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T19:51:37.488Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SHARPSTATS](https://attack.mitre.org/software/S0450) is a .NET backdoor used by [MuddyWater](https://attack.mitre.org/groups/G0069) since at least 2019.(Citation: TrendMicro POWERSTATS V3 June 2019)", "external_references": [{"external_id": "S0450", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0450"}, {"description": "Lunghi, D. and Horejsi, J.. (2019, June 10). MuddyWater Resurfaces, Uses Multi-Stage Backdoor POWERSTATS V3 and New Post-Exploitation Tools. Retrieved May 14, 2020.", "source_name": "TrendMicro POWERSTATS V3 June 2019", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/muddywater-resurfaces-uses-multi-stage-backdoor-powerstats-v3-and-new-post-exploitation-tools/"}], "id": "malware--73c4711b-407a-449d-b269-e3b1531fe7a9", "is_family": true, "modified": "2025-04-16T20:38:17.168Z", "name": "SHARPSTATS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SHARPSTATS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-861', 0, 91, '09-mitre-attack', 'retrieved', '4F4E31000AAFF95B76603ED77F2E03B4BEE7731287B522AB02A51D4E6A407FCE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
