VALUES ('doc-09-mitre-attack-p0-862', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-01T19:19:26.408Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ferocious](https://attack.mitre.org/software/S0679) is a first stage implant composed of VBS and PowerShell scripts that has been used by [WIRTE](https://attack.mitre.org/groups/G0090) since at least 2021.(Citation: Kaspersky WIRTE November 2021)", "external_references": [{"external_id": "S0679", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0679"}, {"description": "Yamout, M. (2021, November 29). WIRTE’s campaign in the Middle East ‘living off the land’ since at least 2019. Retrieved February 1, 2022.", "source_name": "Kaspersky WIRTE November 2021", "url": "https://securelist.com/wirtes-campaign-in-the-middle-east-living-off-the-land-since-at-least-2019/105044"}], "id": "malware--73d08401-005f-4e1f-90b9-8f45d120879f", "is_family": true, "modified": "2025-04-25T14:43:45.868Z", "name": "Ferocious", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ferocious"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-862', 0, 97, '09-mitre-attack', 'retrieved', '618378509E16C2C39BD87E2CDE250521EAB4D58C38681031DAC6A85BEF10D378', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
