VALUES ('doc-09-mitre-attack-p0-864', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-07T14:30:25.403Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CreepyDrive](https://attack.mitre.org/software/S1023) is a custom implant has been used by [POLONIUM](https://attack.mitre.org/groups/G1005) since at least early 2022 for C2 with and exfiltration to actor-controlled OneDrive accounts.(Citation: Microsoft POLONIUM June 2022)\n\n[POLONIUM](https://attack.mitre.org/groups/G1005) has used a similar implant called CreepyBox that relies on actor-controlled DropBox accounts.(Citation: Microsoft POLONIUM June 2022)", "external_references": [{"external_id": "S1023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1023"}, {"description": "Microsoft. (2022, June 2). Exposing POLONIUM activity and infrastructure targeting Israeli organizations. Retrieved July 1, 2022.", "source_name": "Microsoft POLONIUM June 2022", "url": "https://www.microsoft.com/security/blog/2022/06/02/exposing-polonium-activity-and-infrastructure-targeting-israeli-organizations/"}], "id": "malware--750eb92a-7fdf-451e-9592-1d42357018f1", "is_family": true, "modified": "2025-04-16T20:38:17.473Z", "name": "CreepyDrive", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CreepyDrive"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-864', 0, 113, '09-mitre-attack', 'retrieved', '0B718AD8D25E89D28DEE9C6091EBF5A10BFF9E6D2F5D1B8E6D315CDF82132EA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
