VALUES ('doc-09-mitre-attack-p0-866', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-26T21:02:38.186Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Netwalker](https://attack.mitre.org/software/S0457) is fileless ransomware written in PowerShell and executed directly in memory.(Citation: TrendMicro Netwalker May 2020)", "external_references": [{"external_id": "S0457", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0457"}, {"description": "Victor, K.. (2020, May 18). Netwalker Fileless Ransomware Injected via Reflective Loading . Retrieved May 26, 2020.", "source_name": "TrendMicro Netwalker May 2020", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/netwalker-fileless-ransomware-injected-via-reflective-loading/"}], "id": "malware--754effde-613c-4244-a83e-fb659b2a4d06", "is_family": true, "modified": "2025-04-16T20:38:17.793Z", "name": "Netwalker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Netwalker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-866', 0, 83, '09-mitre-attack', 'retrieved', 'D544707073AF5ED10D87567E5BF835A512025AB5982BDB95CD09F5F347EB070F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
