VALUES ('doc-09-mitre-attack-p0-867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:54.416Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Elise](https://attack.mitre.org/software/S0081) is a custom backdoor Trojan that appears to be used exclusively by [Lotus Blossom](https://attack.mitre.org/groups/G0030). It is part of a larger group of tools referred to as LStudio, ST Group, and APT0LSTU.(Citation: Lotus Blossom Jun 2015)(Citation: Accenture Dragonfish Jan 2018)", "external_references": [{"external_id": "S0081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0081"}, {"description": "(Citation: Accenture Dragonfish Jan 2018)", "source_name": "Elise"}, {"description": "(Citation: Lotus Blossom Jun 2015)", "source_name": "BKDR_ESILE"}, {"description": "(Citation: Lotus Blossom Jun 2015)", "source_name": "Page"}, {"description": "Accenture Security. (2018, January 27). DRAGONFISH DELIVERS NEW FORM OF ELISE MALWARE TARGETING ASEAN DEFENCE MINISTERS’ MEETING AND ASSOCIATES. Retrieved November 17, 2024.", "source_name": "Accenture Dragonfish Jan 2018", "url": "https://web.archive.org/web/20190508165226/https://www.accenture.com/t20180127T003755Z_w_/us-en/_acnmedia/PDF-46/Accenture-Security-Dragonfish-Threat-Analysis.pdf"}, {"description": "Falcone, R., et al.. (2015, June 16). Operation Lotus Blossom. Retrieved February 15, 2016.", "source_name": "Lotus Blossom Jun 2015", "url": "https://www.paloaltonetworks.com/resources/research/unit42-operation-lotus-blossom.html"}], "id": "malware--7551188b-8f91-4d34-8350-0d0c57b2b913", "is_family": true, "modified": "2025-04-02T20:34:59.728Z", "name": "Elise", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Elise", "BKDR_ESILE", "Page"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-867', 0, 161, '09-mitre-attack', 'retrieved', '426225630AC2EF32EF0DBC96D2E0AD9122FACD9F157F8FDD1E82D8B5D95D9728', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
