INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-869', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-25T17:30:17.004Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WannaCry](https://attack.mitre.org/software/S0366) is ransomware that was first seen in a global attack during May 2017, which affected more than 150 countries. It contains worm-like features to spread itself across a computer network using the SMBv1 exploit EternalBlue.(Citation: LogRhythm WannaCry)(Citation: US-CERT WannaCry 2017)(Citation: Washington Post WannaCry 2017)(Citation: FireEye WannaCry 2017)", "external_references": [{"external_id": "S0366", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0366"}, {"description": "(Citation: LogRhythm WannaCry)", "source_name": "WanaCrypt0r"}, {"description": "(Citation: LogRhythm WannaCry)(Citation: SecureWorks WannaCry Analysis)", "source_name": "WCry"}, {"description": "(Citation: SecureWorks WannaCry Analysis)", "source_name": "WanaCry"}, {"description": "(Citation: SecureWorks WannaCry Analysis)", "source_name": "WanaCrypt"}, {"description": "Berry, A., Homan, J., and Eitzman, R. (2017, May 23). WannaCry Malware Profile. Retrieved March 15, 2019.", "source_name": "FireEye WannaCry 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/05/wannacry-malware-profile.html"}, {"description": "Counter Threat Unit Research Team. (2017, May 18). WCry Ransomware Analysis. Retrieved March 26, 2019.", "source_name": "SecureWorks WannaCry Analysis", "url": "https://www.secureworks.com/research/wcry-ransomware-analysis"}, {"description": "Dwoskin, E. and Adam, K. (2017, May 14). More than 150 countries affected by massive cyberattack, Europol says. Retrieved March 25, 2019.", "source_name": "Washington Post WannaCry 2017", "url": "https://www.washingtonpost.com/business/economy/more-than-150-countries-affected-by-massive-cyberattack-europol-says/2017/05/14/5091465e-3899-11e7-9e48-c4f199710b69_story.html?utm_term=.7fa16b41cad4"}, {"description": "Noerenberg, E., Costis, A., and Quist, N. (2017, May 16). A Technical Analysis of WannaCry Ransomware. Retrieved December 8, 2024.", "source_name": "LogRhythm WannaCry", "url": "https://web.archive.org/web/20230522041200/https://logrhythm.com/blog/a-technical-analysis-of-wannacry-ransomware/"}, {"description": "US-CERT. (2017, May 12). Alert (TA17-132A): Indicators Associated With WannaCry Ransomware. Retrieved March 25, 2019.", "source_name": "US-CERT WannaCry 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-132A"}], "id": "malware--75ecdbf1-c2bb-4afc-a3f9-c8da4de8c661", "is_family": true, "modified": "2024-12-09T02:29:13.859Z", "name": "WannaCry", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WannaCry", "WanaCry", "WanaCrypt", "WanaCrypt0r", "WCry"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jan Miller, CrowdStrike"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-869', 0, 252, '09-mitre-attack', 'retrieved', '3600AFEC111E66B1541D82FA299750CC8C4375F5023B59D5364CCF5D368DFA88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
