VALUES ('doc-09-mitre-attack-p0-870', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gazer](https://attack.mitre.org/software/S0168) is a backdoor used by [Turla](https://attack.mitre.org/groups/G0010) since at least 2016. (Citation: ESET Gazer Aug 2017)", "external_references": [{"external_id": "S0168", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0168"}, {"description": "(Citation: ESET Gazer Aug 2017)", "source_name": "Gazer"}, {"description": "ESET. (2017, August). Gazing at Gazer: Turla’s new second stage backdoor. Retrieved September 14, 2017.", "source_name": "ESET Gazer Aug 2017", "url": "https://www.welivesecurity.com/wp-content/uploads/2017/08/eset-gazer.pdf"}, {"description": "Faou, M. (2020, December 2). Turla Crutch: Keeping the “back door” open. Retrieved December 4, 2020.", "source_name": "ESET Crutch December 2020", "url": "https://www.welivesecurity.com/2020/12/02/turla-crutch-keeping-back-door-open/"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2017, August 30). Introducing WhiteBear. Retrieved September 21, 2017.", "source_name": "Securelist WhiteBear Aug 2017", "url": "https://securelist.com/introducing-whitebear/81638/"}, {"description": "The term WhiteBear is used both for the activity group (a subset of G0010) as well as the malware observed. Based on similarities in behavior and C2, WhiteBear is assessed to be the same as S0168. (Citation: Securelist WhiteBear Aug 2017)(Citation: ESET Crutch December 2020)", "source_name": "WhiteBear"}], "id": "malware--76abb3ef-dafd-4762-97cb-a35379429db4", "is_family": true, "modified": "2024-04-11T02:28:51.206Z", "name": "Gazer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Gazer", "WhiteBear"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Bartosz Jerzman"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-870', 0, 189, '09-mitre-attack', 'retrieved', '8C3CE43858E3ED1DD0CD2D5421FC189F979ADFD50E90CFA6CDB0A794D0B19B33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
