VALUES ('doc-09-mitre-attack-p0-871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T15:43:49.556Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TSCookie](https://attack.mitre.org/software/S0436) is a remote access tool (RAT) that has been used by [BlackTech](https://attack.mitre.org/groups/G0098) in campaigns against Japanese targets.(Citation: JPCert TSCookie March 2018)(Citation: JPCert BlackTech Malware September 2019). [TSCookie](https://attack.mitre.org/software/S0436) has been referred to as [PLEAD](https://attack.mitre.org/software/S0435) though more recent reporting indicates a separation between the two.(Citation: JPCert PLEAD Downloader June 2018)(Citation: JPCert BlackTech Malware September 2019)", "external_references": [{"external_id": "S0436", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0436"}, {"description": "Tomonaga, S. (2018, June 8). PLEAD Downloader Used by BlackTech. Retrieved May 6, 2020.", "source_name": "JPCert PLEAD Downloader June 2018", "url": "https://blogs.jpcert.or.jp/en/2018/03/malware-tscooki-7aa0.html"}, {"description": "Tomonaga, S. (2018, March 6). Malware “TSCookie”. Retrieved May 6, 2020.", "source_name": "JPCert TSCookie March 2018", "url": "https://blogs.jpcert.or.jp/en/2018/03/malware-tscooki-7aa0.html"}, {"description": "Tomonaga, S.. (2019, September 18). Malware Used by BlackTech after Network Intrusion. Retrieved May 6, 2020.", "source_name": "JPCert BlackTech Malware September 2019", "url": "https://blogs.jpcert.or.jp/en/2019/09/tscookie-loader.html"}], "id": "malware--76ac7989-c5cc-42e2-93e3-d6c476f01ace", "is_family": true, "modified": "2025-04-16T20:38:18.117Z", "name": "TSCookie", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TSCookie"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Tatsuya Daitoku, Cyber Defense Institute, Inc."], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-871', 0, 170, '09-mitre-attack', 'retrieved', 'C469BB7CA29080059322134477B53FA454204BF8439CD931C2B01838DC9DF6F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
