INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-872', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-16T18:47:30.547Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) is a Windows malware downloader that has been used since at least 2023 to download and execute additional payloads and modules. [Latrodectus](https://attack.mitre.org/software/S1160) has most often been distributed through email campaigns, primarily by [TA577](https://attack.mitre.org/groups/G1037) and [TA578](https://attack.mitre.org/groups/G1038), and has infrastructure overlaps with historic [IcedID](https://attack.mitre.org/software/S0483) operations.(Citation: Latrodectus APR 2024)(Citation: Bleeping Computer Latrodectus April 2024)(Citation: Bitsight Latrodectus June 2024)", "external_references": [{"external_id": "S1160", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1160"}, {"description": "(Citation: Bleeping Computer Latrodectus April 2024)", "source_name": "IceNova"}, {"description": "(Citation: Bleeping Computer Latrodectus April 2024)", "source_name": "Unidentified 111"}, {"description": "Abrams, L. (2024, April 30). New Latrodectus malware attacks use Microsoft, Cloudflare themes. Retrieved September 13, 2024.", "source_name": "Bleeping Computer Latrodectus April 2024", "url": "https://www.bleepingcomputer.com/news/security/new-latrodectus-malware-attacks-use-microsoft-cloudflare-themes/"}, {"description": "Batista, J. (2024, June 17). Latrodectus, are you coming back?. Retrieved September 13, 2024.", "source_name": "Bitsight Latrodectus June 2024", "url": "https://www.bitsight.com/blog/latrodectus-are-you-coming-back"}, {"description": "Proofpoint Threat Research and Team Cymru S2 Threat Research. (2024, April 4). Latrodectus: This Spider Bytes Like Ice . Retrieved May 31, 2024.", "source_name": "Latrodectus APR 2024", "url": "https://www.proofpoint.com/us/blog/threat-insight/latrodectus-spider-bytes-ice"}], "id": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "is_family": true, "modified": "2024-09-30T17:59:30.330Z", "name": "Latrodectus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Latrodectus", "IceNova", "Unidentified 111"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Riku Katsuse, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India", "Cris Tomboc, Truswave SpiderLabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-872', 0, 217, '09-mitre-attack', 'retrieved', '24086A4EDDB5E9C3E7207A2EEB28CE4316E1A034688DA7C20B170C86CDCF516F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
