VALUES ('doc-09-mitre-attack-p0-874', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-04T15:12:14.805Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pay2Key](https://attack.mitre.org/software/S0556) is a ransomware written in C++ that has been used by [Fox Kitten](https://attack.mitre.org/groups/G0117) since at least July 2020 including campaigns against Israeli companies. [Pay2Key](https://attack.mitre.org/software/S0556) has been incorporated with a leak site to display stolen sensitive information to further pressure victims into payment.(Citation: ClearkSky Fox Kitten February 2020)(Citation: Check Point Pay2Key November 2020)", "external_references": [{"external_id": "S0556", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0556"}, {"description": "ClearSky. (2020, February 16). Fox Kitten – Widespread Iranian Espionage-Offensive Campaign. Retrieved December 21, 2020.", "source_name": "ClearkSky Fox Kitten February 2020", "url": "https://www.clearskysec.com/fox-kitten/"}, {"description": "Check Point. (2020, November 6). Ransomware Alert: Pay2Key. Retrieved January 4, 2021.", "source_name": "Check Point Pay2Key November 2020", "url": "https://research.checkpoint.com/2020/ransomware-alert-pay2key/"}], "id": "malware--77ca1aa3-280c-4b67-abaa-e8fb891a8f83", "is_family": true, "modified": "2025-04-25T14:43:48.585Z", "name": "Pay2Key", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pay2Key"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-874', 0, 138, '09-mitre-attack', 'retrieved', '289500712273FA5D6DEFD3F1ADE289AFE77885BAE184D23F286739521262B555', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
