VALUES ('doc-09-mitre-attack-p0-875', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-30T16:13:40.232Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chaes](https://attack.mitre.org/software/S0631) is a multistage information stealer written in several programming languages that collects login credentials, credit card numbers, and other financial information. [Chaes](https://attack.mitre.org/software/S0631) was first observed in 2020, and appears to primarily target victims in Brazil as well as other e-commerce customers in Latin America.(Citation: Cybereason Chaes Nov 2020)", "external_references": [{"external_id": "S0631", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0631"}, {"description": "(Citation: Cybereason Chaes Nov 2020)", "source_name": "Chaes"}, {"description": "Salem, E. (2020, November 17). CHAES: Novel Malware Targeting Latin American E-Commerce. Retrieved June 30, 2021.", "source_name": "Cybereason Chaes Nov 2020", "url": "https://www.cybereason.com/hubfs/dam/collateral/reports/11-2020-Chaes-e-commerce-malware-research.pdf"}], "id": "malware--77e0ecf7-ca91-4c06-8012-8e728986a87a", "is_family": true, "modified": "2025-04-16T20:38:18.426Z", "name": "Chaes", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Chaes"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-875', 0, 128, '09-mitre-attack', 'retrieved', '2B23635A98DE1D68C16A6F251454DEBC33F9BBB854DAEF3A7AD7D71C8A543625', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
