VALUES ('doc-09-mitre-attack-p0-876', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T14:45:26.266Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LODEINFO](https://attack.mitre.org/software/S9020) is a fileless backdoor malware first identified in 2020 that has been used by actors including [MirrorFace](https://attack.mitre.org/groups/G1054), primarily against media, diplomatic, governmental, and public sector organizations in Japan.(Citation: Kaspersky LODEINFO OCT 2022)(Citation: ITOCHU LODEINFO JAN 2024)(Citation: ESET MirrorFace DEC 2022)", "external_references": [{"external_id": "S9020", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9020"}, {"description": "Breitenbacher, D. (2022, December 14). Unmasking MirrorFace: Operation LiberalFace targeting Japanese political entities. Retrieved April 17, 2026.", "source_name": "ESET MirrorFace DEC 2022", "url": "https://www.welivesecurity.com/2022/12/14/unmasking-mirrorface-operation-liberalface-targeting-japanese-political-entities/"}, {"description": "Ishimaru, S. (2022, October 31). APT10: Tracking down LODEINFO 2022, part I. Retrieved April 17, 2026.", "source_name": "Kaspersky LODEINFO OCT 2022", "url": "https://securelist.com/apt10-tracking-down-lodeinfo-2022-part-i/107742/"}, {"description": "ITOCHU. (2024, January 24). The Endless Struggle Against APT10: Insights from LODEINFO v0.6.6 - v0.7.3 Analysis. Retrieved April 17, 2026.", "source_name": "ITOCHU LODEINFO JAN 2024", "url": "https://blog-en.itochuci.co.jp/entry/2024/01/24/134100"}], "id": "malware--7908f855-5b5b-4d6a-acbc-af6b45ec27ad", "is_family": true, "modified": "2026-05-12T15:12:00.735Z", "name": "LODEINFO", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LODEINFO"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-876', 0, 164, '09-mitre-attack', 'retrieved', '9EEB24EB04A17AFBB0D48BC859E9253BE8DD05ACDFCCE1CFB55E9D01B09B9770', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
