VALUES ('doc-09-mitre-attack-p0-877', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Briba](https://attack.mitre.org/software/S0204) is a trojan used by [Elderwood](https://attack.mitre.org/groups/G0066) to open a backdoor and download files on to compromised hosts. (Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Briba May 2012)", "external_references": [{"external_id": "S0204", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0204"}, {"description": "(Citation: Symantec Briba May 2012)", "source_name": "Briba"}, {"description": "Ladley, F. (2012, May 15). Backdoor.Briba. Retrieved February 21, 2018.", "source_name": "Symantec Briba May 2012", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2012-051515-2843-99"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}], "id": "malware--79499993-a8d6-45eb-b343-bf58dea5bdde", "is_family": true, "modified": "2024-11-17T19:55:07.590Z", "name": "Briba", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Briba"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-877', 0, 119, '09-mitre-attack', 'retrieved', '678BE74D736C985ED35F3C809ECCB0940CC95CDE9E5DA39915FF8A9B7A930C28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
