VALUES ('doc-09-mitre-attack-p0-878', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-01-24T16:56:36.108Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CharmPower](https://attack.mitre.org/software/S0674) is a PowerShell-based, modular backdoor that has been used by [Magic Hound](https://attack.mitre.org/groups/G0059) since at least 2022.(Citation: Check Point APT35 CharmPower January 2022)", "external_references": [{"external_id": "S0674", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0674"}, {"description": "Check Point. (2022, January 11). APT35 exploits Log4j vulnerability to distribute new modular PowerShell toolkit. Retrieved January 24, 2022.", "source_name": "Check Point APT35 CharmPower January 2022", "url": "https://research.checkpoint.com/2022/apt35-exploits-log4j-vulnerability-to-distribute-new-modular-powershell-toolkit/"}], "id": "malware--7acb15b6-fe2c-4319-b136-6ab36ff0b2d4", "is_family": true, "modified": "2025-06-06T14:12:30.197Z", "name": "CharmPower", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CharmPower"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-878', 0, 94, '09-mitre-attack', 'retrieved', 'E066C92104B3CDC49F70CAA016987458706850AEB331F44DEEAF6E8CE5AA9BA3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
