VALUES ('doc-09-mitre-attack-p0-880', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TYPEFRAME](https://attack.mitre.org/software/S0263) is a remote access tool that has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032). (Citation: US-CERT TYPEFRAME June 2018)", "external_references": [{"external_id": "S0263", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0263"}, {"description": "(Citation: US-CERT TYPEFRAME June 2018)", "source_name": "TYPEFRAME"}, {"description": "US-CERT. (2018, June 14). MAR-10135536-12 – North Korean Trojan: TYPEFRAME. Retrieved July 13, 2018.", "source_name": "US-CERT TYPEFRAME June 2018", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR18-165A"}], "id": "malware--7ba0fc46-197d-466d-8b9f-f1c64d5d81e5", "is_family": true, "modified": "2026-05-12T15:12:00.735Z", "name": "TYPEFRAME", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TYPEFRAME"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-880', 0, 90, '09-mitre-attack', 'retrieved', '1FD752B46D11226835B7B0AA173BC695B3CB636031652A36DB10184E5B30F408', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
