VALUES ('doc-09-mitre-attack-p0-881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:44.131Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[3PARA RAT](https://attack.mitre.org/software/S0066) is a remote access tool (RAT) programmed in C++ that has been used by [Putter Panda](https://attack.mitre.org/groups/G0024). (Citation: CrowdStrike Putter Panda)", "external_references": [{"external_id": "S0066", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0066"}, {"description": "Crowdstrike Global Intelligence Team. (2014, June 9). CrowdStrike Intelligence Report: Putter Panda. Retrieved January 22, 2016.", "source_name": "CrowdStrike Putter Panda", "url": "http://cdn0.vox-cdn.com/assets/4589853/crowdstrike-intelligence-report-putter-panda.original.pdf"}], "id": "malware--7bec698a-7e20-4fd3-bb6a-12787770fb1a", "is_family": true, "modified": "2025-04-25T14:43:49.838Z", "name": "3PARA RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["3PARA RAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-881', 0, 87, '09-mitre-attack', 'retrieved', '91525D938FAA047FE5FDFBAADBCFC48282D39A44A0588E76CB873F65C58B2034', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
