VALUES ('doc-09-mitre-attack-p0-882', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-01T19:34:28.366Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bundlore](https://attack.mitre.org/software/S0482) is adware written for macOS that has been in use since at least 2015. Though categorized as adware, [Bundlore](https://attack.mitre.org/software/S0482) has many features associated with more traditional backdoors.(Citation: MacKeeper Bundlore Apr 2019)", "external_references": [{"external_id": "S0482", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0482"}, {"description": "(Citation: MacKeeper Bundlore Apr 2019)", "source_name": "OSX.Bundlore"}, {"description": "Sushko, O. (2019, April 17). macOS Bundlore: Mac Virus Bypassing macOS Security Features. Retrieved June 30, 2020.", "source_name": "MacKeeper Bundlore Apr 2019", "url": "https://mackeeper.com/blog/post/610-macos-bundlore-adware-analysis/"}], "id": "malware--7bef1b56-4870-4e74-b32a-7dd88c390c44", "is_family": true, "modified": "2025-04-25T14:43:50.199Z", "name": "Bundlore", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bundlore", "OSX.Bundlore"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-882', 0, 106, '09-mitre-attack', 'retrieved', '5BEA2C0D10BD8915BE755B059F07CE061F5A9FC4EB8F69D0726987B6858EB766', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
