VALUES ('doc-09-mitre-attack-p0-883', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-21T15:02:47.928Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[P8RAT](https://attack.mitre.org/software/S0626) is a fileless malware used by [menuPass](https://attack.mitre.org/groups/G0045) to download and execute payloads since at least 2020.(Citation: Securelist APT10 March 2021)", "external_references": [{"external_id": "S0626", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0626"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "HEAVYPOT"}, {"description": "(Citation: Securelist APT10 March 2021)", "source_name": "GreetCake"}, {"description": "GREAT. (2021, March 30). APT10: sophisticated multi-layered loader Ecipekac discovered in A41APT campaign. Retrieved June 17, 2021.", "source_name": "Securelist APT10 March 2021", "url": "https://securelist.com/apt10-sophisticated-multi-layered-loader-ecipekac-discovered-in-a41apt-campaign/101519/"}], "id": "malware--7c58fff0-d206-4db1-96b1-e3a9e0e320b9", "is_family": true, "modified": "2025-04-25T14:43:50.562Z", "name": "P8RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["P8RAT", "HEAVYPOT", "GreetCake"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-883', 0, 104, '09-mitre-attack', 'retrieved', '3A8298A9754A89721387D064D26083F1FEE4F1B0C4CF5D9A92C6E022493F3B74', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
