VALUES ('doc-09-mitre-attack-p0-884', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T21:28:28.895Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Fooder](https://attack.mitre.org/software/S9033) is a custom 64-bit C/C++ loader used by [MuddyWater](https://attack.mitre.org/groups/G0069) that can decrypt and reflectively load embedded payloads such as a go-socks5 proxy utility, the open-source HackBrowserData infostealer, or the [MuddyViper](https://attack.mitre.org/software/S9032) backdoor. [Fooder](https://attack.mitre.org/software/S9033) has frequently masqueraded as an entertainment executable, such as the Snake game (e.g., `Snake_Game.exe`).(Citation: ESET_MuddyWater_Dec2025)", "external_references": [{"external_id": "S9033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9033"}, {"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}], "id": "malware--7c8865dc-1bf9-49ce-b5f2-f15abde0909a", "is_family": true, "modified": "2026-04-23T03:31:09.302Z", "name": "Fooder", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Fooder"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-884', 0, 109, '09-mitre-attack', 'retrieved', 'BAC998B191AE746622A9499C7D2467A3FEC6EF310C40CAD70D98D57B590C331C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
