VALUES ('doc-09-mitre-attack-p0-885', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T17:23:59.580Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VIRTUALPIE](https://attack.mitre.org/software/S1218) is a lightweight backdoor written in Python that spawns an IPv6 listener on a VMware ESXi server and features command line execution, file transfer, and reverse shell capabilities. [VIRTUALPIE](https://attack.mitre.org/software/S1218) has been in use since at least 2022 including by [UNC3886](https://attack.mitre.org/groups/G1048) who installed it via malicious vSphere Installation Bundles (VIBs).(Citation: Google Cloud Threat Intelligence ESXi VIBs 2022)", "external_references": [{"external_id": "S1218", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1218"}, {"description": "Alexander Marvi, Jeremy Koppen, Tufail Ahmed, and Jonathan Lepore. (2022, September 29). Bad VIB(E)s Part One: Investigating Novel Malware Persistence Within ESXi Hypervisors. Retrieved March 26, 2025.", "source_name": "Google Cloud Threat Intelligence ESXi VIBs 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/esxi-hypervisors-malware-persistence"}], "id": "malware--7cc63f0f-f24f-4cda-9e9f-61bde1d52297", "is_family": true, "modified": "2025-06-04T17:25:35.637Z", "name": "VIRTUALPIE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["VIRTUALPIE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-885', 0, 137, '09-mitre-attack', 'retrieved', 'FF0CCFA934C430A1AAB953CAAE1D7F184C38EA9F0C46C4BA8AB684EC69EFA7E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
