VALUES ('doc-09-mitre-attack-p0-886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-28T17:24:48.322Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[EVILNUM](https://attack.mitre.org/software/S0568) is fully capable backdoor that was first identified in 2018. [EVILNUM](https://attack.mitre.org/software/S0568) is used by the APT group [Evilnum](https://attack.mitre.org/groups/G0120) which has the same name.(Citation: ESET EvilNum July 2020)(Citation: Prevailion EvilNum May 2020)", "external_references": [{"external_id": "S0568", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0568"}, {"description": "(Citation: Prevailion EvilNum May 2020)(Citation: ESET EvilNum July 2020)", "source_name": "EVILNUM"}, {"description": "Adamitis, D. (2020, May 6). Phantom in the Command Shell. Retrieved November 17, 2024.", "source_name": "Prevailion EvilNum May 2020", "url": "https://web.archive.org/web/20221209052853/https://www.prevailion.com/phantom-in-the-command-shell-2/"}, {"description": "Porolli, M. (2020, July 9). More evil: A deep look at Evilnum and its toolset. Retrieved January 22, 2021.", "source_name": "ESET EvilNum July 2020", "url": "https://www.welivesecurity.com/2020/07/09/more-evil-deep-look-evilnum-toolset/"}], "id": "malware--7cdfccda-2950-4167-981a-60872ff5d0db", "is_family": true, "modified": "2024-11-17T23:13:51.280Z", "name": "EVILNUM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["EVILNUM"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-886', 0, 135, '09-mitre-attack', 'retrieved', '9048C49BAF4CCDE2372062001BF9EA82CD966C96FAB95D533C6E21F4298C08A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
