VALUES ('doc-09-mitre-attack-p0-887', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KOMPROGO](https://attack.mitre.org/software/S0156) is a signature backdoor used by [APT32](https://attack.mitre.org/groups/G0050) that is capable of process, file, and registry management. (Citation: FireEye APT32 May 2017)", "external_references": [{"external_id": "S0156", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0156"}, {"description": "(Citation: FireEye APT32 May 2017)", "source_name": "KOMPROGO"}, {"description": "Carr, N.. (2017, May 14). Cyber Espionage is Alive and Well: APT32 and the Threat to Global Corporations. Retrieved June 18, 2017.", "source_name": "FireEye APT32 May 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/05/cyber-espionage-apt32.html"}], "id": "malware--7dbb67c7-270a-40ad-836e-c45f8948aa5a", "is_family": true, "modified": "2025-04-25T14:43:51.104Z", "name": "KOMPROGO", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KOMPROGO"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-887', 0, 100, '09-mitre-attack', 'retrieved', '3C01CA784099E6EEB56804D6F2678789C79CF7540A2D5AC2143AFEAC323E29B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
