VALUES ('doc-09-mitre-attack-p0-888', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-22T20:11:08.678Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SMOKEDHAM](https://attack.mitre.org/software/S0649) is a Powershell-based .NET backdoor that was first reported in May 2021; it has been used by at least one ransomware-as-a-service affiliate.(Citation: FireEye Shining A Light on DARKSIDE May 2021)(Citation: FireEye SMOKEDHAM June 2021)", "external_references": [{"external_id": "S0649", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0649"}, {"description": "(Citation: FireEye Shining A Light on DARKSIDE May 2021)(Citation: FireEye SMOKEDHAM June 2021)", "source_name": "SMOKEDHAM"}, {"description": "FireEye. (2021, June 16). Smoking Out a DARKSIDE Affiliate’s Supply Chain Software Compromise. Retrieved September 22, 2021.", "source_name": "FireEye SMOKEDHAM June 2021", "url": "https://www.fireeye.com/blog/threat-research/2021/06/darkside-affiliate-supply-chain-software-compromise.html"}, {"description": "FireEye. (2021, May 11). Shining a Light on DARKSIDE Ransomware Operations. Retrieved September 22, 2021.", "source_name": "FireEye Shining A Light on DARKSIDE May 2021", "url": "https://www.fireeye.com/blog/threat-research/2021/05/shining-a-light-on-darkside-ransomware-operations.html"}], "id": "malware--7e0f8b0f-716e-494d-827e-310bd6ed709e", "is_family": true, "modified": "2025-04-16T20:38:19.381Z", "name": "SMOKEDHAM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SMOKEDHAM"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-888', 0, 145, '09-mitre-attack', 'retrieved', 'A529BA1F5BD0BDA9DE2365F4EB3C4E14EF6114B819B9A69366A111F0AE4DAD58', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
