VALUES ('doc-09-mitre-attack-p0-891', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-15T15:28:10.549Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sagerunex](https://attack.mitre.org/software/S1210) is a malware family exclusively associated with [Lotus Blossom](https://attack.mitre.org/groups/G0030) operations, with variants existing since at least 2016. Variations of [Sagerunex](https://attack.mitre.org/software/S1210) leverage non-traditional command and control mechanisms such as various web services.(Citation: Symantec Bilbug 2022)(Citation: Cisco LotusBlossom 2025)", "external_references": [{"external_id": "S1210", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1210"}, {"description": "Joey Chen, Cisco Talos. (2025, February 27). Lotus Blossom espionage group targets multiple industries with different versions of Sagerunex and hacking tools. Retrieved March 15, 2025.", "source_name": "Cisco LotusBlossom 2025", "url": "https://blog.talosintelligence.com/lotus-blossom-espionage-group/"}, {"description": "Symntec Threat Hunter Team. (2022, November 12). Billbug: State-sponsored Actor Targets Cert Authority, Government Agencies in Multiple Asian Countries. Retrieved March 15, 2025.", "source_name": "Symantec Bilbug 2022", "url": "https://www.security.com/threat-intelligence/espionage-asia-governments-cert-authority"}], "id": "malware--7f269253-c225-45ff-87c2-5e8ef6dd369f", "is_family": true, "modified": "2025-03-16T09:54:28.094Z", "name": "Sagerunex", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Sagerunex"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-891', 0, 143, '09-mitre-attack', 'retrieved', 'D2F5451ACDA592E7D4CC57B793935701E978D71369F71FC040C9A7C3730D3BE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
