VALUES ('doc-09-mitre-attack-p0-892', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-05T15:56:44.479Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TAINTEDSCRIBE](https://attack.mitre.org/software/S0586) is a fully-featured beaconing implant integrated with command modules used by [Lazarus Group](https://attack.mitre.org/groups/G0032). It was first reported in May 2020.(Citation: CISA MAR-10288834-2.v1 TAINTEDSCRIBE MAY 2020)", "external_references": [{"external_id": "S0586", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0586"}, {"description": "USG. (2020, May 12). MAR-10288834-2.v1 – North Korean Trojan: TAINTEDSCRIBE. Retrieved March 5, 2021.", "source_name": "CISA MAR-10288834-2.v1 TAINTEDSCRIBE MAY 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-133b"}], "id": "malware--7f4bbe05-1674-4087-8a16-8f1ad61b6152", "is_family": true, "modified": "2025-04-25T14:43:52.174Z", "name": "TAINTEDSCRIBE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TAINTEDSCRIBE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-892', 0, 96, '09-mitre-attack', 'retrieved', '9DCE16D43FBB9C912B11DCF1ABFC586C9110DD9470C94375802D9CEAC7FC5879', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
