VALUES ('doc-09-mitre-attack-p0-893', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:40.391Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sys10](https://attack.mitre.org/software/S0060) is a backdoor that was used throughout 2013 by [Naikon](https://attack.mitre.org/groups/G0019). (Citation: Baumgartner Naikon 2015)", "external_references": [{"external_id": "S0060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0060"}, {"description": "Baumgartner, K., Golovkin, M.. (2015, May). The MsnMM Campaigns: The Earliest Naikon APT Campaigns. Retrieved April 10, 2019.", "source_name": "Baumgartner Naikon 2015", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07205555/TheNaikonAPT-MsnMM1.pdf"}], "id": "malware--7f8730af-f683-423f-9ee1-5f6875a80481", "is_family": true, "modified": "2025-04-25T14:43:52.533Z", "name": "Sys10", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Sys10"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-893', 0, 80, '09-mitre-attack', 'retrieved', '99DD4BB3465E62B8569A3C206EAA84F03F7C4D830695966E1485806D65A67A0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
