VALUES ('doc-09-mitre-attack-p0-894', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T14:43:14.412Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LP-Notes](https://attack.mitre.org/software/S9036) is a C/C++ Windows credential stealer used by [MuddyWater](https://attack.mitre.org/groups/G0069). [LP-Notes](https://attack.mitre.org/software/S9036) was named after the `lp-notes.txt` file that is used to store stolen credentials.(Citation: ESET_MuddyWater_Dec2025) ", "external_references": [{"external_id": "S9036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9036"}, {"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}], "id": "malware--7fbf1f1e-cbd8-4060-8e3b-7ca0e56ce3fe", "is_family": true, "modified": "2026-04-23T03:29:27.045Z", "name": "LP-Notes", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LP-Notes"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-894', 0, 87, '09-mitre-attack', 'retrieved', 'F4EDDD6A72BF07B0334823295BAC8EC9527854A994A432DEB00E4CBB7E6290F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
