VALUES ('doc-09-mitre-attack-p0-896', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-30T20:25:37.761Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Royal](https://attack.mitre.org/software/S1073) is ransomware that first appeared in early 2022; a version that also targets ESXi servers was later observed in February 2023. [Royal](https://attack.mitre.org/software/S1073) employs partial encryption and multiple threads to evade detection and speed encryption. [Royal](https://attack.mitre.org/software/S1073) has been used in attacks against multiple industries worldwide--including critical infrastructure. Security researchers have identified similarities in the encryption routines and TTPs used in [Royal](https://attack.mitre.org/software/S1073) and [Conti](https://attack.mitre.org/software/S0575) attacks and noted a possible connection between their operators.(Citation: Microsoft Royal ransomware November 2022)(Citation: Cybereason Royal December 2022)(Citation: Kroll Royal Deep Dive February 2023)(Citation: Trend Micro Royal Linux ESXi February 2023)(Citation: CISA Royal AA23-061A March 2023)", "external_references": [{"external_id": "S1073", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1073"}, {"description": "CISA. (2023, March 2). #StopRansomware: Royal Ransomware. Retrieved March 31, 2023.", "source_name": "CISA Royal AA23-061A March 2023", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-061a"}, {"description": "Cybereason Global SOC and Cybereason Security Research Teams. (2022, December 14). Royal Rumble: Analysis of Royal Ransomware. Retrieved March 30, 2023.", "source_name": "Cybereason Royal December 2022", "url": "https://www.cybereason.com/blog/royal-ransomware-analysis"}, {"description": "Iacono, L. and Green, S. (2023, February 13). Royal Ransomware Deep Dive. Retrieved March 30, 2023.", "source_name": "Kroll Royal Deep Dive February 2023", "url": "https://www.kroll.com/en/insights/publications/cyber/royal-ransomware-deep-dive"}, {"description": "Morales, N. et al. (2023, February 20). Royal Ransomware Expands Attacks by Targeting Linux ESXi Servers. Retrieved March 30, 2023.", "source_name": "Trend Micro Royal Linux ESXi February 2023", "url": "https://www.trendmicro.com/en_us/research/23/b/royal-ransomware-expands-attacks-by-targeting-linux-esxi-servers.html"}, {"description": "MSTIC. (2022, November 17). DEV-0569 finds new ways to deliver Royal ransomware, various payloads. Retrieved March 30, 2023.", "source_name": "Microsoft Royal ransomware November 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/11/17/dev-0569-finds-new-ways-to-deliver-royal-ransomware-various-payloads/"}], "id": "malware--802a874d-7463-4f2a-99e3-6a1f5a919a21", "is_family": true, "modified": "2025-10-21T03:24:27.158Z", "name": "Royal", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Royal"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Wataru Takahashi, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "ESXi"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-896', 0, 290, '09-mitre-attack', 'retrieved', 'E51F03BF31F163D815330DA804E9E0C1BBBA9FC1B1DB7A02BD378771781AE6D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
