VALUES ('doc-09-mitre-attack-p0-897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-16T16:50:29.990Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BendyBear](https://attack.mitre.org/software/S0574) is an x64 shellcode for a stage-zero implant designed to download malware from a C2 server. First discovered in August 2020, [BendyBear](https://attack.mitre.org/software/S0574) shares a variety of features with [Waterbear](https://attack.mitre.org/software/S0579), malware previously attributed to the Chinese cyber espionage group [BlackTech](https://attack.mitre.org/groups/G0098).(Citation: Unit42 BendyBear Feb 2021)", "external_references": [{"external_id": "S0574", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0574"}, {"description": "(Citation: Unit42 BendyBear Feb 2021)", "source_name": "BendyBear"}, {"description": "Harbison, M. (2021, February 9). BendyBear: Novel Chinese Shellcode Linked With Cyber Espionage Group BlackTech. Retrieved February 16, 2021.", "source_name": "Unit42 BendyBear Feb 2021", "url": "https://unit42.paloaltonetworks.com/bendybear-shellcode-blacktech/"}], "id": "malware--805480f1-6caa-4a67-8ca9-b2b39650d986", "is_family": true, "modified": "2024-04-11T02:54:10.246Z", "name": "BendyBear", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BendyBear"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-897', 0, 121, '09-mitre-attack', 'retrieved', '319329422FE2D6F5D1DC979A9BB742397406440DAE76239E6E5FF384BC5AB424', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
