VALUES ('doc-09-mitre-attack-p0-900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-26T17:34:19.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Metamorfo](https://attack.mitre.org/software/S0455) is a Latin-American banking trojan operated by a Brazilian cybercrime group that has been active since at least April 2018. The group focuses on targeting banks and cryptocurrency services in Brazil and Mexico.(Citation: Medium Metamorfo Apr 2020)(Citation: ESET Casbaneiro Oct 2019) ", "external_references": [{"external_id": "S0455", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0455"}, {"description": "(Citation: ESET Casbaneiro Oct 2019)", "source_name": "Casbaneiro"}, {"description": "(Citation: Medium Metamorfo Apr 2020)(Citation: ESET Casbaneiro Oct 2019) ", "source_name": "Metamorfo"}, {"description": "Erlich, C. (2020, April 3). The Avast Abuser: Metamorfo Banking Malware Hides By Abusing Avast Executable. Retrieved May 26, 2020.", "source_name": "Medium Metamorfo Apr 2020", "url": "https://medium.com/@chenerlich/the-avast-abuser-metamorfo-banking-malware-hides-by-abusing-avast-executable-ac9b8b392767"}, {"description": "ESET Research. (2019, October 3). Casbaneiro: peculiarities of this banking Trojan that affects Brazil and Mexico. Retrieved September 23, 2021.", "source_name": "ESET Casbaneiro Oct 2019", "url": "https://www.welivesecurity.com/2019/10/03/casbaneiro-trojan-dangerous-cooking/"}], "id": "malware--81c57a96-fc8c-4f91-af8e-63e24c2927c2", "is_family": true, "modified": "2024-04-11T00:44:30.028Z", "name": "Metamorfo", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Metamorfo", "Casbaneiro"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jose Luis Sánchez Martinez", "Chen Erlich, @chen_erlich, enSilo"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-900', 0, 172, '09-mitre-attack', 'retrieved', '035FAD9DD1D69BA46391B95654887E624A81B98FF9045C4B40076497E60D5580', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
