VALUES ('doc-09-mitre-attack-p0-901', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-18T20:03:12.865Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Spica](https://attack.mitre.org/software/S1140) is a custom backdoor written in Rust that has been used by [Star Blizzard](https://attack.mitre.org/groups/G1033) since at least 2023.(Citation: Google TAG COLDRIVER January 2024) ", "external_references": [{"external_id": "S1140", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1140"}, {"description": "Shields, W. (2024, January 18). Russian threat group COLDRIVER expands its targeting of Western officials to include the use of malware. Retrieved June 13, 2024.", "source_name": "Google TAG COLDRIVER January 2024", "url": "https://blog.google/threat-analysis-group/google-tag-coldriver-russian-phishing-malware/"}], "id": "malware--824a230d-0f6a-4fd0-99df-8d464db2265e", "is_family": true, "modified": "2024-06-18T20:03:31.986Z", "name": "Spica", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Spica"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-901', 0, 101, '09-mitre-attack', 'retrieved', 'FB0D95ED0B480920C88E4B3D314A82587D131DADC2126C78BE686EBDBC4CC660', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
