VALUES ('doc-09-mitre-attack-p0-903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:00.176Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Trojan.Karagany](https://attack.mitre.org/software/S0094) is a modular remote access tool used for recon and linked to [Dragonfly](https://attack.mitre.org/groups/G0035). The source code for [Trojan.Karagany](https://attack.mitre.org/software/S0094) originated from Dream Loader malware which was leaked in 2010 and sold on underground forums. (Citation: Symantec Dragonfly)(Citation: Secureworks Karagany July 2019)(Citation: Dragos DYMALLOY )", "external_references": [{"external_id": "S0094", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0094"}, {"description": "(Citation: Secureworks Karagany July 2019)", "source_name": "xFrost"}, {"description": "(Citation: Secureworks Karagany July 2019)", "source_name": "Karagany"}, {"description": "Dragos. (n.d.). DYMALLOY. Retrieved August 20, 2020.", "source_name": "Dragos DYMALLOY ", "url": "https://www.dragos.com/threat/dymalloy/"}, {"description": "Secureworks. (2019, July 24). Updated Karagany Malware Targets Energy Sector. Retrieved August 12, 2020.", "source_name": "Secureworks Karagany July 2019", "url": "https://www.secureworks.com/research/updated-karagany-malware-targets-energy-sector"}, {"description": "Symantec Security Response. (2014, June 30). Dragonfly: Cyberespionage Attacks Against Energy Suppliers. Retrieved April 8, 2016.", "source_name": "Symantec Dragonfly", "url": "https://community.broadcom.com/symantecenterprise/communities/community-home/librarydocuments/viewdocument?DocumentKey=7382dce7-0260-4782-84cc-890971ed3f17&CommunityKey=1ecf5f55-9545-44d6-b0f4-4e4a7f5f5e68&tab=librarydocuments"}], "id": "malware--82cb34ba-02b5-432b-b2d2-07f55cbf674d", "is_family": true, "modified": "2025-04-16T20:38:20.519Z", "name": "Trojan.Karagany", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Trojan.Karagany", "xFrost", "Karagany"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "3.0"}', 'kb-doc-09-mitre-attack-p0-903', 0, 162, '09-mitre-attack', 'retrieved', '7882F55D80D0B8A51307C8A811EF70FF6342863C76DAE1350F25E0920707C50D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
