VALUES ('doc-09-mitre-attack-p0-904', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bandook](https://attack.mitre.org/software/S0234) is a commercially available RAT, written in Delphi and C++, that has been available since at least 2007. It has been used against government, financial, energy, healthcare, education, IT, and legal organizations in the US, South America, Europe, and Southeast Asia. [Bandook](https://attack.mitre.org/software/S0234) has been used by [Dark Caracal](https://attack.mitre.org/groups/G0070), as well as in a separate campaign referred to as \"Operation Manul\".(Citation: EFF Manul Aug 2016)(Citation: Lookout Dark Caracal Jan 2018)(Citation: CheckPoint Bandook Nov 2020)", "external_references": [{"external_id": "S0234", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0234"}, {"description": "Blaich, A., et al. (2018, January 18). Dark Caracal: Cyber-espionage at a Global Scale. Retrieved April 11, 2018.", "source_name": "Lookout Dark Caracal Jan 2018", "url": "https://info.lookout.com/rs/051-ESQ-475/images/Lookout_Dark-Caracal_srr_20180118_us_v.1.0.pdf"}, {"description": "Check Point. (2020, November 26). Bandook: Signed & Delivered. Retrieved May 31, 2021.", "source_name": "CheckPoint Bandook Nov 2020", "url": "https://research.checkpoint.com/2020/bandook-signed-delivered/"}, {"description": "Galperin, E., Et al.. (2016, August). I Got a Letter From the Government the Other Day.... Retrieved April 25, 2018.", "source_name": "EFF Manul Aug 2016", "url": "https://www.eff.org/files/2016/08/03/i-got-a-letter-from-the-government.pdf"}], "id": "malware--835a79f1-842d-472d-b8f4-d54b545c341b", "is_family": true, "modified": "2025-04-25T14:43:54.316Z", "name": "Bandook", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Bandook"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-904', 0, 192, '09-mitre-attack', 'retrieved', '22F30D1ACA786C37A847F1D16807DEB04658C36BF2FE545DF8FB28D9384B49A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
