VALUES ('doc-09-mitre-attack-p0-905', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-24T13:15:51.706Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PipeMon](https://attack.mitre.org/software/S0501) is a multi-stage modular backdoor used by [Winnti Group](https://attack.mitre.org/groups/G0044).(Citation: ESET PipeMon May 2020)", "external_references": [{"external_id": "S0501", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0501"}, {"description": "Tartare, M. et al. (2020, May 21). No “Game over” for the Winnti Group. Retrieved August 24, 2020.", "source_name": "ESET PipeMon May 2020", "url": "https://www.welivesecurity.com/2020/05/21/no-game-over-winnti-group/"}], "id": "malware--8393dac0-0583-456a-9372-fd81691bca20", "is_family": true, "modified": "2024-04-11T00:26:37.214Z", "name": "PipeMon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PipeMon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Mathieu Tartare, ESET", "Martin Smolár, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-905', 0, 89, '09-mitre-attack', 'retrieved', '0A9082C1448EB45077D0030DC84B28E57615814936CF2B14EFFC2E4EA8CE09D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
