VALUES ('doc-09-mitre-attack-p0-906', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:38:11.279Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SYNful Knock](https://attack.mitre.org/software/S0519) is a stealthy modification of the operating system of network devices that can be used to maintain persistence within a victim''s network and provide new capabilities to the adversary.(Citation: Mandiant - Synful Knock)(Citation: Cisco Synful Knock Evolution)", "external_references": [{"external_id": "S0519", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0519"}, {"description": "Bill Hau, Tony Lee, Josh Homan. (2015, September 15). SYNful Knock - A Cisco router implant - Part I. Retrieved November 17, 2024.", "source_name": "Mandiant - Synful Knock", "url": "https://cloud.google.com/blog/topics/threat-intelligence/synful-knock-acis/"}, {"description": "Graham Holmes. (2015, October 8). Evolution of attacks on Cisco IOS devices. Retrieved October 19, 2020.", "source_name": "Cisco Synful Knock Evolution", "url": "https://blogs.cisco.com/security/evolution-of-attacks-on-cisco-ios-devices"}], "id": "malware--84c1ecc6-e5a2-4e8a-bf4b-651a618e0053", "is_family": true, "modified": "2025-04-15T19:46:34.695Z", "name": "SYNful Knock", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SYNful Knock"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-906', 0, 139, '09-mitre-attack', 'retrieved', '3A2E2C23096EFB821E7E96DAC8886A102A78BE3800339E21BED1DAE5651997DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", 