VALUES ('doc-09-mitre-attack-p0-907', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-30T19:36:12.999Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MagicRAT](https://attack.mitre.org/software/S1182) is a remote access tool developed in C++ and exclusively used by the [Lazarus Group](https://attack.mitre.org/groups/G0032) threat actor in operations. [MagicRAT](https://attack.mitre.org/software/S1182) allows for arbitrary command execution on victim machines and provides basic remote access functionality.(Citation: Cisco MagicRAT 2022)", "external_references": [{"external_id": "S1182", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1182"}, {"description": "Asheer Malhotra, Vitor Ventura & Jungsoo An, Cisco Talos. (2022, September 7). MagicRAT: Lazarus’ latest gateway into victim networks. Retrieved December 30, 2024.", "source_name": "Cisco MagicRAT 2022", "url": "https://blog.talosintelligence.com/lazarus-magicrat/"}], "id": "malware--858b0f9d-3a2a-437e-a058-afe72154f6da", "is_family": true, "modified": "2025-04-10T21:36:18.962Z", "name": "MagicRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MagicRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Adam Lichters"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-907', 0, 113, '09-mitre-attack', 'retrieved', '6477C10947E989478527D2BC3C31B7C015F4F5A8ED4EEDBB65B3EA14E13E7E26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
