VALUES ('doc-09-mitre-attack-p0-908', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:15.467Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TINYTYPHON](https://attack.mitre.org/software/S0131) is a backdoor that has been used by the actors responsible for the MONSOON campaign. The majority of its code was reportedly taken from the MyDoom worm. (Citation: Forcepoint Monsoon)", "external_references": [{"external_id": "S0131", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0131"}, {"description": "Settle, A., et al. (2016, August 8). MONSOON - Analysis Of An APT Campaign. Retrieved September 22, 2016.", "source_name": "Forcepoint Monsoon", "url": "https://www.forcepoint.com/sites/default/files/resources/files/forcepoint-security-labs-monsoon-analysis-report.pdf"}], "id": "malware--85b39628-204a-48d2-b377-ec368cbcb7ca", "is_family": true, "modified": "2024-04-10T22:32:05.321Z", "name": "TINYTYPHON", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TINYTYPHON"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-908', 0, 95, '09-mitre-attack', 'retrieved', '6CC6FB08AEFE65CB2429EDAD4AAAEAB1563DB659B189931ED30DA12C0BDC6C89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
