INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-909', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T00:36:39.771Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KONNI](https://attack.mitre.org/software/S0356) is a remote access tool that security researchers assess has been used by North Korean cyber actors since at least 2014. [KONNI](https://attack.mitre.org/software/S0356) has significant code overlap with the [NOKKI](https://attack.mitre.org/software/S0353) malware family, and has been linked to several suspected North Korean campaigns targeting political organizations in Russia, East Asia, Europe and the Middle East; there is some evidence potentially linking [KONNI](https://attack.mitre.org/software/S0356) to [APT37](https://attack.mitre.org/groups/G0067).(Citation: Talos Konni May 2017)(Citation: Unit 42 NOKKI Sept 2018)(Citation: Unit 42 Nokki Oct 2018)(Citation: Medium KONNI Jan 2020)(Citation: Malwarebytes Konni Aug 2021)", "external_references": [{"external_id": "S0356", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0356"}, {"description": "(Citation: Talos Konni May 2017)(Citation: Malwarebytes Konni Aug 2021)", "source_name": "KONNI"}, {"description": "Grunzweig, J. (2018, October 01). NOKKI Almost Ties the Knot with DOGCALL: Reaper Group Uses New Malware to Deploy RAT. Retrieved November 5, 2018.", "source_name": "Unit 42 Nokki Oct 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/10/unit42-nokki-almost-ties-the-knot-with-dogcall-reaper-group-uses-new-malware-to-deploy-rat/"}, {"description": "Grunzweig, J., Lee, B. (2018, September 27). New KONNI Malware attacking Eurasia and Southeast Asia. Retrieved November 5, 2018.", "source_name": "Unit 42 NOKKI Sept 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/09/unit42-new-konni-malware-attacking-eurasia-southeast-asia/"}, {"description": "Karmi, D. (2020, January 4). A Look Into Konni 2019 Campaign. Retrieved April 28, 2020.", "source_name": "Medium KONNI Jan 2020", "url": "https://medium.com/d-hunter/a-look-into-konni-2019-campaign-b45a0f321e9b"}, {"description": "Rascagneres, P. (2017, May 03). KONNI: A Malware Under The Radar For Years. Retrieved November 5, 2018.", "source_name": "Talos Konni May 2017", "url": "https://blog.talosintelligence.com/2017/05/konni-malware-under-radar-for-years.html"}, {"description": "Threat Intelligence Team. (2021, August 23). New variant of Konni malware used in campaign targetting Russia. Retrieved January 5, 2022.", "source_name": "Malwarebytes Konni Aug 2021", "url": "https://blog.malwarebytes.com/threat-intelligence/2021/08/new-variant-of-konni-malware-used-in-campaign-targetting-russia/"}], "id": "malware--86b92f6c-9c05-4c51-b361-4c7bb13e21a1", "is_family": true, "modified": "2025-10-21T03:20:18.481Z", "name": "KONNI", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KONNI"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Doron Karmi, @DoronKarmi"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-909', 0, 280, '09-mitre-attack', 'retrieved', 'E8D2EC7FE1D3B1064EC956C2C08FDA11399A1B52C385E0CCB1A7DBF0C5E1455F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
