VALUES ('doc-09-mitre-attack-p0-912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-13T17:50:25.350Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RAPIDPULSE](https://attack.mitre.org/software/S1113) is a web shell that exists as a modification to a legitimate Pulse Secure file that has been used by [APT5](https://attack.mitre.org/groups/G1023) since at least 2021.(Citation: Mandiant Pulse Secure Update May 2021)", "external_references": [{"external_id": "S1113", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1113"}, {"description": "Perez, D. et al. (2021, May 27). Re-Checking Your Pulse: Updates on Chinese APT Actors Compromising Pulse Secure VPN Devices. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Update May 2021", "url": "https://www.mandiant.com/resources/blog/updates-on-chinese-apt-compromising-pulse-secure-vpn-devices"}], "id": "malware--880f7b3e-ad27-4158-8b03-d44c9357950b", "is_family": true, "modified": "2025-04-15T19:46:34.778Z", "name": "RAPIDPULSE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RAPIDPULSE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-912', 0, 110, '09-mitre-attack', 'retrieved', '1F5DC6DF5DE520CC2BEDDFCDDF2B0692B721165927D1ADA177D947BCCB24C43C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
