VALUES ('doc-09-mitre-attack-p0-915', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:13.407Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Skeleton Key](https://attack.mitre.org/software/S0007) is malware used to inject false credentials into domain controllers with the intent of creating a backdoor password. (Citation: Dell Skeleton) Functionality similar to [Skeleton Key](https://attack.mitre.org/software/S0007) is included as a module in [Mimikatz](https://attack.mitre.org/software/S0002).", "external_references": [{"external_id": "S0007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0007"}, {"description": "Dell SecureWorks. (2015, January 12). Skeleton Key Malware Analysis. Retrieved April 8, 2019.", "source_name": "Dell Skeleton", "url": "https://www.secureworks.com/research/skeleton-key-malware-analysis"}], "id": "malware--89f63ae4-f229-4a5c-95ad-6f22ed2b5c49", "is_family": true, "modified": "2024-02-06T19:02:00.781Z", "name": "Skeleton Key", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Skeleton Key"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-915', 0, 98, '09-mitre-attack', 'retrieved', 'BC9DA00686F11B443486981C12EF2C27EB505BE8D9C76F075D745635A5CADBD3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
