VALUES ('doc-09-mitre-attack-p0-916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-24T14:02:05.144Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DnsSystem](https://attack.mitre.org/software/S1021) is a .NET based DNS backdoor, which is a customized version of the open source tool DIG.net, that has been used by [HEXANE](https://attack.mitre.org/groups/G1001) since at least June 2022.(Citation: Zscaler Lyceum DnsSystem June 2022)", "external_references": [{"external_id": "S1021", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1021"}, {"description": "Shivtarkar, N. and Kumar, A. (2022, June 9). Lyceum .NET DNS Backdoor. Retrieved June 23, 2022.", "source_name": "Zscaler Lyceum DnsSystem June 2022", "url": "https://www.zscaler.com/blogs/security-research/lyceum-net-dns-backdoor"}], "id": "malware--8a2867f9-e8fc-4bf1-a860-ef6e46311900", "is_family": true, "modified": "2025-04-16T20:38:21.017Z", "name": "DnsSystem", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DnsSystem"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-916', 0, 101, '09-mitre-attack', 'retrieved', 'BBC9C222FD845455FA5142BBE76281356F09496A2AE967A441375325E3321AF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
