VALUES ('doc-09-mitre-attack-p0-917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-28T22:09:15.461Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MoleNet](https://attack.mitre.org/software/S0553) is a downloader tool with backdoor capabilities that has been observed in use since at least 2019.(Citation: Cybereason Molerats Dec 2020)", "external_references": [{"external_id": "S0553", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0553"}, {"description": "(Citation: Cybereason Molerats Dec 2020)", "source_name": "MoleNet"}, {"description": "Cybereason Nocturnus Team. (2020, December 9). MOLERATS IN THE CLOUD: New Malware Arsenal Abuses Cloud Platforms in Middle East Espionage Campaign. Retrieved December 22, 2020.", "source_name": "Cybereason Molerats Dec 2020", "url": "https://www.cybereason.com/hubfs/dam/collateral/reports/Molerats-in-the-Cloud-New-Malware-Arsenal-Abuses-Cloud-Platforms-in-Middle-East-Espionage-Campaign.pdf"}], "id": "malware--8a59f456-79a0-4151-9f56-9b1a67332af2", "is_family": true, "modified": "2025-04-25T14:43:57.040Z", "name": "MoleNet", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MoleNet"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-917', 0, 103, '09-mitre-attack', 'retrieved', '9CA0F8D3D2E72253064EB8FC48ACBB577678BFDA14E881963621BF5CC4204A9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
