VALUES ('doc-09-mitre-attack-p0-921', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-01T20:26:49.502Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BLUELIGHT](https://attack.mitre.org/software/S0657) is a remote access Trojan used by [APT37](https://attack.mitre.org/groups/G0067) that was first observed in early 2021.(Citation: Volexity InkySquid BLUELIGHT August 2021)", "external_references": [{"external_id": "S0657", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0657"}, {"description": "(Citation: Volexity InkySquid BLUELIGHT August 2021)", "source_name": "BLUELIGHT"}, {"description": "Cash, D., Grunzweig, J., Meltzer, M., Adair, S., Lancaster, T. (2021, August 17). North Korean APT InkySquid Infects Victims Using Browser Exploits. Retrieved September 30, 2021.", "source_name": "Volexity InkySquid BLUELIGHT August 2021", "url": "https://www.volexity.com/blog/2021/08/17/north-korean-apt-inkysquid-infects-victims-using-browser-exploits/"}], "id": "malware--8bd47506-29ae-44ea-a5c1-c57e8a1ab6b0", "is_family": true, "modified": "2024-04-11T02:49:24.851Z", "name": "BLUELIGHT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BLUELIGHT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-921', 0, 107, '09-mitre-attack', 'retrieved', 'D067EF635DDDFF939D38028A811987B7CE372F334A1916C2768212C763336A40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
