VALUES ('doc-09-mitre-attack-p0-922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-06T18:58:35.456Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KGH_SPY](https://attack.mitre.org/software/S0526) is a modular suite of tools used by [Kimsuky](https://attack.mitre.org/groups/G0094) for reconnaissance, information stealing, and backdoor capabilities. [KGH_SPY](https://attack.mitre.org/software/S0526) derived its name from PDB paths and internal names found in samples containing \"KGH\".(Citation: Cybereason Kimsuky November 2020)", "external_references": [{"external_id": "S0526", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0526"}, {"description": "Dahan, A. et al. (2020, November 2). Back to the Future: Inside the Kimsuky KGH Spyware Suite. Retrieved November 6, 2020.", "source_name": "Cybereason Kimsuky November 2020", "url": "https://www.cybereason.com/blog/back-to-the-future-inside-the-kimsuky-kgh-spyware-suite"}], "id": "malware--8bdfe255-e658-4ddd-a11c-b854762e451d", "is_family": true, "modified": "2024-04-11T01:45:40.875Z", "name": "KGH_SPY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KGH_SPY"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-922', 0, 107, '09-mitre-attack', 'retrieved', 'DE7007820CE6BC58DC6AA6832338189FC4CDF1140935C8DAA833562DE93AF0D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
