VALUES ('doc-09-mitre-attack-p0-924', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:16.360Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ixeshe](https://attack.mitre.org/software/S0015) is a malware family that has been used since at least 2009 against targets in East Asia. (Citation: Moran 2013)", "external_references": [{"external_id": "S0015", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0015"}, {"description": "Moran, N., & Villeneuve, N. (2013, August 12). Survival of the Fittest: New York Times Attackers Evolve Quickly [Blog]. Retrieved November 17, 2024.", "source_name": "Moran 2013", "url": "https://web.archive.org/web/20191224162418/https://www.fireeye.com/blog/threat-research/2013/08/survival-of-the-fittest-new-york-times-attackers-evolve-quickly.html"}], "id": "malware--8beac7c2-48d2-4cd9-9b15-6c452f38ac06", "is_family": true, "modified": "2024-11-17T16:12:58.245Z", "name": "Ixeshe", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ixeshe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-924', 0, 92, '09-mitre-attack', 'retrieved', '8F304EB201DC08BF539A05A02DAE1E516C1E74748A81DC8287663EE5FE14ABBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
