VALUES ('doc-09-mitre-attack-p0-925', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:47:53.070Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Micropsia](https://attack.mitre.org/software/S0339) is a remote access tool written in Delphi.(Citation: Talos Micropsia June 2017)(Citation: Radware Micropsia July 2018)", "external_references": [{"external_id": "S0339", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0339"}, {"description": "(Citation: Talos Micropsia June 2017)(Citation: Radware Micropsia July 2018)", "source_name": "Micropsia"}, {"description": "Rascagneres, P., Mercer, W. (2017, June 19). Delphi Used To Score Against Palestine. Retrieved November 13, 2018.", "source_name": "Talos Micropsia June 2017", "url": "https://blog.talosintelligence.com/2017/06/palestine-delphi.html"}, {"description": "Tsarfaty, Y. (2018, July 25). Micropsia Malware. Retrieved November 13, 2018.", "source_name": "Radware Micropsia July 2018", "url": "https://www.radware.com/blog/security/2018/07/micropsia-malware/"}], "id": "malware--8c050cea-86e1-4b63-bf21-7af4fa483349", "is_family": true, "modified": "2024-10-04T11:08:25.923Z", "name": "Micropsia", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Micropsia"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-925', 0, 115, '09-mitre-attack', 'retrieved', '9174D5F262A8B9633B59695B6ECE19840B184335060C9AA700BA87A08267C372', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
