VALUES ('doc-09-mitre-attack-p0-926', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-02T13:38:32.673Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kerrdown](https://attack.mitre.org/software/S0585) is a custom downloader that has been used by [APT32](https://attack.mitre.org/groups/G0050) since at least 2018 to install spyware from a server on the victim''s network.(Citation: Amnesty Intl. Ocean Lotus February 2021)(Citation: Unit 42 KerrDown February 2019)", "external_references": [{"external_id": "S0585", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0585"}, {"description": "Amnesty International. (2021, February 24). Vietnamese activists targeted by notorious hacking group. Retrieved March 1, 2021.", "source_name": "Amnesty Intl. Ocean Lotus February 2021", "url": "https://www.amnestyusa.org/wp-content/uploads/2021/02/Click-and-Bait_Vietnamese-Human-Rights-Defenders-Targeted-with-Spyware-Attacks.pdf"}, {"description": "Ray, V. and Hayashi, K. (2019, February 1). Tracking OceanLotus’ new Downloader, KerrDown. Retrieved October 1, 2021.", "source_name": "Unit 42 KerrDown February 2019", "url": "https://unit42.paloaltonetworks.com/tracking-oceanlotus-new-downloader-kerrdown/"}], "id": "malware--8c1d01ff-fdc0-4586-99bd-c248e0761af5", "is_family": true, "modified": "2025-04-25T14:43:59.023Z", "name": "Kerrdown", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kerrdown"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-926', 0, 128, '09-mitre-attack', 'retrieved', 'A1F9F82770DC4756451782A1B9C1921CC32ACF56D4CAC436E68F3B41B6F40005', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
