VALUES ('doc-09-mitre-attack-p0-927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:38.480Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RARSTONE](https://attack.mitre.org/software/S0055) is malware used by the [Naikon](https://attack.mitre.org/groups/G0019) group that has some characteristics similar to [PlugX](https://attack.mitre.org/software/S0013). (Citation: Aquino RARSTONE)", "external_references": [{"external_id": "S0055", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0055"}, {"description": "Aquino, M. (2013, June 13). RARSTONE Found In Targeted Attacks. Retrieved December 17, 2015.", "source_name": "Aquino RARSTONE", "url": "http://blog.trendmicro.com/trendlabs-security-intelligence/rarstone-found-in-targeted-attacks/"}], "id": "malware--8c553311-0baa-4146-997a-f79acef3d831", "is_family": true, "modified": "2025-04-25T14:43:59.385Z", "name": "RARSTONE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RARSTONE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-927', 0, 78, '09-mitre-attack', 'retrieved', '85ABB382642BE99632C20EC727922393F31DF292956CFFF3236F49E60F8C1183', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
