VALUES ('doc-09-mitre-attack-p0-929', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-08T20:43:25.743Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VBShower](https://attack.mitre.org/software/S0442) is a backdoor that has been used by [Inception](https://attack.mitre.org/groups/G0100) since at least 2019. [VBShower](https://attack.mitre.org/software/S0442) has been used as a downloader for second stage payloads, including [PowerShower](https://attack.mitre.org/software/S0441).(Citation: Kaspersky Cloud Atlas August 2019)", "external_references": [{"external_id": "S0442", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0442"}, {"description": "GReAT. (2019, August 12). Recent Cloud Atlas activity. Retrieved May 8, 2020.", "source_name": "Kaspersky Cloud Atlas August 2019", "url": "https://securelist.com/recent-cloud-atlas-activity/92016/"}], "id": "malware--8caa18af-4758-4fd3-9600-e8af579e89ed", "is_family": true, "modified": "2025-04-25T14:43:59.751Z", "name": "VBShower", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["VBShower"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-929', 0, 93, '09-mitre-attack', 'retrieved', '1BBFAF6A9C9380168FEF793B1C4574DE0049407BE5891B709CB2A99E130FF42F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
