VALUES ('doc-09-mitre-attack-p0-930', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-20T23:08:38.199Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BPFDoor](https://attack.mitre.org/software/S1161) is a Linux based passive long-term backdoor used by China-based threat actors. First seen in 2021, [BPFDoor](https://attack.mitre.org/software/S1161) is named after its usage of Berkley Packet Filter (BPF) to execute single task instructions. [BPFDoor](https://attack.mitre.org/software/S1161) supports multiple protocols for communicating with a C2 including TCP, UDP, and ICMP and can start local or reverse shells that bypass firewalls using iptables.(Citation: Sandfly BPFDoor 2022)(Citation: Deep Instinct BPFDoor 2023)", "external_references": [{"external_id": "S1161", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1161"}, {"description": " Jamie Harries. (2022, May 25). Hunting a Global Telecommunications Threat: DecisiveArchitect and Its Custom Implant JustForFun. Retrieved September 23, 2024.", "source_name": "Harries JustForFun 2022", "url": "https://www.crowdstrike.com/blog/how-to-hunt-for-decisivearchitect-and-justforfun-implant/"}, {"description": "(Citation: Harries JustForFun 2022)", "source_name": "JustForFun"}, {"description": "(Citation: Harries JustForFun 2022)", "source_name": "Backdoor.Solaris.BPFDOOR.ZAJE"}, {"description": "(Citation: Merces BPFDOOR 2023)", "source_name": "Backdoor.Linux.BPFDOOR"}, {"description": "Fernando Merces. (2023, July 13). Detecting BPFDoor Backdoor Variants Abusing BPF Filters. Retrieved September 23, 2024.", "source_name": "Merces BPFDOOR 2023", "url": "https://www.trendmicro.com/en_us/research/23/g/detecting-bpfdoor-backdoor-variants-abusing-bpf-filters.html"}, {"description": "Shaul Vilkomir-Preisman and Eliran Nissan. (2023, May 10). BPFDoor Malware Evolves – Stealthy Sniffing Backdoor Ups Its Game. Retrieved September 19, 2024.", "source_name": "Deep Instinct BPFDoor 2023", "url": "https://www.deepinstinct.com/blog/bpfdoor-malware-evolves-stealthy-sniffing-backdoor-ups-its-game"}, {"description": "The Sandfly Security Team. (2022, May 11). BPFDoor - An Evasive Linux Backdoor Technical Analysis. Retrieved September 29, 2023.", "source_name": "Sandfly BPFDoor 2022", "url": "https://sandflysecurity.com/blog/bpfdoor-an-evasive-linux-backdoor-technical-analysis/"}], "id": "malware--8d1f89fd-4dde-40ab-80e0-a7b80249162e", "is_family": true, "modified": "2026-05-12T15:12:00.737Z", "name": "BPFDoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BPFDoor", "JustForFun", "Backdoor.Linux.BPFDOOR", "Backdoor.Solaris.BPFDOOR.ZAJE"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-930', 0, 239, '09-mitre-attack', 'retrieved', 'B9A3460D6176F2AE3435C79D9057CC35CC58B24DECE5BAF140A1E16D2B6A43D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
