VALUES ('doc-09-mitre-attack-p0-932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-08T19:52:06.393Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZeroCleare](https://attack.mitre.org/software/S1151) is a wiper malware that has been used in conjunction with the [RawDisk](https://attack.mitre.org/software/S0364) driver since at least 2019 by suspected Iran-nexus threat actors including activity targeting the energy and industrial sectors in the Middle East and political targets in Albania.(Citation: Microsoft Albanian Government Attacks September 2022)(Citation: CISA Iran Albanian Attacks September 2022)(Citation: Mandiant ROADSWEEP August 2022)(Citation: IBM ZeroCleare Wiper December 2019)", "external_references": [{"external_id": "S1151", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1151"}, {"description": "(Citation: Mandiant ROADSWEEP August 2022)", "source_name": "ZEROCLEAR"}, {"description": "CISA. (2022, September 23). AA22-264A Iranian State Actors Conduct Cyber Operations Against the Government of Albania. Retrieved August 6, 2024.", "source_name": "CISA Iran Albanian Attacks September 2022", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa22-264a"}, {"description": "Jenkins, L. at al. (2022, August 4). ROADSWEEP Ransomware - Likely Iranian Threat Actor Conducts Politically Motivated Disruptive Activity Against Albanian Government Organizations. Retrieved August 6, 2024.", "source_name": "Mandiant ROADSWEEP August 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/likely-iranian-threat-actor-conducts-politically-motivated-disruptive-activity-against/"}, {"description": "Kessem, L. (2019, December 4). New Destructive Wiper ZeroCleare Targets Energy Sector in the Middle East. Retrieved September 4, 2024.", "source_name": "IBM ZeroCleare Wiper December 2019", "url": "https://securityintelligence.com/posts/new-destructive-wiper-zerocleare-targets-energy-sector-in-the-middle-east/"}, {"description": "MSTIC. (2022, September 8). Microsoft investigates Iranian attacks against the Albanian government. Retrieved August 6, 2024.", "source_name": "Microsoft Albanian Government Attacks September 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/09/08/microsoft-investigates-iranian-attacks-against-the-albanian-government/"}], "id": "malware--8d8518db-0f52-4f3c-8017-01389a8522bb", "is_family": true, "modified": "2024-09-04T19:16:36.655Z", "name": "ZeroCleare", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ZeroCleare", "ZEROCLEAR"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-932', 0, 233, '09-mitre-attack', 'retrieved', 'AAE1C987A9737DF2D593108DB9D16AE9693B2BCFBA8FDC86629008894E1B17CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
