VALUES ('doc-09-mitre-attack-p0-933', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Catchamas](https://attack.mitre.org/software/S0261) is a Windows Trojan that steals information from compromised systems. (Citation: Symantec Catchamas April 2018)", "external_references": [{"external_id": "S0261", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0261"}, {"description": "(Citation: Symantec Catchamas April 2018)", "source_name": "Catchamas"}, {"description": "Balanza, M. (2018, April 02). Infostealer.Catchamas. Retrieved November 17, 2024.", "source_name": "Symantec Catchamas April 2018", "url": "https://web.archive.org/web/20190508165711/https://www-west.symantec.com/content/symantec/english/en/security-center/writeup.html/2018-040209-1742-99"}], "id": "malware--8d9e758b-735f-4cbc-ba7c-32cd15138b2a", "is_family": true, "modified": "2024-11-17T18:36:16.203Z", "name": "Catchamas", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Catchamas"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-933', 0, 84, '09-mitre-attack', 'retrieved', 'FF593B5EB1A28148930491CDCC77A3E49C31908290704BAEC3EA7265D58F4432', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
