VALUES ('doc-09-mitre-attack-p0-934', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-14T15:05:06.630Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StoneDrill](https://attack.mitre.org/software/S0380) is wiper malware discovered in destructive campaigns against both Middle Eastern and European targets in association with [APT33](https://attack.mitre.org/groups/G0064).(Citation: FireEye APT33 Sept 2017)(Citation: Kaspersky StoneDrill 2017)", "external_references": [{"external_id": "S0380", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0380"}, {"description": "(Citation: FireEye APT33 Sept 2017)", "source_name": "DROPSHOT"}, {"description": "(Citation: Kaspersky StoneDrill 2017)", "source_name": "StoneDrill"}, {"description": "Kaspersky Lab. (2017, March 7). From Shamoon to StoneDrill: Wipers attacking Saudi organizations and beyond. Retrieved March 14, 2019.", "source_name": "Kaspersky StoneDrill 2017", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07180722/Report_Shamoon_StoneDrill_final.pdf"}, {"description": "O''Leary, J., et al. (2017, September 20). Insights into Iranian Cyber Espionage: APT33 Targets Aerospace and Energy Sectors and has Ties to Destructive Malware. Retrieved February 15, 2018.", "source_name": "FireEye APT33 Sept 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/09/apt33-insights-into-iranian-cyber-espionage.html"}], "id": "malware--8dbadf80-468c-4a62-b817-4e4d8b606887", "is_family": true, "modified": "2024-04-11T00:00:54.356Z", "name": "StoneDrill", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["StoneDrill", "DROPSHOT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-934', 0, 146, '09-mitre-attack', 'retrieved', '6547DBA438FCD40AADDAEAA8F47BA6519A62D3C1DE80D85AEA63279F77FC1DBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
