VALUES ('doc-09-mitre-attack-p0-937', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RogueRobin](https://attack.mitre.org/software/S0270) is a payload used by [DarkHydrus](https://attack.mitre.org/groups/G0079) that has been developed in PowerShell and C#. (Citation: Unit 42 DarkHydrus July 2018)(Citation: Unit42 DarkHydrus Jan 2019)", "external_references": [{"external_id": "S0270", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0270"}, {"description": "(Citation: Unit 42 DarkHydrus July 2018)", "source_name": "RogueRobin"}, {"description": "Falcone, R., et al. (2018, July 27). New Threat Actor Group DarkHydrus Targets Middle East Government. Retrieved August 2, 2018.", "source_name": "Unit 42 DarkHydrus July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-new-threat-actor-group-darkhydrus-targets-middle-east-government/"}, {"description": "Lee, B., Falcone, R. (2019, January 18). DarkHydrus delivers new Trojan that can use Google Drive for C2 communications. Retrieved April 17, 2019.", "source_name": "Unit42 DarkHydrus Jan 2019", "url": "https://unit42.paloaltonetworks.com/darkhydrus-delivers-new-trojan-that-can-use-google-drive-for-c2-communications/"}], "id": "malware--8ec6e3b4-b06d-4805-b6aa-af916acc2122", "is_family": true, "modified": "2025-04-16T20:38:22.307Z", "name": "RogueRobin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RogueRobin"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-937', 0, 136, '09-mitre-attack', 'retrieved', 'EA73CE00