VALUES ('doc-09-mitre-attack-p0-938', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T20:26:15.141Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Attor](https://attack.mitre.org/software/S0438) is a Windows-based espionage platform that has been seen in use since 2013. [Attor](https://attack.mitre.org/software/S0438) has a loadable plugin architecture to customize functionality for specific targets.(Citation: ESET Attor Oct 2019)", "external_references": [{"external_id": "S0438", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0438"}, {"description": "(Citation: ESET Attor Oct 2019)", "source_name": "Attor"}, {"description": "Hromcova, Z. (2019, October). AT COMMANDS, TOR-BASED COMMUNICATIONS: MEET ATTOR, A FANTASY CREATURE AND ALSO A SPY PLATFORM. Retrieved May 6, 2020.", "source_name": "ESET Attor Oct 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Attor.pdf"}], "id": "malware--8f423bd7-6ca7-4303-9e85-008c7ad5fdaa", "is_family": true, "modified": "2024-04-11T02:57:38.076Z", "name": "Attor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Attor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-938', 0, 112, '09-mitre-attack', 'retrieved', '1DE5CD639587DC94A62C554D26FC8F352376C209CD57E18F50B3C3413D36E01E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
