VALUES ('doc-09-mitre-attack-p0-940', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-18T18:40:33.671Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SQLRat](https://attack.mitre.org/software/S0390) is malware that executes SQL scripts to avoid leaving traditional host artifacts. [FIN7](https://attack.mitre.org/groups/G0046) has been observed using it.(Citation: Flashpoint FIN 7 March 2019)", "external_references": [{"external_id": "S0390", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0390"}, {"description": "(Citation: Flashpoint FIN 7 March 2019)", "source_name": "SQLRat"}, {"description": "Platt, J. and Reeves, J.. (2019, March). FIN7 Revisited: Inside Astra Panel and SQLRat Malware. Retrieved June 18, 2019.", "source_name": "Flashpoint FIN 7 March 2019", "url": "https://www.flashpoint-intel.com/blog/fin7-revisited-inside-astra-panel-and-sqlrat-malware/"}], "id": "malware--8fc6c9e7-a162-4ca4-a488-f1819e9a7b06", "is_family": true, "modified": "2025-04-16T20:38:22.655Z", "name": "SQLRat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SQLRat"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-940', 0, 101, '09-mitre-attack', 'retrieved', 'CF59CE122BAB2B9F015117641C26436E5EA4A21D8CE2215F651343C40E0081B3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
