VALUES ('doc-09-mitre-attack-p0-941', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-02T14:57:58.026Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LitePower](https://attack.mitre.org/software/S0680) is a downloader and second stage malware that has been used by [WIRTE](https://attack.mitre.org/groups/G0090) since at least 2021.(Citation: Kaspersky WIRTE November 2021)", "external_references": [{"external_id": "S0680", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0680"}, {"description": "Yamout, M. (2021, November 29). WIRTE’s campaign in the Middle East ‘living off the land’ since at least 2019. Retrieved February 1, 2022.", "source_name": "Kaspersky WIRTE November 2021", "url": "https://securelist.com/wirtes-campaign-in-the-middle-east-living-off-the-land-since-at-least-2019/105044"}], "id": "malware--9020f5c7-efde-4125-a4f1-1b70f1274ddd", "is_family": true, "modified": "2025-10-21T22:49:31.186Z", "name": "LitePower", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LitePower"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-941', 0, 95, '09-mitre-attack', 'retrieved', '689E5BB7017B086AD65E6B4B8C8FD89C6D3EB471BA398A5AA1C04FC700129728', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
