VALUES ('doc-09-mitre-attack-p0-945', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-27T20:50:56.335Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BoxCaon](https://attack.mitre.org/software/S0651) is a Windows backdoor that was used by [IndigoZebra](https://attack.mitre.org/groups/G0136) in a 2021 spearphishing campaign against Afghan government officials. [BoxCaon](https://attack.mitre.org/software/S0651)''s name stems from similarities shared with the malware family [xCaon](https://attack.mitre.org/software/S0653).(Citation: Checkpoint IndigoZebra July 2021)", "external_references": [{"external_id": "S0651", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0651"}, {"description": "(Citation: Checkpoint IndigoZebra July 2021)(Citation: HackerNews IndigoZebra July 2021)", "source_name": "BoxCaon"}, {"description": "CheckPoint Research. (2021, July 1). IndigoZebra APT continues to attack Central Asia with evolving tools. Retrieved September 24, 2021.", "source_name": "Checkpoint IndigoZebra July 2021", "url": "https://research.checkpoint.com/2021/indigozebra-apt-continues-to-attack-central-asia-with-evolving-tools/"}, {"description": "Lakshmanan, R.. (2021, July 1). IndigoZebra APT Hacking Campaign Targets the Afghan Government. Retrieved September 24, 2021.", "source_name": "HackerNews IndigoZebra July 2021", "url": "https://thehackernews.com/2021/07/indigozebra-apt-hacking-campaign.html"}], "id": "malware--919a056e-5104-43b9-ad55-2ac929108b71", "is_family": true, "modified": "2025-04-25T14:44:03.536Z", "name": "BoxCaon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BoxCaon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-945', 0, 153, '09-mitre-attack', 'retrieved', 'FBA9CEC00FA70467833DD19416BE3F6DF24D1777B3A6FAA339E797554F3874E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
