VALUES ('doc-09-mitre-attack-p0-947', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-04T20:43:50.481Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Crutch](https://attack.mitre.org/software/S0538) is a backdoor designed for document theft that has been used by [Turla](https://attack.mitre.org/groups/G0010) since at least 2015.(Citation: ESET Crutch December 2020)", "external_references": [{"external_id": "S0538", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0538"}, {"description": "Faou, M. (2020, December 2). Turla Crutch: Keeping the “back door” open. Retrieved December 4, 2020.", "source_name": "ESET Crutch December 2020", "url": "https://www.welivesecurity.com/2020/12/02/turla-crutch-keeping-back-door-open/"}], "id": "malware--925a6c52-5cf0-4fec-99de-b0d6917d8593", "is_family": true, "modified": "2025-04-25T14:44:04.068Z", "name": "Crutch", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Crutch"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-947', 0, 86, '09-mitre-attack', 'retrieved', 'CD5210502BD982B07D0260418ED8B1D3B10EF00925E1D515CCF9F9CAF61D4B1F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
