VALUES ('doc-09-mitre-attack-p0-948', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-09T18:38:40.311Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Akira _v2](https://attack.mitre.org/software/S1194) is a Rust-based variant of [Akira](https://attack.mitre.org/software/S1129) ransomware that has been in use since at least 2024. [Akira _v2](https://attack.mitre.org/software/S1194) is designed to target VMware ESXi servers and includes a new command-line argument set and other expanded capabilities.(Citation: CISA Akira Ransomware APR 2024)(Citation: Cisco Akira Ransomware OCT 2024)(Citation: Palo Alto Howling Scorpius DEC 2024)", "external_references": [{"external_id": "S1194", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1194"}, {"description": "CISA et al. (2024, April 18). #StopRansomware: Akira Ransomware. Retrieved December 10, 2024.", "source_name": "CISA Akira Ransomware APR 2024", "url": "https://www.cisa.gov/sites/default/files/2024-04/aa24-109a-stopransomware-akira-ransomware_2.pdf"}, {"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}, {"description": "Zemah, Y. (2024, December 2). Threat Assessment: Howling Scorpius (Akira Ransomware). Retrieved January 8, 2025.", "source_name": "Palo Alto Howling Scorpius DEC 2024", "url": "https://unit42.paloaltonetworks.com/threat-assessment-howling-scorpius-akira-ransomware/"}], "id": "malware--929d0d4d-b7c6-4ee8-81eb-43c849294e27", "is_family": true, "modified": "2025-03-11T15:37:48.613Z", "name": "Akira _v2", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Akira _v2"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jiraput Thamsongkrah"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-948', 0, 172, '09-mitre-attack', 'retrieved', '816946CB27C02DEBECD7B77266D0D1F4F163134D312DA763C6B21C0D9DD181D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
