VALUES ('doc-09-mitre-attack-p0-949', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-01T12:29:05.241Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SDBbot](https://attack.mitre.org/software/S0461) is a backdoor with installer and loader components that has been used by [TA505](https://attack.mitre.org/groups/G0092) since at least 2019.(Citation: Proofpoint TA505 October 2019)(Citation: IBM TA505 April 2020)", "external_references": [{"external_id": "S0461", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0461"}, {"description": "Frydrych, M. (2020, April 14). TA505 Continues to Infect Networks With SDBbot RAT. Retrieved May 29, 2020.", "source_name": "IBM TA505 April 2020", "url": "https://web.archive.org/web/20200420201624/https://securityintelligence.com/posts/ta505-continues-to-infect-networks-with-sdbbot-rat/"}, {"description": "Schwarz, D. et al. (2019, October 16). TA505 Distributes New SDBbot Remote Access Trojan with Get2 Downloader. Retrieved May 29, 2020.", "source_name": "Proofpoint TA505 October 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/ta505-distributes-new-sdbbot-remote-access-trojan-get2-downloader"}], "id": "malware--92b03a94-7147-4952-9d5a-b4d24da7487c", "is_family": true, "modified": "2026-01-20T15:50:34.668Z", "name": "SDBbot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SDBbot"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-949', 0, 123, '09-mitre-attack', 'retrieved', 'BE81169E2AA1016AAA77220B339361382E939CB477ED887AC9657AD782B0525B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
