VALUES ('doc-09-mitre-attack-p0-951', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:26.565Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RTM](https://attack.mitre.org/software/S0148) is custom malware written in Delphi. It is used by the group of the same name ([RTM](https://attack.mitre.org/groups/G0048)). Newer versions of the malware have been reported publicly as Redaman.(Citation: ESET RTM Feb 2017)(Citation: Unit42 Redaman January 2019)", "external_references": [{"external_id": "S0148", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0148"}, {"description": "(Citation: Unit42 Redaman January 2019)", "source_name": "Redaman"}, {"description": "Duncan, B., Harbison, M. (2019, January 23). Russian Language Malspam Pushing Redaman Banking Malware. Retrieved June 16, 2020.", "source_name": "Unit42 Redaman January 2019", "url": "https://unit42.paloaltonetworks.com/russian-language-malspam-pushing-redaman-banking-malware/"}, {"description": "Faou, M. and Boutin, J. (2017, February). Read The Manual: A Guide to the RTM Banking Trojan. Retrieved March 9, 2017.", "source_name": "ESET RTM Feb 2017", "url": "https://www.welivesecurity.com/wp-content/uploads/2017/02/Read-The-Manual.pdf"}], "id": "malware--92ec0cbd-2c30-44a2-b270-73f4ec949841", "is_family": true, "modified": "2025-04-16T20:38:23.633Z", "name": "RTM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RTM", "Redaman"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Arie Olshtein, Check Point", "Kobi Eisenkraft, Check Point"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-951', 0, 152, '09-mitre-attack', 'retrieved', '2AA391601491E97D8A66958FDA2DCE860D79A2F47965AA9E851483C8132BE00F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
