VALUES ('doc-09-mitre-attack-p0-952', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-19T20:18:52.141Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QUIETCANARY](https://attack.mitre.org/software/S1076) is a backdoor tool written in .NET that has been used since at least 2022 to gather and exfiltrate data from victim networks.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"external_id": "S1076", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1076"}, {"description": "(Citation: Mandiant Suspected Turla Campaign February 2023)", "source_name": "Tunnus"}, {"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "malware--93289ecf-4d15-4d6b-a9c3-4ab27e145ef4", "is_family": true, "modified": "2025-04-16T20:38:23.780Z", "name": "QUIETCANARY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["QUIETCANARY", "Tunnus"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-952', 0, 124, '09-mitre-attack', 'retrieved', 'A32F53E5C09026A0E9D125751AF1D1A4DAF9F5A3E996C6418DB45AF5A86B1C9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
