VALUES ('doc-09-mitre-attack-p0-954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:18.668Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Derusbi](https://attack.mitre.org/software/S0021) is malware used by multiple Chinese APT groups.(Citation: Novetta-Axiom)(Citation: ThreatConnect Anthem) Both Windows and Linux variants have been observed.(Citation: Fidelis Turbo)", "external_references": [{"external_id": "S0021", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0021"}, {"description": "(Citation: FireEye Periscope March 2018)", "source_name": "PHOTO"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Derusbi"}, {"description": "Fidelis Cybersecurity. (2016, February 29). The Turbo Campaign, Featuring Derusbi for 64-bit Linux. Retrieved March 2, 2016.", "source_name": "Fidelis Turbo", "url": "https://paper.seebug.org/papers/APT/APT_CyberCriminal_Campagin/2016/2016.02.29.Turbo_Campaign_Derusbi/TA_Fidelis_Turbo_1602_0.pdf"}, {"description": "FireEye. (2018, March 16). Suspected Chinese Cyber Espionage Group (TEMP.Periscope) Targeting U.S. Engineering and Maritime Industries. Retrieved April 11, 2018.", "source_name": "FireEye Periscope March 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/03/suspected-chinese-espionage-group-targeting-maritime-and-engineering-industries.html"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}, {"description": "ThreatConnect Research Team. (2015, February 27). The Anthem Hack: All Roads Lead to China. Retrieved January 26, 2016.", "source_name": "ThreatConnect Anthem", "url": "https://www.threatconnect.com/the-anthem-hack-all-roads-lead-to-china/"}], "id": "malware--94379dec-5c87-49db-b36e-66abc0b81344", "is_family": true, "modified": "2025-04-16T20:38:23.924Z", "name": "Derusbi", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Derusbi", "PHOTO"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-954', 0, 172, '09-mitre-attack', 'retrieved', 'C523E58AD9E223152D0B562FF80535D5C4471FF3FBFB2918B993ED723C34A785', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
