VALUES ('doc-09-mitre-attack-p0-958', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:14.124Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hikit](https://attack.mitre.org/software/S0009) is malware that has been used by [Axiom](https://attack.mitre.org/groups/G0001) for late-stage persistence and exfiltration after the initial compromise.(Citation: Novetta-Axiom)(Citation: FireEye Hikit Rootkit)", "external_references": [{"external_id": "S0009", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0009"}, {"description": "Glyer, C., Kazanciyan, R. (2012, August 20). The “Hikit” Rootkit: Advanced and Persistent Attack Techniques (Part 1). Retrieved November 17, 2024.", "source_name": "FireEye Hikit Rootkit", "url": "https://web.archive.org/web/20190216180458/https://www.fireeye.com/blog/threat-research/2012/08/hikit-rootkit-advanced-persistent-attack-techniques-part-1.html"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}], "id": "malware--95047f03-4811-4300-922e-1ba937d53a61", "is_family": true, "modified": "2024-11-17T15:43:38.148Z", "name": "Hikit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hikit"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Christopher Glyer, Mandiant, @cglyer"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-958', 0, 115, '09-mitre-attack', 'retrieved', '11F027EC3BED9C519C2E4CC26EE6BC375A39993330BBC644EF1CF0052DA53E19', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
