VALUES ('doc-09-mitre-attack-p0-959', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T16:12:44.473Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) is an information stealer malware variant first identified in November 2022 and active through late 2024. [StrelaStealer](https://attack.mitre.org/software/S1183) focuses on the automated identification, collection, and exfiltration of email credentials from email clients such as Outlook and Thunderbird.(Citation: DCSO StrelaStealer 2022)(Citation: PaloAlto StrelaStealer 2024)(Citation: Fortgale StrelaStealer 2023)(Citation: IBM StrelaStealer 2024)", "external_references": [{"external_id": "S1183", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1183"}, {"description": "Benjamin Chang, Goutam Tripathy, Pranay Kumar Chhaparwal, Anmol Maurya & Vishwa Thothathri, Palo Alto Networks. (2024, March 22). Large-Scale StrelaStealer Campaign in Early 2024. Retrieved December 31, 2024.", "source_name": "PaloAlto StrelaStealer 2024", "url": "https://unit42.paloaltonetworks.com/strelastealer-campaign/"}, {"description": "DCSO CyTec Blog. (2022, November 8). #ShortAndMalicious: StrelaStealer aims for mail credentials. Retrieved December 31, 2024.", "source_name": "DCSO StrelaStealer 2022", "url": "https://medium.com/@DCSO_CyTec/shortandmalicious-strelastealer-aims-for-mail-credentials-a4c3e78c8abc"}, {"description": "Fortgale. (2023, September 18). StrelaStealer Malware Analysis. Retrieved December 31, 2024.", "source_name": "Fortgale StrelaStealer 2023", "url": "https://fortgale.com/blog/malware-analysis/strelastealer-malware-analysis-2/"}, {"description": "Golo Mühr, Joe Fasulo & Charlotte Hammond, IBM X-Force. (2024, November 12). Strela Stealer: Today’s invoice is tomorrow’s phish. Retrieved December 31, 2024.", "source_name": "IBM StrelaStealer 2024", "url": "https://securityintelligence.com/x-force/strela-stealer-todays-invoice-tomorrows-phish/"}], "id": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "is_family": true, "modified": "2025-03-10T18:57:36.697Z", "name": "StrelaStealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["StrelaStealer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Kori Yoshihiro, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-959', 0, 212, '09-mitre-attack', 'retrieved', '162C50004231B59279D2301C6CBC4C468DB07E9EACFE4C01D602BECCCDC66C8F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
