VALUES ('doc-09-mitre-attack-p0-960', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-10T21:13:44.259Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Grandoreiro](https://attack.mitre.org/software/S0531) is a banking trojan written in Delphi that was first observed in 2016 and uses a Malware-as-a-Service (MaaS) business model. [Grandoreiro](https://attack.mitre.org/software/S0531) has confirmed victims in Brazil, Mexico, Portugal, and Spain.(Citation: Securelist Brazilian Banking Malware July 2020)(Citation: ESET Grandoreiro April 2020)", "external_references": [{"external_id": "S0531", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0531"}, {"description": "ESET. (2020, April 28). Grandoreiro: How engorged can an EXE get?. Retrieved November 13, 2020.", "source_name": "ESET Grandoreiro April 2020", "url": "https://www.welivesecurity.com/2020/04/28/grandoreiro-how-engorged-can-exe-get/"}, {"description": "GReAT. (2020, July 14). The Tetrade: Brazilian banking malware goes global. Retrieved November 9, 2020.", "source_name": "Securelist Brazilian Banking Malware July 2020", "url": "https://securelist.com/the-tetrade-brazilian-banking-malware/97779/"}], "id": "malware--958b5d06-8bb0-4c5b-a2e7-0130fe654ac7", "is_family": true, "modified": "2024-04-11T02:25:51.549Z", "name": "Grandoreiro", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Grandoreiro"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-960', 0, 131, '09-mitre-attack', 'retrieved', '86F2E28E33AD67C2317AEF27B1B0A6415645832919105D36DFDF5A6D7735E547', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
