VALUES ('doc-09-mitre-attack-p0-963', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Starloader](https://attack.mitre.org/software/S0188) is a loader component that has been observed loading [Felismus](https://attack.mitre.org/software/S0171) and associated tools. (Citation: Symantec Sowbug Nov 2017)", "external_references": [{"external_id": "S0188", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0188"}, {"description": "(Citation: Symantec Sowbug Nov 2017)", "source_name": "Starloader"}, {"description": "Symantec Security Response. (2017, November 7). Sowbug: Cyber espionage group targets South American and Southeast Asian governments. Retrieved November 16, 2017.", "source_name": "Symantec Sowbug Nov 2017", "url": "https://www.symantec.com/connect/blogs/sowbug-cyber-espionage-group-targets-south-american-and-southeast-asian-governments"}], "id": "malware--96566860-9f11-4b6f-964d-1c924e4f24a4", "is_family": true, "modified": "2025-04-25T14:44:07.496Z", "name": "Starloader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Starloader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Alan Neville, @abnev"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-963', 0, 100, '09-mitre-attack', 'retrieved', 'CCE00B63BFFEA8204EF541ACF277F94C1055973387E39B4BB847DDC4A8E433F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
