VALUES ('doc-09-mitre-attack-p0-964', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:48.482Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sakula](https://attack.mitre.org/software/S0074) is a remote access tool (RAT) that first surfaced in 2012 and was used in intrusions throughout 2015. (Citation: Dell Sakula)", "external_references": [{"external_id": "S0074", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0074"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, July 30). Sakula Malware Family. Retrieved January 26, 2016.", "source_name": "Dell Sakula", "url": "http://www.secureworks.com/cyber-threat-intelligence/threats/sakula-malware-family/"}], "id": "malware--96b08451-b27a-4ff6-893f-790e26393a8e", "is_family": true, "modified": "2024-04-11T00:10:10.398Z", "name": "Sakula", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Sakula", "Sakurel", "VIPER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-964', 0, 89, '09-mitre-attack', 'retrieved', '6268B229FCF3B388F41C2AAF6A5EA91F4FC0CAC3F6C23A7BBB65F05168ACF4D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
