VALUES ('doc-09-mitre-attack-p0-965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-04T15:02:56.965Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VaporRage](https://attack.mitre.org/software/S0636) is a shellcode downloader that has been used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2021.(Citation: MSTIC Nobelium Toolset May 2021)", "external_references": [{"external_id": "S0636", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0636"}, {"description": "MSTIC. (2021, May 28). Breaking down NOBELIUM’s latest early-stage toolset. Retrieved August 4, 2021.", "source_name": "MSTIC Nobelium Toolset May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/28/breaking-down-nobeliums-latest-early-stage-toolset/"}], "id": "malware--96eca9b9-b37f-42f1-96dc-a2c441403194", "is_family": true, "modified": "2025-04-25T14:44:08.033Z", "name": "VaporRage", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["VaporRage"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-965', 0, 83, '09-mitre-attack', 'retrieved', 'E148DD0A6546BD148DB6FBA53F9F0A8771AB834ECF2AC0E98228B4DFFC34D221', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
