VALUES ('doc-09-mitre-attack-p0-968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-02T12:27:33.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZxxZ](https://attack.mitre.org/software/S1013) is a trojan written in Visual C++ that has been used by [BITTER](https://attack.mitre.org/groups/G1002) since at least August 2021, including against Bangladeshi government personnel.(Citation: Cisco Talos Bitter Bangladesh May 2022)", "external_references": [{"external_id": "S1013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1013"}, {"description": "Raghuprasad, C . (2022, May 11). Bitter APT adds Bangladesh to their targets. Retrieved June 1, 2022.", "source_name": "Cisco Talos Bitter Bangladesh May 2022", "url": "https://blog.talosintelligence.com/2022/05/bitter-apt-adds-bangladesh-to-their.html"}], "id": "malware--97cfbdc6-504d-41e9-a46c-78a9f806ff0d", "is_family": true, "modified": "2024-04-10T20:29:50.729Z", "name": "ZxxZ", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ZxxZ"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-968', 0, 99, '09-mitre-attack', 'retrieved', 'AE4A478A8EED5E9342594C832A1030983660E5CFC6ECD2018BD15DA19775A5D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
