VALUES ('doc-09-mitre-attack-p0-969', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T17:48:45.413Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Caminho](https://attack.mitre.org/software/S9016) is a downloader that has been used by threat actors since at least 2025 to deliver various strains of malware such as XWorm.(Citation: Zscaler BlindEagle DEC 2025)", "external_references": [{"external_id": "S9016", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9016"}, {"description": "(Citation: Zscaler BlindEagle DEC 2025)", "source_name": "VMDetectLoader"}, {"description": "Pellegrino, G. (2025, December 16). BlindEagle Targets Colombian Government Agency with Caminho and DCRAT. Retrieved April 16, 2026.", "source_name": "Zscaler BlindEagle DEC 2025", "url": "https://www.zscaler.com/blogs/security-research/blindeagle-targets-colombian-government-agency-caminho-and-dcrat"}], "id": "malware--97da6467-c9c5-4eb0-84d4-1234e937e534", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "Caminho", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Caminho", "VMDetectLoader"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-969', 0, 105, '09-mitre-attack', 'retrieved', '742E18352E2A0D1B0BDE0FE9E78E3CFDADA7FC67130C8CF78A094A5A9FCBE31D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
