VALUES ('doc-09-mitre-attack-p0-970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-01T17:01:32.151Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tarrask](https://attack.mitre.org/software/S1011) is malware that has been used by [HAFNIUM](https://attack.mitre.org/groups/G0125) since at least August 2021. [Tarrask](https://attack.mitre.org/software/S1011) was designed to evade digital defenses and maintain persistence by generating concealed scheduled tasks.(Citation: Tarrask scheduled task)", "external_references": [{"external_id": "S1011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1011"}, {"description": "Microsoft Threat Intelligence Team & Detection and Response Team . (2022, April 12). Tarrask malware uses scheduled tasks for defense evasion. Retrieved June 1, 2022.", "source_name": "Tarrask scheduled task", "url": "https://www.microsoft.com/security/blog/2022/04/12/tarrask-malware-uses-scheduled-tasks-for-defense-evasion/"}], "id": "malware--988976ff-beeb-4fb5-b07d-ca7437ea66e8", "is_family": true, "modified": "2025-04-16T20:38:25.204Z", "name": "Tarrask", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Tarrask"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Sittikorn Sangrattanapitak"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-970', 0, 109, '09-mitre-attack', 'retrieved', 'ED95E0464E51219A28C1ADD27A2FF920D8CF22017E8DF1C5419165CA23C0503B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
