VALUES ('doc-09-mitre-attack-p0-973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-25T18:05:14.953Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Drovorub](https://attack.mitre.org/software/S0502) is a Linux malware toolset comprised of an agent, client, server, and kernel modules, that has been used by [APT28](https://attack.mitre.org/groups/G0007).(Citation: NSA/FBI Drovorub August 2020)", "external_references": [{"external_id": "S0502", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0502"}, {"description": "NSA/FBI. (2020, August). Russian GRU 85th GTsSS Deploys Previously Undisclosed Drovorub Malware. Retrieved August 25, 2020.", "source_name": "NSA/FBI Drovorub August 2020", "url": "https://media.defense.gov/2020/Aug/13/2002476465/-1/-1/0/CSA_DROVORUB_RUSSIAN_GRU_MALWARE_AUG_2020.PDF"}], "id": "malware--99164b38-1775-40bc-b77b-a2373b14540a", "is_family": true, "modified": "2025-04-25T14:44:09.839Z", "name": "Drovorub", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Drovorub"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-973', 0, 89, '09-mitre-attack', 'retrieved', '9463F69EA70673B17E5C2484D9B3E56D3D165AFF8AC2A32BBA6E744BD7F47F56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
