VALUES ('doc-09-mitre-attack-p0-974', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-10T19:45:53.538Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shark](https://attack.mitre.org/software/S1019) is a backdoor malware written in C# and .NET that is an updated version of [Milan](https://attack.mitre.org/software/S1015); it has been used by [HEXANE](https://attack.mitre.org/groups/G1001) since at least July 2021.(Citation: ClearSky Siamesekitten August 2021)(Citation: Accenture Lyceum Targets November 2021)", "external_references": [{"external_id": "S1019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1019"}, {"description": "Accenture. (2021, November 9). Who are latest targets of cyber group Lyceum?. Retrieved June 16, 2022.", "source_name": "Accenture Lyceum Targets November 2021", "url": "https://www.accenture.com/us-en/blogs/cyber-defense/iran-based-lyceum-campaigns"}, {"description": "ClearSky Cyber Security . (2021, August). New Iranian Espionage Campaign By “Siamesekitten” - Lyceum. Retrieved June 6, 2022.", "source_name": "ClearSky Siamesekitten August 2021", "url": "https://www.clearskysec.com/siamesekitten/"}], "id": "malware--99854cc8-f202-4e03-aa0a-4f8a4af93229", "is_family": true, "modified": "2024-04-11T00:08:18.570Z", "name": "Shark", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Shark"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-974', 0, 130, '09-mitre-attack', 'retrieved', '650D6C1F3263E6C8B101C7AF2911657E3EE1B459A08B5D68EA31E590F64CD8DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
