VALUES ('doc-09-mitre-attack-p0-976', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-08T18:30:54.263Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PULSECHECK](https://attack.mitre.org/software/S1108) is a web shell written in Perl that was used by [APT5](https://attack.mitre.org/groups/G1023) as early as 2020 including against Pulse Secure VPNs at US Defense Industrial Base (DIB) companies.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"external_id": "S1108", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1108"}, {"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "malware--9a097d18-d15f-4635-a4f1-189df7efdc40", "is_family": true, "modified": "2025-04-15T19:46:34.866Z", "name": "PULSECHECK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PULSECHECK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-976', 0, 114, '09-mitre-attack', 'retrieved', '6247F1F9ABD303A5EBF84E6B8F13F34CA0475E9567264A978ACCB229F5B5E837', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
