VALUES ('doc-09-mitre-attack-p0-977', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-24T18:56:35.507Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kobalos](https://attack.mitre.org/software/S0641) is a multi-platform backdoor that can be used against Linux, FreeBSD, and Solaris. [Kobalos](https://attack.mitre.org/software/S0641) has been deployed against high profile targets, including high-performance computers, academic servers, an endpoint security vendor, and a large internet service provider; it has been found in Europe, North America, and Asia. [Kobalos](https://attack.mitre.org/software/S0641) was first identified in late 2019.(Citation: ESET Kobalos Feb 2021)(Citation: ESET Kobalos Jan 2021)", "external_references": [{"external_id": "S0641", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0641"}, {"description": "(Citation: ESET Kobalos Feb 2021)(Citation: ESET Kobalos Jan 2021)", "source_name": "Kobalos"}, {"description": "M.Leveille, M., Sanmillan, I. (2021, February 2). Kobalos – A complex Linux threat to high performance computing infrastructure. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Feb 2021", "url": "https://www.welivesecurity.com/2021/02/02/kobalos-complex-linux-threat-high-performance-computing-infrastructure/"}, {"description": "M.Leveille, M., Sanmillan, I. (2021, January). A WILD KOBALOS APPEARS Tricksy Linux malware goes after HPCs. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Jan 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/01/ESET_Kobalos.pdf"}], "id": "malware--9abdda30-08e0-4ab1-9cf0-d447654c6de9", "is_family": true, "modified": "2025-04-25T14:44:10.741Z", "name": "Kobalos", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kobalos"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-977', 0, 187, '09-mitre-attack', 'retrieved', '465F4039AEA6ED12088E2AF50BF51B03B744722233134A396439F958BE4FA5AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
