VALUES ('doc-09-mitre-attack-p0-978', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:33:34.082Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BadPatch](https://attack.mitre.org/software/S0337) is a Windows Trojan that was used in a Gaza Hackers-linked campaign.(Citation: Unit 42 BadPatch Oct 2017)", "external_references": [{"external_id": "S0337", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0337"}, {"description": "(Citation: Unit 42 BadPatch Oct 2017)", "source_name": "BadPatch"}, {"description": "Bar, T., Conant, S. (2017, October 20). BadPatch. Retrieved November 13, 2018.", "source_name": "Unit 42 BadPatch Oct 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/10/unit42-badpatch/"}], "id": "malware--9af05de0-bc09-4511-a350-5eb8b06185c1", "is_family": true, "modified": "2025-04-25T14:44:11.108Z", "name": "BadPatch", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BadPatch"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-978', 0, 88, '09-mitre-attack', 'retrieved', '924930EA2F2EC6927773E237C70A0D874C55A8BD5F12CF5EC2D7ABF72C0F1800', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
