VALUES ('doc-09-mitre-attack-p0-981', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-21T21:02:02.388Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUGARDUMP](https://attack.mitre.org/software/S1042) is a proprietary browser credential harvesting tool that was used by UNC3890 during the [C0010](https://attack.mitre.org/campaigns/C0010) campaign. The first known [SUGARDUMP](https://attack.mitre.org/software/S1042) version was used since at least early 2021, a second SMTP C2 version was used from late 2021-early 2022, and a third HTTP C2 variant was used since at least April 2022.(Citation: Mandiant UNC3890 Aug 2022)", "external_references": [{"external_id": "S1042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1042"}, {"description": "Mandiant Israel Research Team. (2022, August 17). Suspected Iranian Actor Targeting Israeli Shipping, Healthcare, Government and Energy Sectors. Retrieved September 21, 2022.", "source_name": "Mandiant UNC3890 Aug 2022", "url": "https://www.mandiant.com/resources/blog/suspected-iranian-actor-targeting-israeli-shipping"}], "id": "malware--9c10cede-c0bb-4c5c-91c0-8baec30abaf6", "is_family": true, "modified": "2025-04-16T20:38:26.373Z", "name": "SUGARDUMP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SUGARDUMP"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-981', 0, 129, '09-mitre-attack', 'retrieved', 'E8DC0899623BE6B9A6512724C1AC3F63A05E7458095FC7BE4FA0A7094A9BC5D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
