VALUES ('doc-09-mitre-attack-p0-984', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BADCALL](https://attack.mitre.org/software/S0245) is a Trojan malware variant used by the group [Lazarus Group](https://attack.mitre.org/groups/G0032). (Citation: US-CERT BADCALL)", "external_references": [{"external_id": "S0245", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0245"}, {"description": "(Citation: US-CERT BADCALL)", "source_name": "BADCALL"}, {"description": "US-CERT. (2018, February 06). Malware Analysis Report (MAR) - 10135536-G. Retrieved June 7, 2018.", "source_name": "US-CERT BADCALL", "url": "https://www.us-cert.gov/sites/default/files/publications/MAR-10135536-G.PDF"}], "id": "malware--9dbdadb6-fdbf-490f-a35f-38762d06a0d2", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "BADCALL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BADCALL"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-984', 0, 83, '09-mitre-attack', 'retrieved', '22AC1505154EB37002DC73C599EBAE485FE1EFC22066642E67841D88ACB7BD13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
