VALUES ('doc-09-mitre-attack-p0-985', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:46.890Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[hcdLoader](https://attack.mitre.org/software/S0071) is a remote access tool (RAT) that has been used by [APT18](https://attack.mitre.org/groups/G0026). (Citation: Dell Lateral Movement)", "external_references": [{"external_id": "S0071", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0071"}, {"description": "Carvey, H.. (2014, September 2). Where you AT?: Indicators of lateral movement using at.exe on Windows 7 systems. Retrieved January 25, 2016.", "source_name": "Dell Lateral Movement", "url": "http://www.secureworks.com/resources/blog/where-you-at-indicators-of-lateral-movement-using-at-exe-on-windows-7-systems/"}], "id": "malware--9e2bba94-950b-4fcf-8070-cb3f816c5f4e", "is_family": true, "modified": "2025-04-25T14:44:13.298Z", "name": "hcdLoader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["hcdLoader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-985', 0, 86, '09-mitre-attack', 'retrieved', '47E87DB6DF554EA4C816D4FFB2E5314377118CA0C7C38EB781C558C3B92D58F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
