VALUES ('doc-09-mitre-attack-p0-986', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:09.842Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nidiran](https://attack.mitre.org/software/S0118) is a custom backdoor developed and used by [Suckfly](https://attack.mitre.org/groups/G0039). It has been delivered via strategic web compromise. (Citation: Symantec Suckfly March 2016)", "external_references": [{"external_id": "S0118", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0118"}, {"description": "DiMaggio, J. (2016, March 15). Suckfly: Revealing the secret life of your code signing certificates. Retrieved August 3, 2016.", "source_name": "Symantec Suckfly March 2016", "url": "http://www.symantec.com/connect/blogs/suckfly-revealing-secret-life-your-code-signing-certificates"}], "id": "malware--9e9b9415-a7df-406b-b14d-92bfe6809fbe", "is_family": true, "modified": "2025-04-16T20:38:27.055Z", "name": "Nidiran", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Nidiran", "Backdoor.Nidiran"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-986', 0, 93, '09-mitre-attack', 'retrieved', '95443B2E1497ECC4E5E572E0A559CF0F308B996CE7AA81647510BDECDDC27294', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
