VALUES ('doc-09-mitre-attack-p0-988', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T17:12:08.208Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HiddenFace](https://attack.mitre.org/software/S9023) is a modular backdoor developed and used exclusively by [MirrorFace](https://attack.mitre.org/groups/G1054) since at least 2021. [HiddenFace](https://attack.mitre.org/software/S9023) can communicate both actively and passively and has been used against political and academic targets.(Citation: JPCERT MirrorFace JUL 2024)(Citation: Trend Micro Earth Kasha NOV 2024)(Citation: Trend Micro Earth Kasha Updates APR 2025)", "external_references": [{"external_id": "S9023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9023"}, {"description": "(Citation: ESET HiddenFace 2024)(Citation: Trend Micro Earth Kasha NOV 2024)(Citation: Trend Micro Earth Kasha Updates APR 2025)", "source_name": "NOOPDOOR"}, {"description": "Breitenbacher, D. (2024). Unmasking HiddenFace. Retrieved April 17, 2026.", "source_name": "ESET HiddenFace 2024", "url": "https://jsac.jpcert.or.jp/archive/2024/pdf/JSAC2024_2_8_Breitenbacher_en.pdf"}, {"description": "Hiroaki, H. (2025, April 30). Earth Kasha Updates TTPs in Latest Campaign Targeting Taiwan and Japan. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Updates APR 2025", "url": "https://www.trendmicro.com/en_us/research/25/d/earth-kasha-updates-ttps.html"}, {"description": "Tomonaga, S. (2024, July 16). MirrorFace Attack against Japanese Organisations. Retrieved April 17, 2026.", "source_name": "JPCERT MirrorFace JUL 2024", "url": "https://blogs.jpcert.or.jp/en/2024/07/mirrorface-attack-against-japanese-organisations.html"}, {"description": "Trend Micro. (2024, November 19). Spot the Difference: Earth Kasha''s New LODEINFO Campaign And The Correlation Analysis With The APT10 Umbrella. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/lodeinfo-campaign-of-earth-kasha.html"}], "id": "malware--9edc41d1-a13d-4acf-b400-d47fb2f6809d", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "HiddenFace", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HiddenFace", "NOOPDOOR"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-988', 0, 219, '09-mitre-attack', 'retrieved', 'E55250E8D1389F718872B610122A43E6D79AE508338AB3268F62660A84149774', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
