VALUES ('doc-09-mitre-attack-p0-991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-10T14:26:12.369Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cryptoistic](https://attack.mitre.org/software/S0498) is a backdoor, written in Swift, that has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032).(Citation: SentinelOne Lazarus macOS July 2020)", "external_references": [{"external_id": "S0498", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0498"}, {"description": "Stokes, P. (2020, July 27). Four Distinct Families of Lazarus Malware Target Apple’s macOS Platform. Retrieved August 7, 2020.", "source_name": "SentinelOne Lazarus macOS July 2020", "url": "https://www.sentinelone.com/blog/four-distinct-families-of-lazarus-malware-target-apples-macos-platform/"}], "id": "malware--a04d9a4c-bb52-40bf-98ec-e350c2d6a862", "is_family": true, "modified": "2025-04-25T14:44:14.409Z", "name": "Cryptoistic", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cryptoistic"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-991', 0, 87, '09-mitre-attack', 'retrieved', 'AE1A7B03F36F8495A8102D958BE1C9B5CC6BA215BFF752EAE0430DCD5D6C2D9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
