VALUES ('doc-09-mitre-attack-p0-992', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T18:30:08.906Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HermeticWiper](https://attack.mitre.org/software/S0697) is a data wiper that has been used since at least early 2022, primarily against Ukraine with additional activity observed in Latvia and Lithuania. Some sectors targeted include government, financial, defense, aviation, and IT services.(Citation: SentinelOne Hermetic Wiper February 2022)(Citation: Symantec Ukraine Wipers February 2022)(Citation: Crowdstrike DriveSlayer February 2022)(Citation: ESET Hermetic Wiper February 2022)(Citation: Qualys Hermetic Wiper March 2022)", "external_references": [{"external_id": "S0697", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0697"}, {"description": "(Citation: CISA AA22-057A Destructive Malware February 2022)(Citation: Symantec Ukraine Wipers February 2022)", "source_name": "Trojan.Killdisk"}, {"description": "(Citation: Crowdstrike PartyTicket March 2022)(Citation: Crowdstrike DriveSlayer February 2022)", "source_name": "DriveSlayer"}, {"description": "CISA. (2022, February 26). Destructive Malware Targeting Organizations in Ukraine. Retrieved March 25, 2022.", "source_name": "CISA AA22-057A Destructive Malware February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-057a"}, {"description": "Crowdstrike. (2022, March 1). Decryptable PartyTicket Ransomware Reportedly Targeting Ukrainian Entities. Retrieved March 1, 2022.", "source_name": "Crowdstrike PartyTicket March 2022", "url": "https://www.crowdstrike.com/blog/how-to-decrypt-the-partyticket-ransomware-targeting-ukraine"}, {"description": "Dani, M. (2022, March 1). Ukrainian Targets Hit by HermeticWiper, New Datawiper Malware. Retrieved March 25, 2022.", "source_name": "Qualys Hermetic Wiper March 2022", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2022/03/01/ukrainian-targets-hit-by-hermeticwiper-new-datawiper-malware"}, {"description": "ESET. (2022, February 24). HermeticWiper: New data wiping malware hits Ukraine. Retrieved March 25, 2022.", "source_name": "ESET Hermetic Wiper February 2022", "url": "https://www.welivesecurity.com/2022/02/24/hermeticwiper-new-data-wiping-malware-hits-ukraine"}, {"description": "Guerrero-Saade, J. (2022, February 23). HermeticWiper | New Destructive Malware Used In Cyber Attacks on Ukraine. Retrieved March 25, 2022.", "source_name": "SentinelOne Hermetic Wiper February 2022", "url": "https://www.sentinelone.com/labs/hermetic-wiper-ukraine-under-attack"}, {"description": "Symantec Threat Hunter Team. (2022, February 24). Ukraine: Disk-wiping Attacks Precede Russian Invasion. Retrieved March 25, 2022.", "source_name": "Symantec Ukraine Wipers February 2022", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/ukraine-wiper-malware-russia"}, {"description": "Thomas, W. et al. (2022, February 25). CrowdStrike Falcon Protects from New Wiper Malware Used in Ukraine Cyberattacks. Retrieved March 25, 2022.", "source_name": "Crowdstrike DriveSlayer February 2022", "url": "https://www.crowdstrike.com/blog/how-crowdstrike-falcon-protects-against-wiper-malware-used-in-ukraine-attacks/"}], "id": "malware--a0ab8a96-40c9-4483-8a54-3fafa6d6007a", "is_family": true, "modified": "2025-10-21T23:23:39.286Z", "name": "HermeticWiper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HermeticWiper", "Trojan.Killdisk", "DriveSlayer"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Mayuresh Dani, Qualys", "Harshal Tupsamudre, Qualys"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-992', 0, 320, '09-mitre-attack', 'retrieved', '0223DBB09E73F3A9ADA6C9519C187506B7D7761303787492829CF49099E0209D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
