VALUES ('doc-09-mitre-attack-p0-994', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-01T19:44:27.287Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pysa](https://attack.mitre.org/software/S0583) is a ransomware that was first used in October 2018 and has been seen to target particularly high-value finance, government and healthcare organizations.(Citation: CERT-FR PYSA April 2020)", "external_references": [{"external_id": "S0583", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0583"}, {"description": "(Citation: CERT-FR PYSA April 2020)(Citation: DFIR Pysa Nov 2020)(Citation: NHS Digital Pysa Oct 2020)", "source_name": "Pysa"}, {"description": "(Citation: CERT-FR PYSA April 2020)(Citation: DFIR Pysa Nov 2020)(Citation: NHS Digital Pysa Oct 2020)", "source_name": "Mespinoza"}, {"description": "CERT-FR. (2020, April 1). ATTACKS INVOLVING THE MESPINOZA/PYSA RANSOMWARE. Retrieved March 1, 2021.", "source_name": "CERT-FR PYSA April 2020", "url": "https://www.cert.ssi.gouv.fr/uploads/CERTFR-2020-CTI-003.pdf"}, {"description": "THe DFIR Report. (2020, November 23). PYSA/Mespinoza Ransomware. Retrieved March 17, 2021.", "source_name": "DFIR Pysa Nov 2020", "url": "https://thedfirreport.com/2020/11/23/pysa-mespinoza-ransomware/"}, {"description": "NHS Digital. (2020, October 10). Pysa Ransomware: Another ''big-game hunter'' ransomware. Retrieved March 17, 2021.", "source_name": "NHS Digital Pysa Oct 2020", "url": "https://digital.nhs.uk/cyber-alerts/2020/cc-3633"}], "id": "malware--a19c1197-9414-46e3-986f-0f609ff4a46b", "is_family": true, "modified": "2025-04-25T14:44:15.316Z", "name": "Pysa", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pysa", "Mespinoza"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-994', 0, 173, '09-mitre-attack', 'retrieved', 'C8571DA225BF17D103E02252C6A41EFD485335FFF2CEBFD5BE770067C42CDBAF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
