VALUES ('doc-09-mitre-attack-p0-995', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:32.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wiper](https://attack.mitre.org/software/S0041) is a family of destructive malware used in March 2013 during breaches of South Korean banks and media companies. (Citation: Dell Wiper)", "external_references": [{"external_id": "S0041", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0041"}, {"description": "Dell SecureWorks. (2013, March 21). Wiper Malware Analysis Attacking Korean Financial Sector. Retrieved May 13, 2015.", "source_name": "Dell Wiper", "url": "http://www.secureworks.com/cyber-threat-intelligence/threats/wiper-malware-analysis-attacking-korean-financial-sector/"}], "id": "malware--a19c49aa-36fe-4c05-b817-23e1c7a7d085", "is_family": true, "modified": "2025-04-25T14:44:15.681Z", "name": "Wiper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-995', 0, 81, '09-mitre-attack', 'retrieved', '308153B60A3FAD25E61A86499EAAB8479B439A4DE479DF449DAF6EF7096AA11B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
