VALUES ('doc-09-mitre-attack-p0-996', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T00:23:06.022Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Final1stspy](https://attack.mitre.org/software/S0355) is a dropper family that has been used to deliver [DOGCALL](https://attack.mitre.org/software/S0213).(Citation: Unit 42 Nokki Oct 2018)", "external_references": [{"external_id": "S0355", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0355"}, {"description": "(Citation: Unit 42 Nokki Oct 2018)", "source_name": "Final1stspy"}, {"description": "Grunzweig, J. (2018, October 01). NOKKI Almost Ties the Knot with DOGCALL: Reaper Group Uses New Malware to Deploy RAT. Retrieved November 5, 2018.", "source_name": "Unit 42 Nokki Oct 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/10/unit42-nokki-almost-ties-the-knot-with-dogcall-reaper-group-uses-new-malware-to-deploy-rat/"}], "id": "malware--a2282af0-f9dd-4373-9b92-eaf9e11e0c71", "is_family": true, "modified": "2025-04-25T14:44:16.040Z", "name": "Final1stspy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Final1stspy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-996', 0, 99, '09-mitre-attack', 'retrieved', 'E0FCDB2256450E8D80E6E8018EBF415A5AE434D1DBA5A64350AC7674D9F8DD3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
