VALUES ('doc-09-mitre-attack-p0-997', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-25T18:16:57.099Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MgBot](https://attack.mitre.org/software/S1146) is a modular malware framework exclusively associated with [Daggerfly](https://attack.mitre.org/groups/G1034) operations since at least 2012. [MgBot](https://attack.mitre.org/software/S1146) was developed in C++ and features a module design with multiple available plugins that have been under active development through 2024.(Citation: Szappanos MgBot 2014)(Citation: ESET EvasivePanda 2023)(Citation: Symantec Daggerfly 2024)", "external_references": [{"external_id": "S1146", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1146"}, {"description": "Facundo Muñoz. (2023, April 26). Evasive Panda APT group delivers malware via updates for popular Chinese software. Retrieved July 25, 2024.", "source_name": "ESET EvasivePanda 2023", "url": "https://www.welivesecurity.com/2023/04/26/evasive-panda-apt-group-malware-updates-popular-chinese-software/"}, {"description": "Gabor Szappanos. (2014, February 3). Needle in a haystack. Retrieved July 25, 2024.", "source_name": "Szappanos MgBot 2014", "url": "https://www.virusbulletin.com/virusbulletin/2014/02/needle-haystack"}, {"description": "Threat Hunter Team. (2024, July 23). Daggerfly: Espionage Group Makes Major Update to Toolset. Retrieved July 25, 2024.", "source_name": "Symantec Daggerfly 2024", "url": "https://symantec-enterprise-blogs.security.com/threat-intelligence/daggerfly-espionage-updated-toolset"}], "id": "malware--a36eedea-9523-4abb-96e8-205f171ee763", "is_family": true, "modified": "2024-10-10T14:34:23.655Z", "name": "MgBot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MgBot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-997', 0, 161, '09-mitre-attack', 'retrieved', '6D764AD51652061CCD50247798667ACE334C71362F6B503C91D904E5E81DCE15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
