VALUES ('doc-09-mitre-attack-p0-999', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T22:40:58.386Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Kapeka is a backdoor written in C++ used against victims in Eastern Europe since at least mid-2022. Kapeka has technical overlaps with [Exaramel for Windows](https://attack.mitre.org/software/S0343) and [Prestige](https://attack.mitre.org/software/S1058) malware variants, both of which are linked to [Sandworm Team](https://attack.mitre.org/groups/G0034). Kapeka may have been used in advance of [Prestige](https://attack.mitre.org/software/S1058) deployment in late 2022.(Citation: WithSecure Kapeka 2024)(Citation: Microsoft KnuckleTouch 2024)", "external_references": [{"external_id": "S1190", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1190"}, {"description": "(Citation: Microsoft KnuckleTouch 2024)", "source_name": "KnuckleTouch"}, {"description": "Microsoft. (2024, February 14). Backdoor:Win64/KnuckleTouch.A!dha. Retrieved January 6, 2025.", "source_name": "Microsoft KnuckleTouch 2024", "url": "https://www.microsoft.com/en-us/wdsi/threats/malware-encyclopedia-description?Name=Backdoor:Win64/KnuckleTouch.A!dha&threatId=-2147067254"}, {"description": "Mohammad Kazem Hassan Nejad, WithSecure. (2024, April 17). KAPEKA A novel backdoor spotted in Eastern Europe. Retrieved January 6, 2025.", "source_name": "WithSecure Kapeka 2024", "url": "https://labs.withsecure.com/content/dam/labs/docs/WithSecure-Research-Kapeka.pdf"}], "id": "malware--a43e55c9-0b7c-42c0-81de-b7a42d724db9", "is_family": true, "modified": "2025-03-11T13:11:41.929Z", "name": "Kapeka", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kapeka", "KnuckleTouch"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-999', 0, 149, '09-mitre-attack', 'retrieved', 'B3C2FE52C41C4E68413CCA9175F5CFEF14CC7E711702C5AFF20007432BCF83D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
