VALUES ('doc-09-mitre-attack-p0-1000', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-24T22:09:44.468Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 2.0](https://attack.mitre.org/software/S1199) is an affiliate-based Ransomware-as-a-Service (RaaS) that has been in use since at least June 2021 as the successor to LockBit Ransomware. [LockBit 2.0](https://attack.mitre.org/software/S1199) has versions capable of infecting Windows and VMware ESXi virtual machines, and has been observed targeting multiple industry verticals globally.(Citation: FBI Lockbit 2.0 FEB 2022)(Citation: Palo Alto Lockbit 2.0 JUN 2022)", "external_references": [{"external_id": "S1199", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1199"}, {"description": "Elsad, A. et al. (2022, June 9). LockBit 2.0: How This RaaS Operates and How to Protect Against It. Retrieved January 24, 2025.", "source_name": "Palo Alto Lockbit 2.0 JUN 2022", "url": "https://unit42.paloaltonetworks.com/lockbit-2-ransomware/"}, {"description": "FBI. (2022, February 4). Indicators of Compromise Associated with LockBit 2.0 Ransomware. Retrieved January 24, 2025.", "source_name": "FBI Lockbit 2.0 FEB 2022", "url": "https://www.ic3.gov/CSA/2022/220204.pdf"}], "id": "malware--a4578560-42cf-4075-9fa2-056f0058c881", "is_family": true, "modified": "2025-10-21T17:57:24.341Z", "name": "LockBit 2.0", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LockBit 2.0"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1000', 0, 158, '09-mitre-attack', 'retrieved', 'D65C34A558BFA4FFF950D02E6CE723B9DFB403AB9CA86E3A0526C5CDE8AE8E9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
