VALUES ('doc-09-mitre-attack-p0-1001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-26T20:37:42.040Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OilCheck](https://attack.mitre.org/software/S1171) is a C#/.NET downloader that has been used by [OilRig](https://attack.mitre.org/groups/G0049) since at least 2022 including against targets in Israel. [OilCheck](https://attack.mitre.org/software/S1171) uses draft messages created in a shared email account for C2 communication.(Citation: ESET OilRig Downloaders DEC 2023)", "external_references": [{"external_id": "S1171", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1171"}, {"description": "Hromcova, Z. and Burgher, A. (2023, December 14). OilRig’s persistent attacks using cloud service-powered downloaders. Retrieved November 26, 2024.", "source_name": "ESET OilRig Downloaders DEC 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrig-persistent-attacks-cloud-service-powered-downloaders/"}], "id": "malware--a49725db-4a55-44cd-aefa-78b35d2d8641", "is_family": true, "modified": "2024-11-27T19:47:36.502Z", "name": "OilCheck", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OilCheck"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1001', 0, 108, '09-mitre-attack', 'retrieved', 'CEF624BDC5F809E6DABC98A5AD916C31AF5DC36C6BE7F6869CF805CC58BB9E88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
