VALUES ('doc-09-mitre-attack-p0-1002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zebrocy](https://attack.mitre.org/software/S0251) is a Trojan that has been used by [APT28](https://attack.mitre.org/groups/G0007) since at least November 2015. The malware comes in several programming language variants, including C++, Delphi, AutoIt, C#, VB.NET, and Golang. (Citation: Palo Alto Sofacy 06-2018)(Citation: Unit42 Cannon Nov 2018)(Citation: Unit42 Sofacy Dec 2018)(Citation: CISA Zebrocy Oct 2020) ", "external_references": [{"external_id": "S0251", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0251"}, {"description": "(Citation: CyberScoop APT28 Nov 2018)(Citation: Accenture SNAKEMACKEREL Nov 2018)", "source_name": "Zekapab"}, {"description": "(Citation: Palo Alto Sofacy 06-2018)(Citation: Unit42 Cannon Nov 2018)", "source_name": "Zebrocy"}, {"description": "Accenture Security. (2018, November 29). SNAKEMACKEREL. Retrieved April 15, 2019.", "source_name": "Accenture SNAKEMACKEREL Nov 2018", "url": "https://www.accenture.com/t20181129T203820Z__w__/us-en/_acnmedia/PDF-90/Accenture-snakemackerel-delivers-zekapab-malware.pdf#zoom=50"}, {"description": "CISA. (2020, October 29). Malware Analysis Report (AR20-303B). Retrieved December 9, 2020.", "source_name": "CISA Zebrocy Oct 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-303b"}, {"description": "Falcone, R., Lee, B. (2018, November 20). Sofacy Continues Global Attacks and Wheels Out New ‘Cannon’ Trojan. Retrieved November 26, 2018.", "source_name": "Unit42 Cannon Nov 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/11/unit42-sofacy-continues-global-attacks-wheels-new-cannon-trojan/"}, {"description": "Lee, B., Falcone, R. (2018, December 12). Dear Joohn: The Sofacy Group’s Global Campaign. Retrieved April 19, 2019.", "source_name": "Unit42 Sofacy Dec 2018", "url": "https://unit42.paloaltonetworks.com/dear-joohn-sofacy-groups-global-campaign/"}, {"description": "Lee, B., Falcone, R. (2018, June 06). Sofacy Group’s Parallel Attacks. Retrieved June 18, 2018.", "source_name": "Palo Alto Sofacy 06-2018", "url": "https://researchcenter.paloaltonetworks.com/2018/06/unit42-sofacy-groups-parallel-attacks/"}, {"description": "Shoorbajee, Z. (2018, November 29). Accenture: Russian hackers using Brexit talks to disguise phishing lures. Retrieved July 16, 2019.", "source_name": "CyberScoop APT28 Nov 2018", "url": "https://www.cyberscoop.com/apt28-brexit-phishing-accenture/"}], "id": "malware--a4f57468-fbd5-49e4-8476-52088220b92d", "is_family": true, "modified": "2025-10-22T02:49:35.030Z", "name": "Zebrocy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Zebrocy", "Zekapab"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Emily Ratliff, IBM"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "3.1"}', 'kb-doc-09-mitre-attack-p0-1002', 0, 263, '09-mitre-attack', 'retrieved', '37F36A5608FA841AB8C3778F9A92C9F2C45EF539D3D4BC5D6B57124BBBF1E25E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
