VALUES ('doc-09-mitre-attack-p0-1003', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-29T19:53:06.360Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pandora](https://attack.mitre.org/software/S0664) is a multistage kernel rootkit with backdoor functionality that has been in use by [Threat Group-3390](https://attack.mitre.org/groups/G0027) since at least 2020.(Citation: Trend Micro Iron Tiger April 2021)", "external_references": [{"external_id": "S0664", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0664"}, {"description": "Lunghi, D. and Lu, K. (2021, April 9). Iron Tiger APT Updates Toolkit With Evolved SysUpdate Malware. Retrieved November 12, 2021.", "source_name": "Trend Micro Iron Tiger April 2021", "url": "https://www.trendmicro.com/en_us/research/21/d/iron-tiger-apt-updates-toolkit-with-evolved-sysupdate-malware-va.html"}], "id": "malware--a545456a-f9a7-47ad-9ea6-8b017def38d1", "is_family": true, "modified": "2025-04-16T20:38:28.723Z", "name": "Pandora", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pandora"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1003', 0, 100, '09-mitre-attack', 'retrieved', '3AC91DB9F2E970535DFF22C1158F3C8D1576B35277D1B1F0892D8DB7A00DCF4D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
