VALUES ('doc-09-mitre-attack-p0-1005', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-17T18:43:36.156Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SpeakUp](https://attack.mitre.org/software/S0374) is a Trojan backdoor that targets both Linux and OSX devices. It was first observed in January 2019. (Citation: CheckPoint SpeakUp Feb 2019)", "external_references": [{"external_id": "S0374", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0374"}, {"description": "Check Point Research. (2019, February 4). SpeakUp: A New Undetected Backdoor Linux Trojan. Retrieved April 17, 2019.", "source_name": "CheckPoint SpeakUp Feb 2019", "url": "https://research.checkpoint.com/speakup-a-new-undetected-backdoor-linux-trojan/"}], "id": "malware--a5575606-9b85-4e3d-9cd2-40ef30e3672d", "is_family": true, "modified": "2024-04-11T00:02:59.341Z", "name": "SpeakUp", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SpeakUp"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1005', 0, 92, '09-mitre-attack', 'retrieved', '58CB42D9243619476E00EE8D113F127E322B7D5A579D16CA61CB44C853168BD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
