VALUES ('doc-09-mitre-attack-p0-1006', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-26T20:21:21.137Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarMail](https://attack.mitre.org/software/S1142) is a backdoor that has been used by [Turla](https://attack.mitre.org/groups/G0010) since at least 2020 including in a compromise of a European ministry of foreign affairs (MFA) in conjunction with [LunarLoader](https://attack.mitre.org/software/S1143) and [LunarWeb](https://attack.mitre.org/software/S1141). [LunarMail](https://attack.mitre.org/software/S1142) is designed to be deployed on workstations and can use email messages and [Steganography](https://attack.mitre.org/techniques/T1001/002) in command and control.(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"external_id": "S1142", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1142"}, {"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "malware--a5789a26-2b7b-4b2d-a25f-31182468d4bb", "is_family": true, "modified": "2024-08-16T14:42:54.472Z", "name": "LunarMail", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LunarMail"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Riku Katsuse, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1006', 0, 143, '09-mitre-attack', 'retrieved', '05732F8682697E69935F9ADD9C4B736803E6E698E9039D628FC16A1EDE48BFB2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
