VALUES ('doc-09-mitre-attack-p0-1008', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CrossRAT](https://attack.mitre.org/software/S0235) is a cross platform RAT.", "external_references": [{"external_id": "S0235", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0235"}, {"description": "(Citation: Lookout Dark Caracal Jan 2018)", "source_name": "CrossRAT"}, {"description": "Blaich, A., et al. (2018, January 18). Dark Caracal: Cyber-espionage at a Global Scale. Retrieved April 11, 2018.", "source_name": "Lookout Dark Caracal Jan 2018", "url": "https://info.lookout.com/rs/051-ESQ-475/images/Lookout_Dark-Caracal_srr_20180118_us_v.1.0.pdf"}], "id": "malware--a5e91d50-24fa-44ec-9894-39a88f658cea", "is_family": true, "modified": "2023-09-28T21:03:22.526Z", "name": "CrossRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CrossRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows", "macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1008', 0, 86, '09-mitre-attack', 'retrieved', '0171D45FE59044A4C9528A7CAE2275B951F2AB9F72EEEC7E5B7F24A9D8860301', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
