VALUES ('doc-09-mitre-attack-p0-1009', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:47.412Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OwaAuth](https://attack.mitre.org/software/S0072) is a Web shell and credential stealer deployed to Microsoft Exchange servers that appears to be exclusively used by [Threat Group-3390](https://attack.mitre.org/groups/G0027). (Citation: Dell TG-3390)", "external_references": [{"external_id": "S0072", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0072"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}], "id": "malware--a60657fa-e2e7-4f8f-8128-a882534ae8c5", "is_family": true, "modified": "2025-04-25T14:44:19.163Z", "name": "OwaAuth", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OwaAuth"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1009', 0, 91, '09-mitre-attack', 'retrieved', '34B081506FAD5F4D281A8870277038182C23F3318A9B5B61296E3844B80E124D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
