VALUES ('doc-09-mitre-attack-p0-1010', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-22T20:07:15.628Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cadelspy](https://attack.mitre.org/software/S0454) is a backdoor that has been used by [APT39](https://attack.mitre.org/groups/G0087).(Citation: Symantec Chafer Dec 2015)", "external_references": [{"external_id": "S0454", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0454"}, {"description": "Symantec Security Response. (2015, December 7). Iran-based attackers use back door threats to spy on Middle Eastern targets. Retrieved April 17, 2019.", "source_name": "Symantec Chafer Dec 2015", "url": "https://www.symantec.com/connect/blogs/iran-based-attackers-use-back-door-threats-spy-middle-eastern-targets"}], "id": "malware--a705b085-1eae-455e-8f4d-842483d814eb", "is_family": true, "modified": "2025-04-25T14:44:19.544Z", "name": "Cadelspy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cadelspy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1010', 0, 84, '09-mitre-attack', 'retrieved', 'C93DE7B20530F9C4F8767AAAF731A02C8EDA6F019938C4D58D91C7CA4572D2C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
