VALUES ('doc-09-mitre-attack-p0-1012', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-25T19:14:25.846Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SampleCheck5000](https://attack.mitre.org/software/S1168) is a downloader with multiple variants that was used by [OilRig](https://attack.mitre.org/groups/G0049) including during the [Outer Space](https://attack.mitre.org/campaigns/C0042) campaign to download and execute additional payloads. (Citation: ESET OilRig Campaigns Sep 2023)(Citation: ESET OilRig Downloaders DEC 2023)", "external_references": [{"external_id": "S1168", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1168"}, {"description": "(Citation: ESET OilRig Campaigns Sep 2023)", "source_name": "SC5k"}, {"description": "Hromcova, Z. and Burgher, A. (2023, December 14). OilRig’s persistent attacks using cloud service-powered downloaders. Retrieved November 26, 2024.", "source_name": "ESET OilRig Downloaders DEC 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrig-persistent-attacks-cloud-service-powered-downloaders/"}, {"description": "Hromcova, Z. and Burgher, A. (2023, September 21). OilRig’s Outer Space and Juicy Mix: Same ol’ rig, new drill pipes. Retrieved November 21, 2024.", "source_name": "ESET OilRig Campaigns Sep 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrigs-outer-space-juicy-mix-same-ol-rig-new-drill-pipes/"}], "id": "malware--a87c8100-8735-440e-8ee4-27aabb643592", "is_family": true, "modified": "2025-10-22T03:12:00.816Z", "name": "SampleCheck5000", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SampleCheck5000", "SC5k"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1012', 0, 148, '09-mitre-attack', 'retrieved', '35B7C8151A5A2914D27512BC1AD8B0E69BC7A05118409AA75AC6AF68563367C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
