VALUES ('doc-09-mitre-attack-p0-1014', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-28T17:40:32.217Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[EvilBunny](https://attack.mitre.org/software/S0396) is a C++ malware sample observed since 2011 that was designed to be a execution platform for Lua scripts.(Citation: Cyphort EvilBunny Dec 2014)", "external_references": [{"external_id": "S0396", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0396"}, {"description": "(Citation: Cyphort EvilBunny Dec 2014)", "source_name": "EvilBunny"}, {"description": "Marschalek, M.. (2014, December 16). EvilBunny: Malware Instrumented By Lua. Retrieved June 28, 2019.", "source_name": "Cyphort EvilBunny Dec 2014", "url": "https://web.archive.org/web/20150311013500/http://www.cyphort.com/evilbunny-malware-instrumented-lua/"}], "id": "malware--a8a778f5-0035-4870-bb25-53dc05029586", "is_family": true, "modified": "2024-08-05T18:21:34.265Z", "name": "EvilBunny", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["EvilBunny"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1014', 0, 98, '09-mitre-attack', 'retrieved', '9E3D993E654424669DE1AFEE00455B3A86BD1B85CA843897C20F517404EB4186', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
