VALUES ('doc-09-mitre-attack-p0-1016', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:40:37.350Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobian RAT](https://attack.mitre.org/software/S0338) is a backdoor, remote access tool that has been observed since 2016.(Citation: Zscaler Cobian Aug 2017)", "external_references": [{"external_id": "S0338", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0338"}, {"description": "(Citation: Zscaler Cobain Aug 2017)", "source_name": "Cobian RAT"}, {"description": "Yadav, A., et al. (2017, August 31). Cobian RAT – A backdoored RAT. Retrieved November 13, 2018.", "source_name": "Zscaler Cobian Aug 2017", "url": "https://www.zscaler.com/blogs/research/cobian-rat-backdoored-rat"}], "id": "malware--aa1462a1-d065-416c-b354-bedd04998c7f", "is_family": true, "modified": "2025-04-25T14:44:21.097Z", "name": "Cobian RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cobian RAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1016', 0, 94, '09-mitre-attack', 'retrieved', '15BD1504344468016F984C59449B27FCFAE991EE9AF55BA5F5BA03E78299BCBC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
