VALUES ('doc-09-mitre-attack-p0-1017', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-01T19:10:31.446Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HotCroissant](https://attack.mitre.org/software/S0431) is a remote access trojan (RAT) attributed by U.S. government entities to malicious North Korean government cyber activity, tracked collectively as HIDDEN COBRA.(Citation: US-CERT HOTCROISSANT February 2020) [HotCroissant](https://attack.mitre.org/software/S0431) shares numerous code similarities with [Rifdoor](https://attack.mitre.org/software/S0433).(Citation: Carbon Black HotCroissant April 2020)", "external_references": [{"external_id": "S0431", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0431"}, {"description": "Knight, S.. (2020, April 16). VMware Carbon Black TAU Threat Analysis: The Evolution of Lazarus. Retrieved May 1, 2020.", "source_name": "Carbon Black HotCroissant April 2020", "url": "https://www.carbonblack.com/2020/04/16/vmware-carbon-black-tau-threat-analysis-the-evolution-of-lazarus/"}, {"description": "US-CERT. (2020, February 20). MAR-10271944-1.v1 – North Korean Trojan: HOTCROISSANT. Retrieved May 1, 2020.", "source_name": "US-CERT HOTCROISSANT February 2020", "url": "https://www.us-cert.gov/ncas/analysis-reports/ar20-045d"}], "id": "malware--aad11e34-02ca-4220-91cd-2ed420af4db3", "is_family": true, "modified": "2024-04-11T02:17:38.807Z", "name": "HotCroissant", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HotCroissant"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1017', 0, 132, '09-mitre-attack', 'retrieved', 'B66939E6429B399748244DD2F1F77A5816D7B0A23DD60A0D224CE1F98F0773E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
