VALUES ('doc-09-mitre-attack-p0-1018', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-29T13:14:38.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ServHelper](https://attack.mitre.org/software/S0382) is a backdoor first observed in late 2018. The backdoor is written in Delphi and is typically delivered as a DLL file.(Citation: Proofpoint TA505 Jan 2019)", "external_references": [{"external_id": "S0382", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0382"}, {"description": "Schwarz, D. and Proofpoint Staff. (2019, January 9). ServHelper and FlawedGrace - New malware introduced by TA505. Retrieved May 28, 2019.", "source_name": "Proofpoint TA505 Jan 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/servhelper-and-flawedgrace-new-malware-introduced-ta505"}], "id": "malware--aae22730-e571-4d17-b037-65f2a3e26213", "is_family": true, "modified": "2025-04-16T20:38:29.531Z", "name": "ServHelper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ServHelper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1018', 0, 98, '09-mitre-attack', 'retrieved', 'DE9D1CF8DA4E61B37823C4D20A45813445C31C6389564BAA616D7A99F309B9FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
