VALUES ('doc-09-mitre-attack-p0-1019', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-18T17:20:43.635Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[JCry](https://attack.mitre.org/software/S0389) is ransomware written in Go. It was identified as apart of the #OpJerusalem 2019 campaign.(Citation: Carbon Black JCry May 2019)", "external_references": [{"external_id": "S0389", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0389"}, {"description": "(Citation: Carbon Black JCry May 2019)", "source_name": "JCry"}, {"description": "Lee, S.. (2019, May 14). JCry Ransomware. Retrieved June 18, 2019.", "source_name": "Carbon Black JCry May 2019", "url": "https://www.carbonblack.com/2019/05/14/cb-tau-threat-intelligence-notification-jcry-ransomware-pretends-to-be-adobe-flash-player-update-installer/"}], "id": "malware--aaf3fa65-8b27-4e68-91de-2b7738fe4c82", "is_family": true, "modified": "2025-04-25T14:44:21.898Z", "name": "JCry", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["JCry"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1019', 0, 88, '09-mitre-attack', 'retrieved', 'D0A96F22025B7781FE7E91F39572ED885978D0313707C2885AB2B3BB06092D02', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
