VALUES ('doc-09-mitre-attack-p0-1020', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:15.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Unknown Logger](https://attack.mitre.org/software/S0130) is a publicly released, free backdoor. Version 1.5 of the backdoor has been used by the actors responsible for the MONSOON campaign. (Citation: Forcepoint Monsoon)", "external_references": [{"external_id": "S0130", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0130"}, {"description": "Settle, A., et al. (2016, August 8). MONSOON - Analysis Of An APT Campaign. Retrieved September 22, 2016.", "source_name": "Forcepoint Monsoon", "url": "https://www.forcepoint.com/sites/default/files/resources/files/forcepoint-security-labs-monsoon-analysis-report.pdf"}], "id": "malware--ab3580c8-8435-4117-aace-3d9fbe46aa56", "is_family": true, "modified": "2025-04-25T14:44:22.301Z", "name": "Unknown Logger", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Unknown Logger"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1020', 0, 93, '09-mitre-attack', 'retrieved', '625C3528EF2A8CCA988FFA8B24E2552DCD9D867757F8505E1E0F704C410F6869', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
