VALUES ('doc-09-mitre-attack-p0-1022', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:11.911Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RIPTIDE](https://attack.mitre.org/software/S0003) is a proxy-aware backdoor used by [APT12](https://attack.mitre.org/groups/G0005). (Citation: Moran 2014)", "external_references": [{"external_id": "S0003", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0003"}, {"description": "Moran, N., Oppenheim, M., Engle, S., & Wartell, R.. (2014, September 3). Darwin’s Favorite APT Group [Blog]. Retrieved November 12, 2014.", "source_name": "Moran 2014", "url": "https://www.fireeye.com/blog/threat-research/2014/09/darwins-favorite-apt-group-2.html"}], "id": "malware--ad4f146f-e3ec-444a-ba71-24bffd7f0f8e", "is_family": true, "modified": "2025-04-25T14:44:22.846Z", "name": "RIPTIDE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RIPTIDE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1022', 0, 78, '09-mitre-attack', 'retrieved', 'C7CCEC6998493C937852A50B042104503DE654FF6058515099F5F20B38848579', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
