VALUES ('doc-09-mitre-attack-p0-1023', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-19T17:11:54.854Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Valak](https://attack.mitre.org/software/S0476) is a multi-stage modular malware that can function as a standalone information stealer or downloader, first observed in 2019 targeting enterprises in the US and Germany.(Citation: Cybereason Valak May 2020)(Citation: Unit 42 Valak July 2020)", "external_references": [{"external_id": "S0476", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0476"}, {"description": "Duncan, B. (2020, July 24). Evolution of Valak, from Its Beginnings to Mass Distribution. Retrieved August 31, 2020.", "source_name": "Unit 42 Valak July 2020", "url": "https://unit42.paloaltonetworks.com/valak-evolution/"}, {"description": "Salem, E. et al. (2020, May 28). VALAK: MORE THAN MEETS THE EYE . Retrieved June 19, 2020.", "source_name": "Cybereason Valak May 2020", "url": "https://www.cybereason.com/blog/valak-more-than-meets-the-eye"}], "id": "malware--ade37ada-14af-4b44-b36c-210eec255d53", "is_family": true, "modified": "2025-04-16T20:38:30.200Z", "name": "Valak", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Valak"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Cybereason Nocturnus, @nocturnus"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1023', 0, 135, '09-mitre-attack', 'retrieved', '2940C80A3FE67EC2F6167B8599B3DACEDDA5AB8B0DD07987690CCCA0DE2CC265', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
