VALUES ('doc-09-mitre-attack-p0-1024', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-04T20:01:26.144Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Samurai](https://attack.mitre.org/software/S1099) is a passive backdoor that has been used by [ToddyCat](https://attack.mitre.org/groups/G1022) since at least 2020. [Samurai](https://attack.mitre.org/software/S1099) allows arbitrary C# code execution and is used with multiple modules for remote administration and lateral movement.(Citation: Kaspersky ToddyCat June 2022)", "external_references": [{"external_id": "S1099", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1099"}, {"description": "Dedola, G. (2022, June 21). APT ToddyCat. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat June 2022", "url": "https://securelist.com/toddycat/106799/"}], "id": "malware--ae91fb8f-5031-4f57-9839-e3be3ed503f0", "is_family": true, "modified": "2024-01-04T20:02:49.672Z", "name": "Samurai", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Samurai"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1024', 0, 98, '09-mitre-attack', 'retrieved', 'C0A55D58BD7DA7185854FFE1846087BB11827B785B65BB1352C8EDC0B948EEC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
