VALUES ('doc-09-mitre-attack-p0-1025', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:35.780Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PinchDuke](https://attack.mitre.org/software/S0048) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2008 to 2010. (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0048", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0048"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--ae9d818d-95d0-41da-b045-9cabea1ca164", "is_family": true, "modified": "2025-04-25T14:44:24.120Z", "name": "PinchDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PinchDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1025', 0, 79, '09-mitre-attack', 'retrieved', '69DCCE348E0C38448B3D91964FAC9AAF19BDEB27A836F1011A0C6011B044706D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
