VALUES ('doc-09-mitre-attack-p0-1026', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-06T18:34:37.625Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Milan](https://attack.mitre.org/software/S1015) is a backdoor implant based on [DanBot](https://attack.mitre.org/software/S1014) that was written in Visual C++ and .NET. [Milan](https://attack.mitre.org/software/S1015) has been used by [HEXANE](https://attack.mitre.org/groups/G1001) since at least June 2020.(Citation: ClearSky Siamesekitten August 2021)(Citation: Kaspersky Lyceum October 2021)", "external_references": [{"external_id": "S1015", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1015"}, {"description": "(Citation: Accenture Lyceum Targets November 2021)", "source_name": "James"}, {"description": "Accenture. (2021, November 9). Who are latest targets of cyber group Lyceum?. Retrieved June 16, 2022.", "source_name": "Accenture Lyceum Targets November 2021", "url": "https://www.accenture.com/us-en/blogs/cyber-defense/iran-based-lyceum-campaigns"}, {"description": "ClearSky Cyber Security . (2021, August). New Iranian Espionage Campaign By “Siamesekitten” - Lyceum. Retrieved June 6, 2022.", "source_name": "ClearSky Siamesekitten August 2021", "url": "https://www.clearskysec.com/siamesekitten/"}, {"description": "Kayal, A. et al. (2021, October). LYCEUM REBORN: COUNTERINTELLIGENCE IN THE MIDDLE EAST. Retrieved June 14, 2022.", "source_name": "Kaspersky Lyceum October 2021", "url": "https://vblocalhost.com/uploads/VB2021-Kayal-etal.pdf"}], "id": "malware--aea6d6b8-d832-4c90-a1bb-f52c6684db6c", "is_family": true, "modified": "2024-04-11T00:43:16.261Z", "name": "Milan", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Milan", "James"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1026', 0, 163, '09-mitre-attack', 'retrieved', '51785747B4B1CB5B7F4EE9ABA4DBB02A0FE56A1F174B635D08B4B6206B72D4A6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
