VALUES ('doc-09-mitre-attack-p0-1029', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-26T21:02:40.104Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OilBooster](https://attack.mitre.org/software/S1172) is a downloader written in Microsoft Visual C/C++ that has been used by [OilRig](https://attack.mitre.org/groups/G0049) since at least 2022 including against target organizations in Israel to download and execute files and for exfiltration.(Citation: ESET OilRig Downloaders DEC 2023) ", "external_references": [{"external_id": "S1172", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1172"}, {"description": "Hromcova, Z. and Burgher, A. (2023, December 14). OilRig’s persistent attacks using cloud service-powered downloaders. Retrieved November 26, 2024.", "source_name": "ESET OilRig Downloaders DEC 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrig-persistent-attacks-cloud-service-powered-downloaders/"}], "id": "malware--b0381480-d5ba-4dd8-a39e-fb8f1afea3a0", "is_family": true, "modified": "2024-11-27T19:43:37.942Z", "name": "OilBooster", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OilBooster"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1029', 0, 109, '09-mitre-attack', 'retrieved', '7140EF9E769055A8E2ACB3E44FDBEF88B468280382B1EEDD9CC0F8BDB670F21B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
