VALUES ('doc-09-mitre-attack-p0-1031', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:37.341Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OnionDuke](https://attack.mitre.org/software/S0052) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2013 to 2015. (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0052", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0052"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--b136d088-a829-432c-ac26-5529c26d4c7e", "is_family": true, "modified": "2025-04-25T14:44:25.559Z", "name": "OnionDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OnionDuke"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1031', 0, 79, '09-mitre-attack', 'retrieved', '6DC463E406A0547EDC5D37FA1E93ECEDF7B3A50A3614E252584747A17BE16A23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
