VALUES ('doc-09-mitre-attack-p0-1032', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:14.900Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Taidoor](https://attack.mitre.org/software/S0011) is a remote access trojan (RAT) that has been used by Chinese government cyber actors to maintain access on victim networks.(Citation: CISA MAR-10292089-1.v2 TAIDOOR August 2021) [Taidoor](https://attack.mitre.org/software/S0011) has primarily been used against Taiwanese government organizations since at least 2010.(Citation: TrendMicro Taidoor)", "external_references": [{"external_id": "S0011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0011"}, {"description": "CISA, FBI, DOD. (2021, August). MAR-10292089-1.v2 – Chinese Remote Access Trojan: TAIDOOR. Retrieved August 24, 2021.", "source_name": "CISA MAR-10292089-1.v2 TAIDOOR August 2021", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-216a"}, {"description": "Trend Micro. (2012). The Taidoor Campaign. Retrieved November 12, 2014.", "source_name": "TrendMicro Taidoor", "url": "http://www.trendmicro.com/cloud-content/us/pdfs/security-intelligence/white-papers/wp_the_taidoor_campaign.pdf"}], "id": "malware--b143dfa4-e944-43ff-8429-bfffc308c517", "is_family": true, "modified": "2024-04-10T22:36:03.362Z", "name": "Taidoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Taidoor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-1032', 0, 125, '09-mitre-attack', 'retrieved', '82820AD6BAB8C2D5790D6CDEB7CC4B976A9BC5C74FE4B81A1BB97476719F968D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
