VALUES ('doc-09-mitre-attack-p0-1034', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:05.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cherry Picker](https://attack.mitre.org/software/S0107) is a point of sale (PoS) memory scraper. (Citation: Trustwave Cherry Picker)", "external_references": [{"external_id": "S0107", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0107"}, {"description": "Merritt, E.. (2015, November 16). Shining the Spotlight on Cherry Picker PoS Malware. Retrieved April 20, 2016.", "source_name": "Trustwave Cherry Picker", "url": "https://www.trustwave.com/Resources/SpiderLabs-Blog/Shining-the-Spotlight-on-Cherry-Picker-PoS-Malware/"}], "id": "malware--b2203c59-4089-4ee4-bfe1-28fa25f0dbfe", "is_family": true, "modified": "2025-04-25T14:44:26.291Z", "name": "Cherry Picker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cherry Picker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1034', 0, 80, '09-mitre-attack', 'retrieved', '1F5358F2C4BAD90FAD44542C815B384EB28422D12F84690B856D74D43F263957', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
