VALUES ('doc-09-mitre-attack-p0-1035', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-18T17:35:13.361Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUPERNOVA](https://attack.mitre.org/software/S0578) is an in-memory web shell written in .NET C#. It was discovered in November 2020 during the investigation of [APT29](https://attack.mitre.org/groups/G0016)''s SolarWinds cyber operation but determined to be unrelated. Subsequent analysis suggests [SUPERNOVA](https://attack.mitre.org/software/S0578) may have been used by the China-based threat group SPIRAL.(Citation: Guidepoint SUPERNOVA Dec 2020)(Citation: Unit42 SUPERNOVA Dec 2020)(Citation: SolarWinds Advisory Dec 2020)(Citation: CISA Supernova Jan 2021)(Citation: Microsoft Analyzing Solorigate Dec 2020)", "external_references": [{"external_id": "S0578", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0578"}, {"description": "CISA. (2021, January 27). Malware Analysis Report (AR21-027A). Retrieved February 22, 2021.", "source_name": "CISA Supernova Jan 2021", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar21-027a"}, {"description": "MSTIC. (2020, December 18). Analyzing Solorigate, the compromised DLL file that started a sophisticated cyberattack, and how Microsoft Defender helps protect customers . Retrieved January 5, 2021.", "source_name": "Microsoft Analyzing Solorigate Dec 2020", "url": "https://www.microsoft.com/security/blog/2020/12/18/analyzing-solorigate-the-compromised-dll-file-that-started-a-sophisticated-cyberattack-and-how-microsoft-defender-helps-protect/"}, {"description": "Riley, W. (2020, December 1). SUPERNOVA SolarWinds .NET Webshell Analysis. Retrieved February 18, 2021.", "source_name": "Guidepoint SUPERNOVA Dec 2020", "url": "https://www.guidepointsecurity.com/supernova-solarwinds-net-webshell-analysis/"}, {"description": "SolarWinds. (2020, December 24). SolarWinds Security Advisory. Retrieved February 22, 2021.", "source_name": "SolarWinds Advisory Dec 2020", "url": "https://www.solarwinds.com/sa-overview/securityadvisory"}, {"description": "Tennis, M. (2020, December 17). SUPERNOVA: A Novel .NET Webshell. Retrieved February 22, 2021.", "source_name": "Unit42 SUPERNOVA Dec 2020", "url": "https://unit42.paloaltonetworks.com/solarstorm-supernova/"}], "id": "malware--b2b0b946-be0a-4a7f-9c32-a2e5211d1cd9", "is_family": true, "modified": "2024-04-10T23:45:34.261Z", "name": "SUPERNOVA", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SUPERNOVA"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1035', 0, 225, '09-mitre-attack', 'retrieved', 'B27EE6E68AC01178F012F1EDE7A807F450B62B1698BB08DD6A5A7C527AE0837C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
