VALUES ('doc-09-mitre-attack-p0-1036', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:16.715Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[P2P ZeuS](https://attack.mitre.org/software/S0016) is a closed-source fork of the leaked version of the ZeuS botnet. It presents improvements over the leaked version, including a peer-to-peer architecture. (Citation: Dell P2P ZeuS)", "external_references": [{"external_id": "S0016", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0016"}, {"description": "SecureWorks. (2012). The Lifecycle of Peer-to-Peer (Gameover) ZeuS. Retrieved August 19, 2015.", "source_name": "Dell P2P ZeuS", "url": "https://www.secureworks.com/research/The-Lifecycle-of-Peer-to-Peer-Gameover-ZeuS"}], "id": "malware--b2c5d3ca-b43a-4888-ad8d-e2d43497bf85", "is_family": true, "modified": "2024-04-24T19:08:50.637Z", "name": "P2P ZeuS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["P2P ZeuS", "Peer-to-Peer ZeuS", "Gameover ZeuS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1036', 0, 96, '09-mitre-attack', 'retrieved', '9F68A23C44AD939AC60F71C1A9EC5FE191CB5D1BC209CA9804431CF274A97611', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
