VALUES ('doc-09-mitre-attack-p0-1037', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T18:10:59.143Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kivars](https://attack.mitre.org/software/S0437) is a modular remote access tool (RAT), derived from the Bifrost RAT, that was used by [BlackTech](https://attack.mitre.org/groups/G0098) in a 2010 campaign.(Citation: TrendMicro BlackTech June 2017)", "external_references": [{"external_id": "S0437", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0437"}, {"description": "Bermejo, L., et al. (2017, June 22). Following the Trail of BlackTech’s Cyber Espionage Campaigns. Retrieved May 5, 2020.", "source_name": "TrendMicro BlackTech June 2017", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/following-trail-blacktech-cyber-espionage-campaigns/"}], "id": "malware--b2d134a1-7bd5-4293-94d4-8fc978cb1cd7", "is_family": true, "modified": "2025-04-25T14:44:27.009Z", "name": "Kivars", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kivars"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1037', 0, 93, '09-mitre-attack', 'retrieved', '55C23D395011A12861C29B21C4534C6B6C0C8CF3F3E3D72FB3FA3C9F10C7E32A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
