VALUES ('doc-09-mitre-attack-p0-1038', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-23T20:15:38.177Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CaddyWiper](https://attack.mitre.org/software/S0693) is a destructive data wiper that has been used in attacks against organizations in Ukraine since at least March 2022.(Citation: ESET CaddyWiper March 2022)(Citation: Cisco CaddyWiper March 2022)", "external_references": [{"external_id": "S0693", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0693"}, {"description": "ESET. (2022, March 15). CaddyWiper: New wiper malware discovered in Ukraine. Retrieved March 23, 2022.", "source_name": "ESET CaddyWiper March 2022", "url": "https://www.welivesecurity.com/2022/03/15/caddywiper-new-wiper-malware-discovered-ukraine"}, {"description": "Malhotra, A. (2022, March 15). Threat Advisory: CaddyWiper. Retrieved March 23, 2022.", "source_name": "Cisco CaddyWiper March 2022", "url": "https://blog.talosintelligence.com/2022/03/threat-advisory-caddywiper.html"}], "id": "malware--b30d999d-64e0-4e35-9856-884e4b83d611", "is_family": true, "modified": "2024-04-17T15:09:37.646Z", "name": "CaddyWiper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CaddyWiper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1038', 0, 114, '09-mitre-attack', 'retrieved', '11321BA219A21E809E7E36E453746E94797E4A91C6AF45AFE0C9B3B5C9BED858', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
