VALUES ('doc-09-mitre-attack-p0-1039', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-03T15:37:41.440Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cyclops Blink](https://attack.mitre.org/software/S0687) is a modular malware that has been used in widespread campaigns by [Sandworm Team](https://attack.mitre.org/groups/G0034) since at least 2019 to target Small/Home Office (SOHO) network devices, including WatchGuard and Asus. [Cyclops Blink](https://attack.mitre.org/software/S0687) is assessed to be a replacement for [VPNFilter](https://attack.mitre.org/software/S1010), a similar platform targeting network devices.(Citation: NCSC Cyclops Blink February 2022)(Citation: NCSC CISA Cyclops Blink Advisory February 2022)(Citation: Trend Micro Cyclops Blink March 2022)", "external_references": [{"external_id": "S0687", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0687"}, {"description": "Haquebord, F. et al. (2022, March 17). Cyclops Blink Sets Sights on Asus Routers. Retrieved March 17, 2022.", "source_name": "Trend Micro Cyclops Blink March 2022", "url": "https://www.trendmicro.com/en_us/research/22/c/cyclops-blink-sets-sights-on-asus-routers--.html"}, {"description": "NCSC, CISA, FBI, NSA. (2022, February 23). New Sandworm malware Cyclops Blink replaces VPNFilter. Retrieved March 3, 2022.", "source_name": "NCSC CISA Cyclops Blink Advisory February 2022", "url": "https://www.ncsc.gov.uk/news/joint-advisory-shows-new-sandworm-malware-cyclops-blink-replaces-vpnfilter"}, {"description": "NCSC. (2022, February 23). Cyclops Blink Malware Analysis Report. Retrieved March 3, 2022.", "source_name": "NCSC Cyclops Blink February 2022", "url": "https://www.ncsc.gov.uk/files/Cyclops-Blink-Malware-Analysis-Report.pdf"}], "id": "malware--b350b47f-88fe-4921-8538-6d9c59bac84e", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "Cyclops Blink", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cyclops Blink"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1039', 0, 189, '09-mitre-attack', 'retrieved', 'ED3F6229D226A9D8717A45B9562AB4DDB57DD19667A3FED7CBD3138BEB84C9E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
