VALUES ('doc-09-mitre-attack-p0-1040', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:15.263Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PoisonIvy](https://attack.mitre.org/software/S0012) is a popular remote access tool (RAT) that has been used by many groups.(Citation: FireEye Poison Ivy)(Citation: Symantec Elderwood Sept 2012)(Citation: Symantec Darkmoon Aug 2005)", "external_references": [{"external_id": "S0012", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0012"}, {"description": "(Citation: FireEye Poison Ivy) (Citation: Symantec Darkmoon Sept 2014)", "source_name": "Poison Ivy"}, {"description": "(Citation: FireEye Poison Ivy)(Citation: Symantec Darkmoon Sept 2014)", "source_name": "PoisonIvy"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Breut"}, {"description": "(Citation: Symantec Darkmoon Sept 2014)", "source_name": "Darkmoon"}, {"description": "FireEye. (2014). POISON IVY: Assessing Damage and Extracting Intelligence. Retrieved September 19, 2024.", "source_name": "FireEye Poison Ivy", "url": "https://www.mandiant.com/sites/default/files/2021-09/rpt-poison-ivy.pdf"}, {"description": "Hayashi, K. (2005, August 18). Backdoor.Darkmoon. Retrieved February 23, 2018.", "source_name": "Symantec Darkmoon Aug 2005", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2005-081910-3934-99"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}, {"description": "Payet, L. (2014, September 19). Life on Mars: How attackers took advantage of hope for alien existance in new Darkmoon campaign. Retrieved September 13, 2018.", "source_name": "Symantec Darkmoon Sept 2014", "url": "https://www.symantec.com/connect/blogs/life-mars-how-attackers-took-advantage-hope-alien-existance-new-darkmoon-campaign"}], "id": "malware--b42378e0-f147-496f-992a-26a49705395b", "is_family": true, "modified": "2024-11-17T19:55:07.591Z", "name": "PoisonIvy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PoisonIvy", "Breut", "Poison Ivy", "Darkmoon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Darren Spruell"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-1040', 0, 224, '09-mitre-attack', 'retrieved', 'F3CD7891AFCFCFA964706F37719A27497209C12F5147F475449F2BC2BA39B194', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
