VALUES ('doc-09-mitre-attack-p0-1041', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T15:27:06.404Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Seasalt](https://attack.mitre.org/software/S0345) is malware that has been linked to [APT1](https://attack.mitre.org/groups/G0006)''s 2010 operations. It shares some code similarities with [OceanSalt](https://attack.mitre.org/software/S0346).(Citation: Mandiant APT1 Appendix)(Citation: McAfee Oceansalt Oct 2018)", "external_references": [{"external_id": "S0345", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0345"}, {"description": "(Citation: Mandiant APT1 Appendix)(Citation: McAfee Oceansalt Oct 2018)", "source_name": "Seasalt"}, {"description": "Mandiant. (n.d.). Appendix C (Digital) - The Malware Arsenal. Retrieved July 18, 2016.", "source_name": "Mandiant APT1 Appendix", "url": "https://www.mandiant.com/sites/default/files/2021-09/mandiant-apt1-report.pdf"}, {"description": "Sherstobitoff, R., Malhotra, A. (2018, October 18). ‘Operation Oceansalt’ Attacks South Korea, U.S., and Canada With Source Code From Chinese Hacker Group. Retrieved November 30, 2018.", "source_name": "McAfee Oceansalt Oct 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-oceansalt.pdf"}], "id": "malware--b45747dc-87ca-4597-a245-7e16a61bc491", "is_family": true, "modified": "2024-04-11T00:08:51.818Z", "name": "Seasalt", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Seasalt"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1041', 0, 132, '09-mitre-attack', 'retrieved', '52C481D64806DADADE6F2AC1554609E89CB6B2480C9B152998529AD745B4D60B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
