VALUES ('doc-09-mitre-attack-p0-1042', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-04T19:36:55.518Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NativeZone](https://attack.mitre.org/software/S0637) is the name given collectively to disposable custom [Cobalt Strike](https://attack.mitre.org/software/S0154) loaders used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2021.(Citation: MSTIC Nobelium Toolset May 2021)(Citation: SentinelOne NobleBaron June 2021)", "external_references": [{"external_id": "S0637", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0637"}, {"description": "MSTIC. (2021, May 28). Breaking down NOBELIUM’s latest early-stage toolset. Retrieved August 4, 2021.", "source_name": "MSTIC Nobelium Toolset May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/28/breaking-down-nobeliums-latest-early-stage-toolset/"}, {"description": "Guerrero-Saade, J. (2021, June 1). NobleBaron | New Poisoned Installers Could Be Used In Supply Chain Attacks. Retrieved August 4, 2021.", "source_name": "SentinelOne NobleBaron June 2021", "url": "https://labs.sentinelone.com/noblebaron-new-poisoned-installers-could-be-used-in-supply-chain-attacks/"}], "id": "malware--b4783be3-35d9-4a56-ac8d-1f3e1c9d9a84", "is_family": true, "modified": "2025-04-25T14:44:28.081Z", "name": "NativeZone", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NativeZone"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1042', 0, 120, '09-mitre-attack', 'retrieved', '02D58C075E7A15DF4E603995555D6CAFFE9227432D88CF04E216DCEC59F8CD5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
