VALUES ('doc-09-mitre-attack-p0-1044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-08T14:57:32.842Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TajMahal](https://attack.mitre.org/software/S0467) is a multifunctional spying framework that has been in use since at least 2014. [TajMahal](https://attack.mitre.org/software/S0467) is comprised of two separate packages, named Tokyo and Yokohama, and can deploy up to 80 plugins.(Citation: Kaspersky TajMahal April 2019)", "external_references": [{"external_id": "S0467", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0467"}, {"description": "GReAT. (2019, April 10). Project TajMahal – a sophisticated new APT framework. Retrieved October 14, 2019.", "source_name": "Kaspersky TajMahal April 2019", "url": "https://securelist.com/project-tajmahal/90240/"}], "id": "malware--b51797f7-57da-4210-b8ac-b8632ee75d70", "is_family": true, "modified": "2025-04-25T14:44:28.616Z", "name": "TajMahal", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TajMahal"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1044', 0, 101, '09-mitre-attack', 'retrieved', '128DE661A4115582D7DEDA1CF4DE2936F53F0FC455AC298BFE85B97540BD17A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
