VALUES ('doc-09-mitre-attack-p0-1045', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T12:55:10.969Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PLEAD](https://attack.mitre.org/software/S0435) is a remote access tool (RAT) and downloader used by [BlackTech](https://attack.mitre.org/groups/G0098) in targeted attacks in East Asia including Taiwan, Japan, and Hong Kong.(Citation: TrendMicro BlackTech June 2017)(Citation: JPCert PLEAD Downloader June 2018) [PLEAD](https://attack.mitre.org/software/S0435) has also been referred to as [TSCookie](https://attack.mitre.org/software/S0436), though more recent reporting indicates likely separation between the two. [PLEAD](https://attack.mitre.org/software/S0435) was observed in use as early as March 2017.(Citation: JPCert TSCookie March 2018)(Citation: JPCert PLEAD Downloader June 2018)", "external_references": [{"external_id": "S0435", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0435"}, {"description": "Alintanahin, K.. (2014, May 23). PLEAD Targeted Attacks Against Taiwanese Government Agencies. Retrieved April 22, 2019.", "source_name": "Trend Micro PLEAD RTLO", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/plead-targeted-attacks-against-taiwanese-government-agencies-2/"}, {"description": "Bermejo, L., et al. (2017, June 22). Following the Trail of BlackTech’s Cyber Espionage Campaigns. Retrieved May 5, 2020.", "source_name": "TrendMicro BlackTech June 2017", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/following-trail-blacktech-cyber-espionage-campaigns/"}, {"description": "PLEAD derived its name from letters used in backdoor commands in intrusion campaigns.(Citation: Trend Micro PLEAD RTLO)(Citation: TrendMicro BlackTech June 2017)", "source_name": "PLEAD"}, {"description": "Tomonaga, S. (2018, June 8). PLEAD Downloader Used by BlackTech. Retrieved May 6, 2020.", "source_name": "JPCert PLEAD Downloader June 2018", "url": "https://blogs.jpcert.or.jp/en/2018/03/malware-tscooki-7aa0.html"}, {"description": "Tomonaga, S. (2018, March 6). Malware “TSCookie”. Retrieved May 6, 2020.", "source_name": "JPCert TSCookie March 2018", "url": "https://blogs.jpcert.or.jp/en/2018/03/malware-tscooki-7aa0.html"}], "id": "malware--b57f419e-8b12-49d3-886b-145383725dcd", "is_family": true, "modified": "2025-04-25T19:04:32.446Z", "name": "PLEAD", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PLEAD"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Tatsuya Daitoku, Cyber Defense Institute, Inc.", "Hannah S"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1045', 0, 238, '09-mitre-attack', 'retrieved', 'A232250C4A4F609C2003997952A9E74E620D7D56F0AEDC09A964363FF281DC4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
