VALUES ('doc-09-mitre-attack-p0-1046', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-01T21:53:48.812Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raccoon Stealer](https://attack.mitre.org/software/S1148) is an information stealer malware family active since at least 2019 as a malware-as-a-service offering sold in underground forums. [Raccoon Stealer](https://attack.mitre.org/software/S1148) has experienced two periods of activity across two variants, from 2019 to March 2022, then resurfacing in a revised version in June 2022.(Citation: S2W Racoon 2022)(Citation: Sekoia Raccoon1 2022)", "external_references": [{"external_id": "S1148", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1148"}, {"description": "Quentin Bourgue, Pierre le Bourhis, & Sekoia TDR. (2022, June 28). Raccoon Stealer v2 - Part 1: The return of the dead. Retrieved August 1, 2024.", "source_name": "Sekoia Raccoon1 2022", "url": "https://blog.sekoia.io/raccoon-stealer-v2-part-1-the-return-of-the-dead/"}, {"description": "S2W TALON. (2022, June 16). Raccoon Stealer is Back with a New Version. Retrieved August 1, 2024.", "source_name": "S2W Racoon 2022", "url": "https://medium.com/s2wblog/raccoon-stealer-is-back-with-a-new-version-5f436e04b20d"}], "id": "malware--b5a8fb8b-4ff1-43e5-a1ad-75ae565f5175", "is_family": true, "modified": "2025-10-14T21:40:02.258Z", "name": "Raccoon Stealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Raccoon Stealer"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India", "Catherine Williams, BT Security", "Harry Hill, BT Security", "Yoshihiro Kori, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1046', 0, 176, '09-mitre-attack', 'retrieved', 'A4210A4CF148832311F024109CD39482B2E0EDA94AA6FAE3AA6CC0441C164CFC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
