VALUES ('doc-09-mitre-attack-p0-1048', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Daserf](https://attack.mitre.org/software/S0187) is a backdoor that has been used to spy on and steal from Japanese, South Korean, Russian, Singaporean, and Chinese victims. Researchers have identified versions written in both Visual C and Delphi. (Citation: Trend Micro Daserf Nov 2017) (Citation: Secureworks BRONZE BUTLER Oct 2017)", "external_references": [{"external_id": "S0187", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0187"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)", "source_name": "Daserf"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)", "source_name": "Muirim"}, {"description": "(Citation: Trend Micro Daserf Nov 2017)", "source_name": "Nioupale"}, {"description": "Chen, J. and Hsieh, M. (2017, November 7). REDBALDKNIGHT/BRONZE BUTLER’s Daserf Backdoor Now Using Steganography. Retrieved December 27, 2017.", "source_name": "Trend Micro Daserf Nov 2017", "url": "http://blog.trendmicro.com/trendlabs-security-intelligence/redbaldknight-bronze-butler-daserf-backdoor-now-using-steganography/"}, {"description": "Counter Threat Unit Research Team. (2017, October 12). BRONZE BUTLER Targets Japanese Enterprises. Retrieved January 4, 2018.", "source_name": "Secureworks BRONZE BUTLER Oct 2017", "url": "https://www.secureworks.com/research/bronze-butler-targets-japanese-businesses"}], "id": "malware--b6b3dfc7-9a81-43ff-ac04-698bad48973a", "is_family": true, "modified": "2025-04-25T14:44:29.509Z", "name": "Daserf", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Daserf", "Muirim", "Nioupale"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1048', 0, 168, '09-mitre-attack', 'retrieved', 'F6F52DD1FAF15465F9683E5F2CB5CC31B665550BD43226952515A61DD66BB904', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
