VALUES ('doc-09-mitre-attack-p0-1050', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T19:36:02.103Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Carbon](https://attack.mitre.org/software/S0335) is a sophisticated, second-stage backdoor and framework that can be used to steal sensitive information from victims. [Carbon](https://attack.mitre.org/software/S0335) has been selectively used by [Turla](https://attack.mitre.org/groups/G0010) to target government and foreign affairs-related organizations in Central Asia.(Citation: ESET Carbon Mar 2017)(Citation: Securelist Turla Oct 2018)", "external_references": [{"external_id": "S0335", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0335"}, {"description": "(Citation: ESET Carbon Mar 2017)(Citation: Securelist Turla Oct 2018)", "source_name": "Carbon"}, {"description": "ESET. (2017, March 30). Carbon Paper: Peering into Turla’s second stage backdoor. Retrieved November 7, 2018.", "source_name": "ESET Carbon Mar 2017", "url": "https://www.welivesecurity.com/2017/03/30/carbon-paper-peering-turlas-second-stage-backdoor/"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, October 04). Shedding Skin – Turla’s Fresh Faces. Retrieved November 7, 2018.", "source_name": "Securelist Turla Oct 2018", "url": "https://securelist.com/shedding-skin-turlas-fresh-faces/88069/"}], "id": "malware--b7e9880a-7a7c-4162-bddb-e28e8ef2bf1f", "is_family": true, "modified": "2025-04-25T14:44:30.048Z", "name": "Carbon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Carbon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1050', 0, 147, '09-mitre-attack', 'retrieved', '850510B4E450FC75FB7DFE4F165299C795730FE9F19F635EB188B258D556EBF8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
