VALUES ('doc-09-mitre-attack-p0-1051', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-14T12:48:16.344Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TRAILBLAZE](https://attack.mitre.org/software/S9012) is an in-memory dropper used to deploy the passive backdoor [BRUSHFIRE](https://attack.mitre.org/software/S9011). First reported in March 2025, TRAILBLAZE has been observed in operations attributed to People''s Republic of China (PRC) state-sponsored affiliated actors, including UNC5221 and SYLVANITE. (Citation: Dragos SYLVANITE MuddyWater Electrum March 2026)(Citation: Google UNC5221 Ivanti April 2025)(Citation: Picus Security UNC5221 Ivanti May 2025) ", "external_references": [{"external_id": "S9012", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9012"}, {"description": "Dragos. (2026, March 24). Dragos 2026 OT Cybersecurity Report: Year in Review, O&G and Petrochemicals Focus. Retrieved April 17, 2026.", "source_name": "Dragos SYLVANITE MuddyWater Electrum March 2026", "url": "https://hub.dragos.com/hubfs/2026_YIR_ExecutiveBriefing%20O_G.pdf?hsLang=en"}, {"description": "John Wolfram, Michael Edie, Jacob Thompson, Matt Lin, Josh Murchie. (2025, April 3). Suspected China-Nexus Threat Actor Actively Exploiting Critical Ivanti Connect Secure Vulnerability (CVE-2025-22457). Retrieved April 13, 2026.", "source_name": "Google UNC5221 Ivanti April 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-exploiting-critical-ivanti-vulnerability"}, {"description": "Sila Ozeren Hacioglu. (2025, May 5). UNC5221’s Latest Exploit: Weaponizing CVE-2025-22457 in Ivanti Connect Secure. Retrieved April 13, 2026.", "source_name": "Picus Security UNC5221 Ivanti May 2025", "url": "https://www.picussecurity.com/resource/blog/unc5221-cve-2025-22457-ivanti-connect-secure"}], "id": "malware--b82b9e25-e37b-4f7c-b1f0-2c2eea4f4be9", "is_family": true, "modified": "2026-04-23T01:59:00.751Z", "name": "TRAILBLAZE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TRAILBLAZE"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dragos Threat Intelligence"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1051', 0, 201, '09-mitre-attack', 'retrieved', '3DBBD20025D15970B482CE73B315BD53F198DAF779BCB95C4C3DD58BAEDC6DD1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
