VALUES ('doc-09-mitre-attack-p0-1052', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-02T12:58:09.598Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoJax](https://attack.mitre.org/software/S0397) is a UEFI rootkit used by [APT28](https://attack.mitre.org/groups/G0007) to persist remote access software on targeted systems.(Citation: ESET LoJax Sept 2018)", "external_references": [{"external_id": "S0397", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0397"}, {"description": "(Citation: ESET LoJax Sept 2018)", "source_name": "LoJax"}, {"description": "ESET. (2018, September). LOJAX First UEFI rootkit found in the wild, courtesy of the Sednit group. Retrieved July 2, 2019.", "source_name": "ESET LoJax Sept 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/09/ESET-LoJax.pdf"}], "id": "malware--b865dded-0553-4962-a44b-6fe7863effed", "is_family": true, "modified": "2025-04-25T14:44:30.421Z", "name": "LoJax", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LoJax"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jean-Ian Boutin, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1052', 0, 100, '09-mitre-attack', 'retrieved', '05D4FF1F7FF3402BF9CA5A544F6D79B637A0E557E3D55153690799961DCB143D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
