VALUES ('doc-09-mitre-attack-p0-1053', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T16:39:53.573Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cardinal RAT](https://attack.mitre.org/software/S0348) is a potentially low volume remote access trojan (RAT) observed since December 2015. [Cardinal RAT](https://attack.mitre.org/software/S0348) is notable for its unique utilization of uncompiled C# source code and the Microsoft Windows built-in csc.exe compiler.(Citation: PaloAlto CardinalRat Apr 2017)", "external_references": [{"external_id": "S0348", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0348"}, {"description": "(Citation: PaloAlto CardinalRat Apr 2017)", "source_name": "Cardinal RAT"}, {"description": "Grunzweig, J.. (2017, April 20). Cardinal RAT Active for Over Two Years. Retrieved December 8, 2018.", "source_name": "PaloAlto CardinalRat Apr 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/04/unit42-cardinal-rat-active-two-years/"}], "id": "malware--b879758f-bbc4-4cab-b5ba-177ac9b009b4", "is_family": true, "modified": "2024-04-11T02:47:11.431Z", "name": "Cardinal RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cardinal RAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1053', 0, 116, '09-mitre-attack', 'retrieved', '0C0A85FA583D1E1BEE0C944905E0E6220186787B05C687C21B6EB849B366DF43', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
