VALUES ('doc-09-mitre-attack-p0-1054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-03T14:35:23.246Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DanBot](https://attack.mitre.org/software/S1014) is a first-stage remote access Trojan written in C# that has been used by [HEXANE](https://attack.mitre.org/groups/G1001) since at least 2018.(Citation: SecureWorks August 2019)", "external_references": [{"external_id": "S1014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1014"}, {"description": "SecureWorks 2019, August 27 LYCEUM Takes Center Stage in Middle East Campaign Retrieved. 2019/11/19 ", "source_name": "SecureWorks August 2019", "url": "https://www.secureworks.com/blog/lyceum-takes-center-stage-in-middle-east-campaign"}], "id": "malware--b8d48deb-450c-44f6-a934-ac8765aa89cb", "is_family": true, "modified": "2024-04-11T02:42:34.540Z", "name": "DanBot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DanBot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1054', 0, 87, '09-mitre-attack', 'retrieved', '32FB11ABD208F9E23C6FB82F90D2EBF375158B3592EB77D0E921FA4E465E40E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
