VALUES ('doc-09-mitre-attack-p0-1055', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:17.147Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BISCUIT](https://attack.mitre.org/software/S0017) is a backdoor that has been used by [APT1](https://attack.mitre.org/groups/G0006) since as early as 2007. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0017", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0017"}, {"description": "(Citation: Mandiant APT1)(Citation: Mandiant APT1 Appendix)", "source_name": "BISCUIT"}, {"description": "Mandiant. (n.d.). Appendix C (Digital) - The Malware Arsenal. Retrieved July 18, 2016.", "source_name": "Mandiant APT1 Appendix", "url": "https://www.mandiant.com/sites/default/files/2021-09/mandiant-apt1-report.pdf"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "malware--b8eb28e4-48a6-40ae-951a-328714f75eda", "is_family": true, "modified": "2023-12-26T19:55:54.853Z", "name": "BISCUIT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BISCUIT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1055', 0, 109, '09-mitre-attack', 'retrieved', '0B2927D7709C54F65320F89A1DE54C5A71BD950377F8A7147D0617151F73E93B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
