VALUES ('doc-09-mitre-attack-p0-1056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Calisto](https://attack.mitre.org/software/S0274) is a macOS Trojan that opens a backdoor on the compromised machine. [Calisto](https://attack.mitre.org/software/S0274) is believed to have first been developed in 2016. (Citation: Securelist Calisto July 2018) (Citation: Symantec Calisto July 2018)", "external_references": [{"external_id": "S0274", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0274"}, {"description": "(Citation: Securelist Calisto July 2018) (Citation: Symantec Calisto July 2018)", "source_name": "Calisto"}, {"description": "Kuzin, M., Zelensky S. (2018, July 20). Calisto Trojan for macOS. Retrieved September 7, 2018.", "source_name": "Securelist Calisto July 2018", "url": "https://securelist.com/calisto-trojan-for-macos/86543/"}, {"description": "Pantig, J. (2018, July 30). OSX.Calisto. Retrieved September 7, 2018.", "source_name": "Symantec Calisto July 2018", "url": "https://web.archive.org/web/20190111082249/https://www.symantec.com/security-center/writeup/2018-073014-2512-99?om_rssid=sr-latestthreats30days"}], "id": "malware--b8fdef82-d2cf-4948-8949-6466357b1be1", "is_family": true, "modified": "2025-04-16T20:38:32.306Z", "name": "Calisto", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Calisto"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Cody Thomas, SpecterOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1056', 0, 133, '09-mitre-attack', 'retrieved', '06B90A28ED41C43305A397626155E21BA9E7E05628FE317301C8416A1401F2A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
