VALUES ('doc-09-mitre-attack-p0-1058', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:12.388Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pisloader](https://attack.mitre.org/software/S0124) is a malware family that is notable due to its use of DNS as a C2 protocol as well as its use of anti-analysis tactics. It has been used by [APT18](https://attack.mitre.org/groups/G0026) and is similar to another malware family, [HTTPBrowser](https://attack.mitre.org/software/S0070), that has been used by the group. (Citation: Palo Alto DNS Requests)", "external_references": [{"external_id": "S0124", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0124"}, {"description": "(Citation: Palo Alto DNS Requests)", "source_name": "Pisloader"}, {"description": "Grunzweig, J., et al. (2016, May 24). New Wekby Attacks Use DNS Requests As Command and Control Mechanism. Retrieved August 17, 2016.", "source_name": "Palo Alto DNS Requests", "url": "http://researchcenter.paloaltonetworks.com/2016/05/unit42-new-wekby-attacks-use-dns-requests-as-command-and-control-mechanism/"}], "id": "malware--b96680d1-5eb3-4f07-b95c-00ab904ac236", "is_family": true, "modified": "2025-04-25T14:44:31.662Z", "name": "Pisloader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pisloader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1058', 0, 130, '09-mitre-attack', 'retrieved', '6ED4E511D053C39F384C92B1E01F11FF38083F0DACEB89B551738F391C583521', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
