VALUES ('doc-09-mitre-attack-p0-1062', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-27T16:58:08.242Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ramsay](https://attack.mitre.org/software/S0458) is an information stealing malware framework designed to collect and exfiltrate sensitive documents, including from air-gapped systems. Researchers have identified overlaps between [Ramsay](https://attack.mitre.org/software/S0458) and the [Darkhotel](https://attack.mitre.org/groups/G0012)-associated Retro malware.(Citation: Eset Ramsay May 2020)(Citation: Antiy CERT Ramsay April 2020)", "external_references": [{"external_id": "S0458", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0458"}, {"description": "(Citation: Eset Ramsay May 2020)", "source_name": "Ramsay"}, {"description": "Antiy CERT. (2020, April 20). Analysis of Ramsay components of Darkhotel''s infiltration and isolation network. Retrieved March 24, 2021.", "source_name": "Antiy CERT Ramsay April 2020", "url": "https://www.programmersought.com/article/62493896999/"}, {"description": "Sanmillan, I.. (2020, May 13). Ramsay: A cyber‑espionage toolkit tailored for air‑gapped networks. Retrieved May 27, 2020.", "source_name": "Eset Ramsay May 2020", "url": "https://www.welivesecurity.com/2020/05/13/ramsay-cyberespionage-toolkit-airgapped-networks/"}], "id": "malware--ba09b86c-1c40-4ff1-bda0-0d8c4ca35997", "is_family": true, "modified": "2025-04-25T14:44:32.751Z", "name": "Ramsay", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ramsay"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Harry Kim, CODEMIZE"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1062', 0, 145, '09-mitre-attack', 'retrieved', '9977913750340A5F851B98DF7D2CC6F4E2664E37CCE7DEA9B4FCB78C6599997C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
