VALUES ('doc-09-mitre-attack-p0-1063', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T18:46:47.242Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Neo-reGeorg](https://attack.mitre.org/software/S1189) is an open-source web shell designed as a restructuring of [reGeorg](https://attack.mitre.org/software/S1187) with improved usability, security, and fixes for exising [reGeorg](https://attack.mitre.org/software/S1187) bugs.(Citation: GitHub Neo-reGeorg 2019)", "external_references": [{"external_id": "S1189", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1189"}, {"description": "L-Codes. (2019). Neo-reGeorg. Retrieved December 4, 2024.", "source_name": "GitHub Neo-reGeorg 2019", "url": "https://github.com/L-codes/Neo-reGeorg/blob/master/README-en.md"}], "id": "malware--bae6edd1-eb36-4581-ba7e-6cbfe0e24eac", "is_family": true, "modified": "2025-04-15T19:46:35.142Z", "name": "Neo-reGeorg", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Neo-reGeorg"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices", "Windows", "macOS", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1063', 0, 85, '09-mitre-attack', 'retrieved', 'D02D4D4616C840905FE1510ACCBE714B6E37971DF48D0EC1641639FF8418552F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
