VALUES ('doc-09-mitre-attack-p0-1064', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:52.470Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FakeM](https://attack.mitre.org/software/S0076) is a shellcode-based Windows backdoor that has been used by [Scarlet Mimic](https://attack.mitre.org/groups/G0029). (Citation: Scarlet Mimic Jan 2016)", "external_references": [{"external_id": "S0076", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0076"}, {"description": "Falcone, R. and Miller-Osborn, J.. (2016, January 24). Scarlet Mimic: Years-Long Espionage Campaign Targets Minority Activists. Retrieved February 10, 2016.", "source_name": "Scarlet Mimic Jan 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/01/scarlet-mimic-years-long-espionage-targets-minority-activists/"}], "id": "malware--bb3c1098-d654-4620-bf40-694386d28921", "is_family": true, "modified": "2025-04-25T14:44:33.289Z", "name": "FakeM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FakeM"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1064', 0, 86, '09-mitre-attack', 'retrieved', 'E8DD72D96C8E8828C6C0F44368DE7D8CB73FEA31E0F3FDDA2EB733E89905EC11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
