VALUES ('doc-09-mitre-attack-p0-1065', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T14:04:02.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AshTag](https://attack.mitre.org/software/S9031) is a modular .NET backdoor with multiple features that has been used by [WIRTE](https://attack.mitre.org/groups/G0090) since at least 2025. [AshTag](https://attack.mitre.org/software/S9031) is designed for persistence and remote command execution and can masquerade as a legitimate VisualServer utility.(Citation: Palo Alto Ashen Lepus DEC 2025)", "external_references": [{"external_id": "S9031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9031"}, {"description": "Unit 42. (2025, December 11). Hamas-Affiliated Ashen Lepus Targets Middle Eastern Diplomatic Entities With New AshTag Malware Suite. Retrieved April 20, 2026.", "source_name": "Palo Alto Ashen Lepus DEC 2025", "url": "https://unit42.paloaltonetworks.com/hamas-affiliate-ashen-lepus-uses-new-malware-suite-ashtag/"}], "id": "malware--bb6f2a5c-dbc9-45b0-bd3f-a0b7849959c2", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "AshTag", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AshTag"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1065', 0, 116, '09-mitre-attack', 'retrieved', 'F2AA02A3D6146CEA017CD820BF22E7A791179C787C9523881F512C4C6BE7CC88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
