VALUES ('doc-09-mitre-attack-p0-1066', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-15T19:48:35.063Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Carberp](https://attack.mitre.org/software/S0484) is a credential and information stealing malware that has been active since at least 2009. [Carberp](https://attack.mitre.org/software/S0484)''s source code was leaked online in 2013, and subsequently used as the foundation for the [Carbanak](https://attack.mitre.org/software/S0030) backdoor.(Citation: Trend Micro Carberp February 2014)(Citation: KasperskyCarbanak)(Citation: RSA Carbanak November 2017)", "external_references": [{"external_id": "S0484", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0484"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2015, February). CARBANAK APT THE GREAT BANK ROBBERY. Retrieved March 27, 2017.", "source_name": "KasperskyCarbanak", "url": "https://securelist.com/the-great-bank-robbery-the-carbanak-apt/68732/"}, {"description": "RSA. (2017, November 21). THE CARBANAK/FIN7 SYNDICATE A HISTORICAL OVERVIEW OF AN EVOLVING THREAT. Retrieved July 29, 2020.", "source_name": "RSA Carbanak November 2017", "url": "https://www.rsa.com/content/dam/en/white-paper/the-carbanak-fin7-syndicate.pdf"}, {"description": "Trend Micro. (2014, February 27). CARBERP. Retrieved July 29, 2020.", "source_name": "Trend Micro Carberp February 2014", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/carberp"}], "id": "malware--bbcd7a02-ef24-4171-ac94-a93540173b94", "is_family": true, "modified": "2024-04-11T02:47:56.829Z", "name": "Carberp", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Carberp"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1066', 0, 155, '09-mitre-attack', 'retrieved', '5A7D6F785814F942159722666D0953AB6F040148C110F5A127CF89A1E2307D39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
