VALUES ('doc-09-mitre-attack-p0-1069', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-08T15:41:33.284Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NKAbuse](https://attack.mitre.org/software/S1107) is a Go-based, multi-platform malware abusing NKN (New Kind of Network) technology for data exchange between peers, functioning as a potent implant, and equipped with both flooder and backdoor capabilities.(Citation: NKAbuse BC)(Citation: NKAbuse SL)", "external_references": [{"external_id": "S1107", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1107"}, {"description": "Bill Toulas. (2023, December 14). New NKAbuse malware abuses NKN blockchain for stealthy comms. Retrieved February 8, 2024.", "source_name": "NKAbuse BC", "url": "https://www.bleepingcomputer.com/news/security/new-nkabuse-malware-abuses-nkn-blockchain-for-stealthy-comms/#google_vignette"}, {"description": "KASPERSKY GERT. (2023, December 14). Unveiling NKAbuse: a new multiplatform threat abusing the NKN protocol. Retrieved February 8, 2024.", "source_name": "NKAbuse SL", "url": "https://securelist.com/unveiling-nkabuse/111512/"}], "id": "malware--bd2ebee8-7c38-408a-871d-221012104222", "is_family": true, "modified": "2024-04-13T14:10:23.936Z", "name": "NKAbuse", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NKAbuse"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1069', 0, 128, '09-mitre-attack', 'retrieved', 'BF4A56EA250409EC84EC6A7CC7D6BD0E7EACEC7384DA69F77F6DE125D31642F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "