VALUES ('doc-09-mitre-attack-p0-1070', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-27T14:06:29.560Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pillowmint](https://attack.mitre.org/software/S0517) is a point-of-sale malware used by [FIN7](https://attack.mitre.org/groups/G0046) designed to capture credit card information.(Citation: Trustwave Pillowmint June 2020)", "external_references": [{"external_id": "S0517", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0517"}, {"description": "Trustwave SpiderLabs. (2020, June 22). Pillowmint: FIN7’s Monkey Thief . Retrieved July 27, 2020.", "source_name": "Trustwave Pillowmint June 2020", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/pillowmint-fin7s-monkey-thief/"}], "id": "malware--bd7a9e13-69fa-4243-a5e5-04326a63f9f2", "is_family": true, "modified": "2025-04-16T20:38:33.297Z", "name": "Pillowmint", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pillowmint"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1070', 0, 82, '09-mitre-attack', 'retrieved', '4FE778EA01365334CE7DF19D566B5DE6E58FAC0702E0ACAB242C28A759DD3707', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
