VALUES ('doc-09-mitre-attack-p0-1071', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-08T15:38:55.209Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrailBlazer](https://attack.mitre.org/software/S0682) is a modular malware that has been used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2019.(Citation: CrowdStrike StellarParticle January 2022)", "external_references": [{"external_id": "S0682", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0682"}, {"description": "CrowdStrike. (2022, January 27). Early Bird Catches the Wormhole: Observations from the StellarParticle Campaign. Retrieved February 7, 2022.", "source_name": "CrowdStrike StellarParticle January 2022", "url": "https://www.crowdstrike.com/blog/observations-from-the-stellarparticle-campaign/"}], "id": "malware--bdad6f3b-de88-42fa-9295-d29b5271808e", "is_family": true, "modified": "2025-04-16T20:38:33.457Z", "name": "TrailBlazer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TrailBlazer"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1071', 0, 87, '09-mitre-attack', 'retrieved', 'D5F4A1492D4EACB8B22253FD0F2F17C529EAE7F5D5FD0FADE356823D79568EA3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
