VALUES ('doc-09-mitre-attack-p0-1072', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-02T01:07:36.780Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Revenge RAT](https://attack.mitre.org/software/S0379) is a freely available remote access tool written in .NET (C#).(Citation: Cylance Shaheen Nov 2018)(Citation: Cofense RevengeRAT Feb 2019)", "external_references": [{"external_id": "S0379", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0379"}, {"description": "Gannon, M. (2019, February 11). With Upgrades in Delivery and Support Infrastructure, Revenge RAT Malware is a Bigger Threat. Retrieved November 17, 2024.", "source_name": "Cofense RevengeRAT Feb 2019", "url": "https://web.archive.org/web/20200428173819/https://cofense.com/upgrades-delivery-support-infrastructure-revenge-rat-malware-bigger-threat/"}, {"description": "Livelli, K, et al. (2018, November 12). Operation Shaheen. Retrieved May 1, 2019.", "source_name": "Cylance Shaheen Nov 2018", "url": "https://www.cylance.com/content/dam/cylance-web/en-us/resources/knowledge-center/resource-library/reports/WhiteCompanyOperationShaheenReport.pdf?_ga=2.161661948.1943296560.1555683782-1066572390.1555511517"}], "id": "malware--bdb27a1d-1844-42f1-a0c0-826027ae0326", "is_family": true, "modified": "2024-11-17T23:54:41.761Z", "name": "Revenge RAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Revenge RAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1072', 0, 117, '09-mitre-attack', 'retrieved', '774C98976907F4BEEABF05F2517A4ADC2BA59D8EB8B596D21876D95C9707332D', 'v1', '{"source_id": "09-