VALUES ('doc-09-mitre-attack-p0-1073', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-06T01:29:34.860Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MacMa](https://attack.mitre.org/software/S1016) is a macOS-based backdoor with a large set of functionalities to control and exfiltrate files from a compromised computer. [MacMa](https://attack.mitre.org/software/S1016) has been observed in the wild since November 2021.(Citation: ESET DazzleSpy Jan 2022) [MacMa](https://attack.mitre.org/software/S1016) shares command and control and unique libraries with [MgBot](https://attack.mitre.org/software/S1146) and [Nightdoor](https://attack.mitre.org/software/S1147), indicating a relationship with the [Daggerfly](https://attack.mitre.org/groups/G1034) threat actor.(Citation: Symantec Daggerfly 2024)", "external_references": [{"external_id": "S1016", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1016"}, {"description": "(Citation: ESET DazzleSpy Jan 2022)", "source_name": "DazzleSpy"}, {"description": "(Citation: Objective-See MacMa Nov 2021)", "source_name": "OSX.CDDS"}, {"description": "M.Léveillé, M., Cherepanov, A.. (2022, January 25). Watering hole deploys new macOS malware, DazzleSpy, in Asia. Retrieved May 6, 2022.", "source_name": "ESET DazzleSpy Jan 2022", "url": "https://www.welivesecurity.com/2022/01/25/watering-hole-deploys-new-macos-malware-dazzlespy-asia/"}, {"description": "Threat Hunter Team. (2024, July 23). Daggerfly: Espionage Group Makes Major Update to Toolset. Retrieved July 25, 2024.", "source_name": "Symantec Daggerfly 2024", "url": "https://symantec-enterprise-blogs.security.com/threat-intelligence/daggerfly-espionage-updated-toolset"}, {"description": "Wardle, P. (2021, November 11). OSX.CDDS (OSX.MacMa). Retrieved June 30, 2022.", "source_name": "Objective-See MacMa Nov 2021", "url": "https://objective-see.org/blog/blog_0x69.html"}], "id": "malware--bdee9574-7479-4073-a7dc-e86d8acd073a", "is_family": true, "modified": "2025-10-21T03:17:00.503Z", "name": "MacMa", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MacMa", "OSX.CDDS", "DazzleSpy"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-1073', 0, 204, '09-mitre-attack', 'retrieved', '6345BF9B70A2AF3F27CF218B1DCF842CCEF4CD739C59DD09109F55B80A0A72D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
