VALUES ('doc-09-mitre-attack-p0-1074', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-23T14:26:54.392Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FunnyDream](https://attack.mitre.org/software/S1044) is a backdoor with multiple components that was used during the [FunnyDream](https://attack.mitre.org/campaigns/C0007) campaign since at least 2019, primarily for execution and exfiltration.(Citation: Bitdefender FunnyDream Campaign November 2020)", "external_references": [{"external_id": "S1044", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1044"}, {"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "id": "malware--be25c1c0-1590-4219-a3d5-6f31799d1d1b", "is_family": true, "modified": "2024-04-11T02:30:25.854Z", "name": "FunnyDream", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FunnyDream"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1074', 0, 97, '09-mitre-attack', 'retrieved', '9CBCA90B3F37E600741483252AEC047E1E21D2E53DFC78BF2BD199E60C471EC7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
