VALUES ('doc-09-mitre-attack-p0-1075', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-08T17:32:30.731Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROADSWEEP](https://attack.mitre.org/software/S1150) is a ransomware that was deployed against Albanian government networks during [HomeLand Justice](https://attack.mitre.org/campaigns/C0038) along with the [CHIMNEYSWEEP](https://attack.mitre.org/software/S1149) backdoor.(Citation: Mandiant ROADSWEEP August 2022)", "external_references": [{"external_id": "S1150", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1150"}, {"description": "Jenkins, L. at al. (2022, August 4). ROADSWEEP Ransomware - Likely Iranian Threat Actor Conducts Politically Motivated Disruptive Activity Against Albanian Government Organizations. Retrieved August 6, 2024.", "source_name": "Mandiant ROADSWEEP August 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/likely-iranian-threat-actor-conducts-politically-motivated-disruptive-activity-against/"}], "id": "malware--be471c69-12d5-4bcc-9dad-3d42c3dbca4b", "is_family": true, "modified": "2024-08-09T17:27:24.399Z", "name": "ROADSWEEP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ROADSWEEP"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1075', 0, 100, '09-mitre-attack', 'retrieved', '2155D7E30FD3E323B1004D36D0607B9BDC4E2E2F131BA93E0367A5C6E4250585', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
