VALUES ('doc-09-mitre-attack-p0-1076', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-12T16:14:28.845Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNSPOT](https://attack.mitre.org/software/S0562) is an implant that injected the [SUNBURST](https://attack.mitre.org/software/S0559) backdoor into the SolarWinds Orion software update framework. It was used by [APT29](https://attack.mitre.org/groups/G0016) since at least February 2020.(Citation: CrowdStrike SUNSPOT Implant January 2021) ", "external_references": [{"external_id": "S0562", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0562"}, {"description": "(Citation: CrowdStrike SUNSPOT Implant January 2021)", "source_name": "SUNSPOT"}, {"description": "CrowdStrike Intelligence Team. (2021, January 11). SUNSPOT: An Implant in the Build Process. Retrieved January 11, 2021.", "source_name": "CrowdStrike SUNSPOT Implant January 2021", "url": "https://www.crowdstrike.com/blog/sunspot-malware-technical-analysis/"}], "id": "malware--bf48e7f8-752c-4ce8-bf8f-748edacd8fa6", "is_family": true, "modified": "2025-04-16T20:38:33.634Z", "name": "SUNSPOT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SUNSPOT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1076', 0, 109, '09-mitre-attack', 'retrieved', '142B2277B5747CA8D57B1618C984E519B43A45B036E175856148A2988685D5B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
