VALUES ('doc-09-mitre-attack-p0-1080', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:12.310Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TinyZBot](https://attack.mitre.org/software/S0004) is a bot written in C# that was developed by [Cleaver](https://attack.mitre.org/groups/G0003). (Citation: Cylance Cleaver)", "external_references": [{"external_id": "S0004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0004"}, {"description": "Cylance. (2014, December). Operation Cleaver. Retrieved September 14, 2017.", "source_name": "Cylance Cleaver", "url": "https://web.archive.org/web/20200302085133/https://www.cylance.com/content/dam/cylance/pages/operation-cleaver/Cylance_Operation_Cleaver_Report.pdf"}], "id": "malware--c0c45d38-fe57-4cd4-b2b2-9ecd0ddd4ca9", "is_family": true, "modified": "2025-04-16T20:38:33.790Z", "name": "TinyZBot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TinyZBot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1080', 0, 72, '09-mitre-attack', 'retrieved', '623D706DF83300068709E635BB12E9E2597D5DCC8AB645CC81DBF2A920D9FFF7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
