VALUES ('doc-09-mitre-attack-p0-1082', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-17T20:17:37.168Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BackConfig](https://attack.mitre.org/software/S0475) is a custom Trojan with a flexible plugin architecture that has been used by [Patchwork](https://attack.mitre.org/groups/G0040).(Citation: Unit 42 BackConfig May 2020)", "external_references": [{"external_id": "S0475", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0475"}, {"description": "Hinchliffe, A. and Falcone, R. (2020, May 11). Updated BackConfig Malware Targeting Government and Military Organizations in South Asia. Retrieved June 17, 2020.", "source_name": "Unit 42 BackConfig May 2020", "url": "https://unit42.paloaltonetworks.com/updated-backconfig-malware-targeting-government-and-military-organizations/"}], "id": "malware--c13d9621-aca7-436b-ab3d-3a95badb3d00", "is_family": true, "modified": "2025-04-16T20:38:33.939Z", "name": "BackConfig", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BackConfig"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1082', 0, 95, '09-mitre-attack', 'retrieved', 'D7B5026BD724765936B5454E733ACD5264B80162BEC238303ABB9338CB5689BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
