VALUES ('doc-09-mitre-attack-p0-1083', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-29T15:44:58.517Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowGoop](https://attack.mitre.org/software/S1046) is a loader that consists of a DLL loader and a PowerShell-based downloader; it has been used by [MuddyWater](https://attack.mitre.org/groups/G0069) as their main loader.(Citation: DHS CISA AA22-055A MuddyWater February 2022)(Citation: CYBERCOM Iranian Intel Cyber January 2022)", "external_references": [{"external_id": "S1046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1046"}, {"description": "Cyber National Mission Force. (2022, January 12). Iranian intel cyber suite of malware uses open source tools. Retrieved September 30, 2022.", "source_name": "CYBERCOM Iranian Intel Cyber January 2022", "url": "https://www.cybercom.mil/Media/News/Article/2897570/iranian-intel-cyber-suite-of-malware-uses-open-source-tools/"}, {"description": "FBI, CISA, CNMF, NCSC-UK. (2022, February 24). Iranian Government-Sponsored Actors Conduct Cyber Operations Against Global Government and Commercial Networks. Retrieved September 27, 2022.", "source_name": "DHS CISA AA22-055A MuddyWater February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-055a"}], "id": "malware--c19d19ae-dd58-4584-8469-966bbeaa80e3", "is_family": true, "modified": "2025-04-16T20:38:34.085Z", "name": "PowGoop", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PowGoop"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Ozer Sarilar, @ozersarilar, STM"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1083', 0, 147, '09-mitre-attack', 'retrieved', '8CC388033FF428A96D44F0A9DA8FEC5AC36183B9EF637A4CA7DC1B432C2BA6E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
