VALUES ('doc-09-mitre-attack-p0-1086', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nerex](https://attack.mitre.org/software/S0210) is a Trojan used by [Elderwood](https://attack.mitre.org/groups/G0066) to open a backdoor on compromised hosts. (Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Nerex May 2012)", "external_references": [{"external_id": "S0210", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0210"}, {"description": "(Citation: Symantec Nerex May 2012)", "source_name": "Nerex"}, {"description": "Ladley, F. (2012, May 15). Backdoor.Nerex. Retrieved February 23, 2018.", "source_name": "Symantec Nerex May 2012", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2012-051515-3445-99"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}], "id": "malware--c251e4a5-9a2e-4166-8e42-442af75c3b9a", "is_family": true, "modified": "2024-11-17T19:55:07.591Z", "name": "Nerex", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Nerex"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1086', 0, 115, '09-mitre-attack', 'retrieved', '8911BF37D5E4ABCC033A5B394D421C1A822D2EF0D4E192D54A414A4B3DC50D8F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version":