VALUES ('doc-09-mitre-attack-p0-1087', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-03T14:55:46.682Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BoomBox](https://attack.mitre.org/software/S0635) is a downloader responsible for executing next stage components that has been used by [APT29](https://attack.mitre.org/groups/G0016) since at least 2021.(Citation: MSTIC Nobelium Toolset May 2021)", "external_references": [{"external_id": "S0635", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0635"}, {"description": "MSTIC. (2021, May 28). Breaking down NOBELIUM’s latest early-stage toolset. Retrieved August 4, 2021.", "source_name": "MSTIC Nobelium Toolset May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/28/breaking-down-nobeliums-latest-early-stage-toolset/"}], "id": "malware--c26f1c05-b861-4970-94dc-2f7f921a3074", "is_family": true, "modified": "2025-04-25T14:44:37.490Z", "name": "BoomBox", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BoomBox"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1087', 0, 88, '09-mitre-attack', 'retrieved', '9B9E121958E46DE9CD924C2829DF31B11D5D2CEEF39B2408BF227B76800A6680', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
