VALUES ('doc-09-mitre-attack-p0-1088', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-20T21:08:56.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DEADEYE](https://attack.mitre.org/software/S1052) is a malware launcher that has been used by [APT41](https://attack.mitre.org/groups/G0096) since at least May 2021. [DEADEYE](https://attack.mitre.org/software/S1052) has variants that can either embed a payload inside a compiled binary (DEADEYE.EMBED) or append it to the end of a file (DEADEYE.APPEND).(Citation: Mandiant APT41)", "external_references": [{"external_id": "S1052", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1052"}, {"description": "(Citation: Mandiant APT41)", "source_name": "DEADEYE.EMBED"}, {"description": "(Citation: Mandiant APT41)", "source_name": "DEADEYE.APPEND"}, {"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "malware--c46eb8e6-bf29-4696-8008-3ddb0b4ca470", "is_family": true, "modified": "2024-04-11T02:38:56.409Z", "name": "DEADEYE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DEADEYE", "DEADEYE.EMBED", "DEADEYE.APPEND"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1088', 0, 133, '09-mitre-attack', 'retrieved', 'A5D024DB9DC5775DE1376A9538A3366E53DDBB2D9EA9EBAAF17B5115800BC4B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
