VALUES ('doc-09-mitre-attack-p0-1090', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Proton](https://attack.mitre.org/software/S0279) is a macOS backdoor focusing on data theft and credential access (Citation: objsee mac malware 2017).", "external_references": [{"external_id": "S0279", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0279"}, {"description": "(Citation: objsee mac malware 2017).", "source_name": "Proton"}, {"description": "Patrick Wardle. (n.d.). Mac Malware of 2017. Retrieved September 21, 2018.", "source_name": "objsee mac malware 2017", "url": "https://objective-see.com/blog/blog_0x25.html"}], "id": "malware--c541efb4-e7b1-4ad6-9da8-b4e113f5dd42", "is_family": true, "modified": "2025-04-25T14:44:38.517Z", "name": "Proton", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Proton"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1090', 0, 84, '09-mitre-attack', 'retrieved', '056CBEB5248688A737B40620049ACF3E9C71383CD96BCA7CA6575393A28A7193', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
