VALUES ('doc-09-mitre-attack-p0-1091', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T12:07:59.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LAMEHUG](https://attack.mitre.org/software/S9035) is Python-based information stealer first identified in July 2025 by Ukraine''s Computer Emergency Response Team (CERT-UA) in phishing emails targeting Ukrainian government officials. [LAMEHUG](https://attack.mitre.org/software/S9035) is the first known malware to integrate artificial intelligence (AI) directly into its attack workflow by querying large language models (LLMs) hosted on Hugging Face to dynamically generate reconnaissance, data theft, and system manipulation commands in real time. [LAMEHUG](https://attack.mitre.org/software/S9035) has been attributed to [APT28](https://attack.mitre.org/groups/G0007). (Citation: Splunk LAMEHUG SEP 2025)(Citation: Nov AI Threat Tracker)(Citation: Cato LAMEHUG JUL 2025)", "external_references": [{"external_id": "S9035", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9035"}, {"description": "(Citation: Nov AI Threat Tracker)", "source_name": "PROMPTSTEAL"}, {"description": "Conteras, T., Splunk Research Team. (2025, September 25). From Prompt to Payload: LAMEHUG’s LLM-Driven Cyber Intrusion. Retrieved April 21, 2026.", "source_name": "Splunk LAMEHUG SEP 2025", "url": "https://www.splunk.com/en_us/blog/security/lamehug-ai-driven-malware-llm-cyber-intrusion-analysis.html"}, {"description": "Google Threat Intelligence Group. (2025, November 5). GTIG AI Threat Tracker: Advances in Threat Actor Usage of AI Tools. Retrieved March 31, 2026.", "source_name": "Nov AI Threat Tracker", "url": "https://cloud.google.com/blog/topics/threat-intelligence/threat-actor-usage-of-ai-tools"}, {"description": "Simonovich, V. (2025, July 23). Cato CTRL™ Threat Research: Analyzing LAMEHUG – First Known LLM-Powered Malware with Links to APT28 (Fancy Bear) . Retrieved April 21, 2026.", "source_name": "Cato LAMEHUG JUL 2025", "url": "https://www.catonetworks.com/blog/cato-ctrl-threat-research-analyzing-lamehug/"}], "id": "malware--c55e0410-842d-4365-a2c8-26c0330f85b8", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "LAMEHUG", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LAMEHUG", "PROMPTSTEAL"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1091', 0, 227, '09-mitre-attack', 'retrieved', 'D1DCBEE96B096A2089CBAAEF3E403CD3097479EFB6E318622D4B57343B1CABD4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
