VALUES ('doc-09-mitre-attack-p0-1092', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:11.148Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Trojan.Mebromi](https://attack.mitre.org/software/S0001) is BIOS-level malware that takes control of the victim before MBR. (Citation: Ge 2011)", "external_references": [{"external_id": "S0001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0001"}, {"description": "Ge, L. (2011, September 9). BIOS Threat is Showing up Again!. Retrieved November 14, 2014.", "source_name": "Ge 2011", "url": "http://www.symantec.com/connect/blogs/bios-threat-showing-again"}], "id": "malware--c5e9cb46-aced-466c-85ea-7db5572ad9ec", "is_family": true, "modified": "2025-04-25T14:44:38.888Z", "name": "Trojan.Mebromi", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Trojan.Mebromi"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1092', 0, 76, '09-mitre-attack', 'retrieved', '7CFD6828181C7F1701CBB263164363CEBFD5A45308D29D14968BDE335EC7C032', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
