VALUES ('doc-09-mitre-attack-p0-1094', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InnaputRAT](https://attack.mitre.org/software/S0259) is a remote access tool that can exfiltrate files from a victim’s machine. [InnaputRAT](https://attack.mitre.org/software/S0259) has been seen out in the wild since 2016. (Citation: ASERT InnaputRAT April 2018)", "external_references": [{"external_id": "S0259", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0259"}, {"description": "(Citation: ASERT InnaputRAT April 2018)", "source_name": "InnaputRAT"}, {"description": "ASERT Team. (2018, April 04). Innaput Actors Utilize Remote Access Trojan Since 2016, Presumably Targeting Victim Files. Retrieved July 9, 2018.", "source_name": "ASERT InnaputRAT April 2018", "url": "https://asert.arbornetworks.com/innaput-actors-utilize-remote-access-trojan-since-2016-presumably-targeting-victim-files/"}], "id": "malware--c8b6cc43-ce61-42ae-87f3-a5f10526f952", "is_family": true, "modified": "2025-04-25T14:44:39.436Z", "name": "InnaputRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["InnaputRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1094', 0, 108, '09-mitre-attack', 'retrieved', 'CD41C202C34B15FC45506E82FB1F5C44F71A68137C151EADDE9625652DDA40A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
