VALUES ('doc-09-mitre-attack-p0-1096', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-16T15:14:25.631Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kessel](https://attack.mitre.org/software/S0487) is an advanced version of OpenSSH which acts as a custom backdoor, mainly acting to steal credentials and function as a bot. [Kessel](https://attack.mitre.org/software/S0487) has been active since its C2 domain began resolving in August 2018.(Citation: ESET ForSSHe December 2018)", "external_references": [{"external_id": "S0487", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0487"}, {"description": "Dumont, R., M.Léveillé, M., Porcher, H. (2018, December 1). THE DARK SIDE OF THE FORSSHE A landscape of OpenSSH backdoors. Retrieved July 16, 2020.", "source_name": "ESET ForSSHe December 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/12/ESET-The_Dark_Side_of_the_ForSSHe.pdf"}], "id": "malware--c984b414-b766-44c5-814a-2fe96c913c12", "is_family": true, "modified": "2024-04-11T01:48:38.105Z", "name": "Kessel", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kessel"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1096', 0, 114, '09-mitre-attack', 'retrieved', '84F0B550C00155F478607DB08971197B45844E08F3224D369FB43C99FEB0B594', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
