VALUES ('doc-09-mitre-attack-p0-1097', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-16T18:19:25.986Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GrimAgent](https://attack.mitre.org/software/S0632) is a backdoor that has been used before the deployment of [Ryuk](https://attack.mitre.org/software/S0446) ransomware since at least 2020; it is likely used by [FIN6](https://attack.mitre.org/groups/G0037) and [Wizard Spider](https://attack.mitre.org/groups/G0102).(Citation: Group IB GrimAgent July 2021)", "external_references": [{"external_id": "S0632", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0632"}, {"description": "Priego, A. (2021, July). THE BROTHERS GRIM: THE REVERSING TALE OF GRIMAGENT MALWARE USED BY RYUK. Retrieved September 19, 2024.", "source_name": "Group IB GrimAgent July 2021", "url": "https://www.group-ib.com/blog/grimagent/"}], "id": "malware--c9b99d03-ff11-4a48-95f0-82660d582c25", "is_family": true, "modified": "2024-09-19T14:32:39.426Z", "name": "GrimAgent", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GrimAgent"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1097', 0, 103, '09-mitre-attack', 'retrieved', 'DB7697975D8D7EEA9C307DBC24D40368F42944CB8415C4986DD382ACB83C0F94', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
