VALUES ('doc-09-mitre-attack-p0-1098', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-01T14:07:36.692Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LookBack](https://attack.mitre.org/software/S0582) is a remote access trojan written in C++ that was used against at least three US utility companies in July 2019. The TALONITE activity group has been observed using [LookBack](https://attack.mitre.org/software/S0582).(Citation: Proofpoint LookBack Malware Aug 2019)(Citation: Dragos TALONITE)(Citation: Dragos Threat Report 2020)", "external_references": [{"external_id": "S0582", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0582"}, {"description": "(Citation: Proofpoint LookBack Malware Aug 2019)", "source_name": "LookBack"}, {"description": "Raggi, M. Schwarz, D.. (2019, August 1). LookBack Malware Targets the United States Utilities Sector with Phishing Attacks Impersonating Engineering Licensing Boards. Retrieved February 25, 2021.", "source_name": "Proofpoint LookBack Malware Aug 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/lookback-malware-targets-united-states-utilities-sector-phishing-attacks"}, {"description": "Dragos. (null). TALONITE. Retrieved February 25, 2021.", "source_name": "Dragos TALONITE", "url": "https://www.dragos.com/threat/talonite/"}, {"description": "Dragos. (n.d.). ICS Cybersecurity Year in Review 2020. Retrieved February 25, 2021.", "source_name": "Dragos Threat Report 2020", "url": "https://hub.dragos.com/hubfs/Year-in-Review/Dragos_2020_ICS_Cybersecurity_Year_In_Review.pdf?hsCtaTracking=159c0fc3-92d8-425d-aeb8-12824f2297e8%7Cf163726d-579b-4996-9a04-44e5a124d770"}], "id": "malware--c9ccc4df-1f56-49e7-ad57-b383e1451688", "is_family": true, "modified": "2025-04-25T14:44:40.541Z", "name": "LookBack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LookBack"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1098', 0, 159, '09-mitre-attack', 'retrieved', '6EB7EDEC28CF55B18B45E9FFBA57CC0FCF517F02F3D216CFD2AE04EAF3A87B53', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
