VALUES ('doc-09-mitre-attack-p0-1099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-09T20:19:34.719Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[STEADYPULSE](https://attack.mitre.org/software/S1112) is a web shell that infects targeted Pulse Secure VPN servers through modification of a legitimate Perl script that was used as early as 2020 including in activity against US Defense Industrial Base (DIB) entities.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"external_id": "S1112", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1112"}, {"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "malware--ca0fead6-5277-427a-825b-42ff1fbe476e", "is_family": true, "modified": "2025-04-15T19:46:35.400Z", "name": "STEADYPULSE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["STEADYPULSE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1099', 0, 120, '09-mitre-attack', 'retrieved', '2198FB5E103AE2257F24A9CBB92B1B6169F568AEE78CDA1CF79BF60C51C7FA44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
