VALUES ('doc-09-mitre-attack-p0-1101', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-10T23:19:38.608Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Clop](https://attack.mitre.org/software/S0611) is a ransomware family that was first observed in February 2019 and has been used against retail, transportation and logistics, education, manufacturing, engineering, automotive, energy, financial, aerospace, telecommunications, professional and legal services, healthcare, and high tech industries. [Clop](https://attack.mitre.org/software/S0611) is a variant of the CryptoMix ransomware.(Citation: Mcafee Clop Aug 2019)(Citation: Cybereason Clop Dec 2020)(Citation: Unit42 Clop April 2021) ", "external_references": [{"external_id": "S0611", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0611"}, {"description": "(Citation: Mcafee Clop Aug 2019)(Citation: Cybereason Clop Dec 2020)", "source_name": "Clop"}, {"description": "Mundo, A. (2019, August 1). Clop Ransomware. Retrieved May 10, 2021.", "source_name": "Mcafee Clop Aug 2019", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/clop-ransomware/"}, {"description": "Cybereason Nocturnus. (2020, December 23). Cybereason vs. Clop Ransomware. Retrieved May 11, 2021.", "source_name": "Cybereason Clop Dec 2020", "url": "https://www.cybereason.com/blog/cybereason-vs.-clop-ransomware"}, {"description": "Santos, D. (2021, April 13). Threat Assessment: Clop Ransomware. Retrieved July 30, 2021.", "source_name": "Unit42 Clop April 2021", "url": "https://unit42.paloaltonetworks.com/clop-ransomware/"}], "id": "malware--cad3ba95-8c89-4146-ab10-08daa813f9de", "is_family": true, "modified": "2025-04-25T14:44:41.142Z", "name": "Clop", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Clop"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": 