VALUES ('doc-09-mitre-attack-p0-1102', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:25.361Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NetTraveler](https://attack.mitre.org/software/S0033) is malware that has been used in multiple cyber espionage campaigns for basic surveillance of victims. The earliest known samples have timestamps back to 2005, and the largest number of observed samples were created between 2010 and 2013. (Citation: Kaspersky NetTraveler)", "external_references": [{"external_id": "S0033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0033"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (n.d.). The NetTraveler (aka ‘Travnet’). Retrieved November 17, 2024.", "source_name": "Kaspersky NetTraveler", "url": "https://web.archive.org/web/20160326004042/http://kasperskycontenthub.com/wp-content/uploads/sites/43/vlpdfs/kaspersky-the-net-traveler-part1-final.pdf"}], "id": "malware--cafd0bf8-2b9c-46c7-ae3c-3e0f42c5062e", "is_family": true, "modified": "2024-11-17T18:04:41.738Z", "name": "NetTraveler", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["NetTraveler"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1102', 0, 106, '09-mitre-attack', 'retrieved', '1911F3A60962F7CCDE7AD733719A2EFBFFB5F9B63E2187F504F8B309E8EE758D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
