VALUES ('doc-09-mitre-attack-p0-1103', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-17T18:49:30.307Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[YAHOYAH](https://attack.mitre.org/software/S0388) is a Trojan used by [Tropic Trooper](https://attack.mitre.org/groups/G0081) as a second-stage backdoor.(Citation: TrendMicro TropicTrooper 2015)", "external_references": [{"external_id": "S0388", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0388"}, {"description": "Alintanahin, K. (2015). Operation Tropic Trooper: Relying on Tried-and-Tested Flaws to Infiltrate Secret Keepers. Retrieved June 14, 2019.", "source_name": "TrendMicro TropicTrooper 2015", "url": "https://documents.trendmicro.com/assets/wp/wp-operation-tropic-trooper.pdf"}], "id": "malware--cb444a16-3ea5-4a91-88c6-f329adcb8af3", "is_family": true, "modified": "2024-04-19T13:19:32.736Z", "name": "YAHOYAH", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["YAHOYAH"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1103', 0, 82, '09-mitre-attack', 'retrieved', 'CC598925F50810C3149DE3DD603ECB7CA9C1D312EA8E406017545ED91B476E3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
