VALUES ('doc-09-mitre-attack-p0-1104', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T17:31:33.707Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lokibot](https://attack.mitre.org/software/S0447) is a widely distributed information stealer that was first reported in 2015. It is designed to steal sensitive information such as usernames, passwords, cryptocurrency wallets, and other credentials. [Lokibot](https://attack.mitre.org/software/S0447) can also create a backdoor into infected systems to allow an attacker to install additional payloads.(Citation: Infoblox Lokibot January 2019)(Citation: Morphisec Lokibot April 2020)(Citation: CISA Lokibot September 2020)", "external_references": [{"external_id": "S0447", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0447"}, {"description": "(Citation: Infoblox Lokibot January 2019)(Citation: Morphisec Lokibot April 2020)(Citation: Talos Lokibot Jan 2021)", "source_name": "Lokibot"}, {"description": "Hoang, M. (2019, January 31). Malicious Activity Report: Elements of Lokibot Infostealer. Retrieved May 15, 2020.", "source_name": "Infoblox Lokibot January 2019", "url": "https://insights.infoblox.com/threat-intelligence-reports/threat-intelligence--22"}, {"description": "Cheruku, H. (2020, April 15). LOKIBOT WITH AUTOIT OBFUSCATOR + FRENCHY SHELLCODE. Retrieved May 14, 2020.", "source_name": "Morphisec Lokibot April 2020", "url": "https://blog.morphisec.com/lokibot-with-autoit-obfuscator-frenchy-shellcode"}, {"description": "DHS/CISA. (2020, September 22). Alert (AA20-266A) LokiBot Malware . Retrieved September 15, 2021.", "source_name": "CISA Lokibot September 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-266a"}, {"description": "Muhammad, I., Unterbrink, H.. (2021, January 6). A Deep Dive into Lokibot Infection Chain. Retrieved August 31, 2021.", "source_name": "Talos Lokibot Jan 2021", "url": "https://blog.talosintelligence.com/2021/01/a-deep-dive-into-lokibot-infection-chain.html"}], "id": "malware--cb741463-f0fe-42e0-8d45-bc7e8335f5ae", "is_family": true, "modified": "2025-04-25T14:44:41.863Z", "name": "Lokibot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Lokibot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1104', 0, 214, '09-mitre-attack', 'retrieved', 'DDE60775FABFDB2A5255D369E37AAF8CB8E41AC783AF28EBF355CA68EDCA5F96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
