VALUES ('doc-09-mitre-attack-p0-1106', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:07.565Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROCKBOOT](https://attack.mitre.org/software/S0112) is a [Bootkit](https://attack.mitre.org/techniques/T1542/003) that has been used by an unidentified, suspected China-based group. (Citation: FireEye Bootkits)", "external_references": [{"external_id": "S0112", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0112"}, {"description": "Andonov, D., et al. (2015, December 7). Thriving Beyond The Operating System: Financial Threat Group Targets Volume Boot Record. Retrieved May 13, 2016.", "source_name": "FireEye Bootkits", "url": "https://www.fireeye.com/blog/threat-research/2015/12/fin1-targets-boot-record.html"}], "id": "malware--cba78a1c-186f-4112-9e6a-be1839f030f7", "is_family": true, "modified": "2025-04-25T14:44:42.600Z", "name": "ROCKBOOT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ROCKBOOT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1106', 0, 86, '09-mitre-attack', 'retrieved', 'A4F3295159CF7409F279C439621AF5846A2E52576D379B44C8EBAC06198E5657', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
