VALUES ('doc-09-mitre-attack-p0-1107', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:38.128Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CloudDuke](https://attack.mitre.org/software/S0054) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) in 2015. (Citation: F-Secure The Dukes) (Citation: Securelist Minidionis July 2015)", "external_references": [{"external_id": "S0054", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0054"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}, {"description": "Lozhkin, S.. (2015, July 16). Minidionis – one more APT with a usage of cloud drives. Retrieved April 5, 2017.", "source_name": "Securelist Minidionis July 2015", "url": "https://securelist.com/minidionis-one-more-apt-with-a-usage-of-cloud-drives/71443/"}], "id": "malware--cbf646f1-7db5-4dc6-808b-0094313949df", "is_family": true, "modified": "2025-04-25T14:44:42.958Z", "name": "CloudDuke", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CloudDuke", "MiniDionis", "CloudLook"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1107', 0, 112, '09-mitre-attack', 'retrieved', 'D7685E70F09C6074690BE4BEA47D5F7EBE95627C8C758A14AD0A5DCAA4BA013C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
