VALUES ('doc-09-mitre-attack-p0-1108', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-29T21:32:27.939Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Egregor](https://attack.mitre.org/software/S0554) is a Ransomware-as-a-Service (RaaS) tool that was first observed in September 2020. Researchers have noted code similarities between [Egregor](https://attack.mitre.org/software/S0554) and Sekhmet ransomware, as well as [Maze](https://attack.mitre.org/software/S0449) ransomware.(Citation: NHS Digital Egregor Nov 2020)(Citation: Cyble Egregor Oct 2020)(Citation: Security Boulevard Egregor Oct 2020)", "external_references": [{"external_id": "S0554", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0554"}, {"description": "(Citation: NHS Digital Egregor Nov 2020)(Citation: Cyble Egregor Oct 2020)", "source_name": "Egregor"}, {"description": "NHS Digital. (2020, November 26). Egregor Ransomware The RaaS successor to Maze. Retrieved December 29, 2020.", "source_name": "NHS Digital Egregor Nov 2020", "url": "https://digital.nhs.uk/cyber-alerts/2020/cc-3681#summary"}, {"description": "Cybleinc. (2020, October 31). Egregor Ransomware – A Deep Dive Into Its Activities and Techniques. Retrieved December 29, 2020.", "source_name": "Cyble Egregor Oct 2020", "url": "https://cybleinc.com/2020/10/31/egregor-ransomware-a-deep-dive-into-its-activities-and-techniques/"}, {"description": "Meskauskas, T.. (2020, October 29). Egregor: Sekhmet’s Cousin. Retrieved January 6, 2021.", "source_name": "Security Boulevard Egregor Oct 2020", "url": "https://securityboulevard.com/2020/10/egregor-sekhmets-cousin/"}], "id": "malware--cc4c1287-9c86-4447-810c-744f3880ec37", "is_family": true, "modified": "2025-04-25T14:44:43.318Z", "name": "Egregor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Egregor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security", "Matt Brenton, Zurich Insurance Group"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1108', 0, 178, '09-mitre-attack', 'retrieved', '9C13CE56E32E94477371A109ACF1798ECEA4BD2BD2211AB53B1F2AD5987EE33E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
