VALUES ('doc-09-mitre-attack-p0-1109', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-04-27T20:21:16.487Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PoetRAT](https://attack.mitre.org/software/S0428) is a remote access trojan (RAT) that was first identified in April 2020. [PoetRAT](https://attack.mitre.org/software/S0428) has been used in multiple campaigns against the private and public sectors in Azerbaijan, including ICS and SCADA systems in the energy sector. The STIBNITE activity group has been observed using the malware. [PoetRAT](https://attack.mitre.org/software/S0428) derived its name from references in the code to poet William Shakespeare. (Citation: Talos PoetRAT April 2020)(Citation: Talos PoetRAT October 2020)(Citation: Dragos Threat Report 2020)", "external_references": [{"external_id": "S0428", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0428"}, {"description": "Dragos. (n.d.). ICS Cybersecurity Year in Review 2020. Retrieved February 25, 2021.", "source_name": "Dragos Threat Report 2020", "url": "https://hub.dragos.com/hubfs/Year-in-Review/Dragos_2020_ICS_Cybersecurity_Year_In_Review.pdf?hsCtaTracking=159c0fc3-92d8-425d-aeb8-12824f2297e8%7Cf163726d-579b-4996-9a04-44e5a124d770"}, {"description": "Mercer, W, et al. (2020, April 16). PoetRAT: Python RAT uses COVID-19 lures to target Azerbaijan public and private sectors. Retrieved April 27, 2020.", "source_name": "Talos PoetRAT April 2020", "url": "https://blog.talosintelligence.com/2020/04/poetrat-covid-19-lures.html"}, {"description": "Mercer, W. Rascagneres, P. Ventura, V. (2020, October 6). PoetRAT: Malware targeting public and private sector in Azerbaijan evolves . Retrieved April 9, 2021.", "source_name": "Talos PoetRAT October 2020", "url": "https://blog.talosintelligence.com/2020/10/poetrat-update.html"}], "id": "malware--cc5497f7-a9e8-436f-94da-b2b4a9b9ad3c", "is_family": true, "modified": "2024-08-05T18:24:31.652Z", "name": "PoetRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PoetRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.3"}', 'kb-doc-09-mitre-attack-p0-1109', 0, 200, '09-mitre-attack', 'retrieved', '9D5E14028DFA136952871120D87286E616DF299DA500B2ED401E31A3CFA3662B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
