VALUES ('doc-09-mitre-attack-p0-1111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T20:13:25.762Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StealBit](https://attack.mitre.org/software/S1200) is a data exfiltration tool that is developed and maintained by the operators of the the LockBit Ransomware-as-a-Service (RaaS) and offered to affiliates to exfiltrate data from compromised systems for double extortion purposes.(Citation: Cybereason StealBit Exfiltration Tool)(Citation: FBI Lockbit 2.0 FEB 2022)", "external_references": [{"external_id": "S1200", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1200"}, {"description": "Cybereason Global SOC Team. (n.d.). THREAT ANALYSIS REPORT: Inside the LockBit Arsenal - The StealBit Exfiltration Tool. Retrieved January 29, 2025.", "source_name": "Cybereason StealBit Exfiltration Tool", "url": "https://www.cybereason.com/blog/research/threat-analysis-report-inside-the-lockbit-arsenal-the-stealbit-exfiltration-tool"}, {"description": "FBI. (2022, February 4). Indicators of Compromise Associated with LockBit 2.0 Ransomware. Retrieved January 24, 2025.", "source_name": "FBI Lockbit 2.0 FEB 2022", "url": "https://www.ic3.gov/CSA/2022/220204.pdf"}], "id": "malware--cf8b27df-c494-4a0c-b093-556a80ad2bcf", "is_family": true, "modified": "2025-01-29T20:17:12.643Z", "name": "StealBit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["StealBit"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1111', 0, 139, '09-mitre-attack', 'retrieved', 'AA9C1253EC92C478BCAA77C7B4F443B24B07AACEE9123B40F7308BFBBD0619F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
