VALUES ('doc-09-mitre-attack-p0-1112', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FELIXROOT](https://attack.mitre.org/software/S0267) is a backdoor that has been used to target Ukrainian victims. (Citation: FireEye FELIXROOT July 2018)", "external_references": [{"external_id": "S0267", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0267"}, {"description": "(Citation: ESET GreyEnergy Oct 2018)", "source_name": "GreyEnergy mini"}, {"description": "(Citation: FireEye FELIXROOT July 2018)(Citation: ESET GreyEnergy Oct 2018)", "source_name": "FELIXROOT"}, {"description": "Cherepanov, A. (2018, October). GREYENERGY A successor to BlackEnergy. Retrieved November 15, 2018.", "source_name": "ESET GreyEnergy Oct 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/10/ESET_GreyEnergy.pdf"}, {"description": "Patil, S. (2018, June 26). Microsoft Office Vulnerabilities Used to Distribute FELIXROOT Backdoor in Recent Campaign. Retrieved November 17, 2024.", "source_name": "FireEye FELIXROOT July 2018", "url": "https://web.archive.org/web/20200607025424/https://www.fireeye.com/blog/threat-research/2018/07/microsoft-office-vulnerabilities-used-to-distribute-felixroot-backdoor.html"}], "id": "malware--cf8df906-179c-4a78-bd6e-6605e30f6624", "is_family": true, "modified": "2024-11-17T16:15:55.203Z", "name": "FELIXROOT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FELIXROOT", "GreyEnergy mini"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-1112', 0, 131, '09-mitre-attack'