VALUES ('doc-09-mitre-attack-p0-1113', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-24T12:59:57.991Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZxShell](https://attack.mitre.org/software/S0412) is a remote administration tool and backdoor that can be downloaded from the Internet, particularly from Chinese hacker websites. It has been used since at least 2004.(Citation: FireEye APT41 Aug 2019)(Citation: Talos ZxShell Oct 2014)", "external_references": [{"external_id": "S0412", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0412"}, {"description": "(Citation: FireEye APT41 Aug 2019)(Citation: Talos ZxShell Oct 2014)", "source_name": "ZxShell"}, {"description": "(Citation: Talos ZxShell Oct 2014)", "source_name": "Sensocode"}, {"description": "Allievi, A., et al. (2014, October 28). Threat Spotlight: Group 72, Opening the ZxShell. Retrieved September 24, 2019.", "source_name": "Talos ZxShell Oct 2014", "url": "https://blogs.cisco.com/security/talos/opening-zxshell"}, {"description": "Fraser, N., et al. (2019, August 7). Double DragonAPT41, a dual espionage and cyber crime operation APT41. Retrieved September 23, 2019.", "source_name": "FireEye APT41 Aug 2019", "url": "https://www.mandiant.com/sites/default/files/2022-02/rt-apt41-dual-operation.pdf"}], "id": "malware--cfc75b0d-e579-40ae-ad07-a1ce00d49a6c", "is_family": true, "modified": "2025-04-16T20:38:36.169Z", "name": "ZxShell", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ZxShell", "Sensocode"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1113', 0, 154, '09-mitre-attack', 'retrieved', 'B6070A457F007A48E2A9642FCB19CDE169F784FA95E7FA7EA580F68D0F0CC7EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
