VALUES ('doc-09-mitre-attack-p0-1114', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-12T18:58:06.672Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RIFLESPINE](https://attack.mitre.org/software/S1222) is a cross-platform backdoor that leverages Google Drive for file transfer and command execution.(Citation: Google Cloud Mandiant UNC3886 2024)", "external_references": [{"external_id": "S1222", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1222"}, {"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}], "id": "malware--d0270367-37fc-471e-9206-483582c5f47d", "is_family": true, "modified": "2025-06-12T18:59:34.105Z", "name": "RIFLESPINE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["RIFLESPINE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1114', 0, 99, '09-mitre-attack', 'retrieved', 'BA2D441F3A33772F20623A183277CC04528B649FDFE74403957DD502A0420263', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
