VALUES ('doc-09-mitre-attack-p0-1117', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-23T18:41:36.914Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CoinTicker](https://attack.mitre.org/software/S0369) is a malicious application that poses as a cryptocurrency price ticker and installs components of the open source backdoors EvilOSX and EggShell.(Citation: CoinTicker 2019)", "external_references": [{"external_id": "S0369", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0369"}, {"description": "Thomas Reed. (2018, October 29). Mac cryptocurrency ticker app installs backdoors. Retrieved April 23, 2019.", "source_name": "CoinTicker 2019", "url": "https://blog.malwarebytes.com/threat-analysis/2018/10/mac-cryptocurrency-ticker-app-installs-backdoors/"}], "id": "malware--d1531eaa-9e17-473e-a680-3298469662c3", "is_family": true, "modified": "2025-04-25T14:44:45.121Z", "name": "CoinTicker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CoinTicker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Richie Cyrus, SpecterOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1117', 0, 90, '09-mitre-attack', 'retrieved', '6C40219842647CCBDC65AA55982F90E6769EBBF9E49FB12616810BEDAB78718D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
