VALUES ('doc-09-mitre-attack-p0-1119', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-11T15:06:57.934Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Penquin](https://attack.mitre.org/software/S0587) is a remote access trojan (RAT) with multiple versions used by [Turla](https://attack.mitre.org/groups/G0010) to target Linux systems since at least 2014.(Citation: Kaspersky Turla Penquin December 2014)(Citation: Leonardo Turla Penquin May 2020)", "external_references": [{"external_id": "S0587", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0587"}, {"description": "(Citation: Leonardo Turla Penquin May 2020)", "source_name": "Penquin 2.0"}, {"description": "(Citation: Leonardo Turla Penquin May 2020)", "source_name": "Penquin_x64"}, {"description": "Baumgartner, K. and Raiu, C. (2014, December 8). The ‘Penquin’ Turla. Retrieved March 11, 2021.", "source_name": "Kaspersky Turla Penquin December 2014", "url": "https://securelist.com/the-penquin-turla-2/67962/"}, {"description": "Leonardo. (2020, May 29). MALWARE TECHNICAL INSIGHT TURLA “Penquin_x64”. Retrieved March 11, 2021.", "source_name": "Leonardo Turla Penquin May 2020", "url": "https://www.leonardo.com/documents/20142/10868623/Malware+Technical+Insight+_Turla+%E2%80%9CPenquin_x64%E2%80%9D.pdf"}], "id": "malware--d18cb958-f4ad-4fb3-bb4f-e8994d206550", "is_family": true, "modified": "2025-10-22T03:16:19.980Z", "name": "Penquin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Penquin", "Penquin 2.0", "Penquin_x64"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Silvio La Porta, @LDO_CyberSec, Leonardo''s Cyber Security Division", "Antonio Villani, @LDO_CyberSec, Leonardo''s Cyber Security Division", "Nino Verde, @LDO_CyberSec, Leonardo''s Cyber Security Division"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1119', 0, 164, '09-mitre-attack', 'retrieved', '905A6265A10E1AC317778FBE83C7EE8959E4647B4A2D28FC01F52F4FA7131102', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
