VALUES ('doc-09-mitre-attack-p0-1121', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-07T19:05:48.886Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BabyShark](https://attack.mitre.org/software/S0414) is a Microsoft Visual Basic (VB) script-based malware family that is believed to be associated with several North Korean campaigns. (Citation: Unit42 BabyShark Feb 2019)", "external_references": [{"external_id": "S0414", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0414"}, {"description": "(Citation: Mandiant APT43 March 2024)", "source_name": "LATEOP"}, {"description": "(Citation: Unit42 BabyShark Feb 2019)(Citation: Unit42 BabyShark Apr 2019)", "source_name": "BabyShark"}, {"description": "Lim, M.. (2019, April 26). BabyShark Malware Part Two – Attacks Continue Using KimJongRAT and PCRat . Retrieved October 7, 2019.", "source_name": "Unit42 BabyShark Apr 2019", "url": "https://unit42.paloaltonetworks.com/babyshark-malware-part-two-attacks-continue-using-kimjongrat-and-pcrat/"}, {"description": "Mandiant. (2024, March 14). APT43: North Korean Group Uses Cybercrime to Fund Espionage Operations. Retrieved May 3, 2024.", "source_name": "Mandiant APT43 March 2024", "url": "https://services.google.com/fh/files/misc/apt43-report-en.pdf"}, {"description": "Unit 42. (2019, February 22). New BabyShark Malware Targets U.S. National Security Think Tanks. Retrieved October 7, 2019.", "source_name": "Unit42 BabyShark Feb 2019", "url": "https://unit42.paloaltonetworks.com/new-babyshark-malware-targets-u-s-national-security-think-tanks/"}], "id": "malware--d1b7830a-fced-4be3-a99c-f495af9d9e1b", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "BabyShark", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BabyShark", "LATEOP"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1121', 0, 170, '09-mitre-attack', 'retrieved', '03B6B696749BBC1E82DA80DF312CFD9F1CD5BC313E570D5945BEF08E835B0423', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
