VALUES ('doc-09-mitre-attack-p0-1122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T18:58:03.614Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cannon](https://attack.mitre.org/software/S0351) is a Trojan with variants written in C# and Delphi. It was first observed in April 2018. (Citation: Unit42 Cannon Nov 2018)(Citation: Unit42 Sofacy Dec 2018)", "external_references": [{"external_id": "S0351", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0351"}, {"description": "(Citation: Unit42 Cannon Nov 2018)", "source_name": "Cannon"}, {"description": "Falcone, R., Lee, B. (2018, November 20). Sofacy Continues Global Attacks and Wheels Out New ‘Cannon’ Trojan. Retrieved November 26, 2018.", "source_name": "Unit42 Cannon Nov 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/11/unit42-sofacy-continues-global-attacks-wheels-new-cannon-trojan/"}, {"description": "Lee, B., Falcone, R. (2018, December 12). Dear Joohn: The Sofacy Group’s Global Campaign. Retrieved April 19, 2019.", "source_name": "Unit42 Sofacy Dec 2018", "url": "https://unit42.paloaltonetworks.com/dear-joohn-sofacy-groups-global-campaign/"}], "id": "malware--d20b397a-ea47-48a9-b503-2e2a3551e11d", "is_family": true, "modified": "2025-04-25T14:44:46.016Z", "name": "Cannon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Cannon"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1122', 0, 132, '09-mitre-attack', 'retrieved', 'AD936014054E1DB4869510AE91AE522DD516E35E2A5C0034179A1129EDEB01FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_versio