VALUES ('doc-09-mitre-attack-p0-1123', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-08T14:05:44.014Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CreepySnail](https://attack.mitre.org/software/S1024) is a custom PowerShell implant that has been used by [POLONIUM](https://attack.mitre.org/groups/G1005) since at least 2022.(Citation: Microsoft POLONIUM June 2022)", "external_references": [{"external_id": "S1024", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1024"}, {"description": "Microsoft. (2022, June 2). Exposing POLONIUM activity and infrastructure targeting Israeli organizations. Retrieved July 1, 2022.", "source_name": "Microsoft POLONIUM June 2022", "url": "https://www.microsoft.com/security/blog/2022/06/02/exposing-polonium-activity-and-infrastructure-targeting-israeli-organizations/"}], "id": "malware--d23de441-f9cf-4802-b1ff-f588a11a896b", "is_family": true, "modified": "2025-04-16T20:38:36.803Z", "name": "CreepySnail", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CreepySnail"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1123', 0, 86, '09-mitre-attack', 'retrieved', '61DAA1AAE7C0865B92A6E4A97B3AED55E37D0A24EA982927EAA1486070F76A6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
