VALUES ('doc-09-mitre-attack-p0-1125', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-10T20:24:50.464Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Melcoz](https://attack.mitre.org/software/S0530) is a banking trojan family built from the open source tool Remote Access PC. [Melcoz](https://attack.mitre.org/software/S0530) was first observed in attacks in Brazil and since 2018 has spread to Chile, Mexico, Spain, and Portugal.(Citation: Securelist Brazilian Banking Malware July 2020)", "external_references": [{"external_id": "S0530", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0530"}, {"description": "GReAT. (2020, July 14). The Tetrade: Brazilian banking malware goes global. Retrieved November 9, 2020.", "source_name": "Securelist Brazilian Banking Malware July 2020", "url": "https://securelist.com/the-tetrade-brazilian-banking-malware/97779/"}], "id": "malware--d3105fb5-c494-4fd1-a7be-414eab9e0c96", "is_family": true, "modified": "2024-03-29T18:12:59.212Z", "name": "Melcoz", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Melcoz"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1125', 0, 107, '09-mitre-attack', 'retrieved', '274AC7FCE8599F6087E1D75C579A9ACF8333F8B62F40620D715AC766B536DE7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
