VALUES ('doc-09-mitre-attack-p0-1126', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:21.027Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Winnti for Windows](https://attack.mitre.org/software/S0141) is a modular remote access Trojan (RAT) that has been used likely by multiple groups to carry out intrusions in various regions since at least 2010, including by one group referred to as the same name, [Winnti Group](https://attack.mitre.org/groups/G0044).(Citation: Kaspersky Winnti April 2013)(Citation: Microsoft Winnti Jan 2017)(Citation: Novetta Winnti April 2015)(Citation: 401 TRG Winnti Umbrella May 2018). The Linux variant is tracked separately under [Winnti for Linux](https://attack.mitre.org/software/S0430).(Citation: Chronicle Winnti for Linux May 2019)", "external_references": [{"external_id": "S0141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0141"}, {"description": "Cap, P., et al. (2017, January 25). Detecting threat actors in recent German industrial attacks with Windows Defender ATP. Retrieved February 8, 2017.", "source_name": "Microsoft Winnti Jan 2017", "url": "https://blogs.technet.microsoft.com/mmpc/2017/01/25/detecting-threat-actors-in-recent-german-industrial-attacks-with-windows-defender-atp/"}, {"description": "Chronicle Blog. (2019, May 15). Winnti: More than just Windows and Gates. Retrieved April 29, 2020.", "source_name": "Chronicle Winnti for Linux May 2019", "url": "https://medium.com/chronicle-blog/winnti-more-than-just-windows-and-gates-e4f03436031a"}, {"description": "Hegel, T. (2018, May 3). Burning Umbrella: An Intelligence Report on the Winnti Umbrella and Associated State-Sponsored Attackers. Retrieved July 8, 2018.", "source_name": "401 TRG Winnti Umbrella May 2018", "url": "https://401trg.github.io/pages/burning-umbrella.html"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2013, April 11). Winnti. More than just a game. Retrieved February 8, 2017.", "source_name": "Kaspersky Winnti April 2013", "url": "https://securelist.com/winnti-more-than-just-a-game/37029/"}, {"description": "Novetta Threat Research Group. (2015, April 7). Winnti Analysis. Retrieved February 8, 2017.", "source_name": "Novetta Winnti April 2015", "url": "https://web.archive.org/web/20150412223949/http://www.novetta.com/wp-content/uploads/2015/04/novetta_winntianalysis.pdf"}], "id": "malware--d3afa961-a80c-4043-9509-282cdf69ab21", "is_family": true, "modified": "2024-04-10T20:35:29.262Z", "name": "Winnti for Windows", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Winnti for Windows"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "3.1"}', 'kb-doc-09-mitre-attack-p0-1126', 0, 259, '09-mitre-attack', 'retrieved', 'A0267BB22DE432F0BBF7230CED40CAD8BD6067CAFD2305A626B958B748983677', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
