VALUES ('doc-09-mitre-attack-p0-1128', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-18T20:16:12.119Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BONDUPDATER](https://attack.mitre.org/software/S0360) is a PowerShell backdoor used by [OilRig](https://attack.mitre.org/groups/G0049). It was first observed in November 2017 during targeting of a Middle Eastern government organization, and an updated version was observed in August 2018 being used to target a government organization with spearphishing emails.(Citation: FireEye APT34 Dec 2017)(Citation: Palo Alto OilRig Sep 2018)", "external_references": [{"external_id": "S0360", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0360"}, {"description": "Sardiwal, M, et al. (2017, December 7). New Targeted Attack in the Middle East by APT34, a Suspected Iranian Threat Group, Using CVE-2017-11882 Exploit. Retrieved December 20, 2017.", "source_name": "FireEye APT34 Dec 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/12/targeted-attack-in-middle-east-by-apt34.html"}, {"description": "Wilhoit, K. and Falcone, R. (2018, September 12). OilRig Uses Updated BONDUPDATER to Target Middle Eastern Government. Retrieved February 18, 2019.", "source_name": "Palo Alto OilRig Sep 2018", "url": "https://unit42.paloaltonetworks.com/unit42-oilrig-uses-updated-bondupdater-target-middle-eastern-government/"}], "id": "malware--d5268dfb-ae2b-4e0e-ac07-02a460613d8a", "is_family": true, "modified": "2025-04-25T14:44:47.458Z", "name": "BONDUPDATER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BONDUPDATER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1128', 0, 157, '09-mitre-attack', 'retrieved', '4657EDF29701B6E205D17E379D6247EF7FDC06D35DEB951EE6BAB97EB56C7A5B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
