VALUES ('doc-09-mitre-attack-p0-1132', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-19T16:40:24.922Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ebury](https://attack.mitre.org/software/S0377) is an OpenSSH backdoor and credential stealer targeting Linux servers and container hosts developed by [Windigo](https://attack.mitre.org/groups/G0124). [Ebury](https://attack.mitre.org/software/S0377) is primarily installed through modifying shared libraries (`.so` files) executed by the legitimate OpenSSH program. First seen in 2009, [Ebury](https://attack.mitre.org/software/S0377) has been used to maintain a botnet of servers, deploy additional malware, and steal cryptocurrency wallets, credentials, and credit card details.(Citation: ESET Ebury Feb 2014)(Citation: BleepingComputer Ebury March 2017)(Citation: ESET Ebury Oct 2017)(Citation: ESET Ebury May 2024)", "external_references": [{"external_id": "S0377", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0377"}, {"description": "(Citation: ESET Ebury Feb 2014)", "source_name": "Ebury"}, {"description": "Cimpanu, C.. (2017, March 29). Russian Hacker Pleads Guilty for Role in Infamous Linux Ebury Malware. Retrieved April 23, 2019.", "source_name": "BleepingComputer Ebury March 2017", "url": "https://www.bleepingcomputer.com/news/security/russian-hacker-pleads-guilty-for-role-in-infamous-linux-ebury-malware/"}, {"description": "M.Léveillé, M.. (2014, February 21). An In-depth Analysis of Linux/Ebury. Retrieved April 19, 2019.", "source_name": "ESET Ebury Feb 2014", "url": "https://www.welivesecurity.com/2014/02/21/an-in-depth-analysis-of-linuxebury/"}, {"description": "Marc-Etienne M.Léveillé. (2024, May 1). Ebury is alive but unseen. Retrieved May 21, 2024.", "source_name": "ESET Ebury May 2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/ebury-is-alive-but-unseen.pdf"}, {"description": "Vachon, F. (2017, October 30). Windigo Still not Windigone: An Ebury Update . Retrieved February 10, 2021.", "source_name": "ESET Ebury Oct 2017", "url": "https://www.welivesecurity.com/2017/10/30/windigo-ebury-update-2/"}], "id": "malware--d6b3fcd0-1c86-4350-96f0-965ed02fcc51", "is_family": true, "modified": "2024-09-20T21:15:51.302Z", "name": "Ebury", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Ebury"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Marc-Etienne M.Léveillé, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1132', 0, 226, '09-mitre-attack', 'retrieved', '01E494D104E5A520A2E1693C4EAA865DBBD0AEA333395C05BBDFD03DAADEC35B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
