VALUES ('doc-09-mitre-attack-p0-1133', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-06T12:22:23.447Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kinsing](https://attack.mitre.org/software/S0599) is Golang-based malware that runs a cryptocurrency miner and attempts to spread itself to other hosts in the victim environment. (Citation: Aqua Kinsing April 2020)(Citation: Sysdig Kinsing November 2020)(Citation: Aqua Security Cloud Native Threat Report June 2021)", "external_references": [{"external_id": "S0599", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0599"}, {"description": "Singer, G. (2020, April 3). Threat Alert: Kinsing Malware Attacks Targeting Container Environments. Retrieved April 1, 2021.", "source_name": "Aqua Kinsing April 2020", "url": "https://blog.aquasec.com/threat-alert-kinsing-malware-container-vulnerability"}, {"description": "Huang, K. (2020, November 23). Zoom into Kinsing. Retrieved April 1, 2021.", "source_name": "Sysdig Kinsing November 2020", "url": "https://sysdig.com/blog/zoom-into-kinsing-kdevtmpfsi/"}, {"description": "Team Nautilus. (2021, June). Attacks in the Wild on the Container Supply Chain and Infrastructure. Retrieved August 26, 2021.", "source_name": "Aqua Security Cloud Native Threat Report June 2021", "url": "https://info.aquasec.com/hubfs/Threat%20reports/AquaSecurity_Cloud_Native_Threat_Report_2021.pdf?utm_campaign=WP%20-%20Jun2021%20Nautilus%202021%20Threat%20Research%20Report&utm_medium=email&_hsmi=132931006&_hsenc=p2ANqtz-_8oopT5Uhqab8B7kE0l3iFo1koirxtyfTehxF7N-EdGYrwk30gfiwp5SiNlW3G0TNKZxUcDkYOtwQ9S6nNVNyEO-Dgrw&utm_content=132931006&utm_source=hs_automation"}], "id": "malware--d6e55656-e43f-411f-a7af-45df650471c5", "is_family": true, "modified": "2025-04-25T14:44:48.521Z", "name": "Kinsing", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kinsing"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Center for Threat-Informed Defense (CTID)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1133', 0, 161, '09-mitre-attack', 'retrieved', '0B6A64AC8E9C5F76EB6E95DB12530CEB6C80AC49DFF61ACA7D8C1A4DD1E4A641', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
