VALUES ('doc-09-mitre-attack-p0-1135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-07T19:08:55.858Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Meteor](https://attack.mitre.org/software/S0688) is a wiper that was used against Iranian government organizations, including Iranian Railways, the Ministry of Roads, and Urban Development systems, in July 2021. [Meteor](https://attack.mitre.org/software/S0688) is likely a newer version of similar wipers called Stardust and Comet that were reportedly used by a group called \"Indra\" since at least 2019 against private companies in Syria.(Citation: Check Point Meteor Aug 2021)", "external_references": [{"external_id": "S0688", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0688"}, {"description": "Check Point Research Team. (2021, August 14). Indra - Hackers Behind Recent Attacks on Iran. Retrieved February 17, 2022.", "source_name": "Check Point Meteor Aug 2021", "url": "https://research.checkpoint.com/2021/indra-hackers-behind-recent-attacks-on-iran/"}], "id": "malware--d79e7a60-5de9-448e-a074-f95d2d80f8d0", "is_family": true, "modified": "2025-04-16T20:38:37.573Z", "name": "Meteor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Meteor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India", "Tsubasa Matsuda, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1135', 0, 146, '09-mitre-attack', 'retrieved', '5E524CDBE762763F3A8E2CD6E4A3DFA4A17890CB91952F6C748EC155729DCC2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
