VALUES ('doc-09-mitre-attack-p0-1136', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-04T17:52:28.806Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[njRAT](https://attack.mitre.org/software/S0385) is a remote access tool (RAT) that was first observed in 2012. It has been used by threat actors in the Middle East.(Citation: Fidelis njRAT June 2013)", "external_references": [{"external_id": "S0385", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0385"}, {"description": "(Citation: Fidelis njRAT June 2013)", "source_name": "LV"}, {"description": "(Citation: Fidelis njRAT June 2013)(Citation: Trend Micro njRAT 2018)", "source_name": "Bladabindi"}, {"description": "Dawda, U. and Villeneuve, N. (2013, August 30). Njw0rm - Brother From the Same Mother. Retrieved November 17, 2024.", "source_name": "FireEye Njw0rm Aug 2013", "url": "https://web.archive.org/web/20200302085808/https://www.fireeye.com/blog/threat-research/2013/08/njw0rm-brother-from-the-same-mother.html"}, {"description": "Fidelis Cybersecurity. (2013, June 28). Fidelis Threat Advisory #1009: \"njRAT\" Uncovered. Retrieved June 4, 2019.", "source_name": "Fidelis njRAT June 2013", "url": "https://www.threatminer.org/_reports/2013/fta-1009---njrat-uncovered-1.pdf"}, {"description": "Pascual, C. (2018, November 27). AutoIt-Compiled Worm Affecting Removable Media Delivers Fileless Version of BLADABINDI/njRAT Backdoor. Retrieved June 4, 2019.", "source_name": "Trend Micro njRAT 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/autoit-compiled-worm-affecting-removable-media-delivers-fileless-version-of-bladabindi-njrat-backdoor/"}, {"description": "Some sources have discussed Njw0rm as a later variant of [njRAT](https://attack.mitre.org/software/S0385), where Njw0rm adds the ability to spread via removable devices such as USB drives.(Citation: FireEye Njw0rm Aug 2013) Other sources contain that functionality in their description of [njRAT](https://attack.mitre.org/software/S0385) itself.(Citation: Fidelis njRAT June 2013)(Citation: Trend Micro njRAT 2018)", "source_name": "Njw0rm"}], "id": "malware--d906e6f7-434c-44c0-b51a-ed50af8f7945", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "njRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["njRAT", "Njw0rm", "LV", "Bladabindi"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.7"}', 'kb-doc-09-mitre-attack-p0-1136', 0, 222, '09-mitre-attack', 'retrieved', '2F022049DCCBD214692BFAF0588B289020D6E7F99CF7B6FB53AE623C69252986', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
