VALUES ('doc-09-mitre-attack-p0-1139', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:08.292Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOTRASH](https://attack.mitre.org/software/S0114) is a [Bootkit](https://attack.mitre.org/techniques/T1542/003) that targets Windows operating systems. It has been used by threat actors that target the financial sector.(Citation: Mandiant M Trends 2016)(Citation: FireEye Bootkits)(Citation: FireEye BOOTRASH SANS)", "external_references": [{"external_id": "S0114", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0114"}, {"description": "Andonov, D., et al. (2015, December 7). Thriving Beyond The Operating System: Financial Threat Group Targets Volume Boot Record. Retrieved May 13, 2016.", "source_name": "FireEye Bootkits", "url": "https://www.fireeye.com/blog/threat-research/2015/12/fin1-targets-boot-record.html"}, {"description": "Glyer, C.. (2017, June 22). Boot What?. Retrieved November 17, 2024.", "source_name": "FireEye BOOTRASH SANS", "url": "https://web.archive.org/web/20190926040727/https://www.sans.org/cyber-security-summit/archives/file/summit-archive-1498163766.pdf"}, {"description": "Mandiant. (2016, February 25). Mandiant M-Trends 2016. Retrieved November 17, 2024.", "source_name": "Mandiant M Trends 2016", "url": "https://web.archive.org/web/20211024160454/https://www.fireeye.com/content/dam/fireeye-www/current-threats/pdfs/rpt-mtrends-2016.pdf"}], "id": "malware--da2ef4a9-7cbe-400a-a379-e2f230f28db3", "is_family": true, "modified": "2024-11-17T16:24:43.289Z", "name": "BOOTRASH", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BOOTRASH"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Christopher Glyer, Mandiant, @cglyer"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1139', 0, 143, '09-mitre-attack', 'retrieved', '9AD4B083EC30F7F9280DA56FEACBB3B2E49189D555031438027933C5AACD6C15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
