VALUES ('doc-09-mitre-attack-p0-1141', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:13.252Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ComRAT](https://attack.mitre.org/software/S0126) is a second stage implant suspected of being a descendant of [Agent.btz](https://attack.mitre.org/software/S0092) and used by [Turla](https://attack.mitre.org/groups/G0010). The first version of [ComRAT](https://attack.mitre.org/software/S0126) was identified in 2007, but the tool has undergone substantial development for many years since.(Citation: Symantec Waterbug)(Citation: NorthSec 2015 GData Uroburos Tools)(Citation: ESET ComRAT May 2020)", "external_references": [{"external_id": "S0126", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0126"}, {"description": "Faou, M. (2020, May). From Agent.btz to ComRAT v4: A ten-year journey. Retrieved June 15, 2020.", "source_name": "ESET ComRAT May 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/05/ESET_Turla_ComRAT.pdf"}, {"description": "Rascagneres, P. (2015, May). Tools used by the Uroburos actors. Retrieved August 18, 2016.", "source_name": "NorthSec 2015 GData Uroburos Tools", "url": "https://docplayer.net/101655589-Tools-used-by-the-uroburos-actors.html"}, {"description": "Symantec. (2015, January 26). The Waterbug attack group. Retrieved April 10, 2015.", "source_name": "Symantec Waterbug", "url": "https://www.threatminer.org/report.php?q=waterbug-attack-group.pdf&y=2015#gsc.tab=0&gsc.q=waterbug-attack-group.pdf&gsc.page=1"}], "id": "malware--da5880b4-f7da-4869-85f2-e0aba84b8565", "is_family": true, "modified": "2025-04-16T20:38:37.924Z", "name": "ComRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ComRAT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Matthieu Faou, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1141', 0, 159, '09-mitre-attack', 'retrieved', 'EDE6D599F1D773CDE8CCC143F1B4BDA064DEDEA24496B98ACE1EB80EDF531457', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
