VALUES ('doc-09-mitre-attack-p0-1143', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:22.451Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ChChes](https://attack.mitre.org/software/S0144) is a Trojan that appears to be used exclusively by [menuPass](https://attack.mitre.org/groups/G0045). It was used to target Japanese organizations in 2016. Its lack of persistence methods suggests it may be intended as a first-stage tool. (Citation: Palo Alto menuPass Feb 2017) (Citation: JPCERT ChChes Feb 2017) (Citation: PWC Cloud Hopper Technical Annex April 2017)", "external_references": [{"external_id": "S0144", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0144"}, {"description": "(Citation: Palo Alto menuPass Feb 2017) (Citation: JPCERT ChChes Feb 2017) (Citation: PWC Cloud Hopper Technical Annex April 2017)", "source_name": "ChChes"}, {"description": "(Citation: PWC Cloud Hopper Technical Annex April 2017)", "source_name": "Scorpion"}, {"description": "Based on similarities in reported malware behavior and open source reporting, it is assessed that the malware named HAYMAKER by FireEye is likely the same as the malware ChChes. (Citation: FireEye APT10 April 2017) (Citation: Twitter Nick Carr APT10)", "source_name": "HAYMAKER"}, {"description": "Carr, N.. (2017, April 6). Retrieved September 12, 2024.", "source_name": "Twitter Nick Carr APT10", "url": "https://x.com/ItsReallyNick/status/850105140589633536"}, {"description": "FireEye iSIGHT Intelligence. (2017, April 6). APT10 (MenuPass Group): New Tools, Global Campaign Latest Manifestation of Longstanding Threat. Retrieved June 29, 2017.", "source_name": "FireEye APT10 April 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/04/apt10_menupass_grou.html"}, {"description": "Miller-Osborn, J. and Grunzweig, J.. (2017, February 16). menuPass Returns with New Malware and New Attacks Against Japanese Academics and Organizations. Retrieved March 1, 2017.", "source_name": "Palo Alto menuPass Feb 2017", "url": "http://researchcenter.paloaltonetworks.com/2017/02/unit42-menupass-returns-new-malware-new-attacks-japanese-academics-organizations/"}, {"description": "Nakamura, Y.. (2017, February 17). ChChes - Malware that Communicates with C&C Servers Using Cookie Headers. Retrieved November 17, 2024.", "source_name": "JPCERT ChChes Feb 2017", "url": "https://blogs.jpcert.or.jp/en/2017/02/chches-malware--93d6.html"}, {"description": "PwC and BAE Systems. (2017, April). Operation Cloud Hopper: Technical Annex. Retrieved April 13, 2017.", "source_name": "PWC Cloud Hopper Technical Annex April 2017", "url": "https://www.pwc.co.uk/cyber-security/pdf/pwc-uk-operation-cloud-hopper-technical-annex-april-2017.pdf"}], "id": "malware--dc5d1a33-62aa-4a0c-aa8c-589b87beb11e", "is_family": true, "modified": "2024-11-17T16:46:57.582Z", "name": "ChChes", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ChChes", "Scorpion", "HAYMAKER"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1143', 0, 308, '09-mitre-attack', 'retrieved', '2860F7254265623B7FF5104A7C41219C053635658AD6F8A9AF8D4C352640FAFE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
