VALUES ('doc-09-mitre-attack-p0-1144', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T17:23:27.855Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerStallion](https://attack.mitre.org/software/S0393) is a lightweight [PowerShell](https://attack.mitre.org/techniques/T1059/001) backdoor used by [Turla](https://attack.mitre.org/groups/G0010), possibly as a recovery access tool to install other backdoors.(Citation: ESET Turla PowerShell May 2019)", "external_references": [{"external_id": "S0393", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0393"}, {"description": "Faou, M. and Dumont R.. (2019, May 29). A dive into Turla PowerShell usage. Retrieved June 14, 2019.", "source_name": "ESET Turla PowerShell May 2019", "url": "https://www.welivesecurity.com/2019/05/29/turla-powershell-usage/"}], "id": "malware--dcac85c1-6485-4790-84f6-de5e6f6b91dd", "is_family": true, "modified": "2025-04-25T14:44:50.859Z", "name": "PowerStallion", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["PowerStallion"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1144', 0, 91, '09-mitre-attack', 'retrieved', 'B88CC6A74FD71138C3B4590F25DF3C37E99FBDE195BA8CC89881C1BB2D1342A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
