INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1145', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-16T19:24:37.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ANDROMEDA](https://attack.mitre.org/software/S1074) is commodity malware that was widespread in the early 2010''s and continues to be observed in infections across a wide variety of industries. During the 2022 [C0026](https://attack.mitre.org/campaigns/C0026) campaign, threat actors re-registered expired [ANDROMEDA](https://attack.mitre.org/software/S1074) C2 domains to spread malware to select targets in Ukraine.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"external_id": "S1074", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1074"}, {"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "malware--dcd9548e-df9e-47c2-81f3-bc084289959d", "is_family": true, "modified": "2023-09-29T18:11:31.659Z", "name": "ANDROMEDA", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ANDROMEDA"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1145', 0, 133, '09-mitre-attack', 'retrieved', 'EC9FA87AC4D956CC38542D7512652D9694E8E65AADCB1A51CD1783B9A7185DD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
