VALUES ('doc-09-mitre-attack-p0-1146', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-04T18:15:43.225Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Manjusaka](https://attack.mitre.org/software/S1156) is a Chinese-language intrusion framework, similar to [Sliver](https://attack.mitre.org/software/S0633) and [Cobalt Strike](https://attack.mitre.org/software/S0154), with an ELF binary written in GoLang as the controller for Windows and Linux implants written in Rust. First identified in 2022, [Manjusaka](https://attack.mitre.org/software/S1156) consists of multiple components, only one of which (a command and control module) is freely available.(Citation: Talos Manjusaka 2022)", "external_references": [{"external_id": "S1156", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1156"}, {"description": "Asheer Malhotra & Vitor Ventura. (2022, August 2). Manjusaka: A Chinese sibling of Sliver and Cobalt Strike. Retrieved September 4, 2024.", "source_name": "Talos Manjusaka 2022", "url": "https://blog.talosintelligence.com/manjusaka-offensive-framework/"}], "id": "malware--dd2ad3d7-d7ef-4af5-a919-bfe8f2571705", "is_family": true, "modified": "2024-09-06T18:11:40.228Z", "name": "Manjusaka", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Manjusaka"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Subhash Thapa"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1146', 0, 128, '09-mitre-attack', 'retrieved', 'F989D1826AFAEBAE57FF3E412D85B80B3C6BB03676E3DFA4C7A8BE007876A6F7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
