VALUES ('doc-09-mitre-attack-p0-1147', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-27T15:22:22.979Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IceApple](https://attack.mitre.org/software/S1022) is a modular Internet Information Services (IIS) post-exploitation framework, that has been used since at least 2021 against the technology, academic, and government sectors.(Citation: CrowdStrike IceApple May 2022)", "external_references": [{"external_id": "S1022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1022"}, {"description": "CrowdStrike. (2022, May). ICEAPPLE: A NOVEL INTERNET INFORMATION SERVICES (IIS) POST-EXPLOITATION FRAMEWORK. Retrieved June 27, 2022.", "source_name": "CrowdStrike IceApple May 2022", "url": "https://www.crowdstrike.com/wp-content/uploads/2022/05/crowdstrike-iceapple-a-novel-internet-information-services-post-exploitation-framework.pdf"}], "id": "malware--dd889a55-fb2c-4ec7-8e9f-c399939a49e1", "is_family": true, "modified": "2025-04-16T20:38:38.400Z", "name": "IceApple", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["IceApple"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Raphaël Lheureux"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1147', 0, 98, '09-mitre-attack', 'retrieved', '1713BF9A964DFBA26B2E2D11EE68582C2A35AC6C72D87E2B75A2986A022D5054', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
