INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1148', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T18:24:26.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) is a supply chain worm, first reported in September 2025, that spreads through code repositories, including GitHub and NPM packages. It exploits CI/CD pipeline dependencies to propagate to victims and poisons the supply chain by publishing malicious packages. Once inside a victim environment, [Shai-Hulud](https://attack.mitre.org/software/S9008) steals credentials and access tokens from compromised repository accounts and exfiltrates them to attacker-controlled servers via encoded GitHub Actions workflows.(Citation: Palo Alto Unit 42 Shai-Hulud November 2025)(Citation: Microsoft Shai-Hulud December 2025)(Citation: Socket Shai-Hulud November 2025)(Citation: Socket Shai-Hulud Trufflehog September 2025)(Citation: Aikido Shai-Hulud September 2025)(Citation: Netskope Shai-Hulud November 2025)(Citation: Wiz Shai-Hulud September 2025)\n", "external_references": [{"external_id": "S9008", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9008"}, {"description": "Charlie Eriksen. (2025, September 16). S1ngularity/nx attackers strike again. Retrieved April 9, 2026.", "source_name": "Aikido Shai-Hulud September 2025", "url": "https://www.aikido.dev/blog/s1ngularity-nx-attackers-strike-again"}, {"description": "Gianpietro Cutolo. (2025, November 26). Shai-Hulud 2.0: Aggressive, Automated, and Fast Spreading. Retrieved April 9, 2026.", "source_name": "Netskope Shai-Hulud November 2025", "url": "https://www.netskope.com/blog/shai-hulud-2-0-aggressive-automated-one-of-fastest-spreading-npm-supply-chain-attacks-ever-observed"}, {"description": "Justin Moore. (2025, November 25). \"Shai-Hulud\" Worm Compromises npm Ecosystem in Supply Chain Attack (Updated November 26). Retrieved April 9, 2026.", "source_name": "Palo Alto Unit 42 Shai-Hulud November 2025", "url": "https://unit42.paloaltonetworks.com/npm-supply-chain-attack/"}, {"description": "Merav Bar, Rami McCarthy, Barak Sharoni. (2025, September 16). Shai-Hulud: Ongoing Package Supply Chain Worm Delivering Data-Stealing Malware. Retrieved April 9, 2026.", "source_name": "Wiz Shai-Hulud September 2025", "url": "https://www.wiz.io/blog/shai-hulud-npm-supply-chain-attack"}, {"description": "Microsoft Defender Security Team. (n.d.). Shai-Hulud 2.0: Guidance for detecting, investigating, and defending against the supply chain attack. Retrieved April 9, 2026.", "source_name": "Microsoft Shai-Hulud December 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/12/09/shai-hulud-2-0-guidance-for-detecting-investigating-and-defending-against-the-supply-chain-attack/"}, {"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}, {"description": "Socket Research Team. (2025, September 15). Popular Tinycolor npm Package Compromised in Supply Chain Attack Affecting 40+ Packages. Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud Trufflehog September 2025", "url": "https://socket.dev/blog/tinycolor-supply-chain-attack-affects-40-packages"}], "id": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "is_family": true, "modified": "2026-04-24T00:04:27.563Z", "name": "Shai-Hulud", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Shai-Hulud"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Caio Silva", "Alberto Garcia", "Pedro Rodriguez", "Víctor Alba"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "SaaS", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1148', 0, 341, '09-mitre-attack', 'retrieved', '8845515964C549D7C0E29A349AE1432D1C32F7DE39F1BC54D06C7AA8A65DFE15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
