VALUES ('doc-09-mitre-attack-p0-1151', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-24T00:12:34.751Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[metaMain](https://attack.mitre.org/software/S1059) is a backdoor used by [Metador](https://attack.mitre.org/groups/G1013) to maintain long-term access to compromised machines; it has also been used to decrypt [Mafalda](https://attack.mitre.org/software/S1060) into memory.(Citation: SentinelLabs Metador Sept 2022)(Citation: SentinelLabs Metador Technical Appendix Sept 2022)", "external_references": [{"external_id": "S1059", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1059"}, {"description": "Ehrlich, A., et al. (2022, September). THE MYSTERY OF METADOR | AN UNATTRIBUTED THREAT HIDING IN TELCOS, ISPS, AND UNIVERSITIES. Retrieved January 23, 2023.", "source_name": "SentinelLabs Metador Sept 2022", "url": "https://assets.sentinelone.com/sentinellabs22/metador#page=1"}, {"description": "SentinelLabs. (2022, September 22). Metador Technical Appendix. Retrieved April 4, 2023.", "source_name": "SentinelLabs Metador Technical Appendix Sept 2022", "url": "https://docs.google.com/document/d/1e9ZTW9b71YwFWS_18ZwDAxa-cYbV8q1wUefmKZLYVsA/edit#heading=h.lmnbtht1ikzm"}], "id": "malware--df350889-4de9-44e5-8cb3-888b8343e97c", "is_family": true, "modified": "2024-04-11T00:45:31.029Z", "name": "metaMain", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["metaMain"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Massimiliano Romano, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1151', 0, 134, '09-mitre-attack', 'retrieved', '0256DC0A524C31CF11D914AF0BA47A992DDA827E33B1D8DD012025E50B5F7634', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
