VALUES ('doc-09-mitre-attack-p0-1152', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-06T14:44:50.494Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SideTwist](https://attack.mitre.org/software/S0610) is a C-based backdoor that has been used by [OilRig](https://attack.mitre.org/groups/G0049) since at least 2021.(Citation: Check Point APT34 April 2021)", "external_references": [{"external_id": "S0610", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0610"}, {"description": "Check Point. (2021, April 8). Iran’s APT34 Returns with an Updated Arsenal. Retrieved May 5, 2021.", "source_name": "Check Point APT34 April 2021", "url": "https://research.checkpoint.com/2021/irans-apt34-returns-with-an-updated-arsenal/"}], "id": "malware--df4cd566-ff2f-4d08-976d-8c86e95782de", "is_family": true, "modified": "2025-04-25T14:44:52.304Z", "name": "SideTwist", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SideTwist"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1152', 0, 85, '09-mitre-attack', 'retrieved', '5566B4334894D9C3A01DDD5C9CA969761575B7C876AFDAF679C0558120ABA388', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
