VALUES ('doc-09-mitre-attack-p0-1153', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-06T22:38:37.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KOCTOPUS](https://attack.mitre.org/software/S0669)''s batch variant is loader used by [LazyScripter](https://attack.mitre.org/groups/G0140) since 2018 to launch [Octopus](https://attack.mitre.org/software/S0340) and [Koadic](https://attack.mitre.org/software/S0250) and, in some cases, [QuasarRAT](https://attack.mitre.org/software/S0262). [KOCTOPUS](https://attack.mitre.org/software/S0669) also has a VBA variant that has the same functionality as the batch version.(Citation: MalwareBytes LazyScripter Feb 2021)", "external_references": [{"external_id": "S0669", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0669"}, {"description": "(Citation: MalwareBytes LazyScripter Feb 2021)", "source_name": "KOCTOPUS"}, {"description": "Jazi, H. (2021, February). LazyScripter: From Empire to double RAT. Retrieved November 17, 2024.", "source_name": "MalwareBytes LazyScripter Feb 2021", "url": "https://web.archive.org/web/20211003035156/https://www.malwarebytes.com/resources/files/2021/02/lazyscripter.pdf"}], "id": "malware--df9b350b-d4f9-4e79-a826-75cc75fbc1eb", "is_family": true, "modified": "2024-11-17T14:12:07.295Z", "name": "KOCTOPUS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["KOCTOPUS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1153', 0, 111, '09-mitre-attack', 'retrieved', 'EFD2580DC6243BABDEA656BADC92C74D01182D4A5F0474E92627B68F629EBA66', 'v1', '{"source_id": "09-mitre-attack", "version": 