VALUES ('doc-09-mitre-attack-p0-1154', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-27T19:05:29.386Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MechaFlounder](https://attack.mitre.org/software/S0459) is a python-based remote access tool (RAT) that has been used by [APT39](https://attack.mitre.org/groups/G0087). The payload uses a combination of actor developed code and code snippets freely available online in development communities.(Citation: Unit 42 MechaFlounder March 2019)", "external_references": [{"external_id": "S0459", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0459"}, {"description": "Falcone, R. (2019, March 4). New Python-Based Payload MechaFlounder Used by Chafer. Retrieved May 27, 2020.", "source_name": "Unit 42 MechaFlounder March 2019", "url": "https://unit42.paloaltonetworks.com/new-python-based-payload-mechaflounder-used-by-chafer/"}], "id": "malware--dfa03c7d-79ed-4ce2-b9d1-ddc9dbf56ad2", "is_family": true, "modified": "2025-04-25T14:44:52.837Z", "name": "MechaFlounder", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MechaFlounder"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1154', 0, 102, '09-mitre-attack', 'retrieved', 'FD90A645889BB82AEAAAC6D64F6818E607D3094B62D90A323A7C8B4B7D645BF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
