VALUES ('doc-09-mitre-attack-p0-1155', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:53.268Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Psylo](https://attack.mitre.org/software/S0078) is a shellcode-based Trojan that has been used by [Scarlet Mimic](https://attack.mitre.org/groups/G0029). It has similar characteristics as [FakeM](https://attack.mitre.org/software/S0076). (Citation: Scarlet Mimic Jan 2016)", "external_references": [{"external_id": "S0078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0078"}, {"description": "Falcone, R. and Miller-Osborn, J.. (2016, January 24). Scarlet Mimic: Years-Long Espionage Campaign Targets Minority Activists. Retrieved February 10, 2016.", "source_name": "Scarlet Mimic Jan 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/01/scarlet-mimic-years-long-espionage-targets-minority-activists/"}], "id": "malware--dfb5fa9b-3051-4b97-8035-08f80aef945b", "is_family": true, "modified": "2025-04-25T14:44:53.196Z", "name": "Psylo", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Psylo"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1155', 0, 91, '09-mitre-attack', 'retrieved', '0AEA598575FC976D1ACF774990D8FCCA4E974009AC39A6AAF2F8B122F27463C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
