VALUES ('doc-09-mitre-attack-p0-1156', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-25T18:18:32.811Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Heyoka Backdoor](https://attack.mitre.org/software/S1027) is a custom backdoor--based on the Heyoka open source exfiltration tool--that has been used by [Aoqin Dragon](https://attack.mitre.org/groups/G1007) since at least 2013.(Citation: SentinelOne Aoqin Dragon June 2022)(Citation: Sourceforge Heyoka 2022) ", "external_references": [{"external_id": "S1027", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1027"}, {"description": "Chen, Joey. (2022, June 9). Aoqin Dragon | Newly-Discovered Chinese-linked APT Has Been Quietly Spying On Organizations For 10 Years. Retrieved July 14, 2022.", "source_name": "SentinelOne Aoqin Dragon June 2022", "url": "https://www.sentinelone.com/labs/aoqin-dragon-newly-discovered-chinese-linked-apt-has-been-quietly-spying-on-organizations-for-10-years/"}, {"description": "Sourceforge. (n.d.). Heyoka POC Exfiltration Tool. Retrieved October 11, 2022.", "source_name": "Sourceforge Heyoka 2022", "url": "https://heyoka.sourceforge.net/"}], "id": "malware--dff90475-9f72-41a6-84ed-1fbefd3874c0", "is_family": true, "modified": "2024-04-11T02:20:55.694Z", "name": "Heyoka Backdoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Heyoka Backdoor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1156', 0, 141, '09-mitre-attack', 'retrieved', '0379747D7E519018070F11DC57ECD757760CA118D5472650B2FB399778F548FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
