VALUES ('doc-09-mitre-attack-p0-1157', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:46.445Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HTTPBrowser](https://attack.mitre.org/software/S0070) is malware that has been used by several threat groups. (Citation: ThreatStream Evasion Analysis) (Citation: Dell TG-3390) It is believed to be of Chinese origin. (Citation: ThreatConnect Anthem)", "external_references": [{"external_id": "S0070", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0070"}, {"description": "(Citation: ThreatConnect Anthem)", "source_name": "HttpDump"}, {"description": "Shelmire, A.. (2015, July 6). Evasive Maneuvers. Retrieved January 22, 2016.", "source_name": "ThreatStream Evasion Analysis", "url": "https://www.threatstream.com/blog/evasive-maneuvers-the-wekby-group-attempts-to-evade-analysis-via-custom-rop"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}, {"description": "ThreatConnect Research Team. (2015, February 27). The Anthem Hack: All Roads Lead to China. Retrieved January 26, 2016.", "source_name": "ThreatConnect Anthem", "url": "https://www.threatconnect.com/the-anthem-hack-all-roads-lead-to-china/"}], "id": "malware--e066bf86-9cfb-407a-9d25-26fd5d91e360", "is_family": true, "modified": "2025-04-25T14:44:53.772Z", "name": "HTTPBrowser", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HTTPBrowser", "Token Control", "HttpDump"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1157', 0, 146, '09-mitre-attack', 'retrieved', '37399649E321202ED40A4AC33E0FD4108F7698A24C58107C101BF6845A7FC40C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
