VALUES ('doc-09-mitre-attack-p0-1158', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-13T14:24:52.519Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRUSHFIRE](https://attack.mitre.org/software/S9011) is a passive backdoor written in C that executes in-memory within an existing process. First reported in March 2025, [BRUSHFIRE](https://attack.mitre.org/software/S9011) has been observed in activity attributed to People''s Republic of China (PRC) state-affiliated threat actors, including UNC5221 and SYLVANITE.(Citation: Dragos SYLVANITE MuddyWater Electrum March 2026)(Citation: Google UNC5221 Ivanti April 2025)(Citation: Picus Security UNC5221 Ivanti May 2025)", "external_references": [{"external_id": "S9011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9011"}, {"description": "Dragos. (2026, March 24). Dragos 2026 OT Cybersecurity Report: Year in Review, O&G and Petrochemicals Focus. Retrieved April 17, 2026.", "source_name": "Dragos SYLVANITE MuddyWater Electrum March 2026", "url": "https://hub.dragos.com/hubfs/2026_YIR_ExecutiveBriefing%20O_G.pdf?hsLang=en"}, {"description": "John Wolfram, Michael Edie, Jacob Thompson, Matt Lin, Josh Murchie. (2025, April 3). Suspected China-Nexus Threat Actor Actively Exploiting Critical Ivanti Connect Secure Vulnerability (CVE-2025-22457). Retrieved April 13, 2026.", "source_name": "Google UNC5221 Ivanti April 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-exploiting-critical-ivanti-vulnerability"}, {"description": "Sila Ozeren Hacioglu. (2025, May 5). UNC5221’s Latest Exploit: Weaponizing CVE-2025-22457 in Ivanti Connect Secure. Retrieved April 13, 2026.", "source_name": "Picus Security UNC5221 Ivanti May 2025", "url": "https://www.picussecurity.com/resource/blog/unc5221-cve-2025-22457-ivanti-connect-secure"}], "id": "malware--e110c9c6-7691-4bcb-874d-3d83a63c06c2", "is_family": true, "modified": "2026-04-23T03:07:51.031Z", "name": "BRUSHFIRE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BRUSHFIRE"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dragos Threat Intelligence"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1158', 0, 202, '09-mitre-attack', 'retrieved', 'F8DEF9B25BCDC6BD6D5CF05D79911DE4A931FA13B93F202064E645D134BFB61D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
