VALUES ('doc-09-mitre-attack-p0-1159', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:55.565Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mis-Type](https://attack.mitre.org/software/S0084) is a backdoor hybrid that was used in [Operation Dust Storm](https://attack.mitre.org/campaigns/C0016) by 2012.(Citation: Cylance Dust Storm)", "external_references": [{"external_id": "S0084", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0084"}, {"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "malware--e1161124-f22e-487f-9d5f-ed8efc8dcd61", "is_family": true, "modified": "2025-04-16T20:38:39.359Z", "name": "Mis-Type", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mis-Type"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1159', 0, 78, '09-mitre-attack', 'retrieved', '6D4C737621B62E137B4FEEEF12B9DF397CD0146452F72E0505AEDA12F2BFD792', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
