VALUES ('doc-09-mitre-attack-p0-1160', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-26T18:07:37.796Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarWeb](https://attack.mitre.org/software/S1141) is a backdoor that has been used by [Turla](https://attack.mitre.org/groups/G0010) since at least 2020 including in a compromise of a European ministry of foreign affairs (MFA) together with [LunarLoader](https://attack.mitre.org/software/S1143) and [LunarMail](https://attack.mitre.org/software/S1142). [LunarWeb](https://attack.mitre.org/software/S1141) has only been observed deployed against servers and can use [Steganography](https://attack.mitre.org/techniques/T1001/002) to obfuscate command and control.(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"external_id": "S1141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1141"}, {"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "malware--e1284931-3f85-4262-a641-9ae8bb0576a0", "is_family": true, "modified": "2024-08-16T14:42:02.739Z", "name": "LunarWeb", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LunarWeb"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Riku Katsuse, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1160', 0, 140, '09-mitre-attack', 'retrieved', 'FCEFF5F9730E79DAFE48696C7042A29C4E92444D6D74F795FE98AFA8635DA7D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
