INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1161', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-05T21:58:51.161Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) is a modular macOS malware family delivered through infected Xcode projects and executed when the project is compiled. Active since August 2020, it has been observed installing backdoors, spoofed browsers, collecting data, and encrypting user files. It is composed of SHC-compiled shell scripts and run-only AppleScripts, often hiding in apps that mimic system tools (such as Xcode, Mail, or Notes) or use familiar icons (like Launchpad) to avoid detection.(Citation: trendmicro xcsset xcode project 2020)(Citation: April 2021 TrendMicro XCSSET)(Citation: Microsoft March 2025 XCSSET)", "external_references": [{"external_id": "S0658", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0658"}, {"description": "(Citation: malwarebyteslabs xcsset dubrobber)", "source_name": "OSX.DubRobber"}, {"description": "(Citation: trendmicro xcsset xcode project 2020)", "source_name": "XCSSET"}, {"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}, {"description": "Microsoft Threat Intelligence. (2025, March 11). New XCSSET malware adds new obfuscation, persistence techniques to infect Xcode projects. Retrieved April 2, 2025.", "source_name": "Microsoft March 2025 XCSSET", "url": "https://www.microsoft.com/en-us/security/blog/2025/03/11/new-xcsset-malware-adds-new-obfuscation-persistence-techniques-to-infect-xcode-projects/"}, {"description": "Steven Du, Dechao Zhao, Luis Magisa, Ariel Neimond Lazaro. (2021, April 16). XCSSET Quickly Adapts to macOS 11 and M1-based Macs. Retrieved February 18, 2025.", "source_name": "April 2021 TrendMicro XCSSET", "url": "https://www.trendmicro.com/en_us/research/21/d/xcsset-quickly-adapts-to-macos-11-and-m1-based-macs.html"}, {"description": "Thomas Reed. (2020, April 21). OSX.DubRobber. Retrieved October 5, 2021.", "source_name": "malwarebyteslabs xcsset dubrobber", "url": "https://blog.malwarebytes.com/detections/osx-dubrobber/"}], "id": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "is_family": true, "modified": "2025-04-04T17:39:46.453Z", "name": "XCSSET", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["XCSSET", "OSX.DubRobber"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1161', 0, 264, '09-mitre-attack', 'retrieved', '0DB1E5E596D872C00CBE99885D5323CFC879A6497951D20812E287CB4AEE4E2F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
