VALUES ('doc-09-mitre-attack-p0-1163', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dipsind](https://attack.mitre.org/software/S0200) is a malware family of backdoors that appear to be used exclusively by [PLATINUM](https://attack.mitre.org/groups/G0068). (Citation: Microsoft PLATINUM April 2016)", "external_references": [{"external_id": "S0200", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0200"}, {"description": "(Citation: Microsoft PLATINUM April 2016)", "source_name": "Dipsind"}, {"description": "Windows Defender Advanced Threat Hunting Team. (2016, April 29). PLATINUM: Targeted attacks in South and Southeast Asia. Retrieved February 15, 2018.", "source_name": "Microsoft PLATINUM April 2016", "url": "https://download.microsoft.com/download/2/2/5/225BFE3E-E1DE-4F5B-A77B-71200928D209/Platinum%20feature%20article%20-%20Targeted%20attacks%20in%20South%20and%20Southeast%20Asia%20April%202016.pdf"}], "id": "malware--e170995d-4f61-4f17-b60e-04f9a06ee517", "is_family": true, "modified": "2025-04-25T14:44:54.842Z", "name": "Dipsind", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Dipsind"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Ryan Becwar"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1163', 0, 100, '09-mitre-attack', 'retrieved', '648D7192D4EC7DB76691E47E0C3ABAB0C232E642241F2464A341BA53B8B823E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
