VALUES ('doc-09-mitre-attack-p0-1164', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T13:24:08.616Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Octopus](https://attack.mitre.org/software/S0340) is a Windows Trojan written in the Delphi programming language that has been used by [Nomadic Octopus](https://attack.mitre.org/groups/G0133) to target government organizations in Central Asia since at least 2014.(Citation: Securelist Octopus Oct 2018)(Citation: Security Affairs DustSquad Oct 2018)(Citation: ESET Nomadic Octopus 2018) ", "external_references": [{"external_id": "S0340", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0340"}, {"description": "(Citation: Securelist Octopus Oct 2018)(Citation: Security Affairs DustSquad Oct 2018)(Citation: ESET Nomadic Octopus 2018)", "source_name": "Octopus"}, {"description": "Cherepanov, A. (2018, October 4). Nomadic Octopus Cyber espionage in Central Asia. Retrieved October 13, 2021.", "source_name": "ESET Nomadic Octopus 2018", "url": "https://www.virusbulletin.com/uploads/pdf/conference_slides/2018/Cherepanov-VB2018-Octopus.pdf"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, October 15). Octopus-infested seas of Central Asia. Retrieved November 14, 2018.", "source_name": "Securelist Octopus Oct 2018", "url": "https://securelist.com/octopus-infested-seas-of-central-asia/88200/"}, {"description": "Paganini, P. (2018, October 16). Russia-linked APT group DustSquad targets diplomatic entities in Central Asia. Retrieved August 24, 2021.", "source_name": "Security Affairs DustSquad Oct 2018", "url": "https://securityaffairs.co/wordpress/77165/apt/russia-linked-apt-dustsquad.html"}], "id": "malware--e2031fd5-02c2-43d4-85e2-b64f474530c2", "is_family": true, "modified": "2025-10-22T02:21:47.267Z", "name": "Octopus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Octopus"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-1164', 0, 181, '09-mitre-attack', 'retrieved', '76D0F8F051FE5D766579D56DC827F0B6289B1E9E1AECBCD44FDDC01998EE45DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
