VALUES ('doc-09-mitre-attack-p0-1166', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-26T19:18:39.227Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) is a ransomware family operated as a ransomware-as-a-service (RaaS) that has been active since at least 2022. It includes variants written in Go and Rust capable of targeting Windows, Linux, and VMware ESXi environments. [Qilin](https://attack.mitre.org/software/S1242) shares functionality overlaps with [Black Basta](https://attack.mitre.org/software/S1070), [REvil](https://attack.mitre.org/software/S0496), and [BlackCat](https://attack.mitre.org/software/S1068) ransomware. [Qilin](https://attack.mitre.org/software/S1242) affiliates have targeted multiple entities worldwide with the majority of victims in the US, France, Canada, and the UK, primarily in the manufacturing, technology, financial services, and healthcare sectors.(Citation: Trend Micro Agenda Ransomware AUG 2022)(Citation: SentinelOne Qilin NOV 2022)(Citation: BushidoToken Qilin RaaS JUN 2024)(Citation: Sophos Qilin MSP APR 2025)(Citation: Trend Micro Agenda Ransomware OCT 2025)", "external_references": [{"external_id": "S1242", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1242"}, {"description": "(Citation: Sophos Qilin MSP APR 2025)(Citation: Trend Micro Agenda Ransomware AUG 2022)(Citation: SentinelOne Qilin NOV 2022)(Citation: Trend Micro Agenda Ransomware OCT 2025)", "source_name": "Agenda"}, {"description": "Bradshaw, A. et al. (2025, April 1). Qilin affiliates spear-phish MSP ScreenConnect admin, targeting customers downstream. Retrieved September 26, 2025.", "source_name": "Sophos Qilin MSP APR 2025", "url": "https://news.sophos.com/en-us/2025/04/01/sophos-mdr-tracks-ongoing-campaign-by-qilin-affiliates-targeting-screenconnect/"}, {"description": "Magdy, S. et al. (2022, August 25). New Golang Ransomware Agenda Customizes Attacks. Retrieved September 26, 2025.", "source_name": "Trend Micro Agenda Ransomware AUG 2022", "url": "https://www.trendmicro.com/en_us/research/22/h/new-golang-ransomware-agenda-customizes-attacks.html"}, {"description": "SentinelOne. (2022, November 30). Agenda (Qilin). Retrieved September 26, 2025.", "source_name": "SentinelOne Qilin NOV 2022", "url": "https://www.sentinelone.com/anthology/agenda-qilin/"}, {"description": "Thomas, W. (2024, June 12). Tracking Adversaries: The Qilin RaaS. Retrieved September 26, 2025.", "source_name": "BushidoToken Qilin RaaS JUN 2024", "url": "https://blog.bushidotoken.net/2024/06/tracking-adversaries-qilin-raas.html"}, {"description": "Trend Micro. (2025, October 23). Agenda Ransomware Deploys Linux Variant on Windows Systems Through Remote Management Tools and BYOVD Techniques. Retrieved March 26, 2026.", "source_name": "Trend Micro Agenda Ransomware OCT 2025", "url": "https://www.trendmicro.com/en_us/research/25/j/agenda-ransomware-deploys-linux-variant-on-windows-systems.html"}], "id": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "is_family": true, "modified": "2026-04-23T03:12:30.298Z", "name": "Qilin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Qilin", "Agenda"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Jiraput Thamsongkrah", "Simon Williams"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["ESXi", "Windows", "Linux"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1166', 0, 308, '09-mitre-attack', 'retrieved', '196559A98CF9AD902ACD1C87F192FC8224913EC76DCCD6E8CE593DD2D688E1F5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
