VALUES ('doc-09-mitre-attack-p0-1167', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-01T20:17:11.064Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AppleJeus](https://attack.mitre.org/software/S0584) is a family of downloaders initially discovered in 2018 embedded within trojanized cryptocurrency applications. [AppleJeus](https://attack.mitre.org/software/S0584) has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032), targeting companies in the energy, finance, government, industry, technology, and telecommunications sectors, and several countries including the United States, United Kingdom, South Korea, Australia, Brazil, New Zealand, and Russia. [AppleJeus](https://attack.mitre.org/software/S0584) has been used to distribute the [FALLCHILL](https://attack.mitre.org/software/S0181) RAT.(Citation: CISA AppleJeus Feb 2021)", "external_references": [{"external_id": "S0584", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0584"}, {"description": "(Citation: CISA AppleJeus Feb 2021)", "source_name": "AppleJeus"}, {"description": "Cybersecurity and Infrastructure Security Agency. (2021, February 21). AppleJeus: Analysis of North Korea’s Cryptocurrency Malware. Retrieved March 1, 2021.", "source_name": "CISA AppleJeus Feb 2021", "url": "https://us-cert.cisa.gov/ncas/alerts/aa21-048a"}], "id": "malware--e2d34c63-6f5a-41f5-86a2-e2380f27f858", "is_family": true, "modified": "2025-04-16T20:38:39.879Z", "name": "AppleJeus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AppleJeus"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1167', 0, 142, '09-mitre-attack', 'retrieved', '2C3E0A87A616825F46E9814E4A83E1CF0B1615858973B1E90431D731B3AEF079', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
