VALUES ('doc-09-mitre-attack-p0-1168', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-29T19:33:35.122Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SoreFang](https://attack.mitre.org/software/S0516) is first stage downloader used by [APT29](https://attack.mitre.org/groups/G0016) for exfiltration and to load other malware.(Citation: NCSC APT29 July 2020)(Citation: CISA SoreFang July 2016)", "external_references": [{"external_id": "S0516", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0516"}, {"description": "CISA. (2020, July 16). MAR-10296782-1.v1 – SOREFANG. Retrieved September 29, 2020.", "source_name": "CISA SoreFang July 2016", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-198a"}, {"description": "National Cyber Security Centre. (2020, July 16). Advisory: APT29 targets COVID-19 vaccine development. Retrieved September 29, 2020.", "source_name": "NCSC APT29 July 2020", "url": "https://www.ncsc.gov.uk/files/Advisory-APT29-targets-COVID-19-vaccine-development-V1-1.pdf"}], "id": "malware--e33e4603-afab-402d-b2a1-248d435b5fe0", "is_family": true, "modified": "2025-10-22T02:39:07.705Z", "name": "SoreFang", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SoreFang"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1168', 0, 109, '09-mitre-attack', 'retrieved', '08B78660CC9A1BEFDC083FB6F81CB97C929B11BA8A9A7124F25FA9F8AF096F7E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
