VALUES ('doc-09-mitre-attack-p0-1169', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-18T15:00:32.571Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[STARWHALE](https://attack.mitre.org/software/S1037) is Windows Script File (WSF) backdoor that has been used by [MuddyWater](https://attack.mitre.org/groups/G0069), possibly since at least November 2021; there is also a [STARWHALE](https://attack.mitre.org/software/S1037) variant written in Golang with similar capabilities. Security researchers have also noted the use of [STARWHALE](https://attack.mitre.org/software/S1037) by UNC3313, which may be associated with [MuddyWater](https://attack.mitre.org/groups/G0069).(Citation: Mandiant UNC3313 Feb 2022)(Citation: DHS CISA AA22-055A MuddyWater February 2022)", "external_references": [{"external_id": "S1037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1037"}, {"description": "(Citation: DHS CISA AA22-055A MuddyWater February 2022)", "source_name": "CANOPY"}, {"description": "FBI, CISA, CNMF, NCSC-UK. (2022, February 24). Iranian Government-Sponsored Actors Conduct Cyber Operations Against Global Government and Commercial Networks. Retrieved September 27, 2022.", "source_name": "DHS CISA AA22-055A MuddyWater February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-055a"}, {"description": "Tomcik, R. et al. (2022, February 24). Left On Read: Telegram Malware Spotted in Latest Iranian Cyber Espionage Activity. Retrieved August 18, 2022.", "source_name": "Mandiant UNC3313 Feb 2022", "url": "https://www.mandiant.com/resources/telegram-malware-iranian-espionage"}], "id": "malware--e355fc84-6f3c-4888-8e0a-d7fa9c378532", "is_family": true, "modified": "2024-04-11T00:01:29.506Z", "name": "STARWHALE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["STARWHALE", "CANOPY"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1169', 0, 175, '09-mitre-attack', 'retrieved', 'DEAC33CB0FEF01EB931D98030B1355990883F3C778FB0C3AF551390C8747DCDD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
