VALUES ('doc-09-mitre-attack-p0-1170', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MirageFox](https://attack.mitre.org/software/S0280) is a remote access tool used against Windows systems. It appears to be an upgraded version of a tool known as Mirage, which is a RAT believed to originate in 2012. (Citation: APT15 Intezer June 2018)", "external_references": [{"external_id": "S0280", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0280"}, {"description": "(Citation: APT15 Intezer June 2018)", "source_name": "MirageFox"}, {"description": "Rosenberg, J. (2018, June 14). MirageFox: APT15 Resurfaces With New Tools Based On Old Ones. Retrieved September 21, 2018.", "source_name": "APT15 Intezer June 2018", "url": "https://web.archive.org/web/20180615122133/https://www.intezer.com/miragefox-apt15-resurfaces-with-new-tools-based-on-old-ones/"}], "id": "malware--e3cedcfe-6515-4348-af65-7f2c4157bf0d", "is_family": true, "modified": "2025-04-16T20:38:40.181Z", "name": "MirageFox", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MirageFox"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1170', 0, 114, '09-mitre-attack', 'retrieved', 'F50BF617A24517D0393428E7C489AAC934C78AF093447A8C2EEF3F7802B93596', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
