VALUES ('doc-09-mitre-attack-p0-1171', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-04T20:42:21.997Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Industroyer](https://attack.mitre.org/software/S0604) is a sophisticated malware framework designed to cause an impact to the working processes of Industrial Control Systems (ICS), specifically components used in electrical substations.(Citation: ESET Industroyer) [Industroyer](https://attack.mitre.org/software/S0604) was used in the attacks on the Ukrainian power grid in December 2016.(Citation: Dragos Crashoverride 2017) This is the first publicly known malware specifically designed to target and impact operations in the electric grid.(Citation: Dragos Crashoverride 2018)", "external_references": [{"external_id": "S0604", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0604"}, {"description": "(Citation: Dragos Crashoverride 2017)", "source_name": "CRASHOVERRIDE"}, {"description": "(Citation: ESET Industroyer)", "source_name": "Win32/Industroyer"}, {"description": "Anton Cherepanov. (2017, June 12). Win32/Industroyer: A new threat for industrial controls systems. Retrieved December 18, 2020.", "source_name": "ESET Industroyer", "url": "https://www.welivesecurity.com/wp-content/uploads/2017/06/Win32_Industroyer.pdf"}, {"description": "Dragos Inc.. (2017, June 13). CRASHOVERRIDE Analysis of the Threat to Electric Grid Operations. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2017", "url": "https://dragos.com/blog/crashoverride/CrashOverride-01.pdf"}, {"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "malware--e401d4fe-f0c9-44f0-98e6-f93487678808", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "Industroyer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Industroyer", "CRASHOVERRIDE", "Win32/Industroyer"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dragos Threat Intelligence", "Joe Slowik - Dragos"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1171', 0, 204, '09-mitre-attack', 'retrieved', '55857F0BB27C327AD29905C50BC5311E5D6DA763251F5B071574DFE5A43C79B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
