VALUES ('doc-09-mitre-attack-p0-1172', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T22:31:11.070Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LazyWiper](https://attack.mitre.org/software/S9039) is a destructive malware observed targeting a manufacturing sector company during the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063). [LazyWiper](https://attack.mitre.org/software/S9039) is a native Windows PowerShell script that is believed to have been generated by a large language model (LLM). [LazyWiper](https://attack.mitre.org/software/S9039) overwrites files on the system using the C# function `WriteRandomBytes()` and can target multiple specific file types by their extensions.(Citation: CERT Polska)", "external_references": [{"external_id": "S9039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9039"}, {"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "malware--e4160979-b9bc-4f58-acbe-1d921ebbc122", "is_family": true, "modified": "2026-05-12T15:12:00.739Z", "name": "LazyWiper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LazyWiper"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1172', 0, 124, '09-mitre-attack', 'retrieved', '5D96234C116257D5B36710F4887A69EE213A037700B63FFFD7FDB702F0746FE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
