VALUES ('doc-09-mitre-attack-p0-1173', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DownPaper](https://attack.mitre.org/software/S0186) is a backdoor Trojan; its main functionality is to download and run second stage malware. (Citation: ClearSky Charming Kitten Dec 2017)", "external_references": [{"external_id": "S0186", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0186"}, {"description": "(Citation: ClearSky Charming Kitten Dec 2017)", "source_name": "DownPaper"}, {"description": "ClearSky Cyber Security. (2017, December). Charming Kitten. Retrieved December 27, 2017.", "source_name": "ClearSky Charming Kitten Dec 2017", "url": "http://www.clearskysec.com/wp-content/uploads/2017/12/Charming_Kitten_2017.pdf"}], "id": "malware--e48df773-7c95-4a4c-ba70-ea3d15900148", "is_family": true, "modified": "2025-04-25T14:44:56.608Z", "name": "DownPaper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DownPaper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1173', 0, 91, '09-mitre-attack', 'retrieved', '36A496AB9CB134A9A786132A2715420C222E08CBBBF35E882FE6E31039A8A83A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
