VALUES ('doc-09-mitre-attack-p0-1175', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-22T19:21:29.473Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pcexter](https://attack.mitre.org/software/S1102) is an uploader that has been used by [ToddyCat](https://attack.mitre.org/groups/G1022) since at least 2023 to exfiltrate stolen files.(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"external_id": "S1102", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1102"}, {"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "malware--e4feffc2-53d1-45c9-904e-adb9faca0d15", "is_family": true, "modified": "2024-01-22T19:21:48.480Z", "name": "Pcexter", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pcexter"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1175', 0, 93, '09-mitre-attack', 'retrieved', 'B2D0D025319FFA752647873FBCE107EC6DC345E12740FBE96DDE5BF96B68198A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
