VALUES ('doc-09-mitre-attack-p0-1176', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:17.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HIDEDRV](https://attack.mitre.org/software/S0135) is a rootkit used by [APT28](https://attack.mitre.org/groups/G0007). It has been deployed along with [Downdelph](https://attack.mitre.org/software/S0134) to execute and hide that malware. (Citation: ESET Sednit Part 3) (Citation: Sekoia HideDRV Oct 2016)", "external_references": [{"external_id": "S0135", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0135"}, {"description": "ESET. (2016, October). En Route with Sednit - Part 3: A Mysterious Downloader. Retrieved November 21, 2016.", "source_name": "ESET Sednit Part 3", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part3.pdf"}, {"description": "Rascagnères, P.. (2016, October 27). Rootkit analysis: Use case on HideDRV. Retrieved November 17, 2024.", "source_name": "Sekoia HideDRV Oct 2016", "url": "https://web.archive.org/web/20180202163754/http://www.sekoia.fr/blog/wp-content/uploads/2016/10/Rootkit-analysis-Use-case-on-HIDEDRV-v1.6.pdf"}], "id": "malware--e669bb87-f773-4c7b-bfcc-a9ffebfdd8d4", "is_family": true, "modified": "2024-11-17T18:07:17.216Z", "name": "HIDEDRV", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HIDEDRV"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1176', 0, 120, '09-mitre-attack', 'retrieved', 'C417EBBD0DBDA4211398E04C6C265F15599CC26CEBE76DAED621A6A8E6D476D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
