VALUES ('doc-09-mitre-attack-p0-1177', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:35.022Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CozyCar](https://attack.mitre.org/software/S0046) is malware that was used by [APT29](https://attack.mitre.org/groups/G0016) from 2010 to 2015. It is a modular malware platform, and its backdoor component can be instructed to download and execute a variety of modules with different functionality. (Citation: F-Secure The Dukes)", "external_references": [{"external_id": "S0046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0046"}, {"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "malware--e6ef745b-077f-42e1-a37d-29eecff9c754", "is_family": true, "modified": "2024-04-11T02:44:33.881Z", "name": "CozyCar", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CozyCar", "CozyDuke", "CozyBear", "Cozer", "EuroAPT"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1177', 0, 109, '09-mitre-attack', 'retrieved', '630368F9CC46BD10FD9A412E5C98C1F0BC0364DBB53ACDD9498493FF27B576CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
