VALUES ('doc-09-mitre-attack-p0-1178', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-14T14:27:43.651Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kevin](https://attack.mitre.org/software/S1020) is a backdoor implant written in C++ that has been used by [HEXANE](https://attack.mitre.org/groups/G1001) since at least June 2020, including in operations against organizations in Tunisia.(Citation: Kaspersky Lyceum October 2021)", "external_references": [{"external_id": "S1020", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1020"}, {"description": "Kayal, A. et al. (2021, October). LYCEUM REBORN: COUNTERINTELLIGENCE IN THE MIDDLE EAST. Retrieved June 14, 2022.", "source_name": "Kaspersky Lyceum October 2021", "url": "https://vblocalhost.com/uploads/VB2021-Kayal-etal.pdf"}], "id": "malware--e7863f5d-cb6a-4f81-8804-0a635eec160a", "is_family": true, "modified": "2024-04-17T22:07:06.736Z", "name": "Kevin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Kevin"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1178', 0, 97, '09-mitre-attack', 'retrieved', '8789498D2452B0579EEBCB6FBE74D505C1E0F8E82AF7624712006CEB51156CF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
