VALUES ('doc-09-mitre-attack-p0-1179', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T18:44:04.748Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agent Tesla](https://attack.mitre.org/software/S0331) is a spyware Trojan written for the .NET framework that has been observed since at least 2014.(Citation: Fortinet Agent Tesla April 2018)(Citation: Bitdefender Agent Tesla April 2020)(Citation: Malwarebytes Agent Tesla April 2020)", "external_references": [{"external_id": "S0331", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0331"}, {"description": "(Citation: Fortinet Agent Tesla April 2018)(Citation: Talos Agent Tesla Oct 2018)(Citation: DigiTrust Agent Tesla Jan 2017)", "source_name": "Agent Tesla"}, {"description": "Arsene, L. (2020, April 21). Oil & Gas Spearphishing Campaigns Drop Agent Tesla Spyware in Advance of Historic OPEC+ Deal. Retrieved May 19, 2020.", "source_name": "Bitdefender Agent Tesla April 2020", "url": "https://labs.bitdefender.com/2020/04/oil-gas-spearphishing-campaigns-drop-agent-tesla-spyware-in-advance-of-historic-opec-deal/"}, {"description": "Brumaghin, E., et al. (2018, October 15). Old dog, new tricks - Analysing new RTF-based campaign distributing Agent Tesla, Loki with PyREbox. Retrieved November 5, 2018.", "source_name": "Talos Agent Tesla Oct 2018", "url": "https://blog.talosintelligence.com/2018/10/old-dog-new-tricks-analysing-new-rtf_15.html"}, {"description": "Jazi, H. (2020, April 16). New AgentTesla variant steals WiFi credentials. Retrieved May 19, 2020.", "source_name": "Malwarebytes Agent Tesla April 2020", "url": "https://blog.malwarebytes.com/threat-analysis/2020/04/new-agenttesla-variant-steals-wifi-credentials/"}, {"description": "The DigiTrust Group. (2017, January 12). The Rise of Agent Tesla. Retrieved November 5, 2018.", "source_name": "DigiTrust Agent Tesla Jan 2017", "url": "https://www.digitrustgroup.com/agent-tesla-keylogger/"}, {"description": "Zhang, X. (2018, April 05). Analysis of New Agent Tesla Spyware Variant. Retrieved November 5, 2018.", "source_name": "Fortinet Agent Tesla April 2018", "url": "https://www.fortinet.com/blog/threat-research/analysis-of-new-agent-tesla-spyware-variant.html"}], "id": "malware--e7a5229f-05eb-440e-b982-9a6d2b2b87c8", "is_family": true, "modified": "2025-04-16T20:38:40.678Z", "name": "Agent Tesla", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Agent Tesla"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1179', 0, 239, '09-mitre-attack', 'retrieved', '334047A07EB0AFA799EA0CDD7B58CF0B2633915DAC07897E4EC4DD1F27932C0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
