VALUES ('doc-09-mitre-attack-p0-1180', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pasam](https://attack.mitre.org/software/S0208) is a trojan used by [Elderwood](https://attack.mitre.org/groups/G0066) to open a backdoor on compromised hosts. (Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Pasam May 2012)", "external_references": [{"external_id": "S0208", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0208"}, {"description": "(Citation: Symantec Pasam May 2012)", "source_name": "Pasam"}, {"description": "Mullaney, C. & Honda, H. (2012, May 4). Trojan.Pasam. Retrieved February 22, 2018.", "source_name": "Symantec Pasam May 2012", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2012-050412-4128-99"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}], "id": "malware--e811ff6a-4cef-4856-a6ae-a7daf9ed39ae", "is_family": true, "modified": "2025-10-21T23:00:57.240Z", "name": "Pasam", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Pasam"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1180', 0, 118, '09-mitre-attack', 'retrieved', '1BEC2C59768FAB21CEEE231D3FF3643749BEE7580D9A4C5C9BDF6992A32A90BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
