VALUES ('doc-09-mitre-attack-p0-1181', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:45.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[httpclient](https://attack.mitre.org/software/S0068) is malware used by [Putter Panda](https://attack.mitre.org/groups/G0024). It is a simple tool that provides a limited range of functionality, suggesting it is likely used as a second-stage or supplementary/backup tool. (Citation: CrowdStrike Putter Panda)", "external_references": [{"external_id": "S0068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0068"}, {"description": "Crowdstrike Global Intelligence Team. (2014, June 9). CrowdStrike Intelligence Report: Putter Panda. Retrieved January 22, 2016.", "source_name": "CrowdStrike Putter Panda", "url": "http://cdn0.vox-cdn.com/assets/4589853/crowdstrike-intelligence-report-putter-panda.original.pdf"}], "id": "malware--e8268361-a599-4e45-bd3f-71c8c7e700c0", "is_family": true, "modified": "2025-04-25T14:44:58.407Z", "name": "httpclient", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["httpclient"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1181', 0, 97, '09-mitre-attack', 'retrieved', 'C904AA8B81D780520A708D9FAF35EC58F9B68A42B6D1165491A034A8B796D670', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
