VALUES ('doc-09-mitre-attack-p0-1182', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[POWERSTATS](https://attack.mitre.org/software/S0223) is a PowerShell-based first stage backdoor used by [MuddyWater](https://attack.mitre.org/groups/G0069). (Citation: Unit 42 MuddyWater Nov 2017)", "external_references": [{"external_id": "S0223", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0223"}, {"description": "(Citation: Symantec MuddyWater Dec 2018)", "source_name": "Powermud"}, {"description": "(Citation: Unit 42 MuddyWater Nov 2017)(Citation: ClearSky MuddyWater Nov 2018)", "source_name": "POWERSTATS"}, {"description": "ClearSky Cyber Security. (2018, November). MuddyWater Operations in Lebanon and Oman: Using an Israeli compromised domain for a two-stage campaign. Retrieved November 29, 2018.", "source_name": "ClearSky MuddyWater Nov 2018", "url": "https://www.clearskysec.com/wp-content/uploads/2018/11/MuddyWater-Operations-in-Lebanon-and-Oman.pdf"}, {"description": "Lancaster, T.. (2017, November 14). Muddying the Water: Targeted Attacks in the Middle East. Retrieved March 15, 2018.", "source_name": "Unit 42 MuddyWater Nov 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/11/unit42-muddying-the-water-targeted-attacks-in-the-middle-east/"}, {"description": "Symantec DeepSight Adversary Intelligence Team. (2018, December 10). Seedworm: Group Compromises Government Agencies, Oil & Gas, NGOs, Telecoms, and IT Firms. Retrieved December 14, 2018.", "source_name": "Symantec MuddyWater Dec 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/seedworm-espionage-group"}], "id": "malware--e8545794-b98c-492b-a5b3-4b5a02682e37", "is_family": true, "modified": "2025-04-16T20:38:40.984Z", "name": "POWERSTATS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["POWERSTATS", "Powermud"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.3"}', 'kb-doc-09-mitre-attack-p0-1182', 0, 172, '09-mitre-attack', 'retrieved', '2C54F9DC828EC1A9F22A5A04081CB84DFC6CEE9F206085D7017E0D88DD96E201', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
