VALUES ('doc-09-mitre-attack-p0-1183', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-16T17:43:42.724Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[POWERTON](https://attack.mitre.org/software/S0371) is a custom PowerShell backdoor first observed in 2018. It has typically been deployed as a late-stage backdoor by [APT33](https://attack.mitre.org/groups/G0064). At least two variants of the backdoor have been identified, with the later version containing improved functionality.(Citation: FireEye APT33 Guardrail)", "external_references": [{"external_id": "S0371", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0371"}, {"description": "Ackerman, G., et al. (2018, December 21). OVERRULED: Containing a Potentially Destructive Adversary. Retrieved January 17, 2019.", "source_name": "FireEye APT33 Guardrail", "url": "https://www.fireeye.com/blog/threat-research/2018/12/overruled-containing-a-potentially-destructive-adversary.html"}], "id": "malware--e85cae1a-bce3-4ac4-b36b-b00acac0567b", "is_family": true, "modified": "2025-04-25T14:44:58.949Z", "name": "POWERTON", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["POWERTON"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1183', 0, 105, '09-mitre-attack', 'retrieved', '15B5A748A6697B3EF5E2D5C26B907761864D0782D87701AA93D2D7892587A407', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
