VALUES ('doc-09-mitre-attack-p0-1184', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-21T20:08:20.983Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StarProxy](https://attack.mitre.org/software/S1227) is custom malware used by [Mustang Panda](https://attack.mitre.org/groups/G0129) as a post-compromise tool, to enable proxying of traffic between the infected machine and other machines on the same network. (Citation: Zscaler)", "external_references": [{"external_id": "S1227", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1227"}, {"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: ToneShell and StarProxy | P1. Retrieved July 21, 2025.", "source_name": "Zscaler", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-toneshell-and-starproxy-p1"}], "id": "malware--e91d3543-ca5d-474b-8b20-5a753ebc6e49", "is_family": true, "modified": "2025-10-21T22:47:13.304Z", "name": "StarProxy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["StarProxy"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["YH Chang, ZScaler", "ZScaler"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1184', 0, 100, '09-mitre-attack', 'retrieved', 'B8A33969E73C128B069C92506C0DA54177D8974F164A7F35DE99A20CEC83836A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
