VALUES ('doc-09-mitre-attack-p0-1186', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:14.118Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BADNEWS](https://attack.mitre.org/software/S0128) is malware that has been used by the actors responsible for the [Patchwork](https://attack.mitre.org/groups/G0040) campaign. Its name was given due to its use of RSS feeds, forums, and blogs for command and control. (Citation: Forcepoint Monsoon) (Citation: TrendMicro Patchwork Dec 2017)", "external_references": [{"external_id": "S0128", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0128"}, {"description": "(Citation: Forcepoint Monsoon)", "source_name": "BADNEWS"}, {"description": "Settle, A., et al. (2016, August 8). MONSOON - Analysis Of An APT Campaign. Retrieved September 22, 2016.", "source_name": "Forcepoint Monsoon", "url": "https://www.forcepoint.com/sites/default/files/resources/files/forcepoint-security-labs-monsoon-analysis-report.pdf"}, {"description": "Lunghi, D., et al. (2017, December). Untangling the Patchwork Cyberespionage Group. Retrieved July 10, 2018.", "source_name": "TrendMicro Patchwork Dec 2017", "url": "https://documents.trendmicro.com/assets/tech-brief-untangling-the-patchwork-cyberespionage-group.pdf"}], "id": "malware--e9595678-d269-469e-ae6b-75e49259de63", "is_family": true, "modified": "2025-04-25T14:44:59.677Z", "name": "BADNEWS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BADNEWS"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1186', 0, 134, '09-mitre-attack', 'retrieved', 'EBE6E7C5C54F1D8AA33B5AD88411B931C00DFCD8A1BDEB406A887CD5A76B5F15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
