VALUES ('doc-09-mitre-attack-p0-1187', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-14T13:25:25.776Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DRYHOOK](https://attack.mitre.org/software/S9013) is Python script used to steal credentials. [DRYHOOK](https://attack.mitre.org/software/S9013) was first reported in January 2025, and has previously been leveraged by People''s Republic of China (PRC) state-affiliated threat actors identified as UNC5221 and SYLVANITE.(Citation: Dragos SYLVANITE MuddyWater Electrum March 2026)(Citation: Google UNC5221 Ivanti January 2025)(Citation: Picus Security UNC5221 Ivanti May 2025)", "external_references": [{"external_id": "S9013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9013"}, {"description": "Dragos. (2026, March 24). Dragos 2026 OT Cybersecurity Report: Year in Review, O&G and Petrochemicals Focus. Retrieved April 17, 2026.", "source_name": "Dragos SYLVANITE MuddyWater Electrum March 2026", "url": "https://hub.dragos.com/hubfs/2026_YIR_ExecutiveBriefing%20O_G.pdf?hsLang=en"}, {"description": "John Wolfram, Josh Murchie, Matt Lin, Daniel Ainsworth, Robert Wallace, Dimiter Andonov, Dhanesh Kizhakkinan, Jacob Thompson. (2025, January 8). Ivanti Connect Secure VPN Targeted in New Zero-Day Exploitation. Retrieved April 14, 2026.", "source_name": "Google UNC5221 Ivanti January 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-connect-secure-vpn-zero-day"}, {"description": "Sila Ozeren Hacioglu. (2025, May 5). UNC5221’s Latest Exploit: Weaponizing CVE-2025-22457 in Ivanti Connect Secure. Retrieved April 13, 2026.", "source_name": "Picus Security UNC5221 Ivanti May 2025", "url": "https://www.picussecurity.com/resource/blog/unc5221-cve-2025-22457-ivanti-connect-secure"}], "id": "malware--e9c72c02-b55a-4852-b2eb-c7031d215414", "is_family": true, "modified": "2026-04-23T03:09:34.005Z", "name": "DRYHOOK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DRYHOOK"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dragos Threat Intelligence"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1187', 0, 199, '09-mitre-attack', 'retrieved', '1492F945AAD7BEAC99EC75F68365C8DB472C7E7DB48935479ACFAE1E33266B74', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
