VALUES ('doc-09-mitre-attack-p0-1188', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Linfo](https://attack.mitre.org/software/S0211) is a rootkit trojan used by [Elderwood](https://attack.mitre.org/groups/G0066) to open a backdoor on compromised hosts. (Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Linfo May 2012)", "external_references": [{"external_id": "S0211", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0211"}, {"description": "(Citation: Symantec Linfo May 2012)", "source_name": "Linfo"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}, {"description": "Zhou, R. (2012, May 15). Backdoor.Linfo. Retrieved February 23, 2018.", "source_name": "Symantec Linfo May 2012", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2012-051605-2535-99"}], "id": "malware--e9e9bfe2-76f4-4870-a2a1-b7af89808613", "is_family": true, "modified": "2024-11-17T19:55:07.593Z", "name": "Linfo", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Linfo"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1188', 0, 116, '09-mitre-attack', 'retrieved', 'FBC3C482AE43325B6117FACD01E97326B58305A86BC30AF8721FF2708DCFF16F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
