VALUES ('doc-09-mitre-attack-p0-1190', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-23T20:49:39.954Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShadowPad](https://attack.mitre.org/software/S0596) is a modular backdoor that was first identified in a supply chain compromise of the NetSarang software in mid-July 2017. The malware was originally thought to be exclusively used by [APT41](https://attack.mitre.org/groups/G0096), but has since been observed to be used by various Chinese threat activity groups. (Citation: Recorded Future RedEcho Feb 2021)(Citation: Securelist ShadowPad Aug 2017)(Citation: Kaspersky ShadowPad Aug 2017) ", "external_references": [{"external_id": "S0596", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0596"}, {"description": "(Citation: FireEye APT41 Aug 2019)", "source_name": "POISONPLUG.SHADOW"}, {"description": "Fraser, N., et al. (2019, August 7). Double DragonAPT41, a dual espionage and cyber crime operation APT41. Retrieved September 23, 2019.", "source_name": "FireEye APT41 Aug 2019", "url": "https://www.mandiant.com/sites/default/files/2022-02/rt-apt41-dual-operation.pdf"}, {"description": "GReAT. (2017, August 15). ShadowPad in corporate networks. Retrieved March 22, 2021.", "source_name": "Securelist ShadowPad Aug 2017", "url": "https://securelist.com/shadowpad-in-corporate-networks/81432/"}, {"description": "Insikt Group. (2021, February 28). China-Linked Group RedEcho Targets the Indian Power Sector Amid Heightened Border Tensions. Retrieved March 22, 2021.", "source_name": "Recorded Future RedEcho Feb 2021", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2021-0228.pdf"}, {"description": "Kaspersky Lab. (2017, August). ShadowPad: popular server management software hit in supply chain attack. Retrieved March 22, 2021.", "source_name": "Kaspersky ShadowPad Aug 2017", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2017/08/07172148/ShadowPad_technical_description_PDF.pdf"}], "id": "malware--ec9e00dd-0313-4d5b-8105-c20aa47abffc", "is_family": true, "modified": "2025-10-22T03:18:16.948Z", "name": "ShadowPad", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["ShadowPad", "POISONPLUG.SHADOW"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1190', 0, 217, '09-mitre-attack', 'retrieved', '440B1BAA49452227180895666FC57EF8A6B64E2DF12FBB84CC70D4B99E165DEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
