VALUES ('doc-09-mitre-attack-p0-1191', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-17T19:18:00.270Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Remexi](https://attack.mitre.org/software/S0375) is a Windows-based Trojan that was developed in the C programming language.(Citation: Securelist Remexi Jan 2019)", "external_references": [{"external_id": "S0375", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0375"}, {"description": "Legezo, D. (2019, January 30). Chafer used Remexi malware to spy on Iran-based foreign diplomatic entities. Retrieved April 17, 2019.", "source_name": "Securelist Remexi Jan 2019", "url": "https://securelist.com/chafer-used-remexi-malware/89538/"}], "id": "malware--ecc2f65a-b452-4eaf-9689-7e181f17f7a5", "is_family": true, "modified": "2024-04-11T00:17:12.008Z", "name": "Remexi", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Remexi"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1191', 0, 87, '09-mitre-attack', 'retrieved', '0110A0B3CF86BC032A5593EF2A1A4A89E321F1B5F589B9F67C10B933CB6EA839', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
