VALUES ('doc-09-mitre-attack-p0-1192', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-17T13:46:38.565Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Astaroth](https://attack.mitre.org/software/S0373) is a Trojan and information stealer known to affect companies in Europe, Brazil, and throughout Latin America. It has been known publicly since at least late 2017. (Citation: Cybereason Astaroth Feb 2019)(Citation: Cofense Astaroth Sept 2018)(Citation: Securelist Brazilian Banking Malware July 2020)", "external_references": [{"external_id": "S0373", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0373"}, {"description": "(Citation: Securelist Brazilian Banking Malware July 2020)", "source_name": "Guildma"}, {"description": "Doaty, J., Garrett, P.. (2018, September 10). We’re Seeing a Resurgence of the Demonic Astaroth WMIC Trojan. Retrieved September 25, 2024.", "source_name": "Cofense Astaroth Sept 2018", "url": "https://web.archive.org/web/20200302071436/https://cofense.com/seeing-resurgence-demonic-astaroth-wmic-trojan/"}, {"description": "GReAT. (2020, July 14). The Tetrade: Brazilian banking malware goes global. Retrieved November 9, 2020.", "source_name": "Securelist Brazilian Banking Malware July 2020", "url": "https://securelist.com/the-tetrade-brazilian-banking-malware/97779/"}, {"description": "Salem, E. (2019, February 13). ASTAROTH MALWARE USES LEGITIMATE OS AND ANTIVIRUS PROCESSES TO STEAL PASSWORDS AND PERSONAL DATA. Retrieved April 17, 2019.", "source_name": "Cybereason Astaroth Feb 2019", "url": "https://www.cybereason.com/blog/information-stealing-malware-targeting-brazil-full-research"}], "id": "malware--edb24a93-1f7a-4bbf-a738-1397a14662c6", "is_family": true, "modified": "2024-09-25T15:03:49.408Z", "name": "Astaroth", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Astaroth", "Guildma"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Carlos Borges, @huntingneo, CIP"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.3"}', 'kb-doc-09-mitre-attack-p0-1192', 0, 186, '09-mitre-attack', 'retrieved', '64B394F40563ABF2553284A6EFA210BB8DFE16D2002A06010BDD5CBE20C791D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
