VALUES ('doc-09-mitre-attack-p0-1193', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-27T19:35:35.326Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QakBot](https://attack.mitre.org/software/S0650) is a modular banking trojan that has been used primarily by financially-motivated actors since at least 2007. [QakBot](https://attack.mitre.org/software/S0650) is continuously maintained and developed and has evolved from an information stealer into a delivery agent for ransomware, most notably [ProLock](https://attack.mitre.org/software/S0654) and [Egregor](https://attack.mitre.org/software/S0554).(Citation: Trend Micro Qakbot December 2020)(Citation: Red Canary Qbot)(Citation: Kaspersky QakBot September 2021)(Citation: ATT QakBot April 2021)", "external_references": [{"external_id": "S0650", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0650"}, {"description": "(Citation: Kaspersky QakBot September 2021)", "source_name": "QuackBot"}, {"description": "(Citation: Kaspersky QakBot September 2021)(Citation: ATT QakBot April 2021)", "source_name": "Pinkslipbot"}, {"description": "(Citation: Trend Micro Qakbot December 2020)(Citation: Red Canary Qbot)(Citation: Kaspersky QakBot September 2021)(Citation: ATT QakBot April 2021)", "source_name": "QBot"}, {"description": "Kuzmenko, A. et al. (2021, September 2). QakBot technical analysis. Retrieved September 27, 2021.", "source_name": "Kaspersky QakBot September 2021", "url": "https://securelist.com/qakbot-technical-analysis/103931/"}, {"description": "Morrow, D. (2021, April 15). The rise of QakBot. Retrieved September 27, 2021.", "source_name": "ATT QakBot April 2021", "url": "https://cybersecurity.att.com/blogs/labs-research/the-rise-of-qakbot"}, {"description": "Rainey, K. (n.d.). Qbot. Retrieved September 27, 2021.", "source_name": "Red Canary Qbot", "url": "https://redcanary.com/threat-detection-report/threats/qbot/"}, {"description": "Trend Micro. (2020, December 17). QAKBOT: A decade-old malware still with new tricks. Retrieved November 17, 2024.", "source_name": "Trend Micro Qakbot December 2020", "url": "https://success.trendmicro.com/en-US/solution/KA-0011282"}], "id": "malware--edc5e045-5401-42bb-ad92-52b5b2ee0de9", "is_family": true, "modified": "2024-11-17T13:02:32.758Z", "name": "QakBot", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["QakBot", "Pinkslipbot", "QuackBot", "QBot"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Edward Millington", "Inna Danilevich, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1193', 0, 234, '09-mitre-attack', 'retrieved', '5B36767AD8B7AA774158306946BEC3CB34714DD090A82BDEDBFE5A833E5F0BC0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
