VALUES ('doc-09-mitre-attack-p0-1194', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T16:31:22.126Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DOWNIISSA](https://attack.mitre.org/software/S9021) is a shellcode downloader that has been used by [MirrorFace](https://attack.mitre.org/groups/G1054) since at least 2022 to deploy payloads, including the [LODEINFO](https://attack.mitre.org/software/S9020) backdoor.(Citation: Kaspersky LODEINFO OCT 2022)", "external_references": [{"external_id": "S9021", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9021"}, {"description": "Ishimaru, S. (2022, October 31). APT10: Tracking down LODEINFO 2022, part I. Retrieved April 17, 2026.", "source_name": "Kaspersky LODEINFO OCT 2022", "url": "https://securelist.com/apt10-tracking-down-lodeinfo-2022-part-i/107742/"}], "id": "malware--eddb863e-fc77-41c1-86e9-5210d6d58b88", "is_family": true, "modified": "2026-04-24T02:30:38.822Z", "name": "DOWNIISSA", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["DOWNIISSA"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dominik Breitenbacher, ESET"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1194', 0, 96, '09-mitre-attack', 'retrieved', '676B8CB515084FD34570136A510A1F526B848349F16A4F069AAFD39C119D65F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
