VALUES ('doc-09-mitre-attack-p0-1196', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-06T21:22:59.796Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Crocodilus](https://attack.mitre.org/software/S9004) is an Android banking Trojan that was discovered in March 2025. [Crocodilus](https://attack.mitre.org/software/S9004) targeted users worldwide, including Turkey, Poland, Argentina, Brazil, Spain, the United States, Indonesia and India. [Crocodilus](https://attack.mitre.org/software/S9004) has been customized based on the target location. For example, [Crocodilus](https://attack.mitre.org/software/S9004) mimicked major Turkish and Spanish banks for users in Turkey and Spain, while users in Poland saw Facebook advertisements that promoted [Crocodilus](https://attack.mitre.org/software/S9004) to claim bonus points.(Citation: ThreatFabric_Crocodilus_March2025)(Citation: ThreatFabric_Crocodilus_June2025) ", "external_references": [{"external_id": "S9004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9004"}, {"description": "ThreatFabric. (2025, June 3). Crocodilus Mobile Malware: Evolving Fast, Going Global. Retrieved November 24, 2025.", "source_name": "ThreatFabric_Crocodilus_June2025", "url": "https://www.threatfabric.com/blogs/crocodilus-mobile-malware-evolving-fast-going-global"}, {"description": "ThreatFabric. (2025, March 28). Exposing Crocodilus: New Device Takeover Malware Targeting Android Devices. Retrieved November 24, 2025.", "source_name": "ThreatFabric_Crocodilus_March2025", "url": "https://www.threatfabric.com/blogs/exposing-crocodilus-new-device-takeover-malware-targeting-android-devices"}], "id": "malware--eed7b988-0279-4c4f-bfa9-d81f5444a04b", "is_family": true, "modified": "2026-04-23T03:24:47.669Z", "name": "Crocodilus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Crocodilus"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Liran Ravich, CardinalOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["mobile-attack", "enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Android"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1196', 0, 158, '09-mitre-attack', 'retrieved', '086079402FB26B2B6B1EE423F55A190756CBA558EBB82A599B3DDE9E4828DBB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
