VALUES ('doc-09-mitre-attack-p0-1197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-22T19:00:00.779Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CookieMiner](https://attack.mitre.org/software/S0492) is mac-based malware that targets information associated with cryptocurrency exchanges as well as enabling cryptocurrency mining on the victim system itself. It was first discovered in the wild in 2019.(Citation: Unit42 CookieMiner Jan 2019)", "external_references": [{"external_id": "S0492", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0492"}, {"description": "Chen, y., et al. (2019, January 31). Mac Malware Steals Cryptocurrency Exchanges’ Cookies. Retrieved July 22, 2020.", "source_name": "Unit42 CookieMiner Jan 2019", "url": "https://unit42.paloaltonetworks.com/mac-malware-steals-cryptocurrency-exchanges-cookies/"}], "id": "malware--eedc01d5-95e6-4d21-bcd4-1121b1df4586", "is_family": true, "modified": "2025-04-16T20:38:42.106Z", "name": "CookieMiner", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CookieMiner"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1197', 0, 102, '09-mitre-attack', 'retrieved', '37DB4076626C072EC32BD93346B30A033E266C66AB885C15AAAF67ACE74362DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
