VALUES ('doc-09-mitre-attack-p0-1198', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-12T19:32:56.301Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hancitor](https://attack.mitre.org/software/S0499) is a downloader that has been used by [Pony](https://attack.mitre.org/software/S0453) and other information stealing malware.(Citation: Threatpost Hancitor)(Citation: FireEye Hancitor)", "external_references": [{"external_id": "S0499", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0499"}, {"description": "(Citation: FireEye Hancitor)", "source_name": "Chanitor"}, {"description": "Tom Spring. (2017, January 11). Spammers Revive Hancitor Downloader Campaigns. Retrieved August 13, 2020.", "source_name": "Threatpost Hancitor", "url": "https://threatpost.com/spammers-revive-hancitor-downloader-campaigns/123011/"}, {"description": "Anubhav, A., Jallepalli, D. (2016, September 23). Hancitor (AKA Chanitor) observed using multiple attack approaches. Retrieved August 13, 2020.", "source_name": "FireEye Hancitor", "url": "https://www.fireeye.com/blog/threat-research/2016/09/hancitor_aka_chanit.html"}], "id": "malware--ef2247bf-8062-404b-894f-d65d00564817", "is_family": true, "modified": "2025-04-25T14:45:01.455Z", "name": "Hancitor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Hancitor", "Chanitor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1198', 0, 111, '09-mitre-attack', 'retrieved', '4900AAF319A156C00EA911601BBCC5E6F39E15FCAB5CDFDBF0DD3EBC2964927F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
