VALUES ('doc-09-mitre-attack-p0-1199', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-30T19:02:16.138Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gelsemium](https://attack.mitre.org/software/S0666) is a modular malware comprised of a dropper (Gelsemine), a loader (Gelsenicine), and main (Gelsevirine) plug-ins written using the Microsoft Foundation Class (MFC) framework. [Gelsemium](https://attack.mitre.org/software/S0666) has been used by the Gelsemium group since at least 2014.(Citation: ESET Gelsemium June 2021)", "external_references": [{"external_id": "S0666", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0666"}, {"description": "(Citation: ESET Gelsemium June 2021)", "source_name": "Gelsevirine"}, {"description": "(Citation: ESET Gelsemium June 2021)", "source_name": "Gelsenicine"}, {"description": "(Citation: ESET Gelsemium June 2021)", "source_name": "Gelsemine"}, {"description": "Dupuy, T. and Faou, M. (2021, June). Gelsemium. Retrieved November 30, 2021.", "source_name": "ESET Gelsemium June 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/06/eset_gelsemium.pdf"}], "id": "malware--efa7c4d6-8e30-41d9-a8fd-26dc337f4a1b", "is_family": true, "modified": "2024-04-11T02:28:01.735Z", "name": "Gelsemium", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Gelsemium", "Gelsevirine", "Gelsenicine", "Gelsemine"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1199', 0, 130, '09-mitre-attack', 'retrieved', '77E7395D49C13B8F95A455B1999634B2343B2CBFE1814C968D01C0ADAB852935', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
