VALUES ('doc-09-mitre-attack-p0-1200', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[jRAT](https://attack.mitre.org/software/S0283) is a cross-platform, Java-based backdoor originally available for purchase in 2012. Variants of [jRAT](https://attack.mitre.org/software/S0283) have been distributed via a software-as-a-service platform, similar to an online subscription model.(Citation: Kaspersky Adwind Feb 2016) (Citation: jRAT Symantec Aug 2018)", "external_references": [{"external_id": "S0283", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0283"}, {"description": "(Citation: jRAT Symantec Aug 2018)", "source_name": "jRAT"}, {"description": "(Citation: jRAT Symantec Aug 2018)", "source_name": "Trojan.Maljava"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "JSocket"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "AlienSpy"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "Frutas"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "Sockrat"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "Unrecom"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "jFrutas"}, {"description": "(Citation: Kaspersky Adwind Feb 2016)", "source_name": "Adwind"}, {"description": "(Citation: NCSC Joint Report Public Tools)", "source_name": "jBiFrost"}, {"description": "Kamluk, V. & Gostev, A. (2016, February). Adwind - A Cross-Platform RAT. Retrieved April 23, 2019.", "source_name": "Kaspersky Adwind Feb 2016", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07195002/KL_AdwindPublicReport_2016.pdf"}, {"description": "Sharma, R. (2018, August 15). Revamped jRAT Uses New Anti-Parsing Techniques. Retrieved September 21, 2018.", "source_name": "jRAT Symantec Aug 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/jrat-new-anti-parsing-techniques"}, {"description": "The Australian Cyber Security Centre (ACSC), the Canadian Centre for Cyber Security (CCCS), the New Zealand National Cyber Security Centre (NZ NCSC), CERT New Zealand, the UK National Cyber Security Centre (UK NCSC) and the US National Cybersecurity and Communications Integration Center (NCCIC). (2018, October 11). Joint report on publicly available hacking tools. Retrieved March 11, 2019.", "source_name": "NCSC Joint Report Public Tools", "url": "https://www.ncsc.gov.uk/report/joint-report-on-publicly-available-hacking-tools"}], "id": "malware--efece7e8-e40b-49c2-9f84-c55c5c93d05c", "is_family": true, "modified": "2023-10-03T19:38:43.114Z", "name": "jRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["jRAT", "JSocket", "AlienSpy", "Frutas", "Sockrat", "Unrecom", "jFrutas", "Adwind", "jBiFrost", "Trojan.Maljava"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows", "macOS", "Android"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-1200', 0, 285, '09-mitre-attack', 'retrieved', '087D5D7036CD11A7372FEDC07C8C908700654BA835213BBC8FD201EB3DC18E4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
