VALUES ('doc-09-mitre-attack-p0-1201', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Helminth](https://attack.mitre.org/software/S0170) is a backdoor that has at least two variants - one written in VBScript and PowerShell that is delivered via a macros in Excel spreadsheets, and one that is a standalone Windows executable. (Citation: Palo Alto OilRig May 2016)", "external_references": [{"external_id": "S0170", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0170"}, {"description": "(Citation: Palo Alto OilRig May 2016)", "source_name": "Helminth"}, {"description": "Falcone, R. and Lee, B.. (2016, May 26). The OilRig Campaign: Attacks on Saudi Arabian Organizations Deliver Helminth Backdoor. Retrieved May 3, 2017.", "source_name": "Palo Alto OilRig May 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/05/the-oilrig-campaign-attacks-on-saudi-arabian-organizations-deliver-helminth-backdoor/"}], "id": "malware--eff1a885-6f90-42a1-901f-eef6e7a1905e", "is_family": true, "modified": "2024-04-11T02:22:38.177Z", "name": "Helminth", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Helminth"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Robert Falcone"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1201', 0, 126, '09-mitre-attack', 'retrieved', 'D830CC11D9163B5C2655CFC61D5A20DB1DEA9917528F4ABDECD189B24B377C41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
