VALUES ('doc-09-mitre-attack-p0-1202', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-05-30T19:47:37.192Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dridex](https://attack.mitre.org/software/S0384) is a prolific banking Trojan that first appeared in 2014. By December 2019, the US Treasury estimated [Dridex](https://attack.mitre.org/software/S0384) had infected computers in hundreds of banks and financial institutions in over 40 countries, leading to more than $100 million in theft. [Dridex](https://attack.mitre.org/software/S0384) was created from the source code of the Bugat banking Trojan (also known as Cridex).(Citation: Dell Dridex Oct 2015)(Citation: Kaspersky Dridex May 2017)(Citation: Treasury EvilCorp Dec 2019)", "external_references": [{"external_id": "S0384", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0384"}, {"description": "(Citation: Dell Dridex Oct 2015)", "source_name": "Bugat v5"}, {"description": "(Citation: Dell Dridex Oct 2015)(Citation: Kaspersky Dridex May 2017)(Citation: Checkpoint Dridex Jan 2021)", "source_name": "Dridex"}, {"description": "Check Point Research. (2021, January 4). Stopping Serial Killer: Catching the Next Strike. Retrieved September 7, 2021.", "source_name": "Checkpoint Dridex Jan 2021", "url": "https://research.checkpoint.com/2021/stopping-serial-killer-catching-the-next-strike/"}, {"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, October 13). Dridex (Bugat v5) Botnet Takeover Operation. Retrieved May 31, 2019.", "source_name": "Dell Dridex Oct 2015", "url": "https://www.secureworks.com/research/dridex-bugat-v5-botnet-takeover-operation"}, {"description": "Slepogin, N. (2017, May 25). Dridex: A History of Evolution. Retrieved May 31, 2019.", "source_name": "Kaspersky Dridex May 2017", "url": "https://securelist.com/dridex-a-history-of-evolution/78531/"}, {"description": "U.S. Department of Treasury. (2019, December 5). Treasury Sanctions Evil Corp, the Russia-Based Cybercriminal Group Behind Dridex Malware. Retrieved September 15, 2021.", "source_name": "Treasury EvilCorp Dec 2019", "url": "https://home.treasury.gov/news/press-releases/sm845"}], "id": "malware--f01e2711-4b48-4192-a2e8-5f56c945ca19", "is_family": true, "modified": "2025-04-16T20:38:42.420Z", "name": "Dridex", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Dridex", "Bugat v5"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security", "Jennifer Kim Roman, CrowdStrike"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-1202', 0, 252, '09-mitre-attack', 'retrieved', '7A4CE90BAD61B6479FC6D317FFC4C9CD48131CBA916322B65BEF27E4F92003E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
