VALUES ('doc-09-mitre-attack-p0-1203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-10T18:00:28.497Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BBK](https://attack.mitre.org/software/S0470) is a downloader that has been used by [BRONZE BUTLER](https://attack.mitre.org/groups/G0060) since at least 2019.(Citation: Trend Micro Tick November 2019)", "external_references": [{"external_id": "S0470", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0470"}, {"description": "Chen, J. et al. (2019, November). Operation ENDTRADE: TICK’s Multi-Stage Backdoors for Attacking Industries and Stealing Classified Data. Retrieved June 9, 2020.", "source_name": "Trend Micro Tick November 2019", "url": "https://documents.trendmicro.com/assets/pdf/Operation-ENDTRADE-TICK-s-Multi-Stage-Backdoors-for-Attacking-Industries-and-Stealing-Classified-Data.pdf"}], "id": "malware--f0fc920e-57a3-4af5-89be-9ea594c8b1ea", "is_family": true, "modified": "2025-04-25T14:45:02.531Z", "name": "BBK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BBK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1203', 0, 91, '09-mitre-attack', 'retrieved', 'DE988AFDA12A3341A146A1D8BEBE0B23E4DA2A8E4ABF55F9D0C724C7C00C6F6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
