VALUES ('doc-09-mitre-attack-p0-1205', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-29T18:52:20.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX/Shlayer](https://attack.mitre.org/software/S0402) is a Trojan designed to install adware on macOS that was first discovered in 2018.(Citation: Carbon Black Shlayer Feb 2019)(Citation: Intego Shlayer Feb 2018)", "external_references": [{"external_id": "S0402", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0402"}, {"description": "(Citation: Carbon Black Shlayer Feb 2019)(Citation: Intego Shlayer Feb 2018)", "source_name": "OSX/Shlayer"}, {"description": "(Citation: Intego Shlayer Apr 2018)(Citation: Malwarebytes Crossrider Apr 2018)", "source_name": "Crossrider"}, {"description": "(Citation: sentinelone shlayer to zshlayer)", "source_name": "Zshlayer"}, {"description": "Carbon Black Threat Analysis Unit. (2019, February 12). New macOS Malware Variant of Shlayer (OSX) Discovered. Retrieved August 8, 2019.", "source_name": "Carbon Black Shlayer Feb 2019", "url": "https://blogs.vmware.com/security/2020/02/vmware-carbon-black-tau-threat-analysis-shlayer-macos.html"}, {"description": "Long, Joshua. (2018, February 21). OSX/Shlayer: New Mac malware comes out of its shell. Retrieved August 28, 2019.", "source_name": "Intego Shlayer Feb 2018", "url": "https://www.intego.com/mac-security-blog/osxshlayer-new-mac-malware-comes-out-of-its-shell/"}, {"description": "Phil Stokes. (2020, September 8). Coming Out of Your Shell: From Shlayer to ZShlayer. Retrieved September 13, 2021.", "source_name": "sentinelone shlayer to zshlayer", "url": "https://www.sentinelone.com/blog/coming-out-of-your-shell-from-shlayer-to-zshlayer/"}, {"description": "Reed, Thomas. (2018, April 24). New Crossrider variant installs configuration profiles on Macs. Retrieved September 6, 2019.", "source_name": "Malwarebytes Crossrider Apr 2018", "url": "https://blog.malwarebytes.com/threat-analysis/2018/04/new-crossrider-variant-installs-configuration-profiles-on-macs/"}, {"description": "Vrijenhoek, Jay. (2018, April 24). New OSX/Shlayer Malware Variant Found Using a Dirty New Trick. Retrieved September 6, 2019.", "source_name": "Intego Shlayer Apr 2018", "url": "https://www.intego.com/mac-security-blog/new-osxshlayer-malware-variant-found-using-a-dirty-new-trick/"}], "id": "malware--f1314e75-ada8-49f4-b281-b1fb8b48f2a7", "is_family": true, "modified": "2025-04-16T20:38:42.935Z", "name": "OSX/Shlayer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["OSX/Shlayer", "Zshlayer", "Crossrider"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1205', 0, 235, '09-mitre-attack', 'retrieved', '3352759F2CD587C2C62605B7871D2CD3FC153BD9FA0A9345B32379E6B5CA19E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
