VALUES ('doc-09-mitre-attack-p0-1206', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T20:01:44.815Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Denis](https://attack.mitre.org/software/S0354) is a Windows backdoor and Trojan used by [APT32](https://attack.mitre.org/groups/G0050). [Denis](https://attack.mitre.org/software/S0354) shares several similarities to the [SOUNDBITE](https://attack.mitre.org/software/S0157) backdoor and has been used in conjunction with the [Goopy](https://attack.mitre.org/software/S0477) backdoor.(Citation: Cybereason Oceanlotus May 2017)", "external_references": [{"external_id": "S0354", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0354"}, {"description": "(Citation: Cybereason Oceanlotus May 2017)", "source_name": "Denis"}, {"description": "Dahan, A. (2017, May 24). OPERATION COBALT KITTY: A LARGE-SCALE APT IN ASIA CARRIED OUT BY THE OCEANLOTUS GROUP. Retrieved November 5, 2018.", "source_name": "Cybereason Oceanlotus May 2017", "url": "https://www.cybereason.com/blog/operation-cobalt-kitty-apt"}], "id": "malware--f25aab1a-0cef-4910-a85d-bb38b32ea41a", "is_family": true, "modified": "2025-04-16T20:38:43.085Z", "name": "Denis", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Denis"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1206', 0, 113, '09-mitre-attack', 'retrieved', '63D8B7EB711423F5F294EE2A7BEC3AD6D46074773F739A30D1A009D54CC4BE71', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
