VALUES ('doc-09-mitre-attack-p0-1207', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-06T18:28:58.878Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[INC Ransomware](https://attack.mitre.org/software/S1139) is a ransomware strain that has been used by the [INC Ransom](https://attack.mitre.org/groups/G1032) group since at least 2023 against multiple industry sectors worldwide. [INC Ransomware](https://attack.mitre.org/software/S1139) can employ partial encryption combined with multi-threading to speed encryption.(Citation: SentinelOne INC Ransomware)(Citation: Huntress INC Ransom Group August 2023)(Citation: Secureworks GOLD IONIC April 2024)", "external_references": [{"external_id": "S1139", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1139"}, {"description": "Counter Threat Unit Research Team. (2024, April 15). GOLD IONIC DEPLOYS INC RANSOMWARE. Retrieved June 5, 2024.", "source_name": "Secureworks GOLD IONIC April 2024", "url": "https://www.secureworks.com/blog/gold-ionic-deploys-inc-ransomware"}, {"description": "SentinelOne. (n.d.). What Is Inc. Ransomware?. Retrieved June 5, 2024.", "source_name": "SentinelOne INC Ransomware", "url": "https://www.sentinelone.com/anthology/inc-ransom/"}, {"description": "Team Huntress. (2023, August 11). Investigating New INC Ransom Group Activity. Retrieved June 5, 2024.", "source_name": "Huntress INC Ransom Group August 2023", "url": "https://www.huntress.com/blog/investigating-new-inc-ransom-group-activity"}], "id": "malware--f25d4207-25b2-4bb0-a17a-403943c670ad", "is_family": true, "modified": "2024-10-28T19:03:40.175Z", "name": "INC Ransomware", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["INC Ransomware"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Matt Anderson, @‌nosecurething, Huntress"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1207', 0, 167, '09-mitre-attack', 'retrieved', '6FB411EB6232E23464748642625F0A727E053CD4FD2B39409CC59E1263A9DD96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
