VALUES ('doc-09-mitre-attack-p0-1209', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:20.526Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GLOOXMAIL](https://attack.mitre.org/software/S0026) is malware used by [APT1](https://attack.mitre.org/groups/G0006) that mimics legitimate Jabber/XMPP traffic. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0026"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "malware--f2e8c7a1-cae1-45c4-baf0-6f21bdcbb2c2", "is_family": true, "modified": "2024-08-28T14:16:00.884Z", "name": "GLOOXMAIL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["GLOOXMAIL", "Trojan.GTALK"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1209', 0, 77, '09-mitre-attack', 'retrieved', '6C8E6435D74BE8DF4481D47B53FA7C254EF743345FF626D352D399768364DEEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
