VALUES ('doc-09-mitre-attack-p0-1212', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-22T16:35:33.673Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Waterbear](https://attack.mitre.org/software/S0579) is modular malware attributed to [BlackTech](https://attack.mitre.org/groups/G0098) that has been used primarily for lateral movement, decrypting, and triggering payloads and is capable of hiding network behaviors.(Citation: Trend Micro Waterbear December 2019)", "external_references": [{"external_id": "S0579", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0579"}, {"description": "(Citation: Trend Micro Waterbear December 2019)", "source_name": "Waterbear"}, {"description": "Su, V. et al. (2019, December 11). Waterbear Returns, Uses API Hooking to Evade Security. Retrieved February 22, 2021.", "source_name": "Trend Micro Waterbear December 2019", "url": "https://www.trendmicro.com/en_us/research/19/l/waterbear-is-back-uses-api-hooking-to-evade-security-product-detection.html"}], "id": "malware--f3f1fbed-7e29-49cb-8579-4a378f858deb", "is_family": true, "modified": "2024-04-10T22:14:28.440Z", "name": "Waterbear", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Waterbear"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1212', 0, 110, '09-mitre-attack', 'retrieved', '95639C93551879C64572418B14A4F9D978D21CED2BA8D9C9AFA0990984051D83', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
