VALUES ('doc-09-mitre-attack-p0-1215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Vasport](https://attack.mitre.org/software/S0207) is a trojan used by [Elderwood](https://attack.mitre.org/groups/G0066) to open a backdoor on compromised hosts. (Citation: Symantec Elderwood Sept 2012) (Citation: Symantec Vasport May 2012)", "external_references": [{"external_id": "S0207", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0207"}, {"description": "(Citation: Symantec Vasport May 2012)", "source_name": "Vasport"}, {"description": "O''Gorman, G., and McDonald, G.. (2012, September 6). The Elderwood Project. Retrieved November 17, 2024.", "source_name": "Symantec Elderwood Sept 2012", "url": "https://web.archive.org/web/20190717233006/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-elderwood-project.pdf"}, {"description": "Zhou, R. (2012, May 15). Backdoor.Vasport. Retrieved February 22, 2018.", "source_name": "Symantec Vasport May 2012", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2012-051606-5938-99"}], "id": "malware--f4d8a2d6-c684-453a-8a14-cf4a94f755c5", "is_family": true, "modified": "2024-11-17T19:55:07.593Z", "name": "Vasport", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Vasport"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1215', 0, 115, '09-mitre-attack', 'retrieved', 'ECB5E41C158493EAFE36E7C21A784B61F32B27762EC22DCA30341A4D7B938252', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "co