VALUES ('doc-09-mitre-attack-p0-1216', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:14.551Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AutoIt backdoor](https://attack.mitre.org/software/S0129) is malware that has been used by the actors responsible for the MONSOON campaign. The actors frequently used it in weaponized .pps files exploiting CVE-2014-6352. (Citation: Forcepoint Monsoon) This malware makes use of the legitimate scripting language for Windows GUI automation with the same name.", "external_references": [{"external_id": "S0129", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0129"}, {"description": "Settle, A., et al. (2016, August 8). MONSOON - Analysis Of An APT Campaign. Retrieved September 22, 2016.", "source_name": "Forcepoint Monsoon", "url": "https://www.forcepoint.com/sites/default/files/resources/files/forcepoint-security-labs-monsoon-analysis-report.pdf"}], "id": "malware--f5352566-1a64-49ac-8f7f-97e1d1a03300", "is_family": true, "modified": "2025-04-25T14:45:05.203Z", "name": "AutoIt backdoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["AutoIt backdoor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1216', 0, 113, '09-mitre-attack', 'retrieved', '8899D9069770F101D266F6F7587C103CB3760CA5BA3B7097BD28551E96DEA8AD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
