VALUES ('doc-09-mitre-attack-p0-1220', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MacSpy](https://attack.mitre.org/software/S0282) is a malware-as-a-service offered on the darkweb (Citation: objsee mac malware 2017).", "external_references": [{"external_id": "S0282", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0282"}, {"description": "(Citation: objsee mac malware 2017).", "source_name": "MacSpy"}, {"description": "Patrick Wardle. (n.d.). Mac Malware of 2017. Retrieved September 21, 2018.", "source_name": "objsee mac malware 2017", "url": "https://objective-see.com/blog/blog_0x25.html"}], "id": "malware--f72251cb-2be5-421f-a081-99c29a1209e7", "is_family": true, "modified": "2025-04-25T14:45:06.639Z", "name": "MacSpy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["MacSpy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1220', 0, 80, '09-mitre-attack', 'retrieved', 'C8B72FA051A6A5F8D2A2B77009E7F9A7D1DC3D115A9CFDCD7EEA69AE26FABD72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
