VALUES ('doc-09-mitre-attack-p0-1221', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-02T21:05:48.601Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lizar](https://attack.mitre.org/software/S0681) is a modular remote access tool written using the .NET Framework that shares structural similarities to [Carbanak](https://attack.mitre.org/software/S0030). It has likely been used by [FIN7](https://attack.mitre.org/groups/G0046) since at least February 2021.(Citation: BiZone Lizar May 2021)(Citation: Threatpost Lizar May 2021)(Citation: Gemini FIN7 Oct 2021)", "external_references": [{"external_id": "S0681", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0681"}, {"description": "(Citation: BiZone Lizar May 2021)(Citation: Gemini FIN7 Oct 2021)", "source_name": "Tirion"}, {"description": "(Citation: BiZone Lizar May 2021)(Citation: Threatpost Lizar May 2021)(Citation: Gemini FIN7 Oct 2021)", "source_name": "Lizar"}, {"description": "(Citation: Cocomazzi FIN7 Reboot)", "source_name": "DiceLoader"}, {"description": "(Citation: Cocomazzi FIN7 Reboot) ", "source_name": "Icebot"}, {"description": "BI.ZONE Cyber Threats Research Team. (2021, May 13). From pentest to APT attack: cybercriminal group FIN7 disguises its malware as an ethical hacker’s toolkit. Retrieved February 2, 2022.", "source_name": "BiZone Lizar May 2021", "url": "https://bi-zone.medium.com/from-pentest-to-apt-attack-cybercriminal-group-fin7-disguises-its-malware-as-an-ethical-hackers-c23c9a75e319"}, {"description": "Cocomazzi, Antonio. (2024, July 17). FIN7 Reboot | Cybercrime Gang Enhances Ops with New EDR Bypasses and Automated Attacks. Retrieved September 24, 2025.", "source_name": "Cocomazzi FIN7 Reboot", "url": "https://www.sentinelone.com/labs/fin7-reboot-cybercrime-gang-enhances-ops-with-new-edr-bypasses-and-automated-attacks/"}, {"description": "Gemini Advisory. (2021, October 21). FIN7 Recruits Talent For Push Into Ransomware. Retrieved February 2, 2022.", "source_name": "Gemini FIN7 Oct 2021", "url": "https://geminiadvisory.io/fin7-ransomware-bastion-secure/"}, {"description": "Seals, T. (2021, May 14). FIN7 Backdoor Masquerades as Ethical Hacking Tool. Retrieved February 2, 2022.", "source_name": "Threatpost Lizar May 2021", "url": "https://threatpost.com/fin7-backdoor-ethical-hacking-tool/166194/"}], "id": "malware--f74a5069-015d-4404-83ad-5ca01056c0dc", "is_family": true, "modified": "2025-10-03T14:46:54.018Z", "name": "Lizar", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Lizar", "Tirion", "Icebot", "DiceLoader"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Sittikorn Sangrattanapitak", "Matt Brenton"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1221', 0, 249, '09-mitre-attack', 'retrieved', '6DA0853BFE7ECAE2CCC0CF9739A3DFC748FB3E771FD5C0AC9A065C1CC78F2E7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
