VALUES ('doc-09-mitre-attack-p0-1222', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-25T13:58:24.977Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dtrack](https://attack.mitre.org/software/S0567) is spyware that was discovered in 2019 and has been used against Indian financial institutions, research facilities, and the Kudankulam Nuclear Power Plant. [Dtrack](https://attack.mitre.org/software/S0567) shares similarities with the DarkSeoul campaign, which was attributed to [Lazarus Group](https://attack.mitre.org/groups/G0032). (Citation: Kaspersky Dtrack)(Citation: Securelist Dtrack)(Citation: Dragos WASSONITE)(Citation: CyberBit Dtrack)(Citation: ZDNet Dtrack)", "external_references": [{"external_id": "S0567", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0567"}, {"description": "Catalin Cimpanu. (2019, October 30). Confirmed: North Korean malware found on Indian nuclear plant''s network. Retrieved January 20, 2021.", "source_name": "ZDNet Dtrack", "url": "https://www.zdnet.com/article/confirmed-north-korean-malware-found-on-indian-nuclear-plants-network/"}, {"description": "Dragos. (n.d.). WASSONITE. Retrieved January 20, 2021.", "source_name": "Dragos WASSONITE", "url": "https://www.dragos.com/threat/wassonite/"}, {"description": "Hod Gavriel. (2019, November 21). Dtrack: In-depth analysis of APT on a nuclear power plant. Retrieved January 20, 2021.", "source_name": "CyberBit Dtrack", "url": "https://www.cyberbit.com/blog/endpoint-security/dtrack-apt-malware-found-in-nuclear-power-plant/"}, {"description": "Kaspersky Global Research and Analysis Team. (2019, September 23). DTrack: previously unknown spy-tool by Lazarus hits financial institutions and research centers. Retrieved January 20, 2021.", "source_name": "Kaspersky Dtrack", "url": "https://usa.kaspersky.com/about/press-releases/2019_dtrack-previously-unknown-spy-tool-hits-financial-institutions-and-research-centers"}, {"description": "Konstantin Zykov. (2019, September 23). Hello! My name is Dtrack. Retrieved January 20, 2021.", "source_name": "Securelist Dtrack", "url": "https://securelist.com/my-name-is-dtrack/93338/"}], "id": "malware--f8774023-8021-4ece-9aca-383ac89d2759", "is_family": true, "modified": "2025-04-16T20:38:44.292Z", "name": "Dtrack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Dtrack"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1222', 0, 204, '09-mitre-attack', 'retrieved', '94802C983A63D04D9F9A6BACE3CB31686BFF67F398632547B853EC60061C1A03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
