VALUES ('doc-09-mitre-attack-p0-1223', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:15.910Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[H1N1](https://attack.mitre.org/software/S0132) is a malware variant that has been distributed via a campaign using VBA macros to infect victims. Although it initially had only loader capabilities, it has evolved to include information-stealing functionality. (Citation: Cisco H1N1 Part 1)", "external_references": [{"external_id": "S0132", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0132"}, {"description": "Reynolds, J.. (2016, September 13). H1N1: Technical analysis reveals new capabilities. Retrieved September 26, 2016.", "source_name": "Cisco H1N1 Part 1", "url": "http://blogs.cisco.com/security/h1n1-technical-analysis-reveals-new-capabilities"}], "id": "malware--f8dfbc54-b070-4224-b560-79aaa5f835bd", "is_family": true, "modified": "2026-05-12T15:12:00.740Z", "name": "H1N1", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["H1N1"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1223', 0, 102, '09-mitre-attack', 'retrieved', '9A7C2ABAAA049FB23DB0AF05E5D3AF4B741185929817114B4FB80801908A261D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
