VALUES ('doc-09-mitre-attack-p0-1224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-06T21:07:39.125Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SLOWPULSE](https://attack.mitre.org/software/S1104) is a malware that was used by [APT5](https://attack.mitre.org/groups/G1023) as early as 2020 including against U.S. Defense Industrial Base (DIB) companies. [SLOWPULSE](https://attack.mitre.org/software/S1104) has several variants and can modify legitimate Pulse Secure VPN files in order to log credentials and bypass single and two-factor authentication flows.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"external_id": "S1104", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1104"}, {"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "malware--f8fc98ac-ad6d-44db-b6e2-f0c6eb4eace4", "is_family": true, "modified": "2025-04-15T19:46:35.817Z", "name": "SLOWPULSE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["SLOWPULSE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1224', 0, 129, '09-mitre-attack', 'retrieved', 'A977CCCE6276B4CF529FF7582F15AE8DD65724FD53DE5DD103B806B110119BCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
