VALUES ('doc-09-mitre-attack-p0-1225', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-13T14:57:39.387Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Seth-Locker](https://attack.mitre.org/software/S0639) is a ransomware with some remote control capabilities that has been in use since at least 2021.\n(Citation: Trend Micro Ransomware February 2021)", "external_references": [{"external_id": "S0639", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0639"}, {"description": "Centero, R. et al. (2021, February 5). New in Ransomware: Seth-Locker, Babuk Locker, Maoloa, TeslaCrypt, and CobraLocker. Retrieved August 11, 2021.", "source_name": "Trend Micro Ransomware February 2021", "url": "https://www.trendmicro.com/en_us/research/21/b/new-in-ransomware.html"}], "id": "malware--f931a0b9-0361-4b1b-bacf-955062c35746", "is_family": true, "modified": "2025-04-25T14:45:07.890Z", "name": "Seth-Locker", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Seth-Locker"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1225', 0, 93, '09-mitre-attack', 'retrieved', '30410B9B363D30F625F75EDECCC2F95E52DEA902EB5C1F529535F2774832A666', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
