VALUES ('doc-09-mitre-attack-p0-1226', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T21:01:51.045Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoudMiner](https://attack.mitre.org/software/S0451) is a cryptocurrency miner which uses virtualization software to siphon system resources. The miner has been bundled with pirated copies of Virtual Studio Technology (VST) for Windows and macOS.(Citation: ESET LoudMiner June 2019)", "external_references": [{"external_id": "S0451", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0451"}, {"description": "Malik, M. (2019, June 20). LoudMiner: Cross-platform mining in cracked VST software. Retrieved May 18, 2020.", "source_name": "ESET LoudMiner June 2019", "url": "https://www.welivesecurity.com/2019/06/20/loudminer-mining-cracked-vst-software/"}], "id": "malware--f99f3dcc-683f-4936-8791-075ac5e58f10", "is_family": true, "modified": "2024-04-11T01:36:42.906Z", "name": "LoudMiner", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["LoudMiner"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS", "Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1226', 0, 101, '09-mitre-attack', 'retrieved', '321B6001EFD8F1177328973DFD74E4F33210820B76F1F2734CB4E7FC8BD3E3FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
