VALUES ('doc-09-mitre-attack-p0-1227', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T15:19:14.309Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Azorult](https://attack.mitre.org/software/S0344) is a commercial Trojan that is used to steal information from compromised hosts. [Azorult](https://attack.mitre.org/software/S0344) has been observed in the wild as early as 2016.\nIn July 2018, [Azorult](https://attack.mitre.org/software/S0344) was seen used in a spearphishing campaign against targets in North America. [Azorult](https://attack.mitre.org/software/S0344) has been seen used for cryptocurrency theft. (Citation: Unit42 Azorult Nov 2018)(Citation: Proofpoint Azorult July 2018)", "external_references": [{"external_id": "S0344", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0344"}, {"description": "(Citation: Unit42 Azorult Nov 2018)(Citation: Proofpoint Azorult July 2018)", "source_name": "Azorult"}, {"description": "Proofpoint. (2018, July 30). New version of AZORult stealer improves loading features, spreads alongside ransomware in new campaign. Retrieved November 29, 2018.", "source_name": "Proofpoint Azorult July 2018", "url": "https://www.proofpoint.com/us/threat-insight/post/new-version-azorult-stealer-improves-loading-features-spreads-alongside"}, {"description": "Yan, T., et al. (2018, November 21). New Wine in Old Bottle: New Azorult Variant Found in FindMyName Campaign using Fallout Exploit Kit. Retrieved November 29, 2018.", "source_name": "Unit42 Azorult Nov 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/11/unit42-new-wine-old-bottle-new-azorult-variant-found-findmyname-campaign-using-fallout-exploit-kit/"}], "id": "malware--f9b05f33-d45d-4e4d-aafe-c208d38a0080", "is_family": true, "modified": "2025-04-16T20:38:44.780Z", "name": "Azorult", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Azorult"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1227', 0, 176, '09-mitre-attack', 'retrieved', 'A0D78926469B5105D72089C9234B2579887AE1EEC84D73995E1D6849D3B2A197', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
