VALUES ('doc-09-mitre-attack-p0-1228', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-08T22:19:19.340Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BitPaymer](https://attack.mitre.org/software/S0570) is a ransomware variant first observed in August 2017 targeting hospitals in the U.K. [BitPaymer](https://attack.mitre.org/software/S0570) uses a unique encryption key, ransom note, and contact information for each operation. [BitPaymer](https://attack.mitre.org/software/S0570) has several indicators suggesting overlap with the [Dridex](https://attack.mitre.org/software/S0384) malware and is often delivered via [Dridex](https://attack.mitre.org/software/S0384).(Citation: Crowdstrike Indrik November 2018)", "external_references": [{"external_id": "S0570", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0570"}, {"description": "(Citation: Crowdstrike Indrik November 2018)", "source_name": "BitPaymer"}, {"description": "(Citation: Crowdstrike Indrik November 2018)", "source_name": "wp_encrypt"}, {"description": "(Citation: Crowdstrike Indrik November 2018)", "source_name": "FriedEx"}, {"description": "Frankoff, S., Hartley, B. (2018, November 14). Big Game Hunting: The Evolution of INDRIK SPIDER From Dridex Wire Fraud to BitPaymer Targeted Ransomware. Retrieved January 6, 2021.", "source_name": "Crowdstrike Indrik November 2018", "url": "https://www.crowdstrike.com/blog/big-game-hunting-the-evolution-of-indrik-spider-from-dridex-wire-fraud-to-bitpaymer-targeted-ransomware/"}], "id": "malware--fa766a65-5136-4ff3-8429-36d08eaa0100", "is_family": true, "modified": "2024-04-11T02:52:57.879Z", "name": "BitPaymer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BitPaymer", "wp_encrypt", "FriedEx"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1228', 0, 152, '09-mitre-attack', 'retrieved', 'B762C6C2321658CBB002E9033E2D5964BCA3957B8CD8F5BCDABCA935D1288933', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
