VALUES ('doc-09-mitre-attack-p0-1229', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:24.428Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BACKSPACE](https://attack.mitre.org/software/S0031) is a backdoor used by [APT30](https://attack.mitre.org/groups/G0013) that dates back to at least 2005. (Citation: FireEye APT30)", "external_references": [{"external_id": "S0031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0031"}, {"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "malware--fb261c56-b80e-43a9-8351-c84081e7213d", "is_family": true, "modified": "2024-11-17T15:05:25.109Z", "name": "BACKSPACE", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["BACKSPACE", "Lecna"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1229', 0, 84, '09-mitre-attack', 'retrieved', '62A20312D2EEF87301360B2D4FCE94E532ED2097FB7517AD5984BE7BF71B27E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
