VALUES ('doc-09-mitre-attack-p0-1230', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-01-09T22:02:05.615Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zox](https://attack.mitre.org/software/S0672) is a remote access tool that has been used by [Axiom](https://attack.mitre.org/groups/G0001) since at least 2008.(Citation: Novetta-Axiom)", "external_references": [{"external_id": "S0672", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0672"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "Gresim"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "ZoxRPC"}, {"description": "(Citation: Novetta-Axiom)", "source_name": "ZoxPNG"}, {"description": "Novetta. (n.d.). Operation SMN: Axiom Threat Actor Group Report. Retrieved November 12, 2014.", "source_name": "Novetta-Axiom", "url": "https://web.archive.org/web/20230115144216/http://www.novetta.com/wp-content/uploads/2014/11/Executive_Summary-Final_1.pdf"}], "id": "malware--fb28627c-d6ea-4c35-b138-ab5e96ae5445", "is_family": true, "modified": "2024-04-10T20:30:02.520Z", "name": "Zox", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Zox", "Gresim", "ZoxRPC", "ZoxPNG"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1230', 0, 95, '09-mitre-attack', 'retrieved', '0EE0AE3DA599F8D72BCACA4FC08392DE2919CC3FC627EA2DF3A94EC08B0AC256', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
