VALUES ('doc-09-mitre-attack-p0-1233', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-15T16:31:56.856Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrifeWater](https://attack.mitre.org/software/S1034) is a remote-access tool that has been used by [Moses Staff](https://attack.mitre.org/groups/G1009) in the initial stages of their attacks since at least November 2021.(Citation: Cybereason StrifeWater Feb 2022)", "external_references": [{"external_id": "S1034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1034"}, {"description": "Cybereason Nocturnus. (2022, February 1). StrifeWater RAT: Iranian APT Moses Staff Adds New Trojan to Ransomware Operations. Retrieved August 15, 2022.", "source_name": "Cybereason StrifeWater Feb 2022", "url": "https://www.cybereason.com/blog/research/strifewater-rat-iranian-apt-moses-staff-adds-new-trojan-to-ransomware-operations"}], "id": "malware--fb78294a-7d7a-4d38-8ad0-92e67fddc9f0", "is_family": true, "modified": "2025-06-06T14:56:56.321Z", "name": "StrifeWater", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["StrifeWater"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1233', 0, 99, '09-mitre-attack', 'retrieved', '1E584088F77F91156EB1A243A7536A41D1CA788F75F45E82CBB1FDDF67CA385A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
