VALUES ('doc-09-mitre-attack-p0-1234', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:54.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mivast](https://attack.mitre.org/software/S0080) is a backdoor that has been used by [Deep Panda](https://attack.mitre.org/groups/G0009). It was reportedly used in the Anthem breach. (Citation: Symantec Black Vine)", "external_references": [{"external_id": "S0080", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0080"}, {"description": "(Citation: Symantec Black Vine) (Citation: Symantec Backdoor.Mivast)", "source_name": "Mivast"}, {"description": "DiMaggio, J.. (2015, August 6). The Black Vine cyberespionage group. Retrieved January 26, 2016.", "source_name": "Symantec Black Vine", "url": "https://web.archive.org/web/20170823094836/http:/www.symantec.com/content/en/us/enterprise/media/security_response/whitepapers/the-black-vine-cyberespionage-group.pdf"}, {"description": "Stama, D.. (2015, February 6). Backdoor.Mivast. Retrieved February 15, 2016.", "source_name": "Symantec Backdoor.Mivast", "url": "http://www.symantec.com/security_response/writeup.jsp?docid=2015-020623-0740-99&tabid=2"}], "id": "malware--fbb470da-1d44-4f29-bbb3-9efbe20f94a3", "is_family": true, "modified": "2025-04-16T20:38:45.394Z", "name": "Mivast", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mivast"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1234', 0, 112, '09-mitre-attack', 'retrieved', '7F456D1615F579C9E8CFEEF61B7A54EE1C2E0733DCC9F6EDECAF03569D202D7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrie