VALUES ('doc-09-mitre-attack-p0-1235', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T12:04:32.323Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HiddenWasp](https://attack.mitre.org/software/S0394) is a Linux-based Trojan used to target systems for remote control. It comes in the form of a statically linked ELF binary with stdlibc++.(Citation: Intezer HiddenWasp Map 2019)", "external_references": [{"external_id": "S0394", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0394"}, {"description": "(Citation: Intezer HiddenWasp Map 2019)", "source_name": "HiddenWasp"}, {"description": "Sanmillan, I. (2019, May 29). HiddenWasp Malware Stings Targeted Linux Systems. Retrieved June 24, 2019.", "source_name": "Intezer HiddenWasp Map 2019", "url": "https://www.intezer.com/blog-hiddenwasp-malware-targeting-linux-systems/"}], "id": "malware--fc774af4-533b-4724-96d2-ac1026316794", "is_family": true, "modified": "2024-04-11T02:19:50.306Z", "name": "HiddenWasp", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HiddenWasp"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1235', 0, 102, '09-mitre-attack', 'retrieved', 'B1C8FF9337BB965EE144B9498F9BB0C736D17F83834B02250DAAA2259BD1B10F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
