VALUES ('doc-09-mitre-attack-p0-1236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-27T17:21:18.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WarzoneRAT](https://attack.mitre.org/software/S0670) is a malware-as-a-service remote access tool (RAT) written in C++ that has been publicly available for purchase since at least late 2018.(Citation: Check Point Warzone Feb 2020)(Citation: Uptycs Warzone UAC Bypass November 2020)", "external_references": [{"external_id": "S0670", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0670"}, {"description": "(Citation: Check Point Warzone Feb 2020)(Citation: Uptycs Warzone UAC Bypass November 2020)", "source_name": "Ave Maria"}, {"description": "Harakhavik, Y. (2020, February 3). Warzone: Behind the enemy lines. Retrieved December 17, 2021.", "source_name": "Check Point Warzone Feb 2020", "url": "https://research.checkpoint.com/2020/warzone-behind-the-enemy-lines/"}, {"description": "Mohanta, A. (2020, November 25). Warzone RAT comes with UAC bypass technique. Retrieved April 7, 2022.", "source_name": "Uptycs Warzone UAC Bypass November 2020", "url": "https://www.uptycs.com/blog/warzone-rat-comes-with-uac-bypass-technique"}], "id": "malware--fde19a18-e502-467f-be14-58c71b4e7f4b", "is_family": true, "modified": "2023-10-03T19:33:26.976Z", "name": "WarzoneRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["WarzoneRAT", "Warzone", "Ave Maria"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Abhijit Mohanta, @abhijit_mohanta, Uptycs", "Shilpesh Trivedi, Uptycs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1236', 0, 152, '09-mitre-attack', 'retrieved', '664855729D9D609004034CB5CC5AAD790D8378EA8EA5496A0E6AAEE21B038011', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
