VALUES ('doc-09-mitre-attack-p0-1237', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:38.851Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Net Crawler](https://attack.mitre.org/software/S0056) is an intranet worm capable of extracting credentials using credential dumpers and spreading to systems on a network over SMB by brute forcing accounts with recovered passwords and using [PsExec](https://attack.mitre.org/software/S0029) to execute a copy of [Net Crawler](https://attack.mitre.org/software/S0056). (Citation: Cylance Cleaver)", "external_references": [{"external_id": "S0056", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0056"}, {"description": "Cylance. (2014, December). Operation Cleaver. Retrieved September 14, 2017.", "source_name": "Cylance Cleaver", "url": "https://web.archive.org/web/20200302085133/https://www.cylance.com/content/dam/cylance/pages/operation-cleaver/Cylance_Operation_Cleaver_Report.pdf"}], "id": "malware--fde50aaa-f5de-4cb8-989a-babb57d6a704", "is_family": true, "modified": "2025-04-16T20:38:45.551Z", "name": "Net Crawler", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Net Crawler", "NetC"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1237', 0, 102, '09-mitre-attack', 'retrieved', 'B509BDF1FD00BA554F85799223A0FCD9748606BD90EFB3AE90370F7F055BE7DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
