VALUES ('doc-09-mitre-attack-p0-1239', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FALLCHILL](https://attack.mitre.org/software/S0181) is a RAT that has been used by [Lazarus Group](https://attack.mitre.org/groups/G0032) since at least 2016 to target the aerospace, telecommunications, and finance industries. It is usually dropped by other [Lazarus Group](https://attack.mitre.org/groups/G0032) malware or delivered when a victim unknowingly visits a compromised website. (Citation: US-CERT FALLCHILL Nov 2017)", "external_references": [{"external_id": "S0181", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0181"}, {"description": "(Citation: US-CERT FALLCHILL Nov 2017)", "source_name": "FALLCHILL"}, {"description": "US-CERT. (2017, November 22). Alert (TA17-318A): HIDDEN COBRA – North Korean Remote Administration Tool: FALLCHILL. Retrieved December 7, 2017.", "source_name": "US-CERT FALLCHILL Nov 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-318A"}], "id": "malware--fece06b7-d4b1-42cf-b81a-5323c917546e", "is_family": true, "modified": "2025-10-22T02:30:54.011Z", "name": "FALLCHILL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["FALLCHILL"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1239', 0, 124, '09-mitre-attack', 'retrieved', 'AD4256A4CB848E5C573DF9B8E8A98481825DF6BD98A6AF078CF5A0DB064AD590', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
