VALUES ('doc-09-mitre-attack-p0-1241', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-16T19:16:48.398Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Small Sieve](https://attack.mitre.org/software/S1035) is a Telegram Bot API-based Python backdoor that has been distributed using a Nullsoft Scriptable Install System (NSIS) Installer; it has been used by [MuddyWater](https://attack.mitre.org/groups/G0069) since at least January 2022.(Citation: DHS CISA AA22-055A MuddyWater February 2022)(Citation: NCSC GCHQ Small Sieve Jan 2022)\n\nSecurity researchers have also noted [Small Sieve](https://attack.mitre.org/software/S1035)''s use by UNC3313, which may be associated with [MuddyWater](https://attack.mitre.org/groups/G0069).(Citation: Mandiant UNC3313 Feb 2022)", "external_references": [{"external_id": "S1035", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1035"}, {"description": "(Citation: Mandiant UNC3313 Feb 2022)", "source_name": "GRAMDOOR"}, {"description": "FBI, CISA, CNMF, NCSC-UK. (2022, February 24). Iranian Government-Sponsored Actors Conduct Cyber Operations Against Global Government and Commercial Networks. Retrieved September 27, 2022.", "source_name": "DHS CISA AA22-055A MuddyWater February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-055a"}, {"description": "NCSC GCHQ. (2022, January 27). Small Sieve Malware Analysis Report. Retrieved August 22, 2022.", "source_name": "NCSC GCHQ Small Sieve Jan 2022", "url": "https://www.ncsc.gov.uk/files/NCSC-Malware-Analysis-Report-Small-Sieve.pdf"}, {"description": "Tomcik, R. et al. (2022, February 24). Left On Read: Telegram Malware Spotted in Latest Iranian Cyber Espionage Activity. Retrieved August 18, 2022.", "source_name": "Mandiant UNC3313 Feb 2022", "url": "https://www.mandiant.com/resources/telegram-malware-iranian-espionage"}], "id": "malware--ff41b9b6-4c1d-407b-a7e2-835109c8dbc5", "is_family": true, "modified": "2025-04-16T20:38:45.865Z", "name": "Small Sieve", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Small Sieve", "GRAMDOOR"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1241', 0, 204, '09-mitre-attack', 'retrieved', 'FD47B2766C42EE207CD569A3DBB4970F765CBFA6739C944427EB8DFF06548167', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
