VALUES ('doc-09-mitre-attack-p0-1242', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:21.973Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Flame](https://attack.mitre.org/software/S0143) is a sophisticated toolkit that has been used to collect information since at least 2010, largely targeting Middle East countries. (Citation: Kaspersky Flame)", "external_references": [{"external_id": "S0143", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0143"}, {"description": "(Citation: Kaspersky Flame)", "source_name": "Flame"}, {"description": "(Citation: Kaspersky Flame) (Citation: Crysys Skywiper)", "source_name": "sKyWIper"}, {"description": "(Citation: Kaspersky Flame) (Citation: Symantec Beetlejuice)", "source_name": "Flamer"}, {"description": "Gostev, A. (2012, May 28). The Flame: Questions and Answers. Retrieved March 1, 2017.", "source_name": "Kaspersky Flame", "url": "https://securelist.com/the-flame-questions-and-answers-51/34344/"}, {"description": "sKyWIper Analysis Team. (2012, May 31). sKyWIper (a.k.a. Flame a.k.a. Flamer): A complex malware for targeted attacks. Retrieved September 6, 2018.", "source_name": "Crysys Skywiper", "url": "https://www.crysys.hu/publications/files/skywiper.pdf"}, {"description": "Symantec Security Response. (2012, May 31). Flamer: A Recipe for Bluetoothache. Retrieved February 25, 2017.", "source_name": "Symantec Beetlejuice", "url": "https://www.symantec.com/connect/blogs/flamer-recipe-bluetoothache"}], "id": "malware--ff6840c9-4c87-4d07-bbb6-9f50aa33d498", "is_family": true, "modified": "2025-04-16T20:38:46.014Z", "name": "Flame", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Flame", "Flamer", "sKyWIper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1242', 0, 161, '09-mitre-attack', 'retrieved', 'A1FDCC3DC74A82813F84661849AC1B8C9B4C7129BB8948D3D4889B7742075812', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
