VALUES ('doc-09-mitre-attack-p0-1243', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T20:47:06.942Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HermeticWizard](https://attack.mitre.org/software/S0698) is a worm that has been used to spread [HermeticWiper](https://attack.mitre.org/software/S0697) in attacks against organizations in Ukraine since at least 2022.(Citation: ESET Hermetic Wizard March 2022)", "external_references": [{"external_id": "S0698", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0698"}, {"description": "ESET. (2022, March 1). IsaacWiper and HermeticWizard: New wiper and worm targetingUkraine. Retrieved April 10, 2022.", "source_name": "ESET Hermetic Wizard March 2022", "url": "https://www.welivesecurity.com/2022/03/01/isaacwiper-hermeticwizard-wiper-worm-targeting-ukraine"}], "id": "malware--ff7ed9c1-dca3-4e62-9da6-72c5d388b8fa", "is_family": true, "modified": "2024-04-11T02:21:28.830Z", "name": "HermeticWizard", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["HermeticWizard"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1243', 0, 93, '09-mitre-attack', 'retrieved', '5867C380C510AE603BE16C7026D840ED440D07AB30B5387650D7DC3639DD1526', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
