VALUES ('doc-09-mitre-attack-p0-1245', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-18T14:57:34.628Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RemoteUtilities](https://attack.mitre.org/software/S0592) is a legitimate remote administration tool that has been used by [MuddyWater](https://attack.mitre.org/groups/G0069) since at least 2021 for execution on target machines.(Citation: Trend Micro Muddy Water March 2021)", "external_references": [{"external_id": "S0592", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0592"}, {"description": "Peretz, A. and Theck, E. (2021, March 5). Earth Vetala – MuddyWater Continues to Target Organizations in the Middle East. Retrieved March 18, 2021.", "source_name": "Trend Micro Muddy Water March 2021", "url": "https://www.trendmicro.com/en_us/research/21/c/earth-vetala---muddywater-continues-to-target-organizations-in-t.html"}], "id": "tool--03c6e0ea-96d3-4b23-9afb-05055663cf4b", "modified": "2025-04-25T14:45:11.980Z", "name": "RemoteUtilities", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["RemoteUtilities"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1245', 0, 100, '09-mitre-attack', 'retrieved', '40557C8E521CDEF1160FCAAEACE48396AE253B2CD307562A73FB20A33F408A0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
