INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1247', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T18:49:15.318Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "NPPSPY is an implementation of a theoretical mechanism first presented in 2004 for capturing credentials submitted to a Windows system via a rogue Network Provider API item. NPPSPY captures credentials following submission and writes them to a file on the victim system for follow-on exfiltration.(Citation: Huntress NPPSPY 2022)(Citation: Polak NPPSPY 2004)", "external_references": [{"external_id": "S1131", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1131"}, {"description": "Dray Agha. (2022, August 16). Cleartext Shenanigans: Gifting User Passwords to Adversaries With NPPSPY. Retrieved May 17, 2024.", "source_name": "Huntress NPPSPY 2022", "url": "https://www.huntress.com/blog/cleartext-shenanigans-gifting-user-passwords-to-adversaries-with-nppspy"}, {"description": "Sergey Polak. (2004, August). Capturing Windows Passwords using the Network Provider API. Retrieved May 17, 2024.", "source_name": "Polak NPPSPY 2004", "url": "https://www.blackhat.com/presentations/win-usa-04/bh-win-04-polak/bh-win-04-polak2.pdf"}], "id": "tool--0630d1a7-54da-4a48-a6af-eb8a62b13c17", "modified": "2024-10-28T19:00:14.732Z", "name": "NPPSPY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["NPPSPY"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Dray Agha, @Purp1eW0lf, Huntress Labs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1247', 0, 145, '09-mitre-attack', 'retrieved', '4FA1C90DAC45092A6F50F8597DFA59580620C64186ECDDE4976DCCB208C39B41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
