INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1249', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-26T18:36:33.410Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Diskpart](https://attack.mitre.org/software/S9002) is a Windows command-line utility that is used to manage the computer’s drives, which includes disks, partitions, volumes and virtual hard disks.(Citation: Microsoft_diskpart_Feb2023) \n\nAdversaries may abuse [Diskpart](https://attack.mitre.org/software/S9002) to perform discovery and destructive actions on a system’s storage. For example, adversaries have been observed using [Diskpart](https://attack.mitre.org/software/S9002) to conduct [Discovery](https://attack.mitre.org/tactics/TA0007) techniques to enumerate disks and volumes to gather information about the host environment, and to execute commands such as `clean all` to remove partition information and overwrite data across disks, resulting in data destruction.(Citation: Trendmicro_RansomHub_Dec2024)", "external_references": [{"external_id": "S9002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9002"}, {"description": "Microsoft. (2023, February 3). diskpart. Retrieved March 17, 2025.", "source_name": "Microsoft_diskpart_Feb2023", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"}, {"description": "Trend Research. (2024, December 20). RansomHub. Retrieved December 23, 2025.", "source_name": "Trendmicro_RansomHub_Dec2024", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-ransomhub"}], "id": "tool--080f872e-f1a3-4d42-bb00-9eb55949f6a9", "modified": "2026-04-23T02:11:05.517Z", "name": "Diskpart", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Diskpart"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Liran Ravich, CardinalOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1249', 0, 157, '09-mitre-attack', 'retrieved', '1EC6C4F32D260752D8038ADC563CE672E8B6B91FC75A15CEEA98C250798784A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
