VALUES ('doc-09-mitre-attack-p0-1250', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[certutil](https://attack.mitre.org/software/S0160) is a command-line utility that can be used to obtain certificate authority information and configure Certificate Services. (Citation: TechNet Certutil)", "external_references": [{"external_id": "S0160", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0160"}, {"description": "Microsoft. (2012, November 14). Certutil. Retrieved July 3, 2017.", "source_name": "TechNet Certutil", "url": "https://technet.microsoft.com/library/cc732443.aspx"}], "id": "tool--0a68f1f1-da74-4d28-8d9a-696c082706cc", "modified": "2026-05-12T15:12:00.740Z", "name": "certutil", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["certutil", "certutil.exe"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-1250', 0, 77, '09-mitre-attack', 'retrieved', '7DBA722A8D15FF797B70D33A12420A41B59DEF77B85AE272DA0E6A3557202B07', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
