VALUES ('doc-09-mitre-attack-p0-1252', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:09.047Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UACMe](https://attack.mitre.org/software/S0116) is an open source assessment tool that contains many methods for bypassing Windows User Account Control on multiple versions of the operating system. (Citation: Github UACMe)", "external_references": [{"external_id": "S0116", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0116"}, {"description": "UACME Project. (2016, June 16). UACMe. Retrieved July 26, 2016.", "source_name": "Github UACMe", "url": "https://github.com/hfiref0x/UACME"}], "id": "tool--102c3898-85e0-43ee-ae28-62a0a3ed9507", "modified": "2025-04-25T14:45:13.232Z", "name": "UACMe", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1252', 0, 77, '09-mitre-attack', 'retrieved', 'E1FA13420015C5EDFB37C316C2D7BD257A478B940DA829661CF1B93F369CAA81', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
