VALUES ('doc-09-mitre-attack-p0-1254', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-30T15:43:17.770Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sliver](https://attack.mitre.org/software/S0633) is an open source, cross-platform, red team command and control (C2) framework written in Golang. [Sliver](https://attack.mitre.org/software/S0633) includes its own package manager, \"armory,\" for staging and downloading additional tools and payloads to the primary C2 framework.(Citation: Bishop Fox Sliver Framework August 2019)(Citation: Cybereason Sliver Undated)", "external_references": [{"external_id": "S0633", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0633"}, {"description": "Cybereason Global SOC and Incident Response Team. (n.d.). Sliver C2 Leveraged by Many Threat Actors. Retrieved March 24, 2025.", "source_name": "Cybereason Sliver Undated", "url": "https://www.cybereason.com/blog/sliver-c2-leveraged-by-many-threat-actors"}, {"description": "Kervella, R. (2019, August 4). Cross-platform General Purpose Implant Framework Written in Golang. Retrieved July 30, 2021.", "source_name": "Bishop Fox Sliver Framework August 2019", "url": "https://labs.bishopfox.com/tech-blog/sliver"}], "id": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "modified": "2025-03-24T16:00:41.005Z", "name": "Sliver", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Sliver"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Achute Sharma, Keysight", "Ayan Saha, Keysight", "Kyaw Pyiyt Htet, @KyawPyiytHtet"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux", "macOS"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1254', 0, 151, '09-mitre-attack', 'retrieved', 'D6CD18AF6CFAD3AC6D3AEDBE62BA885F63E800D0AB246D2CB01F373287AE27C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
