VALUES ('doc-09-mitre-attack-p0-1255', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-23T19:34:30.486Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SILENTTRINITY](https://attack.mitre.org/software/S0692) is an open source remote administration and post-exploitation framework primarily written in Python that includes stagers written in Powershell, C, and Boo. [SILENTTRINITY](https://attack.mitre.org/software/S0692) was used in a 2019 campaign against Croatian government agencies by unidentified cyber actors.(Citation: GitHub SILENTTRINITY March 2022)(Citation: Security Affairs SILENTTRINITY July 2019)", "external_references": [{"external_id": "S0692", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0692"}, {"description": "(Citation: GitHub SILENTTRINITY March 2022)", "source_name": "SILENTTRINITY"}, {"description": "Paganini, P. (2019, July 7). Croatia government agencies targeted with news SilentTrinity malware. Retrieved March 23, 2022.", "source_name": "Security Affairs SILENTTRINITY July 2019", "url": "https://securityaffairs.co/wordpress/88021/apt/croatia-government-silenttrinity-malware.html"}, {"description": "Salvati, M (2019, August 6). SILENTTRINITY. Retrieved March 23, 2022.", "source_name": "GitHub SILENTTRINITY March 2022", "url": "https://github.com/byt3bl33d3r/SILENTTRINITY"}], "id": "tool--1244e058-fa10-48cb-b484-0bcf671107ae", "modified": "2025-04-30T13:26:45.728Z", "name": "SILENTTRINITY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["SILENTTRINITY"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniel Acevedo, ARMADO"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1255', 0, 143, '09-mitre-attack', 'retrieved', 'DDAD12E445F5A4431301A302A9E947D88558B736999A0D154A4D13564E57D099', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
