VALUES ('doc-09-mitre-attack-p0-1256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerSploit](https://attack.mitre.org/software/S0194) is an open source, offensive security framework comprised of [PowerShell](https://attack.mitre.org/techniques/T1059/001) modules and scripts that perform a wide range of tasks related to penetration testing such as code execution, persistence, bypassing anti-virus, recon, and exfiltration. (Citation: GitHub PowerSploit May 2012) (Citation: PowerShellMagazine PowerSploit July 2014) (Citation: PowerSploit Documentation)", "external_references": [{"external_id": "S0194", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0194"}, {"description": "Graeber, M. (2014, July 8). PowerSploit. Retrieved February 6, 2018.", "source_name": "PowerShellMagazine PowerSploit July 2014", "url": "http://www.powershellmagazine.com/2014/07/08/powersploit/"}, {"description": "PowerShellMafia. (2012, May 26). PowerSploit - A PowerShell Post-Exploitation Framework. Retrieved February 6, 2018.", "source_name": "GitHub PowerSploit May 2012", "url": "https://github.com/PowerShellMafia/PowerSploit"}, {"description": "PowerSploit. (n.d.). PowerSploit. Retrieved February 6, 2018.", "source_name": "PowerSploit Documentation", "url": "http://powersploit.readthedocs.io"}], "id": "tool--13cd9151-83b7-410d-9f98-25d0f0d1d80d", "modified": "2025-04-16T20:38:50.246Z", "name": "PowerSploit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["PowerSploit"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-1256', 0, 141, '09-mitre-attack', 'retrieved', 'EF0BDFCE47CCBF1F288D788051A5C64F2AE5A0B97C99C3376E89C8EE237BCEDC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
