VALUES ('doc-09-mitre-attack-p0-1257', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-28T13:21:49.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Pacu is an open-source AWS exploitation framework. The tool is written in Python and publicly available on GitHub.(Citation: GitHub Pacu)", "external_references": [{"external_id": "S1091", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1091"}, {"description": "Rhino Security Labs. (2019, August 22). Pacu. Retrieved October 17, 2019.", "source_name": "GitHub Pacu", "url": "https://github.com/RhinoSecurityLabs/pacu"}], "id": "tool--1b3b8f96-43b1-4460-8e02-1f53d7802fb9", "modified": "2023-10-19T12:18:43.123Z", "name": "Pacu", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Pacu"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Thanabodi Phrakhun, @naikordian"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1257', 0, 81, '09-mitre-attack', 'retrieved', '142E40D7D060D14A6045CAE97CC228345EAC778C11C3FC99017AEBB715381C7F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
