VALUES ('doc-09-mitre-attack-p0-1258', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-30T20:15:05.674Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) is an open-source adversary-in-the-middle (AiTM) attack framework based on the open-source nginx web server. [evilginx2](https://attack.mitre.org/software/S9003) can be used as a reverse proxy between victims and legitimate web services to intercept and capture credentials, authentication tokens, and session cookies.(Citation: Evilginx 2 July 2018)(Citation: Breakdev Evilginx 2.1 SEP 2018)(Citation: Sophos Evilginx MAR 2025)\n ", "external_references": [{"external_id": "S9003", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9003"}, {"description": "Everts, M. (2025, March 28). Stealing user credentials with evilginx. Retrieved January 27, 2026.", "source_name": "Sophos Evilginx MAR 2025", "url": "https://www.sophos.com/en-us/blog/stealing-user-credentials-with-evilginx"}, {"description": "Gretzky, K. (2018, September 10). Evilginx 2.1 - The First Post-Release Update. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.1 SEP 2018", "url": "https://breakdev.org/evilginx-2-1-the-first-post-release-update/"}, {"description": "Gretzky, K.. (2018, July 26). Evilginx 2 - Next Generation of Phishing 2FA Tokens. Retrieved October 14, 2019.", "source_name": "Evilginx 2 July 2018", "url": "https://breakdev.org/evilginx-2-next-generation-of-phishing-2fa-tokens/"}], "id": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "modified": "2026-04-23T02:18:02.821Z", "name": "evilginx2", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["evilginx2"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS", "Identity Provider", "Office Suite", "SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1258', 0, 171, '09-mitre-attack', 'retrieved', 'CD7FF82B4DFF57A76D04FA332F9EA4598A09239D98F77167F422B2408695F6E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
