VALUES ('doc-09-mitre-attack-p0-1259', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:12.684Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Windows Credential Editor](https://attack.mitre.org/software/S0005) is a password dumping tool. (Citation: Amplia WCE)", "external_references": [{"external_id": "S0005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0005"}, {"description": "Amplia Security. (n.d.). Windows Credentials Editor (WCE) F.A.Q.. Retrieved September 12, 2024.", "source_name": "Amplia WCE", "url": "https://web.archive.org/web/20240904163410/https://www.ampliasecurity.com/research/wcefaq.html"}], "id": "tool--242f3da3-4425-4d11-8f5c-b842886da966", "modified": "2024-09-12T15:17:22.004Z", "name": "Windows Credential Editor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Windows Credential Editor", "WCE"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1259', 0, 74, '09-mitre-attack', 'retrieved', 'DC448D7E9D5DF45567D57509EBAC72662EE505E881DF90F45D69C863390FC510', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
