VALUES ('doc-09-mitre-attack-p0-1260', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T01:39:56.283Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Impacket](https://attack.mitre.org/software/S0357) is an open source collection of modules written in Python for programmatically constructing and manipulating network protocols. [Impacket](https://attack.mitre.org/software/S0357) contains several tools for remote service execution, Kerberos manipulation, Windows credential dumping, packet sniffing, and relay attacks.(Citation: Impacket Tools)", "external_references": [{"external_id": "S0357", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0357"}, {"description": "SecureAuth. (n.d.). Retrieved January 15, 2019.", "source_name": "Impacket Tools", "url": "https://www.secureauth.com/labs/open-source-tools/impacket"}], "id": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "modified": "2026-05-12T15:12:00.740Z", "name": "Impacket", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Impacket"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Jacob Wilkin, Trustwave, SpiderLabs"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.8"}', 'kb-doc-09-mitre-attack-p0-1260', 0, 97, '09-mitre-attack', 'retrieved', '68877660DB9F1AA14C0B1BA93BE0644FDFFE9D26F05879AD6054C7C9D9295771', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
