VALUES ('doc-09-mitre-attack-p0-1261', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:02.863Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ipconfig](https://attack.mitre.org/software/S0100) is a Windows utility that can be used to find information about a system''s TCP/IP, DNS, DHCP, and adapter configuration. (Citation: TechNet Ipconfig)", "external_references": [{"external_id": "S0100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0100"}, {"description": "Microsoft. (n.d.). Ipconfig. Retrieved April 17, 2016.", "source_name": "TechNet Ipconfig", "url": "https://technet.microsoft.com/en-us/library/bb490921.aspx"}], "id": "tool--294e2560-bd48-44b2-9da2-833b5588ad11", "modified": "2026-05-12T15:12:00.740Z", "name": "ipconfig", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["ipconfig"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1261', 0, 75, '09-mitre-attack', 'retrieved', '33CB47F9C5015CCBF2A628CEFBFCDED671F01A95DCFB90F408BDB398F5725609', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
