VALUES ('doc-09-mitre-attack-p0-1262', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-01T15:08:45.007Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AADInternals](https://attack.mitre.org/software/S0677) is a PowerShell-based framework for administering, enumerating, and exploiting Azure Active Directory. The tool is publicly available on GitHub.(Citation: AADInternals Github)(Citation: AADInternals Documentation)", "external_references": [{"external_id": "S0677", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0677"}, {"description": "Dr. Nestori Syynimaa. (2018, October 25). AADInternals. Retrieved February 1, 2022.", "source_name": "AADInternals", "url": "https://o365blog.com/aadinternals/"}, {"description": "Dr. Nestori Syynimaa. (2018, October 25). AADInternals. Retrieved February 18, 2022.", "source_name": "AADInternals Documentation", "url": "https://o365blog.com/aadinternals"}, {"description": "Dr. Nestori Syynimaa. (2021, December 13). AADInternals. Retrieved February 1, 2022.", "source_name": "AADInternals Github", "url": "https://github.com/Gerenios/AADInternals"}], "id": "tool--2c5281dd-b5fd-4531-8aea-c1bf8a0f8756", "modified": "2025-04-16T20:38:50.579Z", "name": "AADInternals", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["AADInternals"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Office Suite", "Identity Provider"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1262', 0, 118, '09-mitre-attack', 'retrieved', '5467D557FDD7DC47A09F8ADC1A767113A22B0A4FFCEB5402EBFB722DA4519E9F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
