VALUES ('doc-09-mitre-attack-p0-1263', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:39.233Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Tasklist](https://attack.mitre.org/software/S0057) utility displays a list of applications and services with their Process IDs (PID) for all tasks running on either a local or a remote computer. It is packaged with Windows operating systems and can be executed from the command-line interface. (Citation: Microsoft Tasklist)", "external_references": [{"external_id": "S0057", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0057"}, {"description": "Microsoft. (n.d.). Tasklist. Retrieved December 23, 2015.", "source_name": "Microsoft Tasklist", "url": "https://technet.microsoft.com/en-us/library/bb491010.aspx"}], "id": "tool--2e45723a-31da-4a7e-aaa6-e01998a6788f", "modified": "2026-05-12T15:12:00.740Z", "name": "Tasklist", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Tasklist"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1263', 0, 96, '09-mitre-attack', 'retrieved', '809582FAC8E1F19FAF429076F259A86271F26921E148D899D16B9A4C10853AD8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
