VALUES ('doc-09-mitre-attack-p0-1264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T18:23:44.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DCRAT](https://attack.mitre.org/software/S9017) is a variant of the open-source [AsyncRAT](https://attack.mitre.org/software/S1087) developed in C# with additional capabilities such as patching Microsoft’s Antimalware Scan Interface (AMSI).(Citation: Zscaler BlindEagle DEC 2025)", "external_references": [{"external_id": "S9017", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9017"}, {"description": "Pellegrino, G. (2025, December 16). BlindEagle Targets Colombian Government Agency with Caminho and DCRAT. Retrieved April 16, 2026.", "source_name": "Zscaler BlindEagle DEC 2025", "url": "https://www.zscaler.com/blogs/security-research/blindeagle-targets-colombian-government-agency-caminho-and-dcrat"}], "id": "tool--2f481072-e9f8-4452-be00-d1d7e43c2edc", "modified": "2026-05-12T15:12:00.740Z", "name": "DCRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["DCRAT"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1264', 0, 92, '09-mitre-attack', 'retrieved', '6ABD6BF6BD5280422A9410E039CAECC98B12C5ED2A3A30F9D0C5830F1A9EC8C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
