VALUES ('doc-09-mitre-attack-p0-1266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:10.962Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lslsass](https://attack.mitre.org/software/S0121) is a publicly-available tool that can dump active logon session password hashes from the lsass process. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0121", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0121"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "tool--2fab555f-7664-4623-b4e0-1675ae38190b", "modified": "2025-04-25T14:45:15.980Z", "name": "Lslsass", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Lslsass"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1266', 0, 78, '09-mitre-attack', 'retrieved', 'DC7D89433A0A449C379F21E437EA0E51CB4CCBD5AC00378275E688669BD5FAB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
