VALUES ('doc-09-mitre-attack-p0-1270', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:03.377Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ifconfig](https://attack.mitre.org/software/S0101) is a Unix-based utility used to gather information about and interact with the TCP/IP settings on a system. (Citation: Wikipedia Ifconfig)", "external_references": [{"external_id": "S0101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0101"}, {"description": "Wikipedia. (2016, January 26). ifconfig. Retrieved April 17, 2016.", "source_name": "Wikipedia Ifconfig", "url": "https://en.wikipedia.org/wiki/Ifconfig"}], "id": "tool--362dc67f-4e85-4562-9dac-1b6b7f3ec4b5", "modified": "2025-04-25T14:45:17.053Z", "name": "ifconfig", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1270', 0, 71, '09-mitre-attack', 'retrieved', 'E8F2318F2E19FC4CE39B71D1DDEC24E8C91705CE0386E5BB39A171CE5740AEC3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
