VALUES ('doc-09-mitre-attack-p0-1271', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-10T18:46:33.555Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FRP](https://attack.mitre.org/software/S1144), which stands for Fast Reverse Proxy, is an openly available tool that is capable of exposing a server located behind a firewall or Network Address Translation (NAT) to the Internet. [FRP](https://attack.mitre.org/software/S1144) can support multiple protocols including TCP, UDP, and HTTP(S) and has been abused by threat actors to proxy command and control communications.(Citation: FRP GitHub)(Citation: Joint Cybersecurity Advisory Volt Typhoon June 2023)(Citation: RedCanary Mockingbird May 2020)(Citation: DFIR Phosphorus November 2021)", "external_references": [{"external_id": "S1144", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1144"}, {"description": "DFIR Report. (2021, November 15). Exchange Exploit Leads to Domain Wide Ransomware. Retrieved January 5, 2023.", "source_name": "DFIR Phosphorus November 2021", "url": "https://thedfirreport.com/2021/11/15/exchange-exploit-leads-to-domain-wide-ransomware/"}, {"description": "fatedier. (n.d.). What is frp?. Retrieved July 10, 2024.", "source_name": "FRP GitHub", "url": "https://github.com/fatedier/frp"}, {"description": "Lambert, T. (2020, May 7). Introducing Blue Mockingbird. Retrieved May 26, 2020.", "source_name": "RedCanary Mockingbird May 2020", "url": "https://redcanary.com/blog/blue-mockingbird-cryptominer/"}, {"description": "NSA et al. (2023, May 24). People''s Republic of China State-Sponsored Cyber Actor Living off the Land to Evade Detection. Retrieved July 27, 2023.", "source_name": "Joint Cybersecurity Advisory Volt Typhoon June 2023", "url": "https://media.defense.gov/2023/May/24/2003229517/-1/-1/0/CSA_Living_off_the_Land.PDF"}], "id": "tool--36dd807e-b5bc-4c3e-91ed-80682360148c", "modified": "2026-05-12T15:12:00.740Z", "name": "FRP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["FRP"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1271', 0, 207, '09-mitre-attack', 'retrieved', '4A5A9E9739C8BFF39B994D015890971BC7A73DB2936F52FB59B5959C8F28F654', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
