VALUES ('doc-09-mitre-attack-p0-1272', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:04.937Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[dsquery](https://attack.mitre.org/software/S0105) is a command-line utility that can be used to query Active Directory for information from a system within a domain. (Citation: TechNet Dsquery) It is typically installed only on Windows Server versions but can be installed on non-server variants through the Microsoft-provided Remote Server Administration Tools bundle.", "external_references": [{"external_id": "S0105", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0105"}, {"description": "Microsoft. (n.d.). Dsquery. Retrieved April 18, 2016.", "source_name": "TechNet Dsquery", "url": "https://technet.microsoft.com/en-us/library/cc732952.aspx"}], "id": "tool--38952eac-cb1b-4a71-bad2-ee8223a1c8fe", "modified": "2025-04-16T20:38:51.407Z", "name": "dsquery", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["dsquery", "dsquery.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1272', 0, 102, '09-mitre-attack', 'retrieved', 'B98530EFA87F78EC3571EC37D7350C56F2502BE0F703760EAE1C7A4F11922809', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
