VALUES ('doc-09-mitre-attack-p0-1273', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T14:07:52.541Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PcShare](https://attack.mitre.org/software/S1050) is an open source remote access tool that has been modified and used by Chinese threat actors, most notably during the FunnyDream campaign since late 2018.(Citation: Bitdefender FunnyDream Campaign November 2020)(Citation: GitHub PcShare 2014)", "external_references": [{"external_id": "S1050", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1050"}, {"description": "LiveMirror. (2014, September 17). PcShare. Retrieved October 11, 2022.", "source_name": "GitHub PcShare 2014", "url": "https://github.com/LiveMirror/pcshare"}, {"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "id": "tool--3a53b207-aba2-4a2b-9cdb-273d633669e7", "modified": "2024-04-11T00:28:17.175Z", "name": "PcShare", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["PcShare"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1273', 0, 118, '09-mitre-attack', 'retrieved', 'F1D5D99CE54AAE7ED9ED84294995BA3E741D522B4993AE55E8AE324A20E1116F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
