VALUES ('doc-09-mitre-attack-p0-1274', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-25T12:30:40.919Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RawDisk](https://attack.mitre.org/software/S0364) is a legitimate commercial driver from the EldoS Corporation that is used for interacting with files, disks, and partitions. The driver allows for direct modification of data on a local computer''s hard drive. In some cases, the tool can enact these raw disk modifications from user-mode processes, circumventing Windows operating system security features.(Citation: EldoS RawDisk ITpro)(Citation: Novetta Blockbuster Destructive Malware)", "external_references": [{"external_id": "S0364", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0364"}, {"description": "Edwards, M. (2007, March 14). EldoS Provides Raw Disk Access for Vista and XP. Retrieved March 26, 2019.", "source_name": "EldoS RawDisk ITpro", "url": "https://www.itprotoday.com/windows-78/eldos-provides-raw-disk-access-vista-and-xp"}, {"description": "Novetta Threat Research Group. (2016, February 24). Operation Blockbuster: Destructive Malware Report. Retrieved November 17, 2024.", "source_name": "Novetta Blockbuster Destructive Malware", "url": "https://web.archive.org/web/20160303200515/https:/operationblockbuster.com/wp-content/uploads/2016/02/Operation-Blockbuster-Destructive-Malware-Report.pdf"}], "id": "tool--3ffbdc1f-d2bf-41ab-91a2-c7b857e98079", "modified": "2024-11-17T19:51:16.652Z", "name": "RawDisk", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["RawDisk"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1274', 0, 150, '09-mitre-attack', 'retrieved', '76AE08F2D3602FDE49F249842F036828E8410BFA36C5D7D81C78199697BCC62C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
