VALUES ('doc-09-mitre-attack-p0-1275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:04.545Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[netstat](https://attack.mitre.org/software/S0104) is an operating system utility that displays active TCP connections, listening ports, and network statistics. (Citation: TechNet Netstat)", "external_references": [{"external_id": "S0104", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0104"}, {"description": "Microsoft. (n.d.). Netstat. Retrieved April 17, 2016.", "source_name": "TechNet Netstat", "url": "https://technet.microsoft.com/en-us/library/bb490947.aspx"}], "id": "tool--4664b683-f578-434f-919b-1c1aad2a1111", "modified": "2026-05-12T15:12:00.740Z", "name": "netstat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["netstat"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1275', 0, 70, '09-mitre-attack', 'retrieved', 'C38C75B9FE0356938138BD0B098974D06741A9B0B57C3AE095EA0562C375EE39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
