VALUES ('doc-09-mitre-attack-p0-1276', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-23T12:31:58.125Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PoshC2](https://attack.mitre.org/software/S0378) is an open source remote administration and post-exploitation framework that is publicly available on GitHub. The server-side components of the tool are primarily written in Python, while the implants are written in [PowerShell](https://attack.mitre.org/techniques/T1059/001). Although [PoshC2](https://attack.mitre.org/software/S0378) is primarily focused on Windows implantation, it does contain a basic Python dropper for Linux/macOS.(Citation: GitHub PoshC2)", "external_references": [{"external_id": "S0378", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0378"}, {"description": "Nettitude. (2018, July 23). Python Server for PoshC2. Retrieved April 23, 2019.", "source_name": "GitHub PoshC2", "url": "https://github.com/nettitude/PoshC2_Python"}], "id": "tool--4b57c098-f043-4da2-83ef-7588a6d426bc", "modified": "2025-04-16T20:38:51.558Z", "name": "PoshC2", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["PoshC2"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux", "macOS"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1276', 0, 113, '09-mitre-attack', 'retrieved', 'ECE9557A72F97DA26AAEF5D31BF3ED9FC6B406006D520806B17EE6B7D82A0154', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
