VALUES ('doc-09-mitre-attack-p0-1278', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:11.941Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[xCmd](https://attack.mitre.org/software/S0123) is an open source tool that is similar to [PsExec](https://attack.mitre.org/software/S0029) and allows the user to execute applications on remote systems. (Citation: xCmd)", "external_references": [{"external_id": "S0123", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0123"}, {"description": "Rayaprolu, A.. (2011, April 12). xCmd an Alternative to PsExec. Retrieved August 10, 2016.", "source_name": "xCmd", "url": "https://ashwinrayaprolu.wordpress.com/2011/04/12/xcmd-an-alternative-to-psexec/"}], "id": "tool--4fa49fc0-9162-4bdb-a37e-7aa3dcb6d38b", "modified": "2025-04-25T14:45:18.852Z", "name": "xCmd", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1278', 0, 76, '09-mitre-attack', 'retrieved', '215D10ABFD88D751F47EF814551F37EDD061F22357EF83B101C42FFE316A0A80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
