VALUES ('doc-09-mitre-attack-p0-1279', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-09T14:30:35.202Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CSPY Downloader](https://attack.mitre.org/software/S0527) is a tool designed to evade analysis and download additional payloads used by [Kimsuky](https://attack.mitre.org/groups/G0094).(Citation: Cybereason Kimsuky November 2020)", "external_references": [{"external_id": "S0527", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0527"}, {"description": "Dahan, A. et al. (2020, November 2). Back to the Future: Inside the Kimsuky KGH Spyware Suite. Retrieved November 6, 2020.", "source_name": "Cybereason Kimsuky November 2020", "url": "https://www.cybereason.com/blog/back-to-the-future-inside-the-kimsuky-kgh-spyware-suite"}], "id": "tool--5256c0f8-9108-4c92-8b09-482dfacdcd94", "modified": "2025-04-16T20:38:52.033Z", "name": "CSPY Downloader", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["CSPY Downloader"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1279', 0, 91, '09-mitre-attack', 'retrieved', '0C160EB773D3411D708BD9AE5ED825DD5D4936D96D94E67B6441D8263D29225D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
