VALUES ('doc-09-mitre-attack-p0-1281', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MimiPenguin](https://attack.mitre.org/software/S0179) is a credential dumper, similar to [Mimikatz](https://attack.mitre.org/software/S0002), designed specifically for Linux platforms. (Citation: MimiPenguin GitHub May 2017)", "external_references": [{"external_id": "S0179", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0179"}, {"description": "Gregal, H. (2017, May 12). MimiPenguin. Retrieved December 5, 2017.", "source_name": "MimiPenguin GitHub May 2017", "url": "https://github.com/huntergregal/mimipenguin"}], "id": "tool--5a33468d-844d-4b1f-98c9-0e786c556b27", "modified": "2025-04-25T14:45:19.566Z", "name": "MimiPenguin", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["MimiPenguin"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Vincent Le Toux"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1281', 0, 78, '09-mitre-attack', 'retrieved', 'ED11D29C6CDDE68AB745C4BDBE1E8CBD4930F4A5834B5CD53E212507E25C3A09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
