VALUES ('doc-09-mitre-attack-p0-1283', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-02T19:10:29.513Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CARROTBALL](https://attack.mitre.org/software/S0465) is an FTP downloader utility that has been in use since at least 2019. [CARROTBALL](https://attack.mitre.org/software/S0465) has been used as a downloader to install [SYSCON](https://attack.mitre.org/software/S0464).(Citation: Unit 42 CARROTBAT January 2020)", "external_references": [{"external_id": "S0465", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0465"}, {"description": "McCabe, A. (2020, January 23). The Fractured Statue Campaign: U.S. Government Agency Targeted in Spear-Phishing Attacks. Retrieved June 2, 2020.", "source_name": "Unit 42 CARROTBAT January 2020", "url": "https://unit42.paloaltonetworks.com/the-fractured-statue-campaign-u-s-government-targeted-in-spear-phishing-attacks/"}], "id": "tool--5fc81b43-62b5-41b1-9113-c79ae5f030c4", "modified": "2025-04-25T14:45:20.112Z", "name": "CARROTBALL", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["CARROTBALL"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1283', 0, 97, '09-mitre-attack', 'retrieved', '5B0BED0D90E5C8E8B3E01B9E9A6B480E0A59880E1E966596FF7AD94D9B98ACCD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
