VALUES ('doc-09-mitre-attack-p0-1286', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-20T17:32:59.932Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AsyncRAT](https://attack.mitre.org/software/S1087) is an open-source remote access tool originally available through the NYANxCAT Github repository that has been used in malicious campaigns.(Citation: Morphisec Snip3 May 2021)(Citation: Cisco Operation Layover September 2021)(Citation: Telefonica Snip3 December 2021)", "external_references": [{"external_id": "S1087", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1087"}, {"description": "Jornet, A. (2021, December 23). Snip3, an investigation into malware. Retrieved September 19, 2023.", "source_name": "Telefonica Snip3 December 2021", "url": "https://telefonicatech.com/blog/snip3-investigacion-malware"}, {"description": "Lorber, N. (2021, May 7). Revealing the Snip3 Crypter, a Highly Evasive RAT Loader. Retrieved September 13, 2023.", "source_name": "Morphisec Snip3 May 2021", "url": "https://blog.morphisec.com/revealing-the-snip3-crypter-a-highly-evasive-rat-loader"}, {"description": "Ventura, V. (2021, September 16). Operation Layover: How we tracked an attack on the aviation industry to five years of compromise. Retrieved September 15, 2023.", "source_name": "Cisco Operation Layover September 2021", "url": "https://blog.talosintelligence.com/operation-layover-how-we-tracked-attack/"}], "id": "tool--6a5947f3-1a36-4653-8734-526df3e1d28d", "modified": "2026-05-12T15:12:00.740Z", "name": "AsyncRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["AsyncRAT"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Aaron Jornet"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1286', 0, 159, '09-mitre-attack', 'retrieved', '75CA6006AC8FCF1D19A9D86E46F3830262987FBB36AEC95360A9ACB14C94FE10', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
