VALUES ('doc-09-mitre-attack-p0-1287', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-18T13:29:23.577Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROADTools](https://attack.mitre.org/software/S0684) is a framework for enumerating Azure Active Directory environments. The tool is written in Python and publicly available on GitHub.(Citation: ROADtools Github)", "external_references": [{"external_id": "S0684", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0684"}, {"description": "Dirk-jan Mollema. (2022, January 31). ROADtools. Retrieved January 31, 2022.", "source_name": "ROADtools Github", "url": "https://github.com/dirkjanm/ROADtools"}], "id": "tool--6dbdc657-d8e0-4f2f-909b-7251b3e72c6d", "modified": "2024-09-16T17:02:37.377Z", "name": "ROADTools", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["ROADTools"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1287', 0, 80, '09-mitre-attack', 'retrieved', 'CED86349F52419AD6DDF8097C6587734D2D21BA02C66DFDBB012EF1391AD5297', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
