VALUES ('doc-09-mitre-attack-p0-1290', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-08T16:11:38.528Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Peirates](https://attack.mitre.org/software/S0683) is a post-exploitation Kubernetes exploitation framework with a focus on gathering service account tokens for lateral movement and privilege escalation. The tool is written in GoLang and publicly available on GitHub.(Citation: Peirates GitHub)", "external_references": [{"external_id": "S0683", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0683"}, {"description": "InGuardians. (2022, January 5). Peirates GitHub. Retrieved February 8, 2022.", "source_name": "Peirates GitHub", "url": "https://github.com/inguardians/peirates"}], "id": "tool--79dd477a-8226-4b3d-ad15-28623675f221", "modified": "2025-04-16T20:38:52.924Z", "name": "Peirates", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Peirates"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1290', 0, 90, '09-mitre-attack', 'retrieved', '49716CCC4077EE59E81B83ECA5B73CCC94635451B95EFCF3D698BBA48ECC7FDE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
