VALUES ('doc-09-mitre-attack-p0-1291', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T18:55:20.245Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Remcos](https://attack.mitre.org/software/S0332) is a closed-source tool that is marketed as a remote control and surveillance software by a company called Breaking Security. [Remcos](https://attack.mitre.org/software/S0332) has been observed being used in malware campaigns.(Citation: Riskiq Remcos Jan 2018)(Citation: Talos Remcos Aug 2018)", "external_references": [{"external_id": "S0332", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0332"}, {"description": "(Citation: Riskiq Remcos Jan 2018)(Citation: Fortinet Remcos Feb 2017)(Citation: Talos Remcos Aug 2018)", "source_name": "Remcos"}, {"description": "Bacurio, F., Salvio, J. (2017, February 14). REMCOS: A New RAT In The Wild. Retrieved November 6, 2018.", "source_name": "Fortinet Remcos Feb 2017", "url": "https://www.fortinet.com/blog/threat-research/remcos-a-new-rat-in-the-wild-2.html"}, {"description": "Brumaghin, E., Unterbrink, H. (2018, August 22). Picking Apart Remcos Botnet-In-A-Box. Retrieved November 6, 2018.", "source_name": "Talos Remcos Aug 2018", "url": "https://blog.talosintelligence.com/2018/08/picking-apart-remcos.html"}, {"description": "Klijnsma, Y. (2018, January 23). Espionage Campaign Leverages Spear Phishing, RATs Against Turkish Defense Contractors. Retrieved November 6, 2018.", "source_name": "Riskiq Remcos Jan 2018", "url": "https://web.archive.org/web/20180124082756/https://www.riskiq.com/blog/labs/spear-phishing-turkish-defense-contractors/"}], "id": "tool--7cd0bc75-055b-4098-a00e-83dc8beaff14", "modified": "2026-04-23T03:33:15.712Z", "name": "Remcos", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Remcos"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1291', 0, 170, '09-mitre-attack', 'retrieved', 'FD9B3B6A9A621D3BBC35B8C0A7F856F4D91DF434C7D05C3BC66717471EEE4ED2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
