VALUES ('doc-09-mitre-attack-p0-1292', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:00.969Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Systeminfo](https://attack.mitre.org/software/S0096) is a Windows utility that can be used to gather detailed information about a computer. (Citation: TechNet Systeminfo)", "external_references": [{"external_id": "S0096", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0096"}, {"description": "Microsoft. (n.d.). Systeminfo. Retrieved April 8, 2016.", "source_name": "TechNet Systeminfo", "url": "https://technet.microsoft.com/en-us/library/bb491007.aspx"}], "id": "tool--7fcbc4e8-1989-441f-9ac5-e7b6ff5806f1", "modified": "2025-04-16T20:38:53.231Z", "name": "Systeminfo", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Systeminfo"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1292', 0, 70, '09-mitre-attack', 'retrieved', 'AAF5A9BEFB49B9B2D92657A058F132C826E513ECCFC645D487CAD093A7869866', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
