VALUES ('doc-09-mitre-attack-p0-1295', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-04T15:47:07.382Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[attrib](https://attack.mitre.org/software/S1176) is a Windows utility used to display, set or remove attributes assigned to files or directories.(Citation: Microsoft attrib 2023) ", "external_references": [{"external_id": "S1176", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1176"}, {"description": "Xelu86, et al. (2023, September 25). attrib. Retrieved November 22, 2024.", "source_name": "Microsoft attrib 2023", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/attrib"}], "id": "tool--8c6e9947-f7b1-4bd3-9d5d-cc7d39934989", "modified": "2025-01-02T21:29:42.017Z", "name": "attrib", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["attrib", "attrib.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Liran Ravich, CardinalOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1295', 0, 84, '09-mitre-attack', 'retrieved', 'BCC557AE299CBBCC25575C0ECCE5F09B9BF39F7079544BDA15CAD0347E411A36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
