VALUES ('doc-09-mitre-attack-p0-1296', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-05T18:45:36.358Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Imminent Monitor](https://attack.mitre.org/software/S0434) was a commodity remote access tool (RAT) offered for sale from 2012 until 2019, when an operation was conducted to take down the Imminent Monitor infrastructure. Various cracked versions and variations of this RAT are still in circulation.(Citation: Imminent Unit42 Dec2019)", "external_references": [{"external_id": "S0434", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0434"}, {"description": "Unit 42. (2019, December 2). Imminent Monitor – a RAT Down Under. Retrieved May 5, 2020.", "source_name": "Imminent Unit42 Dec2019", "url": "https://unit42.paloaltonetworks.com/imminent-monitor-a-rat-down-under/"}], "id": "tool--8f8cd191-902c-4e83-bf20-b57c8c4640e9", "modified": "2023-10-03T19:35:03.646Z", "name": "Imminent Monitor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Imminent Monitor"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Jose Luis Sánchez Martinez"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1296', 0, 113, '09-mitre-attack', 'retrieved', '9EF156D8CD56D904498E790ADF1A07D8AE26FEE69352424F560D1D92DFE8755F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
