VALUES ('doc-09-mitre-attack-p0-1297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-04T18:27:00.501Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ruler](https://attack.mitre.org/software/S0358) is a tool to abuse Microsoft Exchange services. It is publicly available on GitHub and the tool is executed via the command line. The creators of [Ruler](https://attack.mitre.org/software/S0358) have also released a defensive tool, NotRuler, to detect its usage.(Citation: SensePost Ruler GitHub)(Citation: SensePost NotRuler)", "external_references": [{"external_id": "S0358", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0358"}, {"description": "SensePost. (2016, August 18). Ruler: A tool to abuse Exchange services. Retrieved February 4, 2019.", "source_name": "SensePost Ruler GitHub", "url": "https://github.com/sensepost/ruler"}, {"description": "SensePost. (2017, September 21). NotRuler - The opposite of Ruler, provides blue teams with the ability to detect Ruler usage against Exchange. Retrieved February 4, 2019.", "source_name": "SensePost NotRuler", "url": "https://github.com/sensepost/notruler"}], "id": "tool--90ac9266-68ce-46f2-b24f-5eb3b2a8ea38", "modified": "2025-04-25T14:45:22.953Z", "name": "Ruler", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Ruler"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Office Suite"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1297', 0, 138, '09-mitre-attack', 'retrieved', '4880542C59BA9D30BB929B43681C79BA95F14BF75A650B6D3BDCDABDAF9EB773', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
