VALUES ('doc-09-mitre-attack-p0-1298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Forfiles](https://attack.mitre.org/software/S0193) is a Windows utility commonly used in batch jobs to execute commands on one or more selected files or directories (ex: list all directories in a drive, read the first line of all files created yesterday, etc.). Forfiles can be executed from either the command line, Run window, or batch files/scripts. (Citation: Microsoft Forfiles Aug 2016)", "external_references": [{"external_id": "S0193", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0193"}, {"description": "Microsoft. (2016, August 31). Forfiles. Retrieved January 22, 2018.", "source_name": "Microsoft Forfiles Aug 2016", "url": "https://docs.microsoft.com/previous-versions/windows/it-pro/windows-server-2012-R2-and-2012/cc753551(v=ws.11)"}], "id": "tool--90ec2b22-7061-4469-b539-0989ec4f96c2", "modified": "2025-04-25T14:45:23.318Z", "name": "Forfiles", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1298', 0, 108, '09-mitre-attack', 'retrieved', '087F1B39067DAAE56F72F4B5CDC898450E1D8C06D6B0D448373B32219C223125', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
