VALUES ('doc-09-mitre-attack-p0-1299', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Winexe](https://attack.mitre.org/software/S0191) is a lightweight, open source tool similar to [PsExec](https://attack.mitre.org/software/S0029) designed to allow system administrators to execute commands on remote servers. (Citation: Winexe Github Sept 2013) [Winexe](https://attack.mitre.org/software/S0191) is unique in that it is a GNU/Linux based client. (Citation: Überwachung APT28 Forfiles June 2015)", "external_references": [{"external_id": "S0191", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0191"}, {"description": "Guarnieri, C. (2015, June 19). Digital Attack on German Parliament: Investigative Report on the Hack of the Left Party Infrastructure in Bundestag. Retrieved January 22, 2018.", "source_name": "Überwachung APT28 Forfiles June 2015", "url": "https://netzpolitik.org/2015/digital-attack-on-german-parliament-investigative-report-on-the-hack-of-the-left-party-infrastructure-in-bundestag/"}, {"description": "Skalkotos, N. (2013, September 20). WinExe. Retrieved January 22, 2018.", "source_name": "Winexe Github Sept 2013", "url": "https://github.com/skalkoto/winexe/"}], "id": "tool--96fd6cc4-a693-4118-83ec-619e5352d07d", "modified": "2024-09-04T21:09:10.255Z", "name": "Winexe", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Winexe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1299', 0, 134, '09-mitre-attack', 'retrieved', 'A97F050453D459BB5B331A1DF3B08609E2E2795751DCBF9A22BDD4F4ABC9F9FF', 'v1', '{"source_id": 