VALUES ('doc-09-mitre-attack-p0-1300', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-13T17:15:25.702Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MCMD](https://attack.mitre.org/software/S0500) is a remote access tool that provides remote command shell capability used by [Dragonfly](https://attack.mitre.org/groups/G0035).(Citation: Secureworks MCMD July 2019)", "external_references": [{"external_id": "S0500", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0500"}, {"description": "Secureworks. (2019, July 24). MCMD Malware Analysis. Retrieved August 13, 2020.", "source_name": "Secureworks MCMD July 2019", "url": "https://www.secureworks.com/research/mcmd-malware-analysis"}], "id": "tool--975737f1-b10d-476f-8bda-3ec26ea57172", "modified": "2026-05-12T15:12:00.740Z", "name": "MCMD", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["MCMD"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1300', 0, 78, '09-mitre-attack', 'retrieved', '1989F32A36A01FEDB79C75A69922000CF1E02A206019B63E8F0C4567FAE1189D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
