VALUES ('doc-09-mitre-attack-p0-1301', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-14T17:08:55.176Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nltest](https://attack.mitre.org/software/S0359) is a Windows command-line utility used to list domain controllers and enumerate domain trusts.(Citation: Nltest Manual)", "external_references": [{"external_id": "S0359", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0359"}, {"description": "ss64. (n.d.). NLTEST.exe - Network Location Test. Retrieved February 14, 2019.", "source_name": "Nltest Manual", "url": "https://ss64.com/nt/nltest.html"}], "id": "tool--981acc4c-2ede-4b56-be6e-fa1a75f37acf", "modified": "2026-05-12T15:12:00.740Z", "name": "Nltest", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Nltest"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1301', 0, 74, '09-mitre-attack', 'retrieved', '8AF4D747B105A88EBC45A20EACEC016CD25C87F56ACB8840D7FA74318AC18D06', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
