VALUES ('doc-09-mitre-attack-p0-1302', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-05T02:34:01.189Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "MailSniper is a penetration testing tool for searching through email in a Microsoft Exchange environment for specific terms (passwords, insider intel, network architecture information, etc.). It can be used by a non-administrative user to search their own email, or by an Exchange administrator to search the mailboxes of every user in a domain.(Citation: GitHub MailSniper)", "external_references": [{"external_id": "S0413", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0413"}, {"description": "Bullock, B., . (2018, November 20). MailSniper. Retrieved October 4, 2019.", "source_name": "GitHub MailSniper", "url": "https://github.com/dafthack/MailSniper"}], "id": "tool--999c4e6e-b8dc-4b4f-8d6e-1b829f29997e", "modified": "2024-10-14T22:11:30.271Z", "name": "MailSniper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["MailSniper"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Office Suite"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1302', 0, 114, '09-mitre-attack', 'retrieved', '1701644BC3F81C2D61BE7C600F7BF977186483FE272052154BFAD57476FA547B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
