VALUES ('doc-09-mitre-attack-p0-1303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[sqlmap](https://attack.mitre.org/software/S0225) is an open source penetration testing tool that can be used to automate the process of detecting and exploiting SQL injection flaws. (Citation: sqlmap Introduction)", "external_references": [{"external_id": "S0225", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0225"}, {"description": "Damele, B., Stampar, M. (n.d.). sqlmap. Retrieved March 19, 2018.", "source_name": "sqlmap Introduction", "url": "http://sqlmap.org/"}], "id": "tool--9a2640c2-9f43-46fe-b13f-bde881e55555", "modified": "2026-05-12T15:12:00.740Z", "name": "sqlmap", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["sqlmap"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1303', 0, 80, '09-mitre-attack', 'retrieved', 'E133CDB4584C12DB21E0AB4F08563AF49132DB2D97E13B4DF1BA80C1D485D870', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
