VALUES ('doc-09-mitre-attack-p0-1304', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:13.051Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[pwdump](https://attack.mitre.org/software/S0006) is a credential dumper. (Citation: Wikipedia pwdump)", "external_references": [{"external_id": "S0006", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0006"}, {"description": "Wikipedia. (2007, August 9). pwdump. Retrieved June 22, 2016.", "source_name": "Wikipedia pwdump", "url": "https://en.wikipedia.org/wiki/Pwdump"}], "id": "tool--9de2308e-7bed-43a3-8e58-f194b3586700", "modified": "2025-04-25T14:45:24.744Z", "name": "pwdump", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["pwdump"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1304', 0, 61, '09-mitre-attack', 'retrieved', '1CD7C3891EB0BCC5D10D22F4B6601AC41FBFF288F0086A186F0F42FDAA402AEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
