VALUES ('doc-09-mitre-attack-p0-1305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Responder is an open source tool used for LLMNR, NBT-NS and MDNS poisoning, with built-in HTTP/SMB/MSSQL/FTP/LDAP rogue authentication server supporting NTLMv1/NTLMv2/LMv2, Extended Security NTLMSSP and Basic HTTP authentication. (Citation: GitHub Responder)", "external_references": [{"external_id": "S0174", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0174"}, {"description": "Gaffie, L. (2016, August 25). Responder. Retrieved November 17, 2017.", "source_name": "GitHub Responder", "url": "https://github.com/SpiderLabs/Responder"}], "id": "tool--a1dd2dbd-1550-44bf-abcc-1a4c52e97719", "modified": "2025-04-16T20:38:54.639Z", "name": "Responder", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Responder"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1305', 0, 85, '09-mitre-attack', 'retrieved', '0860D93A948BA82F1ECED26D1F5BAA79654B7346298D2003E4BEA47DF9BD1A23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
