VALUES ('doc-09-mitre-attack-p0-1306', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:11.426Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pass-The-Hash Toolkit](https://attack.mitre.org/software/S0122) is a toolkit that allows an adversary to \"pass\" a password hash (without knowing the original password) to log in to systems. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0122", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0122"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "tool--a52edc76-328d-4596-85e7-d56ef5a9eb69", "modified": "2025-04-25T14:45:25.272Z", "name": "Pass-The-Hash Toolkit", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1306', 0, 82, '09-mitre-attack', 'retrieved', 'E55B35C0D64AF54A4F1E007EFF7A050D53F7007149172123CD3E000E6F6A5FBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
