VALUES ('doc-09-mitre-attack-p0-1307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T13:35:46.781Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Donut](https://attack.mitre.org/software/S0695) is an open source framework used to generate position-independent shellcode.(Citation: Donut Github)(Citation: Introducing Donut) [Donut](https://attack.mitre.org/software/S0695) generated code has been used by multiple threat actors to inject and load malicious payloads into memory.(Citation: NCC Group WastedLocker June 2020)", "external_references": [{"external_id": "S0695", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0695"}, {"description": "Antenucci, S., Pantazopoulos, N., Sandee, M. (2020, June 23). WastedLocker: A New Ransomware Variant Developed By The Evil Corp Group. Retrieved September 14, 2021.", "source_name": "NCC Group WastedLocker June 2020", "url": "https://research.nccgroup.com/2020/06/23/wastedlocker-a-new-ransomware-variant-developed-by-the-evil-corp-group/"}, {"description": "The Wover. (2019, May 9). Donut - Injecting .NET Assemblies as Shellcode. Retrieved October 4, 2021.", "source_name": "Introducing Donut", "url": "https://thewover.github.io/Introducing-Donut/"}, {"description": "TheWover. (2019, May 9). donut. Retrieved March 25, 2022.", "source_name": "Donut Github", "url": "https://github.com/TheWover/donut"}], "id": "tool--a7b5df47-73bb-4d47-b701-869f185633a6", "modified": "2025-04-16T20:38:54.932Z", "name": "Donut", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Donut"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["The Wover, @TheRealWover"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1307', 0, 152, '09-mitre-attack', 'retrieved', 'C2C65B2CEB4D9671A573792850ECD10B76A8FCF724E12AA51CB6058FC771414C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
