VALUES ('doc-09-mitre-attack-p0-1308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:11.544Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mimikatz](https://attack.mitre.org/software/S0002) is a credential dumper capable of obtaining plaintext Windows account logins and passwords, along with many other features that make it useful for testing the security of networks. (Citation: Deply Mimikatz) (Citation: Adsecurity Mimikatz Guide)", "external_references": [{"external_id": "S0002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0002"}, {"description": "Deply, B. (n.d.). Mimikatz. Retrieved September 29, 2015.", "source_name": "Deply Mimikatz", "url": "https://github.com/gentilkiwi/mimikatz"}, {"description": "Metcalf, S. (2015, November 13). Unofficial Guide to Mimikatz & Command Reference. Retrieved December 23, 2015.", "source_name": "Adsecurity Mimikatz Guide", "url": "https://adsecurity.org/?page_id=1821"}], "id": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "modified": "2026-05-12T15:12:00.740Z", "name": "Mimikatz", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Mimikatz"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Vincent Le Toux"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.11"}', 'kb-doc-09-mitre-attack-p0-1308', 0, 117, '09-mitre-attack', 'retrieved', '8F67608DAEE30BDF7928AD1D1BADC8B57CF76B17F1A7DDDFD9A0EB93498BD8BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
