VALUES ('doc-09-mitre-attack-p0-1309', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:13.755Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[gsecdump](https://attack.mitre.org/software/S0008) is a publicly-available credential dumper used to obtain password hashes and LSA secrets from Windows operating systems. (Citation: TrueSec Gsecdump)", "external_references": [{"external_id": "S0008", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0008"}, {"description": "TrueSec. (n.d.). gsecdump v2.0b5. Retrieved November 17, 2024.", "source_name": "TrueSec Gsecdump", "url": "https://web.archive.org/web/20140328102838/https://www.truesec.se/sakerhet/verktyg/saakerhet/gsecdump_v2.0b5"}], "id": "tool--b07c2c47-fefb-4d7c-a69e-6a3296171f54", "modified": "2024-11-17T23:49:27.288Z", "name": "gsecdump", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["gsecdump"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1309', 0, 75, '09-mitre-attack', 'retrieved', 'D5FB1FC69418DA03E5DC66B130ECBD5BCEE443396FD485E7C57CCF0F5139B886', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
