VALUES ('doc-09-mitre-attack-p0-1310', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-24T21:28:44.175Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IronNetInjector](https://attack.mitre.org/software/S0581) is a [Turla](https://attack.mitre.org/groups/G0010) toolchain that utilizes scripts from the open-source IronPython implementation of Python with a .NET injector to drop one or more payloads including [ComRAT](https://attack.mitre.org/software/S0126).(Citation: Unit 42 IronNetInjector February 2021 )", "external_references": [{"external_id": "S0581", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0581"}, {"description": "Reichel, D. (2021, February 19). IronNetInjector: Turla’s New Malware Loading Tool. Retrieved February 24, 2021.", "source_name": "Unit 42 IronNetInjector February 2021 ", "url": "https://unit42.paloaltonetworks.com/ironnetinjector/"}], "id": "tool--b1595ddd-a783-482a-90e1-8afc8d48467e", "modified": "2024-04-11T02:14:36.791Z", "name": "IronNetInjector", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["IronNetInjector"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1310', 0, 98, '09-mitre-attack', 'retrieved', '34786CF27647C93B4218E492947DB81E551A20ABF3E227E112AB99DC91A29671', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
