VALUES ('doc-09-mitre-attack-p0-1311', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:03.773Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[nbtstat](https://attack.mitre.org/software/S0102) is a utility used to troubleshoot NetBIOS name resolution. (Citation: TechNet Nbtstat)", "external_references": [{"external_id": "S0102", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0102"}, {"description": "Microsoft. (n.d.). Nbtstat. Retrieved April 17, 2016.", "source_name": "TechNet Nbtstat", "url": "https://technet.microsoft.com/en-us/library/cc940106.aspx"}], "id": "tool--b35068ec-107a-4266-bda8-eb7036267aea", "modified": "2026-05-12T15:12:00.740Z", "name": "nbtstat", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["nbtstat"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1311', 0, 64, '09-mitre-attack', 'retrieved', '9772C55AAA050FA43E861E5ECDCBC43EEAE9D4468CBA9227451F5241F208AC87', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
