VALUES ('doc-09-mitre-attack-p0-1313', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-17T15:26:20.015Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NBTscan](https://attack.mitre.org/software/S0590) is an open source tool that has been used by state groups to conduct internal reconnaissance within a compromised network.(Citation: Debian nbtscan Nov 2019)(Citation: SecTools nbtscan June 2003)(Citation: Symantec Waterbug Jun 2019)(Citation: FireEye APT39 Jan 2019)", "external_references": [{"external_id": "S0590", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0590"}, {"description": "Bezroutchko, A. (2019, November 19). NBTscan man page. Retrieved March 17, 2021.", "source_name": "Debian nbtscan Nov 2019", "url": "https://manpages.debian.org/testing/nbtscan/nbtscan.1.en.html"}, {"description": "Hawley et al. (2019, January 29). APT39: An Iranian Cyber Espionage Group Focused on Personal Information. Retrieved February 19, 2019.", "source_name": "FireEye APT39 Jan 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/01/apt39-iranian-cyber-espionage-group-focused-on-personal-information.html"}, {"description": "SecTools. (2003, June 11). NBTscan. Retrieved March 17, 2021.", "source_name": "SecTools nbtscan June 2003", "url": "https://sectools.org/tool/nbtscan/"}, {"description": "Symantec DeepSight Adversary Intelligence Team. (2019, June 20). Waterbug: Espionage Group Rolls Out Brand-New Toolset in Attacks Against Governments. Retrieved July 8, 2019.", "source_name": "Symantec Waterbug Jun 2019", "url": "https://www.symantec.com/blogs/threat-intelligence/waterbug-espionage-governments"}], "id": "tool--b63970b7-ddfb-4aee-97b1-80d335e033a8", "modified": "2025-04-25T14:45:26.872Z", "name": "NBTscan", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["NBTscan"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux", "macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1313', 0, 180, '09-mitre-attack', 'retrieved', '54C734AB9806DBF052E975678C3CE5F575462946D82C8C3A6EB56D764BE428F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
