VALUES ('doc-09-mitre-attack-p0-1314', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T16:44:59.887Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LaZagne](https://attack.mitre.org/software/S0349) is a post-exploitation, open-source tool used to recover stored passwords on a system. It has modules for Windows, Linux, and OSX, but is mainly focused on Windows systems. [LaZagne](https://attack.mitre.org/software/S0349) is publicly available on GitHub.(Citation: GitHub LaZagne Dec 2018)", "external_references": [{"external_id": "S0349", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0349"}, {"description": "(Citation: GitHub LaZange Dec 2018)", "source_name": "LaZagne"}, {"description": "Zanni, A. (n.d.). The LaZagne Project !!!. Retrieved December 14, 2018.", "source_name": "GitHub LaZagne Dec 2018", "url": "https://github.com/AlessandroZ/LaZagne"}, {"description": "Zanni, A. (n.d.). The LaZagne Project !!!. Retrieved December 14, 2018.", "source_name": "GitHub LaZange Dec 2018", "url": "https://github.com/AlessandroZ/LaZagne"}], "id": "tool--b76b2d94-60e4-4107-a903-4a3a7622fb3b", "modified": "2024-04-04T03:49:27.035Z", "name": "LaZagne", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["LaZagne"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-1314', 0, 127, '09-mitre-attack', 'retrieved', 'A2593B9AE531ADF71C761FB393CF5574DF86733955C23029F618DED3FB7F5296', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
