VALUES ('doc-09-mitre-attack-p0-1315', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:01.483Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ping](https://attack.mitre.org/software/S0097) is an operating system utility commonly used to troubleshoot and verify network connections. (Citation: TechNet Ping)", "external_references": [{"external_id": "S0097", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0097"}, {"description": "Microsoft. (n.d.). Ping. Retrieved April 8, 2016.", "source_name": "TechNet Ping", "url": "https://technet.microsoft.com/en-us/library/bb490968.aspx"}], "id": "tool--b77b563c-34bb-4fb8-86a3-3694338f7b47", "modified": "2026-05-12T15:12:00.740Z", "name": "Ping", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Ping"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-1315', 0, 68, '09-mitre-attack', 'retrieved', '7294F56F55F67D7A4E9D1C2179ACC39F116F32DD8123721520FC583B33047C5D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
