VALUES ('doc-09-mitre-attack-p0-1316', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:05.319Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[cmd](https://attack.mitre.org/software/S0106) is the Windows command-line interpreter that can be used to interact with systems and execute other processes and utilities. (Citation: TechNet Cmd)\n\nCmd.exe contains native functionality to perform many operations to interact with the system, including listing files in a directory (e.g., dir (Citation: TechNet Dir)), deleting files (e.g., del (Citation: TechNet Del)), and copying files (e.g., copy (Citation: TechNet Copy)).", "external_references": [{"external_id": "S0106", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0106"}, {"description": "Microsoft. (n.d.). Cmd. Retrieved April 18, 2016.", "source_name": "TechNet Cmd", "url": "https://technet.microsoft.com/en-us/library/bb490880.aspx"}, {"description": "Microsoft. (n.d.). Copy. Retrieved April 26, 2016.", "source_name": "TechNet Copy", "url": "https://technet.microsoft.com/en-us/library/bb490886.aspx"}, {"description": "Microsoft. (n.d.). Del. Retrieved April 22, 2016.", "source_name": "TechNet Del", "url": "https://technet.microsoft.com/en-us/library/cc771049.aspx"}, {"description": "Microsoft. (n.d.). Dir. Retrieved April 18, 2016.", "source_name": "TechNet Dir", "url": "https://technet.microsoft.com/en-us/library/cc755121.aspx"}], "id": "tool--bba595da-b73a-4354-aa6c-224d4de7cb4e", "modified": "2025-04-16T20:38:55.702Z", "name": "cmd", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["cmd", "cmd.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1316', 0, 154, '09-mitre-attack', 'retrieved', '6CAE24BA42EE630A700C21163C2716FB37A9D1B3C76130926C8E77835E292118', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
