VALUES ('doc-09-mitre-attack-p0-1318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-03T18:25:36.963Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[esentutl](https://attack.mitre.org/software/S0404) is a command-line tool that provides database utilities for the Windows Extensible Storage Engine.(Citation: Microsoft Esentutl)", "external_references": [{"external_id": "S0404", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0404"}, {"description": "Microsoft. (2016, August 30). Esentutl. Retrieved September 3, 2019.", "source_name": "Microsoft Esentutl", "url": "https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-R2-and-2012/hh875546(v=ws.11)"}], "id": "tool--c256da91-6dd5-40b2-beeb-ee3b22ab3d27", "modified": "2023-09-28T03:45:36.045Z", "name": "esentutl", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["esentutl", "esentutl.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Edward Millington", "Matthew Demaske, Adaptforward"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1318', 0, 79, '09-mitre-attack', 'retrieved', 'C9474E9710EC9313B06B3AC6A6DB4693FF39F8A489601AD0C97D22E0F317E05B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
