VALUES ('doc-09-mitre-attack-p0-1319', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-17T14:23:05.958Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CrackMapExec](https://attack.mitre.org/software/S0488), or CME, is a post-exploitation tool developed in Python and designed for penetration testing against networks. [CrackMapExec](https://attack.mitre.org/software/S0488) collects Active Directory information to conduct lateral movement through targeted networks.(Citation: CME Github September 2018)", "external_references": [{"external_id": "S0488", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0488"}, {"description": "byt3bl33d3r. (2018, September 8). SMB: Command Reference. Retrieved July 17, 2020.", "source_name": "CME Github September 2018", "url": "https://github.com/byt3bl33d3r/CrackMapExec/wiki/SMB-Command-Reference"}], "id": "tool--c4810609-7da6-48ec-8057-1b70a7814db0", "modified": "2024-03-14T17:29:49.200Z", "name": "CrackMapExec", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["CrackMapExec"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1319', 0, 92, '09-mitre-attack', 'retrieved', 'C7CBE58325117A49D387911958C53B9A35C06C9690EFC8F1D66694C88D2540AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
