VALUES ('doc-09-mitre-attack-p0-1320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Koadic](https://attack.mitre.org/software/S0250) is a Windows post-exploitation framework and penetration testing tool that is publicly available on GitHub. [Koadic](https://attack.mitre.org/software/S0250) has several options for staging payloads and creating implants, and performs most of its operations using Windows Script Host.(Citation: Github Koadic)(Citation: Palo Alto Sofacy 06-2018)(Citation: MalwareBytes LazyScripter Feb 2021)", "external_references": [{"external_id": "S0250", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0250"}, {"description": "(Citation: Github Koadic)(Citation: MalwareBytes LazyScripter Feb 2021)", "source_name": "Koadic"}, {"description": "Jazi, H. (2021, February). LazyScripter: From Empire to double RAT. Retrieved November 17, 2024.", "source_name": "MalwareBytes LazyScripter Feb 2021", "url": "https://web.archive.org/web/20211003035156/https://www.malwarebytes.com/resources/files/2021/02/lazyscripter.pdf"}, {"description": "Lee, B., Falcone, R. (2018, June 06). Sofacy Group’s Parallel Attacks. Retrieved June 18, 2018.", "source_name": "Palo Alto Sofacy 06-2018", "url": "https://researchcenter.paloaltonetworks.com/2018/06/unit42-sofacy-groups-parallel-attacks/"}, {"description": "Magius, J., et al. (2017, July 19). Koadic. Retrieved September 27, 2024.", "source_name": "Github Koadic", "url": "https://github.com/offsecginger/koadic"}], "id": "tool--c8655260-9f4b-44e3-85e1-6538a5f6e4f4", "modified": "2024-11-17T14:12:07.296Z", "name": "Koadic", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Koadic"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1320', 0, 159, '09-mitre-attack', 'retrieved', '3A4053F2F31EE1F11B9817BFFCEF69FEDC9F914FC55D02D6AD0B545D27B2C085', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
