VALUES ('doc-09-mitre-attack-p0-1322', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:10.197Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cachedump](https://attack.mitre.org/software/S0119) is a publicly-available tool that program extracts cached password hashes from a system’s registry. (Citation: Mandiant APT1)", "external_references": [{"external_id": "S0119", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0119"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}], "id": "tool--c9cd7ec9-40b7-49db-80be-1399eddd9c52", "modified": "2025-04-25T14:45:28.653Z", "name": "Cachedump", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Cachedump"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1322', 0, 76, '09-mitre-attack', 'retrieved', '39768C4DC0DCAD495DCFC1FE0FF041F0BCBC024C07E527CDEB6F85A9EB4F1DA6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
