VALUES ('doc-09-mitre-attack-p0-1323', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-19T19:17:14.971Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Expand](https://attack.mitre.org/software/S0361) is a Windows utility used to expand one or more compressed CAB files.(Citation: Microsoft Expand Utility) It has been used by [BBSRAT](https://attack.mitre.org/software/S0127) to decompress a CAB file into executable content.(Citation: Palo Alto Networks BBSRAT)", "external_references": [{"external_id": "S0361", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0361"}, {"description": "Microsoft. (2017, October 15). Expand. Retrieved February 19, 2019.", "source_name": "Microsoft Expand Utility", "url": "https://docs.microsoft.com/en-us/windows-server/administration/windows-commands/expand"}, {"description": "Lee, B. Grunzweig, J. (2015, December 22). BBSRAT Attacks Targeting Russian Organizations Linked to Roaming Tiger. Retrieved August 19, 2016.", "source_name": "Palo Alto Networks BBSRAT", "url": "http://researchcenter.paloaltonetworks.com/2015/12/bbsrat-attacks-targeting-russian-organizations-linked-to-roaming-tiger/"}], "id": "tool--ca656c25-44f1-471b-9d9f-e2a3bbb84973", "modified": "2025-04-25T14:45:29.018Z", "name": "Expand", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Expand"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Matthew Demaske, Adaptforward"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1323', 0, 121, '09-mitre-attack', 'retrieved', 'D55AE08878FCAE6334641BA1293C140219D72B5E76AFD249E58CEAAE66C792BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
