VALUES ('doc-09-mitre-attack-p0-1324', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pupy](https://attack.mitre.org/software/S0192) is an open source, cross-platform (Windows, Linux, OSX, Android) remote administration and post-exploitation tool. (Citation: GitHub Pupy) It is written in Python and can be generated as a payload in several different ways (Windows exe, Python file, PowerShell oneliner/file, Linux elf, APK, Rubber Ducky, etc.). (Citation: GitHub Pupy) [Pupy](https://attack.mitre.org/software/S0192) is publicly available on GitHub. (Citation: GitHub Pupy)", "external_references": [{"external_id": "S0192", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0192"}, {"description": "Nicolas Verdier. (n.d.). Retrieved January 29, 2018.", "source_name": "GitHub Pupy", "url": "https://github.com/n1nj4sec/pupy"}], "id": "tool--cb69b20d-56d0-41ab-8440-4a4b251614d4", "modified": "2023-09-28T21:08:47.128Z", "name": "Pupy", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Pupy"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows", "macOS", "Android"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1324', 0, 114, '09-mitre-attack', 'retrieved', '2CC11064CFBD593194BCA3BE352C0D00BA7C5FCE52E892161C93C0CD8C4B8D64', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
