VALUES ('doc-09-mitre-attack-p0-1325', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:49.000Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Reg](https://attack.mitre.org/software/S0075) is a Windows utility used to interact with the Windows Registry. It can be used at the command-line interface to query, add, modify, and remove information. (Citation: Microsoft Reg)\n\nUtilities such as [Reg](https://attack.mitre.org/software/S0075) are known to be used by persistent threats. (Citation: Windows Commands JPCERT)", "external_references": [{"external_id": "S0075", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0075"}, {"description": "Microsoft. (2012, April 17). Reg. Retrieved May 1, 2015.", "source_name": "Microsoft Reg", "url": "https://technet.microsoft.com/en-us/library/cc732643.aspx"}, {"description": "Tomonaga, S. (2016, January 26). Windows Commands Abused by Attackers. Retrieved February 2, 2016.", "source_name": "Windows Commands JPCERT", "url": "https://blogs.jpcert.or.jp/en/2016/01/windows-commands-abused-by-attackers.html"}], "id": "tool--cde2d700-9ed1-46cf-9bce-07364fe8b24f", "modified": "2025-04-16T20:38:56.474Z", "name": "Reg", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Reg", "reg.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1325', 0, 122, '09-mitre-attack', 'retrieved', '299B7CE2109BFDEEAC1BC91CC2F978E64F55691F371322D6EE92BB2300D127C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
