VALUES ('doc-09-mitre-attack-p0-1326', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:00.565Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ftp](https://attack.mitre.org/software/S0095) is a utility commonly available with operating systems to transfer information over the File Transfer Protocol (FTP). Adversaries can use it to transfer other tools onto a system or to exfiltrate data.(Citation: Microsoft FTP)(Citation: Linux FTP)", "external_references": [{"external_id": "S0095", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0095"}, {"description": "Microsoft. (2021, July 21). ftp. Retrieved February 25, 2022.", "source_name": "Microsoft FTP", "url": "https://docs.microsoft.com/en-us/windows-server/administration/windows-commands/ftp"}, {"description": "N/A. (n.d.). ftp(1) - Linux man page. Retrieved February 25, 2022.", "source_name": "Linux FTP", "url": "https://linux.die.net/man/1/ftp"}], "id": "tool--cf23bf4a-e003-4116-bbae-1ea6c558d565", "modified": "2025-06-04T16:11:23.752Z", "name": "ftp", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["ftp", "ftp.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows", "macOS"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-1326', 0, 112, '09-mitre-attack', 'retrieved', 'A96C70822494C5E7CAC6CDDB45217854FF054E59659DB6E9C5836D8A2BDF8C80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
