VALUES ('doc-09-mitre-attack-p0-1327', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-26T01:38:12.966Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mythic](https://attack.mitre.org/software/S0699) is an open source, cross-platform post-exploitation/command and control platform. [Mythic](https://attack.mitre.org/software/S0699) is designed to \"plug-n-play\" with various agents and communication channels.(Citation: Mythic Github)(Citation: Mythic SpecterOps)(Citation: Mythc Documentation) Deployed [Mythic](https://attack.mitre.org/software/S0699) C2 servers have been observed as part of potentially malicious infrastructure.(Citation: RecordedFuture 2021 Ad Infra)", "external_references": [{"external_id": "S0699", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0699"}, {"description": "Insikt Group. (2022, January 18). 2021 Adversary Infrastructure Report. Retrieved March 25, 2022.", "source_name": "RecordedFuture 2021 Ad Infra", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2022-0118.pdf"}, {"description": "Thomas, C. (2018, July 4). Mythic. Retrieved March 25, 2022.", "source_name": "Mythic Github", "url": "https://github.com/its-a-feature/Mythic"}, {"description": "Thomas, C. (2020, August 13). A Change of Mythic Proportions. Retrieved March 25, 2022.", "source_name": "Mythic SpecterOps", "url": "https://posts.specterops.io/a-change-of-mythic-proportions-21debeb03617"}, {"description": "Thomas, C. (n.d.). Mythc Documentation. Retrieved March 25, 2022.", "source_name": "Mythc Documentation", "url": "https://docs.mythic-c2.net/"}], "id": "tool--d505fc8b-2e64-46eb-96d6-9ef7ffca5b66", "modified": "2025-04-16T20:38:56.653Z", "name": "Mythic", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Mythic"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Cody Thomas, SpecterOps"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "Linux", "macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1327', 0, 162, '09-mitre-attack', 'retrieved', '0A2284B0714FA94A030F8691EB4AFA1FDCA31E5E09418E38F2C513373B1664A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
