VALUES ('doc-09-mitre-attack-p0-1329', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SDelete](https://attack.mitre.org/software/S0195) is an application that securely deletes data in a way that makes it unrecoverable. It is part of the Microsoft Sysinternals suite of tools. (Citation: Microsoft SDelete July 2016)", "external_references": [{"external_id": "S0195", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0195"}, {"description": "(Citation: Microsoft SDelete July 2016)", "source_name": "SDelete"}, {"description": "Russinovich, M. (2016, July 4). SDelete v2.0. Retrieved February 8, 2018.", "source_name": "Microsoft SDelete July 2016", "url": "https://docs.microsoft.com/en-us/sysinternals/downloads/sdelete"}], "id": "tool--d8d19e33-94fd-4aa3-b94a-08ee801a2153", "modified": "2025-04-25T14:45:30.257Z", "name": "SDelete", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["SDelete"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1329', 0, 95, '09-mitre-attack', 'retrieved', '50BA7A873F63FCBE8600558D06CF14C02DEFE377CEB15CA4D9602A1BB82D4BAB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
