VALUES ('doc-09-mitre-attack-p0-1330', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QuasarRAT](https://attack.mitre.org/software/S0262) is an open-source, remote access tool that has been publicly available on GitHub since at least 2014. [QuasarRAT](https://attack.mitre.org/software/S0262) is developed in the C# language.(Citation: GitHub QuasarRAT)(Citation: Volexity Patchwork June 2018)", "external_references": [{"external_id": "S0262", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0262"}, {"description": "(Citation: GitHub QuasarRAT) (Citation: Volexity Patchwork June 2018) (Citation: TrendMicro Patchwork Dec 2017)", "source_name": "QuasarRAT"}, {"description": "(Citation: TrendMicro Patchwork Dec 2017)(Citation: Securelist APT10 March 2021)", "source_name": "xRAT"}, {"description": "GREAT. (2021, March 30). APT10: sophisticated multi-layered loader Ecipekac discovered in A41APT campaign. Retrieved June 17, 2021.", "source_name": "Securelist APT10 March 2021", "url": "https://securelist.com/apt10-sophisticated-multi-layered-loader-ecipekac-discovered-in-a41apt-campaign/101519/"}, {"description": "Lunghi, D., et al. (2017, December). Untangling the Patchwork Cyberespionage Group. Retrieved July 10, 2018.", "source_name": "TrendMicro Patchwork Dec 2017", "url": "https://documents.trendmicro.com/assets/tech-brief-untangling-the-patchwork-cyberespionage-group.pdf"}, {"description": "MaxXor. (n.d.). QuasarRAT. Retrieved July 10, 2018.", "source_name": "GitHub QuasarRAT", "url": "https://github.com/quasar/QuasarRAT"}, {"description": "Meltzer, M, et al. (2018, June 07). Patchwork APT Group Targets US Think Tanks. Retrieved July 16, 2018.", "source_name": "Volexity Patchwork June 2018", "url": "https://www.volexity.com/blog/2018/06/07/patchwork-apt-group-targets-us-think-tanks/"}], "id": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "modified": "2026-05-12T15:12:00.741Z", "name": "QuasarRAT", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["QuasarRAT", "xRAT"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Kyaw Pyiyt Htet, @KyawPyiytHtet"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-1330', 0, 192, '09-mitre-attack', 'retrieved', 'F193D51E61FBF219F6D385583B63E2185AD76BD90895C31BE1AF096973B069C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
