VALUES ('doc-09-mitre-attack-p0-1331', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:31:00.202Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[cipher.exe](https://attack.mitre.org/software/S1205) is a native Microsoft utility that manages encryption of directories and files on NTFS (New Technology File System) partitions by using the Encrypting File System (EFS).(Citation: cipher.exe)", "external_references": [{"external_id": "S1205", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1205"}, {"description": "Microsoft Support. (n.d.). Cipher.exe Security Tool for the Encrypting File System. Retrieved February 25, 2025.", "source_name": "cipher.exe", "url": "https://support.microsoft.com/en-us/topic/cipher-exe-security-tool-for-the-encrypting-file-system-56c85edd-85cf-ac07-f2f7-ca2d35dab7e4"}], "id": "tool--da66959d-9875-4fde-bfed-11111a55895e", "modified": "2025-03-10T19:48:40.412Z", "name": "cipher.exe", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["cipher.exe"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1331', 0, 88, '09-mitre-attack', 'retrieved', 'AFC74467F2AAFAAEC3295730A67C3DB1C928AE89005AC065B80B6028400CEF2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
