VALUES ('doc-09-mitre-attack-p0-1332', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-29T20:19:26.940Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rubeus](https://attack.mitre.org/software/S1071) is a C# toolset designed for raw Kerberos interaction that has been used since at least 2020, including in ransomware operations.(Citation: GitHub Rubeus March 2023)(Citation: FireEye KEGTAP SINGLEMALT October 2020)(Citation: DFIR Ryuk''s Return October 2020)(Citation: DFIR Ryuk 2 Hour Speed Run November 2020)", "external_references": [{"external_id": "S1071", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1071"}, {"description": "Harmj0y. (n.d.). Rubeus. Retrieved March 29, 2023.", "source_name": "GitHub Rubeus March 2023", "url": "https://github.com/GhostPack/Rubeus"}, {"description": "Kimberly Goody, Jeremy Kennelly, Joshua Shilko, Steve Elovitz, Douglas Bienstock. (2020, October 28). Unhappy Hour Special: KEGTAP and SINGLEMALT With a Ransomware Chaser. Retrieved October 28, 2020.", "source_name": "FireEye KEGTAP SINGLEMALT October 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/10/kegtap-and-singlemalt-with-a-ransomware-chaser.html"}, {"description": "The DFIR Report. (2020, November 5). Ryuk Speed Run, 2 Hours to Ransom. Retrieved November 6, 2020.", "source_name": "DFIR Ryuk 2 Hour Speed Run November 2020", "url": "https://thedfirreport.com/2020/11/05/ryuk-speed-run-2-hours-to-ransom/"}, {"description": "The DFIR Report. (2020, October 8). Ryuk’s Return. Retrieved October 9, 2020.", "source_name": "DFIR Ryuk''s Return October 2020", "url": "https://thedfirreport.com/2020/10/08/ryuks-return/"}], "id": "tool--e33267fe-099f-4af2-8730-63d49f8813b2", "modified": "2026-05-12T15:12:00.741Z", "name": "Rubeus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Rubeus"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Mayuresh Dani, Qualys", "Akshat Pradhan, Qualys"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1332', 0, 192, '09-mitre-attack', 'retrieved', 'F83EDBCE565846895A33C5C856E8435C596569A2C6ACA7B2B5163CF4B86C7DA8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
