VALUES ('doc-09-mitre-attack-p0-1333', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tor](https://attack.mitre.org/software/S0183) is a software suite and network that provides increased anonymity on the Internet. It creates a multi-hop proxy network and utilizes multilayer encryption to protect both the message and routing information. [Tor](https://attack.mitre.org/software/S0183) utilizes \"Onion Routing,\" in which messages are encrypted with multiple layers of encryption; at each step in the proxy network, the topmost layer is decrypted and the contents forwarded on to the next node until it reaches its destination. (Citation: Dingledine Tor The Second-Generation Onion Router)", "external_references": [{"external_id": "S0183", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0183"}, {"description": "(Citation: Dingledine Tor The Second-Generation Onion Router)", "source_name": "Tor"}, {"description": "Roger Dingledine, Nick Mathewson and Paul Syverson. (2004). Tor: The Second-Generation Onion Router. Retrieved December 21, 2017.", "source_name": "Dingledine Tor The Second-Generation Onion Router", "url": "http://www.dtic.mil/dtic/tr/fulltext/u2/a465464.pdf"}], "id": "tool--ed7d0cb1-87a6-43b4-9f46-ef1bc56d6c68", "modified": "2026-05-12T15:12:00.741Z", "name": "Tor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Tor"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "Windows", "macOS"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-1333', 0, 158, '09-mitre-attack', 'retrieved', '38DFF5DC9804D25E4AEE8D2E7CBF7E5BE7403BCD05230B8BA4FC447503E6FB8C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
