VALUES ('doc-09-mitre-attack-p0-1335', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-14T21:45:30.280Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wevtutil](https://attack.mitre.org/software/S0645) is a Windows command-line utility that enables administrators to retrieve information about event logs and publishers.(Citation: Wevtutil Microsoft Documentation)", "external_references": [{"external_id": "S0645", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0645"}, {"description": "Microsoft. (n.d.). wevtutil. Retrieved September 14, 2021.", "source_name": "Wevtutil Microsoft Documentation", "url": "https://docs.microsoft.com/en-us/windows-server/administration/windows-commands/wevtutil"}], "id": "tool--f91162cc-1686-4ff8-8115-bf3f61a4cc7a", "modified": "2026-05-12T15:12:00.741Z", "name": "Wevtutil", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Wevtutil"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Viren Chaudhari, Qualys", "Harshal Tupsamudre, Qualys"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1335', 0, 81, '09-mitre-attack', 'retrieved', 'C8DE6EF63B242FC7847A03488F1D509D7859D403BAE462970E6417150817EBA6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
