VALUES ('doc-09-mitre-attack-p0-1336', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Havij](https://attack.mitre.org/software/S0224) is an automatic SQL Injection tool distributed by the Iranian ITSecTeam security company. Havij has been used by penetration testers and adversaries. (Citation: Check Point Havij Analysis)", "external_references": [{"external_id": "S0224", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0224"}, {"description": "Ganani, M. (2015, May 14). Analysis of the Havij SQL Injection tool. Retrieved March 19, 2018.", "source_name": "Check Point Havij Analysis", "url": "https://blog.checkpoint.com/2015/05/14/analysis-havij-sql-injection-tool/"}], "id": "tool--fbd727ea-c0dc-42a9-8448-9e12962d1ab5", "modified": "2025-04-25T14:45:31.679Z", "name": "Havij", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "tool", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1336', 0, 86, '09-mitre-attack', 'retrieved', 'FEB75C8727CCC319B7685C834C9C8B784B8EA1D732A3561BB047EBB29B419A05', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
