VALUES ('doc-09-mitre-attack-p0-1337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:13:01.957Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quick Assist](https://attack.mitre.org/software/S1209) is a remote assistance tool primarily for Microsoft Windows, although a macOS version also exists. [Quick Assist](https://attack.mitre.org/software/S1209) allows for remote screen sharing and, with end user approval, remote control and command execution on the enabling device.(Citation: Microsoft Storm-1811 2024)(Citation: Microsoft Quick Assist 2024)", "external_references": [{"external_id": "S1209", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S1209"}, {"description": "Microsoft Threat Intelligence. (2024, May 15). Threat actors misusing Quick Assist in social engineering attacks leading to ransomware. Retrieved March 14, 2025.", "source_name": "Microsoft Storm-1811 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/15/threat-actors-misusing-quick-assist-in-social-engineering-attacks-leading-to-ransomware/"}, {"description": "Microsoft. (2024, September 4). Use Quick Assist to help users. Retrieved March 14, 2025.", "source_name": "Microsoft Quick Assist 2024", "url": "https://learn.microsoft.com/en-us/windows/client-management/client-tools/quick-assist"}], "id": "tool--fcdb30de-5449-4777-a4f4-922e71f65932", "modified": "2025-03-14T19:17:27.658Z", "name": "Quick Assist", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["Quick Assist"], "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Liran Ravich, CardinalOps", "Joe Gumke, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1337', 0, 147, '09-mitre-attack', 'retrieved', '149840759560804771563B67D0E1C0934C1B4EBD03D97443D5F309CB7C1C0688', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
