VALUES ('doc-09-mitre-attack-p0-1338', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:32:21.771Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PsExec](https://attack.mitre.org/software/S0029) is a free Microsoft tool that can be used to execute a program on another computer. It is used by IT administrators and attackers.(Citation: Russinovich Sysinternals)(Citation: SANS PsExec)", "external_references": [{"external_id": "S0029", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S0029"}, {"description": "Pilkington, M. (2012, December 17). Protecting Privileged Domain Accounts: PsExec Deep-Dive. Retrieved August 17, 2016.", "source_name": "SANS PsExec", "url": "https://www.sans.org/blog/protecting-privileged-domain-accounts-psexec-deep-dive/"}, {"description": "Russinovich, M. (2014, May 2). Windows Sysinternals PsExec v2.11. Retrieved May 13, 2015.", "source_name": "Russinovich Sysinternals", "url": "https://technet.microsoft.com/en-us/sysinternals/bb897553.aspx"}], "id": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "modified": "2026-05-12T15:12:00.741Z", "name": "PsExec", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "tool", "x_mitre_aliases": ["PsExec"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Janantha Marasinghe"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.7"}', 'kb-doc-09-mitre-attack-p0-1338', 0, 112, '09-mitre-attack', 'retrieved', '73CEFC4E50CF8F90346C9F0CBEE155F4B7206E0B9183D04C22C43A74A757C7DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
