VALUES ('doc-09-mitre-attack-p0-1339', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-01T21:11:27.530Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) is a comprehensive filesystem credential stealer that can harvest, encrypt, and exfiltrate credentials from over 50 sensitive file paths across CI/CD, cloud, developer tooling, and container environments. The [TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) was the primary payload used by [TeamPCP](https://attack.mitre.org/groups/G1056) in March 2026 during early stages of a cascading supply chain campaign targeting CI/CD workflows.(Citation: Wiz Trivy Compromise MAR 2026)(Citation: Aqua Security Trivy Compromise MAR 2026)(Citation: Aqua Security Blog Trivy Compromise APR 2026)(Citation: Sysdig TeamPCP MAR 2026)(Citation: Wiz TeamPCP KICS MAR 2026)(Citation: Palo Alto TeamPCP MAR 2026)(Citation: Google AI Threat Tracker MAY 2026)(Citation: FBI TeamPCP JUL 2026)", "external_references": [{"external_id": "S9041", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9041"}, {"description": "(Citation: Google AI Threat Tracker MAY 2026)(Citation: FBI TeamPCP JUL 2026)", "source_name": "SANDCLOCK"}, {"description": "Aqua Security . (2026, March 21). Trivy ecosystem supply chain temporarily compromised. Retrieved July 1, 2026.", "source_name": "Aqua Security Trivy Compromise MAR 2026", "url": "https://github.com/aquasecurity/trivy/security/advisories/GHSA-69fq-xp46-6x23"}, {"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "FBI. (2026, July 2). Cyber Criminal Group TeamPCP. Retrieved July 7, 2026.", "source_name": "FBI TeamPCP JUL 2026", "url": "https://www.ic3.gov/CSA/2026/260702.pdf"}, {"description": "Google Threat Intelligence Group. (2026, May 11). GTIG AI Threat Tracker: Adversaries Leverage AI for Vulnerability Exploitation, Augmented Operations, and Initial Access. Retrieved July 7, 2026.", "source_name": "Google AI Threat Tracker MAY 2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ai-vulnerability-exploitation-initial-access"}, {"description": "McCarthy, R. (2026, March 20). Trivy Compromised: Everything You Need to Know about the Latest Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz Trivy Compromise MAR 2026", "url": "https://www.wiz.io/blog/trivy-compromised-teampcp-supply-chain-attack"}, {"description": "McCarthy, R., Haughom, J., Read, B. (2026, March 23). KICS GitHub Action Compromised: TeamPCP Strikes Again in Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz TeamPCP KICS MAR 2026", "url": "https://www.wiz.io/blog/teampcp-attack-kics-github-action"}, {"description": "Sysdig Threat Research Team. (2026, March 23). TeamPCP expands: Supply chain compromise spreads from Trivy to Checkmarx GitHub Actions. Retrieved July 1, 2026.", "source_name": "Sysdig TeamPCP MAR 2026", "url": "https://www.sysdig.com/blog/teampcp-expands-supply-chain-compromise-spreads-from-trivy-to-checkmarx-github-actions"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "is_family": true, "modified": "2026-07-31T02:42:44.295Z", "name": "TeamPCP Cloud Stealer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["TeamPCP Cloud Stealer", "SANDCLOCK"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers", "Linux", "macOS", "SaaS", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1339', 0, 396, '09-mitre-attack', 'retrieved', '0890A9E56A76CBC9DC5B4E5A8B0DDD111AE480692EA83A992A54005B5477538E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
