VALUES ('doc-09-mitre-attack-p0-1340', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T14:50:38.891Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) is a credential stealer and self-replicating supply chain worm, derived from [Shai-Hulud](https://attack.mitre.org/software/S9008), that has been used by [TeamPCP](https://attack.mitre.org/groups/G1056) to target Continuous Integration and Continuous Delivery/Deployment (CI/CD) workflows since at least 2026. [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) can compromise credentials across multiple cloud, container, and AI configuration file paths and can use stolen npm and GitHub OIDC tokens to spread to other packages maintained by the compromised user. [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) also has a targeted wiper component and has used multiple C2 and data exfiltration mechanisms.(Citation: Wiz Mini Shai-Hulud MAY 2026)(Citation: Trend Micro TeamPCP MAY 2026)(Citation: Hunt.io TeamPCP Toolkit MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)(Citation: Flashpoint Mini Shai-Hulud MAY 2026)(Citation: FBI TeamPCP JUL 2026)", "external_references": [{"external_id": "S9043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9043"}, {"description": "FBI. (2026, July 2). Cyber Criminal Group TeamPCP. Retrieved July 7, 2026.", "source_name": "FBI TeamPCP JUL 2026", "url": "https://www.ic3.gov/CSA/2026/260702.pdf"}, {"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}, {"description": "Hunt.io. (2026, May 14). How TeamPCP''s Python Toolkit Survives a C2 Takedown: FIRESCALE, GitHub, and the Victim''s Own Account. Retrieved July 16, 2026.", "source_name": "Hunt.io TeamPCP Toolkit MAY 2026", "url": "https://hunt.io/blog/teampcp-python-toolkit-firescale-github-c2-takedown"}, {"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "is_family": true, "modified": "2026-07-31T02:40:12.281Z", "name": "Mini Shai-Hulud", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["Mini Shai-Hulud"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Rajkumar Barot"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers", "IaaS", "Linux", "macOS", "SaaS", "Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1340', 0, 347, '09-mitre-attack', 'retrieved', '02B0EE3554EA73FA3F574646CD95F7D0B5E3AB038DA068C85D63FA7133F764D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
