VALUES ('doc-09-mitre-attack-p0-1341', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T17:52:27.451Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) is a self-propagating malware that has been used by [TeamPCP](https://attack.mitre.org/groups/G1056) in credential harvesting and software supply chain campaigns since at least 2026. [CanisterWorm](https://attack.mitre.org/software/S9042) has used npm credentials to infect software packages and propagate across developer ecosystems. [CanisterWorm](https://attack.mitre.org/software/S9042) has a targeted wiper component and can use decentralized C2 infrastructure implemented via an Internet Computer Protocol (ICP) blockchain canister.(Citation: Aikido TeamPCP Telnyx MAR 2026)(Citation: Palo Alto TeamPCP MAR 2026)(Citation: Aikido CanisterWorm MAR 2026)(Citation: Aikido TeamPCP Trivy MAR 2026)", "external_references": [{"external_id": "S9042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/software/S9042"}, {"description": "Eriksen, C. (2026, March 20). TeamPCP deploys CanisterWorm on NPM following Trivy compromise. Retrieved July 27, 2026.", "source_name": "Aikido TeamPCP Trivy MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-deploys-worm-npm-trivy-compromise"}, {"description": "Eriksen, C. (2026, March 22). CanisterWorm Gets Teeth: TeamPCP''s Kubernetes Wiper Targets Iran. Retrieved July 27, 2026.", "source_name": "Aikido CanisterWorm MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-stage-payload-canisterworm-iran"}, {"description": "Eriksen, C. (2026, March 27). Popular telnyx package compromised on PyPI by TeamPCP. Retrieved July 16, 2026.", "source_name": "Aikido TeamPCP Telnyx MAR 2026", "url": "https://www.aikido.dev/blog/telnyx-pypi-compromised-teampcp-canisterworm"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "is_family": true, "modified": "2026-07-31T02:39:34.113Z", "name": "CanisterWorm", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "malware", "x_mitre_aliases": ["CanisterWorm"], "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dhanvarshini Gopalsamy, NEC Corporation India", "Kamei Risa, NEC Corporation", "Sareena Karapoola, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers", "Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1341', 0, 241, '09-mitre-attack', 'retrieved', 'E126416EBD299CBBF2D012B8EAD81A16FA9FDEA4BAA23E09998EB2ED36FE5ACD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
