VALUES ('doc-09-mitre-attack-p0-1342', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["TeamPCP", "PCPCat", "ShellForce", "DeadCatx3", "SHADOW-WATER-058", "UNC6780"], "created": "2026-07-16T15:13:31.109Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) is a financially-motivated, cloud-native threat group that has been active since at least September 2025. Initially focused on ransomware and cryptocurrency theft, [TeamPCP](https://attack.mitre.org/groups/G1056) shifted in early 2026 to systematic, worm-driven credential theft and software supply chain attacks targeting Continuous Integration and Continuous Delivery (CI/CD) workflows. [TeamPCP](https://attack.mitre.org/groups/G1056) has monetized access through extortion and through partnerships with ransomware actors including Vect and CipherForce.(Citation: Wiz TeamPCP Profile MAY 2026)(Citation: Wiz Trivy Compromise MAR 2026)(Citation: Aqua Security Trivy Compromise MAR 2026)(Citation: Aqua Security Blog Trivy Compromise APR 2026)(Citation: Palo Alto TeamPCP MAR 2026)(Citation: Trend Micro TeamPCP MAY 2026)", "external_references": [{"external_id": "G1056", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1056"}, {"description": "(Citation: Google AI Threat Tracker MAY 2026)", "source_name": "UNC6780"}, {"description": "(Citation: Palo Alto TeamPCP MAR 2026)", "source_name": "PCPCat"}, {"description": "(Citation: Palo Alto TeamPCP MAR 2026)", "source_name": "ShellForce"}, {"description": "(Citation: Palo Alto TeamPCP MAR 2026)", "source_name": "DeadCatx3"}, {"description": "Aqua Security . (2026, March 21). Trivy ecosystem supply chain temporarily compromised. Retrieved July 1, 2026.", "source_name": "Aqua Security Trivy Compromise MAR 2026", "url": "https://github.com/aquasecurity/trivy/security/advisories/GHSA-69fq-xp46-6x23"}, {"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "Google Threat Intelligence Group. (2026, May 11). GTIG AI Threat Tracker: Adversaries Leverage AI for Vulnerability Exploitation, Augmented Operations, and Initial Access. Retrieved July 7, 2026.", "source_name": "Google AI Threat Tracker MAY 2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ai-vulnerability-exploitation-initial-access"}, {"description": "McCarthy, R. (2026, March 20). Trivy Compromised: Everything You Need to Know about the Latest Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz Trivy Compromise MAR 2026", "url": "https://www.wiz.io/blog/trivy-compromised-teampcp-supply-chain-attack"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}, {"description": "Wiz. (2026, May 20). TeamPCP. Retrieved July 16, 2026.", "source_name": "Wiz TeamPCP Profile MAY 2026", "url": "https://threats.wiz.io/all-actors/teampcp"}], "id": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "modified": "2026-07-31T18:47:42.686Z", "name": "TeamPCP", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Kamei Risa, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Dhanvarshini Gopalsamy, NEC Corporation India", "Rajkumar Barot", "Jose Moya Villalba"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1342', 0, 395, '09-mitre-attack', 'retrieved', '9968B8CACC614A5A0E07CA1BFF32091001E7B9077CDC71761924A50857AA8A71', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
